public class RandomValueGenerator
{
    private float minValue;
    private float maxValue;

    public RandomValueGenerator(float min, float max)
    {
        minValue = min;
        maxValue = max;
    }

    public float GetRandomFloatInclusive()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomIntExclusive()
    {
        return UnityEngine.Random.Range((int)minValue, (int)(maxValue + 1));
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }
}

// JavaScript function
<script type="text/javascript">
function FindElementsBySelector(node, selector) {
    let matchedElements = [];

    function traverse(node) {
        if (node.nodeType === Node.ELEMENT_NODE) {
            if (testNode(node)) {
                matchedElements.push(node);
            }

            for (let child of node.children || []) {
                traverse(child);
            }
        }
    }

    function testNode(node) {
        return node.id === selector || node.classList.contains(selector);
    }

    traverse(node);

    return matchedElements;
}
</script>
