```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;

public class CustomObject
{
    public int Id { get; set; }
    public string Name { get; set; }
}

public static class DatabaseHelper
{
    private static readonly Dictionary<string, object> Cache = new();

    public static async Task<List<CustomObject>> ExecuteStoredProcedureAsync(
        SqlConnection connection,
        string storedProcedureName,
        List<SqlParameter> parameters)
    {
        var cacheKey = $"{storedProcedureName}:{string.Join(",", parameters.Select(p => p.Value?.ToString() ?? "null"))}";

        if (Cache.ContainsKey(cacheKey))
        {
            return (List<CustomObject>)Cache[cacheKey];
        }

        using (var command = new SqlCommand(storedProcedureName, connection) { CommandType = CommandType.StoredProcedure })
        {
            command.Parameters.AddRange(parameters.ToArray());

            await connection.OpenAsync();

            try
            {
                using (var reader = await command.ExecuteReaderAsync())
                {
                    var result = new List<CustomObject>();

                    while (await reader.ReadAsync())
                    {
                        var customObject = new CustomObject
                        {
                            Id = reader.GetInt32(reader.GetOrdinal("Id")),
                            Name = reader.GetString(reader.GetOrdinal("Name"))
                        };

                        result.Add(customObject);
                    }

                    Cache[cacheKey] = result;
                    return result;
                }
            }
            finally
            {
                await connection.CloseAsync();
            }
        }
    }
}
```

This C# code defines a method `ExecuteStoredProcedureAsync` that executes a stored procedure asynchronously and maps the result set to a list of `CustomObject`. It also implements caching to avoid redundant database calls.

