#include <openssl/evp.h>
#include <stdlib.h>

typedef struct State {
    int id;
    struct State *next;
} State;

typedef struct CipherObj {
    EVP_CIPHER_CTX *cipher_ctx;
    State *state_list;
} CipherObj;

CipherObj* performOperation(const char *input, const char *cmdOption) {
    if (!input || !cmdOption) return NULL;

    // Initialize OpenSSL cipher context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Perform specific operation based on cmdOption (example: AES-256-CBC)
    if (strcmp(cmdOption, "AES-256-CBC") == 0) {
        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL) <= 0) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
        // Perform other necessary operations with ctx
    } else {
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Unsupported command option
    }

    // Assume fsa_get_states is a function that returns an FSA and retrieves states
    State *states = fsa_get_states(input);  // Placeholder for actual implementation

    if (!states) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Create new state list with dynamic memory allocation
    State *new_state_list = malloc(sizeof(State));
    if (!new_state_list) {
        free(states);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    State *current_new = new_state_list;
    State *current_old = states;

    while (current_old) {
        current_new->id = current_old->id;
        current_new->next = malloc(sizeof(State));
        if (!current_new->next) {
            // Free allocated memory on error
            State *temp = new_state_list;
            while (temp) {
                State *to_free = temp;
                temp = temp->next;
                free(to_free);
            }
            free(current_new);  // In case of failure after allocation
            free(states);
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
        current_new = current_new->next;
        current_old = current_old->next;
    }
    current_new->next = NULL;

    // Update the 'next' pointer of the last state in the original list
    State *last_state = states;
    while (last_state && last_state->next) {
        last_state = last_state->next;
    }
    if (last_state) {
        last_state->next = new_state_list;
    }

    // Create and return CipherObj
    CipherObj *cipher_obj = malloc(sizeof(CipherObj));
    if (!cipher_obj) {
        free(new_state_list);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    cipher_obj->cipher_ctx = ctx;
    cipher_obj->state_list = new_state_list;

    return cipher_obj;
}
