```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <stdexcept>
#include "rapidjson/document.h"
#include "rapidjson/writer.h"
#include "rapidjson/stringbuffer.h"

struct Node {
    int key;
    std::string value;

    Node(int k, const std::string& v) : key(k), value(v) {}
};

class DynamicNodeArray {
private:
    std::vector<Node*> nodes;
    size_t threshold;

public:
    explicit DynamicNodeArray(size_t initialThreshold = 10)
        : threshold(initialThreshold) {}

    ~DynamicNodeArray() {
        for (auto node : nodes) {
            delete node;
        }
    }

    void readFileAndInitialize(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file");
        }

        int key;
        std::string value;

        while (file >> key >> value) {
            nodes.push_back(new Node(key, value));
            if (nodes.size() > threshold) {
                resize();
            }
        }

        file.close();
    }

    void resize() {
        // Double the size of the threshold for simplicity
        threshold *= 2;
        std::cout << "Resized array to new threshold: " << threshold << "\n";
    }

    void serializeToJson(const std::string& filename) const {
        rapidjson::Document doc(rapidjson::kObjectType);
        rapidjson::Document::AllocatorType& allocator = doc.GetAllocator();

        for (const auto& node : nodes) {
            rapidjson::Value obj(rapidjson::kObjectType);
            obj.AddMember("key", node->key, allocator);
            obj.AddMember("value", rapidjson::StringRef(node->value.c_str()), allocator);
            doc.PushBack(obj, allocator);
        }

        rapidjson::StringBuffer buffer;
        rapidjson::Writer<rapidjson::StringBuffer> writer(buffer);
        doc.Accept(writer);

        std::ofstream outFile(filename);
        if (!outFile.is_open()) {
            throw std::runtime_error("Failed to open output file");
        }
        outFile << buffer.GetString();
        outFile.close();
    }

    void deserializeFromJson(const std::string& filename) {
        std::ifstream inFile(filename);
        if (!inFile.is_open()) {
            throw std::runtime_error("Failed to open input file");
        }

        rapidjson::IStreamWrapper isw(inFile);
        rapidjson::Document doc;
        if (doc.ParseStream(isw).HasParseError()) {
            throw std::runtime_error("Failed to parse JSON");
        }

        for (const auto& node : doc.GetArray()) {
            int key = node["key"].GetInt();
            std::string value = node["value"].GetString();
            nodes.push_back(new Node(key, value));
        }
    }
};

int main() {
    try {
        DynamicNodeArray array;
        array.readFileAndInitialize("nodes.txt");
        array.serializeToJson("nodes.json");

        DynamicNodeArray newArray;
        newArray.deserializeFromJson("nodes.json");
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
    }

    return 0;
}
```

This code includes the following components:
- A `Node` structure that holds an integer key and a string value.
- A `DynamicNodeArray` class to manage dynamic arrays of `Node` objects, including functions for reading from a file, resizing, serialization, and deserialization using RapidJSON.

```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.*;
import java.util.Random;

public class GameCharacter {

    private final Selector selector;
    private final InetSocketAddress remoteAddress = new InetSocketAddress("localhost", 9999);
    private final int COOLDOWN_PERIOD = 9000; // in milliseconds
    private long lastAttackTime = 0;

    public GameCharacter() throws IOException {
        this.selector = Selector.open();
        SocketChannel socketChannel = SocketChannel.open();
        socketChannel.configureBlocking(false);
        socketChannel.register(selector, SelectionKey.OP_CONNECT);

        initiateConnection(socketChannel);
    }

    private void initiateConnection(SocketChannel socketChannel) throws IOException {
        if (!socketChannel.connect(remoteAddress)) {
            socketChannel.register(selector, SelectionKey.OP_CONNECT | SelectionKey.OP_WRITE, null);
        }
    }

    public void handleConnection() throws IOException {
        while (true) {
            selector.select();
            for (SelectionKey key : selector.selectedKeys()) {
                if (key.isValid()) {
                    if (key.isConnectable()) {
                        finishConnection(key);
                    } else if (key.isWritable()) {
                        // Handle writable state
                        // For demonstration, we'll just close the connection
                        key.channel().close();
                    }
                }
            }
            selector.selectedKeys().clear();

            performAttackIfCooldownElapsed();
        }
    }

    private void finishConnection(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        if (channel.isConnectionPending()) {
            channel.finishConnect();
        }
        // Transition to writable state or other operations
        key.interestOps(SelectionKey.OP_WRITE);
    }

    private void performAttackIfCooldownElapsed() {
        long currentTime = System.currentTimeMillis();
        if (currentTime - lastAttackTime >= COOLDOWN_PERIOD) {
            int attackNumber = new Random().nextInt(2) + 1;
            System.out.println("Selected Attack: " + attackNumber);
            lastAttackTime = currentTime;
        }
    }

    public static void main(String[] args) {
        try {
            GameCharacter character = new GameCharacter();
            character.handleConnection();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
