using System;
using UnityEngine;

public class CustomRandomGenerator
{
    private int _currentSeed;

    public event Action<int> OnNewSeedGenerated;

    // Generates a random float within the specified range.
    public float CustomRange(float min, float max, bool isExclusive, bool seeded, int? seed = null)
    {
        if (min >= max && !isExclusive) throw new ArgumentException("Min must be less than Max for inclusive ranges.");
        if (min > max && isExclusive) throw new ArgumentException("Min must be less or equal to Max for exclusive ranges.");

        SetSeed(seeded, seed);

        float range = max - min;
        float value;

        if (isExclusive)
        {
            value = UnityEngine.Random.Range(min, max); // Random.Range is exclusive on the upper bound.
        }
        else
        {
            value = UnityEngine.Random.Range(min, max + 1e-7f);
        }

        return value;
    }

    // Generates a random integer within the specified range.
    public int CustomRange(int min, int max, bool isExclusive, bool seeded, int? seed = null)
    {
        if (min >= max && !isExclusive) throw new ArgumentException("Min must be less than Max for inclusive ranges.");
        if (min > max && isExclusive) throw new ArgumentException("Min must be less or equal to Max for exclusive ranges.");

        SetSeed(seeded, seed);

        int range = max - min;
        int value;

        if (isExclusive)
        {
            value = UnityEngine.Random.Range(min, max); // Random.Range is exclusive on the upper bound.
        }
        else
        {
            value = UnityEngine.Random.Range(min, max + 1);
        }

        return value;
    }

    private void SetSeed(bool seeded, int? seed)
    {
        if (!seeded || seed == null) return;

        _currentSeed = seed.Value;
        UnityEngine.Random.InitState(_currentSeed);

        OnNewSeedGenerated?.Invoke(_currentSeed);
    }

    public override string ToString()
    {
        return $"CustomRandomGenerator: Seed={_currentSeed}";
    }
}
```

### Key Points:
- The class uses `UnityEngine.Random.Range` for random number generation, which is exclusive on the upper bound.
- An optional seed can be set to make the random number generation reproducible.
- Event-driven design allows external systems to react when a new seed is generated.
- Error handling ensures valid ranges are provided.
- The code is structured to separate concerns and facilitate maintainability.

