import java.io.*;
import java.nio.file.Files;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.locks.ReentrantLock;

public class FileChunkProcessor {

    private LoggingCallback loggingCallback;
    private ReentrantLock lock = new ReentrantLock();

    public interface LoggingCallback {
        void logMessage(String message);
    }

    public void setLoggingCallback(LoggingCallback callback) {
        this.loggingCallback = callback;
    }

    public void readProcessWriteFile(String filePath, int chunkSize, int bufferSize, boolean useParallelProcessing) throws IOException {
        validateFilePath(filePath);
        if (chunkSize <= 0 || bufferSize <= 0) throw new IllegalArgumentException("Chunk size and buffer size must be positive integers.");

        ExecutorService executor = Executors.newFixedThreadPool(useParallelProcessing ? Runtime.getRuntime().availableProcessors() : 1);

        try (RandomAccessFile inputFile = new RandomAccessFile(filePath, "r");
             BufferedOutputStream outputStream = new BufferedOutputStream(new FileOutputStream(filePath + ".processed"), bufferSize)) {

            long fileSize = inputFile.length();
            int chunks = (int) ((fileSize + chunkSize - 1) / chunkSize);

            for (int i = 0; i < chunks; i++) {
                executor.submit(() -> processChunk(inputFile, outputStream, i * chunkSize, Math.min(chunkSize, fileSize - i * chunkSize), bufferSize));
            }

            executor.shutdown();
            while (!executor.isTerminated()) {}
        }
    }

    private void processChunk(RandomAccessFile inputFile, BufferedOutputStream outputStream, long startOffset, int chunkLength, int bufferSize) {
        try {
            byte[] buffer = new byte[bufferSize];
            inputFile.seek(startOffset);
            int bytesRead;

            lock.lock();
            try {
                while ((bytesRead = inputFile.read(buffer, 0, Math.min(buffer.length, chunkLength))) > 0) {
                    // Simulate processing (e.g., transform data)
                    for (int i = 0; i < bytesRead; i++) {
                        buffer[i] = (byte) ~buffer[i]; // Example transformation
                    }
                    outputStream.write(buffer, 0, bytesRead);
                }
            } finally {
                lock.unlock();
            }

            if (loggingCallback != null) loggingCallback.logMessage("Processed chunk at offset: " + startOffset);

        } catch (IOException e) {
            logError("Failed to process chunk starting at offset: " + startOffset, e);
        }
    }

    private void validateFilePath(String filePath) throws IOException {
        if (!Files.exists(Paths.get(filePath))) {
            throw new FileNotFoundException("File not found: " + filePath);
        }
    }

    private void logError(String message, Exception e) {
        System.err.println(message);
        e.printStackTrace();
        if (loggingCallback != null) loggingCallback.logMessage(message + " - " + e.getMessage());
    }

    public void processFileInChunks(String filePath, int chunkSize, int bufferSize) throws IOException {
        readProcessWriteFile(filePath, chunkSize, bufferSize, false);
    }

    public void processFileInParallel(String filePath, int chunkSize, int bufferSize) throws IOException {
        readProcessWriteFile(filePath, chunkSize, bufferSize, true);
    }
}
