// Mock database logger function for demonstration purposes.
bool logToDatabase(const std::string& timestamp, const std::string& action, const std::forward_list<std::string>& modifiedList) {
    try {
        // Simulate database logging operation
        std::cout << "Logging to Database: " << timestamp << " | Action: " << action << " | Modified List: ";
        for (const auto& item : modifiedList) {
            std::cout << item << " ";
        }
        std::cout << std::endl;
        return true; // Return true if logging succeeds
    } catch (...) {
        return false; // In case of an exception, log operation fails
    }
}

void insertString(std::forward_list<std::string>& list, const std::string& targetStr, const std::string& strToInsert, int numOccurrences = 1) {
    if (list.empty() || targetStr.empty() || strToInsert.empty()) return;

    bool found = false;
    auto it = list.before_begin();

    for (auto currIt = list.begin(); currIt != list.end(); ++currIt) {
        if (*currIt == targetStr && !found) {
            // Insert after the first occurrence
            for (int i = 0; i < numOccurrences; ++i) {
                it = std::next(currIt);
                list.insert_after(it, strToInsert);
            }
            found = true;
        } else if (!found) {
            it = currIt;
        }
    }

    // If the target string was not found, insert at the end
    if (!found) {
        list.push_back(strToInsert);
    }

    // Log to database with error handling
    std::time_t now = std::time(nullptr);
    std::string timestamp = std::ctime(&now);

    bool logSuccess = logToDatabase(timestamp, "Insert String Operation", list);
    if (!logSuccess) {
        std::cerr << "Error: Failed to log operation details to the database." << std::endl;
    }
}

int main() {
    // Example usage
    std::forward_list<std::string> myList{"apple", "banana", "cherry"};

    try {
        insertString(myList, "banana", "orange", 2);
        for (const auto& item : myList) {
            std::cout << item << " ";
        }
        std::cout << std::endl;
    } catch (const std::exception &ex) {
        std::cerr << "Exception occurred: " << ex.what() << std::endl;
    }

    return 0;
}
```

### Explanation:
- The function `insertString` takes a forward list of strings and two mandatory string parameters. It optionally takes an integer parameter specifying the number of times to insert the second string.
- The logic checks for occurrences of the target string, inserting the new string after each occurrence as specified by `numOccurrences`.
- If the target string is not found, it appends the new string at the end.
- A mock function `logToDatabase` simulates logging database operations. In practice, this would be replaced with actual database interaction code using a library like SQLite or any other suitable library for your database system.
- The program handles various edge cases such as empty lists and null inputs (by returning early if necessary).
- Proper error handling is included to manage potential exceptions that might occur during the logging process.

