// Utility to fetch scripts with caching
async function fetchScripts(apiEndpoint) {
  const cache = new Map();

  async function fetchScript(url) {
    if (cache.has(url)) {
      return cache.get(url);
    }

    try {
      const response = await fetch(url, { mode: 'cors', timeout: 5000 });

      if (!response.ok) throw new Error(`Failed to fetch script from ${url}`);

      const data = await response.json();
      if (!data.code) throw new Error('Script code missing');

      cache.set(url, data);
      return data;
    } catch (error) {
      console.error(error.message);
      return null;
    }
  }

  try {
    const scriptsResponse = await fetch(apiEndpoint);

    if (!scriptsResponse.ok) throw new Error(`Failed to fetch script list from ${apiEndpoint}`);

    const scriptList = await scriptsResponse.json();
    return Promise.all(scriptList.map(url => fetchScript(url)));
  } catch (error) {
    console.error(error.message);
    return [];
  }
}

// Render scripts as HTML
function renderScripts(scripts) {
  return scripts.reduce((html, { code, type }, index) => {
    if (!code || !type) return html;

    const key = `script-${index}`;
    return `${html}<script key="${key}" type="${type}">${code}</script>`;
  }, '');
}

// Manage DOM and load scripts asynchronously
function manageScriptsInDOM(scriptsHtml, containerId) {
  const container = document.getElementById(containerId);

  // Clean up existing scripts
  const oldScripts = Array.from(container.querySelectorAll('script'));
  oldScripts.forEach(script => script.remove());

  // Insert new scripts
  container.insertAdjacentHTML('beforeend', scriptsHtml);
}

// Display loading spinner or progress indicator
function showLoadingSpinner(isVisible) {
  const spinner = document.getElementById('loading-spinner');

  if (isVisible) {
    spinner.style.display = 'block';
  } else {
    spinner.style.display = 'none';
  }
}

async function renderFooter(apiEndpoint, containerId) {
  try {
    showLoadingSpinner(true);

    const scripts = await fetchScripts(apiEndpoint);
    const scriptsHtml = renderScripts(scripts);
    manageScriptsInDOM(scriptsHtml, containerId);
  } finally {
    showLoadingSpinner(false);
  }
}

// Example usage
document.addEventListener('DOMContentLoaded', () => {
  renderFooter('https://api.example.com/scripts', 'footer-container');
});
