namespace DistributedSim {

class RandomNumberGenerator {
public:
    // Constructor initializes RNG with an optional external seed value
    RandomNumberGenerator(int initialSeed = getDefaultSeed()) : rng(initialSeed) {}

    // Generates a pseudo-random number within the specified range [min, max]
    int generateRandomNumber(int min, int max) {
        std::uniform_int_distribution<int> dist(min, max);
        return dist(rng);
    }

    // Updates the seed value with an external source; fallback to default if unavailable
    void updateSeed(const std::string& seedSourceUrl) {
        try {
            int newSeed = fetchExternalSeed(seedSourceUrl);
            rng.seed(newSeed);
        } catch (const std::exception& e) {
            std::cerr << "Failed to update seed from external source: " << e.what() << ". Using default seed.\n";
            rng.seed(getDefaultSeed());
        }
    }

    // Destructor
    ~RandomNumberGenerator() = default;

private:
    std::mt19937 rng;

    // Fetches a new seed value from an external data source
    int fetchExternalSeed(const std::string& url) {
        // Simulate fetching seed with potential delay or failure
        if (url.empty()) throw std::invalid_argument("Seed source URL is empty.");

        std::this_thread::sleep_for(std::chrono::milliseconds(100));  // simulate network delay

        // Simulated successful fetch; replace this logic with actual external call
        return std::hash<std::string>{}(url) % 10000 + 1;
    }

    // Provides a default seed value in case the external source fails
    static int getDefaultSeed() {
        auto timeNow = std::chrono::system_clock::now();
        return std::chrono::duration_cast<std::chrono::milliseconds>(timeNow.time_since_epoch()).count();
    }
};

}  // namespace DistributedSim

