// Utility function to generate a unique key for each script tag
const generateUniqueKey = (() => {
  let counter = 0;
  return () => `script-${counter++}`;
})();

// Function to log errors
function logError(error) {
  console.error('Script Error:', error);
}

// Fetch scripts from an external API endpoint
async function fetchScripts(apiEndpoint) {
  const cache = new Map();

  try {
    const response = await fetch(apiEndpoint, { cache: 'no-store' });
    if (!response.ok) throw new Error(`Network response was not ok: ${response.statusText}`);

    const scriptsArray = await response.json();

    // Caching fetched scripts
    scriptsArray.forEach((scriptObj) => {
      if (scriptObj.id && scriptObj.code) cache.set(scriptObj.id, scriptObj);
    });

    return scriptsArray;
  } catch (error) {
    logError(error);
    return [];
  }
}

// Function to render a footer with scripts as <script> tags
function renderFooter(scripts = []) {
  const container = document.createElement('div');
  let htmlString = '';

  scripts.forEach((scriptObj, index) => {
    if (!scriptObj.code || typeof scriptObj.code !== 'string') return;

    const key = generateUniqueKey();
    const attributes = `key="${key}"`;

    // Asynchronously setting innerHTML to avoid blocking
    setTimeout(() => {
      htmlString += `<script ${attributes} type="${scriptObj.type || ''}">
        ${scriptObj.code}
      </script>`;
      container.insertAdjacentHTML('beforeend', scriptObj.code);
    }, 0);
  });

  return htmlString;
}

// Function to update the footer dynamically
async function updateFooter(apiEndpoint) {
  const spinner = document.createElement('div');
  spinner.textContent = 'Loading...';
  document.body.appendChild(spinner);

  const scripts = await fetchScripts(apiEndpoint);

  // Clean up and remove spinner after loading is complete
  setTimeout(() => {
    document.body.removeChild(spinner);
    const footerHtml = renderFooter(scripts);

    // Insert the rendered scripts into the footer section of the webpage
    const footer = document.getElementById('footer');
    if (footer) {
      footer.innerHTML = footerHtml;
    } else {
      const newFooter = document.createElement('footer');
      newFooter.id = 'footer';
      newFooter.innerHTML = footerHtml;
      document.body.appendChild(newFooter);
    }
  }, 1000); // Simulate a delay for demonstration purposes
}

// Example usage: Call updateFooter with your API endpoint
// updateFooter('https://api.example.com/scripts');

module.exports = {
  fetchScripts,
  renderFooter,
  updateFooter,
};
