using System;

public enum DistributionType
{
    Uniform,
    Normal
}

public class RandomValueGenerator
{
    private readonly float minValue;
    private readonly float maxValue;
    private readonly DistributionType distributionType;

    public RandomValueGenerator(float min, float max, DistributionType type)
    {
        if (min >= max) throw new ArgumentException("Minimum value must be less than maximum value.");
        if (type == DistributionType.Normal && (max - min < 6)) // Assuming a reasonable range for standard deviations
            throw new ArgumentException("Range too small for normal distribution.");

        minValue = min;
        maxValue = max;
        distributionType = type;
    }

    public float GetRandomFloat()
    {
        switch (distributionType)
        {
            case DistributionType.Uniform:
                return (float)new Random().NextDouble() * (maxValue - minValue) + minValue;

            case DistributionType.Normal:
                double mean = (minValue + maxValue) / 2;
                double stdDeviation = (maxValue - minValue) / 6; // Approx. 99.7% within range
                return (float)(new Random().NextDouble() * stdDeviation * 2 + (1 - new Random().NextDouble()) * stdDeviation + mean);

            default:
                throw new InvalidOperationException("Unsupported distribution type.");
        }
    }

    public int GetRandomInt()
    {
        switch (distributionType)
        {
            case DistributionType.Uniform:
                return new Random().Next((int)minValue, (int)Math.Ceiling(maxValue));

            case DistributionType.Normal:
                double mean = (minValue + maxValue) / 2;
                double stdDeviation = (maxValue - minValue) / 6;
                double randomValue = new Random().NextDouble() * stdDeviation * 2 + (1 - new Random().NextDouble()) * stdDeviation + mean;
                return (int)Math.Round(randomValue);

            default:
                throw new InvalidOperationException("Unsupported distribution type.");
        }
    }

    public float GetRandomFloatWithinQuantile(float lowerBound, float upperBound)
    {
        if (lowerBound < 0 || upperBound > 1 || lowerBound >= upperBound)
            throw new ArgumentOutOfRangeException("Quantiles must be between 0 and 1 and in the range lowerBound < upperBound.");

        return GetRandomFloat() * (upperBound - lowerBound) + minValue + (maxValue - minValue) * lowerBound;
    }

    public int GetRandomIntWithinStandardDeviation(int numStdDeviations)
    {
        double mean = (minValue + maxValue) / 2;
        double stdDeviation = (maxValue - minValue) / 6;

        if (numStdDeviations < 0) throw new ArgumentOutOfRangeException("Number of standard deviations must be non-negative.");

        double lowerBound = mean - numStdDeviations * stdDeviation;
        double upperBound = mean + numStdDeviations * stdDeviation;

        return (int)Math.Round(GetRandomFloat() * (upperBound - lowerBound) + Math.Max(minValue, lowerBound));
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}], Distribution Type: {distributionType}";
    }
}

// Example usage:
// RandomValueGenerator generator = new RandomValueGenerator(0, 100, DistributionType.Uniform);
// float randomFloat = generator.GetRandomFloat();
// int randomInt = generator.GetRandomInt();
