using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Newtonsoft.Json;

public class HtmlContentService
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private const string CacheKeyPrefix = "HtmlContent_";

    public HtmlContentService(HttpClient httpClient, IMemoryCache cache)
    {
        _httpClient = httpClient;
        _cache = cache;
    }

    public async Task UpdateHtmlContentAsync(string pageSectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId))
            throw new ArgumentException("Page section ID and Element ID cannot be null or empty.");

        string key = $"{CacheKeyPrefix}{pageSectionId}_{elementId}";

        try
        {
            // Attempt to update content directly via storage service for atomic operation
            var response = await _httpClient.PostAsync(
                $"https://externalstorage.com/api/updateHtmlContent",
                new StringContent(JsonConvert.SerializeObject(new { pageSectionId, elementId, htmlContent }), Encoding.UTF8, "application/json"));

            if (!response.IsSuccessStatusCode)
                throw new HttpRequestException($"Failed to update content. Status Code: {response.StatusCode}");

            // Invalidate cache after successful update
            _cache.Remove(key);

        }
        catch (HttpRequestException ex)
        {
            // Handle HTTP request failures
            Console.Error.WriteLine(ex.Message);

            // Fallback strategy for high concurrency - read from cache and retry logic if needed
            var cachedContent = await GetCachedHtmlContentAsync(pageSectionId, elementId);
            if (!string.Equals(cachedContent, htmlContent))
            {
                // Retry update logic or queue the update request here
                Console.WriteLine("Retrying or queueing for later.");
            }
        }
    }

    private async Task<string> GetCachedHtmlContentAsync(string pageSectionId, string elementId)
    {
        string key = $"{CacheKeyPrefix}{pageSectionId}_{elementId}";
        if (!_cache.TryGetValue(key, out string cachedContent))
        {
            // Fetch from storage service
            var response = await _httpClient.GetAsync($"https://externalstorage.com/api/getHtmlContent?section={pageSectionId}&element={elementId}");
            if (response.IsSuccessStatusCode)
            {
                cachedContent = await response.Content.ReadAsStringAsync();
                _cache.Set(key, cachedContent, TimeSpan.FromMinutes(5)); // Adjust cache duration as needed
            }
        }

        return cachedContent;
    }
}

