import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SocketChannel;
import java.util.Random;

public class GameCharacter {

    private static final String SERVER_HOST = "example.com";
    private static final int SERVER_PORT = 12345;
    private static final int RETRY_LIMIT = 3;
    private static final long INITIAL_COOLDOWN = 1000; // milliseconds
    private Random random = new Random();

    private long lastAttackTime = -1;
    private SocketChannel socketChannel;

    public void manageConnectionAndAttacks() {
        if (!establishConnection()) {
            System.out.println("Failed to establish connection after retries.");
            return;
        }

        while (true) { // Simulate continuous game loop
            try {
                long currentTime = System.currentTimeMillis();
                if (canPerformAttack(currentTime)) {
                    Attack selectedAttack = selectRandomAttack();
                    executeAttack(selectedAttack);
                    adjustCooldownBasedOnServerLoad();
                }

                Thread.sleep(100); // Reduce CPU usage, simulate game tick
            } catch (IOException | InterruptedException e) {
                logEvent("Error during connection or attack: " + e.getMessage());
                break;
            }
        }
    }

    private boolean establishConnection() {
        int retries = 0;
        while (retries < RETRY_LIMIT) {
            try {
                socketChannel = SocketChannel.open();
                socketChannel.connect(new InetSocketAddress(SERVER_HOST, SERVER_PORT));

                if (socketChannel.finishConnect()) {
                    logEvent("Successfully connected to the server.");
                    return true;
                }
            } catch (IOException e) {
                retries++;
                logEvent("Connection attempt " + retries + " failed: " + e.getMessage());
                try {
                    Thread.sleep(2000); // Wait before retrying
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
        return false;
    }

    private boolean canPerformAttack(long currentTime) {
        if (lastAttackTime == -1 || (currentTime - lastAttackTime >= getCooldownPeriod())) {
            return true;
        }
        return false;
    }

    private Attack selectRandomAttack() {
        // Simulated resource and history check
        int resources = 50; // Placeholder for actual resource level
        boolean recentStrongAttack = (lastAttackTime != -1 && System.currentTimeMillis() - lastAttackTime < getCooldownPeriod());

        if (resources > 30 && !recentStrongAttack) {
            return new Attack("Power Strike", 80);
        } else {
            return new Attack("Quick Jab", 40);
        }
    }

    private void executeAttack(Attack attack) throws IOException, InterruptedException {
        lastAttackTime = System.currentTimeMillis();

        logEvent("Executing attack: " + attack.getType() + " with power " + attack.getPower());

        // Simulated network delay
        Thread.sleep(random.nextInt(100)); 
    }

    private void adjustCooldownBasedOnServerLoad() {
        // Placeholder for actual logic to determine server load and latency
        long additionalDelay = random.nextInt(500); // Simulate varying conditions
        System.out.println("Adjusting cooldown by " + additionalDelay + " ms due to server conditions.");
    }

    private long getCooldownPeriod() {
        return INITIAL_COOLDOWN; // Placeholder, could be dynamically adjusted based on server load/latency
    }

    private void logEvent(String message) {
        System.out.println("[LOG] " + message);
    }

    static class Attack {
        private final String type;
        private final int power;

        public Attack(String type, int power) {
            this.type = type;
            this.power = power;
        }

        public String getType() {
            return type;
        }

        public int getPower() {
            return power;
        }
    }

    public static void main(String[] args) {
        GameCharacter character = new GameCharacter();
        character.manageConnectionAndAttacks();
    }
}
