### Rust Function

```rust
use std::env;
use std::ffi::{CStr, CString};
use std::os::raw::c_char;
use std::path::PathBuf;

#[no_mangle]
pub extern "C" fn create_dir_with_env_var(directory_name: *const c_char) -> i32 {
    let dir_name = unsafe { CStr::from_ptr(directory_name).to_str().unwrap() };

    if let Ok(existing_path) = env::var("MY_CUSTOM_DIR") {
        println!("Environment variable already set to: {}", existing_path);
        return 0;
    }

    match create_directory_and_set_env_var(dir_name) {
        Ok(_) => 0,
        Err(e) => {
            eprintln!("Failed to create directory or set environment variable: {}", e);
            -1
        }
    }
}

fn create_directory_and_set_env_var(directory_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let path = PathBuf::from(env::current_dir()?).join(directory_name);

    if !path.exists() {
        std::fs::create_dir_all(&path)?;
        println!("Created directory at: {}", path.display());

        // Set environment variable
        env::set_var("MY_CUSTOM_DIR", path.to_string_lossy().into_owned())?;
    }

    Ok(())
}
```

