```php
<?php

/**
 * Generates a secure random string of a specified length.
 *
 * @param int $length The desired length of the random string.
 * @param string $charset The character set to use for generating the string.
 * 
 * @return string|null The generated string or null on error.
 */
function generateSecureRandomString($length, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
    if (!is_int($length) || $length <= 0) {
        return null; // Invalid length
    }
    $str = '';
    $maxIndex = strlen($charset) - 1;
    for ($i = 0; $i < $length; $i++) {
        $randByte = random_int(0, PHP_INT_MAX);
        $str .= $charset[$randByte % ($maxIndex + 1)];
    }
    return $str;
}

/**
 * Hashes a given password with a customizable hash algorithm and salt.
 *
 * @param string $password The password to be hashed.
 * @param string $algorithm The hashing algorithm to use (e.g., 'bcrypt', 'argon2').
 * 
 * @return string|null The hashed password or null on error.
 */
function hashPassword($password, $algorithm = 'bcrypt') {
    if (!in_array($algorithm, ['bcrypt', 'argon2'], true)) {
        return null; // Unsupported algorithm
    }

    try {
        switch ($algorithm) {
            case 'bcrypt':
                return password_hash($password, PASSWORD_BCRYPT);
            case 'argon2':
                return password_hash($password, PASSWORD_ARGON2ID);
        }
    } catch (Exception $e) {
        error_log('Password hashing failed: ' . $e->getMessage());
        return null;
    }
}

/**
 * Handles session management for tokens and hashed passwords.
 *
 * @param string $key The key under which to store the data.
 * @param mixed  $data The data to be stored (string or array).
 */
function manageSession($key, $data) {
    if (!session_id()) {
        session_start();
    }

    $_SESSION[$key] = $data;
}

// Example usage
$token = generateSecureRandomString(32);
$passwordHash = hashPassword('my_secure_password', 'argon2id');

if ($token && $passwordHash) {
    manageSession('token', $token);
    manageSession('password_hash', $passwordHash);
}
