const fs = require('fs');
const path = require('path');

/**
 * Reads a file synchronously from a directory and returns its contents as a string.
 *
 * @param {string} directoryPath The path to the directory containing the file.
 * @param {string} fileName The name of the file to read.
 * 
 * @return {string|null} The content of the file or null if an error occurs.
 */
function readFileContent(directoryPath, fileName) {
    try {
        const filePath = path.join(directoryPath, fileName);

        // Check if the file exists
        if (!fs.existsSync(filePath)) {
            throw new Error('File does not exist');
        }

        // Read and return the content of the file
        return fs.readFileSync(filePath, 'utf8');
    } catch (error) {
        console.error('Error reading file:', error.message);
        return null;
    }
}

