```csharp
using System;
using System.Collections.Concurrent;
using System.Data;
using System.Threading;
using Microsoft.Extensions.Logging;

public class DatabaseConnectionManager : IDisposable
{
    private readonly ConcurrentDictionary<string, ObjectPool<IDbConnection>> _connectionPools = new();
    private ILogger<DatabaseConnectionManager> _logger;

    public DatabaseConnectionManager(ILogger<DatabaseConnectionManager> logger)
    {
        _logger = logger;
    }

    public IDbConnection GetConnection(string provider, string connectionString)
    {
        if (!_connectionPools.TryGetValue(provider, out var connectionPool))
        {
            connectionPool = new ObjectPool<IDbConnection>(() => CreateConnection(provider, connectionString), 
                                                           (conn) => ReleaseConnection(conn));
            _connectionPools[provider] = connectionPool;
        }

        return connectionPool.Get();
    }

    public void ReleaseConnection(IDbConnection connection)
    {
        if (_connectionPools.Count > 0 && connection != null)
        {
            foreach (var pool in _connectionPools.Values)
            {
                if (pool.TryReturn(connection))
                    break;
            }
        }
    }

    public string ToString()
    {
        return $"DatabaseConnectionManager State: Pools = {_connectionPools.Count}, Connections Managed: {GetActiveConnectionsCount()}";
    }

    public void InitializeFromConfiguration()
    {
        // Simulate loading configuration from an external system
        _logger.LogInformation("Initializing database connection settings from configuration management system.");
        // Implementation for integration with Azure App Configuration or AWS SSM would go here.
    }

    public void ConfigurePooling(int minSize, int maxSize, int idleTimeout)
    {
        foreach (var pool in _connectionPools.Values)
        {
            pool.Configure(minSize, maxSize, idleTimeout);
        }
    }

    public object GetPerformanceMetrics()
    {
        // Collect and return performance metrics
        return new 
        {
            TotalConnections = _connectionPools.Count,
            ActiveConnections = GetActiveConnectionsCount(),
            PerformanceData = "Simulated data" // Replace with actual metric collection logic
        };
    }

    private int GetActiveConnectionsCount() => _connectionPools.Values.Sum(pool => pool.ActiveCount);

    private IDbConnection CreateConnection(string provider, string connectionString)
    {
        try
        {
            switch (provider.ToLower())
            {
                case "mysql":
                    return new MySql.Data.MySqlClient.MySqlConnection(connectionString);
                case "postgresql":
                    return new Npgsql.NpgsqlConnection(connectionString);
                case "sqlite":
                    return new System.Data.SQLite.SQLiteConnection(connectionString);
                default:
                    throw new NotSupportedException($"Provider {provider} is not supported.");
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to create connection for provider {provider}");
            throw;
        }
    }

    private void ReleaseConnection(IDbConnection conn)
    {
        if (conn != null && !conn.State.Equals(ConnectionState.Closed))
        {
            try
            {
                conn.Close();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to close connection.");
            }
        }
    }

    public void Dispose()
    {
        foreach (var pool in _connectionPools.Values)
        {
            pool.Dispose();
        }
        _connectionPools.Clear();
    }

    private class ObjectPool<T> : IDisposable where T : class
    {
        private readonly Func<T> _objectGenerator;
        private readonly Action<T> _onRelease;
        private readonly ConcurrentBag<T> _objects;
        private int _minSize, _maxSize, _idleTimeout;

        public ObjectPool(Func<T> objectGenerator, Action<T> onRelease)
        {
            _objectGenerator = objectGenerator ?? throw new ArgumentNullException(nameof(objectGenerator));
            _onRelease = onRelease;
            _objects = new ConcurrentBag<T>();
        }

        public T Get()
        {
            if (_objects.TryTake(out var item))
                return item;

            return _objectGenerator();
        }

        public bool TryReturn(T obj)
        {
            if (obj != null && _objects.Count < _maxSize)
            {
                _objects.Add(obj);
                return true;
            }

            _onRelease(obj);

            if (_objects.Count < _minSize)
                Get(); // Ensure minimum pool size

            return false;
        }

        public void Configure(int minSize, int maxSize, int idleTimeout)
        {
            _minSize = minSize;
            _maxSize = maxSize;
            _idleTimeout = idleTimeout;

            while (_objects.Count < _minSize && _objects.Count < _maxSize)
                Get();
        }

        public int ActiveCount => _maxSize - _objects.Count;

        public void Dispose()
        {
            foreach (var obj in _objects)
            {
                _onRelease(obj);
            }
            _objects.Clear();
        }
    }
}
```

**Note:** This code provides a basic structure for managing database connections with pooling and includes placeholders where integration with external configuration management systems would occur. The `ObjectPool<T>` class demonstrates simple pooling logic, and additional error handling/logging can be added as needed for robustness. Integration specifics (e.g., Azure App Configuration or AWS SSM) are simulated through logger messages but should be implemented using appropriate SDKs or libraries.

