using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AesGcmEncryptionService
{
    private const int KeySize = 32; // AES-256 bits
    private const int NonceSize = 12;
    private const int TagSize = 16;

    public (byte[] EncryptedData, byte[] Nonce, byte[] Tag) EncryptFile(string filePath, byte[] encryptionKey)
    {
        using var aesGcm = new AesGcm(encryptionKey);

        byte[] nonce = new byte[NonceSize];
        RandomNumberGenerator.Fill(nonce);

        using (var inputFileStream = File.OpenRead(filePath))
        {
            long fileSize = inputFileStream.Length;
            using (var memoryStream = new MemoryStream())
            {
                memoryStream.Write(nonce, 0, NonceSize);

                var tag = new byte[TagSize];
                aesGcm.Encrypt(nonce, inputFileStream.ReadWriteBytes(), tag);

                memoryStream.Write(tag, 0, TagSize);
                memoryStream.Write(inputFileStream.ReadWriteBytes(), 0, (int)fileSize - (int)memoryStream.Position + NonceSize + TagSize);

                return (memoryStream.ToArray(), nonce, tag);
            }
        }
    }

    public byte[] DecryptFile(byte[] encryptedData, byte[] nonce, byte[] tag, byte[] encryptionKey)
    {
        using var aesGcm = new AesGcm(encryptionKey);

        int nonceOffset = 0;
        int cipherTextStartIndex = NonceSize;

        var tagCopy = new byte[TagSize];
        Array.Copy(encryptedData, cipherTextStartIndex, tagCopy, 0, TagSize);
        cipherTextStartIndex += TagSize;

        using (var memoryStream = new MemoryStream())
        {
            aesGcm.Decrypt(nonce, encryptedData, cipherTextStartIndex, encryptedData.Length - cipherTextStartIndex, tag);

            if (!tag.SequenceEqual(tagCopy))
                throw new CryptographicException("Tag mismatch. Decryption failed due to data corruption or tampering.");

            memoryStream.Write(encryptedData, cipherTextStartIndex, encryptedData.Length - cipherTextStartIndex);
            return memoryStream.ToArray();
        }
    }

    private static class StreamExtensions
    {
        public static byte[] ReadWriteBytes(this Stream stream)
        {
            using var memoryStream = new MemoryStream();
            stream.CopyTo(memoryStream);
            return memoryStream.ToArray();
        }
    }
}

