#include <cstdio>
#include <cstdlib>
#include <ctime>
#include <cstring>
#include <cerrno>
#include <sys/stat.h>

// Function to generate a random alphanumeric string of given length
void generateRandomString(char* str, size_t len) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    while (--len) {
        *str++ = charset[(int)(drand48() * (sizeof(charset) - 1))];
    }
    *str = '\0';
}

// Function to generate a new file name based on the input file path
void generateNewFileName(const char* filePath, char* newFilePath, size_t maxLen) {
    struct stat pathStat;
    if (stat(filePath, &pathStat) != 0) {
        perror("Failed to get file status");
        return;
    }

    // Extract directory and base name from the input file path
    const char* dir = filePath;
    while (*filePath && *filePath != '/') {
        filePath++;
    }
    const char* baseName = (filePath[0] == '/' ? filePath + 1 : filePath);

    // Extract file extension if present
    char* dotPos = strrchr(baseName, '.');
    const char* ext = dotPos ? dotPos : "";
    const char* fileNameWithoutExt = (ext ? baseName : baseName) - strlen(ext);

    // Generate timestamp in YYYYMMDD_HHMMSS format
    time_t rawTime;
    struct tm *timeInfo;
    char timeStamp[20];
    time(&rawTime);
    timeInfo = localtime(&rawTime);
    strftime(timeStamp, sizeof(timeStamp), "%Y%m%d_%H%M%S", timeInfo);

    // Generate a random alphanumeric string for versioning
    char randomStr[16];  // Adjust size as needed
    srand48((unsigned)time(NULL));
    generateRandomString(randomStr, sizeof(randomStr) - 1);

    // Create the new file name with constraints
    char newFileName[256];
    snprintf(newFileName, sizeof(newFileName), "%s_%s%s_v%s", fileNameWithoutExt, timeStamp, ext, randomStr);

    // Construct the full path for the new file name ensuring it does not exceed maxLen
    if (snprintf(newFilePath, maxLen, "%s/%s", dir, newFileName) >= maxLen) {
        fprintf(stderr, "Generated file name exceeds maximum length\n");
        snprintf(newFilePath, maxLen, "error_filename_too_long.txt");  // Fallback or error handling
    }
}
