#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

typedef struct {
    const char *url;
    CURL* curl_handle;
} RequestBuilder;

int verify_json_and_create_request(const char *json_string, const char *base_url, int disable_ssl_verification) {
    // Required fields
    const char *required_fields[] = {"access_token", "expires_in", "token_type"};
    const size_t num_required_fields = sizeof(required_fields) / sizeof(required_fields[0]);

    if (!json_string || !base_url) return 0;

    int is_valid = 1;
    char access_token[256] = {0};
    int expires_in = -1;
    char token_type[32] = {0};

    // Parse JSON
    // This example assumes a simple parsing logic for illustration.
    // In practice, use a proper JSON parser library.
    for (size_t i = 0; i < num_required_fields && is_valid; ++i) {
        char *start_key = strstr(json_string, required_fields[i]);
        if (!start_key) {
            is_valid = 0;
            continue;
        }

        start_key += strlen(required_fields[i]) + 2; // skip key and ": "
        char *end_value = strchr(start_key, ',');
        end_value = end_value ? end_value : strstr(start_key, "}");

        if (!end_value) {
            is_valid = 0;
            continue;
        }

        size_t value_length = end_value - start_key;
        char temp_value[value_length + 1];
        strncpy(temp_value, start_key, value_length);
        temp_value[value_length] = '\0';

        if (strcmp(required_fields[i], "access_token") == 0) {
            strcpy(access_token, temp_value);
        } else if (strcmp(required_fields[i], "expires_in") == 0) {
            expires_in = atoi(temp_value);
        } else if (strcmp(required_fields[i], "token_type") == 0) {
            strcpy(token_type, temp_value);
        }
    }

    // Validate parsed values
    if (!is_valid || strlen(access_token) == 0 || expires_in <= 0 || strcmp(token_type, "Bearer")) {
        return 0;
    }

    // Create the RequestBuilder
    RequestBuilder *request_builder = (RequestBuilder *)malloc(sizeof(RequestBuilder));
    if (!request_builder) return 0;

    request_builder->url = base_url;
    request_builder->curl_handle = curl_easy_init();

    if (!request_builder->curl_handle) {
        free(request_builder);
        return 0;
    }

    // Set up CURL options
    curl_easy_setopt(request_builder->curl_handle, CURLOPT_URL, request_builder->url);

    if (disable_ssl_verification) {
        curl_easy_setopt(request_builder->curl_handle, CURLOPT_SSL_VERIFYPEER, 0L);
        curl_easy_setopt(request_builder->curl_handle, CURLOPT_SSL_VERIFYHOST, 0L);
    }

    // Set Authorization header
    char auth_header[512];
    snprintf(auth_header, sizeof(auth_header), "Authorization: Bearer %s", access_token);
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, auth_header);
    curl_easy_setopt(request_builder->curl_handle, CURLOPT_HTTPHEADER, headers);

    return 1;
}
