#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <curl/curl.h>
#include "parson.h" // Include a JSON library like parson

// A structure to cache tokens
typedef struct {
    char *access_token;
    time_t expires_at; // Timestamp when the token expires
} TokenCache;

TokenCache* token_cache = NULL;

bool is_valid_json(const char *json, const char **error) {
    json_value *root = json_parse_string(json);
    if (json_get_error_code(root)) {
        if (error) *error = "Invalid JSON format";
        return false;
    }
    json_value_free(root);
    return true;
}

bool validate_token_fields(const char *json, const char **error) {
    json_value *root = json_parse_string(json);

    // Check for required fields
    if (!json_object_get_value(json_object(root), "access_token") ||
        !json_object_get_value(json_object(root), "expires_in") ||
        !json_object_get_value(json_object(root), "token_type")) {
        if (error) *error = "Missing required field(s)";
        json_value_free(root);
        return false;
    }

    // Validate token_type
    const char *token_type = json_object_get_string(json_object(root), "token_type");
    if (strcmp(token_type, "Bearer") != 0) {
        if (error) *error = "Invalid token type";
        json_value_free(root);
        return false;
    }

    // Validate expires_in
    int64_t expires_in = (int64_t)json_object_get_number(json_object(root), "expires_in");
    if (expires_in <= 0) {
        if (error) *error = "Invalid expires_in value";
        json_value_free(root);
        return false;
    }

    json_value_free(root);
    return true;
}

bool cache_token(const char *access_token, int64_t expires_in) {
    time_t current_time = time(NULL);
    time_t expiration_time = current_time + expires_in;

    // Allocate and initialize token cache
    if (token_cache == NULL) {
        token_cache = malloc(sizeof(TokenCache));
        token_cache->access_token = strdup(access_token);
        token_cache->expires_at = expiration_time;
    } else {
        free(token_cache->access_token);
        token_cache->access_token = strdup(access_token);
        token_cache->expires_at = expiration_time;
    }

    return true;
}

bool is_cached_token_valid() {
    if (token_cache == NULL) return false;

    time_t current_time = time(NULL);
    return current_time < token_cache->expires_at;
}

typedef struct {
    char *url;
    bool verify_ssl;
} RequestBuilder;

RequestBuilder create_request_builder(const char *url, bool verify_ssl) {
    RequestBuilder builder;
    builder.url = strdup(url);
    builder.verify_ssl = verify_ssl;
    return builder;
}

bool free_request_builder(RequestBuilder *builder) {
    if (builder == NULL) return false;
    free(builder->url);
    return true;
}

bool construct_and_cache_token(const char *json, const char **error) {
    if (!is_valid_json(json, error)) return false;

    if (!validate_token_fields(json, error)) return false;

    json_value *root = json_parse_string(json);

    // Extract token details
    const char *access_token = json_object_get_string(json_object(root), "access_token");
    int64_t expires_in = (int64_t)json_object_get_number(json_object(root), "expires_in");

    bool cache_result = cache_token(access_token, expires_in);
    json_value_free(root);

    if (!cache_result && error != NULL) {
        *error = "Failed to cache token";
        return false;
    }

    return true;
}

bool validate_and_construct(const char *json, const char **error, RequestBuilder *builder) {
    if (is_cached_token_valid()) {
        builder->url = strdup("Cached URL"); // Use cached URL or similar logic
        builder->verify_ssl = true; // Or handle based on your caching strategy
        return true;
    }

    if (!construct_and_cache_token(json, error)) return false;

    // Create the request builder after token is validated and cached
    builder->url = strdup("https://api.example.com/endpoint"); // Replace with actual URL
    builder->verify_ssl = true; // Set according to your security needs

    return true;
}

int main() {
    const char *json_response = "{\"access_token\":\"abc123\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
    RequestBuilder builder;

    if (validate_and_construct(json_response, NULL, &builder)) {
        printf("Request URL: %s\n", builder.url);
        free_request_builder(&builder);
    } else {
        printf("Token validation failed.\n");
    }

    return 0;
}
```

