using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Xml.Linq;

public class DecryptorConfigurator
{
    public static byte[] DecryptCiphertext(byte[] ciphertext, byte[] key, byte[] iv)
    {
        if (key == null || key.Length != 16 && key.Length != 24 && key.Length != 32 ||
            iv == null || iv.Length != 16)
        {
            throw new ArgumentException("Invalid key or IV length.");
        }

        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                    {
                        return Encoding.UTF8.GetBytes(srDecrypt.ReadToEnd());
                    }
                }
            }
        }
    }

    public static void LoadConfig()
    {
        try
        {
            XDocument doc = XDocument.Load("config.xml");

            var settings = doc.Root?.Elements().ToDictionary(e => e.Name.LocalName, e => Convert.ToInt32(e.Value));

            if (settings != null)
            {
                int tileSize = settings.ContainsKey("tileSize") ? settings["tileSize"] : 0;
                Console.WriteLine($"Tile Size: {tileSize}");

                int worldWidth = settings.ContainsKey("worldWidth") ? settings["worldWidth"] : 0;
                Console.WriteLine($"World Width: {worldWidth}");

                int worldHeight = settings.ContainsKey("worldHeight") ? settings["worldHeight"] : 0;
                Console.WriteLine($"World Height: {worldHeight}");

                double cameraSpeed = settings.ContainsKey("cameraSpeed") ? Convert.ToDouble(settings["cameraSpeed"]) : 0.0;
                Console.WriteLine($"Camera Speed: {cameraSpeed}");
            }
        }
        catch (FileNotFoundException)
        {
            Console.WriteLine("Config file not found.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred while loading the config: {ex.Message}");
        }
    }

    public static void Main(string[] args)
    {
        // Example usage
        byte[] ciphertext = Encoding.UTF8.GetBytes("EncryptedTextHere");
        byte[] key = new byte[16] { /* Your AES key here */ };
        byte[] iv = new byte[16] { /* Your AES IV here */ };

        try
        {
            byte[] plaintext = DecryptCiphertext(ciphertext, key, iv);
            Console.WriteLine("Decrypted Text: " + Encoding.UTF8.GetString(plaintext));
        }
        catch (CryptographicException)
        {
            Console.WriteLine("An error occurred during decryption.");
        }

        LoadConfig();
    }
}
