import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;

public class GameCharacter {

    private static final Logger LOGGER = Logger.getLogger(GameCharacter.class.getName());
    private static final String REMOTE_ADDRESS = "remote.server.address";
    private static final int PORT = 8080;

    private volatile boolean canAttack = true;
    private Selector selector;
    private ScheduledExecutorService scheduler;

    public GameCharacter() {
        try {
            // Setup the selector for non-blocking I/O
            this.selector = Selector.open();

            // Create and configure a scheduled executor service to handle cooldowns
            this.scheduler = Executors.newScheduledThreadPool(1);

            connectToRemoteAddress();

            // Schedule attack selection in a loop with a cooldown
            scheduler.scheduleAtFixedRate(this::selectAttack, 0, 9, TimeUnit.SECONDS);
        } catch (IOException e) {
            LOGGER.severe("Failed to initialize selector: " + e.getMessage());
        }
    }

    private void connectToRemoteAddress() throws IOException {
        SocketChannel socketChannel = SocketChannel.open();
        socketChannel.configureBlocking(false);
        socketChannel.connect(new InetSocketAddress(REMOTE_ADDRESS, PORT));

        SelectionKey key = socketChannel.register(selector, SelectionKey.OP_CONNECT);

        // Handle connection state changes
        new Thread(() -> {
            try {
                while (true) {
                    selector.select();

                    for (SelectionKey k : selector.selectedKeys()) {
                        if (!k.isValid()) continue;

                        if (k.isConnectable()) {
                            SocketChannel channel = (SocketChannel) k.channel();
                            if (channel.finishConnect()) {
                                LOGGER.info("Connected to server.");
                            }
                            key.interestOps(0); // No more interest in connect ops
                        }

                        selector.selectedKeys().remove(k);
                    }
                }
            } catch (IOException e) {
                LOGGER.severe("Error handling connection: " + e.getMessage());
            }
        }).start();
    }

    private void selectAttack() {
        if (!canAttack) return;

        // Randomly select an attack
        int selectedAttack = Math.random() < 0.5 ? 1 : 2;
        LOGGER.info("Selected Attack: " + selectedAttack);

        logAttack(selectedAttack);

        canAttack = false; // Disable attacks until cooldown completes

        // Re-enable the ability to attack after the cooldown period
        scheduler.schedule(() -> canAttack = true, 9, TimeUnit.SECONDS);
    }

    private void logAttack(int attackNumber) {
        try {
            // Simulate logging to a remote service (this would be an actual network call in production)
            System.out.println("Logging attack " + attackNumber + " to remote server.");
            LOGGER.info("Attack " + attackNumber + " logged.");
        } catch (Exception e) {
            LOGGER.severe("Failed to log attack: " + e.getMessage());
        }
    }

    public void close() throws IOException {
        selector.close();
        scheduler.shutdownNow();
    }
}
