Below is an example implementation of such a function in C using libcurl to manage HTTP downloads with concurrency:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

typedef struct {
    size_t bytes_downloaded;
    pthread_t *thread_ids;
    int success;
} DownloadResult;

size_t write_data(void *ptr, size_t size, size_t nmemb, FILE *stream) {
    return fwrite(ptr, size, nmemb, stream);
}

void *download_url_thread(void *arg) {
    const char *url = ((char **)arg)[0];
    const char *output_file_path = ((char **)arg)[1];

    CURL *curl;
    FILE *fp;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();

    if (curl) {
        fp = fopen(output_file_path, "wb");
        if (!fp) return NULL;

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);

        res = curl_easy_perform(curl);

        fclose(fp);

        if (res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
    return NULL;
}

DownloadResult *download_from_urls(const char **urls, int url_count, const char *output_dir, int max_concurrent_downloads) {
    if (!urls || !url_count > 0 || !output_dir || max_concurrent_downloads <= 0)
        return NULL;

    DownloadResult *result = malloc(sizeof(DownloadResult));
    if (!result) return NULL;

    result->bytes_downloaded = 0; // This will need to be calculated dynamically in a real implementation
    result->thread_ids = malloc(url_count * sizeof(pthread_t));
    result->success = 1;

    if (!result->thread_ids) {
        free(result);
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int active_threads = 0;

    for (int i = 0; i < url_count; ++i) {
        char *output_file_path = malloc(strlen(output_dir) + strlen(urls[i]) + 2); // Extra space for slashes and null-terminator
        if (!output_file_path) {
            result->success = 0;
            break;
        }
        sprintf(output_file_path, "%s/%ld.html", output_dir, i);

        while (active_threads >= max_concurrent_downloads) {
            pthread_mutex_lock(&mutex);
            pthread_cond_wait(NULL, &mutex); // Wait for a thread to complete
            active_threads--;
            pthread_mutex_unlock(&mutex);
        }

        char **args = malloc(2 * sizeof(char *));
        args[0] = (char *)urls[i];
        args[1] = output_file_path;

        if (!args) {
            free(output_file_path);
            result->success = 0;
            break;
        }

        pthread_mutex_lock(&mutex);
        active_threads++;
        pthread_create(&result->thread_ids[i], NULL, download_url_thread, (void *)args);
        pthread_mutex_unlock(&mutex);

        free(args);
        free(output_file_path);
    }

    for (int i = 0; i < url_count; ++i) {
        pthread_join(result->thread_ids[i], NULL);
    }

    if (!result->success)
        free(result->thread_ids);

    return result;
}
```

**Key Aspects of the Code:**

- **Thread Management:** Uses a pool of threads to manage concurrency, ensuring no more than `max_concurrent_downloads` are active at once.

- **Error Handling:** Includes basic error handling for network failures and file operations.

- **Dynamic Memory Allocation:** Manages memory allocation dynamically for thread IDs and output paths. Free resources properly on failure conditions.

- **libcurl Integration:** Uses libcurl to perform the actual HTTP GET requests and handle data writing to files.

**Considerations:**

- This example assumes that the download URLs are valid, the output directory exists and is writable.

- The implementation of `bytes_downloaded` in a real scenario would require additional mechanisms to track bytes per thread.

- Proper error handling should be expanded to cover all possible failure points.

