```javascript
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const log4js = require('log4js');

// Promisify readFile for async usage
const readFileAsync = promisify(fs.readFile);

// Configure logging
log4js.configure({
  appenders: { out: { type: 'stdout' } },
  categories: { default: { appenders: ['out'], level: 'info' } }
});
const logger = log4js.getLogger();

class ModuleLoader {
  constructor(configPath, concurrencyLevel) {
    this.configPath = configPath;
    this.concurrencyLevel = concurrencyLevel || 2; // Default concurrency level
    this.loadedModules = new Set();
    this.loadingQueue = [];
    this.moduleDependencies = {};
    this.circularDependencyCheck = new Map();
  }

  async loadModules() {
    try {
      const configContent = await readFileAsync(this.configPath, 'utf8');
      const config = JSON.parse(configContent);

      for (const moduleInfo of config.modules) {
        this.loadModule(moduleInfo.name, moduleInfo.dependencies || []);
      }

      const loadingProcess = [];
      while (this.loadingQueue.length > 0 && 
             loadingProcess.length < this.concurrencyLevel) {
        const nextLoad = this.loadingQueue.shift();
        if (!nextLoad) continue;
        loadingProcess.push(nextLoad());
      }

      await Promise.all(loadingProcess);
    } catch (error) {
      logger.error(`Failed to load modules: ${error.message}`);
    }
  }

  async loadModule(moduleName, dependencies) {
    if (this.loadedModules.has(moduleName)) return;

    if (this.circularDependencyCheck.has(moduleName)) {
      logger.warn(`Circular dependency detected for module: ${moduleName}`);
      return;
    }

    this.circularDependencyCheck.set(moduleName, true);

    const resolveDependencies = async () => {
      for (const dep of dependencies) {
        await this.loadModule(dep, this.moduleDependencies[dep] || []);
      }
    };

    try {
      this.loadingQueue.push(async () => {
        logger.info(`Loading module: ${moduleName}`);

        if (!this.moduleDependencies[moduleName]) {
          const modulePath = path.resolve(__dirname, moduleName + '.js');
          await resolveDependencies();

          await import(modulePath).catch((err) => {
            logger.error(`Failed to load module "${moduleName}": ${err.message}`);
            throw err;
          });
        }

        this.loadedModules.add(moduleName);
        logger.info(`Successfully loaded module: ${moduleName}`);
      });
    } catch (error) {
      logger.error(`Error loading module ${moduleName}: ${error.message}`);
    }

    this.circularDependencyCheck.delete(moduleName);
  }
}

// Example usage
(async () => {
  const loader = new ModuleLoader('moduleConfig.json', 3);
  await loader.loadModules();
})();
```

