#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUFFER_SIZE 4096

// Define a structure for encryption context
typedef struct {
    EVP_CIPHER_CTX *ctx;
    FILE *log_file;
} EncryptionContext;

// Function prototypes
void log_message(const char *message, const char *file_path);
int get_cipher(int argc, char **argv);
unsigned long key_size_for_cipher(EVP_CIPHER *cipher);
void handle_errors(const char *error_msg);

EncryptionContext* encrypt_file(
    const char *input_file,
    const char *output_file,
    int (*progress_callback)(const char *status),
    void *callback_data) {

    EVP_CIPHER_CTX *ctx;
    unsigned char buffer[BUFFER_SIZE];
    unsigned char enc_buffer[BUFFER_SIZE + EVP_MAX_BLOCK_LENGTH];
    FILE *in_file = NULL, *out_file = NULL;
    size_t read_len, write_len;
    int cipher_type = get_cipher(0, NULL); // Assume command-line options are parsed elsewhere
    EVP_CIPHER *cipher = NULL;

    switch (cipher_type) {
        case 1: cipher = EVP_aes_256_cbc(); break;
        case 2: cipher = EVP_rsa_oaep(); break;
        default: handle_errors("Unsupported cipher type"); return NULL;
    }

    if (!cipher) handle_errors("Cipher initialization failed");

    EncryptionContext *enc_ctx = malloc(sizeof(EncryptionContext));
    if (!enc_ctx) handle_errors("Failed to allocate encryption context");

    enc_ctx->ctx = ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        free(enc_ctx);
        handle_errors("EVP_CIPHER_CTX allocation failed");
    }

    FILE *log_file = fopen("encryption_log.txt", "a");
    if (!log_file) {
        EVP_CIPHER_CTX_free(ctx);
        free(enc_ctx);
        handle_errors("Log file opening failed");
    }
    enc_ctx->log_file = log_file;

    // Key retrieval and setup
    unsigned char key[EVP_MAX_KEY_LENGTH];
    int key_len = key_size_for_cipher(cipher);

    if (RAND_bytes(key, key_len) != 1)
        handle_errors("Random bytes generation for key failed");

    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, key, NULL))
        handle_errors("Cipher initialization failed");

    in_file = fopen(input_file, "rb");
    out_file = fopen(output_file, "wb");

    if (!in_file || !out_file) {
        fclose(log_file);
        EVP_CIPHER_CTX_free(ctx);
        free(enc_ctx);
        handle_errors("File opening failed");
    }

    int progress = 0;
    while ((read_len = fread(buffer, 1, BUFFER_SIZE, in_file)) > 0) {

        if (!EVP_EncryptUpdate(ctx, enc_buffer, &write_len, buffer, read_len))
            handle_errors("Encryption update failed");

        fwrite(enc_buffer, 1, write_len, out_file);

        progress++;
        if (progress_callback && progress_callback("Progress")) {
            log_message("Progress callback interrupted the process", input_file);
            break;
        }
    }

    unsigned int final_len;
    if (!EVP_EncryptFinal_ex(ctx, enc_buffer, &final_len))
        handle_errors("Encryption finalization failed");

    fwrite(enc_buffer, 1, final_len, out_file);

    fclose(in_file);
    fclose(out_file);
    fclose(log_file);
    EVP_CIPHER_CTX_free(ctx);

    return enc_ctx;
}

void log_message(const char *message, const char *file_path) {
    fprintf(stderr, "Log: %s in file: %s\n", message, file_path);
}

int get_cipher(int argc, char **argv) {
    // Logic to parse command-line arguments for cipher selection
    return 1; // For simplicity, assume AES-256-CBC is selected
}

unsigned long key_size_for_cipher(EVP_CIPHER *cipher) {
    return EVP_CIPHER_key_length(cipher);
}

void handle_errors(const char *error_msg) {
    fprintf(stderr, "Error: %s\n", error_msg);
    exit(EXIT_FAILURE);
}
