from typing import List, Tuple
from bs4 import BeautifulSoup
import threading

class Cache:
    def __init__(self, max_size: int = 100):
        self.cache = {}
        self.lock = threading.Lock()
        self.max_size = max_size

    def get(self, key: Tuple[str, str, str]) -> List[BeautifulSoup]:
        with self.lock:
            return self.cache.get(key)

    def set(self, key: Tuple[str, str, str], value: List[BeautifulSoup]):
        with self.lock:
            if len(self.cache) >= self.max_size:
                # Simple eviction policy: remove the first item
                self.cache.pop(next(iter(self.cache)))
            self.cache[key] = value

def get_matching_elements(html_doc: str, tag: str, attribute: str, value: str) -> List[BeautifulSoup]:
    cache_key = (tag, attribute, value)

    # Check if result is in the cache
    cached_result = Cache.get(cache_key)
    if cached_result is not None:
        return cached_result

    try:
        soup = BeautifulSoup(html_doc, 'html.parser')

        # Find elements with the specified tag and attributes
        elements = soup.find_all(tag, attrs={attribute: value})

        # Store result in cache
        Cache.set(cache_key, elements)

        return elements

    except Exception as e:
        raise ValueError(f"An error occurred while processing the query. Details: {e}")

# Initialize a global cache instance
Cache = Cache()
