#include <pthread.h>
#include <sys/stat.h>
#include <unistd.h>

#define MAX_FILES 1000
#define MAX_LINE_LENGTH 1024

typedef struct {
    char filename[256];
} FileInfo;

// External logging service API functions (stubs)
void log_to_service(const char *message) {
    // Implement the actual logging to an external service here.
}

int report_error(const char *error_message) {
    log_to_service(error_message);
    return 0;
}

double parse_last_two_numbers(char *line, int *success) {
    double num1 = 0.0, num2 = 0.0;
    char *token, *endptr;

    // Tokenize the line and find the last two numbers
    token = strtok(line, " \t\n");
    while (token != NULL) {
        if (*success == 0) break; // Stop parsing after one failure
        num2 = strtod(token, &endptr);
        if (num1 == 0.0 && *endptr == '\0') { // First valid number found
            num1 = num2;
        } else if (num1 != 0.0 && *endptr == '\0') { // Second valid number found
            break;
        }
        token = strtok(NULL, " \t\n");
    }

    if (num1 == 0.0 || num2 == 0.0) {
        *success = 0; // Not enough numbers were parsed
        return -1.0;
    } else {
        return (num1 + num2) / 2.0;
    }
}

void* process_file(void *arg) {
    FileInfo *file_info = (FileInfo *)arg;
    FILE *file = fopen(file_info->filename, "r");
    if (!file) {
        report_error((char*)strcat(strdup("Error opening file: "), file_info->filename));
        pthread_exit(NULL);
    }

    char line[MAX_LINE_LENGTH];
    int success;
    double total_average = 0.0;
    int count = 0;

    while (fgets(line, sizeof(line), file)) {
        double average = parse_last_two_numbers(line, &success);
        if (success) {
            total_average += average;
            count++;
        }
    }

    if (count > 0) {
        printf("File: %s, Average of last two numbers: %.2f\n", file_info->filename, total_average / count);
    } else {
        report_error((char*)strcat(strdup("No valid numeric data found in file: "), file_info->filename));
    }

    fclose(file);
    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    DIR *dir = opendir(argv[1]);
    if (!dir) {
        perror("opendir");
        return EXIT_FAILURE;
    }

    FileInfo files[MAX_FILES];
    int file_count = 0;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL && file_count < MAX_FILES) {
        if (entry->d_type == DT_REG) { // Only regular files
            snprintf(files[file_count].filename, sizeof(files[file_count].filename), "%s/%s", argv[1], entry->d_name);
            file_count++;
        }
    }

    closedir(dir);

    pthread_t threads[MAX_FILES];
    for (int i = 0; i < file_count; ++i) {
        if (pthread_create(&threads[i], NULL, process_file, &files[i]) != 0) {
            perror("pthread_create");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < file_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}

