```csharp
using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileTransferService
{
    private static readonly HttpClient httpClient = new HttpClient();

    public async Task<UploadResult> UploadFileAsync(string filePath, byte[] encryptionKey, byte[] iv)
    {
        if (string.IsNullOrEmpty(filePath) || !File.Exists(filePath))
            return new UploadResult { Success = false, ErrorMessage = "Invalid file path." };

        try
        {
            string authToken = await GetAuthTokenAsync();
            if (string.IsNullOrEmpty(authToken))
                return new UploadResult { Success = false, ErrorMessage = "Failed to obtain authentication token." };

            using var aes = Aes.Create();
            aes.Key = encryptionKey;
            aes.IV = iv;

            byte[] fileData = File.ReadAllBytes(filePath);
            using var encryptor = aes.CreateEncryptor(aes.Key, aes.IV);

            await UploadFileAsync(fileData, authToken, encryptor);
        }
        catch (Exception ex)
        {
            return new UploadResult { Success = false, ErrorMessage = $"Upload failed: {ex.Message}" };
        }

        return new UploadResult { Success = true };
    }

    private async Task<string> GetAuthTokenAsync()
    {
        // Simulate obtaining a token from an external authentication service
        await Task.Delay(100); // Simulated network delay

        // Example: Return a hardcoded token or fetch one using httpClient.
        return "example-auth-token";
    }

    private async Task UploadFileAsync(byte[] fileData, string authToken, ICryptoTransform encryptor)
    {
        using var ms = new MemoryStream();
        using (var cryptoStream = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
        {
            await cryptoStream.WriteAsync(fileData, 0, fileData.Length);
        }

        byte[] encryptedData = ms.ToArray();

        httpClient.DefaultRequestHeaders.Authorization = 
            new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", authToken);

        var content = new ByteArrayContent(encryptedData);
        content.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/octet-stream");

        using (var response = await httpClient.PostAsync("https://cloudstorage.example.com/upload", content))
        {
            if (!response.IsSuccessStatusCode)
                throw new Exception($"Upload failed with status code: {response.StatusCode}");
        }
    }
}

public class UploadResult
{
    public bool Success { get; set; }
    public string ErrorMessage { get; set; }
}
