```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

public class FileChunkProcessor
{
    private readonly int _chunkSize;
    private readonly int _bufferSize;
    private Action<string> _loggingCallback;
    private ReaderWriterLockSlim _lock = new ReaderWriterLockSlim();

    public FileChunkProcessor(int chunkSize, int bufferSize)
    {
        if (chunkSize <= 0) throw new ArgumentException("Chunk size must be positive.", nameof(chunkSize));
        if (bufferSize <= 0) throw new ArgumentException("Buffer size must be positive.", nameof(bufferSize));

        _chunkSize = chunkSize;
        _bufferSize = bufferSize;
    }

    public void SetLoggingCallback(Action<string> callback)
    {
        _loggingCallback = callback ?? throw new ArgumentNullException(nameof(callback));
    }

    private void Log(string message)
    {
        _loggingCallback?.Invoke(message);
    }

    public string DecryptFileChunk(string filePath, byte[] key, byte[] iv)
    {
        if (string.IsNullOrWhiteSpace(filePath)) throw new ArgumentException("File path is not valid.", nameof(filePath));
        if (key == null || key.Length != 24) throw new ArgumentException("Key must be 192 bits (24 bytes).", nameof(key));
        if (iv == null || iv.Length != 8) throw new ArgumentException("IV must be 64 bits (8 bytes).", nameof(iv));

        using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
        {
            var decryptedData = new StringBuilder();

            _lock.EnterReadLock();
            try
            {
                byte[] buffer = new byte[_bufferSize];

                while (fileStream.Position < fileStream.Length)
                {
                    int bytesRead = Math.Min(fileStream.Read(buffer, 0, buffer.Length), _chunkSize);

                    using (var tripleDes = TripleDES.Create())
                    {
                        tripleDes.Key = key;
                        tripleDes.IV = iv;

                        var decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV);

                        using (var cryptoStream = new CryptoStream(new MemoryStream(buffer, 0, bytesRead), decryptor, CryptoStreamMode.Read))
                        {
                            using (var reader = new StreamReader(cryptoStream, Encoding.UTF8))
                            {
                                decryptedData.Append(reader.ReadToEnd());
                            }
                        }
                    }

                    Log($"Processed chunk at position {fileStream.Position}");
                }
            }
            catch (Exception ex)
            {
                Log($"Error processing file: {ex.Message}");
                throw;
            }
            finally
            {
                _lock.ExitReadLock();
            }

            return decryptedData.ToString();
        }
    }

    // Additional methods for parallel processing, error handling and validation can be added here.
}
