            # Assume User is a model class for interacting with the user table in the database
            if 'id' not in account_data or account_data['id'] is None:
                new_user = User.create(**account_data)
            else:
                User.update(**account_data).where(User.id == account_data['id']).execute()

            # Optionally send a confirmation email through an external API
            self.send_confirmation_email(account_data)

    def delete_account(self, user_id):
        with self.db.atomic():
            User.delete().where(User.id == user_id).execute()

    def send_confirmation_email(self, account_data):
        # Dummy function for sending confirmation emails
        pass

    def handle_request(self, request):
        try:
            self.validate_request(request)

            if 'sub_action' in request and request['sub_action'].lower() == 'delete':
                if 'id' not in request or request['id'] is None:
                    return json.dumps({'status': 'error', 'message': 'Missing ID for deletion'})

                self.delete_account(request['id'])
                message = f"User account with ID {request['id']} deleted successfully."
            else:
                # Prepare user data
                user_data = {
                    'username': request['username'],
                    'email': request['email'],
                    'password': request.get('password'),
                    'token': request.get('token')
                }

                if 'id' in request and request['id'] is not None:
                    user_data['id'] = request['id']

                self.save_account(user_data)
                message = "User account created/updated successfully."

            return json.dumps({'status': 'success', 'message': message})

        except PermissionError as e:
            return json.dumps({'status': 'error', 'message': str(e)})
        except ValueError as e:
            return json.dumps({'status': 'error', 'message': str(e)})
        except Exception as e:
            return json.dumps({'status': 'error', 'message': "An unexpected error occurred."})

