```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class SecureCipherService
{
    private static readonly HttpClient httpClient = new HttpClient();
    private readonly string tokenUrl;
    private ConcurrentDictionary<string, TokenData> tokenCache = new ConcurrentDictionary<string, TokenData>();

    public SecureCipherService(string tokenUrl)
    {
        this.tokenUrl = tokenUrl;
    }

    public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext, byte[] key, byte[] iv, int offset = 0)
    {
        if (key == null || key.Length != 32) throw new ArgumentException("Key must be a valid AES-256 key.");
        if (iv == null || iv.Length != 16) throw new ArgumentException("IV must be 128 bits long.");

        var tokenData = await GetValidTokenAsync();

        try
        {
            using (var aes = Aes.Create())
            {
                aes.Key = key;
                aes.IV = iv;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                int length = ciphertext.Length - offset;
                using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
                using (var ms = new MemoryStream(ciphertext, offset, length, false))
                using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    var plaintext = new byte[length];
                    int bytesRead = await cs.ReadAsync(plaintext, 0, length);
                    Array.Resize(ref plaintext, bytesRead); // Resize to actual decrypted data size
                    return plaintext;
                }
            }
        }
        catch (CryptographicException ex)
        {
            throw new InvalidOperationException("Decryption failed due to an invalid key or IV.", ex);
        }
    }

    private async Task<TokenData> GetValidTokenAsync()
    {
        var cacheKey = "token";
        if (!tokenCache.TryGetValue(cacheKey, out TokenData tokenData) || tokenData.IsExpired())
        {
            lock (this)
            {
                // Double-check locking
                if (!tokenCache.TryGetValue(cacheKey, out tokenData) || tokenData.IsExpired())
                {
                    try
                    {
                        var response = await httpClient.GetAsync(tokenUrl);
                        response.EnsureSuccessStatusCode();
                        var jsonContent = await response.Content.ReadAsStringAsync();

                        // Assume the JSON content contains access_token and expires_in fields
                        var tokenInfo = System.Text.Json.JsonSerializer.Deserialize<TokenResponse>(jsonContent);

                        if (tokenInfo == null)
                            throw new Exception("Invalid token response.");

                        tokenData = new TokenData(tokenInfo.AccessToken, DateTimeOffset.UtcNow.AddSeconds(tokenInfo.ExpiresIn));

                        // Update cache
                        tokenCache[cacheKey] = tokenData;
                    }
                    catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.Forbidden)
                    {
                        throw new UnauthorizedAccessException("Failed to retrieve or refresh the authentication token.", ex);
                    }
                }
            }
        }

        return tokenData;
    }

    private class TokenData
    {
        public string AccessToken { get; }
        public DateTimeOffset ExpiryTime { get; }

        public TokenData(string accessToken, DateTimeOffset expiryTime)
        {
            AccessToken = accessToken ?? throw new ArgumentNullException(nameof(accessToken));
            ExpiryTime = expiryTime;
        }

        public bool IsExpired() => DateTimeOffset.UtcNow >= ExpiryTime;
    }

    private class TokenResponse
    {
        public string AccessToken { get; set; }
        public int ExpiresIn { get; set; }
    }
}
``` 

