from flask import Flask, redirect, url_for, render_template_string, request, flash
from flask_sqlalchemy import SQLAlchemy
from flask_login import LoginManager, UserMixin, current_user, login_user, logout_user, login_required
from flask_principal import Principal, Permission, RoleNeed, Identity, identity_changed, AnonymousIdentity, identity_loaded, UserNeed
import requests

app = Flask(__name__)
app.config['SECRET_KEY'] = 'supersecretkey'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
db = SQLAlchemy(app)

login_manager = LoginManager(app)
login_manager.login_view = 'login'
principals = Principal(app)

# Define roles and permissions
admin_permission = Permission(RoleNeed('admin'))
user_permission = Permission(RoleNeed('user'))

# Models for users and roles
roles_users = db.Table('roles_users',
    db.Column('user_id', db.Integer(), db.ForeignKey('user.id')),
    db.Column('role_id', db.Integer(), db.ForeignKey('role.id')))

class Role(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), unique=True)

class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(150), unique=True)
    roles = db.relationship('Role', secondary=roles_users, backref=db.backref('users', lazy='dynamic'))

# Initialize database
with app.app_context():
    db.create_all()

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

@identity_loaded.connect_via(app)
def on_identity_loaded(sender, identity):
    if hasattr(current_user, 'id'):
        identity.provides.add(UserNeed(current_user.id))
        for role in current_user.roles:
            identity.provides.add(RoleNeed(role.name))

def validate_with_external_provider():
    # Simulate external provider validation
    response = requests.post('https://external-identity-provider.com/token', data=request.form)
    return response.ok

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        if validate_with_external_provider():
            user = User.query.filter_by(username=request.form['username']).first()
            if not user:
                user = User(username=request.form['username'])
                db.session.add(user)
                # Assign default role
                user_role = Role.query.filter_by(name='user').first()
                if not user_role:
                    user_role = Role(name='user')
                    db.session.add(user_role)
                user.roles.append(user_role)
                db.session.commit()

            login_user(user)
            identity_changed.send(app, identity=Identity(user.id))
            return redirect(url_for('index'))
        else:
            flash("Invalid credentials with external provider.")
    return render_template_string('<form method="post"><input name="username"/><button type="submit">Login</button></form>')

@app.route('/logout')
@login_required
def logout():
    identity_changed.send(app, identity=AnonymousIdentity())
    logout_user()
    return redirect(url_for('login'))

@app.route('/')
@login_required
def index():
    return 'Welcome to the dashboard!'

@app.route('/admin')
@admin_permission.require(http_exception=403)
def admin_dashboard():
    return 'Admin Dashboard - Only for admins.'

@app.route('/user')
@user_permission.require(http_exception=403)
def user_dashboard():
    return 'User Dashboard - Only for users.'

if __name__ == '__main__':
    app.run(debug=True)
```

