Below is a C program that fulfills the given requirements using POSIX threads for concurrency and message queues for inter-process communication:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <dirent.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>
#include <ctype.h>

#define MAX_THREADS 1000
#define QUEUE_SIZE 100

typedef struct {
    char *name;
} file_info_t;

typedef struct {
    file_info_t files[QUEUE_SIZE];
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} message_queue_t;

typedef struct {
    message_queue_t queue;
    pthread_t threads[MAX_THREADS];
    int max_threads;
} worker_pool_t;

worker_pool_t pool = {0};

void init_worker_pool(int max_threads) {
    pthread_mutex_init(&pool.queue.mutex, NULL);
    pthread_cond_init(&pool.queue.cond, NULL);
    pool.max_threads = max_threads;
}

void enqueue_file(message_queue_t *queue, const char *filename) {
    pthread_mutex_lock(&queue->mutex);

    while (queue->count == QUEUE_SIZE) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }

    queue->files[queue->count].name = strdup(filename);
    queue->count++;

    pthread_cond_signal(&queue->mutex);
    pthread_mutex_unlock(&queue->mutex);
}

file_info_t dequeue_file(message_queue_t *queue) {
    file_info_t file;
    memset(&file, 0, sizeof(file_info_t));

    pthread_mutex_lock(&queue->mutex);

    while (queue->count == 0) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }

    file = queue->files[0];
    memmove(queue->files, queue->files + 1, sizeof(file_info_t) * --queue->count);

    pthread_mutex_unlock(&queue->mutex);
    return file;
}

void process_file(const char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return;
    }

    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("fstat");
        close(fd);
        return;
    }

    char *data = mmap(NULL, sb.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (data == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return;
    }

    double total = 0.0, count = 0;
    char *line_start = data;
    char *ptr = line_start;

    while ((ptr = strchr(ptr, '\n')) != NULL) {
        *ptr = '\0';
        int num_fields = 0;
        double values[2] = {0};

        for (char *token = strtok(line_start, " "); token; token = strtok(NULL, " ")) {
            if (isdigit(token[0]) || (token[0] == '-' && isdigit(token[1]))) {
                values[num_fields++] = atof(token);
                if (num_fields > 1) break;
            }
        }

        if (num_fields >= 2) {
            total += (values[0] + values[1]) / 2.0;
            count++;
        }

        line_start = ptr + 1;
    }

    munmap(data, sb.st_size);
    close(fd);

    double average = count > 0 ? total / count : 0;
    printf("File: %s, Average of last two numbers: %.2f\n", filename, average);
}

void *worker_thread(void *arg) {
    while (1) {
        file_info_t file = dequeue_file(&pool.queue);
        if (!file.name) break; // No more files to process

        process_file(file.name);
        free(file.name);
    }

    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <directory> <max_threads>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *directory = argv[1];
    int max_threads = atoi(argv[2]);

    init_worker_pool(max_threads);

    for (int i = 0; i < pool.max_threads; ++i) {
        pthread_create(&pool.threads[i], NULL, worker_thread, NULL);
    }

    DIR *dir = opendir(directory);
    if (!dir) {
        perror("opendir");
        return EXIT_FAILURE;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            char path[PATH_MAX];
            snprintf(path, sizeof(path), "%s/%s", directory, entry->d_name);
            enqueue_file(&pool.queue, path);
        }
    }

    closedir(dir);

    // Signal threads to exit
    for (int i = 0; i < pool.max_threads; ++i) {
        enqueue_file(&pool.queue, NULL);
    }

    for (int i = 0; i < pool.max_threads; ++i) {
        pthread_join(pool.threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
```

### Key Features:

1. **Concurrency**: Uses POSIX threads to process files concurrently.
2. **Message Queue**: Implements a simple message queue for file processing tasks.
3. **Memory Mapping**: Utilizes `mmap` for efficient file reading.
4. **Graceful Error Handling**: Handles errors such as file opening, mapping, and statistical calculations.
5. **Modular Design**: Separates functionality into functions like `enqueue_file`, `dequeue_file`, `process_file`, and `worker_thread`.
6. **Command-Line Interface**: Takes directory and max threads as command-line arguments.

