    [HttpPost("UpdateElement")]
    [Authorize(Roles = "Editor,Admin")]
    public async Task<IActionResult> UpdateElement([FromBody] ElementUpdateRequest request)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        if (!_documentValidator.ValidateHtml(request.HtmlContent))
        {
            return BadRequest("Invalid HTML content.");
        }

        try
        {
            await _contentService.UpdateElementAsync(request.PageSectionId, request.ElementId, request.HtmlContent);

            await _auditService.LogChangeAsync(request.PageSectionId, request.ElementId, request.User.Identity.Name);

            return Ok();
        }
        catch (ConcurrencyException)
        {
            return StatusCode(409, "Conflict detected. Please try again.");
        }
        catch (TransientDatabaseOperationException ex)
        {
            // Retry logic can be implemented here
            await Task.Delay(1000);  // Example delay for retry
            return StatusCode(500, "Temporary issue with the database. Try again later.");
        }
        catch (Exception ex)
        {
