```python
# WebContentProcessor.py

from bs4 import BeautifulSoup
import threading
from collections import OrderedDict
import requests
import logging
import unittest


class LRUCache:
    def __init__(self, capacity=100):
        self.cache = {}
        self.order = OrderedDict()
        self.lock = threading.Lock()
        self.capacity = capacity

    def get(self, key):
        with self.lock:
            if key in self.cache:
                self.order.move_to_end(key)
                return self.cache[key]
            return None

    def put(self, key, value):
        with self.lock:
            if key in self.cache:
                self.order.move_to_end(key)
            else:
                if len(self.cache) >= self.capacity:
                    oldest = next(iter(self.order))
                    del self.cache[oldest]
                    del self.order[oldest]
                self.cache[key] = value
            self.order[key] = None


class WebContentProcessor:
    def __init__(self):
        self.cache = LRUCache()
        logging.basicConfig(level=logging.INFO)

    def _fetch_data(self, url):
        try:
            response = requests.get(url)
            response.raise_for_status()
            return response.text
        except requests.RequestException as e:
            logging.error(f"Failed to fetch data: {e}")
            raise

    def extract_relevant_data(self, html_stream, tag, attribute=None, value=None):
        key = (tag, attribute, value)
        cached_result = self.cache.get(key)

        if cached_result is not None:
            return cached_result

        try:
            soup = BeautifulSoup(html_stream, 'html.parser')
            elements = soup.find_all(tag, {attribute: value} if attribute else {})

            # Extract and process relevant data from elements
            extracted_data = [element.text.strip() for element in elements]
            self.cache.put(key, extracted_data)

            return extracted_data

        except Exception as e:
            logging.error(f"Error extracting data: {e}")
            return []


# Unit tests
class TestWebContentProcessor(unittest.TestCase):
    def setUp(self):
        self.processor = WebContentProcessor()

    def test_extract_relevant_data_valid_input(self):
        html_content = "<html><body><p class='test'>Test</p><div>Ignore</div></body></html>"
        result = self.processor.extract_relevant_data(html_content, 'p', 'class', 'test')
        self.assertEqual(result, ['Test'])

    def test_extract_relevant_data_invalid_tag(self):
        html_content = "<html><body><p class='test'>Test</p><div>Ignore</div></body></html>"
        result = self.processor.extract_relevant_data(html_content, 'span', 'class', 'test')
        self.assertEqual(result, [])

    def test_cache_mechanism(self):
        html_content = "<html><body><p class='test'>Test</p></body></html>"
        # First extraction should populate cache
        result1 = self.processor.extract_relevant_data(html_content, 'p', 'class', 'test')

        # Second extraction should hit the cache
        result2 = self.processor.extract_relevant_data(html_content, 'p', 'class', 'test')

        self.assertEqual(result1, result2)

    def test_concurrent_access(self):
        html_content = "<html><body><p class='test'>Test</p></body></html>"
        results = []

        def fetch():
            result = self.processor.extract_relevant_data(html_content, 'p', 'class', 'test')
            results.append(result)

        threads = [threading.Thread(target=fetch) for _ in range(10)]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()

        # All should be the same due to caching
        self.assertTrue(all(result == ['Test'] for result in results))


if __name__ == '__main__':
    unittest.main()
```

