import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Random;

public class DeserializationHelper {

    public static String[] deserializeAndProcess(byte[] data, int randomStringLength) {
        Object deserializedObject = null;

        try (ByteArrayInputStream byteStream = new ByteArrayInputStream(data);
             ObjectInputStream objectStream = new ObjectInputStream(byteStream)) {

            deserializedObject = objectStream.readObject();

        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize the object: " + e.getMessage(), e);
        }

        if (deserializedObject == null || !(deserializedObject instanceof String)) {
            throw new RuntimeException("Deserialized object is not a valid string.");
        }

        String randomString = generateRandomString(randomStringLength, "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789");
        String hashedPassword = hashPassword("your-password");

        return new String[] { (String) deserializedObject, randomString, hashedPassword };
    }

    private static String generateRandomString(int length, String characterSet) {
        Random random = new Random();
        StringBuilder sb = new StringBuilder(length);

        for (int i = 0; i < length; i++) {
            int index = random.nextInt(characterSet.length());
            sb.append(characterSet.charAt(index));
        }

        return sb.toString();
    }

    private static String hashPassword(String password) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hashedBytes = md.digest(password.getBytes());

            StringBuilder sb = new StringBuilder();
            for (byte b : hashedBytes) {
                sb.append(String.format("%02x", b));
            }

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to hash the password: " + e.getMessage(), e);
        }
    }

    public static void main(String[] args) {
        // Example usage
        byte[] serializedData = {/* Your serialized data here */};

        try {
            String[] result = deserializeAndProcess(serializedData, 10);
            System.out.println("Deserialized Object: " + result[0]);
            System.out.println("Random String: " + result[1]);
            System.out.println("Hashed Password: " + result[2]);
        } catch (RuntimeException e) {
            e.printStackTrace();
        }
    }
}
