```rust
use std::fs;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use rayon::prelude::*;
use rustc_driver::{catch_with_exit_code, RunCompiler};
use rustc_session::{early_error, config};
use log::{info, error, debug};
use serde_json::json;
use lazy_static::lazy_static;
use sync_lazy::SyncLazy;

// Assuming `get_resident_set_size` is defined elsewhere
extern "C" fn get_resident_set_size() -> usize {
    // Mock implementation
    1024 * 1024
}

lazy_static! {
    static ref LOG_HOOK: SyncLazy<()> = {
        install_log_hook();
        ()
    };
}

fn install_log_hook() {
    // Implementation for installing a custom logging hook
    info!("Log hook installed.");
}

fn compile_file(path: PathBuf) -> Result<(i32, u64, usize), String> {
    let start_time = Instant::now();
    let initial_rss = get_resident_set_size();

    let exit_code = catch_with_exit_code(|| {
        RunCompiler::new(&[path.to_str().unwrap()], &config::Options::default())
            .run(|args| args)
    });

    let elapsed_time = start_time.elapsed().as_millis();
    let final_rss = get_resident_set_size();

    match exit_code {
        Ok(0) => Ok((exit_code.unwrap(), elapsed_time, final_rss - initial_rss)),
        Err(e) => {
            early_error(&format!("Compilation error: {:?}", e));
            Err(format!("Failed to compile {}: {}", path.display(), e))
        }
    }
}

fn compile_files(paths: Vec<PathBuf>) -> String {
    let results = Arc::new(Mutex::new(Vec::new()));

    paths.par_iter().for_each(|path| {
        match compile_file(path.clone()) {
            Ok(result) => {
                let mut results_lock = results.lock().unwrap();
                results_lock.push((path.to_path_buf(), result));
            }
            Err(e) => error!("Error compiling file: {}", e),
        }
    });

    let results_lock = results.lock().unwrap();
    serde_json::to_string_pretty(&*results_lock).unwrap_or_else(|_| json!({ "error": "JSON serialization failed" }).to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_compile_files() {
        let paths = vec![PathBuf::from("file1.rs"), PathBuf::from("file2.rs")];
        let result = compile_files(paths);
        debug!("Test Result: {}", result);
        // Add more assertions as needed
    }
}

fn main() {
    env_logger::init();
    let paths = vec![
        "path/to/file1.rs".into(),
        "path/to/file2.rs".into(),
        // Add more file paths as needed
    ];

    let output = compile_files(paths);
    println!("{}", output);
}
```

### Explanation:

- **Parallelization**: The `rayon` crate is used to parallelize the compilation process with `par_iter()`.
- **Error Handling**: Errors during compilation are caught using `rustc_driver::catch_with_exit_code`, and errors are logged.
- **Resource Measurement**: Compilation time and memory usage (resident set size) are measured before and after each file's compilation.
- **Logging**: The `log` crate is used to log detailed information about the process.
- **JSON Output**: Results are serialized into JSON format using `serde_json`.
- **Error Resilience**: If a file fails to compile, it logs an error but continues with other files.

