```javascript
function copyBufferedData(chunks, byteCount) {
    const newBuffer = Buffer.allocUnsafe(byteCount);
    let offset = 0;

    for (const chunk of chunks) {
        const bytesToCopy = Math.min(chunk.length - offset, byteCount - offset);
        if (bytesToCopy <= 0) break;

        chunk.copy(newBuffer, offset, offset, offset + bytesToCopy);
        offset += bytesToCopy;
    }

    return newBuffer.slice(0, offset); // Return only the copied part
}
