<?php

// Configuration constants (use environment variables or config files)
define('DATABASE_HOST', 'localhost');
define('DATABASE_NAME', 'your_database_name');
define('DATABASE_USER', 'your_database_user');
define('DATABASE_PASS', 'your_database_password');

function updateClinicStatus($clinicId, $newStatus, $clientIp) {
    if (!validateClinicId($clinicId)) {
        logError("Invalid clinic ID: $clinicId");
        return ['success' => false, 'message' => "Invalid clinic ID", 'updatedCount' => 0];
    }

    try {
        // Establish a database connection
        $pdo = new PDO("mysql:host=" . DATABASE_HOST . ";dbname=" . DATABASE_NAME, DATABASE_USER, DATABASE_PASS);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Begin transaction
        $pdo->beginTransaction();

        $stmt = $pdo->prepare("
            UPDATE clinics 
            SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() 
            WHERE id = :clinicId
        ");

        $stmt->bindParam(':status', $newStatus);
        $stmt->bindParam(':ip', $clientIp);
        $stmt->bindParam(':clinicId', $clinicId);

        if ($stmt->execute()) {
            // Commit transaction
            $pdo->commit();

            logChange($clinicId, $newStatus, $clientIp); // Log change externally

            return ['success' => true, 'message' => "Clinic status updated successfully", 'updatedCount' => 1];
        } else {
            throw new Exception("Failed to execute update statement");
        }
    } catch (Exception $e) {
        if ($pdo->inTransaction()) {
            // Rollback transaction in case of error
            $pdo->rollBack();
        }

        logError($e->getMessage());
        return ['success' => false, 'message' => "Update failed: " . $e->getMessage(), 'updatedCount' => 0];
    } finally {
        // Ensure the database connection is closed to free resources
        $pdo = null;
    }
}

function validateClinicId($clinicId) {
    return filter_var($clinicId, FILTER_VALIDATE_INT) !== false && $clinicId > 0;
}

function logError($message) {
    // Integrate with an external logging service
    file_put_contents('error_log.txt', date('[Y-m-d H:i:s] ') . $message . PHP_EOL, FILE_APPEND);
}

function logChange($clinicId, $newStatus, $clientIp) {
