```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;

public class DatabaseService
{
    private readonly IMemoryCache _cache;
    private readonly ILogger<DatabaseService> _logger; // Assuming an external logging system is in place

    public DatabaseService(IMemoryCache cache, ILogger<DatabaseService> logger)
    {
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<List<T>> ExecuteStoredProcedureAsync<T>(
        SqlConnection connection,
        string storedProcedureName,
        List<SqlParameter> inputParameters,
        TimeSpan? cacheExpiration = null) where T : class, new()
    {
        if (connection == null) throw new ArgumentNullException(nameof(connection));
        if (string.IsNullOrWhiteSpace(storedProcedureName)) throw new ArgumentException("StoredProcedure name cannot be null or whitespace.", nameof(storedProcedureName));
        if (inputParameters == null || inputParameters.Count == 0) throw new ArgumentException("Input parameters cannot be null or empty.", nameof(inputParameters));

        // Generate a cache key based on stored procedure and its parameters
        var cacheKey = $"{storedProcedureName}:{string.Join(":", inputParameters)}";

        // Try to get the data from cache
        if (_cache.TryGetValue(cacheKey, out List<T> cachedResult))
        {
            _logger.LogInformation($"Cache hit for {cacheKey}");
            return cachedResult;
        }

        try
        {
            using var command = new SqlCommand(storedProcedureName, connection) { CommandType = CommandType.StoredProcedure };

            // Add input parameters to the command
            foreach (var parameter in inputParameters)
            {
                if (parameter == null || string.IsNullOrWhiteSpace(parameter.ParameterName))
                    throw new ArgumentException("Parameter cannot be null and must have a valid name.", nameof(inputParameters));

                command.Parameters.Add(parameter);
            }

            await connection.OpenAsync();

            using var reader = await command.ExecuteReaderAsync();

            var results = MapResultSetToObjects<T>(reader);

            // Cache the result with an optional expiration time
            cacheExpiration ??= TimeSpan.FromMinutes(10); // Default cache duration
            _cache.Set(cacheKey, results, cacheExpiration.Value);

            _logger.LogInformation($"Stored procedure {storedProcedureName} executed successfully.");
            return results;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Error executing stored procedure: {storedProcedureName}");
            throw; // Re-throw exception to allow calling code to handle it
        }
    }

    private List<T> MapResultSetToObjects<T>(SqlDataReader reader) where T : class, new()
    {
        var results = new List<T>();

        while (reader.Read())
        {
            var obj = new T();
            foreach (var property in typeof(T).GetProperties())
            {
                if (!reader.HasColumn(property.Name)) continue;

                try
                {
                    var value = reader[property.Name];
                    if (value != DBNull.Value)
                        property.SetValue(obj, Convert.ChangeType(value, property.PropertyType));
                }
                catch (Exception ex)
                {
                    _logger.LogWarning($"Failed to map column '{property.Name}' for type {typeof(T).Name}: {ex.Message}");
                }
            }

            results.Add(obj);
        }

        return results;
    }
}
```

**Notes:**
- This code assumes the presence of an `ILogger` implementation from a logging framework, such as Microsoft.Extensions.Logging.
- The `MapResultSetToObjects<T>` method uses reflection to map columns from the SQL result set to properties of the generic type `T`.
- Cache management is handled with Microsoft.Extensions.Caching.Memory's `IMemoryCache`.
- Parameter validation and exception handling are included to ensure safe and predictable execution.

