// Global mutex for thread safety
pthread_mutex_t lock;

// Progress callback function prototype
typedef void (*progress_callback)(double percentage);

// Function to log messages
void log_message(const char *message) {
    pthread_mutex_lock(&lock);
    FILE *log_file = fopen("encryption_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
    pthread_mutex_unlock(&lock);
}

// Function to retrieve keys from the key management service
int get_key_from_kms(const char *key_id, unsigned char **key, int *key_len) {
