    }
    return 0;
}

// Function to validate file path and command line options
int validate_inputs(const char *file_path, const char *cipher_name) {
    if (!file_path || !cipher_name) {
        log_message("Invalid input parameters.");
        return 0;
    }
    // Add more validation as needed
    return 1;
}

// Function to encrypt file
EVP_CIPHER_CTX* encrypt_file(const char *input_file, const char *output_file,
                            const char *cipher_name, progress_callback progress_cb) {

    if (!validate_inputs(input_file, cipher_name)) {
        log_message("Input validation failed.");
        return NULL;
    }

    FILE *in = fopen(input_file, "rb");
    FILE *out = fopen(output_file, "wb");
    if (!in || !out) {
        log_message("File opening failed.");
        if (in) fclose(in);
        if (out) fclose(out);
        return NULL;
    }

    unsigned char key[EVP_MAX_KEY_LENGTH];
    int key_len;

    if (!get_key_from_kms(cipher_name, &key, &key_len)) {
        log_message("Key retrieval failed.");
        fclose(in);
        fclose(out);
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        log_message("Failed to create cipher context.");
        fclose(in);
        fclose(out);
        free(key);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_get_cipherbyname(cipher_name), NULL, key, NULL)) {
        log_message("Cipher initialization failed.");
        goto cleanup;
    }

    unsigned char in_buf[4096];
    unsigned char out_buf[EVP_MAX_BLOCK_LENGTH];
    int in_len, out_len;

    while ((in_len = fread(in_buf, 1, sizeof(in_buf), in)) > 0) {
        if (1 != EVP_EncryptUpdate(ctx, out_buf, &out_len, in_buf, in_len)) {
            log_message("Encryption update failed.");
            goto cleanup;
        }
        fwrite(out_buf, 1, out_len, out);

        // Call progress callback
        if (progress_cb) {
            double percentage = ((double)fread(in_buf, 1, sizeof(in_buf), in) / 
                                fseek(in, 0, SEEK_END)) * 100.0;
            fseek(in, 0, SEEK_SET);
            progress_cb(percentage);
        }
    }

    if (1 != EVP_EncryptFinal_ex(ctx, out_buf, &out_len)) {
        log_message("Encryption finalization failed.");
        goto cleanup;
    }
    fwrite(out_buf, 1, out_len, out);

cleanup:
    free(key);
    fclose(in);
    fclose(out);
    EVP_CIPHER_CTX_free(ctx);
    return ctx;  // Return cipher context
}

// Example usage of progress callback
void example_progress_callback(double percentage) {
    printf("Encryption progress: %.2f%%\n", percentage);
}

int main(int argc, char *argv[]) {
    pthread_mutex_init(&lock, NULL);

    if (argc < 4) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <cipher_name>\n", argv[0]);
        return EXIT_FAILURE;
    }

    EVP_CIPHER_CTX *ctx = encrypt_file(argv[1], argv[2], argv[3], example_progress_callback);
    if (!ctx) {
        log_message("Encryption failed.");
    } else {
        printf("Encryption successful.\n");
    }

    pthread_mutex_destroy(&lock);
    return EXIT_SUCCESS;
}
