```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileHasher
{
    private const int BufferSize = 8192; // 8KB buffer size

    public async Task<string> ComputeSha256Async(string filePath, bool computeInChunks = false)
    {
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("File path cannot be null or empty.", nameof(filePath));

        try
        {
            using var sha256 = SHA256.Create();
            long fileSize = new FileInfo(filePath).Length;
            long processedBytes = 0;

            await using var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, BufferSize, useAsync: true);

            if (computeInChunks)
            {
                return await ComputeHashInChunksAsync(sha256, fileStream, fileSize);
            }
            else
            {
                return await ComputeHashAllAtOnceAsync(sha256, fileStream);
            }
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }
    }

    private async Task<string> ComputeHashInChunksAsync(SHA256 sha256, FileStream fileStream, long fileSize)
    {
        byte[] buffer = new byte[BufferSize];
        int bytesRead;

        var stopwatch = System.Diagnostics.Stopwatch.StartNew();

        try
        {
            while ((bytesRead = await fileStream.ReadAsync(buffer, 0, BufferSize)) > 0)
            {
                sha256.TransformBlock(buffer, 0, bytesRead, null, 0);
            }

            byte[] hashBytes = sha256.Hash;
            return Convert.ToBase64String(hashBytes);

        } finally
        {
            stopwatch.Stop();
            LogHashComputationTime(fileSize, stopwatch.ElapsedMilliseconds);
            sha256.TransformFinalBlock(Array.Empty<byte>(), 0, 0); // Finalize hash computation
        }
    }

    private async Task<string> ComputeHashAllAtOnceAsync(SHA256 sha256, FileStream fileStream)
    {
        byte[] allBytes = new byte[fileStream.Length];

        var stopwatch = System.Diagnostics.Stopwatch.StartNew();

        try
        {
            await fileStream.ReadAsync(allBytes, 0, allBytes.Length);
            byte[] hashBytes = sha256.ComputeHash(allBytes);
            return Convert.ToBase64String(hashBytes);

        } finally
        {
            stopwatch.Stop();
            LogHashComputationTime(fileStream.Length, stopwatch.ElapsedMilliseconds);
        }
    }

    private void LogError(Exception ex)
    {
        // Integrate with external logging service
        Console.Error.WriteLine($"Error: {ex.Message}");
    }

    private void LogHashComputationTime(long fileSize, long timeTakenMs)
    {
        // Integrate with external logging service
        Console.WriteLine($"Computed SHA-256 for a file of size {fileSize} bytes in {timeTakenMs} ms.");
    }
}
```

This class uses asynchronous methods to efficiently compute the SHA-256 hash for large files. It provides options to process the entire file at once or in chunks, logging both computation time and errors encountered during the hashing process.

