#include <iostream>
#include <string>
#include <forward_list>
#include <fstream>
#include <filesystem>
#include <mutex>
#include <vector>
#include <cassert>

namespace fs = std::filesystem;

// Mutex for thread safety
std::mutex mtx;

// Logging function
void logOperation(const std::string& message) {
    std::lock_guard<std::mutex> lock(mtx);
    std::cout << "Log: " << message << std::endl;
}

bool caseInsensitiveCompare(const std::string &a, const std::string &b) {
    if (a.size() != b.size()) return false;
    for (size_t i = 0; i < a.size(); ++i)
        if (tolower(a[i]) != tolower(b[i])) return false;
    return true;
}

std::string readFileContents(const std::string &directoryPath, const std::string &fileName) {
    try {
        fs::path filePath = directoryPath + "/" + fileName;
        if (!fs::exists(filePath)) throw std::runtime_error("File does not exist");

        std::ifstream fileStream(filePath);
        if (!fileStream.is_open()) throw std::runtime_error("Unable to open file");

        return {std::istreambuf_iterator<char>(fileStream), std::istreambuf_iterator<char>()};
    } catch (const std::exception &e) {
        logOperation("Error reading file: " + std::string(e.what()));
        throw;
    }
}

void insertAfterTarget(std::forward_list<std::string> &strList, const std::string &target, const std::string &replacement) {
    for (auto it = strList.begin(); it != strList.end(); ++it) {
        if (caseInsensitiveCompare(*it, target)) {
            logOperation("Inserting after found: " + *it);
            auto nextIt = std::next(it);
            strList.insert_after(it, replacement);
            return;
        }
    }

    logOperation("Target not found. Inserting at the end.");
    strList.push_front(replacement); // Since it's a forward_list, push_front effectively adds to the end.
}

void processForwardList(std::forward_list<std::string> &strList, const std::string &target, 
                        const std::string &replacement, const std::string &directoryPath) {
    try {
        if (strList.empty()) throw std::invalid_argument("The forward list is empty");

        insertAfterTarget(strList, target, replacement);

        // Assuming a file named "example.txt" exists in the directory
        std::string fileContents = readFileContents(directoryPath, "example.txt");
        std::cout << "File Contents: \n" << fileContents << std::endl;
    } catch (const std::exception &e) {
        logOperation("Error processing forward list: " + std::string(e.what()));
    }
}

// Unit tests
void runTests() {
    {
        std::forward_list<std::string> strList = {"apple", "banana", "cherry"};
        processForwardList(strList, "banana", "date", "./");

        auto it = strList.begin();
        assert(*it == "apple"); ++it;
        assert(*it == "banana"); ++it;
        assert(*it == "date"); ++it;
        assert(*it == "cherry");

        std::cout << "Test 1 passed: Insertion after target." << std::endl;
    }

    {
        std::forward_list<std::string> strList = {"apple", "banana", "cherry"};
        processForwardList(strList, "grape", "date", "./");

        auto it = strList.begin();
        assert(*it == "apple"); ++it;
        assert(*it == "banana"); ++it;
        assert(*it == "cherry"); ++it;
        assert(*it == "date");

        std::cout << "Test 2 passed: Insertion at the end." << std::endl;
    }

    {
        std::forward_list<std::string> strList = {"Apple", "banana", "Cherry"};
        processForwardList(strList, "apple", "date", "./");

        auto it = strList.begin();
        assert(*it == "Apple"); ++it;
        assert(*it == "date"); ++it;
        assert(*it == "banana"); ++it;
        assert(*it == "Cherry");

        std::cout << "Test 3 passed: Case-insensitive search." << std::endl;
    }
}

int main() {
    runTests();
    return 0;
}
