```javascript
const { Readable } = require('stream');
const crypto = require('crypto');

function copyBytesFromChunks(chunks, byteCount) {
  return new Promise((resolve, reject) => {
    let copiedData = Buffer.alloc(0);
    let totalCopiedBytes = 0;

    const readStream = new Readable({
      objectMode: true,
      read() {}
    });

    chunks.forEach(chunk => {
      if (!Buffer.isBuffer(chunk)) {
        return reject(new Error('All chunks must be Buffers.'));
      }
      readStream.push(chunk);
    });

    readStream.push(null);

    readStream.on('data', (chunk) => {
      const remainingBytes = byteCount - totalCopiedBytes;
      if (remainingBytes <= 0) {
        // If we've copied enough, stop reading further data
        readStream.destroy();
        return;
      }

      try {
        if (chunk.length > remainingBytes) {
          copiedData = Buffer.concat([copiedData, chunk.slice(0, remainingBytes)]);
          totalCopiedBytes += remainingBytes;
        } else {
          copiedData = Buffer.concat([copiedData, chunk]);
          totalCopiedBytes += chunk.length;
        }
      } catch (error) {
        reject(new Error('Error while copying data: ' + error.message));
      }

      if (totalCopiedBytes === byteCount) {
        readStream.destroy();
      }
    });

    readStream.on('end', () => {
      if (totalCopiedBytes < byteCount) {
        return reject(new Error(`Requested ${byteCount} bytes but only got ${totalCopiedBytes}.`));
      }

      const hash = crypto.createHash('sha256').update(copiedData).digest('hex');
      console.log(`Copied data SHA-256: ${hash}`); // Replace with actual database logging

      resolve(copiedData);
    });

    readStream.on('error', (err) => {
      reject(err);
    });
  });
}

module.exports = { copyBytesFromChunks };
