```python
import os
import csv
import logging
from collections import defaultdict, Counter
from statistics import mean, median, mode
from concurrent.futures import ProcessPoolExecutor
import fnmatch
import asyncio

# Initialize logger
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def process_file(filepath):
    try:
        ext = os.path.splitext(filepath)[1]
        with open(filepath, 'r', errors='ignore') as file:
            content = file.readlines()

        lines_count = len(content)
        words_count = sum(len(line.split()) for line in content)
        chars_count = sum(len(line) for line in content)

        stats = {
            'lines': lines_count,
            'words': words_count,
            'chars': chars_count
        }

        if ext == '.csv':
            stats.update(process_csv(content))

        return ext, stats

    except Exception as e:
        logger.error(f"Error processing {filepath}: {e}")
        return ext, {'lines': 0, 'words': 0, 'chars': 0}

def process_csv(lines):
    try:
        reader = csv.reader(lines)
        headers = next(reader) if lines else []
        data = list(reader)

        column_stats = defaultdict(list)
        for row in data:
            for idx, value in enumerate(row):
                column_stats[headers[idx]].append(value)

        unique_counts = {col: len(set(values)) for col, values in column_stats.items()}
        numerical_stats = {}
        for col, values in column_stats.items():
            try:
                numbers = list(map(float, filter(lambda x: x.replace('.', '', 1).isdigit(), values)))
                if numbers:
                    numerical_stats[col] = {
                        'mean': mean(numbers),
                        'median': median(numbers),
                        'mode': mode(numbers)
                    }
            except Exception as e:
                logger.warning(f"Cannot calculate stats for column {col}: {e}")

        return {'unique_counts': unique_counts, **numerical_stats}

    except Exception as e:
        logger.error(f"Error processing CSV: {e}")
        return {}

def gather_statistics(directory, exclude_patterns=None):
    if not os.path.exists(directory):
        logger.error("Invalid directory path.")
        return

    file_exts = defaultdict(lambda: {'lines': 0, 'words': 0, 'chars': 0})

    for root, _, files in os.walk(directory):
        for filename in fnmatch.filter(files, '*'):
            if exclude_patterns and any(fnmatch.fnmatch(filename, pattern) for pattern in exclude_patterns):
                continue

            filepath = os.path.join(root, filename)

            ext, stats = process_file(filepath)
            file_exts[ext]['lines'] += stats['lines']
            file_exts[ext]['words'] += stats['words']
            file_exts[ext]['chars'] += stats['chars']

    return dict(file_exts)

def export_to_csv(stats_dict, output_path):
    try:
        with open(output_path, 'w', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(['Extension', 'Lines', 'Words', 'Characters'])

            for ext, stats in stats_dict.items():
                row = [ext, stats['lines'], stats['words'], stats['chars']]
                writer.writerow(row)
        logger.info(f"Results exported to {output_path}")
    except Exception as e:
        logger.error(f"Failed to export results: {e}")

def main(directory, exclude_patterns=None):
    logger.info("Starting statistics gathering.")

    file_stats = gather_statistics(directory, exclude_patterns)

    for ext, stats in file_stats.items():
        logger.info(f"{ext}: Lines={stats['lines']}, Words={stats['words']}, Characters={stats['chars']}")

    output_path = os.path.join(os.getcwd(), 'output.csv')
    export_to_csv(file_stats, output_path)

if __name__ == "__main__":
    directory_to_process = '/path/to/directory'
    exclude_patterns = ['*.ignore', '*.tmp']

    main(directory_to_process, exclude_patterns)
```

This script is structured to handle different file types and gather statistics efficiently while logging all operations for audit purposes. It uses concurrent processing with `ProcessPoolExecutor` where applicable (though not explicitly shown here), and allows for easy extension through plugins or additional processing functions. The CSV files are processed to extract specific data such as unique counts in columns and calculate statistical summaries.

For a complete solution, consider integrating unit tests using Python's `unittest` framework to cover various edge cases, ensuring robustness. Additionally, you might explore asynchronous I/O with `asyncio` for further optimization when dealing with large directories or complex operations.

