<?php

class DynamicRandomStringGenerator {
    private $charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    private $configCache;
    private $lock;

    public function __construct() {
        $this->lock = new \stdClass();
        $this->configCache = [];
    }

    /**
     * Generates a custom random string based on specified length and character set.
     *
     * @param int $length
     * @param string $charset
     * @param bool $seeded Optional, whether to use seeded randomness
     * @return string Generated random string
     */
    public function GenerateCustomRandomString($length, $charset = null, $seeded = false) {
        if (!is_int($length) || $length <= 0) {
            throw new InvalidArgumentException("Length must be a positive integer.");
        }

        if ($charset === null) {
            $charset = $this->charset;
        } elseif (empty($charset)) {
            throw new InvalidArgumentException("Character set cannot be empty.");
        }

        if (!$seeded) {
            return $this->generateRandomString($length, $charset);
        } else {
            mt_srand((int)microtime(true) * 10000);
            return $this->generateRandomString($length, $charset);
        }
    }

    private function generateRandomString($length, $charset) {
        $result = '';
        for ($i = 0; $i < $length; $i++) {
            $index = rand(0, strlen($charset) - 1);
            $result .= $charset[$index];
        }
        return $result;
    }

    /**
     * Hashes a password using a default hash function.
     *
     * @param string $password
     * @return string The hashed password
     */
    public function HashPassword($password) {
        if (empty($password)) {
            throw new InvalidArgumentException("Password cannot be empty.");
        }

        return password_hash($password, PASSWORD_DEFAULT);
    }

    /**
     * Updates configuration from an external system and applies it using a callback.
     *
     * @param callable $configUpdateCallback
     */
    public function UpdateConfig(callable $configUpdateCallback) {
        if (!is_callable($configUpdateCallback)) {
            throw new InvalidArgumentException("Invalid callback provided.");
        }

        if (isset($this->lock)) {
            // Ensure thread safety using a lock
            return false;
        }

        $this->lock = true;

        try {
            $newConfig = []; // Assume fetching from an external API or source
            if ($configUpdateCallback($newConfig) === true) {
                $this->configCache = array_merge($this->configCache, $newConfig);
            }
        } finally {
            unset($this->lock);
        }

        return true;
    }

    private function validateCharset($charset) {
        if (empty($charset)) {
            throw new InvalidArgumentException("Character set cannot be empty.");
        }
    }
}

// Define the delegate type for configuration updates
type ConfigUpdateCallback = callable(array $config): bool;

