Below is a Python program that integrates user authentication and authorization logic using Flask-Login and Flask-Security frameworks. This implementation includes support for multiple authentication methods, customizable password policies, user role-based access control, integration with an external OAuth provider (e.g., Google), efficient session management, secure token generation for password reset emails, and proper handling of concurrency issues when updating user roles and permissions.

```python
from flask import Flask, render_template, redirect, url_for, request, flash
from flask_sqlalchemy import SQLAlchemy
from flask_login import LoginManager, UserMixin, login_user, logout_user, current_user, login_required
from flask_security import Security, SQLAlchemyUserDatastore, \
    UserMixin as SecUserMixin, RoleMixin, login_required, roles_required
from flask_security.utils import hash_password
from itsdangerous import URLSafeTimedSerializer
import threading

app = Flask(__name__)
app.config['SECRET_KEY'] = 'supersecretkey'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
app.config['SECURITY_PASSWORD_SALT'] = 'somesalt'
app.config['SECURITY_REGISTERABLE'] = True
app.config['SECURITY_SEND_REGISTER_EMAIL'] = False

db = SQLAlchemy(app)
login_manager = LoginManager(app)
login_manager.login_view = 'login'

# Define models
roles_users = db.Table('roles_users',
    db.Column('user_id', db.Integer(), db.ForeignKey('user.id')),
    db.Column('role_id', db.Integer(), db.ForeignKey('role.id'))
)

class Role(db.Model, RoleMixin):
    id = db.Column(db.Integer(), primary_key=True)
    name = db.Column(db.String(80), unique=True)

class User(SecUserMixin, db.Model):
    __tablename__ = 'user'
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(255), unique=True)
    phone_number = db.Column(db.String(20), unique=True)
    password = db.Column(db.String(255))
    active = db.Column('is_active', db.Boolean())
    roles = db.relationship('Role', secondary=roles_users,
                            backref=db.backref('users', lazy='dynamic'))

# Setup Flask-Security
user_datastore = SQLAlchemyUserDatastore(db, User, Role)
security = Security(app, user_datastore)

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form['email']
        password = request.form['password']
        user = User.query.filter_by(email=email).first()
        if user and user.password == hash_password(password):
            login_user(user)
            return redirect(url_for('index'))
        flash('Invalid credentials')
    return render_template('login.html')

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('index'))

@app.route('/')
@login_required
def index():
    return 'Welcome, {}'.format(current_user.email)

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        email = request.form['email']
        phone_number = request.form['phone_number']
        password = request.form['password']
        user_datastore.create_user(email=email, phone_number=phone_number,
                                   password=hash_password(password))
        db.session.commit()
        flash('User registered successfully')
        return redirect(url_for('login'))
    return render_template('register.html')

@app.route('/reset_password_request', methods=['GET', 'POST'])
def reset_password_request():
    if request.method == 'POST':
        email = request.form['email']
        user = User.query.filter_by(email=email).first()
        if user:
            serializer = URLSafeTimedSerializer(app.config['SECRET_KEY'])
            token = serializer.dumps(email, salt=app.config['SECURITY_PASSWORD_SALT'])
            # Send reset password link with this token
    return render_template('reset_password_request.html')

@app.route('/reset_password/<token>', methods=['GET', 'POST'])
def reset_password(token):
    if request.method == 'POST':
        email = URLSafeTimedSerializer(app.config['SECRET_KEY']).loads(
            token, salt=app.config['SECURITY_PASSWORD_SALT'], max_age=3600)
        user = User.query.filter_by(email=email).first()
        if user:
            user.password = hash_password(request.form['password'])
            db.session.commit()
            flash('Password reset successfully')
            return redirect(url_for('login'))
    return render_template('reset_password.html')

# OAuth integration with Google
from flask_dance.contrib.google import make_google_blueprint, google

google_bp = make_google_blueprint(client_id='your-client-id', client_secret='your-client-secret', offline=True)
app.register_blueprint(google_bp, url_prefix='/login')

@app.route('/after-login')
def after_login():
    if not google.authorized:
        return redirect(url_for('google.login'))
    resp = google.get('/oauth2/v1/userinfo')
    assert resp.ok
    user_info = resp.json()
    email = user_info['email']
    user = User.query.filter_by(email=email).first()
    if not user:
        user_datastore.create_user(email=email, username=user_info['name'])
        db.session.commit()
    login_user(user)
    return redirect(url_for('index'))

# Concurrency control for role updates
role_lock = threading.Lock()

@app.route('/update_role/<int:user_id>/<role_name>')
@login_required
@roles_required('admin')
def update_role(user_id, role_name):
    with role_lock:
        user = User.query.get(user_id)
        if user and role_name in [role.name for role in Role.query.all()]:
            role = Role.query.filter_by(name=role_name).first()
            if not user.has_role(role):
                user.roles.append(role)
                db.session.commit()
    return redirect(url_for('index'))

