```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

public class GameClient {

    private static final int MAX_RETRIES = 5;
    private static final long BASE_TIMEOUT_MS = 1000;
    private static final ConcurrentHashMap<String, Long> lastAttackTime = new ConcurrentHashMap<>();
    private static final ReentrantLock lock = new ReentrantLock();

    public void connectAndManageCharacter(String serverAddress, int port) throws IOException {
        SocketChannel socketChannel = null;
        Selector selector = Selector.open();

        try {
            socketChannel = SocketChannel.open(new InetSocketAddress(serverAddress, port));
            socketChannel.configureBlocking(false);

            SelectionKey key = socketChannel.register(selector, SelectionKey.OP_CONNECT);

            boolean connected = false;
            int attempt = 0;
            long timeout = BASE_TIMEOUT_MS;

            while (!connected && attempt < MAX_RETRIES) {
                if (key.isConnectable()) {
                    try {
                        key.attach(new Long(System.currentTimeMillis()));
                        socketChannel.finishConnect();
                        connected = true;
                        log("Connected to server at " + serverAddress + ":" + port);
                    } catch (IOException e) {
                        handleDoSAttack(e, attempt, selector);
                        attempt++;
                        timeout *= 2; // Exponential backoff
                        Thread.sleep(timeout);
                    }
                }

                selector.select();
            }

            if (!connected) {
                log("Failed to connect after " + MAX_RETRIES + " attempts.");
                return;
            }

            manageCharacterActions(socketChannel, serverAddress, port);

        } finally {
            if (socketChannel != null) {
                socketChannel.close();
            }
            selector.close();
        }
    }

    private void handleDoSAttack(IOException e, int attempt, Selector selector) throws IOException {
        log("Connection attempt " + (attempt + 1) + " failed: " + e.getMessage());
        if (e instanceof java.net.ConnectException || 
            e.toString().contains("Connection refused") ||
            e.toString().contains("No route to host")) {
            log("Potential DoS attack detected. Retrying...");
            selector.wakeup();
        }
    }

    private void manageCharacterActions(SocketChannel socketChannel, String serverAddress, int port) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(256);

        while (true) {
            lock.lock();
            try {
                if (!isCooldownMet()) {
                    log("Attack cooldown not met. Waiting...");
                    Thread.sleep(calculateDynamicCooldown());
                    continue;
                }

                // Simulate attack selection logic
                String selectedAttack = selectAttackBasedOnResources();

                long powerLevel = determinePowerLevel(selectedAttack);
                log("Selected Attack: " + selectedAttack + ", Power Level: " + powerLevel);

                buffer.clear();
                buffer.put(("ATTACK:" + selectedAttack).getBytes());
                buffer.flip();

                socketChannel.write(buffer);
                recordLastAttackTime(System.currentTimeMillis());

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                log("Thread interrupted.");
                break;
            } finally {
                lock.unlock();
            }
        }
    }

    private boolean isCooldownMet() {
        return lastAttackTime.entrySet().stream()
                             .allMatch(entry -> System.currentTimeMillis() - entry.getValue() > calculateDynamicCooldown());
    }

    private long calculateDynamicCooldown() {
        // Placeholder logic for dynamic cooldown calculation
        return 1000 + (Math.random() * 2000);
    }

    private String selectAttackBasedOnResources() {
        // Placeholder logic for attack selection based on resources and conditions
        return "Basic Attack"; 
    }

    private long determinePowerLevel(String attackType) {
        switch (attackType.toLowerCase()) {
            case "basic attack":
                return 10;
            case "medium attack":
                return 20;
            case "heavy attack":
                return 30;
            default:
                return 0;
        }
    }

    private void recordLastAttackTime(long timestamp) {
        lastAttackTime.put("characterId", timestamp);
    }

    private void log(String message) {
        System.out.println("[LOG] " + message);
    }
}
