#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/socket.h>
#include <unistd.h>
#include <errno.h>

#define DNS_QUERY_TIMEOUT -2
#define DNS_QUERY_FAILURE -3
#define INVALID_INPUT -1
#define INSUFFICIENT_BUFFER -4

typedef unsigned char u_char;

int resolveHostWithTimeout(const char *hostname, u_char *ipAddress, size_t ipAddressLength, const char *dnsServers[], int timeout) {
    if (!hostname || !ipAddress || !dnsServers || timeout <= 0) {
        return INVALID_INPUT;
    }

    struct addrinfo hints, *res, *p;
    int status;
    fd_set readfds;
    struct timeval tv;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    for (int i = 0; dnsServers[i] != NULL; ++i) {
        char server[INET_ADDRSTRLEN];
        inet_pton(AF_INET, dnsServers[i], &server);

        char query[256];
        snprintf(query, sizeof(query), "gethostbyname2_r(%s)", hostname);

        // Attempt DNS resolution
        if (getaddrinfo(hostname, NULL, &hints, &res) == 0) {
            for (p = res; p != NULL; p = p->ai_next) {
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                if (inet_ntop(AF_INET, &(ipv4->sin_addr), ipAddress, ipAddressLength)) {
                    freeaddrinfo(res);
                    return 0; // Success
                }
            }
        }

        freeaddrinfo(res);

        int sockfd = socket(AF_INET, SOCK_STREAM, IPPROTO_IP);
        if (sockfd < 0) continue;

        struct sockaddr_in servaddr;
        memset(&servaddr, 0, sizeof(servaddr));
        servaddr.sin_family = AF_INET;
        servaddr.sin_port = htons(53); // DNS port
        inet_pton(AF_INET, dnsServers[i], &servaddr.sin_addr);

        if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
            close(sockfd);
            continue;
        }

        // Prepare the query and send it
        char buffer[512];
        snprintf(buffer, sizeof(buffer), "your DNS query format here"); // Simplified

        write(sockfd, buffer, strlen(buffer));

        FD_ZERO(&readfds);
        FD_SET(sockfd, &readfds);

        tv.tv_sec = timeout / 1000;
        tv.tv_usec = (timeout % 1000) * 1000;

        int select_status = select(sockfd + 1, &readfds, NULL, NULL, &tv);
        if (select_status > 0) {
            char response[512];
            read(sockfd, response, sizeof(response));
            // Parse the response and store in ipAddress
            inet_pton(AF_INET, "parsed IP", ipAddress); // Simplified
            close(sockfd);
            return 0; // Success
        } else if (select_status == 0) {
            close(sockfd);
            return DNS_QUERY_TIMEOUT;
        } else {
            perror("Select error");
            close(sockfd);
            continue;
        }
    }

    return DNS_QUERY_FAILURE;
}

int main() {
    u_char ipAddress[16];
    const char *dnsServers[] = {"8.8.8.8", "8.8.4.4", NULL};
    int result = resolveHostWithTimeout("www.example.com", ipAddress, sizeof(ipAddress), dnsServers, 5000);

    if (result == 0) {
        printf("Resolved IP: %s\n", inet_ntoa(*(struct in_addr*)ipAddress));
    } else {
        printf("Error code: %d\n", result);
    }

    return 0;
}
