#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double value;
} record;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_arrays(const char* config_file_path, size_t num_records, double min_value, double max_value) {
    FILE *file = fopen(config_file_path, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    offsets = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));
    records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        free(offsets);
        free(keys);
        free(records);
        fclose(file);
        return;
    }

    // Read initial values from the configuration file
    for (size_t i = 0; i < num_records; ++i) {
        if (fscanf(file, "%ld %d", &offsets[i], &keys[i]) != 2) {
            fprintf(stderr, "Failed to read offset and key at line %zu\n", i + 1);
            free(offsets);
            free(keys);
            free(records);
            fclose(file);
            return;
        }
    }

    fclose(file);

    // Initialize records and set random values
    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&mutex);  // Ensure thread safety when accessing shared resources

        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);

        pthread_mutex_unlock(&mutex);
    }

    free(offsets);
    free(keys);
    free(records);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <config_file_path> <num_records> <min_value> <max_value>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* config_file_path = argv[1];
    size_t num_records = strtoul(argv[2], NULL, 10);
    double min_value = atof(argv[3]);
    double max_value = atof(argv[4]);

    // Ensure seed for random number generation
    srand((unsigned int)time(NULL));

    initialize_arrays(config_file_path, num_records, min_value, max_value);

    return EXIT_SUCCESS;
}
