#include <stdint.h>
#include <pthread.h>

#define ERROR_MEMORY_ALLOCATION -1
#define ERROR_INVALID_PARAMETERS -2

typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    // Add relevant fields here
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T rxUeInformationTag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG_T crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

int generateNFAPduList(int num_pdus, NFAPI_CRC_INDICATION_PDU_T **pdu_list, uint32_t *checksum) {
    if (num_pdus <= 0 || pdu_list == NULL || checksum == NULL) {
        return ERROR_INVALID_PARAMETERS;
    }

    pthread_mutex_lock(&list_mutex);

    // Allocate memory for the list
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        pthread_mutex_unlock(&list_mutex);
        return ERROR_MEMORY_ALLOCATION;
    }

    uint32_t checksum_value = 0;

    for (int i = 0; i < num_pdus; ++i) {
        // Populate RX_UE_INFORMATION_TAG and RNTI here
        list[i].rxUeInformationTag = /* initialize with valid data */;
        list[i].rnti = /* initialize with valid RNTI value */;

        // Randomly set CRCFLAG (example using rand(), replace with actual random source if needed)
        list[i].crcIndicationRel8Tag.CRCFLAG = rand() % 2;
        checksum_value += list[i].crcIndicationRel8Tag.CRCFLAG;
    }

    *pdu_list = list;
    *checksum = checksum_value;

    pthread_mutex_unlock(&list_mutex);

    return 0;
}

// Function to free the allocated memory for NFAPI_CRC_INDICATION_PDU_T list
void freePduList(NFAPI_CRC_INDICATION_PDU_T **pdu_list) {
    if (pdu_list && *pdu_list) {
        free(*pdu_list);
        *pdu_list = NULL;
    }
}
```

### Explanation:

- **Memory Management**: Uses `malloc` for dynamic allocation and provides a `freePduList` function to deallocate memory, ensuring proper cleanup.

- **Concurrency**: Utilizes `pthread_mutex_t` to ensure thread safety when accessing shared resources or critical sections.

- **Error Handling**: Checks for invalid input parameters and handles memory allocation failures with appropriate return codes.

- **Performance and Scalability**: Allocates all structures at once and uses efficient loops, minimizing overhead. The code is designed to handle large numbers of structures efficiently.

- **Integration**: Computes a checksum over the CRCFLAG values, making it suitable for integration where such a checksum might be required.

- **Maintainability**: The code is organized in clear sections with comments indicating where specific initializations should occur, making future modifications and maintenance straightforward.

