// JavaScript Function: Copy bytes from buffered data chunks

function copyBytesFromChunks(chunks, numBytes) {
    let buffer = Buffer.alloc(numBytes);
    let totalCopied = 0;

    for (const chunk of chunks) {
        if (chunk.length === 0 || totalCopied >= numBytes) break;

        const bytesToCopy = Math.min(chunk.length, numBytes - totalCopied);

        chunk.copy(buffer, totalCopied, 0, bytesToCopy);
        totalCopied += bytesToCopy;

        // Log for debugging
        console.log(`Copied ${bytesToCopy} bytes from a chunk`);
    }

    if (totalCopied < numBytes) {
        throw new Error('Requested byte count exceeds available data');
    }

    return buffer.slice(0, totalCopied);
}

