```cpp
#include <iostream>
#include <forward_list>
#include <string>
#include <random>
#include <functional>
#include <algorithm>
#include <openssl/sha.h> // Ensure OpenSSL is installed for SHA-256

bool generateAndHash(std::forward_list<std::string>& list, const std::string& charset,
                     const std::string& password, size_t length,
                     const std::string& target, 
                     bool (*compare)(const std::string&, const std::string&) = nullptr) {
    // Default comparison function: case-insensitive
    auto default_compare = [](const std::string& a, const std::string& b) {
        return std::equal(a.begin(), a.end(), b.begin(), b.end(),
                          [](char ac, char bc) { return tolower(ac) == tolower(bc); });
    };

    // Use the provided comparison function or default to case-insensitive
    compare = compare ? compare : default_compare;

    try {
        std::random_device rd;
        std::mt19937 gen(rd());

        // Generate a random string of given length using the character set
        std::uniform_int_distribution<> dis(0, charset.size() - 1);
        std::string random_string;
        for (size_t i = 0; i < length; ++i) {
            random_string += charset[dis(gen)];
        }

        // Find position to insert after the first occurrence of target
        auto it = list.before_begin();
        bool found = false;

        for (auto current = list.begin(); current != list.end(); ++current) {
            if (compare(*current, target)) {
                it = current;
                ++it;  // Insert after the current element
                found = true;
                break;
            }
        }

        // If target not found, insert at end of list
        if (!found) {
            it = list.end();
        }

        // Perform the insertion
        list.insert_after(it, random_string);

        // Hash the password using SHA-256
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, password.c_str(), password.size());
        SHA256_Final(hash, &sha256);

        std::cout << "Hash: ";
        for (unsigned char i : hash) {
            printf("%02x", i);
        }
        std::cout << std::endl;

        return true;  // Indicate success
    } catch (...) {
        return false;  // Catch any exceptions and indicate failure
    }
}
```

This function provides the requested functionality, including handling memory management gracefully by using `std::forward_list`'s automatic memory management. It includes a default case-insensitive comparison function for finding the target string in the list and allows users to specify their own comparison function if needed. The SHA-256 hashing is done using OpenSSL's library functions. Make sure to link with `-lssl -lcrypto` when compiling, as this code uses OpenSSL for hashing.

