using System;
using UnityEngine;

public class DynamicRandomValueGenerator
{
    private float minValue;
    private float maxValue;
    private Func<float> distributionFunction = () => UnityEngine.Random.Range(minValue, maxValue);

    public enum DistributionType { Uniform, Gaussian }

    private DistributionType distribution = DistributionType.Uniform;

    public DynamicRandomValueGenerator(float min, float max)
    {
        if (min >= max) throw new ArgumentException("Min should be less than Max");

        minValue = min;
        maxValue = max;
    }

    public void SetDistribution(DistributionType distType, Func<float> customFunction = null)
    {
        distribution = distType;
        distributionFunction = customFunction ?? (() => 
            distribution == DistributionType.Gaussian ? UnityEngine.Random.Range(minValue, maxValue) * 0.5f : UnityEngine.Random.Range(minValue, maxValue));
    }

    public float GenerateRandomFloat()
    {
        return distributionFunction();
    }

    public int GenerateRandomInt()
    {
        return Mathf.FloorToInt(GenerateRandomFloat());
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}] (Distribution: {distribution})";
    }
}

// Unit Tests
using NUnit.Framework;

[TestFixture]
public class DynamicRandomValueGeneratorTests
{
    [Test]
    public void TestUniformDistributionFloat()
    {
        var generator = new DynamicRandomValueGenerator(0.0f, 10.0f);
        float value = generator.GenerateRandomFloat();

        Assert.IsTrue(value >= 0.0f && value <= 10.0f);
    }

    [Test]
    public void TestUniformDistributionInt()
    {
        var generator = new DynamicRandomValueGenerator(1, 100);
        int value = generator.GenerateRandomInt();

        Assert.IsTrue(value >= 1 && value <= 99); // Mathf.FloorToInt affects range
    }

    [Test]
    public void TestGaussianDistributionFloat()
    {
        Func<float> gaussianDist = () => UnityEngine.Random.Range(0.0f, 10.0f) * 0.5f;
        var generator = new DynamicRandomValueGenerator(0.0f, 10.0f);

        generator.SetDistribution(DynamicRandomValueGenerator.DistributionType.Gaussian, gaussianDist);
        float value = generator.GenerateRandomFloat();

        Assert.IsTrue(value >= 0.0f && value <= 5.0f); // Due to the custom distribution
    }
}
