```javascript
function FindElementsBySelector(rootNode, selector) {
    if (!rootNode || !selector) return [];

    const result = [];
    const stack = [rootNode];

    while (stack.length > 0) {
        const node = stack.pop();

        // Process the current node to see if it matches the selector
        if ((node.tagName && node.classList.contains(selector)) ||
            (node.id === selector)) {
                result.push(node);
        }

        // Add child nodes to stack for processing
        for (let i = node.children.length - 1; i >= 0; i--) {
            stack.push(node.children[i]);
        }
    }

    return result;
}

// Example usage:
// const matchedElements = FindElementsBySelector(document.body, 'target-class');
```

### Explanation

- **C# Class:**
  - The `DynamicRandomValueGenerator` class provides functionality to generate random values within a specified range. It can handle both uniform and Gaussian distributions.
  - Unit tests using NUnit ensure the correctness of random value generation for various conditions.

- **JavaScript Function:**
  - The `FindElementsBySelector` function uses an iterative approach with a stack to traverse the DOM tree, preventing stack overflow issues typical in recursive solutions.
  - It checks elements against a selector based on class or ID and collects matches efficiently.

```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class FileChunkProcessor
{
    private Func<string, byte[], byte[], Task<byte[]>> _encryptionServiceCallback;
    private Action<string> _loggingCallback;
    private const int DefaultBufferSize = 4096; // Default buffer size for reading/writing

    public async Task<string> DecryptFileChunkAsync(string filePath, byte[] key, byte[] iv, int chunkSize, int bufferSize, bool parallelProcessing)
    {
        if (_encryptionServiceCallback == null) throw new InvalidOperationException("Encryption service callback is not set.");

        try
        {
            using (FileStream fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            {
                long totalBytesProcessed = 0;
                long fileSize = fileStream.Length;
                byte[] buffer = new byte[bufferSize];
                int bytesRead;

                var tasks = new Task<byte[]>[parallelProcessing ? (int)Math.Ceiling((double)fileSize / chunkSize) : 1];

                for (long position = 0; position < fileSize; position += chunkSize)
                {
                    long currentChunkSize = Math.Min(chunkSize, fileSize - position);
                    int taskIndex = parallelProcessing ? (int)(position / chunkSize) : 0;

                    tasks[taskIndex] = Task.Run(async () =>
                    {
                        fileStream.Seek(position, SeekOrigin.Begin);
                        bytesRead = await fileStream.ReadAsync(buffer, 0, currentChunkSize).ConfigureAwait(false);

                        if (bytesRead > 0)
                        {
                            byte[] decryptedData = await _encryptionServiceCallback(filePath, buffer[..bytesRead], iv).ConfigureAwait(false);
                            return decryptedData;
                        }

                        return Array.Empty<byte>();
                    });

                    // Log progress
                    totalBytesProcessed += bytesRead;
                    _loggingCallback?.Invoke($"Progress: {totalBytesProcessed}/{fileSize} bytes processed.");
                }

                await Task.WhenAll(tasks);

                string result = string.Join("", tasks.Select(task => Encoding.UTF8.GetString(task.Result)));
                return result;
            }
        }
        catch (Exception ex)
        {
            _loggingCallback?.Invoke($"Error processing file: {ex.Message}");
            throw;
        }
    }

    public void SetEncryptionServiceCallback(Func<string, byte[], byte[], Task<byte[]>> callback)
    {
        _encryptionServiceCallback = callback ?? throw new ArgumentNullException(nameof(callback));
    }

    public void SetLoggingCallback(Action<string> callback)
    {
        _loggingCallback = callback ?? throw new ArgumentNullException(nameof(callback));
    }
}

// Example usage:
// FileChunkProcessor processor = new FileChunkProcessor();
// processor.SetEncryptionServiceCallback(async (filePath, data, iv) =>
