using System;
using System.IO;
using System.Linq;
using System.Xml;
using System.Xml.XPath;
using System.Xml.Schema;
using System.Collections.Concurrent;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class XmlParserService : IXmlParserService
{
    private readonly ILogger<XmlParserService> _logger;
    private readonly IMemoryCache _cache;
    private readonly XPathDocument _externalApiSchema;

    public XmlParserService(ILogger<XmlParserService> logger, IMemoryCache cache)
    {
        _logger = logger;
        _cache = cache;

        // Assume that we fetch the schema from an external API
        var schemaData = FetchExternalAPISchema();
        _externalApiSchema = new XPathDocument(new StringReader(schemaData));
    }

    public XElement GetElementByName(string xmlContent, string elementName)
    {
        using (var reader = XmlReader.Create(new StringReader(xmlContent)))
        {
            ValidateXmlAgainstSchema(reader);

            var cacheKey = $"XPath_{elementName}";
            if (!_cache.TryGetValue(cacheKey, out XPathNavigator navigator))
            {
                _logger.LogInformation("Loading XML document into memory.");
                var doc = new XPathDocument(new StringReader(xmlContent));

                // Cache management with size limit and expiration
                _cache.Set(cacheKey, doc.CreateNavigator(), TimeSpan.FromMinutes(30));

                navigator = doc.CreateNavigator();
                _cache.Set(cacheKey, navigator);
            }

            var query = $"//{elementName}";
            try
            {
                var nodes = navigator.Select(query).Cast<XPathNavigator>().ToList();

                if (nodes.Count == 0)
                    throw new ElementNotFoundException($"No element found with the name '{elementName}'.");

                if (nodes.Count > 1)
                    throw new MultipleElementsFoundException($"Multiple elements found with the name '{elementName}'.");

                var firstNode = nodes.First();
                return XElement.Load(firstNode.ReadSubtree());
            }
            catch (XPathException ex)
            {
                _logger.LogError(ex, "Invalid XPath query provided.");
                throw new InvalidXPathQueryException("The XPath query is invalid. Please check your syntax.", ex);
            }
        }
    }

    private void ValidateXmlAgainstSchema(XmlReader reader)
    {
        var settings = new XmlReaderSettings { ValidationType = ValidationType.Schema };
        settings.Schemas.Add(null, _externalApiSchema.CreateNavigator());

        settings.ValidationEventHandler += (sender, e) =>
        {
            _logger.LogError(e.Exception, "XML schema validation failed.");
            throw new InvalidXmlFormatException("The XML document does not conform to the expected schema.", e.Exception);
        };

        using (var validator = XmlReader.Create(reader, settings))
        {
            while (validator.Read()) { }
        }
    }

    private string FetchExternalAPISchema()
    {
        // Implement API call logic here
        return "<Schema>...</Schema>"; // Dummy return value for illustration
    }
}

public interface IXmlParserService
{
    XElement GetElementByName(string xmlContent, string elementName);
}

// Custom Exceptions
public class ElementNotFoundException : Exception { public ElementNotFoundException(string message) : base(message) { } }
public class MultipleElementsFoundException : Exception { public MultipleElementsFoundException(string message) : base(message) { } }
public class InvalidXPathQueryException : Exception 
{ 
    public InvalidXPathQueryException(string message, Exception innerException) : base(message, innerException) { } 
}
