    public function generateRandomString(int $length, string $charset): ?string {
        if ($length <= 0 || empty($charset)) {
            $this->logger->error('Invalid input parameters for random string generation.');
            return null;
        }

        $randomString = '';
        try {
            $maxIndex = strlen($charset) - 1;
            for ($i = 0; $i < $length; $i++) {
                $randomString .= $charset[random_int(0, $maxIndex)];
            }
        } catch (\Exception $e) {
            $this->logger->error('Error generating random string: ' . $e->getMessage());
            return null;
        }

        return $randomString;
    }

    public function hashPassword(string $password, string $algorithm = PASSWORD_BCRYPT): ?string {
        if (empty($password)) {
            $this->logger->error('Empty password provided for hashing.');
            return null;
        }

        try {
            switch ($algorithm) {
                case 'bcrypt':
                    return password_hash($password, PASSWORD_BCRYPT);
                case 'argon2id':
                    return password_hash($password, PASSWORD_ARGON2ID);
                default:
                    $this->logger->error('Unsupported hashing algorithm: ' . $algorithm);
                    return null;
