using System;
using UnityEngine;

public class ValueGenerator : MonoBehaviour
{
    private int minInt;
    private int maxInt;
    private bool constrainFloatsToUnitInterval;

    public ValueGenerator(int minValue, int maxValue, bool constrainFloats = false)
    {
        if (minValue > maxValue)
            throw new ArgumentOutOfRangeException(nameof(minValue), "Minimum value must be less than or equal to maximum value.");

        minInt = minValue;
        maxInt = maxValue;
        constrainFloatsToUnitInterval = constrainFloats;
    }

    public int GenerateRandomInteger()
    {
        return UnityEngine.Random.Range(minInt, maxInt + 1);
    }

    public float GenerateRandomFloat()
    {
        float randomValue = UnityEngine.Random.value;

        if (constrainFloatsToUnitInterval)
            return Mathf.Lerp(0f, 1f, randomValue);

        return randomValue;
    }

    public int[] GenerateIntArray(int size)
    {
        if (size <= 0)
            throw new ArgumentException("Size must be greater than zero.", nameof(size));

        var array = new int[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GenerateRandomInteger();
        }
        return array;
    }

    public float[] GenerateFloatArray(int size)
    {
        if (size <= 0)
            throw new ArgumentException("Size must be greater than zero.", nameof(size));

        var array = new float[size];
        for (int i = 0; i < size; i++)
        {
            array[i] = GenerateRandomFloat();
        }
        return array;
    }

    public override string ToString()
    {
        return $"ValueGenerator: Integer Range [{minInt}, {maxInt}], Floats Constrained to [0, 1]: {constrainFloatsToUnitInterval}";
    }
}
