using System;
using System.Collections.Concurrent;
using System.Data;
using System.Diagnostics;
using System.Net.Http;
using System.Threading;
using Microsoft.Extensions.Logging;

public class DynamicDatabaseConnectionManager : IDisposable
{
    private readonly ConcurrentDictionary<string, ConcurrentBag<IDbConnection>> _connectionPool = new();
    private readonly object _lock = new();
    private int _minPoolSize = 5;
    private int _maxPoolSize = 50;
    private static Random _random = new(42);
    private readonly ILogger<DynamicDatabaseConnectionManager> _logger;

    public DynamicDatabaseConnectionManager(ILogger<DynamicDatabaseConnectionManager> logger)
    {
        _logger = logger;
    }

    public IDbConnection GetConnection(string provider, string connectionString)
    {
        if (!_connectionPool.TryGetValue(provider, out var connections))
        {
            lock (_lock)
            {
                if (!_connectionPool.TryGetValue(provider, out connections))
                {
                    connections = new ConcurrentBag<IDbConnection>();
                    _connectionPool[provider] = connections;
                }
            }

            for (int i = 0; i < _minPoolSize; i++)
            {
                CreateAndAddConnection(connections, provider, connectionString);
            }
        }

        if (!connections.TryTake(out var connection))
        {
            if (_connectionPool[provider].Count >= _maxPoolSize)
            {
                throw new InvalidOperationException("Max pool size reached.");
            }

            connection = CreateNewConnection(provider, connectionString);
        }

        return connection;
    }

    public void ReleaseConnection(IDbConnection connection)
    {
        if (connection != null && !_connectionPool.ContainsKey(connection.DataSource))
            return;

        _connectionPool[connection.DataSource].Add(connection);
        AdjustPoolSize();
    }

    private IDbConnection CreateNewConnection(string provider, string connectionString)
    {
        IDbConnection connection = null;

        switch (provider.ToLower())
        {
            case "mysql":
                connection = new MySql.Data.MySqlClient.MySqlConnection(connectionString);
                break;
            case "postgresql":
                connection = new Npgsql.NpgsqlConnection(connectionString);
                break;
            case "sqlite":
                connection = new System.Data.SQLite.SQLiteConnection(connectionString);
                break;
            default:
                throw new NotSupportedException($"Provider {provider} is not supported.");
        }

        try
        {
            connection.Open();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error opening database connection.");
            throw;
        }

        return connection;
    }

    private void CreateAndAddConnection(ConcurrentBag<IDbConnection> connections, string provider, string connectionString)
    {
        var connection = CreateNewConnection(provider, connectionString);
        connections.Add(connection);
    }

    private void AdjustPoolSize()
    {
        foreach (var pool in _connectionPool.Values)
        {
            if (pool.Count < _minPoolSize && pool.Count + 5 <= _maxPoolSize)
            {
                for (int i = 0; i < 5; i++)
                {
                    CreateAndAddConnection(pool, "provider", "connectionString");
                }
            }
        }
    }

    public void InitializeFromConfiguration()
    {
        // Example: Fetch configuration from an external system
        try
        {
            using var client = new HttpClient();
            string configJson = client.GetStringAsync("https://config-service/api/config").Result;
            // Parse and update connection settings accordingly
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to initialize from configuration.");
        }
    }

    public override string ToString()
    {
        var stateInfo = $"Connection Pool Size: {GetTotalPoolSize()}, Active Connections: {_connectionPool.Count}";
        return stateInfo;
    }

    private int GetTotalPoolSize() => _connectionPool.Values.Sum(bag => bag.Count);

    public void Dispose()
    {
        foreach (var connections in _connectionPool.Values)
        {
            foreach (var connection in connections)
            {
                try
                {
                    if (connection.State != ConnectionState.Closed)
                        connection.Close();
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error closing database connection.");
                }
            }
        }

        _connectionPool.Clear();
    }
}
