// Global semaphore for synchronization
sem_t sem;

void* access_resource(void* arg) {
    int* data = (int*)arg;

    // Wait on the semaphore
    if (sem_wait(&sem) != 0) {
        perror("sem_wait failed");
        exit(EXIT_FAILURE);
    }

    // Simulate accessing a shared resource (e.g., database)
    printf("Accessing resource with value: %d\n", *data);

    // Signal the semaphore to release
    if (sem_post(&sem) != 0) {
        perror("sem_post failed");
        exit(EXIT_FAILURE);
    }

    return NULL;
}

int find_largest(int* arr, int size) {
    if (size == 0) return INT_MIN; // Handle empty array case

    int largest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

