    for (int i = 0; i < size; i++) {
        if (scanf("%d", &arr[i]) != 1) {
            fprintf(stderr, "Invalid input\n");
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup() {
    // Destroy the semaphore
    sem_destroy(&sem);
}

int main() {
    int nums[MAX_INTS];
    int num_count;

    printf("Enter number of integers (max %d): ", MAX_INTS);
    if (scanf("%d", &num_count) != 1 || num_count <= 0 || num_count > MAX_INTS) {
        fprintf(stderr, "Invalid input\n");
        return EXIT_FAILURE;
    }

    // Initialize semaphore
    if (sem_init(&sem, 0, 1) != 0) { // Binary semaphore for single resource access
        perror("sem_init failed");
        return EXIT_FAILURE;
    }

    read_integers(nums, num_count);

    pthread_t threads[num_count];
    for (int i = 0; i < num_count; i++) {
        if (pthread_create(&threads[i], NULL, access_resource, &nums[i]) != 0) {
            perror("pthread_create failed");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_count; i++) {
        pthread_join(threads[i], NULL);
    }

    int largest = find_largest(nums, num_count);
    printf("The largest integer is: %d\n", largest);

    cleanup();
    return EXIT_SUCCESS;
}
