### Expected Behavior and Error Responses

- **Semaphore Initialization**: The semaphore is initialized with a value of `1` to allow one thread access at a time. If initialization fails, an error message is printed, and the program exits.

- **Network Operations**: Simulated by accessing shared resources in `access_resource`. In real scenarios, handle network errors such as timeouts or unavailable services.

- **Error Handling**: Proper checks for input validation, semaphore operations, and thread creation failures. If any operation fails, an error message is printed, and the program exits gracefully.

- **Thread Synchronization**: Ensures that only one thread accesses the shared resource at a time, minimizing latency and maximizing throughput.

- **Scalability**: Designed to handle up to `MAX_INTS` integers concurrently, with potential for scaling by adjusting semaphore initialization and thread management strategies.

```javascript
// main.js

const fs = require('fs');
const path = require('path');
const { promisify } = require('util');

const readFileAsync = promisify(fs.readFile);
const loadModule = async (moduleName, context) => {
  if (!context.loadedModules[moduleName]) {
    try {
      console.log(`Loading module: ${moduleName}`);
      const modPath = path.resolve(__dirname, moduleName);
      const moduleCode = await readFileAsync(modPath + '.js', 'utf-8');
      context.loadedModules[moduleName] = new Function('require', 'module', 'exports', moduleCode)(require, { exports: {} }, {});
    } catch (error) {
      console.error(`Error loading module ${moduleName}:`, error.message);
    }
  }
  return context.loadedModules[moduleName];
};

const executeModuleSequence = async (configPath, concurrencyLevel) => {
  const configData = await readFileAsync(configPath, 'utf-8');
  const config = JSON.parse(configData);

  let context = { loadedModules: {}, executionQueue: [], errors: [] };

  for (let moduleName of config.modules) {
    context.executionQueue.push(async () => await loadModule(moduleName, context));
  }

  while (context.executionQueue.length > 0) {
    const concurrentPromises = [];
    for (let i = 0; i < concurrencyLevel && context.executionQueue.length > 0; i++) {
      const task = context.executionQueue.shift();
      concurrentPromises.push(task());
    }
    await Promise.all(concurrentPromises);
  }

  if (context.errors.length) {
    console.error('Some modules failed to load:', context.errors);
  } else {
    console.log('All modules loaded successfully.');
  }
};

const configPath = './moduleConfig.json';
const concurrencyLevel = process.argv[2] ? parseInt(process.argv[2], 10) : 3;
executeModuleSequence(configPath, concurrencyLevel).catch(console.error);

