// tiff_parser.c

#include <stdio.h>
#include <stdlib.h>

typedef struct {
  int bitsPerSample;
  int samplesPerPixel;
  int extraSamples;
} TiffInfo;

TiffInfo parseTIFF(const char *filename) {
  FILE *file = fopen(filename, "rb");
  if (!file) {
    fprintf(stderr, "Error opening file\n");
    exit(EXIT_FAILURE);
  }

  TiffInfo info = {0, 0, 0};

  // Simplified TIFF parsing logic
  unsigned char buffer[4];
  fread(buffer, sizeof(unsigned char), 2, file); // Read first two bytes to determine endian-ness

  if (buffer[0] == 'M' && buffer[1] == 'M') {
    fseek(file, 4, SEEK_SET);
  } else if (buffer[0] == 'I' && buffer[1] == 'I') {
    fseek(file, 8, SEEK_SET);
  } else {
    fprintf(stderr, "Not a valid TIFF file\n");
    fclose(file);
    exit(EXIT_FAILURE);
  }

  // Skip to BitsPerSample offset
  fseek(file, 10, SEEK_CUR); // Assume fixed location for simplicity

  int bitsPerSample;
  fread(&bitsPerSample, sizeof(int), 1, file);

  if (bitsPerSample == 1 || bitsPerSample == 2 || bitsPerSample == 4 ||
      bitsPerSample == 8 || bitsPerSample == 16) {
    info.bitsPerSample = bitsPerSample;
  } else {
    fprintf(stderr, "Unsupported BitsPerSample: %d\n", bitsPerSample);
    fclose(file);
    exit(EXIT_FAILURE);
  }

  // Assume SamplesPerPixel is next
  int samplesPerPixel;
  fread(&samplesPerPixel, sizeof(int), 1, file);
  info.samplesPerPixel = samplesPerPixel;

  // Assume ExtraSamples is next
  int extraSamples;
  fread(&extraSamples, sizeof(int), 1, file);
  info.extraSamples = extraSamples;

  fclose(file);

  return info;
}

int main(int argc, char *argv[]) {
  if (argc < 2) {
    fprintf(stderr, "Usage: %s <tiff_file>\n", argv[0]);
    exit(EXIT_FAILURE);
  }

  TiffInfo info = parseTIFF(argv[1]);

  printf("BitsPerSample: %d\n", info.bitsPerSample);
  printf("SamplesPerPixel: %d\n", info.samplesPerPixel);
  printf("ExtraSamples: %d\n", info.extraSamples);

  return EXIT_SUCCESS;
}
