    private readonly List<string> _filePaths;
    private static readonly ConcurrentBag<Product> MergedProducts = new();

    public ProductLoader(List<string> filePaths)
    {
        _filePaths = filePaths;
    }

    public async Task<List<Product>> LoadAndMergeProductsAsync()
    {
        var tasks = _filePaths.Select(filePath => Task.Run(() => LoadProductsFromFile(filePath)));
        await Task.WhenAll(tasks);

        return MergedProducts.ToList();
    }

    private List<Product> LoadProductsFromFile(string filePath)
    {
        if (!File.Exists(filePath))
        {
            LogError($"File not found: {filePath}");
            return new List<Product>();
        }

        try
        {
            using (FileStream fs = new FileStream(filePath, FileMode.Open))
            {
                BinaryFormatter formatter = new();

                while (fs.Position < fs.Length)
                {
                    Product product = (Product)formatter.Deserialize(fs);
                    MergedProducts.Add(product);
                }

                return MergedProducts.Where(p => p != null).ToList();
            }
        }
        catch (Exception ex)
        {
            LogError($"Failed to load products from file: {filePath}. Error: {ex.Message}");
            return new List<Product>();
        }
    }

    private void LogError(string message)
    {
        // Implement logging mechanism, e.g., log to a file or external system
