```javascript
const { createWriteStream, promises: fs } = require('fs');
const { pipeline } = require('stream/promises');
const { PassThrough } = require('stream');

class StreamBuffer {
  constructor() {
    this.totalSize = 0;
    this.streams = [];
  }

  addStream(id, stream) {
    if (typeof id !== 'string') throw new Error("Stream ID must be a string");
    const passThrough = new PassThrough();
    this.streams.push({ id, size: 0, stream, passThrough });
    pipeline(stream, passThrough, err => {
      if (err) console.error(`Error in stream ${id}:`, err);
      else console.log(`Stream ${id} ended`);
    });

    const onData = chunk => {
      this.totalSize += chunk.length;
    };
    passThrough.on('data', onData);

    return passThrough;
  }

  async copyToBuffer(byteCount) {
    if (byteCount <= 0 || byteCount > this.totalSize) throw new Error("Invalid byte count");

    const bufferStream = PassThrough();
    let copiedBytes = 0;

    for (const { id, stream, passThrough } of this.streams) {
      stream.on('data', chunk => {
        const remainingBytes = byteCount - copiedBytes;
        if (remainingBytes <= 0) return;

        const bytesToCopy = Math.min(remainingBytes, chunk.length);
        bufferStream.write(chunk.slice(0, bytesToCopy));
        copiedBytes += bytesToCopy;

        if (copiedBytes >= byteCount) {
          passThrough.pause();
          stream.destroy(); // Stop further data processing
          this.logOperation(id, 0, copiedBytes - 1); // Log metadata

          bufferStream.end();
        }
      });
    }

    return bufferStream;
  }

  async logOperation(streamId, startByte, endByte) {
    const metadata = { streamId, startByte, endByte, timestamp: new Date().toISOString() };

    try {
      await fs.appendFile('operation_logs.json', JSON.stringify(metadata) + "\n");
      console.log(`Logged operation for ${streamId}`);
    } catch (err) {
      console.error("Error logging operation:", err);
    }
  }

  // Concurrency control using Node.js async nature
  acquireLock() {
    if (!this.locked) {
      this.locked = true;
      return new Promise(resolve => resolve());
    }
    return new Promise(resolve => setTimeout(() => resolve(this.acquireLock()), 10));
  }

  releaseLock() {
    this.locked = false;
  }
}

// Usage example (ensure streams are available):
async function main() {
  const streamBuffer = new StreamBuffer();

  // Example of adding simulated network streams
  const stream1 = fs.createReadStream('path/to/stream1.txt');
  const stream2 = fs.createReadStream('path/to/stream2.txt');

  streamBuffer.addStream("stream1", stream1);
  streamBuffer.addStream("stream2", stream2);

  try {
    await streamBuffer.acquireLock();
    const buffer = await streamBuffer.copyToBuffer(1024); // Copy first 1024 bytes

    const output = fs.createWriteStream('merged_output.txt');
    await pipeline(buffer, output);
    console.log("Data merged successfully.");
  } catch (error) {
    console.error("Error copying to buffer:", error);
  } finally {
    streamBuffer.releaseLock();
  }
}

main().catch(console.error);
