#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Define constants for buffer size and thread count
#define BUFFER_SIZE 1024
#define THREAD_COUNT 4

// Mutex for database connection
pthread_mutex_t db_lock = PTHREAD_MUTEX_INITIALIZER;

// Simulated function to store processed entries in the database.
int store_in_database(const char *entry) {
    // Lock the mutex before accessing the database
    pthread_mutex_lock(&db_lock);

    // Simulate storing in a database and handle potential connection loss
    int success = 1; // Assume success unless there's an error
    if (success != 0) {
        printf("Error: Failed to store entry in the database. Error code: %d\n", errno);
        pthread_mutex_unlock(&db_lock);
        return 0;
    }

    pthread_mutex_unlock(&db_lock);
    return 1;
}

// Function to process log entries
void* process_logs(void *arg) {
    FILE *log_file = fopen("logfile.log", "r");
    if (!log_file) {
        perror("Failed to open log file");
        return NULL;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, log_file)) {
        // Parse the log entry
        char *token = strtok(buffer, ",");
        double sum_of_last_two = 0.0;
        int field_count = 0;

        char *last_numeric1 = NULL, *last_numeric2 = NULL;

        while (token) {
            if (field_count >= 2 && last_numeric2 != NULL) {
                // Found at least two numeric fields
                double num1 = atof(last_numeric1);
                double num2 = atof(last_numeric2);
                sum_of_last_two = num1 + num2;
                break;
            }

            if (sscanf(token, "%lf", &sum_of_last_two) == 1) {
                last_numeric2 = last_numeric1;
                last_numeric1 = token;
            }

            field_count++;
            token = strtok(NULL, ",");
        }

        double average = sum_of_last_two / 2.0;

        // Construct the new log entry
        char processed_entry[BUFFER_SIZE];
        snprintf(processed_entry, BUFFER_SIZE, "%s,%.2f", buffer, average);

        // Store in database
        if (!store_in_database(processed_entry)) {
            fprintf(stderr, "Failed to store processed entry.\n");
        } else {
            printf("%s\n", processed_entry);
        }
    }

    fclose(log_file);
    return NULL;
}

int main() {
    pthread_t threads[THREAD_COUNT];

    // Create and run threads
    for (int i = 0; i < THREAD_COUNT; ++i) {
        if (pthread_create(&threads[i], NULL, process_logs, NULL)) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < THREAD_COUNT; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
