#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct SubNode {
    char *str;
    double val;
    struct SubNode *next;
} SubNode;

typedef struct Node {
    int value;
    SubNode *subListHead;
} Node;

void freeSubNodes(SubNode *head) {
    while (head) {
        SubNode *temp = head;
        head = head->next;
        free(temp->str);
        free(temp);
    }
}

void freeNodes(Node *nodes, size_t nodeCount) {
    for (size_t i = 0; i < nodeCount; ++i) {
        freeSubNodes(nodes[i].subListHead);
    }
    free(nodes);
}

Node* initializeNodes(size_t nodeCount, size_t subNodeCount, int minValue, int maxValue) {
    Node *nodes = malloc(nodeCount * sizeof(Node));
    if (!nodes) {
        fprintf(stderr, "Memory allocation error for nodes.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < nodeCount; ++i) {
        nodes[i].value = rand() % (maxValue - minValue + 1) + minValue;

        SubNode *head = malloc(sizeof(SubNode));
        if (!head) {
            fprintf(stderr, "Memory allocation error for subNodes.\n");
            freeNodes(nodes, i);
            return NULL;
        }

        head->str = malloc(20); // Assume fixed size string buffer
        if (!head->str) {
            fprintf(stderr, "Memory allocation error for subNode strings.\n");
            freeSubNodes(head);
            freeNodes(nodes, i + 1);
            return NULL;
        }

        snprintf(head->str, 20, "%s", "RandomString"); // Placeholder for a random string
        head->val = (double)rand() / RAND_MAX * 100.0; // Random double value between 0 and 100

        SubNode *current = head;
        for (size_t j = 1; j < subNodeCount; ++j) {
            current->next = malloc(sizeof(SubNode));
            if (!current->next) {
                fprintf(stderr, "Memory allocation error for subNodes.\n");
                freeSubNodes(head);
                freeNodes(nodes, i + 1);
                return NULL;
            }

            current->next->str = malloc(20); // Assume fixed size string buffer
            if (!current->next->str) {
                fprintf(stderr, "Memory allocation error for subNode strings.\n");
                freeSubNodes(head);
                freeNodes(nodes, i + 1);
                return NULL;
            }

            snprintf(current->next->str, 20, "%s", "RandomString"); // Placeholder
            current->next->val = (double)rand() / RAND_MAX * 100.0;

            current = current->next;
        }

        nodes[i].subListHead = head;
    }

    return nodes;
}

int main() {
    size_t nodeCount = 5;
    size_t subNodeCount = 3;
    int minValue = 10, maxValue = 50;

    Node *nodes = initializeNodes(nodeCount, subNodeCount, minValue, maxValue);
    if (nodes) {
        // Use the nodes for something

        freeNodes(nodes, nodeCount); // Free all allocated memory
    }

    return 0;
}
