use std::env;
use std::fs;
use std::path::Path;

fn main() {
    let key = "MY_ENV_VAR";
    if let Ok(value) = env::var(key) {
        println!("Using existing directory: {}", value);
    } else {
        let dir_name = format!("my_directory_{}", get_unique_suffix());
        match fs::create_dir(&dir_name) {
            Ok(_) => {
                if let Err(e) = env::set_var(key, &dir_name) {
                    eprintln!("Failed to set environment variable: {}", e);
                } else {
                    println!("Created and set directory: {}", dir_name);
                }
            },
            Err(e) => eprintln!("Failed to create directory: {}", e),
        }
    }
}

fn get_unique_suffix() -> u32 {
    use std::time::{SystemTime, UNIX_EPOCH};
    let start = SystemTime::now();
    let since_the_epoch = start.duration_since(UNIX_EPOCH).expect("Time went backwards");
    since_the_epoch.as_secs()
}
