#[no_mangle]
pub extern "C" fn call_setup_environment(directory_name: *const c_char) -> i32 {
    let directory_cstr = unsafe { CStr::from_ptr(directory_name) };
    let dir_path = match directory_cstr.to_str() {
        Ok(s) => s,
        Err(_) => return -1, // Error handling
    };

    if env::var("MY_ENV_VAR").is_err() {
        let new_dir = format!("{}/{}", env::current_dir().unwrap(), dir_path);

        match fs::create_dir(new_dir.clone()) {
            Ok(_) => {
                env::set_var("MY_ENV_VAR", new_dir);
                0 // Success
            }
            Err(_) => -1, // Error handling for directory creation
        }
    } else {
        0 // Environment variable already exists
    }
}
