using System.Threading.Tasks;

public class WebSiteManager
{
    private static readonly object _lock = new object();

    public async Task<string> AddAndStartWebsiteAsync(string directoryPath, string siteName)
    {
        if (!Directory.Exists(directoryPath) || !IsAccessible(directoryPath))
            return "Invalid or inaccessible directory path.";

        if (!IsValidSiteName(siteName))
            return "Invalid site name. Only alphanumeric characters and hyphens are allowed.";

        lock (_lock)
        {
            if (!File.Exists(Path.Combine(directoryPath, "web.config")))
                return RetrieveDefaultSettingsAsync().Result ?? null;
        }

        int port = GetAvailablePort();

        try
        {
            var startInfo = new ProcessStartInfo("cmd.exe", $"/c appcmd add site /name:{siteName} /bindings:http/*:localhost:{port}")
            {
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            using var process = new Process { StartInfo = startInfo };
            process.Start();

            if (!await process.StandardOutput.ReadToEndAsync().WaitForExitWithTimeout(10000))
                return "Failed to add the site within timeout.";

            using (var httpClient = new HttpClient())
            {
                string url = $"http://localhost:{port}";
                var response = await httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead);

                if (!response.IsSuccessStatusCode)
                    return "Failed to start the site.";
            }
        }
        catch (Exception ex)
        {
            LogError(ex);
            return "An error occurred while adding or starting the website. Please check dependencies and configuration.";
        }

        return $"Website '{siteName}' successfully added and started on port {port}.";
    }

    private bool IsAccessible(string path)
    {
        try
        {
            var access = FileIOPermission(FileIOPermissionAccess.PathDiscovery, path);
            access.Demand();
            return true;
        }
        catch
        {
            return false;
        }
    }

    private bool IsValidSiteName(string siteName) => Regex.IsMatch(siteName, @"^[a-zA-Z0-9\-]+$");

    private async Task<string> RetrieveDefaultSettingsAsync()
    {
        // Simulate interaction with external configuration system.
        await Task.Delay(500);  // Simulating network delay
        return null;
    }

    private int GetAvailablePort()
    {
        var listener = new TcpListener(System.Net.IPAddress.Loopback, 0);
        listener.Start();
        int port = ((IPEndPoint)listener.LocalEndpoint).Port;
        listener.Stop();
        return port;
    }

    private void LogError(Exception ex)
    {
        // Simulate logging
        Console.WriteLine($"Error: {ex.Message}");
    }
}

public static class ProcessExtensions
{
    public static async Task<bool> WaitForExitWithTimeout(this Task<string> task, int timeoutMilliseconds)
    {
        using (var cts = new CancellationTokenSource())
        {
            var completedTask = await Task.WhenAny(task, Task.Delay(timeoutMilliseconds, cts.Token));
            if (completedTask == task)
            {
                cts.Cancel();
                return true;
            }
            else
            {
                return false;
            }
        }
    }
