#include <mutex>
#include <thread>

namespace Simulation {

    class RNG {
    public:
        static nlohmann::json config;
        static std::mt19937 gen;
        static std::mutex mtx;

        RNG() {
            loadConfig();
            initGenerator();
        }

        ~RNG() {
            // Destructor logic if necessary
        }

        double generateUniform(double min, double max) {
            std::lock_guard<std::mutex> lock(mtx);
            std::uniform_real_distribution<double> dist(min, max);
            return dist(gen);
        }

        double generateNormal(double mean, double stddev) {
            std::lock_guard<std::mutex> lock(mtx);
            std::normal_distribution<double> dist(mean, stddev);
            return dist(gen);
        }

        double generateExponential(double lambda) {
            std::lock_guard<std::mutex> lock(mtx);
            std::exponential_distribution<double> dist(lambda);
            return dist(gen);
        }

    private:
        void loadConfig() {
            try {
                std::ifstream configFile("config.json");
                if (configFile.is_open()) {
                    configFile >> config;
                    configFile.close();
                } else {
                    throw std::runtime_error("Unable to open configuration file.");
                }
            } catch (...) {
                std::cerr << "Error loading configuration. Using default settings." << std::endl;
                // Set default configuration
                config["distribution"] = "uniform";
                config["min"] = 0.0;
                config["max"] = 1.0;
                config["mean"] = 0.0;
                config["stddev"] = 1.0;
                config["lambda"] = 1.0;
            }
        }

        void initGenerator() {
            unsigned seed = std::random_device{}();
            gen.seed(seed);
        }
    };

    // Initialize static members
    nlohmann::json RNG::config;
    std::mt19937 RNG::gen;
    std::mutex RNG::mtx;

} // namespace Simulation

int main() {
