import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.concurrent.*;
import javax.net.ssl.*;

public class SecureConnectionPool {

    private final ExecutorService executorService;
    private final SSLContext sslContext;
    private final int maxConnections;
    private final BlockingQueue<Channel> connectionPool;

    public SecureConnectionPool(int initialSize, int maxConnections) throws NoSuchAlgorithmException, KeyManagementException {
        this.executorService = Executors.newCachedThreadPool();
        this.sslContext = SSLContext.getInstance("TLS");
        this.sslContext.init(null, null, new java.security.SecureRandom());
        this.maxConnections = maxConnections;
        this.connectionPool = new LinkedBlockingQueue<>(maxConnections);
        for (int i = 0; i < initialSize; i++) {
            connectionPool.offer(createSecureChannel());
        }
    }

    private Channel createSecureChannel() throws IOException {
        SocketChannel channel = SocketChannel.open();
        SslEngine sslEngine = sslContext.createSSLEngine();
        sslEngine.setUseClientMode(true);
        ((AutoCloseable) sslEngine).close(); // Ensure resources are released
        return new NioSslWrapper(channel, sslEngine);
    }

    public Channel acquireConnection() throws InterruptedException {
        return connectionPool.poll(10, TimeUnit.SECONDS);
    }

    public void releaseConnection(Channel channel) {
        if (connectionPool.size() < maxConnections) {
            connectionPool.offer(channel);
        }
    }

    public void closeAll() throws IOException {
        for (Channel channel : connectionPool) {
            ((AutoCloseable) channel).close();
        }
        executorService.shutdownNow();
    }

    private class NioSslWrapper implements Channel {
        private final SocketChannel socketChannel;
        private final SslEngine sslEngine;

        public NioSslWrapper(SocketChannel socketChannel, SslEngine sslEngine) {
            this.socketChannel = socketChannel;
            this.sslEngine = sslEngine;
        }

        @Override
        public boolean isOpen() {
            return socketChannel.isOpen();
        }

        // Implement other Channel methods delegating to socketChannel and managing SSL state

        @Override
        public void close() throws IOException {
            if (socketChannel != null) {
                socketChannel.close();
            }
            ((AutoCloseable) sslEngine).close();
        }
    }

    public static void main(String[] args) {
        try {
            SecureConnectionPool pool = new SecureConnectionPool(10, 1000);
            // Example usage
            Channel channel = pool.acquireConnection();
            // Use the channel for communication
            pool.releaseConnection(channel);

            pool.closeAll();
        } catch (Exception e) {
            e.printStackTrace(); // Log errors appropriately
        }
    }

    // Add methods to configure from properties file or command-line arguments
}

// Unit tests and configuration handling omitted for brevity
