public static class StringHasher
{
    public static string ComputeHash(string input, string algorithm)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty.", nameof(input));

        using var hashAlgorithm = CreateHashAlgorithm(algorithm);

        byte[] data = Encoding.UTF8.GetBytes(input);
        byte[] hashBytes = hashAlgorithm.ComputeHash(data);

        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }

    public static void ComputeHashesParallel(string[] inputs, string algorithm, ILoggerService logger)
    {
        if (inputs == null) throw new ArgumentNullException(nameof(inputs));

        var tasks = new ConcurrentBag<Task>();

        Parallel.ForEach(inputs, input =>
        {
            try
            {
                string hash = ComputeHash(input, algorithm);
                // Simulate processing the hash result...
            }
            catch (Exception ex)
            {
                logger.Log($"Error hashing input '{input}': {ex.Message}");
            }
        });
    }

    public static bool ValidateHash(string input, string knownHash, string algorithm)
    {
        if (string.IsNullOrEmpty(input) || string.IsNullOrEmpty(knownHash))
            throw new ArgumentException("Input and known hash cannot be null or empty.");

        return ComputeHash(input, algorithm).Equals(knownHash, StringComparison.OrdinalIgnoreCase);
    }

    private static HashAlgorithm CreateHashAlgorithm(string algorithm)
    {
        switch (algorithm.ToUpperInvariant())
        {
            case "SHA256":
                return SHA256.Create();
            case "MD5":
            default:
                return MD5.Create();
        }
    }
}

