import requests
from datetime import datetime, timedelta
from unittest.mock import patch, Mock

# Constants
API_KEY = 'your_openweathermap_api_key'
BASE_URL = "http://api.openweathermap.org/data/2.5/weather"
CACHE_EXPIRY = timedelta(minutes=10)
RATE_LIMIT_SECONDS = 60

class WeatherCache:
    def __init__(self):
        self.cache = {}

    def get(self, city):
        if city in self.cache:
            data, timestamp = self.cache[city]
            if datetime.now() - timestamp < CACHE_EXPIRY:
                return data
        return None

    def set(self, city, data):
        self.cache[city] = (data, datetime.now())

cache = WeatherCache()

def fetch_weather(city):
    cached_data = cache.get(city)
    if cached_data:
        return cached_data

    params = {'q': city, 'appid': API_KEY, 'units': 'metric'}
    try:
        response = requests.get(BASE_URL, params=params)
        response.raise_for_status()
        data = response.json()

        # Check for rate limiting
        if response.status_code == 429:
            wait_time = int(response.headers.get("Retry-After", RATE_LIMIT_SECONDS))
            print(f"Rate limit exceeded. Retrying in {wait_time} seconds.")
            time.sleep(wait_time)
            return fetch_weather(city)

        cache.set(city, data)
        return data

    except requests.exceptions.RequestException as e:
        print(f"Error fetching weather data: {e}")
        return None

def get_average_conditions(cities, days):
    end_date = datetime.now()
    start_date = end_date - timedelta(days=days)

    conditions = {
        'temperature': [],
        'humidity': [],
        'wind_speed': []
    }

    for city in cities:
        # Simulate daily data retrieval
        for single_date in (start_date + timedelta(n) for n in range((end_date-start_date).days)):
            # Using mock data to simulate different weather conditions during testing
            fetch_weather.cache_clear()

            with patch('requests.get') as mocked_get:
                mocked_response = Mock()
                mocked_response.json.return_value = {
                    'main': {'temp': 20 + (n % 10), 'humidity': 50},
                    'wind': {'speed': 5 + (n % 3)}
                }
                mocked_response.raise_for_status = lambda: None
                mocked_get.return_value = mocked_response

                data = fetch_weather(city)
                if data:
                    conditions['temperature'].append(data['main']['temp'])
                    conditions['humidity'].append(data['main']['humidity'])
                    conditions['wind_speed'].append(data['wind']['speed'])

    avg_conditions = {key: sum(values) / len(values) for key, values in conditions.items() if values}
    return avg_conditions

# Example usage
cities = ['London', 'New York', 'Tokyo']
average_conditions = get_average_conditions(cities, 7)
print(average_conditions)
