public class PageElementController : ControllerBase
{
    private readonly IDistributedCacheService _cacheService;
    private readonly IMessageQueueService _messageQueueService;
    private readonly RateLimiter _rateLimiter;

    public PageElementController(IDistributedCacheService cacheService, IMessageQueueService messageQueueService)
    {
        _cacheService = cacheService ?? throw new ArgumentNullException(nameof(cacheService));
        _messageQueueService = messageQueueService ?? throw new ArgumentNullException(nameof(messageQueueService));

        // Example rate limiter setup: 10 requests per minute
        _rateLimiter = new RateLimiter(10, TimeSpan.FromMinutes(1));
    }

    [HttpPost("update-element")]
    public async Task<IActionResult> UpdateElementHtmlAsync([FromBody] ElementUpdateRequest request)
    {
        if (!_rateLimiter.AllowRequest())
        {
            return StatusCode(StatusCodes.Status429TooManyRequests, "Rate limit exceeded.");
        }

        try
        {
            // Validate IDs and HTML content (basic validation for demonstration)
            if (string.IsNullOrWhiteSpace(request.PageSectionId) || string.IsNullOrWhiteSpace(request.ElementId))
                throw new ArgumentException("Invalid Page Section ID or Element ID.");

            var isHtmlWellFormed = IsHtmlWellFormed(request.HtmlContent);
            if (!isHtmlWellFormed)
                throw new ArgumentException("HTML content is not well-formed.");

            // Update HTML in distributed cache
            bool updateSuccessful = await _cacheService.UpdateElementHtmlAsync(
                request.PageSectionId, request.ElementId, request.HtmlContent);

            if (!updateSuccessful)
                throw new Exception("Failed to update element's HTML content in the distributed cache.");

            // Send message to trigger page refresh for all clients
            string message = $"RefreshPage:{request.PageSectionId}:{request.ElementId}";
            await _messageQueueService.SendMessageAsync(message);

            return Ok(new { Message = "Element updated successfully." });
        }
        catch (Exception ex)
        {
            // Log the error (implementation of logging is assumed to be available in your application)
            Console.Error.WriteLine($"Error updating element: {ex.Message}");
            return StatusCode(StatusCodes.Status500InternalServerError, ex.Message);
        }
    }

    private bool IsHtmlWellFormed(string htmlContent)
    {
        try
        {
            var xDoc = new System.Xml.Linq.XDocument();
            xDoc.Add(System.Xml.Linq.XElement.Parse(htmlContent));
            return true;
        }
        catch (Exception)
        {
            return false;
        }
    }
}

public class ElementUpdateRequest
{
    public string PageSectionId { get; set; }
    public string ElementId { get; set; }
    public string HtmlContent { get; set; }
}
