public:
    static std::mt19937_64 generator;

    SecureRandom() {
        seedRandomGenerator();
    }

    ~SecureRandom() = default; // Trivial destructor

private:
    void seedRandomGenerator() {
        unsigned long entropySeed = 0;
        std::ifstream urandom("/dev/urandom", std::ios::binary);

        if (urandom) {
            urandom.read(reinterpret_cast<char*>(&entropySeed), sizeof(entropySeed));
            urandom.close();
        } else {
            throw std::runtime_error("Failed to access /dev/urandom");
        }

        unsigned seed = entropySeed ^ std::chrono::system_clock::now().time_since_epoch().count();
        generator.seed(seed);
    }
