            });

            services.Configure<LockoutOptions>(options =>
            {
                options.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(5);
                options.MaxFailedAccessAttempts = 3;
            });
        }

        public void Configure(IApplicationBuilder app)
        {
            app.UseRouting();
            app.UseAuthentication();
            app.UseAuthorization();

            app.MapGet("/", async context =>
            {
                // Implement retry logic for S3 upload
                await RetryAsync(async () => await UploadToS3("file.txt"), 3);
            });
        }

        private static async Task RetryAsync(Func<Task> action, int retries)
        {
            while (retries-- > 0)
            {
                try
                {
                    await action();
                    break;
                }
                catch (Exception ex) when (IsTransient(ex))
                {
                    if (retries == 0) throw;
                    await Task.Delay(1000);
                }
            }
        }

        private static bool IsTransient(Exception ex)
        {
            // Implement logic to determine if the exception is transient
            return true; 
        }

        private async Task UploadToS3(string filename)
        {
            var transformedFilename = string.Format("{0}_modified", Path.GetFileNameWithoutExtension(filename));
            var client = new AmazonS3Client(); // Initialize with appropriate configuration
            var request = new PutObjectRequest
            {
                BucketName = "your-bucket-name",
                Key = transformedFilename,
                FilePath = filename
            };

            await client.PutObjectAsync(request);
        }
    }
}
