int main(int argc, char **argv) {
    DIR *dir;
    struct dirent *entry;
    ThreadData files[1024];
    int file_count = 0;

    // Open the directory containing log files
    dir = opendir("logs");
    if (!dir) {
        perror("Could not open directory");
        return EXIT_FAILURE;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // If it's a regular file
            char filepath[256];
            snprintf(filepath, sizeof(filepath), "logs/%s", entry->d_name);

            struct stat file_stat;
            if (stat(filepath, &file_stat) == 0) {
                files[file_count].filepath = strdup(filepath);
                files[file_count].priority = rand() % 10; // Random priority for example
                file_count++;
            }
        }
    }

    closedir(dir);

    prioritize_files(files, file_count);

    pthread_t threads[file_count];
    for (int i = 0; i < file_count; ++i) {
        if (pthread_create(&threads[i], NULL, (void *(*)(void *))process_log_file, (void *)files[i].filepath) != 0) {
            perror("Failed to create thread");
        }
    }

    for (int i = 0; i < file_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    for (int i = 0; i < file_count; ++i) {
        free(files[i].filepath);
    }

    return EXIT_SUCCESS;
}

// Function to process a log file
void *process_log_file(void *arg) {
    char *filepath = (char *)arg;
    FILE *file = fopen(filepath, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    FileMetadata metadata;
    metadata.filename = strdup(filepath);
    metadata.total_lines_read = 0;

    struct stat file_stat;
    if (stat(filepath, &file_stat) == 0) {
        metadata.last_modified = file_stat.st_mtime;
    }

    char line[1024];
    double total_average = 0.0;
    int valid_line_count = 0;

    while (fgets(line, sizeof(line), file)) {
        double avg = calculate_average_of_last_two_fields(line);
        if (!isnan(avg)) { // Valid average calculated
            total_average += avg;
            valid_line_count++;
        }
        metadata.total_lines_read++;
    }

    if (valid_line_count > 0) {
        double final_avg = total_average / valid_line_count;
        authenticate_and_send_to_logging_service(metadata, final_avg);
    }

    fclose(file);

    // Report real-time metrics
    collect_real_time_metrics();

    free(metadata.filename);
    return NULL;
}

// Function to calculate average of last two numerical fields in a line
double calculate_average_of_last_two_fields(char *line) {
    char *last_num1 = strrchr(line, ' ');
    char *last_num2 = strrchr(last_num1 + 1, ' ');

    if (!last_num1 || !last_num2) return NAN;

    double num1, num2;
    int valid1 = sscanf(last_num1 + 1, "%lf", &num1);
    int valid2 = sscanf(last_num2 + 1, "%lf", &num2);

    if (valid1 == 1 && valid2 == 1) {
        return (num1 + num2) / 2.0;
    }

    return NAN; // Invalid line
}

// Function to authenticate and send data to the external logging service API
