    pthread_mutex_lock(&lock);

    // Simulate sending data to an external service with OAuth2/JWT token
    fprintf(log_service_api, "File: %s, Avg: %.2f\n", metadata.filename, avg);

    // Normally you'd use HTTPS requests here
    // For example, using libcurl

    pthread_mutex_unlock(&lock);
}

// Function to collect real-time metrics
void collect_real_time_metrics() {
    // Implement metrics collection (e.g., with Prometheus or StatsD)
    // This function would collect and report processing speed, latency, error rates, etc.
}

// Function to prioritize files based on their criticality
void prioritize_files(ThreadData *files, int count) {
    // Simple bubble sort for example purposes
    for (int i = 0; i < count - 1; ++i) {
        for (int j = 0; j < count - i - 1; ++j) {
            if (files[j].priority < files[j + 1].priority) {
                ThreadData temp = files[j];
                files[j] = files[j + 1];
                files[j + 1] = temp;
            }
        }
    }
}
