using System;
using System.Diagnostics;
using System.IO;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;

public class WebsiteManager
{
    private readonly object _lock = new object();
    private const string DefaultWebConfigTemplate = "<configuration>...</configuration>";
    private static readonly Regex SiteNameRegex = new(@"^[a-zA-Z0-9-_]+$");

    public async Task AddAndStartSiteAsync(string directoryPath, string siteName, int basePort)
    {
        if (!Directory.Exists(directoryPath))
            throw new DirectoryNotFoundException("Invalid directory path.");

        if (!IsValidSiteName(siteName))
            throw new ArgumentException("Site name contains invalid characters.");

        lock (_lock) // Lock to handle concurrent access
        {
            var webConfigPath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigPath))
                File.WriteAllText(webConfigPath, GetDefaultWebConfig());

            int port = basePort;
            while (IsPortInUse(port)) 
            {
                port++;
            }

            string siteArgs = $"\"{directoryPath}\" {port}";
            var startInfo = new ProcessStartInfo("cmd.exe", $"/c appcmd add site /name:{siteName} /bindings:http/*:localhost:{port}:")
            {
                RedirectStandardOutput = true,
                UseShellExecute = false
            };

            using (var process = new Process { StartInfo = startInfo })
            {
                try
                {
                    var timeoutCancellationTokenSource = new CancellationTokenSource(TimeSpan.FromSeconds(30));
                    await Task.WhenAny(process.Start(), Task.Delay(Timeout.Infinite, timeoutCancellationTokenSource.Token));

                    if (!process.HasExited)
                    {
                        timeoutCancellationTokenSource.Cancel();
                        process.Kill();
                        LogError($"Failed to start site {siteName} due to timeout.");
                        return;
                    }

                    var output = await process.StandardOutput.ReadToEndAsync();
                    if (output.Contains("ERROR"))
                    {
                        LogError(output);
                    }
                }
                catch (Exception ex)
                {
                    LogError(ex.Message);
                }
            }

            StartHealthCheck(siteName, port);
        }
    }

    private bool IsValidSiteName(string siteName) =>
        SiteNameRegex.IsMatch(siteName);

    private string GetDefaultWebConfig()
    {
        // Assume integration with an external configuration management system
        return DefaultWebConfigTemplate;
    }

    private bool IsPortInUse(int port)
    {
        using (var listener = new TcpListener(System.Net.IPAddress.Loopback, port))
        {
            try
            {
                listener.Start();
                return false; // Port is available if Start() succeeds without exceptions
            }
            catch
            {
                return true; // Port is in use if exception occurs
            }
            finally
            {
                listener.Stop();
            }
        }
    }

    private void LogError(string message)
    {
        Console.Error.WriteLine($"[ERROR] {DateTime.Now}: {message}");
    }

    private async Task StartHealthCheck(string siteName, int port)
    {
        while (true)
        {
            try
            {
                using (var client = new System.Net.WebClient())
                {
                    string url = $"http://localhost:{port}";
                    await client.DownloadStringTaskAsync(url);
                }
            }
            catch (Exception ex)
            {
                LogError($"Health check failed for site {siteName} on port {port}: {ex.Message}");
            }

            await Task.Delay(TimeSpan.FromMinutes(1)); // Perform health checks every minute
        }
    }
}
