import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.List;
import java.util.concurrent.*;
import java.util.function.Function;

public class FileHasher {

    public static class HashMismatchException extends Exception {
        public HashMismatchException(String message) {
            super(message);
        }
    }

    private static final int BUFFER_SIZE = 4096; // Adjust buffer size as needed

    public List<String> computeAndValidateMD5(List<Path> filePaths) throws InterruptedException, ExecutionException, IOException {
        ExecutorService executor = Executors.newFixedThreadPool(filePaths.size());
        List<Future<String>> futures = filePaths.stream()
                .map(path -> executor.submit(() -> processFile(path)))
                .collect(Collectors.toList());

        // Shutdown the executor
        executor.shutdown();

        return futures.stream()
                .map(future -> {
                    try {
                        return future.get();
                    } catch (ExecutionException | InterruptedException e) {
                        throw new RuntimeException("Error processing file", e);
                    }
                })
                .collect(Collectors.toList());
    }

    private String processFile(Path filePath) throws IOException, HashMismatchException {
        MessageDigest md = getMessageDigest();

        try (InputStream fis = Files.newInputStream(filePath)) {
            byte[] buffer = new byte[BUFFER_SIZE];
            int bytesRead;

            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }

        String computedHash = bytesToHex(md.digest());

        // Call external API to get the hash
        String apiHash = callExternalHashingService(filePath.toString());

        if (!computedHash.equals(apiHash)) {
            throw new HashMismatchException("Computed MD5 does not match with the external service's MD5 for file: " + filePath);
        }

        return computedHash;
    }

    private MessageDigest getMessageDigest() throws IOException {
        try {
            return MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new IOException("MD5 algorithm not found", e);
        }
    }

    private String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder(2 * hash.length);
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private String callExternalHashingService(String filePath) throws IOException, InterruptedException {
        // Simulating API call with a placeholder URL and handling potential network issues
        String apiUrl = "https://api.example.com/hash?file=" + filePath; // Replace with actual API endpoint

        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(new URL(apiUrl).openStream(), java.nio.charset.StandardCharsets.UTF_8))) {
            return reader.readLine();  // Assuming the response contains the hash directly
        } catch (IOException e) {
            throw new IOException("Error calling external hashing service", e);
        }
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException, IOException {
        FileHasher hasher = new FileHasher();

        List<Path> filePaths = List.of(
                Paths.get("/path/to/file1.txt"),
                Paths.get("/path/to/file2.txt")
        );

        try {
            List<String> hashes = hasher.computeAndValidateMD5(filePaths);
            hashes.forEach(System.out::println);
        } catch (HashMismatchException e) {
            System.err.println("Hash mismatch: " + e.getMessage());
        }
    }
}
