// JavaScript Code

class ScriptManager {
    constructor() {
        this.cache = new Map();
        this.spinnerElement = document.createElement('div');
        this.spinnerElement.innerText = 'Loading...';
        this.cacheExpirationTime = 60000; // Default cache expiration time in milliseconds
    }

    async fetchScript(url) {
        if (this.cache.has(url)) {
            const { script, timestamp } = this.cache.get(url);
            if (Date.now() - timestamp < this.cacheExpirationTime) {
                return script;
            }
        }

        try {
            const response = await fetch(url);
            if (!response.ok) throw new Error(`Network response was not ok: ${response.statusText}`);

            const scriptContent = await response.text();
            this.cache.set(url, { script: scriptContent, timestamp: Date.now() });
            return scriptContent;
        } catch (error) {
            console.error('Error fetching script:', error);
            // Implement retry logic if needed
            throw error;
        }
    }

    createScriptTag(scriptObj, index) {
        const defaultType = 'text/javascript';
        const src = scriptObj.src || '';
        const type = scriptObj.type || defaultType;

        return `
            <script key="footer-script-${index}" ${src ? `src="${src}"` : `type="${type}"`} ${!src ? `innerHTML="${scriptObj.code}"` : ''}></script>
        `;
    }

    async renderScripts(scripts, loadSequentially = false) {
        this.showSpinner();
        const scriptTags = [];

        if (loadSequentially) {
            for (let i = 0; i < scripts.length; i++) {
                try {
                    const src = scripts[i].src;
                    let code = scripts[i].code;

                    if (src && !scripts[i].cachedScript) {
                        code = await this.fetchScript(src);
                        scripts[i].cachedScript = code;
                    }

                    scriptTags.push(this.createScriptTag({ code }, i));
                } catch (error) {
                    console.error(`Error loading script ${i}:`, error);
                }
            }
        } else {
            const fetchPromises = scripts
                .filter(script => script.src)
                .map(async (script, index) => {
                    try {
                        if (!script.cachedScript) {
                            script.cachedScript = await this.fetchScript(script.src);
                        }
                        return this.createScriptTag({ code: script.cachedScript }, index);
                    } catch (error) {
                        console.error(`Error loading script ${index}:`, error);
                    }
                });

            const fetchedScripts = await Promise.all(fetchPromises);

            scripts.forEach((script, index) => {
                if (!script.src || script.cachedScript) {
                    scriptTags.push(this.createScriptTag(script, index));
                } else {
                    // If fetch failed or src wasn't provided
                    scriptTags.push(this.createScriptTag({ code: `console.error('Failed to load script ${index}');` }, index));
                }
            });
        }

        this.hideSpinner();
        return scriptTags.join('');
    }

    showSpinner() {
        document.body.appendChild(this.spinnerElement);
    }

    hideSpinner() {
        if (this.spinnerElement.parentElement) {
            this.spinnerElement.parentElement.removeChild(this.spinnerElement);
        }
    }

    log(level, message) {
        // Example logging mechanism
        console[level](message); // Replace with a more sophisticated logging solution if needed
    }
}

function renderFooter(scriptsArray, loadSequentially = false) {
    const scriptManager = new ScriptManager();
    return scriptManager.renderScripts(scriptsArray, loadSequentially);
}
