using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class DatabaseHelper
{
    public IDataReader ExecuteQuery(string connectionString, string sql, List<object> parameters)
    {
        if (string.IsNullOrEmpty(connectionString)) throw new ArgumentException("Connection string cannot be null or empty.");
        if (string.IsNullOrEmpty(sql)) throw new ArgumentException("SQL command cannot be null or empty.");

        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            using (SqlCommand command = new SqlCommand(sql, connection))
            {
                for (int i = 0; i < parameters.Count; i++)
                {
                    command.Parameters.AddWithValue($"@param{i}", parameters[i]);
                }

                connection.Open();
                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
        }
    }
}
