using System.Text;
using Microsoft.AspNetCore.Mvc;

public class WebAppController : Controller
{
    private readonly IElementService _elementService;
    private readonly string _encryptionKey = "your-32-byte-key-here"; // Ensure this is 32 bytes for Triple DES
    private readonly byte[] _initializationVector = { /* your 8-byte IV here */ };

    public WebAppController(IElementService elementService)
    {
        _elementService = elementService;
    }

    [HttpPost]
    public IActionResult UpdateElement(string pageSectionId, string elementId, string encryptedHtmlContent)
    {
        try
        {
            // Decrypt the HTML content
            var decryptedHtmlContent = DecryptTripleDes(encryptedHtmlContent, _encryptionKey, _initializationVector);

            // Update the element's HTML content using the service class
            _elementService.UpdateElementContent(pageSectionId, elementId, decryptedHtmlContent);

            // Return a response indicating that the page should be refreshed
            return Json(new { refreshPage = true });
        }
        catch (Exception ex)
        {
            // Handle exceptions and return an error message
            return StatusCode(500, $"Internal server error: {ex.Message}");
        }
    }

    private string DecryptTripleDes(string encryptedData, string key, byte[] iv)
    {
        using var tdes = TripleDES.Create();
        tdes.Key = Encoding.UTF8.GetBytes(key);
        tdes.IV = iv;

        using var decryptor = tdes.CreateDecryptor(tdes.Key, tdes.IV);

        using var ms = new MemoryStream(Convert.FromBase64String(encryptedData));
        using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
        using (var sr = new StreamReader(cs))
        {
            return sr.ReadToEnd();
        }
    }
}

public interface IElementService
{
    void UpdateElementContent(string pageSectionId, string elementId, string htmlContent);
}
