namespace SessionManager {

    class SecureSessionIDGenerator {
    public:
        SecureSessionIDGenerator();
        ~SecureSessionIDGenerator();

        static std::string generateSessionID();
        static bool isValidSessionID(const std::string& sessionID);
        static void invalidateOldSessions();

    private:
        static std::mt19937_64 randomEngine;
        static std::mutex cacheMutex;
        static std::unordered_map<std::string, bool> sessionCache;

        static void seedRandomGenerator();
        static std::string encodeBase64(const std::vector<unsigned char>& data);
        static std::vector<unsigned char> decodeBase64(const std::string& encoded);
        static void collectEntropyFromNodes();

        // Simulated network communication for entropy collection
        static std::vector<unsigned char> getNetworkEntropy();
    };

    // Static member definitions
    std::mt19937_64 SecureSessionIDGenerator::randomEngine;
    std::mutex SecureSessionIDGenerator::cacheMutex;
    std::unordered_map<std::string, bool> SecureSessionIDGenerator::sessionCache;

    SecureSessionIDGenerator::SecureSessionIDGenerator() {
        seedRandomGenerator();
        collectEntropyFromNodes();
    }

    SecureSessionIDGenerator::~SecureSessionIDGenerator() {}

    std::string SecureSessionIDGenerator::generateSessionID() {
        const size_t sessionIdLength = 22;
        std::vector<unsigned char> randomBytes(sessionIdLength);

        do {
            randomEngine.fill(randomBytes.begin(), randomBytes.end());

            // Check for duplicates
            std::lock_guard<std::mutex> lock(cacheMutex);
            if (sessionCache.find(SecureSessionIDGenerator::encodeBase64(randomBytes)) == sessionCache.end()) {
                sessionCache[SecureSessionIDGenerator::encodeBase64(randomBytes)] = true;
                return encodeBase64(randomBytes);
            }
        } while (true);
    }

    bool SecureSessionIDGenerator::isValidSessionID(const std::string& sessionID) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        auto it = sessionCache.find(sessionID);
        if (it != sessionCache.end()) {
            return true;
        }
        return false;
    }

    void SecureSessionIDGenerator::invalidateOldSessions() {
        // For simplicity, we clear the cache here. A real implementation would
        // periodically remove expired entries based on a timestamp or usage count.
        std::lock_guard<std::mutex> lock(cacheMutex);
        sessionCache.clear();
    }

    void SecureSessionIDGenerator::seedRandomGenerator() {
        unsigned seedBytes[16];

        // Use /dev/urandom for entropy
        std::ifstream urandom("/dev/urandom", std::ios::in | std::ios::binary);
        if (urandom) {
            urandom.read(reinterpret_cast<char*>(seedBytes), sizeof(seedBytes));
            randomEngine.seed(std::hash<std::string>{}(std::string(seedBytes, seedBytes + 16)));
        } else {
            // Fallback to current time
            randomEngine.seed(std::chrono::system_clock::now().time_since_epoch().count());
        }
    }

    std::string SecureSessionIDGenerator::encodeBase64(const std::vector<unsigned char>& data) {
        BIO *bio, *b64;
        BUF_MEM *bufferPtr;

        b64 = BIO_new(BIO_f_base64());
        bio = BIO_new(BIO_s_mem());
        bio = BIO_push(b64, bio);

        BIO_write(bio, data.data(), data.size());
        BIO_flush(bio);
        BIO_get_mem_ptr(bio, &bufferPtr);

        std::string encodedData(bufferPtr->data, bufferPtr->length);
        BIO_free_all(bio);

        return encodedData;
    }

    std::vector<unsigned char> SecureSessionIDGenerator::decodeBase64(const std::string& encoded) {
        BIO *bio, *b64;
        int decodeLen = encoded.length();
        int len = 0;
        unsigned char* buffer = (unsigned char*)malloc(decodeLen);

        b64 = BIO_new(BIO_f_base64());
        bio = BIO_new_mem_buf(encoded.data(), -1);
        bio = BIO_push(b64, bio);

        len = BIO_read(bio, buffer, decodeLen);
        BIO_free_all(bio);

        std::vector<unsigned char> decodedData(buffer, buffer + len);
        free(buffer);

        return decodedData;
    }

    void SecureSessionIDGenerator::collectEntropyFromNodes() {
        auto networkEntropy = getNetworkEntropy();
        randomEngine.seed(std::hash<std::string>{}(std::string(networkEntropy.begin(), networkEntropy.end())));
    }

    std::vector<unsigned char> SecureSessionIDGenerator::getNetworkEntropy() {
        // Simulated function: In a real-world scenario, implement secure communication
        return {'N', 'e', 't', 'w', 'o', 'r', 'k'};
    }
}

