void* encrypt_file_chunk(void *arg) {
    ThreadData *data = (ThreadData *)arg;
    FILE *in_file = fopen(data->input_path, "rb");
    if (!in_file) {
        log_action("Error opening input file");
        pthread_exit(NULL);
    }

    FILE *out_file = fopen(data->output_path, "wb");
    if (!out_file) {
        fclose(in_file);
        log_action("Error opening output file");
        pthread_exit(NULL);
    }

    const int chunk_size = 4096;
    unsigned char in_chunk[chunk_size];
    unsigned char out_chunk[EVP_MAX_BLOCK_LENGTH];

    int read_len, written_len, total_written = 0;

    while ((read_len = fread(in_chunk, 1, chunk_size, in_file)) > 0) {
        if (!EVP_EncryptUpdate(data->ctx, out_chunk, &written_len, in_chunk, read_len)) {
            log_action("Encryption update failed");
            break;
        }

        fwrite(out_chunk, 1, written_len, out_file);
        total_written += written_len;

        if (data->progress_cb) {
            data->progress_cb(total_written, chunk_size); // Adjust for accurate progress
        }
    }

    if (!EVP_EncryptFinal_ex(data->ctx, out_chunk, &written_len)) {
        log_action("Encryption finalization failed");
    } else {
        fwrite(out_chunk, 1, written_len, out_file);
        total_written += written_len;
    }

    fclose(in_file);
    fclose(out_file);

    pthread_exit(NULL);
}

EVP_CIPHER_CTX* encrypt_file(const char *input_path, const char *output_path, 
                             progress_callback_t progress_cb) {
