    EVP_PKEY *key = retrieve_encryption_key();
    if (!key) {
        log_action("Failed to retrieve encryption key");
        return NULL;
    }

    // Initialize OpenSSL cipher context
    const EVP_CIPHER *cipher = EVP_aes_256_cbc();  // Example for AES-256-CBC, dynamically choose based on options
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        log_action("Failed to create EVP_CIPHER_CTX");
        return NULL;
    }

    unsigned char key_buffer[EVP_PKEY_size(key)];
    unsigned char iv[EVP_MAX_IV_LENGTH];
    RAND_bytes(iv, sizeof(iv));  // Random IV for CBC

    EVP_PKEY_get_raw_private_key(key, key_buffer, NULL);
    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, key_buffer, iv)) {
        log_action("Encryption initialization failed");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    pthread_t threads[4];  // Example with 4 threads
    ThreadData thread_data[4];

    for (int i = 0; i < 4; ++i) {
        snprintf(thread_data[i].input_path, sizeof(thread_data[i].input_path), "%s_%d", input_path, i);
        snprintf(thread_data[i].output_path, sizeof(thread_data[i].output_path), "%s_encrypted_%d", output_path, i);

        thread_data[i].ctx = ctx;
        thread_data[i].progress_cb = progress_cb;

