using System;
using System.IO;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Formatters.Binary;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

public class DataService : IDataService
{
    private readonly IServiceProvider _serviceProvider;

    public DataService(IServiceProvider serviceProvider)
    {
        _serviceProvider = serviceProvider;
    }

    public T LoadData<T>(string filePath) where T : class
    {
        if (filePath == null) throw new ArgumentNullException(nameof(filePath));

        using var loggerFactory = LoggerFactory.Create(builder => builder.AddConsole());
        ILogger logger = loggerFactory.CreateLogger<DataService>();

        try
        {
            using FileStream fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 4096, true);
            IFormatter formatter = new BinaryFormatter();

            lock (fileStream) // Ensuring thread safety for concurrent processing.
            {
                return (T)formatter.Deserialize(fileStream);
            }
        }
        catch (SerializationException ex)
        {
            logger.LogError(ex, "Deserialization failed due to invalid data format or version mismatch.");
            throw;
        }
        catch (IOException ex)
        {
            logger.LogError(ex, "I/O error occurred while reading the binary file.");
            throw;
        }
        catch (UnauthorizedAccessException ex)
        {
            logger.LogError(ex, "Access denied when attempting to read the file.");
            throw;
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "An unexpected error occurred during deserialization.");
            throw;
        }
    }
}

public interface IDataService
{
    T LoadData<T>(string filePath) where T : class;
}

// Example of dependency injection setup in a Startup.cs or Program.cs for ASP.NET Core
public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Register the data service with the DI container.
        services.AddSingleton<IDataService, DataService>();

        // Add other necessary services and configurations here...
    }
}
