```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <memory>
#include <stdexcept>

struct Point {
    float x, y, z;
};

class OctreeNode;

using OctreeNodePtr = std::shared_ptr<OctreeNode>;
using NodeList = std::vector<OctreeNodePtr>;

class OctreeNode {
public:
    explicit OctreeNode(const Point& center, float size);
    ~OctreeNode();

    bool insertPoint(const Point& point);
    void lockNode();
    void unlockNode();

    // Additional methods for managing sub-nodes
    bool split();
    void pruneUnusedNodes();

private:
    Point center_;
    float size_;
    int capacity_;  // Maximum points allowed before splitting
    NodeList children_;
    std::vector<Point> points_;

    mutable std::mutex mutex_;
    std::condition_variable cond_var_;

    // Utility methods for node management
    bool isPointInBounds(const Point& point) const;
};

OctreeNode::OctreeNode(const Point& center, float size)
    : center_(center), size_(size), capacity_(10), children_(8, nullptr) {}

bool OctreeNode::insertPoint(const Point& point) {
    if (!isPointInBounds(point)) return false;

    lockNode();

    try {
        if (points_.size() >= static_cast<size_t>(capacity_) * 0.8 && !split()) {
            std::cerr << "Failed to split node due to memory or other constraints." << std::endl;
            unlockNode();
            return false;
        }

        for (auto& child : children_) {
            if (child && child->insertPoint(point)) {
                return true;
            }
        }

        points_.push_back(point);
    } catch (...) {
        unlockNode();
        throw; // Rethrow exception after unlocking
    }

    unlockNode();
    return true;
}

void OctreeNode::lockNode() {
    mutex_.lock();
}

void OctreeNode::unlockNode() {
    mutex_.unlock();
}

bool OctreeNode::isPointInBounds(const Point& point) const {
    float halfSize = size_ * 0.5f;
    return (point.x >= center_.x - halfSize && point.x <= center_.x + halfSize &&
            point.y >= center_.y - halfSize && point.y <= center_.y + halfSize &&
            point.z >= center_.z - halfSize && point.z <= center_.z + halfSize);
}

bool OctreeNode::split() {
    if (!children_[0]) {  // First time splitting
        float quarterSize = size_ * 0.25f;

        children_[0] = std::make_shared<OctreeNode>(Point(center_.x - quarterSize, center_.y - quarterSize, center_.z + quarterSize), size_ * 0.5f);
        children_[1] = std::make_shared<OctreeNode>(Point(center_.x + quarterSize, center_.y - quarterSize, center_.z + quarterSize), size_ * 0.5f);
        // Initialize other children similarly...

        for (auto& point : points_) {
            if (!children_[0]->insertPoint(point)) {  // Attempt to re-insert points into new child nodes
                return false;
            }
        }

        points_.clear();
    }

    return true;
}

void OctreeNode::pruneUnusedNodes() {
    lockNode();

    for (auto& child : children_) {
        if (child) {
            child->pruneUnusedNodes();
            if (child->points_.empty()) {  // If a child node is empty, reset it
                child.reset();
            }
        }
    }

    unlockNode();
}

OctreeManager* initializeAdvancedOctree(const Point& center, float size) {
    try {
        auto root = std::make_shared<OctreeNode>(center, size);
