```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class DataPointGenerator
{
    private readonly Random _random = new Random();
    private int _minValue;
    private int _maxValue;

    public DataPointGenerator(int minValue, int maxValue)
    {
        ValidateRange(minValue, maxValue);
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public float GenerateRandomFloat(bool inclusive)
    {
        lock (_random) // Ensure thread safety
        {
            return inclusive ? (float)(_random.NextDouble() * (_maxValue - _minValue + 1) + _minValue) 
                             : (float)(_random.NextDouble() * (_maxValue - _minValue) + _minValue);
        }
    }

    public int GenerateRandomInt(bool inclusive)
    {
        lock (_random) // Ensure thread safety
        {
            if (inclusive)
                return _random.Next(_minValue, _maxValue + 1);

            return _random.Next(_minValue, _maxValue);
        }
    }

    public IEnumerable<float> GenerateMultipleDataPoints(int count, bool inclusive = true)
    {
        for (int i = 0; i < count; i++)
        {
            yield return GenerateRandomFloat(inclusive);
        }
    }

    private void ValidateRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");
        }
    }

    public override string ToString()
    {
        return $"Range: [{_minValue}, {_maxValue}]";
    }
}

public static class DomElementSelector
{
    public delegate bool SelectorMatch(Element element);

    public static IEnumerable<Element> SelectMatchingElements(Node startNode, string selector)
    {
        var elementsToCheck = new Queue<Node>();
        elementsToCheck.Enqueue(startNode);

        while (elementsToCheck.Count > 0)
        {
            Node currentNode = elementsToCheck.Dequeue();

            if (currentNode is Element element && MatchesSelector(element, selector))
            {
                yield return element;
            }

            foreach (var child in currentNode.ChildrenNodes)
            {
                elementsToCheck.Enqueue(child);
            }
        }
    }

    private static bool MatchesSelector(Element element, string selector)
    {
        // Implement your logic for matching the CSS selector with classes or IDs
        if (selector.StartsWith("."))
        {
            return element.ClassNames.Contains(selector.Substring(1));
        }

        if (selector.StartsWith("#"))
        {
            return element.Id == selector.Substring(1);
        }

        return false; // Extend this function as necessary to handle more complex selectors
    }
}

// Example of external classes for demonstration purposes
public class Node
{
    public List<Node> ChildrenNodes { get; set; } = new List<Node>();
}

public class Element : Node
{
    public string Id { get; set; }
    public List<string> ClassNames { get; set; } = new List<string>();
}
