<?php

session_start();
require 'vendor/autoload.php';

use GuzzleHttp\Client;
use Psr\Log\LoggerInterface;

function authenticateUser($clientId, $clientSecret, $username, $password) {
    global $logger; // Assume logger is a PSR-3 compliant Logger instance passed globally or through dependency injection

    if (!isset($_SESSION['attempt_count'])) {
        $_SESSION['attempt_count'] = 0;
    }

    // Rate limiting logic
    if ($_SESSION['attempt_count'] > 5) {
        $logger->warning("Too many failed attempts. Blocking user.");
        return "Too many login attempts, please try again later.";
    }

    // OAuth client setup
    $client = new Client();
    $oauthUrl = 'https://example.com/oauth/token'; // Replace with actual OAuth URL

    try {
        $response = $client->post($oauthUrl, [
            'form_params' => [
                'grant_type' => 'password',
                'client_id' => $clientId,
                'client_secret' => $clientSecret,
                'username' => $username,
                'password' => $password
            ]
        ]);

        if ($response->getStatusCode() === 200) {
            $data = json_decode($response->getBody(), true);
            $_SESSION['access_token'] = $data['access_token'];
            $_SESSION['attempt_count'] = 0; // Reset on successful login

            $logger->info("User authenticated successfully.");

            // Retrieve user information
            $userInfoResponse = getUserInfo($client, $data['access_token']);
            if ($userInfoResponse) {
                storeUserInfoInDatabase($userInfoResponse);
            }
        } else {
            $_SESSION['attempt_count']++;
            $logger->error("Authentication failed with status code: {$response->getStatusCode()}");
            return "Invalid credentials.";
        }
    } catch (\Exception $e) {
        $_SESSION['attempt_count']++;
        $logger->error("An error occurred during authentication: " . $e->getMessage());
        return "An error occurred. Please try again later.";
    }
}

function getUserInfo($client, $accessToken) {
    global $logger;

    $userInfoUrl = 'https://example.com/userinfo'; // Replace with actual user info URL

    try {
        $response = $client->get($userInfoUrl, [
            'headers' => ['Authorization' => "Bearer {$accessToken}"]
        ]);

        if ($response->getStatusCode() === 200) {
            return json_decode($response->getBody(), true);
        } else {
            $logger->error("Failed to retrieve user info with status code: {$response->getStatusCode()}");
            return null;
        }
    } catch (\Exception $e) {
        $logger->error("An error occurred while retrieving user info: " . $e->getMessage());
        return null;
    }
}

function storeUserInfoInDatabase($userInfo) {
    // Assume $pdo is a PDO instance for database connection
    global $pdo;

    // Sanitize and prepare data
    $name = htmlspecialchars($userInfo['name'], ENT_QUOTES, 'UTF-8');
    $email = filter_var($userInfo['email'], FILTER_SANITIZE_EMAIL);

    // Store in the database safely
    $stmt = $pdo->prepare('INSERT INTO users (name, email) VALUES (:name, :email)');
    $stmt->execute([':name' => $name, ':email' => $email]);
}

function refreshTokenIfNeeded() {
    global $logger;

    if (!isset($_SESSION['access_token_expires_at'])) return;

    $currentTimestamp = time();
    if ($currentTimestamp >= $_SESSION['access_token_expires_at'] - 300) { // Refresh before expiration
        $logger->info("Refreshing access token.");
        refreshAccessToken();
    }
}

function refreshAccessToken() {
    global $client, $clientId, $clientSecret;

    $refreshTokenUrl = 'https://example.com/oauth/token'; // Replace with actual OAuth URL

    try {
        $response = $client->post($refreshTokenUrl, [
            'form_params' => [
                'grant_type' => 'refresh_token',
                'refresh_token' => $_SESSION['refresh_token'],
                'client_id' => $clientId,
                'client_secret' => $clientSecret
            ]
        ]);

        if ($response->getStatusCode() === 200) {
            $data = json_decode($response->getBody(), true);
            $_SESSION['access_token'] = $data['access_token'];
            $_SESSION['refresh_token'] = $data['refresh_token'];
            $_SESSION['access_token_expires_at'] = time() + $data['expires_in'];

            global $logger;
            $logger->info("Access token refreshed successfully.");
        } else {
            $logger->error("Failed to refresh access token with status code: {$response->getStatusCode()}");
        }
    } catch (\Exception $e) {
        $logger->error("An error occurred while refreshing the access token: " . $e->getMessage());
    }
}
