```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <mutex>
#include <thread>
#include <rapidjson/document.h>
#include <rapidjson/writer.h>
#include <rapidjson/stringbuffer.h>
#include <sqlite3.h>

struct Node {
    int key;
    std::string value;

    // Serialize a node to JSON
    void serialize(rapidjson::Value& obj, rapidjson::Document::AllocatorType& allocator) const {
        rapidjson::Value k_obj(kNumberType);
        k_obj.SetInt(key);

        rapidjson::Value v_obj(kStringType);
        v_obj.SetString(value.c_str(), value.size(), allocator);

        obj.AddMember("key", k_obj, allocator);
        obj.AddMember("value", v_obj, allocator);
    }

    // Deserialize a node from JSON
    static Node deserialize(const rapidjson::Value& obj) {
        return {obj["key"].GetInt(), obj["value"].GetString()};
    }
};

class NodeList {
private:
    std::vector<Node> nodes;
    mutable std::mutex mtx;

public:
    void loadFromFile(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) throw std::runtime_error("Could not open file");

        int key;
        std::string value;
        while (file >> key >> value) {
            nodes.push_back({key, value});
        }
    }

    void resizeIfNeeded() {
        std::lock_guard<std::mutex> lock(mtx);
        if (nodes.size() > 100) { // Example threshold
            nodes.resize(nodes.capacity() * 2); // Double the capacity
        }
    }

    rapidjson::Document serializeToJSON(rapidjson::Document::AllocatorType& allocator) const {
        rapidjson::Value arr(rapidjson::kArrayType);
        for (const auto& node : nodes) {
            rapidjson::Value obj(rapidjson::kObjectType);
            node.serialize(obj, allocator);
            arr.PushBack(obj, allocator);
        }

        rapidjson::Document doc;
        doc.SetArray();
        *doc.GetArray() = std::move(arr);

        return doc;
    }

    void deserializeFromJSON(const rapidjson::Document& doc) {
        for (const auto& value : doc.GetArray()) {
            nodes.push_back(Node::deserialize(value));
        }
    }

    void addNode(int key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mtx);
        nodes.emplace_back(key, value);
    }

    void removeNode(int key) {
        std::lock_guard<std::mutex> lock(mtx);
        nodes.erase(std::remove_if(nodes.begin(), nodes.end(),
            [key](const Node& node) { return node.key == key; }), nodes.end());
    }

    void updateNode(int key, const std::string& newValue) {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& node : nodes) {
            if (node.key == key) {
                node.value = newValue;
                break;
            }
        }
    }
};

class Logger {
public:
    void log(const std::string& message) {
        std::ofstream logFile("log.txt", std::ios_base::app);
        logFile << message << std::endl;
    }
};

void databaseThreadFunction(sqlite3* db, const NodeList& nodeList, Logger& logger) {
    char* errMsg = nullptr;
    for (const auto& node : nodeList.nodes) {
        int rc = sqlite3_exec(db,
            ("INSERT INTO Nodes (key, value) VALUES (?, ?);").c_str(),
            [](void*, int argc, char** argv, char**) -> int { return 0; },
            &node.key,
            &errMsg);

        if (rc != SQLITE_OK) {
            logger.log(std::string("Database error: ") + errMsg);
            sqlite3_free(errMsg);
        } else {
            logger.log("Node inserted into database.");
        }
    }
}

void initializeDatabase(sqlite3*& db) {
    int rc = sqlite3_open(":memory:", &db);
    if (rc) throw std::runtime_error("Can't open database");

    const char* sqlCreateTable = "CREATE TABLE Nodes (key INTEGER PRIMARY KEY, value TEXT);";
    char* errMsg;
    if (sqlite3_exec(db, sqlCreateTable, nullptr, 0, &errMsg) != SQLITE_OK) {
        sqlite3_free(errMsg);
        throw std::runtime_error("SQL error: failed to create table");
    }
}

int main() {
    try {
        NodeList nodeList;
        Logger logger;

        // Load nodes from a file
        nodeList.loadFromFile("config.txt");

        // Initialize SQLite database
        sqlite3* db = nullptr;
        initializeDatabase(db);

        std::thread dbThread(databaseThreadFunction, db, std::ref(nodeList), std::ref(logger));

        nodeList.addNode(101, "New Node");
        nodeList.updateNode(1, "Updated Value");
        nodeList.removeNode(2);

        logger.log("Performed operations on NodeList.");

        // Serialize to JSON
        rapidjson::Document d;
        rapidjson::Document::AllocatorType& allocator = d.GetAllocator();
        auto jsonDoc = nodeList.serializeToJSON(allocator);

        std::string jsonString;
        {
            rapidjson::StringBuffer buffer;
            rapidjson::Writer<rapidjson::StringBuffer> writer(buffer);
            jsonDoc.Accept(writer);
            jsonString = buffer.GetString();
        }

        logger.log("Serialized NodeList to JSON.");

        // Example usage of resizing
        for (int i = 0; i < 150; ++i) {
            nodeList.addNode(i, "Value" + std::to_string(i));
        }

        nodeList.resizeIfNeeded();

        dbThread.join();
        sqlite3_close(db);

    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
    }

    return 0;
}
