import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

// External Dependencies (to be added in build.gradle or pom.xml)
// dependencies {
//     implementation 'com.fasterxml.jackson.core:jackson-databind:2.12.5'
// }

public class PokemonService {

    private final ExecutorService executor;
    private Map<String, List<String>> typeWeaknesses = new HashMap<>();
    private static final String API_URL = "https://pokeapi.co/api/v2/pokemon/";

    public PokemonService() {
        this.executor = Executors.newFixedThreadPool(10);
        loadWeaknessesConfig();
    }

    // Load weaknesses from a configuration file
    private void loadWeaknessesConfig() {
        // Assuming the config is loaded here, for example:
        typeWeaknesses.put("Fire", Arrays.asList("Water", "Ground"));
        typeWeaknesses.put("Water", Arrays.asList("Electric", "Grass"));
        // Add other types as necessary
    }

    public CompletableFuture<Optional<PokemonReport>> getPokemonReportAsync(String pokemonName) {
        return CompletableFuture.supplyAsync(() -> fetchPokemon(pokemonName), executor)
                .thenApply(this::processPokemonData)
                .exceptionally(ex -> {
                    System.err.println("Error fetching Pokemon data: " + ex.getMessage());
                    return Optional.empty();
                });
    }

    private Pokemon fetchPokemon(String pokemonName) throws IOException, InterruptedException {
        URL url = new URL(API_URL + pokemonName.toLowerCase());
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        // Handle rate limits and retries
        int attempt = 0;
        while (attempt < 3) {
            try {
                connection.connect();
                if (connection.getResponseCode() == HttpURLConnection.HTTP_OK) {
                    return parsePokemon(connection.getInputStream());
                } else if (connection.getResponseCode() == 429) { // Rate limit
                    Thread.sleep(1000);
                }
            } catch (IOException | InterruptedException e) {
                attempt++;
                Thread.sleep(attempt * 1000);
            }
        }

        throw new IOException("Failed to fetch data for " + pokemonName);
    }

    private Pokemon parsePokemon(InputStream inputStream) throws IOException {
        // Use Jackson or any other JSON library to parse the input stream
        return new ObjectMapper().readValue(inputStream, Pokemon.class);
    }

    private PokemonReport processPokemonData(Pokemon pokemon) {
        List<String> weaknesses = determineWeaknesses(pokemon.getType());
        return new PokemonReport(pokemon.getName(), weaknesses);
    }

    private List<String> determineWeaknesses(List<String> types) {
        return types.stream()
                .flatMap(type -> typeWeaknesses.getOrDefault(type, Collections.emptyList()).stream())
                .distinct()
                .collect(Collectors.toList());
    }

    public String generateHtmlReport(PokemonReport report) {
        StringBuilder html = new StringBuilder();
        html.append("<html><head><title>Pokémon Report</title></head><body>")
            .append("<h1>").append(report.getName()).append(" Weaknesses</h1>")
            .append("<ul>");

        for (String weakness : report.getWeaknesses()) {
            html.append("<li>").append(weakness).append("</li>");
        }

        html.append("</ul></body></html>");
        return html.toString();
    }

    public void shutdown() {
        executor.shutdown();
    }

    // Placeholder classes
    static class Pokemon {
        private String name;
        private List<String> types;

        public String getName() { return name; }
        public List<String> getType() { return types; }
    }

    static class PokemonReport {
        private final String name;
        private final List<String> weaknesses;

        public PokemonReport(String name, List<String> weaknesses) {
            this.name = name;
            this.weaknesses = weaknesses;
        }

        public String getName() { return name; }
        public List<String> getWeaknesses() { return weaknesses; }
    }
}
