<?php

class ClinicManager {
    private $pdo;
    private $rateLimit = [];
    private $registry = [];

    public function __construct($dsn, $username, $password) {
        try {
            $this->pdo = new PDO($dsn, $username, $password);
            $this->pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        } catch (PDOException $e) {
            $this->logError("Database connection error: " . $e->getMessage());
        }
    }

    public function updateClinicStatus($clinicId, $status, $ipAddress, $timestamp) {
        if (!$this->validateRateLimit($clinicId)) {
            return ['error' => 'Rate limit exceeded'];
        }

        if (!$this->isValidClinicId($clinicId)) {
            return ['error' => 'Invalid clinic ID'];
        }

        try {
            $this->pdo->beginTransaction();

            $stmt = $this->pdo->prepare('UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?');
            $stmt->execute([$status, $ipAddress, $timestamp, $clinicId]);

            if ($stmt->rowCount() === 0) {
                throw new Exception("Clinic not found or no change in data");
            }

            $this->logChange($clinicId, $status, $ipAddress, $timestamp);

            $this->pdo->commit();
            return ['success' => true];
        } catch (Exception $e) {
            $this->pdo->rollBack();
            $this->logError("Update failed: " . $e->getMessage());
            return ['error' => 'Database update error'];
        }
    }

    private function validateRateLimit($clinicId) {
        if (!isset($this->rateLimit[$clinicId])) {
            $this->rateLimit[$clinicId] = 0;
        }

        $currentTime = time();
        if ($currentTime - $this->rateLimit[$clinicId] < 60) { // 1 request per minute
            return false;
        }
        $this->rateLimit[$clinicId] = $currentTime;
        return true;
    }

    private function isValidClinicId($clinicId) {
        try {
            $stmt = $this->pdo->prepare('SELECT 1 FROM clinics WHERE id = ?');
            $stmt->execute([$clinicId]);
            return $stmt->fetchColumn() !== false;
        } catch (Exception $e) {
            $this->logError("Validation error: " . $e->getMessage());
            return false;
        }
    }

    private function logChange($clinicId, $status, $ipAddress, $timestamp) {
        // Implement integration with external logging service
        file_put_contents('clinic_changes.log', json_encode([
            'clinic_id' => $clinicId,
            'status' => $status,
            'ip_address' => $ipAddress,
            'timestamp' => $timestamp,
            'logged_at' => date('Y-m-d H:i:s')
        ]) . PHP_EOL, FILE_APPEND);
    }

    private function logError($message) {
        // Implement integration with external logging service
        file_put_contents('clinic_errors.log', json_encode([
            'error_message' => $message,
            'logged_at' => date('Y-m-d H:i:s')
        ]) . PHP_EOL, FILE_APPEND);
    }

    public function toJson($clinicData) {
        return json_encode($clinicData);
    }

    public function fromJson($jsonString) {
        return json_decode($jsonString, true);
    }

    public function addFactoryFunction($id, $callback) {
        if (is_callable($callback)) {
            $this->registry[$id] = $callback;
        }
    }

    public function createInstance($id, $data) {
        if (isset($this->registry[$id])) {
            return call_user_func($this->registry[$id], $data);
        }
        throw new Exception("No factory function for ID: " . $id);
    }
}

