fn compile_rust_source(file_path: &Path) -> i32 {
    if !file_path.exists() {
        eprintln!("Error: Source file does not exist.");
        return 1;
    }

    let logger = LOGGER.clone();
    let start_time = Instant::now();

    rustc_driver::catch_with_exit_code(move || {
        logger.log(&format!("Compilation started at {:?}", start_time));
        let initial_rss = get_resident_set_size();

        if let Err(e) = Command::new("rustc")
            .arg(file_path)
            .status()
            .map_err(|e| eprintln!("Error running rustc: {}", e))
        {
            early_error(&format!("Compilation error: {:?}", e));
            return 1;
        }

        let elapsed_time = start_time.elapsed();
        let final_rss = get_resident_set_size();

        logger.log(&format!(
            "Compilation finished at {:?}, Duration: {:?}, RSS change: {}",
            Instant::now(),
            elapsed_time,
            final_rss - initial_rss
        ));
    })
}

fn early_error(message: &str) {
    LOGGER.lock().unwrap().log(message);
}

pub fn run_compiler(file_path_str: &str) -> i32 {
    let file_path = PathBuf::from(file_path_str);

    if !file_path.is_file() {
        eprintln!("Error: Invalid path or not a file.");
        return 1;
    }

    compile_rust_source(&file_path)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <source_file>", args[0]);
        std::process::exit(1);
    }

    run_compiler(&args[1])
}
```

