    [ApiController]
    [Route("[controller]")]
    public class ContentController : ControllerBase
    {
        private readonly IContentService _contentService;
        private readonly ICachingService _cachingService;

        public ContentController(IContentService contentService, ICachingService cachingService)
        {
            _contentService = contentService ?? throw new ArgumentNullException(nameof(contentService));
            _cachingService = cachingService ?? throw new ArgumentNullException(nameof(cachingService));
        }

        [HttpPost("UpdateElement")]
        public async Task<IActionResult> UpdateElement([FromBody] ContentRequest request)
        {
            if (!ModelState.IsValid || string.IsNullOrWhiteSpace(request.PageSectionId) ||
                !Guid.TryParse(request.ElementId, out var elementId))
            {
                return BadRequest(new { message = "Invalid Page Section ID or Element ID" });
            }

            try
            {
                // Validate HTML content (pseudo validation method)
                if (!IsValidHtml(request.HtmlContent))
                {
                    return BadRequest(new { message = "Malformed HTML Content" });
                }

                bool updateSuccess = await _contentService.UpdateElementAsync(elementId, request.PageSectionId, request.HtmlContent);

                if (!updateSuccess)
                {
                    return StatusCode(500, new { message = "Failed to Update Element" });
                }

                // Asynchronously notify cache invalidation service
                try
                {
                    await _cachingService.InvalidateCacheAsync(request.PageSectionId);
                }
                catch (Exception ex)
                {
                    // Log and handle cache service error
                    return StatusCode(500, new { message = $"Cache Invalidation Failed: {ex.Message}" });
                }

                return Ok(new { message = "Update Successful", refreshPage = true });
            }
            catch (Exception ex)
            {
                // General exception handling
                return StatusCode(500, new { message = $"An unexpected error occurred: {ex.Message}" });
            }
        }

        private bool IsValidHtml(string htmlContent)
        {
            // Implement HTML validation logic here
            // For example purposes, assume it always returns true
            return !string.IsNullOrWhiteSpace(htmlContent);
        }
    }

    public class ContentRequest
    {
        public string PageSectionId { get; set; }
        public string ElementId { get; set; }
        public string HtmlContent { get; set; }
    }

    public interface IContentService
    {
        Task<bool> UpdateElementAsync(Guid elementId, string pageSectionId, string htmlContent);
    }

    public interface ICachingService
    {
        Task InvalidateCacheAsync(string pageSectionId);
    }
}
