import os
import time
import tempfile
import shutil
from threading import Lock
from ctypes import CDLL, c_double, c_int, POINTER

# Python Function for Directory Creation with Mutex and Retry Mechanism
def create_directory_with_env_var(dir_name, parent_dir=None):
    # Default to current directory if no parent is specified
    base_path = parent_dir or os.getcwd()
    target_path = os.path.join(base_path, dir_name)

    retry_attempts = 5
    delay_between_retries = 1

    mutex = Lock()

    def create_directory():
        nonlocal target_path
        attempts = 0

        while attempts < retry_attempts:
            try:
                with mutex:
                    if not os.path.exists(target_path):
                        os.makedirs(target_path)
                        break
            except Exception as e:
                print(f"Attempt {attempts + 1} failed: {e}")
                time.sleep(delay_between_retries)
            finally:
                attempts += 1

        if attempts == retry_attempts:
            raise RuntimeError("Failed to create directory after several retries.")

    # Temporary file for cleanup
    with tempfile.TemporaryDirectory(dir=base_path) as temp_dir:
        try:
            create_directory()

            os.environ["MY_DIR_PATH"] = target_path

            # Call the C function from here if necessary using ctypes

        except Exception as e:
            print(f"An error occurred: {e}")
            raise
        finally:
            # Cleanup is handled by tempfile context manager
            pass

# C Code for Filtering Transactions
c_code = """
#include <stdlib.h>

typedef struct {
    int id;
    double weighted_sum;
    time_t timestamp; // Assuming UNIX epoch timestamp
} Transaction;

typedef struct {
    double max_weighted_sum;
    int transaction_id;
} Metrics;

void filter_transactions(Transaction* transactions, int count, Metrics* metrics) {
    double age_threshold = 3600.0; // 1 hour in seconds
    int recent_transaction_count_limit = 100;
    time_t current_time = time(NULL);

    metrics->max_weighted_sum = 0.0;
    metrics->transaction_id = -1;

    for (int i = 0; i < count; ++i) {
        double age = difftime(current_time, transactions[i].timestamp);
        if (age <= age_threshold) {
            int recent_count = 0;
            for (int j = 0; j < count; ++j) {
                if (difftime(transactions[j].timestamp, transactions[i].timestamp) <= 3.0) {
                    recent_count++;
                }
            }

            if (recent_count <= recent_transaction_count_limit && 
                transactions[i].weighted_sum > metrics->max_weighted_sum) {

                metrics->max_weighted_sum = transactions[i].weighted_sum;
                metrics->transaction_id = transactions[i].id;
            }
        }
    }
}
"""

# Save C code to a file and compile it
with open("filter.c", "w") as c_file:
    c_file.write(c_code)

os.system("gcc -shared -o filter.so -fPIC filter.c")

# Load the compiled shared library
lib = CDLL("./filter.so")

def call_c_filter(transactions):
    class Metrics(ctypes.Structure):
        _fields_ = [("max_weighted_sum", c_double), ("transaction_id", c_int)]

    metrics_array = (Metrics * 1)()
    metrics_ptr = ctypes.cast(metrics_array, POINTER(Metrics))

    transaction_array_type = Transaction * len(transactions)
    transaction_array = transaction_array_type(*transactions)

    lib.filter_transactions(transaction_array, len(transactions), metrics_ptr)

    return metrics_ptr[0].max_weighted_sum, metrics_ptr[0].transaction_id

# Assuming Transaction is a ctypes structure mirroring the C struct
Transaction = CDLL(None).Transaction

# Example usage:
if __name__ == "__main__":
    create_directory_with_env_var("example_dir")

    # Example transaction data
    transactions = [
        (1, 10.5, time.time() - 500), 
        (2, 20.0, time.time() - 1000),
        (3, 15.0, time.time() - 200)
    ]

    max_sum, trans_id = call_c_filter(transactions)
    print(f"Max Weighted Sum: {max_sum}, Transaction ID: {trans_id}")
