                    options.User.AllowedUserNameCharacters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._@+";
                })
                .Configure<LockoutOptions>(options =>
                {
                    options.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(5);
                    options.MaxFailedAccessAttempts = 5;
                });

            // Register RustComponent as a service
            services.AddSingleton<RustComponent>();

            // Other necessary services for cloud interaction, etc.
        }
