    public class FilenameManager
    {
        public void TransformAndUploadFiles()
        {
            string[] files = System.IO.Directory.GetFiles("path/to/files");
            foreach (var file in files)
            {
                string transformedFilename = TransformFilename(file);
                RetryLogic(() => UploadToCloud(transformedFilename), 3);
            }
        }

        private string TransformFilename(string originalFilename)
        {
            return string.Format("{0}.transformed", System.IO.Path.GetFileNameWithoutExtension(originalFilename));
        }

        private void UploadToCloud(string filename)
        {
            // Simulate cloud upload
            Console.WriteLine($"Uploading {filename} to cloud...");
        }

        private void RetryLogic(Action action, int maxAttempts)
        {
            int attempts = 0;
            while (attempts < maxAttempts)
            {
                try
                {
                    action();
                    return;
                }
                catch (Exception ex) when (ex is IOException || ex is TimeoutException)
                {
                    Console.WriteLine($"Attempt {++attempts} failed: {ex.Message}");
                    if (attempts == maxAttempts) throw;
                    System.Threading.Thread.Sleep(1000); // Wait before retry
                }
            }
        }
    }

    public class RustComponent
    {
        [DllImport("rust_component.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern void ExecuteTests(string moduleName);

        public void ExecuteTests(string moduleName)
        {
            ExecuteTests(moduleName);
        }
    }

