        public static IntPtr CreateNewStateList(StateListDelegate createStateList)
        {
            int[] stateArray = { /* Example data */ };
            IntPtr fsaPtr = /* Pointer to FSA */;

            int numStates = stateArray.Length;
            int lastState = 0; // Example value

            return createStateList(stateArray, numStates, fsaPtr, lastState);
        }

        public static unsafe IntPtr CreateStateList(int* states, int numStates, IntPtr fsa, int lastState)
        {
            if (numStates == 0) return null;

            int size = sizeof(IntPtr) * numStates;
            IntPtr stateList = Marshal.AllocHGlobal(size);

            if (stateList == IntPtr.Zero) return null;

            for (int i = 0; i < numStates; i++)
            {
                *(IntPtr*)(stateList + i * sizeof(IntPtr)) = new IntPtr(states[i]);
            }

            // Update the 'next' pointer of the last state
            int* fsaStates = (int*)fsa;
            fsaStates[lastState] = (int)stateList;

            return stateList;
        }
    }
}
