### C# Code: File Encryption/Decryption Using AES-GCM

```csharp
using System;
using System.IO;
using System.Security.Cryptography;

public class AesGcmEncryptionService
{
    private readonly KeyManagementService _keyManager = new KeyManagementService();

    public async Task<EncryptionMetadata> EncryptFileAsync(string filePath)
    {
        byte[] key = await _keyManager.RetrieveKeyAsync();

        using (var aesGcm = new AesGcm(key))
        {
            var nonce = new byte[AesGcm.NonceByteSizes.MaxSize];
            RandomNumberGenerator.Fill(nonce);

            int tagLength = 16;
            byte[] encryptedData, tag;

            using (var inputStream = File.OpenRead(filePath))
            {
                using (var outputStream = new MemoryStream())
                {
                    await aesGcm.EncryptAsync(
                        nonce,
                        inputStream,
                        outputStream.ToArray(),
                        tag,
                        tagLength);

                    encryptedData = outputStream.ToArray();
                }
            }

            return new EncryptionMetadata
            {
                Nonce = nonce,
                Tag = tag,
                Iv = null // GCM doesn't use a separate IV, nonce is used.
            };
        }
    }

    public async Task<byte[]> DecryptFileAsync(string filePath, EncryptionMetadata metadata)
    {
        byte[] key = await _keyManager.RetrieveKeyAsync();

        using (var aesGcm = new AesGcm(key))
        {
            using (var inputStream = File.OpenRead(filePath))
            {
                var decryptedData = new byte[inputStream.Length];

                if (!await aesGcm.DecryptAsync(metadata.Nonce, inputStream, decryptedData, metadata.Tag))
                    throw new CryptographicException("Decryption failed.");

                return decryptedData;
            }
        }
    }

    private class KeyManagementService
    {
        public Task<byte[]> RetrieveKeyAsync()
        {
            // Simulate key retrieval from a secure key management service.
            byte[] key = new byte[32]; // Example key size for AES-256.
            RandomNumberGenerator.Fill(key);
            return Task.FromResult(key);
        }
    }

    public class EncryptionMetadata
    {
        public byte[] Nonce { get; set; }
        public byte[] Tag { get; set; }
        public byte[] Iv { get; set; } // For compatibility, though not used in GCM.
    }
}
