### C Code: Semaphore Management

```c
#include <stdio.h>
#include <semaphore.h>
#include <stdlib.h>

// Function to create and delete a semaphore with an initial value.
void manageSemaphore(int initialValue) {
    sem_t *sem = sem_open("/my_semaphore", O_CREAT, 0644, initialValue);

    if (sem == SEM_FAILED) {
        perror("Failed to open semaphore");
        exit(EXIT_FAILURE);
    }

    // Example: Wait and signal the semaphore
    printf("Waiting on semaphore...\n");
    sem_wait(sem);

    printf("Semaphore acquired.\n");

    printf("Releasing semaphore...\n");
    sem_post(sem);

    // Close and unlink the semaphore after use
    if (sem_close(sem) == -1) {
        perror("Failed to close semaphore");
        exit(EXIT_FAILURE);
    }
    if (sem_unlink("/my_semaphore") == -1) {
        perror("Failed to unlink semaphore");
        exit(EXIT_FAILURE);
    }

    printf("Semaphore deleted.\n");
}

int main() {
    // Manage a semaphore with an initial value of 1.
    manageSemaphore(1);
    return 0;
}
```

