#[derive(Debug)]
struct CompilationResult {
    file_path: String,
    status: String,
    time_taken: f64,
    warnings: Vec<String>,
}

fn compile_sources(files: Vec<&Path>) -> Result<Vec<CompilationResult>, String> {
    let logger = CustomLogger::new();
    let results = Arc::new(Mutex::new(Vec::new()));

    files.par_iter().for_each(|file| {
        if !file.exists() || file.is_dir() {
            warn!(logger, "Invalid file path: {:?}", file);
            return;
        }

        let start_time = Instant::now();
        match compile_file(file) {
            Ok(warnings) => {
                let validation_result = validate_with_external_source(file);
                let elapsed = start_time.elapsed().as_secs_f64();

                let result = CompilationResult {
                    file_path: file.to_string_lossy().to_string(),
                    status: if validation_result { "Success" } else { "Failed Validation" },
                    time_taken: elapsed,
                    warnings,
                };

                results.lock().unwrap().push(result);
            }
            Err(e) => {
                error!(logger, "Compilation failed for {:?}: {}", file, e);
            }
        }
    });

    let compiled_results = Arc::try_unwrap(results)
        .map_err(|_| "Failed to unwrap results".to_string())?
        .into_inner()
        .expect("Could not lock results");

    Ok(compiled_results)
}

