                    format='%(asctime)s - %(levelname)s - %(message)s')

class WebServerRequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        try:
            # Call the C function to parse HTTP request
            parsed_request = c_parse_http_request(ctypes.c_char_p(self.requestline.encode('utf-8')))

            if parsed_request is None:
                self.send_error(400, "Bad Request")
                return

            # Process the parsed request (as an example, log it)
            logging.info(f"Parsed Request: {parsed_request}")

            self.send_response(200)
            self.end_headers()
            self.wfile.write(b"Hello, World!")
        except Exception as e:
            logging.error("Error handling GET request", exc_info=e)
            self.send_error(500, "Internal Server Error")

def configure_web_server(port, server_name, ssl_certificate):
    try:
        # Create the HTTP server
        server_address = ('', port)
        httpd = HTTPServer(server_address, WebServerRequestHandler)

        logging.info(f"Starting {server_name} on port {port}")

        def run_server():
            try:
                httpd.serve_forever()
            except Exception as e:
                logging.error("Error while serving", exc_info=e)

        # Start the server in a separate thread
        server_thread = threading.Thread(target=run_server)
        server_thread.daemon = True  # Daemonize thread to exit cleanly with main program
        server_thread.start()

    except OSError as e:
        logging.critical(f"Network Error: {e}", exc_info=True)
    except FileNotFoundError as e:
        logging.error(f"SSL Certificate not found: {ssl_certificate}", exc_info=True)
    except Exception as e:
        logging.critical("Unhandled error occurred", exc_info=e)

# Load C library
c_lib = ctypes.CDLL('./parse_http_request.so')

def c_parse_http_request(request_line):
    c_lib.parse_http_request.restype = ctypes.POINTER(ctypes.py_object)  # Assume a pointer to a Python object is returned
    result_ptr = c_lib.parse_http_request(request_line)

    if not result_ptr:
        return None

    try:
        parsed_result = ctypes.cast(result_ptr, ctypes.py_object).value
        return parsed_result
    except Exception as e:
        logging.error("Error parsing HTTP request", exc_info=e)
        return None

if __name__ == '__main__':
    configure_web_server(port=8080, server_name="MyServer", ssl_certificate="path/to/certificate.pem")
