#include <Python.h>
#include <stdio.h>

static PyObject* parse_http_request(PyObject *self, PyObject *args) {
    const char *request_line;

    if (!PyArg_ParseTuple(args, "s", &request_line)) {
        return NULL;
    }

    // Example parsing logic (to be implemented according to actual HTTP format)
    PyDictObject *parsed_dict = (PyDictObject *)PyDict_New();

    if (parsed_dict == NULL) {
        PyErr_SetString(PyExc_RuntimeError, "Failed to create dictionary");
        return NULL;
    }

    PyObject *method = PyUnicode_FromString("GET");  // Placeholder
    PyObject *path = PyUnicode_FromString("/index.html");  // Placeholder

    if (!method || !path) {
        Py_XDECREF(method);
        Py_XDECREF(path);
        Py_DECREF(parsed_dict);
        PyErr_SetString(PyExc_RuntimeError, "Failed to allocate memory for dictionary values");
        return NULL;
    }

    PyDict_SetItemString((PyObject *)parsed_dict, "Method", method);
    PyDict_SetItemString((PyObject *)parsed_dict, "Path", path);

    // Decrease reference counts as these will be added to the dict
    Py_DECREF(method);
    Py_DECREF(path);

    return (PyObject*)parsed_dict;
}

static PyMethodDef ParseMethods[] = {
    {"parse_http_request", parse_http_request, METH_VARARGS, "Parse an HTTP request line"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef pyparser_module = {
    PyModuleDef_HEAD_INIT,
    "parse_http_request",
    NULL,
    -1,
    ParseMethods
};

PyMODINIT_FUNC PyInit_parse_http_request(void) {
    return PyModule_Create(&pyparser_module);
}

