```rust
use std::env;
use std::fs::{self, DirEntry};
use std::io;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use tempfile::TempDir;
use log::{info, error};
use std::time::{Duration, Instant};

// Define a trait for plugin system integration
trait CICDPlugin {
    fn before_directory_management(&self);
    fn after_directory_management(&self);
}

struct FileManagementUtility {
    work_dir: Arc<Mutex<WorkDir>>,
    plugins: Vec<Box<dyn CICDPlugin + Send + Sync>>,
}

enum WorkDir {
    Persistent(PathBuf),
    Temporary(TempDir),
}

impl FileManagementUtility {
    pub fn new(plugins: Vec<Box<dyn CICDPlugin + Send + Sync>>) -> io::Result<Self> {
        let work_dir = Self::get_or_create_work_dir()?;
        Ok(Self {
            work_dir: Arc::new(Mutex::new(work_dir)),
            plugins,
        })
    }

    fn get_or_create_work_dir() -> io::Result<WorkDir> {
        if let Ok(dir) = env::var("WORK_DIR") {
            let path = Path::new(&dir);
            if path.exists() && path.is_dir() && fs::metadata(&path)?.permissions().readonly() == false {
                info!("Using existing WORK_DIR: {:?}", dir);
                return Ok(WorkDir::Persistent(PathBuf::from(dir)));
            } else {
                error!("WORK_DIR is invalid or inaccessible.");
            }
        }

        let tmp_dir = TempDir::new_in("/tmp", "ci_pipeline_")?;
        info!("Created temporary directory: {:?}", tmp_dir.path());
        Ok(WorkDir::Temporary(tmp_dir))
    }

    pub fn execute(&self) {
        for plugin in &self.plugins {
            plugin.before_directory_management();
        }

        let work_dir = self.work_dir.lock().unwrap();

        // Placeholder for pipeline execution logic

        for plugin in &self.plugins {
            plugin.after_directory_management();
        }
    }

    pub fn cleanup_workdir(&self) -> io::Result<()> {
        if let Ok(mut work_dir) = self.work_dir.try_lock() {
            match *work_dir {
                WorkDir::Temporary(ref tmp_dir) => {
                    info!("Cleaning up temporary directory: {:?}", tmp_dir.path());
                    drop(tmp_dir); // Explicitly drop the TempDir to ensure cleanup
                }
                WorkDir::Persistent(_) => {
                    info!("Persistent directory will not be cleaned automatically.");
                }
            }
        }
        Ok(())
    }

    pub fn start_cleanup_timer(&self, interval: Duration) -> io::Result<()> {
        std::thread::spawn(move || loop {
            std::thread::sleep(interval);
            if let Err(e) = self.cleanup_workdir() {
                error!("Failed to clean up work directory: {}", e);
            }
        });
        Ok(())
    }
}

// Example plugin for integration
struct JenkinsPlugin;

impl CICDPlugin for JenkinsPlugin {
    fn before_directory_management(&self) {
        info!("Jenkins Plugin: Before directory management.");
    }

    fn after_directory_management(&self) {
        info!("Jenkins Plugin: After directory management.");
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;
    use std::sync::mpsc;

    #[test]
    fn test_work_dir_creation() -> io::Result<()> {
        if let Ok(dir) = env::var("WORK_DIR") {
            env::remove_var("WORK_DIR");
        }

        // Create a temporary directory for testing
        let tmp_dir = tempdir()?;
        env::set_var("WORK_DIR", tmp_dir.path().to_str().unwrap());

        let utility = FileManagementUtility::new(vec![Box::new(JenkinsPlugin)])?;

        assert!(matches!(
            *utility.work_dir.lock().unwrap(),
            WorkDir::Persistent(ref path) if path == tmp_dir.path()
        ));

        // Cleanup
        env::remove_var("WORK_DIR");
        Ok(())
    }
}

fn main() {
    env_logger::init();

    let plugins = vec![Box::new(JenkinsPlugin)];
    let utility = FileManagementUtility::new(plugins).expect("Failed to initialize utility");

    utility.execute();

    // Start cleanup timer with a 10-minute interval
    if let Err(e) = utility.start_cleanup_timer(Duration::from_secs(600)) {
        error!("Failed to start cleanup timer: {}", e);
    }
}
```

