public class User : IdentityUser
{
    // Custom properties can be added here.
}

public class Role : IdentityRole
{
    // Custom role-based logic can be added here.
}

public class ApplicationDbContext : Microsoft.AspNetCore.Identity.EntityFrameworkCore.IdentityDbContext<User, Role>
{
