```php
<?php

class SecureTokenManager {
    private $characterSets = [
        'alnum' => 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',
        'alpha' => 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ',
        'num'   => '0123456789',
    ];

    public function __construct($algorithm = PASSWORD_BCRYPT) {
        if (!in_array($algorithm, [PASSWORD_BCRYPT, PASSWORD_ARGON2ID])) {
            throw new InvalidArgumentException("Unsupported hashing algorithm.");
        }
        $this->hashAlgorithm = $algorithm;
    }

    public function generateToken($length = 32, $charset = 'alnum') {
        if (!isset($this->characterSets[$charset])) {
            throw new InvalidArgumentException("Invalid character set.");
        }

        $set = $this->characterSets[$charset];
        $token = '';
        for ($i = 0; $i < $length; $i++) {
            $index = random_int(0, strlen($set) - 1);
            $token .= $set[$index];
        }

        return bin2hex($token); // Ensure URL safety
    }

    public function hashPassword($password) {
        if (empty($password)) {
            throw new InvalidArgumentException("Password cannot be empty.");
        }

        return password_hash($password, $this->hashAlgorithm);
    }

    public function verifyPassword($enteredPassword, $storedHash) {
        return password_verify($enteredPassword, $storedHash);
    }

    // Additional methods for session management and user validation
    public function createSession($userId, $token) {
        try {
            $db = new MongoDB\Client("mongodb://localhost:27017");
            $collection = $db->user_sessions;

            $result = $collection->insertOne([
                'user_id' => $userId,
                'session_token' => $token,
                'created_at' => (new DateTime())->format(DATE_ATOM)
            ]);

            return $result->getInsertedId();
        } catch (\Exception $e) {
            // Handle database connection errors
            error_log($e->getMessage());
            throw new RuntimeException("Database operation failed.");
        }
    }

    public function validateToken($token) {
        if (empty($token)) {
            throw new InvalidArgumentException("Invalid token.");
        }

        return strlen($token) === 64; // Assuming hex representation length
    }

    public function authenticateUser($username, $password) {
        try {
            $db = new MongoDB\Client("mongodb://localhost:27017");
            $collection = $db->users;

            $user = $collection->findOne(['username' => $username]);

            if (!$user || !$this->verifyPassword($password, $user['password'])) {
                return false;
            }

            $token = $this->generateToken();
            $this->createSession($user['_id'], $token);

            return true; // Authentication successful
        } catch (\Exception $e) {
            error_log($e->getMessage());
            return false; // Handle errors gracefully
        }
    }
}

