```javascript
const fs = require('fs').promises;
const path = require('path');

async function readDirectoryContents(directoryPath) {
    try {
        const files = await fs.readdir(directoryPath, { withFileTypes: true });
        let contents = '';

        for (let file of files) {
            const fullPath = path.join(directoryPath, file.name);
            if (file.isDirectory()) {
                // Recursively process subdirectories
                contents += await readDirectoryContents(fullPath) + '\n';
            } else if (file.isFile()) {
                // Read the content of each file
                const data = await fs.readFile(fullPath, 'utf8');
                contents += `${fullPath}: ${data}\n`;
            }
        }

        return contents.trim();
    } catch (error) {
        console.error('Error reading directory:', error);
        throw new Error(`Failed to read directory: ${directoryPath}`);
    }
}

// Example usage
readDirectoryContents('./example_directory').then(console.log).catch(console.error);

```

