```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;

public static class SqlHelper
{
    private static readonly IMemoryCache CommandCache = new MemoryCache(new MemoryCacheOptions());
    private const int CacheSizeLimit = 100; // Configurable threshold

    public static async Task<IDataReader> ExecuteParameterizedQueryAsync(
        SqlConnection connection, string sqlCommand, List<object> parameters, bool returnAsList = false)
    {
        if (connection == null) throw new ArgumentNullException(nameof(connection));
        if (string.IsNullOrEmpty(sqlCommand)) throw new ArgumentException("SQL command cannot be null or empty", nameof(sqlCommand));

        try
        {
            // Check cache for existing command
            DbCommand cachedCommand;
            var cacheKey = $"{sqlCommand}-{string.Join(",", parameters.Select(p => p?.ToString() ?? "null"))}";
            if (!CommandCache.TryGetValue(cacheKey, out cachedCommand))
            {
                // Create a new parameterized SQL command
                using (var cmd = connection.CreateCommand())
                {
                    cmd.CommandText = sqlCommand;

                    for (int i = 0; i < parameters.Count; i++)
                    {
                        var param = cmd.CreateParameter();
                        param.ParameterName = $"@param{i}";
                        param.Value = parameters[i] ?? DBNull.Value;

                        if (parameters[i] is int) param.DbType = DbType.Int32;
                        else if (parameters[i] is string) param.DbType = DbType.String;
                        else if (parameters[i] is DateTime) param.DbType = DbType.DateTime;
                        // Add more types as needed

                        cmd.Parameters.Add(param);
                    }

                    // Cache the command
                    CommandCache.Set(cacheKey, cmd, new MemoryCacheEntryOptions { Size = 1 });

                    // Limit cache size to avoid excessive memory usage
                    if (CommandCache.Count > CacheSizeLimit)
                    {
                        var keysToRemove = CommandCache.Select(kvp => kvp.Key).Take(CommandCache.Count - CacheSizeLimit);
                        foreach (var key in keysToRemove) CommandCache.Remove(key);
                    }

                    cachedCommand = cmd;
                }
            }

            // Execute the command asynchronously
            using (var reader = await cachedCommand.ExecuteReaderAsync())
            {
                if (!returnAsList)
                {
                    return reader;
                }

                var resultList = new List<object>();
                while (await reader.ReadAsync())
                {
                    // Convert each row into an object, e.g., a dictionary or a custom type
                    var rowObject = new Dictionary<string, object>();
                    for (int i = 0; i < reader.FieldCount; i++)
                    {
                        rowObject[reader.GetName(i)] = reader.GetValue(i);
                    }
                    resultList.Add(rowObject);
                }

                return resultList;
            }
        }
        catch (Exception ex)
        {
            // Log the error
            Console.Error.WriteLine($"Error executing SQL command: {ex.Message}");
            throw; // Re-throw to allow higher-level handling if necessary
        }
    }
}
```

This code defines a method `ExecuteParameterizedQueryAsync` that meets your requirements. It uses an in-memory cache to store and retrieve precompiled SQL commands for improved performance, handles various data types for parameters, and supports asynchronous execution. The code includes error handling and logging mechanisms as well.

```java
import org.springframework.web.multipart.MultipartFile;
import java.io.IOException;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class FileUploadProcessor {

    private static final Logger logger = Logger.getLogger(FileUploadProcessor.class.getName());

    public void processFileUploads(Queue<MultipartFile> uploadQueue, int maxConcurrency) {
        ExecutorService executorService = Executors.newFixedThreadPool(maxConcurrency);

        try (CompletionService<Void> completionService = new ExecutorCompletionService<>(executorService)) {
            while (!uploadQueue.isEmpty()) {
                MultipartFile file = uploadQueue.poll();
                if (file != null) {
                    long startTime = System.currentTimeMillis();
                    completionService.submit(() -> processFile(file, startTime));
                }
            }

            int completedUploads = 0;
            while (completedUploads < uploadQueue.size()) {
                try {
                    Future<Void> future = completionService.take(); // Blocks until a file is processed
                    future.get(); // Wait for the file to be processed
                    completedUploads++;
                } catch (InterruptedException | ExecutionException e) {
                    logger.log(Level.SEVERE, "Error during file upload processing", e);
                }
            }

        } finally {
            executorService.shutdown();
            try {
                if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                    executorService.shutdownNow();
                }
            } catch (InterruptedException e) {
                executorService.shutdownNow();
            }
        }
    }

    private void processFile(MultipartFile file, long startTime) {
        String fileName = file.getOriginalFilename();
        long fileSize = file.getSize();

        try {
            logger.info("Starting upload: " + fileName + ", Size: " + fileSize);

            // Simulate file processing (e.g., saving to disk or cloud storage)
            Thread.sleep(1000); // Replace with actual file I/O operations

            long duration = System.currentTimeMillis() - startTime;
            logger.info("Completed upload: " + fileName + ", Duration: " + duration + "ms");

        } catch (IOException | InterruptedException e) {
            logger.log(Level.SEVERE, "Failed to process file: " + fileName, e);
        }
    }
}
```

### Key Points:
- **ExecutorService**: Manages a fixed thread pool for handling concurrent uploads.
- **CompletionService**: Facilitates efficient retrieval of completed tasks and handles blocking until tasks are done.
- **Logging**: Tracks the start and completion times, sizes, and any exceptions encountered during file processing.
- **Resource Management**: Ensures that resources like threads are properly closed after use to prevent leaks.

