```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <curl/curl.h>
#include <string.h>

#define MAX_THREADS 10
#define URL_LIST_SIZE 100

typedef struct {
    char *url;
    int thread_id;
} ThreadArgs;

typedef struct {
    char *data;
    size_t size;
} MemoryStruct;

static pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t queue_cv = PTHREAD_COND_INITIALIZER;

// A simple linked list to hold URLs
typedef struct URLNode {
    char *url;
    struct URLNode *next;
} URLNode;

URLNode *url_list = NULL; // Head of the list

// Queue for managing URLs and thread work
pthread_mutex_t queue_lock;
pthread_cond_t queue_not_empty;
int queue_count = 0;
ThreadArgs queue[MAX_THREADS];

void enqueue(ThreadArgs arg) {
    pthread_mutex_lock(&queue_lock);
    while (queue_count == MAX_THREADS) {
        pthread_cond_wait(&queue_not_empty, &queue_lock);
    }
    queue[queue_count++] = arg;
    pthread_cond_signal(&queue_cv);
    pthread_mutex_unlock(&queue_lock);
}

ThreadArgs dequeue() {
    ThreadArgs arg;
    pthread_mutex_lock(&queue_lock);
    while (queue_count == 0) {
        pthread_cond_wait(&queue_not_empty, &queue_lock);
    }
    arg = queue[0];
    for (int i = 1; i < queue_count; i++) {
        queue[i - 1] = queue[i];
    }
    queue_count--;
    pthread_mutex_unlock(&queue_lock);
    return arg;
}

// Thread function to fetch data using libcurl
void *fetch_data(void *arg) {
    struct MemoryStruct chunk;
    chunk.data = malloc(1); // Initial size is unknown, will grow as needed
    chunk.size = 0;

    ThreadArgs args = *(ThreadArgs *)arg;
    free(arg);

    CURL *curl_handle;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl_handle = curl_easy_init();

    if (curl_handle) {
        curl_easy_setopt(curl_handle, CURLOPT_URL, args.url);
        curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, NULL); // Placeholder
        curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, &chunk);

        res = curl_easy_perform(curl_handle);

        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl_handle);
    }
    curl_global_cleanup();

    // Process data in chunk.data of size chunk.size

    free(chunk.data);
    return NULL;
}

void process_urls() {
    pthread_t threads[MAX_THREADS];

    for (int i = 0; url_list != NULL; ) {
        char *url = url_list->url;

        ThreadArgs *arg = malloc(sizeof(ThreadArgs));
        arg->url = url;
        arg->thread_id = -1; // Placeholder

        enqueue(*arg);

        if (i < MAX_THREADS) {
            ThreadArgs task = dequeue();
            pthread_create(&threads[i], NULL, fetch_data, &task);
            i++;
        } else {
            for (int j = 0; j < MAX_THREADS; j++) {
                pthread_join(threads[j], NULL);
            }
            i = 0;
        }

        URLNode *tmp = url_list;
        url_list = url_list->next;
        free(tmp);
    }

    // Join remaining threads
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }
}

// A basic main function to simulate the scraping process
int main(int argc, char *argv[]) {
    if (argc > 1) {
        // Assume URLs are passed as command-line arguments for simplicity
        for (int i = 1; i < argc; i++) {
            URLNode *node = malloc(sizeof(URLNode));
            node->url = strdup(argv[i]);
            node->next = url_list;
            url_list = node;
        }
    }

    process_urls();

    return 0;
}
```

