void process_file(const char *input_filename, const char *output_filename, const char *rules, int chunk_size) {
    FILE *input_file = fopen(input_filename, "rb");
    if (!input_file) {
        perror("Error opening input file");
        exit(EXIT_FAILURE);
    }

    FILE *output_file = fopen(output_filename, "wb");
    if (!output_file) {
        fclose(input_file);
        perror("Error opening output file");
        exit(EXIT_FAILURE);
    }

    char *buffer = (char *)malloc(chunk_size);
    if (!buffer) {
        perror("Memory allocation error");
        fclose(input_file);
        fclose(output_file);
        exit(EXIT_FAILURE);
    }

    size_t bytes_read;
    int chunk_id = 0;
    Metadata metadata;

    while ((bytes_read = fread(buffer, 1, chunk_size, input_file)) > 0) {
        if (!get_metadata_from_db(chunk_id++, &metadata)) {
            fprintf(stderr, "Failed to retrieve metadata for chunk %d\n", chunk_id);
            continue; // Or handle error appropriately
        }

        apply_rules(buffer, bytes_read, rules, &metadata);

        fwrite(buffer, 1, bytes_read, output_file);
    }

    free(buffer);
    fclose(input_file);
    fclose(output_file);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input file> <output file> <rules> <chunk size>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_filename = argv[1];
    const char *output_filename = argv[2];
    const char *rules = argv[3];
    int chunk_size = atoi(argv[4]);

    if (chunk_size <= 0 || chunk_size > MAX_CHUNK_SIZE) {
        fprintf(stderr, "Invalid chunk size. Must be between 1 and %d bytes.\n", MAX_CHUNK_SIZE);
        return EXIT_FAILURE;
    }

    process_file(input_filename, output_filename, rules, chunk_size);

    return EXIT_SUCCESS;
}
