public:
    SandeshClient(net::io_context& ioc)
        : resolver_(ioc), ssl_ctx_(net::ssl::context::tlsv12_client) {}

    void SendRequest(const std::string& host, const std::string& port, 
                     const http::request<http::empty_body>& req, bool isPost = false) {
        auto self = shared_from_this();
        net::connect(resolver_.async_resolve(host, port),
            [this, self, req, isPost](beast::error_code ec, beast::tcp::resolver::results_type results) {
                if (ec) return Logger::Log("Resolve: " + ec.message());

                beast::ssl_stream<beast::tcp_stream> stream(ssl_ctx_);
                net::async_connect(stream.lowest_layer(), results.begin(), results.end(),
                    [this, self, req, isPost](beast::error_code ec, auto) {
                        if (ec) return Logger::Log("Connect: " + ec.message());

                        stream.async_handshake(net::ssl::stream_base::client,
                            [this, self, req, isPost](beast::error_code ec) {
                                if (ec) return Logger::Log("Handshake: " + ec.message());

                                auto start = std::chrono::high_resolution_clock::now();
                                if (isPost) {
                                    stream.async_write(requestBuffer(req), 
                                        [this, self, req, start](beast::error_code ec, std::size_t bytes_transferred) {
                                            HandleResponse(ec, req, start);
                                        });
                                } else {
                                    http::async_read(stream, buffer_, response_,
                                        [this, self, start](beast::error_code ec, std::size_t bytes_transferred) {
                                            HandleResponse(ec, req, start);
                                        });
                                }
                            });
                    });
    }

private:
    void HandleResponse(beast::error_code ec, const http::request<http::empty_body>& req, 
                        std::chrono::time_point<std::chrono::high_resolution_clock> start) {
        if (ec) {
            Logger::Log("Request failed: " + ec.message());
            ++internal_errors;
            return;
        }

        auto end = std::chrono::high_resolution_clock::now();
        int64_t duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

        std::string log_message = "Request to " + req.target().to_string() +
                                  ", Status: " + std::to_string(response_.result_int()) +
                                  ", Duration: " + std::to_string(duration) + "ms, ";
        if (isPost) {
            log_message += "Body Length: " + std::to_string(requestBuffer(req).size());
        } else {
            log_message += "Response Body Length: " + std::to_string(response_.body().size());
        }

        Logger::Log(log_message);
        ++request_count;
    }

    http::response<http::dynamic_body> response_;
    beast::flat_buffer buffer_;
    net::ip::tcp::resolver resolver_;
    net::ssl::context ssl_ctx_;

    std::string requestBuffer(const http::request<http::empty_body>& req) {
        return req.to_string();
    }
};

void MakeRequests(SandeshClient& client, const std::vector<std::pair<std::string, std::string>>& requests) {
    for (const auto& [url, method] : requests) {
        http::request<http::empty_body> req{http::verb::get, url, 11};
        if (method == "POST") {
            req.method(http::verb::post);
        }
        client.SendRequest("example.com", "443", req, method == "POST");
    }
}

int main() {
    net::io_context ioc;
    SandeshClient client(ioc);

    std::vector<std::pair<std::string, std::string>> requests = {
        {"/api/vm/1234", "GET"},
        {"/api/vm/5678", "POST"}
    };

    std::thread t1(MakeRequests, std::ref(client), requests);
    std::thread t2(MakeRequests, std::ref(client), requests);

    t1.join();
    t2.join();

    Logger::Log("Total Requests: " + std::to_string(request_count));
    Logger::Log("Proxy Sessions: " + std::to_string(proxy_sessions));
    Logger::Log("Internal Errors: " + std::to_string(internal_errors));

    return 0;
}
