        }

        int selected_attack = randomGenerator() % 2 + 1;

        cooldown_end_time = std::chrono::steady_clock::now() + std::chrono::seconds(cooldown_period);

        if (selected_attack == 1 && attack1_count < max_uses) {
            ++attack1_count;
