interface ElementMetadata {
    id: string;
    class: string;
    description: Promise<string>;
}

async function fetchElementDescription(elementId: string): Promise<string> {
    try {
        const response = await fetch(`https://api.example.com/elements/${elementId}`);
        if (!response.ok) throw new Error('Network response was not ok');
        return await response.text();
    } catch (error) {
        console.error("Error fetching element description:", error);
        return "Description unavailable";
    }
}

async function getElementMetadata(element: HTMLElement): Promise<ElementMetadata> {
    const id = element.id;
    const classList = Array.from(element.classList).join(' ');

    return {
        id,
        class: classList,
        description: fetchElementDescription(id)
    };
}

async function getMatchingElements(rootElement: HTMLElement, selector: string, filterFn: (element: ElementMetadata) => boolean): Promise<HTMLElement[]> {
    const stack = [rootElement];
    const matchedElements: HTMLElement[] = [];

    while (stack.length > 0) {
        const currentElement = stack.pop()!;

        if (currentElement.matches(selector)) {
            try {
                const metadata = await getElementMetadata(currentElement);

                if (await filterFn(metadata)) {
                    matchedElements.push(currentElement);
                }
            } catch (error) {
                console.error("Error processing element:", error);
            }
        }

        for (let child of currentElement.children) {
            stack.push(child);
        }
    }

    return matchedElements;
}

