        // Asynchronously execute the stored procedure
        std::future<std::vector<CustomObject>> resultFuture = std::async(std::launch::async, [&]() {
            // Execute the SQL command asynchronously and return results as CustomObjects
            return std::vector<CustomObject>();  // Replace with actual database call logic
        });

        // Wait for the result and cache it
        std::vector<CustomObject> result = resultFuture.get();
        cache[key] = result;

        Logger::LogSuccess("Stored procedure executed successfully: " + procName);
        return result;
    } catch (const std::exception& e) {
        Logger::LogError("Error executing stored procedure: " + std::string(e.what()));
        throw;  // Re-throw exception for caller to handle
    }
}

int runCommandInBackground(const std::string& command) {
    pid_t pid = fork();
    if (pid < 0) {
        Logger::LogError("Fork failed");
        return 0;
    } else if (pid > 0) { 
        // Parent process waits for the child to finish
        int status;
        waitpid(pid, &status, 0);
        if(WIFEXITED(status)) {
            return WEXITSTATUS(status) == 0 ? 1 : 0;  // Return success or failure based on exit status
        }
    } else {
        // Child process executes the command
        execlp(command.c_str(), command.c_str(), nullptr);
        Logger::LogError("Failed to execute command: " + command);
        return 0;
    }
}

