#include "DatabaseConnectionPool.h"
#include "Logger.h"

struct CustomObject {
    // Define your custom object structure here
};

class CommandRunner {
public:
    bool runBackgroundCommand(const std::string& command) {
        pid_t pid = fork();
        if (pid < 0) {
            return false; // Fork failed
        }
        if (pid == 0) {
            execl("/bin/sh", "sh", "-c", command.c_str(), nullptr);
            exit(EXIT_FAILURE); // If exec fails
        } else {
            int status;
            waitpid(pid, &status, WNOHANG);
            return true; // Command ran successfully in the background
        }
    }

    std::vector<CustomObject> executeStoredProcedure(
        DatabaseConnectionPool& pool,
        const std::string& procedureName,
        const std::vector<std::variant<int, double, std::string>>& inputParams) {

        auto key = generateCacheKey(procedureName, inputParams);

        // Check cache
        if (cache.find(key) != cache.end()) {
            return cache[key];
        }

        try {
            // Validate parameters
            validateParameters(inputParams);

            auto connection = pool.getConnection();
            auto command = createCommand(connection, procedureName, inputParams);

            std::vector<CustomObject> results;
            executeAsync(command, [&results](const CustomResultSet& resultSet) {
                for (auto& row : resultSet) {
                    // Map the result set to custom objects
                    results.push_back(mapToCustomObject(row));
                }
            });

            cache[key] = results;  // Store in cache

            logExecution(procedureName, true);
            return results;
        } catch (const std::exception& e) {
            logExecution(procedureName, false, e.what());
            handleErrors(e);  // Handle errors like timeout or invalid parameters
            return {};
        }
    }

private:
    std::unordered_map<std::string, std::vector<CustomObject>> cache;

    std::string generateCacheKey(const std::string& procedureName,
                                 const std::vector<std::variant<int, double, std::string>>& params) {
        // Generate a unique key for the cache based on procedure name and parameters
        std::string key = procedureName;
        for (const auto& param : params) {
            key += std::to_string(std::visit([](auto&& arg) { return arg; }, param));
        }
        return key;
    }

    void validateParameters(const std::vector<std::variant<int, double, std::string>>& params) {
        // Implement parameter validation logic here
    }

    auto createCommand(DatabaseConnection& connection,
                       const std::string& procedureName,
                       const std::vector<std::variant<int, double, std::string>>& inputParams) -> DatabaseCommand {
        // Create and configure the database command object to execute the stored procedure
    }

    void executeAsync(DatabaseCommand& command, std::function<void(const CustomResultSet&)> callback) {
        // Execute the command asynchronously
        std::thread([command, callback]() mutable {
            try {
                auto resultSet = command.execute();
                callback(resultSet);
            } catch (const std::exception& e) {
                Logger::logError("Async execution failed", e.what());
            }
        }).detach();  // Detach to allow asynchronous disposal
    }

    void logExecution(const std::string& procedureName, bool success, const std::string& errorMessage = "") {
        if (success) {
            Logger::logInfo("Stored Procedure executed successfully: " + procedureName);
        } else {
            Logger::logError("Failed executing Stored Procedure: " + procedureName + ", Error: " + errorMessage);
        }
    }

    void handleErrors(const std::exception& e) {
        // Handle specific exceptions such as database timeouts or invalid parameters
    }

    CustomObject mapToCustomObject(const ResultSetRow& row) {
        // Map a row from the result set to a custom object
    }
};

