using System;
using System.Data.SqlClient;
using System.Security.Cryptography;
using BCrypt.Net;

public enum HashAlgorithmType
{
    SHA256,
    Bcrypt
}

public class PasswordHasher
{
    private readonly string connectionString;

    public PasswordHasher(string dbConnectionString)
    {
        connectionString = dbConnectionString ?? throw new ArgumentNullException(nameof(dbConnectionString));
    }

    // Generates a hash using the specified algorithm
    public string HashPassword(string password, HashAlgorithmType algorithmType)
    {
        if (string.IsNullOrWhiteSpace(password))
            throw new ArgumentException("Password cannot be null or empty.", nameof(password));

        switch (algorithmType)
        {
            case HashAlgorithmType.SHA256:
                return ComputeSha256Hash(password);
            case HashAlgorithmType.Bcrypt:
                return BCrypt.Net.BCrypt.HashPassword(password);
            default:
                throw new NotSupportedException($"The algorithm type {algorithmType} is not supported.");
        }
    }

    // Verifies a password against the stored hash
    public bool VerifyPassword(string password, string hashedPassword, HashAlgorithmType algorithmType)
    {
        if (string.IsNullOrWhiteSpace(hashedPassword))
            return false;

        switch (algorithmType)
        {
            case HashAlgorithmType.SHA256:
                var saltedHash = ComputeSha256Hash(password);
                return saltedHash == hashedPassword;
            case HashAlgorithmType.Bcrypt:
                return BCrypt.Net.BCrypt.Verify(password, hashedPassword);
            default:
                throw new NotSupportedException($"The algorithm type {algorithmType} is not supported.");
        }
    }

    // Store hashed password and salt in the database
    public void StorePasswordHash(string username, string hashedPassword)
    {
        if (string.IsNullOrWhiteSpace(username) || string.IsNullOrWhiteSpace(hashedPassword))
            throw new ArgumentException("Username or hashed password cannot be null or empty.");

        using (var connection = new SqlConnection(connectionString))
        {
            var query = "INSERT INTO UserPasswords (Username, PasswordHash) VALUES (@Username, @PasswordHash)";
            var command = new SqlCommand(query, connection);

            command.Parameters.AddWithValue("@Username", username);
            command.Parameters.AddWithValue("@PasswordHash", hashedPassword);

            try
            {
                connection.Open();
                command.ExecuteNonQuery();
            }
            catch (SqlException ex)
            {
                // Log or handle exception appropriately in production code
                Console.WriteLine($"Database error: {ex.Message}");
            }
        }
    }

    // Retrieves a stored password hash from the database
    public string GetStoredPasswordHash(string username)
    {
        if (string.IsNullOrWhiteSpace(username))
            throw new ArgumentException("Username cannot be null or empty.", nameof(username));

        using (var connection = new SqlConnection(connectionString))
        {
            var query = "SELECT PasswordHash FROM UserPasswords WHERE Username = @Username";
            var command = new SqlCommand(query, connection);

            command.Parameters.AddWithValue("@Username", username);

            try
            {
                connection.Open();
                return command.ExecuteScalar()?.ToString() ?? string.Empty;
            }
            catch (SqlException ex)
            {
                // Log or handle exception appropriately in production code
                Console.WriteLine($"Database error: {ex.Message}");
                return string.Empty;
            }
        }
    }

    // Helper method to compute SHA256 hash with salt
    private string ComputeSha256Hash(string password)
    {
        using (var sha256 = SHA256.Create())
        {
            var saltBytes = new byte[16];
            using (var rng = RandomNumberGenerator.Create())
                rng.GetBytes(saltBytes);

            var passwordBytes = System.Text.Encoding.UTF8.GetBytes(password);
            var saltedPassword = System.BitConverter.ToString(saltBytes).Replace("-", "").Concat(passwordBytes)
                .Select(b => Convert.ToString(b, 2).PadLeft(8, '0')).Aggregate((current, next) => current + next).ToCharArray()
                .GroupBy(c => c).ToDictionary(grp => grp.Key, grp => grp.Count())
                .OrderBy(kvp => kvp.Key).Select(kvp => new string(kvp.Value.Select(n => (char)(n % 2 == 0 ? '1' : '0')).ToArray()));

            var hashBytes = sha256.ComputeHash(System.Text.Encoding.UTF8.GetBytes(string.Join("", saltedPassword)));
            return Convert.ToBase64String(hashBytes);
        }
    }

    // Example method to integrate with an external authentication API
    private void AuthenticateWithExternalApi(string username, string password)
    {
        // Integration logic with the external API can be added here.
        // Ensure secure handling of credentials and proper error logging/management.
    }
}

