<?php

class SaltNotFoundException extends Exception {}

class PasswordManager {
    private $dbConnection;
    private $saltCache = [];

    public function __construct($dbConnection) {
        $this->dbConnection = $dbConnection;
    }

    public function generateRandomString($length, $charset) {
        if ($length > strlen($charset)) {
            throw new Exception('Length must be less than or equal to the charset length.');
        }

        $randomString = '';
        $uniqueChars = [];

        while (strlen($randomString) < $length) {
            $charIndex = mt_rand(0, strlen($charset) - 1);
            $char = $charset[$charIndex];

            if (!in_array($char, $uniqueChars)) {
                $randomString .= $char;
                $uniqueChars[] = $char;
            }
        }

        return str_shuffle($randomString);
    }

    public function hashPassword($password, $salt) {
        if (!$this->isValidSalt($salt)) {
            throw new Exception('Invalid salt provided.');
        }

        return password_hash($password . $salt, PASSWORD_BCRYPT, ['cost' => 12]);
    }

    private function isValidSalt($salt) {
        // Simple validation for the example
        return is_string($salt) && strlen(base64_decode($salt)) > 0;
    }

    public function verifyPassword($hashedPassword, $password, $salt) {
        if (!$this->isValidSalt($salt)) {
            throw new Exception('Invalid salt provided.');
        }

        $expectedHash = password_hash($password . $salt, PASSWORD_BCRYPT, ['cost' => 12]);

        return password_verify($password . $salt, $hashedPassword);
    }

    public function retrieveSalt($username) {
        if (isset($this->saltCache[$username])) {
            return $this->saltCache[$username];
        }

        // Simulate database retrieval
        $query = "SELECT salt FROM users WHERE username = ?";
        $stmt = $this->dbConnection->prepare($query);
        $stmt->bind_param('s', $username);
        $stmt->execute();
        $result = $stmt->get_result();

        if ($row = $result->fetch_assoc()) {
            $salt = $row['salt'];
            $this->saltCache[$username] = $salt;
            return $salt;
        } else {
            throw new SaltNotFoundException("No salt found for user: {$username}");
        }
    }

    public function saveHashedPassword($username, $hashedPassword, $salt) {
        try {
            $query = "INSERT INTO users (username, hashed_password, salt) VALUES (?, ?, ?)";
            $stmt = $this->dbConnection->prepare($query);
            if (!$stmt) {
                throw new Exception('Failed to prepare statement.');
            }

            $stmt->bind_param('sss', $username, $hashedPassword, $salt);
            $result = $stmt->execute();

            if (!$result) {
                throw new Exception('Failed to save hashed password.');
            }
        } catch (Exception $e) {
            error_log($e->getMessage());
            // Handle database connection failures or other errors gracefully
            return false;
        }

        return true;
    }
}
