#include <base64.h> // Assuming you have a third-party base64 encoding library
#include <hiredis/hiredis.h>
#include <cpp_redis/cpp_redis>

namespace SessionIDGenerator {

    class SecureRandom {
    public:
        SecureRandom() {
            seed_generator();
        }

        ~SecureRandom() = default;

        std::string generateUniqueSessionID();

    private:
        static std::mt19937_64 rng;
        static std::mutex generator_mutex;
        static std::unordered_set<std::string> cache; // In-memory store for recent IDs
        void seed_generator();
        bool is_unique(const std::string& id);
        std::string base64_encode(const uint8_t* buf, size_t len);

    };

    std::mt19937_64 SecureRandom::rng;
    std::mutex SecureRandom::generator_mutex;
    std::unordered_set<std::string> SecureRandom::cache;

    void SecureRandom::seed_generator() {
        unsigned seed[4] = {0};
        if (RAND_bytes((unsigned char*)seed, sizeof(seed)) != 1) {
            std::cerr << "Error getting entropy from system." << std::endl;
            std::exit(1);
        }

        auto time_seed = std::chrono::system_clock::now().time_since_epoch().count();
        rng.seed(time_seed ^ seed[0] ^ seed[1] ^ seed[2] ^ seed[3]);
    }

    bool SecureRandom::is_unique(const std::string& id) {
        cpp_redis::client redis_client;

        redis_client.connect("127.0.0.1", 6379, [](cpp_redis::connect_state status){
            if (status == cpp_redis::connect_state::connected) {
                std::cout << "Connected to Redis" << std::endl;
            }
        });

        auto result = redis_client.get(id);
        while(result.is_in_progress()) {
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }

        if (result.result().str() == "exists") {
            return false;
        } else {
            redis_client.set(id, "exists");
            return true;
        }
    }

    std::string SecureRandom::base64_encode(const uint8_t* buf, size_t len) {
        // Assuming Base64::encode function is available
        return Base64::encode(buf, len);
    }

    std::string SecureRandom::generateUniqueSessionID() {
        std::lock_guard<std::mutex> lock(generator_mutex);

        while (true) {
            std::uniform_int_distribution<uint64_t> dist(0, ~0ULL);
            uint64_t random_value = dist(rng);

            auto buffer = reinterpret_cast<uint8_t*>(&random_value);
            std::string session_id = base64_encode(buffer, sizeof(uint64_t));

            if (session_id.length() == 22 && is_unique(session_id)) {
                cache.insert(session_id);
                return session_id;
            }
        }
    }

} // namespace SessionIDGenerator

int main() {
    try {
        SessionIDGenerator::SecureRandom generator;
        std::string session_id = generator.generateUniqueSessionID();
        std::cout << "Generated Session ID: " << session_id << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Exception occurred: " << e.what() << std::endl;
    }
    return 0;
}
```

### Notes:
1. **Dependencies**: This code assumes the use of `cpp_redis` for Redis operations and a base64 encoding library, which should be linked properly in your build system.
2. **Security**: Entropy is gathered from `/dev/urandom` using OpenSSL's `RAND_bytes`.
3. **Concurrency & Locking**: The mutex ensures that session ID generation remains thread-safe across concurrent calls.
4. **Redis Usage**: Redis is used for checking and storing session IDs to maintain uniqueness across distributed nodes.
