```javascript
class ApiClient {
    constructor(url) {
        this.url = url;
    }

    async fetchDescriptions(elements) {
        const responses = await Promise.all(
            elements.map(element =>
                fetch(`${this.url}/descriptions?id=${element.id}`)
                    .then(res => res.json())
                    .catch(() => ({ error: true }))
            )
        );
        return new Map(
            responses.reduce((map, response, index) => {
                if (!response.error) map.set(elements[index].id, response.description);
                return map;
            }, new Map())
        );
    }

    async fetchImages(elements) {
        const responses = await Promise.all(
            elements.map(element =>
                fetch(`${this.url}/images?id=${element.id}`)
                    .then(res => res.json())
                    .catch(() => ({ error: true }))
            )
        );
        return new Map(
            responses.reduce((map, response, index) => {
                if (!response.error) map.set(elements[index].id, response.imageUrl);
                return map;
            }, new Map())
        );
    }
}

class ApiClientFactory {
    createApiClient(url) {
        return new ApiClient(url);
    }
}

async function fetchAndFilterElements(rootElement, selector, filterFn, apiClientFactory) {
    const matchedElements = [];
    const queue = [rootElement];

    while (queue.length > 0) {
        const currentNode = queue.shift();

        if (currentNode.matches(selector)) {
            matchedElements.push(currentNode);
        }

        for (const child of currentNode.children) {
            queue.push(child);
        }
    }

    const apiClient = await apiClientFactory.createApiClient('https://api.example.com');

    const metadataPromises = matchedElements.map(async element => ({
        id: element.id || '',
        class: element.className,
        descriptions: apiClient.fetchDescriptions([element]),
        images: apiClient.fetchImages([element])
    }));

    const elementsMetadata = await Promise.all(metadataPromises);

    const filteredElements = [];
    for (const metadata of elementsMetadata) {
        try {
            if (await filterFn(metadata)) {
                filteredElements.push(matchedElements[elementsMetadata.indexOf(metadata)]);
            }
        } catch (error) {
            console.error('Error filtering element:', error);
        }
    }

    return filteredElements;
}
