```cpp
#include <iostream>
#include <forward_list>
#include <string>
#include <fstream>
#include <stdexcept>

void insert_after_position(std::forward_list<std::string>& flist, const std::string& target, const std::string& to_insert, int position = -1) {
    if (position < -1) {
        throw std::invalid_argument("Position index cannot be less than -1.");
    }

    auto it = flist.before_begin();
    size_t current_pos = 0;

    bool found = false;

    for (auto curr_it = flist.begin(); curr_it != flist.end(); ++curr_it) {
        if (*curr_it == target && (position == -1 || current_pos == position)) {
            flist.insert_after(curr_it, to_insert);
            found = true;
        }

        if (!found && current_pos == position) {
            flist.insert_after(curr_it, to_insert);
            break;
        }

        ++current_pos;
    }

    // If not found and position is specified, check if we need to append at the end
    if (!found && (position != -1)) {
        std::cerr << "Target string '" << target << "' not found at position " << position << ". Inserting at the end.\n";
    }

    // Append to_insert if target is not found or specified position was beyond list length
    if (!found || current_pos < position) {
        flist.push_front(to_insert);
    }
}

void insert_from_file(const std::string& filename, std::forward_list<std::string>& flist) {
    std::ifstream file(filename);

    if (!file.is_open()) {
        throw std::runtime_error("Could not open the file.");
    }

    std::string target, to_insert;
    int position;

    while (file >> target >> to_insert >> position) {
        try {
            insert_after_position(flist, target, to_insert, position);
        } catch (const std::exception& e) {
            std::cerr << "Error inserting: " << e.what() << '\n';
        }
    }

    file.close();
}

int main() {
    std::forward_list<std::string> list = {"apple", "banana", "cherry", "date"};

    insert_after_position(list, "cherry", "orange", 2);

    try {
        insert_from_file("insertions.txt", list); // Assuming the file contains lines like "fig grape -1"
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }

    for (const auto& item : list) {
        std::cout << item << ' ';
    }
    std::cout << '\n';

    return 0;
}
