using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace RandomNumberGeneratorApp
{
    public class RandomNumberGeneratorMT19937 : IDisposable
    {
        private static readonly Random _random = new Random();

        // Constructor
        public RandomNumberGeneratorMT19937()
        {
            Console.WriteLine("Random Number Generator MT19937 initialized.");
        }

        // Destructor
        ~RandomNumberGeneratorMT19937()
        {
            Dispose(false);
        }

        public int GenerateRandomNumber(int min, int max)
        {
            lock (_random)  // Ensure thread safety when accessing the random generator.
            {
                return _random.Next(min, max);
            }
        }

        private void Dispose(bool disposing)
        {
            if (disposing)
            {
                Console.WriteLine("Cleaning up resources.");
            }
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            var randomGenerator = new RandomNumberGeneratorMT19937();
            if (!CheckWebConfig())
            {
                Console.WriteLine("web.config not found. Exiting.");
                return;
            }

            ConcurrentBag<int> allIntegers = new ConcurrentBag<int>();
            using (var cts = new CancellationTokenSource(TimeSpan.FromSeconds(30)))
            {
                var tasks = args.Select(file => ProcessFileAsync(file, allIntegers, cts.Token));
                await Task.WhenAll(tasks);
            }

            int? largestNumber = allIntegers.Any() ? allIntegers.Max() : null;
            double average = allIntegers.Count > 0 ? allIntegers.Average() : 0;

            Console.WriteLine($"Largest Number: {largestNumber}");
            Console.WriteLine($"Average of All Numbers: {average}");

            randomGenerator.Dispose();
        }

        static bool CheckWebConfig()
        {
            return Directory.Exists(Directory.GetCurrentDirectory()) && File.Exists(Path.Combine(Directory.GetCurrentDirectory(), "web.config"));
        }

        static async Task ProcessFileAsync(string filePath, ConcurrentBag<int> allIntegers, CancellationToken token)
        {
            if (!File.Exists(filePath) || !Directory.Exists(Path.GetDirectoryName(filePath)))
            {
                Console.WriteLine($"Error: Invalid file or directory path for {filePath}");
                return;
            }

            try
            {
                var numbers = await File.ReadAllLinesAsync(filePath).ContinueWith(t => 
                    t.Result.Select(int.Parse).ToList(), token);

                foreach (var number in numbers)
                {
                    allIntegers.Add(number);
                }
            }
            catch (Exception ex) when (ex is FormatException || ex is IOException)
            {
                Console.WriteLine($"Error processing file {filePath}: {ex.Message}");
            }
        }
    }
}
```

