```php
<?php

session_start();

class SecurityManager {
    private $charSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    private const RATE_LIMIT_ATTEMPTS = 5;
    private const RATE_LIMIT_TIME_FRAME = 60; // seconds

    public function __construct() {
        register_shutdown_function([$this, 'rotateTokens']);
    }

    public function generateRandomString($length) {
        if (!is_int($length) || $length <= 0) {
            throw new InvalidArgumentException('Invalid length for random string');
        }
        return substr(str_shuffle(str_repeat($this->charSet, ceil($length / strlen($this->charSet)))), 1, $length);
    }

    public function hashPassword($password, $algorithm = PASSWORD_BCRYPT) {
        if (empty($password)) {
            throw new InvalidArgumentException('Password cannot be empty');
        }

        return password_hash($password, $algorithm);
    }

    public function validateLoginAttempt($ipAddress) {
        static $attempts = [];
        $currentTime = time();

        if (!isset($attempts[$ipAddress])) {
            $attempts[$ipAddress] = [['time' => $currentTime]];
        } else {
            $attempts[$ipAddress] = array_filter(
                $attempts[$ipAddress],
                function ($attempt) use ($currentTime) {
                    return $currentTime - $attempt['time'] <= self::RATE_LIMIT_TIME_FRAME;
                }
            );

            if (count($attempts[$ipAddress]) >= self::RATE_LIMIT_ATTEMPTS) {
                throw new RuntimeException('Too many login attempts. Please try again later.');
            }

            $attempts[$ipAddress][] = ['time' => $currentTime];
        }
    }

    public function logFailedLogin($ipAddress, $message) {
        error_log("[$ipAddress] Failed Login: $message");
    }

    public function createSessionToken() {
        $_SESSION['token'] = $this->generateRandomString(32);
        $_SESSION['last_token_rotation'] = time();
    }

    public function rotateTokens() {
        if (!isset($_SESSION['last_token_rotation']) || (time() - $_SESSION['last_token_rotation']) > 3600) { // every hour
            $this->createSessionToken();
        }
    }

    public function createPasswordResetLink($email, $pdo) {
        $token = $this->generateRandomString(64);
        $expiryTime = time() + 3600; // token valid for 1 hour

        $stmt = $pdo->prepare('INSERT INTO password_reset_tokens (email, token, expiry_time) VALUES (?, ?, ?)');
        if (!$stmt->execute([$email, $token, $expiryTime])) {
            throw new RuntimeException('Failed to create password reset link');
        }

        return "https://example.com/reset-password?token=$token";
    }

    public function validatePasswordResetToken($token, $pdo) {
        $stmt = $pdo->prepare('SELECT email FROM password_reset_tokens WHERE token = ? AND expiry_time > ?');
        if (!$stmt->execute([$token, time()])) {
            throw new RuntimeException('Failed to validate password reset token');
        }

        return $stmt->fetchColumn();
    }
}

// Usage example
$securityManager = new SecurityManager();

try {
    // Hashing a password
    $hashedPassword = $securityManager->hashPassword("userPassword123");

    // Generating session token
    $securityManager->createSessionToken();

    // Validating login attempts (e.g., before hashing for login)
    $ipAddress = $_SERVER['REMOTE_ADDR'];
    $securityManager->validateLoginAttempt($ipAddress);

} catch (Exception $e) {
    $securityManager->logFailedLogin($_SERVER['REMOTE_ADDR'], $e->getMessage());
}

// Database connection for password reset
