```rust
use std::collections::VecDeque;
use std::fs;
use std::process::{Command, Stdio};
use serde_json::{json, Value};
use std::time::{Duration, Instant};
use std::sync::{Arc, Mutex};
use rayon::ThreadPoolBuilder;

#[derive(Clone)]
struct CompileConfig {
    max_concurrent_compiles: usize,
    batch_size: usize,
    retry_limit: usize,
}

fn compile_files(file_paths: Vec<String>, config: CompileConfig) -> Result<Vec<Value>, String> {
    let max_concurrent = Arc::new(config.max_concurrent_compiles);
    let results = Arc::new(Mutex::new(Vec::new()));
    let mut pool = ThreadPoolBuilder::new().num_threads(*max_concurrent).build().unwrap();

    file_paths.chunks(config.batch_size)
        .for_each(|batch| {
            let max_concurrent = Arc::clone(&max_concurrent);
            let results = Arc::clone(&results);

            pool.scope(move |s| {
                s.spawn(move |_| {
                    for path in batch.iter() {
                        compile_single_file(path.to_string(), *max_concurrent, &results).unwrap_or_else(|e| eprintln!("{}", e));
                    }
                });
            });
        });

    let res: Vec<Value> = results.lock().unwrap().clone();
    Ok(res)
}

fn compile_single_file(file_path: String, max_concurrent: Arc<usize>, results: &Arc<Mutex<Vec<Value>>>) -> Result<(), String> {
    if file_path.as_str().is_empty() || !fs::metadata(&file_path).is_ok() {
        return Err(format!("Invalid file path: {}", file_path));
    }

    let retry_count = 0;
    for _ in 0..config.retry_limit {
        match try_compile(file_path.clone()) {
            Ok(output) => {
                results.lock().unwrap().push(output);
                break;
            },
            Err(e) if retry_count < config.retry_limit => {
                eprintln!("Error compiling {}: {}. Retrying...", file_path, e);
                retry_count += 1;
            }
            Err(e) => return Err(format!("Failed to compile {} after retries: {}", file_path, e)),
        }
    }

    Ok(())
}

fn try_compile(file_path: String) -> Result<Value, String> {
    let start_time = Instant::now();

    // Simulate getting resident set size before and after
    let rss_before = get_resident_set_size();
    let exit_code = rustc_driver::catch_with_exit_code(|| Command::new("rustc")
        .arg(&file_path)
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap_or_else(|e| eprintln!("Failed to start process: {}", e))
        .wait()
        .map(|status| status.code().unwrap_or(-1))
    );

    let rss_after = get_resident_set_size();
    let duration = start_time.elapsed();

    if exit_code == 0 {
        Ok(json!({
            "file_path": file_path,
            "time_taken_ms": duration.as_millis(),
            "rss_before_kb": rss_before,
            "rss_after_kb": rss_after,
            "status": "success"
        }))
    } else {
        Err(format!("Compilation failed for {}", file_path))
    }
}

fn get_resident_set_size() -> u64 {
    // Placeholder for actual implementation to fetch RSS size
    1024 * 10 // Dummy value in KB
}
