```php
<?php

class SecureSessionManager {
    private $db;
    private $tokenCharset;

    public function __construct($mongoClient, $dbName, $collectionName, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
        try {
            $this->db = $mongoClient->$dbName->$collectionName;
            $this->tokenCharset = $charset;
        } catch (Exception $e) {
            throw new Exception('Database connection failed: ' . $e->getMessage());
        }
    }

    private function generateToken($length = 32) {
        if (!$this->tokenCharset || strlen($this->tokenCharset) < 2) {
            throw new InvalidArgumentException('Invalid character set for token generation.');
        }

        $token = '';
        $maxIndex = mb_strlen($this->tokenCharset, '8bit') - 1;

        while (strlen($token) < $length) {
            $randomByte = random_int(0, PHP_INT_MAX);
            $index = $randomByte % ($maxIndex + 1);
            $token .= mb_substr($this->tokenCharset, $index, 1, '8bit');
        }

        return hash('sha256', $token);
    }

    public function startSession($userId) {
        $token = $this->generateToken();
        try {
            $result = $this->db->updateOne(
                ['_id' => new MongoDB\BSON\ObjectID($userId)],
                ['$set' => ['session_token' => $token, 'last_active' => new MongoDB\BSON\UTCDateTime()]]
            );

            if ($result->getModifiedCount() === 0) {
                throw new Exception('Failed to update session token.');
            }
        } catch (Exception $e) {
            throw new Exception('Error starting session: ' . $e->getMessage());
        }

        return $token;
    }

    public function verifySession($userId, $sessionToken) {
        try {
            $user = $this->db->findOne(['_id' => new MongoDB\BSON\ObjectID($userId)]);

            if (!$user || !$user['session_token'] || hash('sha256', $user['session_token']) !== $sessionToken) {
                return false;
            }

            // Update last active time
            $this->db->updateOne(
                ['_id' => new MongoDB\BSON\ObjectID($userId)],
                ['$set' => ['last_active' => new MongoDB\BSON\UTCDateTime()]]
            );

            return true;
        } catch (Exception $e) {
            throw new Exception('Error verifying session: ' . $e->getMessage());
        }
    }

    public function endSession($userId) {
        try {
            $result = $this->db->updateOne(
                ['_id' => new MongoDB\BSON\ObjectID($userId)],
                ['$unset' => ['session_token' => ""]]
            );

            if ($result->getModifiedCount() === 0) {
                throw new Exception('Failed to end session.');
            }
        } catch (Exception $e) {
            throw new Exception('Error ending session: ' . $e->getMessage());
        }

        return true;
    }
}
