async function readDynamicFiles(basePath, filePattern = '*') {
    try {
        const fs = require('fs').promises;
        const path = require('path');

        // Read all files and directories recursively
        async function getAllFiles(dir) {
            let results = [];
            const list = await fs.readdir(dir);

            for (const file of list) {
                const fullPath = path.join(dir, file);
                const stat = await fs.stat(fullPath);

                if (stat.isDirectory()) {
                    results = results.concat(await getAllFiles(fullPath));
                } else if (new RegExp(filePattern).test(file)) {
                    results.push(fullPath);
                }
            }

            return results;
        }

        const files = await getAllFiles(basePath);

        for (const file of files) {
            try {
                const content = await fs.readFile(file, 'utf-8');
                console.log(`File: ${file}, Content: ${content}`);
            } catch (readError) {
                console.error(`Failed to read file ${file}:`, readError.message);
            }
        }

    } catch (error) {
        console.error('Error reading files:', error.message);
    }
}

// Example usage:
// readDynamicFiles('/path/to/directory', '\\.txt$');
