# python_function.py

import subprocess
import threading
from kubernetes import client, config
import yaml
import time
from ctypes import cdll, c_char_p, Structure, POINTER, c_double, c_int

# Load Kubernetes config
config.load_kube_config()

lock = threading.Lock()

class ResourceMetrics(Structure):
    _fields_ = [("cpu_usage", c_double), 
                ("memory_usage", c_double)]

def validate_manifest(manifest_path):
    with open(manifest_path, 'r') as file:
        try:
            yaml.safe_load(file)
            return True
        except yaml.YAMLError as e:
            print(f"Manifest validation error: {e}")
            return False

def create_namespace_with_retry(namespace_name, parent_namespace='default', max_retries=3):
    for attempt in range(max_retries):
        try:
            with lock:
                v1 = client.CoreV1Api()
                if not any(ns.metadata.name == namespace_name for ns in v1.list_namespace().items):
                    body = client.V1Namespace(
                        metadata=client.V1ObjectMeta(name=namespace_name),
                        spec=client.V1NamespaceSpec(parent=v1_api_v1.Namespace(name=parent_namespace))
                    )
                    v1.create_namespace(body)
                    print(f"Namespace '{namespace_name}' created successfully.")
                    return
        except Exception as e:
            print(f"Attempt {attempt + 1} failed: {e}")
            if attempt < max_retries - 1:
                time.sleep(2 ** attempt)  # Exponential backoff

    raise RuntimeError(f"Failed to create namespace '{namespace_name}' after {max_retries} attempts.")

def deploy_application(manifest_path, namespace_name):
    if not validate_manifest(manifest_path):
        print("Invalid manifest. Deployment aborted.")
        return

    create_namespace_with_retry(namespace_name)

    with open(manifest_path, 'r') as file:
        yaml_data = yaml.safe_load(file)

    k8s_client = client.ApiClient()
    customObjectsApi = client.CustomObjectsApi(k8s_client)

    group = "apps"
    version = "v1"
    plural = "deployments"

    namespace = namespace_name
    custom_objects_api = client.CustomObjectsApi()

    try:
        resp = custom_objects_api.create_namespaced_custom_object(
            group=group,
            version=version,
            namespace=namespace,
            plural=plural,
            body=yaml_data
        )
        print(f"Deployment created. Status='{resp['status']}'")
    except Exception as e:
        print(f"Failed to deploy application: {e}")

def analyze_pod_resources():
    lib = cdll.LoadLibrary('./resource_analysis.so')

    lib.analyze_resources.restype = ResourceMetrics

    metrics = lib.analyze_resources()
    return {
        "cpu_usage": metrics.cpu_usage,
        "memory_usage": metrics.memory_usage
    }

def monitor_pods(namespace_name, interval=60):
    while True:
        resource_data = analyze_pod_resources()
        print(f"Resource usage in namespace '{namespace_name}': {resource_data}")
        time.sleep(interval)

