void process_binary_log(CommandLineArgs args) {
    FILE *input = fopen(args.input_file, "rb");
    if (!input) {
        handle_error("Failed to open input file.");
    }

    FILE *output = fopen(args.output_file, "w");
    if (!output) {
        fclose(input);
        handle_error("Failed to open output file.");
