        fclose(output);
        fclose(input);
        handle_error("Failed to load config.");
    }

    fseek(input, 0L, SEEK_END);
    long num_entries = ftell(input) / ENTRY_SIZE;
    rewind(input);

    pthread_t threads[10];
    int thread_count = 0;

    for (long i = 0; i < num_entries; ++i) {
        unsigned char entry[ENTRY_SIZE];
        if (fread(entry, 1, ENTRY_SIZE, input) != ENTRY_SIZE) {
            handle_error("Corrupted log file.");
        }

        if (thread_count < 10) {
            pthread_create(&threads[thread_count], NULL, process_log_entry, (void *)entry);
            thread_count++;
        } else {
            for (int j = 0; j < 10; ++j) {
                pthread_join(threads[j], NULL);
            }
            thread_count = 0;
        }
    }

    for (int j = 0; j < thread_count; ++j) {
        pthread_join(threads[j], NULL);
    }

    fclose(input);
    fclose(output);
}

