// Cache to store fetched scripts to minimize redundant requests
const scriptCache = new Map();

// Function to create a spinner element
function createSpinner() {
    const spinner = document.createElement('div');
    spinner.id = 'loading-spinner';
    spinner.innerText = 'Loading...';
    spinner.style.display = 'none'; // Initially hidden
    return spinner;
}

// Fetch scripts from the API endpoint with error handling and caching
async function fetchScriptsFromAPI() {
    try {
        if (scriptCache.size > 0) {
            console.log('Using cached scripts');
            return Array.from(scriptCache.values());
        }

        const response = await fetch('/api/scripts');
        if (!response.ok) throw new Error(`Network response was not ok: ${response.statusText}`);

        const scripts = await response.json();
        scripts.forEach(script => scriptCache.set(script.id, script));
        console.log('Scripts fetched and cached');
        return scripts;
    } catch (error) {
        console.error('Failed to fetch scripts:', error);
        showErrorToUser('There was an issue loading the scripts.');
        return [];
    }
}

// Render scripts to the footer
function renderFooterScripts(scripts) {
    const footer = document.getElementById('footer') || document.createElement('div');
    footer.id = 'footer';

    // Clean up old script elements
    const existingScripts = footer.querySelectorAll('script');
    existingScripts.forEach(script => script.remove());

    scripts.forEach(({ code, type } = {}) => {
        if (!code) return;

        type = type || 'text/javascript';

        const scriptElement = document.createElement('script');
        scriptElement.type = type;
        scriptElement.async = true; // Ensure asynchronous loading
        scriptElement.textContent = code;

        footer.appendChild(scriptElement);
    });

    document.body.appendChild(footer);
}

// Display error message to the user
function showErrorToUser(message) {
    const errorMessage = document.createElement('div');
    errorMessage.innerText = message;
    errorMessage.style.color = 'red';
    document.body.insertBefore(errorMessage, document.body.firstChild);
}

// Main function to load and render scripts
async function loadAndRenderFooterScripts() {
    const spinner = createSpinner();
    document.body.appendChild(spinner);

    try {
        spinner.style.display = 'block'; // Show loading spinner

        const fetchedScripts = await fetchScriptsFromAPI();

        spinner.style.display = 'none'; // Hide loading spinner after fetching

        renderFooterScripts(fetchedScripts);
    } catch (error) {
        console.error('Error in loadAndRenderFooterScripts:', error);
    }
}

// Initialize script loading
loadAndRenderFooterScripts();
