```python
from flask import Flask, request, jsonify
from functools import wraps
import logging
import sqlite3
from datetime import datetime

app = Flask(__name__)

# Configure Logging
logging.basicConfig(filename='api.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Sample In-Memory Cache for Version and Timestamps
cache = {
    # 'resource_id': {'version': version_number, 'timestamp': timestamp}
}

def rate_limit(limit=100):
    """Rate limiting decorator."""
    def decorator(func):
        last_called = {}

        @wraps(func)
        def wrapped(*args, **kwargs):
            client_ip = request.remote_addr
            now = datetime.now()

            if client_ip in last_called:
                elapsed_time = (now - last_called[client_ip]).total_seconds()

                if elapsed_time < 60 / limit:
                    return jsonify({"error": "Rate limit exceeded"}), 429

            last_called[client_ip] = now
            return func(*args, **kwargs)
        return wrapped
    return decorator

def get_db_connection():
    conn = sqlite3.connect('database.db')
    conn.row_factory = sqlite3.Row
    return conn

@app.route('/resource/<int:resource_id>', methods=['PUT'])
@rate_limit(limit=100)
def update_resource(resource_id):
    data = request.get_json()
    version = data.get("version")
    last_modified_since = request.headers.get('If-Unmodified-Since')

    conn = get_db_connection()
    resource = conn.execute('SELECT * FROM resources WHERE id = ?', (resource_id,)).fetchone()

    if not resource:
        return jsonify({"error": "Resource not found"}), 404

    current_version = cache.get(resource_id, {}).get("version")
    last_modified_timestamp = datetime.strptime(resource['last_modified'], '%Y-%m-%d %H:%M:%S')

    # Check version number for optimistic concurrency
    if version and int(version) != current_version:
        return jsonify({"error": "Version mismatch"}), 412

    # Check timestamp condition
    if last_modified_since:
        specified_timestamp = datetime.strptime(last_modified_since, '%a, %d %b %Y %H:%M:%S GMT')
        if last_modified_timestamp > specified_timestamp:
            return jsonify({"error": "Resource has been modified"}), 409

    # Perform update within a transaction
    try:
        with conn:
            conn.execute('UPDATE resources SET data = ?, version = version + 1, last_modified = ? WHERE id = ?',
                         (data['new_data'], datetime.now().strftime('%Y-%m-%d %H:%M:%S'), resource_id))

        # Update cache
        updated_resource = conn.execute('SELECT * FROM resources WHERE id = ?', (resource_id,)).fetchone()
        cache[resource_id] = {'version': updated_resource['version'], 'timestamp': updated_resource['last_modified']}

    except Exception as e:
        logging.error(f"Update failed: {str(e)}")
        return jsonify({"error": "Internal server error"}), 500

    return jsonify(updated_resource), 200

@app.route('/resource/<int:resource_id>', methods=['DELETE'])
@rate_limit(limit=100)
def delete_resource(resource_id):
    version = request.args.get('version')
    last_modified_since = request.headers.get('If-Unmodified-Since')

    conn = get_db_connection()
    resource = conn.execute('SELECT * FROM resources WHERE id = ?', (resource_id,)).fetchone()

    if not resource:
        return jsonify({"error": "Resource not found"}), 404

    current_version = cache.get(resource_id, {}).get("version")
    last_modified_timestamp = datetime.strptime(resource['last_modified'], '%Y-%m-%d %H:%M:%S')

    # Check version number for optimistic concurrency
    if version and int(version) != current_version:
        return jsonify({"error": "Version mismatch"}), 412

    # Check timestamp condition
    if last_modified_since:
        specified_timestamp = datetime.strptime(last_modified_since, '%a, %d %b %Y %H:%M:%S GMT')
        if last_modified_timestamp > specified_timestamp:
            return jsonify({"error": "Resource has been modified"}), 409

    try:
        with conn:
            affected_rows = conn.execute('DELETE FROM resources WHERE id = ?', (resource_id,)).rowcount
            if affected_rows == 0:
                return jsonify({"error": "Resource not found or already deleted"}), 404

        # Invalidate cache
        cache.pop(resource_id, None)

    except Exception as e:
        logging.error(f"Delete failed: {str(e)}")
        return jsonify({"error": "Internal server error"}), 500

    return '', 204

if __name__ == '__main__':
    app.run(debug=True)

# Unit Tests
