        with self.conn:
            self.conn.execute('UPDATE resources SET last_modified = ? WHERE id = ?', 
                              (datetime.now().strftime('%Y-%m-%d %H:%M:%S'), 1))

        response = self.app.delete('/resource/1', headers={'If-Unmodified-Since': 'Mon, 01 Jan 2020 00:00:00 GMT'})
        self.assertEqual(response.status_code, 409)

if __name__ == '__main__':
    unittest.main()
