```cpp
#include <iostream>
#include <vector>
#include <memory>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <stdexcept>

class OctreeNode {
public:
    struct DataPoint {
        // Represents a generic spatial data point, e.g., position or bounding box.
        float x, y, z;
        DataPoint(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}
    };

    std::mutex nodeMutex;  // Fine-grained lock for this node.
    bool isLeaf = true;
    int depth = 0;
    std::vector<std::unique_ptr<OctreeNode>> children;
    std::vector<DataPoint> points;

    OctreeNode(int depth_) : depth(depth_) {}

    void insert(DataPoint point);
};

void OctreeNode::insert(DataPoint point) {
    std::lock_guard<std::mutex> lock(nodeMutex);

    if (depth == 0 || isLeaf) {
        // Simplified logic for leaf nodes.
        points.push_back(point);

        if (points.size() > MAX_POINTS_PER_NODE && depth < MAX_DEPTH) {
            splitNode();
        }
        return;
    }

    // Determine the appropriate child node for insertion.
    int index = getOctantIndexForPoint(point);
    if (!children[index]) {
        children[index] = std::make_unique<OctreeNode>(depth - 1);
    }
    children[index]->insert(point);
}

int OctreeNode::getOctantIndexForPoint(const DataPoint& point) {
    // Logic to determine the child index based on spatial location.
    int index = 0;
    if (point.x > 0.5f) index |= 4;
    if (point.y > 0.5f) index |= 2;
    if (point.z > 0.5f) index |= 1;
    return index;
}

void OctreeNode::splitNode() {
    isLeaf = false;
    for (int i = 0; i < 8; ++i) {
        children[i] = std::make_unique<OctreeNode>(depth - 1);
    }

    // Redistribute points to child nodes.
    for (auto& point : points) {
        int index = getOctantIndexForPoint(point);
        children[index]->insert(point);
    }
    points.clear();
}

class Octree {
public:
    static const int MAX_POINTS_PER_NODE = 10;
    static const int MAX_DEPTH = 5;

    std::unique_ptr<OctreeNode> root;
    mutable std::mutex treeMutex; // Protects the whole tree structure.

    Octree() : root(std::make_unique<OctreeNode>(MAX_DEPTH)) {}

    void insert(DataPoint point) {
        if (!root) throw std::runtime_error("Octree not initialized.");

        std::lock_guard<std::mutex> lock(treeMutex);
        root->insert(point);
    }
};

// Example usage:
void simulateConcurrentInsertions(Octree& octree, const std::vector<OctreeNode::DataPoint>& points, int numThreads) {
    auto worker = [&octree, &points](int start, int end) {
        for (int i = start; i < end; ++i) {
            octree.insert(points[i]);
        }
    };

    int step = points.size() / numThreads;
    std::vector<std::thread> threads;

    for (int i = 0; i < numThreads; ++i) {
        int start = i * step;
        int end = (i == numThreads - 1) ? points.size() : start + step;
        threads.emplace_back(worker, start, end);
    }

    for (auto& thread : threads) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}

int main() {
    Octree octree;

    std::vector<OctreeNode::DataPoint> points = {
        {0.1f, 0.2f, 0.3f}, {0.4f, 0.5f, 0.6f}, /* ... more points ... */};

    simulateConcurrentInsertions(octree, points, 4);

    return 0;
}
```

This code initializes an octree with fine-grained locking to support concurrent insertions and accesses from multiple threads. It handles dynamic memory allocation for nodes and includes logic for splitting nodes when they exceed a maximum point capacity. The `OctreeNode::insert` method determines where points should be inserted, supports rebalancing by redistributing points upon node splits, and ensures that data integrity is maintained with mutexes.

