public class TaskMicroservice {

    private final ExecutorService executor;
    private final Map<String, ServerInfo> servers = new ConcurrentHashMap<>();
    private final BlockingQueue<Task> taskQueue = new LinkedBlockingQueue<>();
    private volatile boolean running = true;

    public TaskMicroservice(List<String> serverAddresses) {
        this.executor = Executors.newCachedThreadPool();
        initializeServers(serverAddresses);
    }

    @PostConstruct
    public void start() {
        executor.submit(this::processTasks);
        // Optionally, another thread for monitoring and analytics integration.
    }

    private void initializeServers(List<String> addresses) {
        for (String address : addresses) {
            servers.put(address, new ServerInfo(new InetSocketAddress(address.split(":")[0], Integer.parseInt(address.split(":")[1]))));
        }
    }

    public List<ExecutionResult> submitTasks(List<Task> tasks) {
        tasks.forEach(taskQueue::offer);
        // Implement priority and deadline handling
        return null; // Return appropriate response or future results.
    }

    private void processTasks() {
        while (running || !taskQueue.isEmpty()) {
            Task task = taskQueue.poll();
            if (task != null) {
                try {
                    ServerInfo server = selectServerForTask(task);
                    executeTaskOnServer(server, task);
                } catch (Exception e) {
                    handleTaskFailure(task);
                }
            }
        }
    }

    private ServerInfo selectServerForTask(Task task) {
        // Implement dynamic load balancing logic
        return servers.values().stream().min(Comparator.comparingInt(ServerInfo::getLoad)).orElse(null);
    }

    private void executeTaskOnServer(ServerInfo server, Task task) throws IOException {
        try (AsynchronousSocketChannel channel = AsynchronousSocketChannel.open()) {
            Future<Void> future = channel.connect(server.getAddress());
            if (!future.get()) return;

            ByteBuffer buffer = ByteBuffer.wrap(task.toBytes());
            channel.write(buffer).get();

            // Read response
            ByteBuffer readBuffer = ByteBuffer.allocate(1024);
            channel.read(readBuffer).get();
            ExecutionResult result = parseResponse(readBuffer.array());

            task.setExecutionResult(result);

        } catch (Exception e) {
            handleTaskFailure(task, server);
        }
    }

    private void handleTaskFailure(Task task, ServerInfo failedServer) {
        // Implement retry logic and queue handling
        servers.values().remove(failedServer);
        taskQueue.offer(task); // Re-queue the task for another attempt.
    }

    public void shutdown() {
        running = false;
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    private ExecutionResult parseResponse(byte[] responseBytes) {
