import sqlite3

class DatabaseConnector:
    def __init__(self, db_settings):
        self.db_settings = db_settings
        self.connection = None

    def connect(self):
        if not self.connection:
            self.connection = sqlite3.connect(self.db_settings['database'])

    def disconnect(self):
        if self.connection:
            self.connection.close()
            self.connection = None

    def store(self, data):
        self.connect()
        cursor = self.connection.cursor()

        try:
            # Assuming a table 'extracted_data' with suitable columns exists
            for item in data:
                placeholders = ', '.join('?' * len(item))
                query = f"INSERT INTO extracted_data VALUES ({placeholders})"
                cursor.execute(query, list(item.values()))

            self.connection.commit()
        except Exception as e:
            print(f"Database storage error: {e}")
        finally:
            self.disconnect()

