#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct DOMNode {
    char* tagName;
    struct DOMNode** children;
    size_t childCount;
} DOMNode;

typedef void (*ProcessCallback)(DOMNode*);

typedef struct MatchingNodes {
    DOMNode** nodes;
    size_t count;
    size_t capacity;
} MatchingNodes;

// Forward declarations
void traverseDOM(DOMNode* node, int depthLimit, ProcessCallback processCallback,
                 MatchingNodes* matchingNodes, pthread_mutex_t* mutex);
int matchSelector(DOMNode* node, void (*cssSelectorFunc)(DOMNode*, int));
void extendMatchingNodes(MatchingNodes* matchingNodes, DOMNode* node);

// Thread function for parallel traversal
void* traverseDOMParallel(void* args) {
    struct {
        DOMNode* node;
        int depthLimit;
        ProcessCallback processCallback;
        MatchingNodes* matchingNodes;
        pthread_mutex_t* mutex;
    } *traversalArgs = (struct {
        DOMNode* node;
        int depthLimit;
        ProcessCallback processCallback;
        MatchingNodes* matchingNodes;
        pthread_mutex_t* mutex;
    } *)args;

    traverseDOM(traversalArgs->node, traversalArgs->depthLimit,
                traversalArgs->processCallback, traversalArgs->matchingNodes, 
                traversalArgs->mutex);

    return NULL;
}

void traverseDOM(DOMNode* node, int depthLimit, ProcessCallback processCallback,
                 MatchingNodes* matchingNodes, pthread_mutex_t* mutex) {
    if (!node || !depthLimit) return;

    // Match the current node using the CSS selector function
    if (matchSelector(node, /* external CSS Selector Function */)) {
        pthread_mutex_lock(mutex);
        extendMatchingNodes(matchingNodes, node);
        pthread_mutex_unlock(mutex);

        if (processCallback) processCallback(node);
    }

    // Recursively traverse child nodes
    for (size_t i = 0; i < node->childCount; ++i) {
        traverseDOM(node->children[i], depthLimit - 1, processCallback,
                    matchingNodes, mutex);
    }
}

int matchSelector(DOMNode* node, void (*cssSelectorFunc)(DOMNode*, int)) {
    // Placeholder for integration with external CSS selector engine
    // Return 1 if the node matches, otherwise return 0
    cssSelectorFunc(node, /* additional parameters */);
    return 1; // Assume it matches for illustration purposes
}

void extendMatchingNodes(MatchingNodes* matchingNodes, DOMNode* node) {
    if (matchingNodes->count == matchingNodes->capacity) {
        size_t newCapacity = matchingNodes->capacity ? 
                             matchingNodes->capacity * 2 : 4;
        matchingNodes->nodes = realloc(matchingNodes->nodes,
                                       sizeof(DOMNode*) * newCapacity);
        matchingNodes->capacity = newCapacity;
    }
    matchingNodes->nodes[matchingNodes->count++] = node;
}

MatchingNodes* findDOMMatches(DOMNode* root, int depthLimit,
                              void (*cssSelectorFunc)(DOMNode*, int),
                              ProcessCallback processCallback) {
    MatchingNodes* result = malloc(sizeof(MatchingNodes));
    if (!result) return NULL;

    result->nodes = NULL;
    result->count = 0;
    result->capacity = 0;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    traverseDOM(root, depthLimit, processCallback, result, &mutex);

    pthread_mutex_destroy(&mutex);
    return result;
}

void freeMatchingNodes(MatchingNodes* matchingNodes) {
    if (!matchingNodes) return;

    for (size_t i = 0; i < matchingNodes->count; ++i) {
        // Handle node cleanup if necessary
    }
    free(matchingNodes->nodes);
    free(matchingNodes);
}

void processNodeExample(DOMNode* node) {
