from threading import Lock

# Simulating a database and external audit system
class Database:
    def __init__(self):
        self.orders = {}
        self.lock = Lock()

    def get_order(self, order_id):
        with self.lock:
            return self.orders.get(order_id)

    def update_order(self, order_id, delivery_person_id, delivery_time):
        with self.lock:
            if order_id in self.orders and not self.orders[order_id]['status'] == 'delivered':
                self.orders[order_id].update({'delivery_person_id': delivery_person_id, 'delivery_time': delivery_time, 'status': 'in_delivery'})
                return True
            else:
                return False

    def log_error(self, message):
        print(f"ERROR: {message}")

class AuditSystem:
    @staticmethod
    def log(message):
        print(f"Audit Log: {message}")


# Simulated database and audit system instances
db = Database()
audit_system = AuditSystem()


def rate_limited(max_calls_per_second):
    min_interval = 1.0 / float(max_calls_per_second)

    def decorate(func):
        last_time_called = [0.0]

        @wraps(func)
        def rate_limited_function(*args, **kwargs):
            elapsed = time.perf_counter() - last_time_called[0]
            left_to_wait = min_interval - elapsed
            if left_to_wait > 0:
                time.sleep(left_to_wait)
            ret_val = func(*args, **kwargs)
            last_time_called[0] = time.perf_counter()
            return ret_val

        return rate_limited_function

    return decorate


@cached(cache=TTLCache(maxsize=100, ttl=300))
def get_cached_order(order_id):
    order = db.get_order(order_id)
    if not order:
        audit_system.log(f"Order {order_id} not found.")
    return order

@rate_limited(5)  # Limit to 5 calls per second
def process_order(order_id, delivery_person_id, current_time):
    try:
        # Validate the order ID and fetch from cache if possible
        order = get_cached_order(order_id)

        if not order or order['status'] == 'delivered':
            return "Error: Invalid order ID or order already delivered.", 0

        # Update the order with transaction-like mechanism
        success = db.update_order(order_id, delivery_person_id, current_time)

        if success:
            audit_system.log(f"Order {order_id} updated successfully.")
            return f"Success: Order {order_id} processed.", 1
        else:
            db.log_error(f"Failed to update order {order_id}.")
            return "Error: Failed to process the order due to an unknown error.", 0

    except Exception as e:
        audit_system.log(f"Exception occurred: {str(e)}")
        return f"Error: An exception occurred while processing the order. Details: {str(e)}", 0


