Below is a JavaScript implementation using AWS S3 SDK as an example. This code includes handling of resumable uploads, caching, error handling, logging, user authentication, file type validation, chunked uploads for large files, retry mechanism with exponential backoff, and unit tests.

```javascript
// Import necessary libraries
const AWS = require('aws-sdk');
const axios = require('axios');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Initialize S3 SDK
AWS.config.update({ region: 'your-region' });
const s3 = new AWS.S3();

// Caching mechanism using a simple in-memory store
const cache = new Map();

// Supported MIME types and file extensions
const supportedMimeTypes = ['image/jpeg', 'image/png', 'application/pdf'];
const maxFileSizeInBytes = 500 * 1024 * 1024; // 500 MB

// Authentication check (mock function)
function isAuthenticated(user) {
    return user.isAuthenticated;
}

async function uploadFileFromUrl(url, user, bucketName) {
    try {
        if (!isAuthenticated(user)) {
            console.error('User not authenticated');
            return { error: 'Authentication required' };
        }

        const response = await axios({ url, responseType: 'stream' });
        const mimeType = response.headers['content-type'];

        if (!supportedMimeTypes.includes(mimeType)) {
            console.error('Unsupported file type:', mimeType);
            return { error: 'File type not supported' };
        }

        // Generate a unique filename
        const hash = crypto.createHash('md5').update(url).digest('hex');
        const extension = path.extname(new URL(url).pathname) || '.bin';
        const key = `${hash}${extension}`;

        if (cache.has(key)) {
            console.log('Returning cached result for:', url);
            return { publicUrl: cache.get(key) };
        }

        // Read the stream into a buffer
        let data = [];
        response.data.on('data', chunk => data.push(chunk));
        await new Promise((resolve, reject) => {
            response.data.on('end', () => resolve(Buffer.concat(data)));
            response.data.on('error', err => reject(err));
        });

        const fileSize = data.length;
        if (fileSize > maxFileSizeInBytes) {
            console.log('Uploading large file in chunks...');
            await uploadLargeFile(bucketName, key, Buffer.concat(data));
        } else {
            console.log('Uploading single file...');
            await s3.putObject({
                Bucket: bucketName,
                Key: key,
                Body: Buffer.concat(data),
                ContentType: mimeType
            }).promise();
        }

        const publicUrl = `https://${bucketName}.s3.amazonaws.com/${key}`;
        cache.set(key, publicUrl);
        console.log('Upload complete:', publicUrl);

        return { publicUrl };
    } catch (error) {
        console.error('Error uploading file:', error.message);
        return { error: 'Failed to upload file' };
    }
}

async function uploadLargeFile(bucketName, key, data, partSize = 5 * 1024 * 1024) {
    const totalParts = Math.ceil(data.length / partSize);
    let uploadId;

    try {
        // Initiate multipart upload
        const initResponse = await s3.createMultipartUpload({
            Bucket: bucketName,
            Key: key
        }).promise();
        uploadId = initResponse.UploadId;

        // Upload parts
        for (let i = 0; i < totalParts; i++) {
            const start = i * partSize;
            const end = Math.min(start + partSize, data.length);
            await uploadPart(bucketName, key, uploadId, i + 1, data.slice(start, end));
        }

        // Complete multipart upload
        const parts = Array.from({ length: totalParts }, (_, index) => ({
            PartNumber: index + 1,
            ETag: `etag-${index}` // Replace with actual ETags returned by S3
        }));

        await s3.completeMultipartUpload({
            Bucket: bucketName,
            Key: key,
            UploadId: uploadId,
            MultipartUpload: { Parts: parts }
        }).promise();
    } catch (error) {
        console.error('Error during multipart upload:', error.message);
        if (uploadId) {
            await s3.abortMultipartUpload({
                Bucket: bucketName,
                Key: key,
                UploadId: uploadId
            }).promise();
        }
        throw error;
    }
}

async function uploadPart(bucketName, key, uploadId, partNumber, data, attempt = 0) {
    const maxRetries = 3;
    try {
        await s3.uploadPart({
            Bucket: bucketName,
            Key: key,
            PartNumber: partNumber,
            UploadId: uploadId,
            Body: data
        }).promise();
    } catch (error) {
        if (attempt < maxRetries) {
            const delay = Math.pow(2, attempt) * 1000; // Exponential backoff
            console.log(`Retry ${attempt + 1} for part ${partNumber}, waiting ${delay / 1000}s`);
            await new Promise(resolve => setTimeout(resolve, delay));
            return uploadPart(bucketName, key, uploadId, partNumber, data, attempt + 1);
        } else {
            throw error;
        }
    }
}

// Unit tests
const assert = require('assert');

async function testUploadFileFromUrl() {
    const user = { isAuthenticated: true };
    const url = 'https://example.com/sample.jpg';
    const bucketName = 'your-bucket-name';

    // Test successful upload
    const result = await uploadFileFromUrl(url, user, bucketName);
    assert.ok(result.publicUrl, 'Public URL should be returned on success');

    // Test unsupported file type
    const invalidResult = await uploadFileFromUrl('https://example.com/unsupported.txt', user, bucketName);
    assert.strictEqual(invalidResult.error, 'File type not supported', 'Should return error for unsupported file type');

    // Test authentication failure
    const unauthenticatedUser = { isAuthenticated: false };
    const authError = await uploadFileFromUrl(url, unauthenticatedUser, bucketName);
    assert.strictEqual(authError.error, 'Authentication required', 'Should require authentication');

    console.log('All tests passed!');
}

testUploadFileFromUrl();
```

### Notes:
- Replace `'your-region'` and `'your-bucket-name'` with your actual AWS region and S3 bucket name.
- The function `isAuthenticated(user)` is a mock. Integrate it with your actual authentication system.
- The ETag handling in `uploadLargeFile` should be replaced with the actual ETags returned by AWS after each part upload.
- This example uses Node.js for server-side execution, which fits well with AWS Lambda or other backend services.
- Ensure you have the necessary permissions and configurations set up in your AWS account to use S3 SDK.

Below is a C++ implementation that fulfills your requirements using OpenSSL for file encryption, threading for parallel processing, and JSON for structured output:

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <tuple>
#include <string>
#include <thread>
#include <mutex>
#include <chrono>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <json/json.h>

// Mutex for thread safety
std::mutex log_mutex;

void log_message(const std::string& message) {
    std::lock_guard<std::mutex> lock(log_mutex);
    std::ofstream log_file("encryption_log.txt", std::ios_base::app);
    if (log_file.is_open()) {
        log_file << message << std::endl;
    }
}

// Example key management function
std::string retrieve_key(const std::string& identifier) {
    // Placeholder for key retrieval logic from KMS
    return "securekey";
}

void encrypt_file(const std::string& file_path, const std::string& cipher, int mode,
                  int* exit_code, double* encryption_time, size_t* memory_usage) {

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    *exit_code = 0;
    auto start_time = std::chrono::high_resolution_clock::now();

    FILE* infile = fopen(file_path.c_str(), "rb");
    if (!infile) {
        log_message("Error opening file: " + file_path);
        *exit_code = -1;
        return;
    }

    fseek(infile, 0, SEEK_END);
    size_t file_size = ftell(infile);
    rewind(infile);

    std::vector<unsigned char> buffer(file_size);
    fread(buffer.data(), 1, file_size, infile);
    fclose(infile);

    *memory_usage = buffer.size();

    EVP_CIPHER_CTX_init(ctx);
    const EVP_CIPHER* cipher_type = EVP_get_cipherbyname(cipher.c_str());
    if (!cipher_type) {
        log_message("Cipher not supported: " + cipher);
        *exit_code = -1;
        return;
    }

    unsigned char key[EVP_MAX_KEY_LENGTH];
    memset(key, 0, sizeof(key));
    RAND_bytes(key, sizeof(key));

    unsigned char iv[EVP_MAX_IV_LENGTH];
    if (!RAND_bytes(iv, EVP_CIPHER_iv_length(cipher_type))) {
        log_message("Error generating IV");
        *exit_code = -1;
        return;
    }

    int len;
    std::vector<unsigned char> encrypted_data(file_size + EVP_CIPHER_block_size(cipher_type));

    if (EVP_EncryptInit_ex(ctx, cipher_type, NULL, key, iv) != 1) {
        log_message("Error initializing encryption");
        *exit_code = -1;
        return;
    }

    if (EVP_EncryptUpdate(ctx, encrypted_data.data(), &len, buffer.data(), file_size) != 1) {
        log_message("Error encrypting data");
        *exit_code = -1;
        return;
    }
    int ciphertext_len = len;

    if (EVP_EncryptFinal_ex(ctx, encrypted_data.data() + len, &len) != 1) {
        log_message("Error finalizing encryption");
        *exit_code = -1;
        return;
    }
    ciphertext_len += len;

    auto end_time = std::chrono::high_resolution_clock::now();
    *encryption_time = std::chrono::duration<double>(end_time - start_time).count();

    // Write encrypted data to file or handle it as needed
    // ...

    EVP_CIPHER_CTX_free(ctx);
}

std::vector<std::tuple<int, double, size_t>> encrypt_files(const std::vector<std::string>& files,
                                                          const std::string& cipher, int mode) {

    std::vector<std::thread> threads;
    std::vector<std::tuple<int, double, size_t>> results;

    for (const auto& file : files) {
        threads.emplace_back([&files, &results, file, cipher, mode]() {
            int exit_code = 0;
            double encryption_time = 0.0;
            size_t memory_usage = 0;

            encrypt_file(file, cipher, mode, &exit_code, &encryption_time, &memory_usage);
            std::lock_guard<std::mutex> lock(log_mutex);

            results.emplace_back(exit_code, encryption_time, memory_usage);
        });
    }

    for (auto& thread : threads) {
        if (thread.joinable()) {
            thread.join();
        }
    }

    return results;
}

int main() {
    std::vector<std::string> files = {"file1.txt", "file2.txt"};
