        $this->loadConfiguration();
    }

    private function detectEnvironment(): string {
        if (getenv('APP_ENV') === 'production') {
            return self::ENV_PRODUCTION;
        } elseif (getenv('APP_ENV') === 'testing') {
            return self::ENV_TESTING;
        }

        // Default to development.
        return self::ENV_DEVELOPMENT;
    }

    private function loadConfiguration() {
        try {
            $cacheKey = "config_{$this->environment}";
            $cachedConfig = $this->cache->getItem($cacheKey);

            if ($cachedConfig->isHit()) {
                $config = $cachedConfig->get();
            } else {
                $config = $this->fetchConfigurationFromDatabase();

                // Validate configuration with external API.
                if (!$this->validateConfigurationWithAPI($config)) {
                    throw new Exception('Validation failed.');
                }

                $this->cache->save($cachedConfig->set($config));
            }

            $this->setEnvironmentVariables($config);
        } catch (Exception $e) {
            // Log the error and fall back to default settings.
            $this->logger->error("Configuration loading failed: " . $e->getMessage());
            $this->applyDefaultSettings();
        }
    }

    private function fetchConfigurationFromDatabase(): array {
        $stmt = $this->dbConnection->prepare('SELECT * FROM config WHERE environment = :environment');
        $stmt->execute([':environment' => $this->environment]);

        return $stmt->fetchAll(PDO::FETCH_ASSOC);
    }

    private function validateConfigurationWithAPI(array $config): bool {
        // Simulate an API call.
        try {
            $response = file_get_contents('https://api.example.com/validate', false, stream_context_create([
                'http' => [
                    'method'  => 'POST',
                    'header'  => "Content-Type: application/json\r\n",
                    'content' => json_encode($config)
                ]
            ]));

            $result = json_decode($response, true);

            if ($result['status'] !== 'success') {
                throw new Exception('API validation error');
            }

            return true;
        } catch (Exception $e) {
            // Log API errors.
            $this->logger->error("API validation failed: " . $e->getMessage());
            return false;
        }
    }

    private function setEnvironmentVariables(array $config): void {
        foreach ($config as $key => $value) {
            putenv("$key=$value");
        }
    }

    private function applyDefaultSettings(): void {
        $defaultConfig = [
            'DB_HOST' => 'localhost',
            'APP_NAME' => 'MyApp',
            // Other default settings...
        ];

        foreach ($defaultConfig as $key => $value) {
            putenv("$key=$value");
        }
    }
}

