using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml;
using System.Xml.Linq;
using System.Xml.XPath;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class XmlParserService
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private readonly ILogger<XmlParserService> _logger;
    private readonly string[] _apiEndpoints;

    public XmlParserService(HttpClient httpClient, IMemoryCache cache, ILogger<XmlParserService> logger, string[] apiEndpoints)
    {
        _httpClient = httpClient;
        _cache = cache;
        _logger = logger;
        _apiEndpoints = apiEndpoints;
    }

    public async Task<XElement> GetFirstXmlElementAsync(string xmlUrl, string xpathQuery, string schemaName)
    {
        var xmlDocument = await FetchXmlDocumentAsync(xmlUrl);
        ValidateSchema(xmlDocument, schemaName);

        var elements = xmlDocument.XPathSelectElements(xpathQuery);
        if (elements.Count() == 0)
            throw new Exception("No element found.");
        if (elements.Count() > 1)
            throw new Exception("Multiple elements found.");

        return elements.First();
    }

    private async Task<XDocument> FetchXmlDocumentAsync(string url)
    {
        if (!_cache.TryGetValue(url, out XDocument cachedDocument))
        {
            var document = await RetrieveWithRetry(() => _httpClient.GetStringAsync(url));
            cachedDocument = XDocument.Parse(document);

            _cache.Set(url, cachedDocument, new MemoryCacheEntryOptions
            {
                Size = 1,
                Priority = CacheItemPriority.Normal,
                SlidingExpiration = TimeSpan.FromMinutes(10)
            });
        }

        return cachedDocument;
    }

    private void ValidateSchema(XDocument document, string schemaName)
    {
        var schemaUrl = _apiEndpoints.FirstOrDefault(endpoint => endpoint.Contains(schemaName));
        if (schemaUrl == null) throw new Exception("Invalid schema name.");

        var schemaXml = FetchXmlSchemaAsync(schemaUrl).Result;

        XDocument schemaDoc = XDocument.Parse(schemaXml);
        XmlReader reader = document.CreateReader();

        try
        {
            XmlSchemaSet schemas = new XmlSchemaSet();
            schemas.Add("", XmlReader.Create(new System.IO.StringReader(schemaDoc.ToString())));
            document.Validate(schemas, (o, e) => 
            {
                _logger.LogError(e.Message);
                throw new Exception($"Schema validation failed: {e.Message}");
            });
        }
        catch (XmlException ex)
        {
            _logger.LogError(ex, "XML Parsing error.");
            throw;
        }
    }

    private async Task<string> FetchXmlSchemaAsync(string schemaUrl)
    {
        return await RetrieveWithRetry(() => _httpClient.GetStringAsync(schemaUrl));
    }

    private async Task<T> RetrieveWithRetry<T>(Func<Task<T>> operation, int maxRetries = 3, TimeSpan? delay = null)
    {
        delay ??= TimeSpan.FromSeconds(2);

        for (int retry = 0; retry < maxRetries; retry++)
        {
            try
            {
                return await operation();
            }
            catch (HttpRequestException) when (retry < maxRetries - 1)
            {
                await Task.Delay(delay.Value);
                delay = TimeSpan.FromMilliseconds(delay.Value.TotalMilliseconds * 2);
            }
        }

        throw new Exception("Failed to fetch data from external API.");
    }
}
```

