class NodeManager {
private:
    std::vector<Node> nodes;
    mutable std::mutex mtx;

public:
    void loadFromFile(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) throw std::runtime_error("Failed to open file.");

        Json::Value root;
        file >> root;
        for (const auto& elem : root["nodes"]) {
            Node node;
            node.key = elem["key"].asInt();
            node.value = elem["value"].asString();
            addNode(node);
        }
    }

    void addNode(const Node& node) {
        std::lock_guard<std::mutex> lock(mtx);
        nodes.push_back(node);
        if (nodes.size() > 100) resizeArray();
    }

    void removeNode(int key) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::remove_if(nodes.begin(), nodes.end(),
                                 [key](const Node& node) { return node.key == key; });
        nodes.erase(it, nodes.end());
    }

    void updateNode(int key, const std::string& newValue) {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& node : nodes) {
            if (node.key == key) {
                node.value = newValue;
                break;
            }
        }
    }

    void resizeArray() {
        // Implement dynamic resizing logic
    }

    Json::Value serializeToJson() const {
        std::lock_guard<std::mutex> lock(mtx);
        Json::Value root;
        for (const auto& node : nodes) {
            Json::Value elem;
            elem["key"] = node.key;
            elem["value"] = node.value;
            root["nodes"].append(elem);
        }
        return root;
    }

    void displayJson() const {
        std::cout << serializeToJson().toStyledString() << std::endl;
    }
};

class DatabaseManager {
private:
    std::unordered_map<Node, std::future<std::vector<Node>>, std::hash<Node>> cache;

public:
    std::vector<Node> executeProcedureAsync(const Node& node) {
        auto cached = cache.find(node);
        if (cached != cache.end()) return cached->second.get();

        auto futureResult = std::async(std::launch::async, [this, node]() -> std::vector<Node> {
            // Simulate database call
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            return {node};  // Return the result as a list of nodes
        });

        cache[node] = std::move(futureResult);
        return futureResult.get();
    }

    void clearCache() {
        for (auto& entry : cache) {
            if (entry.second.valid()) {
                entry.second.wait();  // Ensure completion before clearing
            }
        }
        cache.clear();
    }
};

