```cpp
#include <iostream>
#include <unordered_map>
#include <vector>
#include <memory>
#include <mutex>
#include <shared_mutex>
#include <condition_variable>
#include <thread>
#include <functional>

class AdvancedOctreeManager {
public:
    struct Node {
        float x, y, z;
        float size;
        std::unique_ptr<Node> children[8];
        mutable std::shared_mutex nodeMutex;

        Node(float _x, float _y, float _z, float _size)
            : x(_x), y(_y), z(_z), size(_size) {}
    };

private:
    std::unique_ptr<Node> root;
    std::unordered_map<std::string, std::function<void()>> sensors;
    mutable std::shared_mutex treeMutex;
    std::condition_variable treeCV;
    const float maxSizeLimit = 1.2f; // 20% over the initial size

    int nodeCount = 0;

public:
    AdvancedOctreeManager(float rootSize) {
        root = std::make_unique<Node>(0, 0, 0, rootSize);
    }

    void configureSensor(const std::string& sensorId, std::function<void()> updateFunc) {
        sensors[sensorId] = std::move(updateFunc);
    }

    bool getSpatialDataPoint(const std::string& sensorId, float x, float y, float z) {
        if (sensors.find(sensorId) == sensors.end()) return false;

        std::shared_lock lock(treeMutex);
        Node* currentNode = root.get();
        traverseAndRetrieve(currentNode, x, y, z);

        return true; // Add meaningful retrieval logic here
    }

private:
    void traverseAndRetrieve(Node* node, float x, float y, float z) {
        std::unique_lock lock(node->nodeMutex);

        if (shouldSplitNode(x, y, z, *node)) {
            splitNode(node);
        }

        // Traverse to the relevant child
        int index = getOctantIndex(x, y, z, node);
        if (!node->children[index]) {
            float newSize = node->size / 2;
            Node* newChild = new Node(
                node->x + (index & 1) * newSize - newSize / 2,
                node->y + ((index >> 1) & 1) * newSize - newSize / 2,
                node->z + ((index >> 2) & 1) * newSize - newSize / 2,
                newSize
            );
            node->children[index] = std::unique_ptr<Node>(newChild);
        }

        traverseAndRetrieve(node->children[index].get(), x, y, z);

        lock.unlock();
    }

    bool shouldSplitNode(float x, float y, float z, const Node& node) {
        return (std::abs(x - node.x) > maxSizeLimit * (node.size / 2)) ||
               (std::abs(y - node.y) > maxSizeLimit * (node.size / 2)) ||
               (std::abs(z - node.z) > maxSizeLimit * (node.size / 2));
    }

    void splitNode(Node* node) {
        for (int i = 0; i < 8; ++i) {
            float newSize = node->size / 2;
            Node* newChild = new Node(
                node->x + ((i & 1) ? newSize : -newSize) / 2,
                node->y + ((i & 2) ? newSize : -newSize) / 2,
                node->z + ((i & 4) ? newSize : -newSize) / 2,
                newSize
            );
            node->children[i] = std::unique_ptr<Node>(newChild);
        }
    }

    int getOctantIndex(float x, float y, float z, const Node& node) {
        int index = 0;
        if (x >= node.x) index |= 1;
        if (y >= node.y) index |= 2;
        if (z >= node.z) index |= 4;
        return index;
    }

public:
    void updateNodeConcurrently(const std::string& sensorId, float x, float y, float z) {
        auto sensorFunc = sensors[sensorId];
        std::lock_guard lock(treeMutex);
        treeCV.notify_all();
        sensorFunc(); // Simulated data handling
        getSpatialDataPoint(sensorId, x, y, z); // Update octree based on the new point
    }

    void reportPerformanceMetrics() {
        std::shared_lock lock(treeMutex);
        std::cout << "Node Count: " << nodeCount << "\n";
        // Add more metrics reporting as needed.
    }
};

// Example of how one might use this class:

int main() {
    AdvancedOctreeManager octree(10.0f);

    octree.configureSensor("sensor1", []() { std::cout << "Updating sensor 1 data\n"; });

    octree.getSpatialDataPoint("sensor1", 1.0f, 2.0f, 3.0f);

    // Simulate concurrent updates
    std::thread updateThread([&octree]() {
        octree.updateNodeConcurrently("sensor1", 4.0f, 5.0f, 6.0f);
    });

    updateThread.join();
    octree.reportPerformanceMetrics();

    return 0;
