class JsonSerializable {
public:
    virtual ~JsonSerializable() = default;

    virtual std::string toJsonString() const = 0;

    static std::unique_ptr<JsonSerializable> fromJson(const std::string& jsonString);

protected:
    explicit JsonSerializable(const Json::Value& value) : data(value) {}

private:
    Json::Value data;
};

class Registry {
public:
    using FactoryFunc = std::function<std::unique_ptr<JsonSerializable>()>;

    void addFactoryFunction(int id, const FactoryFunc& func) {
        lock.lock();
        factories[id] = func;
        lock.unlock();
    }

    std::unique_ptr<JsonSerializable> createInstance(int id) {
        lock.lock();
        auto it = factories.find(id);
        if (it != factories.end()) {
            auto instance = it->second();
            lock.unlock();
            return instance;
        }
        lock.unlock();
        log("Factory function not found for ID: " + std::to_string(id));
        return nullptr;
    }

private:
    std::unordered_map<int, FactoryFunc> factories;
    mutable std::mutex lock; // Ensure thread safety
};

// Implementation of JsonSerializable fromJson method
std::unique_ptr<JsonSerializable> JsonSerializable::fromJson(const std::string& jsonString) {
    Json::Value root;
    Json::Reader reader;
    if (!reader.parse(jsonString, root)) {
        log("Failed to parse JSON string.");
        return nullptr;
    }
    // This would typically be dynamic based on the type of object
    return std::make_unique<ConcreteJsonSerializable>(root);
}

class ConcreteJsonSerializable : public JsonSerializable {
public:
    using JsonSerializable::JsonSerializable;

    std::string toJsonString() const override {
        Json::StreamWriterBuilder writer;
        return Json::writeString(writer, data);
    }
};

// Asynchronous file loading with error handling
void loadFilesAsync(const std::vector<std::string>& urls) {
    std::vector<std::future<void>> futures;

    for (const auto& url : urls) {
        futures.push_back(std::async(std::launch::async, [url]() {
            CURL* curl = curl_easy_init();
            if(curl) {
                curl_easy_setopt(curl, CURLOPT_URL, url.c_str());

                // Set other options like timeouts or headers as needed

                CURLcode res = curl_easy_perform(curl);
                if(res != CURLE_OK) {
                    log("Failed to load file: " + std::string(url) + " Error: " + curl_easy_strerror(res));
                }
                curl_easy_cleanup(curl);
            } else {
                log("CURL initialization failed for URL: " + url);
            }
        }));
    }

    for (auto& future : futures) {
        try {
            future.get(); // Ensure all files are loaded
        } catch (...) {
            log("Exception occurred during file loading.");
        }
    }
}

