```python
import os
import re
import gzip
import zipfile
import csv
import json
from collections import Counter
from concurrent.futures import ProcessPoolExecutor
from statistics import mean, median, mode
import logging
from flask import Flask, request, jsonify

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

app = Flask(__name__)
EXCLUDE_PATTERNS = []  # User-defined patterns for exclusion

def process_file(file_path):
    try:
        if file_path.endswith('.gz'):
            with gzip.open(file_path, 'rt') as f:
                content = f.read()
        elif file_path.endswith('.zip'):
            with zipfile.ZipFile(file_path) as z:
                content = z.read(z.namelist()[0]).decode('utf-8')
        else:
            with open(file_path, 'r') as f:
                content = f.read()

        lines = content.splitlines()
        words = re.findall(r'\b\w+\b', content)
        char_count = len(content)

        if file_path.endswith('.csv'):
            unique_values = count_unique_csv_values(lines)
            stats_summary = calculate_stats_summary(csv.reader(lines))

        return {
            'file': file_path,
            'lines': len(lines),
            'words': len(words),
            'characters': char_count,
            'unique_values': unique_values if 'unique_values' in locals() else None,
            'stats_summary': stats_summary if 'stats_summary' in locals() else None
        }
    except Exception as e:
        logger.error(f"Error processing file {file_path}: {e}")
        return {}

def count_unique_csv_values(lines):
    unique_counts = {}
    for row in csv.reader(lines):
        for i, value in enumerate(row):
            if i not in unique_counts:
                unique_counts[i] = set()
            unique_counts[i].add(value)
    return {k: len(v) for k, v in unique_counts.items()}

def calculate_stats_summary(csv_reader):
    data = list(csv_reader)
    stats = {}
    for col_index in range(len(data[0])):
        column_data = [float(row[col_index]) for row in data[1:] if row[col_index].replace('.', '', 1).isdigit()]
        if column_data:
            stats[col_index] = {
                'mean': mean(column_data),
                'median': median(column_data),
                'mode': mode(column_data) if len(set(column_data)) > 1 else None
            }
    return stats

def process_directory(directory):
    results = []
    with ProcessPoolExecutor() as executor:
        futures = []
        for root, _, files in os.walk(directory):
            for file in files:
                file_path = os.path.join(root, file)
                if any(re.match(pattern, file) for pattern in EXCLUDE_PATTERNS):
                    continue
                futures.append(executor.submit(process_file, file_path))

        for future in futures:
            result = future.result()
            if result:
                results.append(result)

    return results

@app.route('/process', methods=['POST'])
def process():
    data = request.json
    directory = data.get('directory')
    exclude_patterns = data.get('exclude_patterns', [])

    global EXCLUDE_PATTERNS
    EXCLUDE_PATTERNS = exclude_patterns

    if not os.path.isdir(directory):
        return jsonify({'error': 'Invalid directory path'}), 400

    results = process_directory(directory)
    return jsonify(results)

@app.route('/export_csv', methods=['POST'])
def export_csv():
    data = request.json
    results = data.get('results')

    if not results:
        return jsonify({'error': 'No results to export'}), 400

    with open('output.csv', 'w', newline='') as csvfile:
        fieldnames = ['file', 'lines', 'words', 'characters', 'unique_values', 'stats_summary']
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)

        writer.writeheader()
        for result in results:
            row = {k: v if isinstance(v, str) else json.dumps(v) for k, v in result.items()}
            writer.writerow(row)

    return jsonify({'message': 'CSV exported successfully'})

if __name__ == '__main__':
    app.run(debug=True)

# Unit tests would be implemented using a framework like pytest
```

### Key Points:
- **Logging**: Integrated logging to track operations and errors.
- **File Handling**: Supports `.txt`, `.log`, `.csv`, `.gz`, and `.zip` files.
- **Concurrency**: Uses `ProcessPoolExecutor` for concurrent file processing.
- **CSV Processing**: Counts unique values and calculates statistics.
- **Web Interface**: Flask app provides endpoints for processing and exporting results.
- **Error Handling**: Graceful error handling with logging.

