import json
import os
import asyncio
from concurrent.futures import ThreadPoolExecutor
from typing import Callable, Dict, List
import hashlib

class JSONManager:
    _registry: Dict[str, Callable] = {}

    def __init__(self, data=None):
        if isinstance(data, dict):
            self.__dict__.update(data)
        else:
            self.__dict__ = {}

    @classmethod
    async def load_files(cls, file_paths: List[str]):
        loop = asyncio.get_event_loop()
        with ThreadPoolExecutor() as pool:
            tasks = [loop.run_in_executor(pool, cls._load_file, path) for path in file_paths]
            results = await asyncio.gather(*tasks, return_exceptions=True)

        loaded_files = {}
        for result in results:
            if isinstance(result, Exception):
                print(f"Error loading file: {result}")
            else:
                loaded_files.update(result)

        cls._execute_scripts(loaded_files)

    @staticmethod
    def _load_file(file_path: str) -> Dict:
        try:
            with open(file_path, 'r') as file:
                data = json.load(file)
            return {os.path.basename(file_path): data}
        except Exception as e:
            return e

    @classmethod
    def _execute_scripts(cls, loaded_files: Dict):
        for path, content in loaded_files.items():
            if isinstance(content, dict):
                try:
                    # Simulate execution of script logic here
                    cls._process_content(path, content)
                except Exception as e:
                    print(f"Error executing file {path}: {e}")

    @staticmethod
    def _process_content(file_path: str, content: Dict):
        factory_id = content.get("factoryId")
        if factory_id and factory_id in JSONManager._registry:
            obj = JSONManager._registry[factory_id](**content)
            print(f"Created object from {file_path}: {obj}")

    @classmethod
    def register_factory(cls, id_: str, factory_func: Callable):
        cls._registry[id_] = factory_func

    @classmethod
    def create_instance(cls, id_: str, **kwargs):
        if id_ in cls._registry:
            return JSONManager._registry[id_](**kwargs)
        raise ValueError(f"No registered factory for ID: {id_}")

    def to_json(self) -> str:
        return json.dumps(self.__dict__)

    @classmethod
    def from_json(cls, json_str: str):
        data = json.loads(json_str)
        return cls(data)

    @staticmethod
    def deserialize(byte_data: bytes):
        # Simulate deserialization logic
        return JSONManager()  # Placeholder for actual deserialized object

    @staticmethod
    def generate_random_string_from_byte_array(byte_data: bytes) -> str:
        return hashlib.sha256(byte_data).hexdigest()

    def hash_password(self, password: str) -> str:
        return hashlib.sha256(password.encode()).hexdigest()

    def manipulate_forward_list(self, forward_list: List[str], find_str: str, insert_str: str, position_idx: int = None):
        try:
            if position_idx is not None and (position_idx < 0 or position_idx >= len(forward_list)):
                raise IndexError("Position index out of bounds")

            found_at = -1
            for i in range(len(forward_list)):
                if forward_list[i] == find_str:
                    if position_idx is None or i == position_idx:
                        found_at = i + 1
                        break

            if found_at != -1 and found_at <= len(forward_list):
                forward_list.insert(found_at, insert_str)
            else:
                forward_list.append(insert_str)

        except Exception as e:
            print(f"Error manipulating list: {e}")

# Example factory functions for demonstration
def example_factory_function(**kwargs):
    return JSONManager(kwargs)

# Usage of the JSONManager class
JSONManager.register_factory("example", example_factory_function)

async def main():
    file_paths = ["file1.json", "file2.json"]
    await JSONManager.load_files(file_paths)

    json_str = '{"factoryId": "example", "key1": "value1"}'
    obj = JSONManager.from_json(json_str)
    print(obj.to_json())

    byte_data = b'some_byte_array'
    deserialized_obj = JSONManager.deserialize(byte_data)
    random_string = JSONManager.generate_random_string_from_byte_array(byte_data)

    password_hash = obj.hash_password("mypassword")
    print(f"Random String: {random_string}, Password Hash: {password_hash}")

    forward_list = ["a", "b", "c"]
    obj.manipulate_forward_list(forward_list, "b", "inserted", 1)
    print(forward_list)

# Run the main function
asyncio.run(main())
