```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using PKCS11Interop.Common; // Assuming a library is used for PKCS#11 interaction

public class FileEncryptor
{
    private readonly IKcs11Library _kcs11Library;
    private const int BufferSize = 4096 * 1024; // 4MB buffer size
    private static readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);

    public FileEncryptor(string pkcs11ModulePath)
    {
        _kcs11Library = Factory.GetPkcs11Library(pkcs11ModulePath);
        _kcs11Library.OpenSession(s => s.IsTokenPresent = true).Session.Login(SessionType.ReadOnly, "password"); // Use appropriate credentials
    }

    public async Task<byte[]> EncryptFileAsync(string filePath)
    {
        await _semaphore.WaitAsync();
        try
        {
            using var aesGcm = new AesGcm(await GetEncryptionKey());
            byte[] nonce = GenerateNonce();
            byte[] tag;
            using var encryptedStream = File.OpenWrite(filePath + ".enc");
            using var inputStream = File.OpenRead(filePath);
            await encryptedStream.WriteAsync(nonce, 0, nonce.Length);

            byte[] buffer = new byte[BufferSize];
            int bytesRead;

            while ((bytesRead = await inputStream.ReadAsync(buffer, 0, BufferSize)) > 0)
            {
                byte[] encryptedChunk = new byte[buffer.Length + aesGcm.TagLength];
                aesGcm.Encrypt(nonce, buffer.AsSpan(0, bytesRead), null, encryptedChunk.AsSpan(), out tag);
                await encryptedStream.WriteAsync(encryptedChunk, 0, encryptedChunk.Length);
            }

            StoreFileMetadata(filePath, nonce, tag);

            return Convert.ToBase64String(tag); // Return the tag for integrity verification
        }
        finally
        {
            _semaphore.Release();
        }
    }

    public async Task<byte[]> DecryptFileAsync(string filePath, byte[] expectedTag)
    {
        await _semaphore.WaitAsync();
        try
        {
            using var aesGcm = new AesGcm(await GetEncryptionKey());
            byte[] nonce;
            byte[] tag;

            using var encryptedStream = File.OpenRead(filePath);
            using var decryptedStream = File.Create(filePath + ".dec");

            nonce = new byte[AesGcm.NonceByteSizes.MaxSize];
            await encryptedStream.ReadAsync(nonce, 0, nonce.Length);

            int bytesRead;
            byte[] buffer = new byte[BufferSize + aesGcm.TagLength];

            while ((bytesRead = await encryptedStream.ReadAsync(buffer, 0, buffer.Length)) > 0)
            {
                byte[] decryptedChunk = new byte[buffer.Length - aesGcm.TagLength];
                tag = new byte[aesGcm.TagLength];
                Array.Copy(buffer, bytesRead - aesGcm.TagLength, tag, 0, aesGcm.TagLength);

                if (!tag.SequenceEqual(expectedTag))
                    throw new CryptographicException("Data integrity check failed.");

                aesGcm.Decrypt(nonce, buffer.AsSpan(0, bytesRead - aesGcm.TagLength), tag, decryptedChunk);

                await decryptedStream.WriteAsync(decryptedChunk, 0, decryptedChunk.Length);
            }

            return File.ReadAllBytes(filePath + ".dec");
        }
        finally
        {
            _semaphore.Release();
        }
    }

    private byte[] GetEncryptionKey()
    {
        // Retrieve key from HSM. This is a simplified representation.
        using var session = _kcs11Library.OpenSession(s => s.IsTokenPresent = true);
        session.Login(SessionType.ReadWrite, "password"); // Use appropriate credentials

        object obj = session.FindObjectsInit().FindObjectClass(CKA.KeyType).GetAttribute(CKA.Certificate);
        return (byte[])obj; // Simplified key retrieval. Adapt as needed.
    }

    private byte[] GenerateNonce()
    {
        byte[] nonce = new byte[AesGcm.NonceByteSizes.MaxSize];
        using var rng = RandomNumberGenerator.Create();
        rng.GetBytes(nonce);
        return nonce;
    }

    private void StoreFileMetadata(string filePath, byte[] nonce, byte[] tag)
    {
        // Assume a method to store metadata in distributed storage system.
        DistributedStorageSystem.StoreMetadata(filePath, nonce, tag); 
    }
}

// Assuming an interface representing the distributed storage system
