```rust
use std::env;
use std::fs::{self, Permissions};
use std::io;
use std::path::{Path, PathBuf};
use tempfile::Builder;
use log::{info, error};

// Plugin system trait definitions
trait CIPreAction {
    fn execute(&self) -> io::Result<()>;
}

trait CIPostAction {
    fn execute(&self) -> io::Result<()>;
}

struct FileManager;

impl FileManager {
    fn get_work_dir() -> Result<PathBuf, String> {
        match env::var("WORK_DIR") {
            Ok(dir) => {
                if Path::new(&dir).exists() && fs::metadata(&dir).unwrap().permissions().readonly() == false {
                    info!("Using existing WORK_DIR: {}", dir);
                    Ok(PathBuf::from(dir))
                } else {
                    error!("Invalid WORK_DIR environment variable.");
                    Err("WORK_DIR is invalid or inaccessible.".to_string())
                }
            },
            Err(_) => {
                let new_dir = Builder::new()
                    .prefix("ci_work_")
                    .tempdir_in("/tmp")
                    .map_err(|e| e.to_string())?;

                info!("Created new temporary WORK_DIR: {}", new_dir.path().display());
                Ok(new_dir.into_path())
            }
        }
    }

    fn cleanup(&self, dir: &Path) -> io::Result<()> {
        if dir.exists() {
            fs::remove_dir_all(dir).map_err(|e| {
                error!("Failed to clean up directory {}: {}", dir.display(), e);
                e
            })?;
        } else {
            info!("Directory {} does not exist, nothing to cleanup.", dir.display());
        }
        Ok(())
    }

    fn run_with_plugins<T: CIPreAction + CIPostAction>(&self, plugin: &T) -> io::Result<()> {
        plugin.execute()?;

        let work_dir = self.get_work_dir()?;

        // Run the pipeline logic here...

        plugin.execute()?;
        self.cleanup(&work_dir)?;
        Ok(())
    }
}

// Example implementations of CIPreAction and CIPostAction
struct MyPreAction;
impl CIPreAction for MyPreAction {
    fn execute(&self) -> io::Result<()> {
        info!("Executing pre-action tasks.");
        // Custom logic here...
        Ok(())
    }
}

struct MyPostAction;
impl CIPostAction for MyPostAction {
    fn execute(&self) -> io::Result<()> {
        info!("Executing post-action cleanup tasks.");
        // Custom logic here...
        Ok(())
    }
}
