```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class MediaAssetManager
{
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly string _uploadEndpoint = "https://cloudstorage.example.com/upload";
    private readonly string _tokenServiceUrl = "https://tokenservice.example.com/token";
    private string _accessToken;
    private DateTime _tokenExpiryTime;
    private readonly SemaphoreSlim _semaphore = new(5); // Allows up to 5 concurrent uploads

    public MediaAssetManager()
    {
        RefreshTokenAsync().Wait();
    }

    private async Task RefreshTokenAsync()
    {
        var response = await _httpClient.PostAsync(_tokenServiceUrl, null);
        if (response.IsSuccessStatusCode)
        {
            var tokenData = await response.Content.ReadAsAsync<TokenResponse>();
            _accessToken = tokenData.AccessToken;
            _tokenExpiryTime = DateTime.UtcNow.AddSeconds(tokenData.ExpiresIn);
        }
    }

    public async Task<UploadResult> UploadFileAsync(string filePath, CancellationToken cancellationToken = default)
    {
        try
        {
            using var semaphoreScope = await _semaphore.WaitAsync(cancellationToken);
            if (string.IsNullOrEmpty(_accessToken) || _tokenExpiryTime < DateTime.UtcNow)
            {
                await RefreshTokenAsync();
            }

            long fileSize = new FileInfo(filePath).Length;
            byte[] fileData = File.ReadAllBytes(filePath);

            return await UploadDataAsync(fileData, cancellationToken);
        }
        catch (Exception ex)
        {
            return new UploadResult { Success = false, ErrorMessage = ex.Message };
        }
    }

    public async Task<UploadResult> UploadDataAsync(byte[] data, CancellationToken cancellationToken = default)
    {
        try
        {
            using var semaphoreScope = await _semaphore.WaitAsync(cancellationToken);
            if (string.IsNullOrEmpty(_accessToken) || _tokenExpiryTime < DateTime.UtcNow)
            {
                await RefreshTokenAsync();
            }

            int chunkSize = CalculateChunkSize(data.Length);
            for (int i = 0; i < data.Length; i += chunkSize)
            {
                var chunk = new ArraySegment<byte>(data, i, Math.Min(chunkSize, data.Length - i));
                if (!await UploadChunkAsync(chunk, cancellationToken))
                {
                    return new UploadResult { Success = false, ErrorMessage = "Upload failed during chunk transfer." };
                }
            }

            return new UploadResult { Success = true };
        }
        catch (Exception ex)
        {
            return new UploadResult { Success = false, ErrorMessage = ex.Message };
        }
    }

    private bool ValidateToken()
    {
        if (string.IsNullOrEmpty(_accessToken) || _tokenExpiryTime < DateTime.UtcNow)
        {
            RefreshTokenAsync().Wait();
            return true;
        }
        return false;
    }

    private async Task<bool> UploadChunkAsync(ArraySegment<byte> chunk, CancellationToken cancellationToken)
    {
        using var content = new ByteArrayContent(chunk.Array, chunk.Offset, chunk.Count);
        _httpClient.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _accessToken);

        var response = await _httpClient.PostAsync(_uploadEndpoint + "/chunk", content, cancellationToken);
        return response.IsSuccessStatusCode;
    }

    private int CalculateChunkSize(long fileSize)
    {
        // Dynamic chunking strategy based on file size and network conditions
        if (fileSize < 10 * 1024 * 1024) // Less than 10MB
            return 1 * 1024 * 1024; // 1 MB
        else if (fileSize < 100 * 1024 * 1024) // Between 10MB and 100MB
            return 5 * 1024 * 1024; // 5 MB
        else
            return 10 * 1024 * 1024; // 10 MB for larger files
    }
}

public class UploadResult
{
    public bool Success { get; set; }
    public string ErrorMessage { get; set; }
    public string RetrySuggestion { get; set; }
}

public class TokenResponse
{
    public string AccessToken { get; set; }
    public int ExpiresIn { get; set; }
}
