```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <memory>
#include <stdexcept>

class OctreeNode {
public:
    bool isLeaf;
    std::vector<std::unique_ptr<OctreeNode>> children;
    std::vector<int> data;  // Example placeholder for spatial data.

    OctreeNode() : isLeaf(true) {}
};

class OctreeSpatialPartitioner {
private:
    struct Bounds {
        float minX, minY, minZ;
        float maxX, maxY, maxZ;
    };

    std::unique_ptr<OctreeNode> root;
    int depth;
    int capacity;  // Max number of data points per leaf node.
    Bounds bounds;

    void subdivide(OctreeNode* node) {
        if (node->isLeaf && node->data.size() > capacity) {
            float xMid = (bounds.minX + bounds.maxX) / 2.0f;
            float yMid = (bounds.minY + bounds.maxY) / 2.0f;
            float zMid = (bounds.minZ + bounds.maxZ) / 2.0f;

            node->isLeaf = false;
            for (int i = 0; i < 8; ++i) {
                std::unique_ptr<OctreeNode> child(new OctreeNode());

                // Define the boundaries of each child.
                float minX, minY, minZ, maxX, maxY, maxZ;
                if (i & 1) { minX = xMid; } else { minX = bounds.minX; }
                if (i & 2) { minY = yMid; } else { minY = bounds.minY; }
                if (i & 4) { minZ = zMid; } else { minZ = bounds.minZ; }

                if (i & 1) { maxX = bounds.maxX; } else { maxX = xMid; }
                if (i & 2) { maxY = bounds.maxY; } else { maxY = yMid; }
                if (i & 4) { maxZ = bounds.maxZ; } else { maxZ = zMid; }

                child->bounds = {minX, minY, minZ, maxX, maxY, maxZ};

                node->children.push_back(std::move(child));
            }

            // Distribute existing data to children.
            for (int d : node->data) {
                addData(d);
            }
            node->data.clear();
        }
    }

public:
    OctreeSpatialPartitioner(int depth, int capacity, Bounds bounds)
        : depth(depth), capacity(capacity), bounds(bounds) {
        root = std::make_unique<OctreeNode>();
    }

    void addData(int dataPoint) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto node = findNodeForData(root.get(), depth);
        if (node->data.size() < capacity) {
            node->data.push_back(dataPoint);
        } else {
            subdivide(node);
            addData(dataPoint);  // Add again since node is now subdivided.
        }
    }

private:
    std::mutex mutex_;

    OctreeNode* findNodeForData(OctreeNode* node, int remainingDepth) {
        if (node->isLeaf || remainingDepth == 0) {
            return node;
        }

        // Implement logic to determine which child the data point belongs to.
        int index = /* Determine appropriate child index based on spatial location */;
        return findNodeForData(node->children[index].get(), remainingDepth - 1);
    }
};

