function FindElementsBySelector(node, selector, callback) {
    if (!node || typeof node !== 'object' || !selector || typeof selector !== 'string') {
        throw new Error('Invalid arguments');
    }

    const result = [];

    function traverse(node) {
        for (let childNode of node.childNodes) {
            // Apply the callback to test class or ID.
            if (callback(childNode, selector)) {
                result.push(childNode);
            }

            if (childNode.nodeType === Node.ELEMENT_NODE) {
                traverse(childNode);
            }
        }
    }

    traverse(node);

    return result;
}

