std::mutex forwardListMutex;

/**
 * @brief Inserts a new node with the specified value after the first occurrence 
 *        of a given target value in a forward list.
 *
 * If the target value is not found, the function inserts the new node at the end
 * of the list. Handles large lists efficiently and ensures thread safety using mutexes.
 * Implements error handling for database connectivity issues and memory allocation errors.
 * Designed to be easily extendable for future features like versioning or caching.
 *
 * @param forwardList The forward_list into which a new node will be inserted.
 * @param targetValue The value after which the new node should be inserted.
 * @param newValue The value of the new node to insert.
 */
void insertAfterTarget(std::forward_list<int>& forwardList, int targetValue, int newValue) {
    std::lock_guard<std::mutex> lock(forwardListMutex);

    try {
        auto it = forwardList.before_begin();
        for (auto currIt = forwardList.begin(); currIt != forwardList.end(); ++currIt) {
            if (*currIt == targetValue) {
                forwardList.insert_after(currIt, newValue);
                LOG_INFO("Inserted %d after first occurrence of %d.", newValue, targetValue); // Using logging framework
                return;
            }
        }

        // If target value is not found, insert at the end
        forwardList.push_back(newValue);
        LOG_INFO("Target value %d not found. Inserted %d at the end of the list.", targetValue, newValue);

    } catch (const std::bad_alloc& e) {
        LOG_ERROR("Memory allocation failed: %s", e.what());
        throw std::runtime_error("Failed to allocate memory for new node.");
    } catch (...) {
        LOG_ERROR("An unexpected error occurred while inserting the node.");
        throw;
    }

    // Simulating database update operation
    if (!updateDatabaseWithNewNode(newValue)) {  // Assume this is a function from an external DB API
        LOG_ERROR("Failed to update database with new node value: %d.", newValue);
        throw std::runtime_error("Database connectivity issue.");
    }
}

// Example Usage:
int main() {
    std::forward_list<int> myList = {1, 2, 3, 4};

    try {
        insertAfterTarget(myList, 3, 5); // Should insert 5 after the first occurrence of 3
        for (const auto& val : myList) {
            std::cout << val << " ";
        }
        std::cout << std::endl;

        insertAfterTarget(myList, 10, 6); // Should insert 6 at the end since 10 is not in the list
        for (const auto& val : myList) {
            std::cout << val << " ";
        }
        std::cout << std::endl;
    } catch (const std::exception& e) {
        LOG_ERROR("Exception occurred: %s", e.what());
    }

    return 0;
}
