```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/resource.h>

#define MAX_URLS 100
#define DEFAULT_MAX_THREADS 5

typedef struct {
    char *url;
    int index;
} UrlInfo;

typedef struct {
    char *memory;
    size_t size;
} MemoryStruct;

void *download_content(void *arg);
size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata);
int check_system_load(int max_threads);

// Command-line options
static int max_concurrent_downloads = DEFAULT_MAX_THREADS;
static char output_file[256] = "./output";
static int log_level = 1;

void parse_command_line_options(int argc, char **argv) {
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            max_concurrent_downloads = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            strncpy(output_file, argv[++i], sizeof(output_file) - 1);
        } else if (strcmp(argv[i], "-l") == 0 && i + 1 < argc) {
            log_level = atoi(argv[++i]);
        }
    }
}

int main(int argc, char **argv) {
    parse_command_line_options(argc, argv);

    // URLs to scrape
    const char *urls[MAX_URLS] = {"http://example.com", "http://another-example.com"};
    UrlInfo url_infos[MAX_URLS];
    for (int i = 0; i < MAX_URLS && urls[i]; ++i) {
        url_infos[i].url = strdup(urls[i]);
        url_infos[i].index = i;
    }

    int num_urls = 0;
    while (urls[num_urls]) num_urls++;

    pthread_t threads[max_concurrent_downloads];
    int active_threads = 0;

    for (int i = 0; i < num_urls; ++i) {
        if (active_threads >= max_concurrent_downloads || !check_system_load(max_concurrent_downloads)) {
            // Wait for a thread to finish
            pthread_join(threads[0], NULL);
            active_threads--;
        }

        pthread_create(&threads[active_threads++], NULL, download_content, &url_infos[i]);
    }

    for (int i = 0; i < active_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < num_urls; ++i) {
        free(url_infos[i].url);
    }

    return 0;
}

void *download_content(void *arg) {
    UrlInfo *info = (UrlInfo *)arg;
    CURL *curl;
    CURLcode res;

    MemoryStruct chunk;
    chunk.memory = malloc(1);
    chunk.size = 0;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, info->url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            // Process the downloaded content
            printf("Downloaded content from %s\n", info->url);
            // Additional processing like metadata extraction and data validation can be added here
        }

        curl_easy_cleanup(curl);
    }
    free(chunk.memory);

    return NULL;
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    MemoryStruct *mem = (MemoryStruct *)userdata;

    size_t new_size = mem->size + size * nmemb;
    mem->memory = realloc(mem->memory, new_size);
    if (!mem->memory) {
        // Out of memory
        return 0;
    }

    memcpy(&(mem->memory[mem->size]), ptr, size * nmemb);
    mem->size = new_size;

    return size * nmemb;
}

int check_system_load(int max_threads) {
    struct rlimit rl;
    if (getrlimit(RLIMIT_NOFILE, &rl) == 0 && rl.rlim_cur > 0) {
        int num_open_files = rl.rlim_cur - max_threads;
        if (num_open_files < 0) return 0;

        // Simplified load check: compare open files to a threshold
        return num_open_files < (max_concurrent_downloads * 2);
    }
    return 0;
}
```

