```php
<?php

class UserNotFoundException extends Exception {}
class InvalidEmailException extends Exception {}

class UserAuthentication {

    private $users = [
        'john_doe' => [
            'password_hash' => '$2y$12$s1s3mBnMkZlWfz7Y4LX8Ou5P6VrjD9v0gqHcKtQwN0hGdEJiXbR7e', // Example bcrypt hash
            'salt' => 'random_salt_string',
            'email' => 'john@example.com'
        ]
    ];

    private $tokens = [];
    private const RATE_LIMIT_ATTEMPTS = 5;
    private const TOKEN_EXPIRY_TIME = 3600; // 1 hour

    private $failedAttempts = [];

    public function authenticateUser($username, $password) {
        if (!isset($this->users[$username])) {
            return "Username not found.";
        }

        if ($this->isRateLimited($username)) {
            return "Too many failed attempts. Try again later.";
        }

        $salt = $this->retrieveSalt($username);
        $storedHash = $this->users[$username]['password_hash'];

        if (password_verify($password . $salt, $storedHash)) {
            // Reset the attempt count after successful login
            unset($this->failedAttempts[$username]);
            return "Authentication successful.";
        } else {
            $this->recordFailedAttempt($username);
            return "Password is incorrect.";
        }
    }

    public function changeUserPassword($username, $newPassword) {
        if (!isset($this->users[$username])) {
            throw new UserNotFoundException("Username not found.");
        }

        // Generate a new salt and hash the password
        $salt = bin2hex(random_bytes(16));
        $options = ['cost' => 12];
        $passwordHash = password_hash($newPassword . $salt, PASSWORD_BCRYPT, $options);

        // Simulate atomic update using transactions or locking mechanism in real-world scenario
        $this->users[$username]['password_hash'] = $passwordHash;
        $this->users[$username]['salt'] = $salt;

        return "Password changed successfully.";
    }

    public function forgotPassword($email) {
        foreach ($this->users as $user => $details) {
            if ($details['email'] === $email) {
                $token = bin2hex(random_bytes(16));
                $expiryTime = time() + self::TOKEN_EXPIRY_TIME;
                $this->tokens[$token] = ['username' => $user, 'expires_at' => $expiryTime];

                // Simulate sending email
                mail($email, "Password Reset", "Use this token to reset your password: $token");

                return "Password reset email sent.";
            }
        }

        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            throw new InvalidEmailException("Invalid email format.");
        }

        return "Email not found in our records.";
    }

    public function resetPasswordUsingToken($token, $newPassword) {
        if (!isset($this->tokens[$token])) {
            return "Invalid or expired token.";
        }

        $tokenData = $this->tokens[$token];

        if (time() > $tokenData['expires_at']) {
            unset($this->tokens[$token]);
            return "Token has expired.";
        }

        // Update password
        $username = $tokenData['username'];
        return $this->changeUserPassword($username, $newPassword);
    }

    private function retrieveSalt($username) {
        if (!isset($this->users[$username])) {
            throw new UserNotFoundException("Username not found.");
        }
        return $this->users[$username]['salt'];
    }

    private function isRateLimited($username) {
        $currentTime = time();
        $attempts = &$this->failedAttempts[$username] ?? [];
        $attempts = array_filter($attempts, fn($time) => ($currentTime - $time) < 3600);

        return count($attempts) >= self::RATE_LIMIT_ATTEMPTS;
    }

    private function recordFailedAttempt($username) {
        $this->failedAttempts[$username][] = time();
    }
}

