async function runTests(moduleLabel, testSuite) {
    try {
        console.log(`Loading module: ${moduleLabel}`);
        const module = require(moduleLabel);

        for (const test of testSuite) {
            // Each test is an object with a label and a testFunction
            const { label, testFunction } = test;

            describe(label, async function() {
                before(async () => {
                    console.log(`Initializing blueslip mocking library for test: ${label}`);
                    await blueslip.init();
                });

                after(async () => {
                    console.log(`Resetting and cleaning up blueslip for test: ${label}`);
                    await blueslip.reset();
                });

                it('should run the test', async function() {
                    try {
                        console.log(`Running test: ${label}`);
                        await testFunction(module);
                    } catch (error) {
                        console.error(`Error in test "${label}":`, error.message);
                        this.test.skip(); // Skip further actions to avoid interference
                    }
                });

                afterEach(async () => {
                    // Optional cleanup for each individual test if necessary
                    console.log(`Cleaning up resources after test: ${label}`);
                });
            });
        }

