            return version.StartsWith(RequiredDotNetVersion);
        }

        private static bool ValidateAndReadFile(string filePath, out List<int> integers)
        {
            integers = new();

            try
            {
                if (!File.Exists(filePath))
                {
                    LogError($"File not found: {filePath}");
                    return false;
                }

                var directoryInfo = new DirectoryInfo(Path.GetDirectoryName(filePath));
                if (!directoryInfo.Exists || !HasAccess(directoryInfo.FullName))
                {
                    LogError($"Directory access denied or does not exist: {directoryInfo.FullName}");
                    return false;
                }

                foreach (var line in File.ReadAllLines(filePath).Where(line => int.TryParse(line, out _)))
                {
                    integers.Add(int.Parse(line));
                }
            }
            catch (Exception ex)
            {
                LogError($"Error reading file {filePath}: {ex.Message}");
                integers = null;
                return false;
            }

            if (!integers.Any())
            {
                LogWarning($"No valid integers found in {filePath}");
                return false;
            }

            return true;
        }

        private static bool HasAccess(string path)
        {
            try
            {
                FileIOPermission permission = new(FileIOPermissionAccess.PathDiscovery, path);
                permission.Demand();
                return true;
            }
            catch (SecurityException)
            {
                return false;
            }
        }

        private static void LogError(string message)
        {
            Console.Error.WriteLine($"ERROR: {message}");
        }

        private static void LogWarning(string message)
        {
            Console.WriteLine($"WARNING: {message}");
        }

        private static async Task ValidateAndCorrectSitesAsync(IEnumerable<string> directories)
        {
            var tasks = directories.Select(async directory =>
            {
                try
                {
                    var webConfigPath = Path.Combine(directory, "web.config");
                    if (File.Exists(webConfigPath))
                    {
                        XElement webConfig = XElement.Load(webConfigPath);
                        // Validate and correct sites here
                    }
                }
                catch (Exception ex)
                {
                    LogError($"Failed to validate/fix site in {directory}: {ex.Message}");
                }
            });

            await Task.WhenAll(tasks);
        }
    }
}
