Now, here's a Python script that processes files in a directory and provides a web interface:

```python
import os
import gzip
import zipfile
import json
from flask import Flask, request, jsonify, render_template, session
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.secret_key = 'supersecretkey'

file_statistics = {}

def process_file(file_path):
    file_extension = os.path.splitext(file_path)[1]
    if file_extension == '.gz':
        with gzip.open(file_path, 'rt') as f:
            data = f.read()
    elif file_extension == '.zip':
        with zipfile.ZipFile(file_path, 'r') as z:
            for filename in z.namelist():
                with z.open(filename) as f:
                    data = f.read().decode('utf-8')
    else:
        with open(file_path, 'r') as f:
            data = f.read()

    lines = data.splitlines()
    words = data.split()
    chars = list(data)

    return len(lines), len(words), len(chars)

@app.route('/')
def index():
    if not session.get('logged_in'):
        return render_template('login.html')
    else:
        return render_template('dashboard.html', stats=file_statistics)

@app.route('/login', methods=['POST'])
def login():
    username = request.form['username']
    password = request.form['password']

    # This should be replaced with a proper user management system
    if username == 'admin' and check_password_hash(generate_password_hash("password"), password):
        session['logged_in'] = True
        return "Logged in successfully"
    else:
        return "Invalid credentials"

@app.route('/logout')
def logout():
    session.pop('logged_in', None)
    return "Logged out"

@app.route('/process_directory', methods=['POST'])
def process_directory():
    directory = request.form['directory']
    exclusions = request.form.getlist('exclusions')

    for root, _, files in os.walk(directory):
        for file_name in files:
            if any(file_name.endswith(ext) for ext in exclusions):
                continue
            file_path = os.path.join(root, file_name)
            try:
                lines, words, chars = process_file(file_path)
                file_type = os.path.splitext(file_name)[1]
                file_statistics.setdefault(file_type, {'lines': 0, 'words': 0, 'chars': 0})
                file_statistics[file_type]['lines'] += lines
                file_statistics[file_type]['words'] += words
                file_statistics[file_type]['chars'] += chars
            except Exception as e:
                print(f"Error processing {file_name}: {e}")

    return jsonify(file_statistics)

if __name__ == '__main__':
    app.run(debug=True, port=5000)
```

