<?php

class RateLimitExceededException extends Exception {}
class UserNotFoundException extends Exception {}

class UserAuthentication {
    private $users = [];
    private $loginAttempts = [];
    private $passwordResetTokens = [];

    public function __construct() {
        // Simulated database with users
        $this->users['exampleUser'] = [
            'username' => 'exampleUser',
            'passwordHash' => password_hash('password123', PASSWORD_BCRYPT, ['cost' => 12]),
            'salt' => base64_encode(random_bytes(16)),
        ];
    }

    private function getCurrentTime() {
        return time();
    }

    public function authenticateUser($username, $password) {
        if (!isset($this->users[$username])) {
            throw new UserNotFoundException("Username not found.");
        }

        if (isset($this->loginAttempts[$username]) && 
            count($this->loginAttempts[$username]) >= 3 &&
            ($this->getCurrentTime() - end($this->loginAttempts[$username])[0] < 300)) {
            throw new RateLimitExceededException("Rate limit exceeded.");
        }

        $user = $this->users[$username];
        if (password_verify($password, $user['passwordHash'])) {
            unset($this->loginAttempts[$username]); // Reset on successful login
            return "Authenticated successfully.";
        } else {
            if (!isset($this->loginAttempts[$username])) {
                $this->loginAttempts[$username] = [];
            }
            $this->loginAttempts[$username][] = [$this->getCurrentTime()];

            if (count($this->loginAttempts[$username]) > 3) {
                array_shift($this->loginAttempts[$username]); // Remove oldest attempt
            }

            return "Invalid password.";
        }
    }

    public function changeUserPassword($username, $newPassword) {
        if (!isset($this->users[$username])) {
            throw new UserNotFoundException("Username not found.");
        }

        $lock = fopen(__DIR__ . "/$username.lock", 'c+');
        flock($lock, LOCK_EX);

        $salt = base64_encode(random_bytes(16));
        $hashedPassword = password_hash($newPassword, PASSWORD_BCRYPT, ['cost' => 12]);

        $this->users[$username]['passwordHash'] = $hashedPassword;
        $this->users[$username]['salt'] = $salt;

        flock($lock, LOCK_UN);
        fclose($lock);

        return "Password changed successfully.";
    }

    public function forgotPassword($email) {
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return "Invalid email format.";
        }

        // Simulated user retrieval by email
        $user = array_filter($this->users, fn($u) => strtolower($u['username']) === strtolower(str_replace('@', '.', $email)));
        if (empty($user)) {
            return "Email not found.";
        }

        // CAPTCHA verification assumed to be successful

        $token = bin2hex(random_bytes(16));
        $expiresAt = time() + 3600; // Token expires in one hour

        $this->passwordResetTokens[$email] = [
            'token' => $token,
            'expiresAt' => $expiresAt
        ];

        // Simulate sending email (details omitted)

        return "Password reset email sent.";
    }

    public function resetPasswordUsingToken($token, $newPassword) {
        foreach ($this->passwordResetTokens as &$data) {
            if ($data['token'] === $token && $data['expiresAt'] > time()) {
                // Simulate optimistic locking
                $lock = fopen(__DIR__ . "/token.lock", 'c+');
                flock($lock, LOCK_EX);

                unset($this->passwordResetTokens[array_search($data, $this->passwordResetTokens)]); // Invalidate token

                // Retrieve user from email (details omitted)
                // Assume we find the user
                $username = 'exampleUser'; 

                $salt = base64_encode(random_bytes(16));
                $hashedPassword = password_hash($newPassword, PASSWORD_BCRYPT, ['cost' => 12]);

                $this->users[$username]['passwordHash'] = $hashedPassword;
                $this->users[$username]['salt'] = $salt;

                flock($lock, LOCK_UN);
                fclose($lock);

                return "Password reset successfully.";
            }
        }

        return "Invalid or expired token.";
    }

    public function retrieveSalt($username) {
        if (!isset($this->users[$username])) {
            throw new UserNotFoundException("Username not found.");
        }

        // Simulated caching logic (details omitted)

        return $this->users[$username]['salt'];
    }
}
