```javascript
const { Transform } = require('stream');
const { createWriteStream, createReadStream } = require('fs');
const { pipeline } = require('stream/promises');
const util = require('util');
const dbLogger = require('./dbLogger'); // Assume this is a module to log data to an external database

async function copyBytesFromChunks(chunks, byteCount) {
    const totalLength = chunks.reduce((sum, chunk) => sum + chunk.length, 0);

    if (byteCount > totalLength) {
        throw new Error('Requested byte count exceeds available data.');
    }

    return new Promise((resolve, reject) => {
        let copiedBytes = 0;
        const resultBuffer = Buffer.alloc(byteCount);
        let currentOffset = 0;

        const transformStream = new Transform({
            readableObjectMode: true,
            writableObjectMode: true,

            async _transform(chunk, encoding, callback) {
                try {
                    if (typeof chunk !== 'object' || !chunk.buffer || typeof chunk.byteLength !== 'number') {
                        throw new Error('Chunk data integrity issue.');
                    }

                    const available = Math.min(byteCount - copiedBytes, chunk.byteLength);
                    resultBuffer.copy(currentOffset, chunk.buffer, 0, available);

                    currentOffset += available;
                    copiedBytes += available;

                    if (copiedBytes === byteCount) {
                        this.push(resultBuffer.slice(0, copiedBytes));
                        callback();
                    } else {
                        callback();
                    }

                } catch (err) {
                    dbLogger.logError(err);
                    callback(new Error('Data copying error: ' + err.message));
                }
            }
        });

        pipeline(
            chunks.map(chunk => new Transform({
                readableObjectMode: true,
                writableObjectMode: true,

                async _transform(buffer, encoding, callback) {
                    this.push({ buffer, byteLength: buffer.length });
                    callback();
                }
            })),
            transformStream,
            (err) => {
                if (err) {
                    dbLogger.logError(err);
                    return reject(err);
                }
                resolve(resultBuffer.slice(0, copiedBytes));
            }
        );
    });
}

// Usage example
(async () => {
    try {
        const chunks = [
            createReadStream('file1.bin'),
            createReadStream('file2.bin')
        ];

        const result = await copyBytesFromChunks(chunks, 1024);

        // Use the copied data as needed
        console.log(result);

    } catch (error) {
        console.error('Error copying bytes:', error.message);
    }
})();
```

### Explanation:
- **Stream Processing**: The code uses Node.js streams to process chunks of data concurrently without blocking other processes.

- **Buffer Handling**: It utilizes `Transform` streams to merge multiple chunk buffers into a single buffer efficiently.

- **Error Handling and Logging**: Errors are logged using an external logging utility (`dbLogger`). This ensures that any issues during the processing, such as integrity problems or byte count mismatches, are captured.

- **Resource Management**: The use of streams inherently manages resources better than manual buffering, reducing memory usage and potential leaks.

- **Concurrency and Performance**: Leveraging Node.js's asynchronous capabilities allows for concurrent handling of data without blocking, ensuring smooth operation even with large datasets. 

