<?php

class ClinicUpdater {
    private $db;
    private $logger;
    private $cache;
    private $mailer;

    public function __construct($db, $logger, $cache, $mailer) {
        $this->db = $db;
        $this->logger = $logger;
        $this->cache = $cache;
        $this->mailer = $mailer;
    }

    public function updateClinicStatus(array $clinicUpdates, $userId, $ipAddress) {
        try {
            // Start a transaction
            $this->db->beginTransaction();

            foreach ($clinicUpdates as $clinicUpdate) {
                $clinicId = $clinicUpdate['clinic_id'];
                if (!$this->validateClinicId($clinicId)) {
                    continue;
                }

                $currentRateLimit = $this->getRateLimit($ipAddress, $clinicId);
                if ($currentRateLimit > 5) {
                    throw new Exception("Rate limit exceeded for clinic ID: $clinicId");
                }

                // Fetch current status
                $oldStatus = $this->fetchCurrentStatus($clinicId);

                // Check cache and update only if necessary
                $cacheKey = "clinic_{$clinicId}_status";
                if ($this->cache->get($cacheKey) === $clinicUpdate['new_status']) {
                    continue;
                }

                // Update the clinic status in the database
                $stmt = $this->db->prepare(
                    'UPDATE clinics SET status = :status, last_modified_ip = :ip, last_modified_date = NOW() WHERE id = :id'
                );
                $stmt->execute([
                    ':status' => $clinicUpdate['new_status'],
                    ':ip'     => $ipAddress,
                    ':id'     => $clinicId
                ]);

                // Update cache
                $this->cache->set($cacheKey, $clinicUpdate['new_status']);

                // Log the update
                $this->logger->log([
                    'user_id'    => $userId,
                    'clinic_id'  => $clinicId,
                    'old_status' => $oldStatus,
                    'new_status' => $clinicUpdate['new_status'],
                    'ip_address' => $ipAddress,
                    'reason'     => $clinicUpdate['reason']
                ]);

                // Send notification email
                $this->mailer->send([
                    'to'       => $this->getClinicAdminEmail($clinicId),
                    'subject'  => "Status Update for Clinic ID: $clinicId",
                    'body'     => "The status has been updated from $oldStatus to {$clinicUpdate['new_status']} by user $userId."
                ]);

                // Increment rate limit counter
                $this->incrementRateLimit($ipAddress, $clinicId);
            }

            // Commit the transaction
            $this->db->commit();

        } catch (Exception $e) {
            // Rollback the transaction in case of error
            $this->db->rollBack();
            $this->logger->logError($e->getMessage());

            // Implement fallback mechanism if needed
            $this->fallbackMechanism();
        }
    }

    private function validateClinicId($clinicId) {
        // Validate clinic ID (assuming a simple integer check)
        return filter_var($clinicId, FILTER_VALIDATE_INT) !== false;
    }

    private function fetchCurrentStatus($clinicId) {
        $stmt = $this->db->prepare('SELECT status FROM clinics WHERE id = :id');
        $stmt->execute([':id' => $clinicId]);
        return $stmt->fetchColumn();
    }

    private function getRateLimit($ipAddress, $clinicId) {
        // Fetch the current rate limit from cache
        $cacheKey = "rate_limit_{$ipAddress}_{$clinicId}";
        return $this->cache->get($cacheKey, 0);
    }

    private function incrementRateLimit($ipAddress, $clinicId) {
        // Increment the rate limit counter in cache with expiration time of one hour
        $cacheKey = "rate_limit_{$ipAddress}_{$clinicId}";
        $currentCount = $this->getRateLimit($ipAddress, $clinicId);
        $this->cache->set($cacheKey, $currentCount + 1, 3600); // 1 hour expiration
    }

    private function getClinicAdminEmail($clinicId) {
        // Fetch the clinic admin email from database or configuration
        $stmt = $this->db->prepare('SELECT admin_email FROM clinics WHERE id = :id');
        $stmt->execute([':id' => $clinicId]);
        return $stmt->fetchColumn();
    }

    private function fallbackMechanism() {
        // Define a fallback mechanism to revert changes if necessary
        // This could involve logging, alerting, or compensating actions
    }
}

// Unit tests and further implementation of other required methods are assumed to be implemented separately.
