### Python: WebConfigurator

```python
import asyncio
from aiohttp import web
import ssl
import logging
import threading
import queue

class WebConfigurator:
    def __init__(self, port=8080, server_name='localhost', use_ssl=False, cert_file=None, key_file=None):
        self.port = port
        self.server_name = server_name
        self.use_ssl = use_ssl
        self.cert_file = cert_file
        self.key_file = key_file
        self.loop = asyncio.get_event_loop()
        self.app = web.Application()

    async def start(self):
        if self.use_ssl:
            ssl_context = ssl.create_default_context(ssl.Purpose.CLIENT_AUTH)
            ssl_context.load_cert_chain(certfile=self.cert_file, keyfile=self.key_file)

            runner = web.AppRunner(self.app)
            await runner.setup()
            site = web.TCPSite(runner, self.server_name, self.port, ssl_context=ssl_context)
        else:
            runner = web.AppRunner(self.app)
            await runner.setup()
            site = web.TCPSite(runner, self.server_name, self.port)

        logging.info(f'Starting server on {self.server_name}:{self.port}...')
        await site.start()

    def stop(self):
        logging.info('Stopping server...')
        self.loop.run_until_complete(self.app.shutdown())
        self.loop.run_until_complete(self.app.cleanup())

    def configure_routes(self, routes):
        for route in routes:
            self.app.router.add_route(route['method'], route['path'], route['handler'])

def handle_request(request):
    # Call C function to parse HTTP request
    parsed_data = parse_http_request_c(request.text)
    return web.Response(text=str(parsed_data))

# Example of setting up the server
if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)

    routes = [
        {'method': 'GET', 'path': '/', 'handler': handle_request}
    ]

    configurator = WebConfigurator(port=8443, use_ssl=True, cert_file='path/to/cert.pem', key_file='path/to/key.pem')
    configurator.configure_routes(routes)

    try:
        asyncio.run(configurator.start())
    except KeyboardInterrupt:
        configurator.stop()
```

### C: parse_http_request

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* headers;
    char* query_params;
} ParsedRequest;

ParsedRequest parse_http_request(const char *request) {
    ParsedRequest result = {NULL, NULL};
    const char *header_end = strstr(request, "\r\n\r\n");

    if (header_end != NULL) {
        size_t header_length = header_end - request + 4;
        result.headers = strndup(request, header_length);

        const char *query_start = strstr(header_end + 4, "GET /") ? header_end + 4 : strchr(header_end + 4, '?');
        if (query_start) {
            query_start += strlen("?");
            char *query_end = strstr(query_start, " ");
            size_t query_length = query_end - query_start;
            result.query_params = strndup(query_start, query_length);
        }
    }

    return result;
}

// Example usage
int main() {
    const char *http_request = "GET /index.html?name=example HTTP/1.1\r\nHost: localhost\r\nConnection: keep-alive\r\n\r\n";
    ParsedRequest parsed = parse_http_request(http_request);

    printf("Headers:\n%s\n", parsed.headers);
    printf("Query Params:\n%s\n", parsed.query_params);

    free(parsed.headers);
    free(parsed.query_params);

    return 0;
}
