#include <algorithm>
#include <filesystem>
#include <thread>
#include <mutex>
#include <condition_variable>

namespace fs = std::filesystem;

// Logger class (stub for integration with existing logging system)
class Logger {
public:
    static void log(const std::string& message) {
        // Integrate with your existing logging framework here
        std::cout << "LOG: " << message << std::endl;
    }
};

void processFile(const fs::path& filePath, int64_t& largestInt, long double& totalSum, size_t& count, std::mutex& dataMutex) {
    try {
        std::ifstream file(filePath);
        if (!file.is_open()) {
            Logger::log("Error opening file: " + filePath.string());
            return;
        }

        int64_t value;
        while (file >> value) {
            std::lock_guard<std::mutex> lock(dataMutex);
            largestInt = std::max(largestInt, value);
            totalSum += value;
            ++count;
        }

        if (file.bad()) {
            Logger::log("Error reading file: " + filePath.string());
        }
    } catch (const fs::filesystem_error& e) {
        Logger::log("Filesystem error: " + std::string(e.what()));
    } catch (...) {
        Logger::log("Unknown error processing file: " + filePath.string());
    }
}

void processDirectory(const fs::path& directoryPath, int64_t& largestInt, long double& totalSum, size_t& count) {
    std::vector<std::thread> threads;
    std::mutex dataMutex;

    for (const auto& entry : fs::recursive_directory_iterator(directoryPath)) {
        if (entry.is_regular_file() && entry.path().extension() == ".txt") {
            threads.emplace_back(processFile, entry.path(), std::ref(largestInt), std::ref(totalSum), std::ref(count), std::ref(dataMutex));
        }
    }

    for (auto& t : threads) {
        if (t.joinable()) {
            t.join();
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        Logger::log("Usage: <program> <input_directory> <output_file>");
        return EXIT_FAILURE;
    }

    fs::path inputDir = argv[1];
    std::string outputFilePath = argv[2];

    int64_t largestInt = LLONG_MIN;
    long double totalSum = 0.0;
    size_t count = 0;

    if (!fs::exists(inputDir) || !fs::is_directory(inputDir)) {
        Logger::log("Input directory does not exist or is not a directory.");
        return EXIT_FAILURE;
    }

    processDirectory(inputDir, largestInt, totalSum, count);

    if (count == 0) {
        Logger::log("No valid integers found in the files.");
        return EXIT_SUCCESS;
    }

    long double average = totalSum / count;

    std::ofstream outputFile(outputFilePath);
    if (!outputFile.is_open()) {
        Logger::log("Error opening output file: " + outputFilePath);
        return EXIT_FAILURE;
    }

    outputFile << "Largest Integer: " << largestInt << "\n";
    outputFile << "Average: " << average << "\n";

    Logger::log("Processing complete. Results written to " + outputFilePath);

    return EXIT_SUCCESS;
}
