std::shared_ptr<Attack> selectAttack(int characterType) {
    static const int defaultCooldown = 9;
    int cooldownPeriod = (characterType == 1) ? 7 : defaultCooldown; // Example of customizable cooldown

    static std::chrono::time_point<std::chrono::steady_clock> lastAttackTime;

    if (std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::steady_clock::now() - lastAttackTime).count() < cooldownPeriod) {
        log("Cooldown period active. Attack selection skipped.");
        return nullptr; // Cooldown period still active
    }

    // Randomly select an attack ID
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1);
    int attackId = dis(gen);

    try {
        auto selectedAttack = fetchAttackData(attackId);
        lastAttackTime = std::chrono::steady_clock::now();

        log("Selected Attack: " + selectedAttack->name);
        return selectedAttack;
    } catch (const std::exception& e) {
        log(std::string("Error fetching attack data: ") + e.what());
        return nullptr; // Return null in case of error
    }
}

// Example usage
int main() {
    for (int i = 0; i < 5; ++i) { 
        auto attack = selectAttack(0);
        if (attack) {
            std::cout << "Character uses: " << attack->name << "\n";
        } else {
            std::cout << "No attack selected.\n";
        }
        std::this_thread::sleep_for(std::chrono::seconds(3)); // Simulate time between attempts
    }

    return 0;
}
```

### Design Choices Explained

1. **Concurrency**:
   - A `std::mutex` is used to ensure that log writes are thread-safe, allowing the function to operate correctly in multi-threaded environments.

2. **Error Handling**:
   - Exception handling is employed when fetching attack data and writing logs. This gracefully manages potential network failures or file access issues without crashing the application.

3. **Performance Optimization**:
   - `std::shared_ptr` is used for attack objects to manage memory efficiently.
   - Minimized use of locks, focusing only on critical sections (logging), to reduce contention in high-concurrency environments.

4. **Configurable Cooldowns**:
   - The cooldown period can be adjusted based on character type, showcasing flexibility without compromising performance.

5. **Logging**:
   - Log entries are appended to a file with minimal locking overhead, ensuring that logging is efficient even under load.

