using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

namespace RandomNumberGeneratorApp
{
    public class Program
    {
        private static RandomNumberGenerator _rng = new RandomNumberGenerator();

        public static async Task Main(string[] args)
        {
            if (args.Length == 0)
            {
                Console.WriteLine("Please provide file paths as command-line parameters.");
                return;
            }

            var allNumbers = new List<int>();
            foreach (var filePath in args)
            {
                try
                {
                    if (!_rng.ValidateDirectory(filePath))
                    {
                        continue;
                    }

                    var numbers = await _rng.ProcessFileAsync(filePath);
                    if (numbers != null)
                    {
                        allNumbers.AddRange(numbers);
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error processing file {filePath}: {ex.Message}");
                }
            }

            if (allNumbers.Count == 0)
            {
                Console.WriteLine("No valid numbers processed.");
                return;
            }

            var maxNumber = allNumbers.Max();
            var average = allNumbers.Average();

            Console.WriteLine($"Largest Number: {maxNumber}");
            Console.WriteLine($"Average: {average}");

            await _rng.LogDataToDatabaseAsync(allNumbers);
        }
    }

    public class RandomNumberGenerator : IDisposable
    {
        private System.Security.Cryptography.RandomNumberGenerator _rng;

        static RandomNumberGenerator()
        {
            // Static initialization if needed
        }

        public RandomNumberGenerator()
        {
            _rng = System.Security.Cryptography.RandomNumberGenerator.Create();
        }

        ~RandomNumberGenerator()
        {
            Dispose(false);
        }

        public bool ValidateDirectory(string filePath)
        {
            var directoryPath = Path.GetDirectoryName(filePath);

            if (!Directory.Exists(directoryPath) || !File.Exists(Path.Combine(directoryPath, "web.config")))
            {
                return false;
            }

            // Additional validation logic for naming conventions
            return true;
        }

        public async Task<List<int>> ProcessFileAsync(string filePath)
        {
            try
            {
                var numbers = new List<int>();

                using (var reader = new StreamReader(filePath))
                {
                    string line;
                    while ((line = await reader.ReadLineAsync()) != null)
                    {
                        if (int.TryParse(line, out int number))
                        {
                            numbers.Add(number);
                        }
                    }
                }

                return numbers;
            }
            catch
            {
                // Log error or handle exception as needed
                return null;
            }
        }

        public async Task LogDataToDatabaseAsync(List<int> data)
        {
            using (var context = new DataDbContext())
            {
                await context.Database.EnsureCreatedAsync();

                var entry = new ProcessedData { Numbers = string.Join(",", data) };
                context.ProcessedDatas.Add(entry);
                await context.SaveChangesAsync();
            }
        }

        public int GenerateRandomNumber(int min, int max)
        {
            byte[] randomNumber = new byte[4];
            _rng.GetBytes(randomNumber);

            // Convert bytes to a positive integer
            uint generatedNumber = BitConverter.ToUInt32(randomNumber, 0) % (max - min + 1) + min;
            return (int)generatedNumber;
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        protected virtual void Dispose(bool disposing)
        {
            if (disposing && _rng != null)
            {
                _rng.Dispose();
                _rng = null;
            }
        }
    }

    public class DataDbContext : DbContext
    {
        public DbSet<ProcessedData> ProcessedDatas { get; set; }

        protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
        {
            optionsBuilder.UseSqlServer("YourConnectionStringHere");
        }
    }

    public class ProcessedData
    {
        public int Id { get; set; }
        public string Numbers { get; set; }
    }
}
