using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class AesDecryptorWithSemaphoreManager
{
    private static readonly HttpClient httpClient = new HttpClient();

    // API to decrypt a given ciphertext using AES-CBC and manage semaphores.
    public async Task<string> DecryptAndManageSemaphoreAsync(string ciphertext, byte[] key, byte[] iv, string semaphoreUrl)
    {
        try
        {
            // Step 1: Decrypt the ciphertext using AES-CBC
            string plaintext = await DecryptAesCbcAsync(ciphertext, key, iv);

            // Step 2: Manage semaphore for resource access
            SemaphoreSlim semaphore = null;
            try
            {
                semaphore = await InitializeSemaphore(semaphoreUrl);

                // Critical section where threads acquire and release the semaphore.
                await semaphore.WaitAsync();

                // Simulate access to shared resource (e.g., database).
                await Task.Delay(100); // Placeholder for actual resource usage.

            }
            finally
            {
                if (semaphore != null)
                    await ReleaseSemaphore(semaphore, semaphoreUrl);
            }

            return plaintext;
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            throw new InvalidOperationException("Decryption or Semaphore management failed.", ex);
        }
    }

    private async Task<string> DecryptAesCbcAsync(string ciphertext, byte[] key, byte[] iv)
    {
        using var aes = Aes.Create();
        aes.Key = key;
        aes.IV = iv;
        aes.Mode = CipherMode.CBC;

        var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

        var cipherBytes = Convert.FromBase64String(ciphertext);

        using var ms = new MemoryStream(cipherBytes);
        using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
        using var sr = new StreamReader(cs);

        return await sr.ReadToEndAsync();
    }

    private async Task<SemaphoreSlim> InitializeSemaphore(string semaphoreUrl)
    {
        // Create and initialize the semaphore based on cloud service's response.
        var response = await httpClient.GetAsync($"{semaphoreUrl}/initialize");

        if (!response.IsSuccessStatusCode)
            throw new Exception("Failed to initialize semaphore.");

        dynamic result = await response.Content.ReadAsAsync<dynamic>();
        int maxConcurrentThreads = result.MaxConcurrentThreads;

        return new SemaphoreSlim(maxConcurrentThreads, maxConcurrentThreads);
    }

    private async Task ReleaseSemaphore(SemaphoreSlim semaphore, string semaphoreUrl)
    {
        await semaphore.ReleaseAsync();
        // Optionally notify the cloud service about release.
        var response = await httpClient.PostAsync($"{semaphoreUrl}/release", null);

        if (!response.IsSuccessStatusCode)
            LogWarning("Failed to release semaphore at the cloud service.");
    }

    private void LogError(string message) => Console.Error.WriteLine($"ERROR: {message}");
    private void LogWarning(string message) => Console.Out.WriteLine($"WARNING: {message}");
}
