#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    RESOURCE_IMAGE,
    RESOURCE_TEXT,
    RESOURCE_AUDIO,
    RESOURCE_TYPE_COUNT // Keep this as the last entry to maintain count
} ResourceType;

typedef struct ResourceItem {
    ResourceType type;
    char *data;
} ResourceItem;

typedef struct ResourceBundle {
    ResourceItem **items;
    int counts[RESOURCE_TYPE_COUNT];
    pthread_mutex_t lock;
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char *filePath) {
    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) return NULL;

    memset(bundle, 0, sizeof(ResourceBundle));
    pthread_mutex_init(&bundle->lock, NULL);

    FILE *file = fopen(filePath, "r");
    if (!file) {
        free(bundle);
        return (ResourceBundle *)-1; // Error code for file open failure
    }

    // Example logic to read and allocate resources from the file
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        ResourceType type = RESOURCE_IMAGE; // Dummy value, replace with actual parsing logic

        ResourceItem *item = malloc(sizeof(ResourceItem));
        if (!item) {
            fclose(file);
            free(bundle);
            return (ResourceBundle *)-2; // Error code for memory allocation failure
        }

        pthread_mutex_lock(&bundle->lock);
        item->type = type;
        item->data = strdup(buffer); // For example purposes, replace with actual data

        int index = bundle->counts[type]++;
        if (!bundle->items) {
            bundle->items = malloc(sizeof(ResourceItem *));
            if (!bundle->items) {
                free(item->data);
                free(item);
                fclose(file);
                free(bundle);
                return (ResourceBundle *)-2; // Error code for memory allocation failure
            }
        } else {
            ResourceItem **newItems = realloc(bundle->items, sizeof(ResourceItem *) * bundle->counts[type]);
            if (!newItems) {
                fclose(file);
                free(bundle);
                return (ResourceBundle *)-2; // Error code for memory allocation failure
            }
            bundle->items = newItems;
        }

        bundle->items[index] = item;
        pthread_mutex_unlock(&bundle->lock);
    }

    fclose(file);

    return bundle;
}

