import threading
from http.server import HTTPServer, BaseHTTPRequestHandler
import logging
import ctypes

# Load the C library
c_lib = ctypes.CDLL('./your_c_library.so')

class RequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        request_data = self.raw_requestline + '\n' + self.headers.as_string() + '\n'
        parsed_request = c_lib.parse_http_request(request_data.encode('utf-8'))

        # Assuming parse_http_request returns a pointer to the HttpRequest structure
        if not parsed_request:
            logging.error("Failed to parse HTTP request")
            return

        method = ctypes.cast(parsed_request.contents.method, ctypes.c_char_p).value.decode()
        path = ctypes.cast(parsed_request.contents.path, ctypes.c_char_p).value.decode()

        # Free resources allocated by C after use
        c_lib.free_http_request(parsed_request)

        logging.info(f"Method: {method}, Path: {path}")

        self.send_response(200)
        self.end_headers()
        self.wfile.write(b'Hello, world!')

def configure_web_server(port, server_name, ssl_cert):
    def run(server_class=HTTPServer, handler_class=RequestHandler):
        logging.info(f'Starting {server_name} on port {port}')
        httpd = server_class(('localhost', port), handler_class)
        try:
            httpd.serve_forever()
        except Exception as e:
            logging.error(f"Error running the server: {e}")
        finally:
            httpd.server_close()

    thread = threading.Thread(target=run)
    thread.daemon = True
    thread.start()

    logging.info(f"{server_name} started on port {port}")

# Example configuration and starting of web server
if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    configure_web_server(8080, 'MyWebServer', '/path/to/cert.pem')
```

