```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define structure for FSA nodes
typedef struct Node {
    int state;
    char *classID;
    struct Node **children;
    int numChildren;
} Node;

// Structure to hold the selector match result
typedef struct MatchResult {
    int state;
    struct MatchResult *next;
} MatchResult;

// Function prototypes for selector matching and logging
int testSelector(const char* classOrID, const char* selector);
void logError(const char* message);

// Recursive function to traverse FSA and find matching states
MatchResult* traverseFSA(Node* node, int numStates, const char* selector, MatchResult* lastState) {
    // Base case: if the node is NULL, return the current last state
    if (node == NULL) {
        return lastState;
    }

    // Check if current node matches the selector using the provided function
    if (testSelector(node->classID, selector)) {
        MatchResult* newState = malloc(sizeof(MatchResult));
        if (!newState) {
            logError("Memory allocation failed");
            return NULL; // Return NULL in case of insufficient memory
        }

        newState->state = node->state;
        newState->next = lastState;
        lastState = newState;
    }

    // Recurse for each child of the current node
    for (int i = 0; i < node->numChildren; ++i) {
        MatchResult* result = traverseFSA(node->children[i], numStates, selector, lastState);
        if (!result) {
            return NULL; // Propagate memory allocation failure upwards
        }
        lastState = result;
    }

    return lastState;
}

// Function to initiate traversal and handle initial setup
MatchResult* findMatchingStates(Node** fsaArray, int numStates, const char* selector) {
    if (!fsaArray || !selector) {
        logError("Invalid input parameters");
        return NULL;
    }

    MatchResult dummyHead = { .next = NULL };
    MatchResult *lastState = &dummyHead;

    // Traverse the FSA tree starting from each root node
    for (int i = 0; i < numStates; ++i) {
        lastState = traverseFSA(fsaArray[i], numStates, selector, lastState);
        if (!lastState) return NULL;
    }

    MatchResult* resultHead = dummyHead.next;
    if (!resultHead) {
        logError("No matching states found");
    }
    return resultHead;
}

// Dummy implementations for the testSelector and logError functions
int testSelector(const char* classOrID, const char* selector) {
    // Assume a simple string comparison for demonstration
    return strcmp(classOrID, selector) == 0;
}

void logError(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}
```

**Explanation:**
- The `Node` structure represents each state in the FSA with pointers to child nodes.
- `MatchResult` is used to store states matching a given selector.
- The `traverseFSA` function recursively checks if each node matches the selector, storing results as it goes.
- Memory allocation failure and invalid input are handled gracefully by logging errors and returning `NULL`.
- The main function `findMatchingStates` sets up traversal across all root nodes of the FSA.

