int handlePostRequest(DatabaseConnectionPool* connectionPool,
                      const std::vector<std::string>& inputParameters, 
                      const std::string& procedureName) {

    Request request{connectionPool, inputParameters, procedureName};

    // Run a command in the background
    runCommandInBackground("echo 'Running background task'");

    return handleHTTPRequest(request);
}

