```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <pthread.h>

// Function to add a cipher or digest based on the provided algorithm name
int add_algorithm(const char *name, int type) {
    if (type == EVP_CIPHER_TYPE) {
        return EVP_add_cipherbyname(name);
    } else if (type == EVP_MD_TYPE) {
        return EVP_add_digestbyname(name);
    }
    return 0;
}

// Error handling function
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    // Additional error logging or cleanup can be added here
}

// Load configuration and initialize cryptographic algorithms
int cryptoLibInit(const char *config_path) {
    FILE *file = fopen(config_path, "r");
    if (!file) {
        handle_error("Unable to open configuration file.");
        return -1;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    const int BUFFER_SIZE = 256;
    char line[BUFFER_SIZE];

    while (fgets(line, sizeof(line), file)) {
        // Remove newline character
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') {
            line[--len] = '\0';
        }

        pthread_mutex_lock(&lock);

        int result;
        if (strncmp(line, "AES", 3) == 0 || strncmp(line, "Camellia", 8) == 0) {
            result = add_algorithm(line, EVP_CIPHER_TYPE);
        } else if (strncmp(line, "MD5", 3) == 0 || 
                   strncmp(line, "SHA-256", 7) == 0 ||
                   strncmp(line, "SHA-512", 7) == 0) {
            result = add_algorithm(line, EVP_MD_TYPE);
        } else if (strncmp(line, "RSA-SHA1", 8) == 0) {
            // RSA operations typically involve both key exchange and signature
            // This is a placeholder for integrating RSA functionality
            handle_error("RSA operations are not directly supported by EVP_add functions.");
            result = -1;
        } else {
            fprintf(stderr, "Unsupported algorithm: %s\n", line);
            result = 0; // Unsupported but non-critical
        }

        pthread_mutex_unlock(&lock);

        if (result != 1) {
            handle_error("Failed to load cryptographic module.");
            fclose(file);
            return -1;
        }
    }

    fclose(file);
    pthread_mutex_destroy(&lock);

    return 0;
}

// Example unit test function for cryptoLibInit
