#define MAX_FILENAME_LENGTH 255

typedef struct {
    char allowed_file_types[10][5];
    int default_digits;
} Config;

// Function prototypes
int validate_filename(const char *filename, size_t max_length);
int get_number_of_digits(const char *filename);
const char* get_file_type(const char *filename, const Config *config);
void modify_extension(char *new_filename, const char *original_filename, int digits, const char *file_type, const char *prefix, const char *suffix);

// Thread-local storage for configuration
__thread Config config;

void load_config_from_file(const char *config_path) {
    // Load configuration from an external file (mock implementation)
    strcpy(config.allowed_file_types[0], "txt");
    strcpy(config.allowed_file_types[1], "gz");
    config.default_digits = 3;
}

int main() {
    load_config_from_file("config.cfg");

    pthread_t threads[10];
    const char *filenames[] = {"file.txt", "archive.tar.gz", "document.docx"};

    for (size_t i = 0; i < sizeof(filenames) / sizeof(filenames[0]); ++i) {
        pthread_create(&threads[i], NULL, (void *(*)(void *))modify_file_name, (void *)filenames[i]);
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(threads[0]); ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

void* modify_file_name(void *arg) {
    const char *filename = (const char *)arg;
    char new_filename[MAX_FILENAME_LENGTH + 1];

    if (!validate_filename(filename, MAX_FILENAME_LENGTH)) {
        fprintf(stderr, "Invalid filename: %s\n", filename);
        return NULL;
    }

    int digits = get_number_of_digits(filename);
    const char *file_type = get_file_type(filename, &config);

    modify_extension(new_filename, (char *)filename, digits, file_type, "_modified_", ".backup");

    printf("Original: %s\nModified: %s\n", filename, new_filename);
    return NULL;
}

int validate_filename(const char *filename, size_t max_length) {
    if (strlen(filename) == 0 || strlen(filename) > max_length) return 0;

    for (const char *p = filename; *p != '\0'; ++p) {
        if (!isalnum(*p) && !strchr(".-_/", *p)) return 0;
    }
    return 1;
}

int get_number_of_digits(const char *filename) {
    int count = 0;
    for (const char *p = filename; *p != '\0'; ++p) {
        if (isdigit(*p)) ++count;
    }
    return count ? count : config.default_digits;
}

const char* get_file_type(const char *filename, const Config *config) {
    size_t len = strlen(filename);
    for (size_t i = 0; i < len; ++i) {
        if (filename[i] == '.') {
            for (int j = 0; j < 10; ++j) {
                if (strncmp(&filename[i + 1], config->allowed_file_types[j], strlen(config->allowed_file_types[j])) == 0) {
                    return &config->allowed_file_types[j][0];
                }
            }
        }
    }
    return "unknown";
}

void modify_extension(char *new_filename, const char *original_filename, int digits, const char *file_type, const char *prefix, const char *suffix) {
    strncpy(new_filename, original_filename, MAX_FILENAME_LENGTH);
    new_filename[MAX_FILENAME_LENGTH] = '\0';

    char extension[16];
    snprintf(extension, sizeof(extension), ".%s%d", file_type, digits);

    // Find the last occurrence of '.'
    char *last_dot = strrchr(new_filename, '.');
    if (last_dot) {
        size_t space_left = MAX_FILENAME_LENGTH - strlen(prefix) - strlen(suffix) - strlen(extension);

        if (space_left < strlen(last_dot + 1)) {
            fprintf(stderr, "New filename exceeds maximum length.\n");
            return;
        }

        strncpy(new_filename + strlen(prefix), last_dot, space_left);
    }

    strcat(new_filename, prefix);
    strcat(new_filename, extension);
    strcat(new_filename, suffix);

    if (strlen(new_filename) > MAX_FILENAME_LENGTH) {
        fprintf(stderr, "New filename exceeds maximum length after modification.\n");
        new_filename[MAX_FILENAME_LENGTH] = '\0';
    }
}
