import java.util.concurrent.*;
import java.util.function.Function;

public class DynamicResourcePoolManager {

    private final ConcurrentHashMap<String, ResourcePool> resourcePools = new ConcurrentHashMap<>();

    public void initializeResourcePool(String poolId, int minConnections, int maxConnections, long connectionTimeoutMillis) {
        validateParameters(minConnections, maxConnections, connectionTimeoutMillis);

        ConnectionConfig config = createConnectionConfig(poolId, minConnections, maxConnections, connectionTimeoutMillis);
        ResourcePool pool = new ResourcePool(config);
        resourcePools.put(poolId, pool);
    }

    public void initializeResourcePoolWithSeed(String poolId, int minConnections, int maxConnections, long connectionTimeoutMillis, long seed) {
        validateParameters(minConnections, maxConnections, connectionTimeoutMillis);

        synchronized (this) {
            ConnectionConfig config = createConnectionConfig(poolId, minConnections, maxConnections, connectionTimeoutMillis);
            if (seed > 0L) {
                config.setSeed(seed);
            }

            ResourcePool pool = new ResourcePool(config);
            resourcePools.put(poolId, pool);
        }
    }

    public void initializeResourcePoolWithCallback(String poolId, int minConnections, int maxConnections, long connectionTimeoutMillis,
                                                   ConnectionConfigCallback callback) {
        validateParameters(minConnections, maxConnections, connectionTimeoutMillis);

        ConnectionConfig config = createConnectionConfig(poolId, minConnections, maxConnections, connectionTimeoutMillis);
        if (callback != null) {
            config = callback.apply(config);
        }

        ResourcePool pool = new ResourcePool(config);
        resourcePools.put(poolId, pool);
    }

    private void validateParameters(int minConnections, int maxConnections, long timeout) {
        if (minConnections < 1 || maxConnections < minConnections || timeout <= 0) {
            throw new IllegalArgumentException("Invalid parameters for resource pool configuration.");
        }
    }

    private ConnectionConfig createConnectionConfig(String poolId, int minConnections, int maxConnections, long timeout) {
        // Basic connection config setup
        return new ConnectionConfig(poolId, minConnections, maxConnections, timeout);
    }

    public interface ConnectionConfigCallback {
        ConnectionConfig apply(ConnectionConfig config);
    }

    public static class ResourcePool implements AutoCloseable {

        private final BlockingQueue<Connection> pool;
        private final long timeoutMillis;

        public ResourcePool(ConnectionConfig config) {
            this.timeoutMillis = config.getTimeoutMillis();
            this.pool = createConnectionPool(config.getMinConnections(), config.getMaxConnections());
        }

        private BlockingQueue<Connection> createConnectionPool(int minSize, int maxSize) {
            LinkedBlockingDeque<Connection> queue = new LinkedBlockingDeque<>(maxSize);

            for (int i = 0; i < minSize; i++) {
                queue.offer(createNewConnection());
            }

            return queue;
        }

        private Connection createNewConnection() {
            // Logic to create a new connection
            return new Connection();
        }

        public Connection getConnection() throws InterruptedException, TimeoutException {
            long deadline = System.currentTimeMillis() + timeoutMillis;
            while (true) {
                if (System.currentTimeMillis() > deadline) {
                    throw new TimeoutException("Connection request timed out.");
                }

                Connection conn = pool.pollFirst(timeoutMillis, TimeUnit.MILLISECONDS);
                if (conn == null || !isHealthy(conn)) {
                    conn = createNewConnection();
                }

                return conn;
            }
        }

        private boolean isHealthy(Connection conn) {
            // Health checking logic
            return new ConnectionHealthChecker() {
                @Override
                public boolean isHealthy(Connection conn) {
                    // Implement actual health check
                    return true; // Assume connection is healthy for example purposes
                }
            }.isHealthy(conn);
        }

        @Override
        public void close() {
            pool.forEach(Connection::close);  // Assuming Connection has a close method to release resources.
            pool.clear();
        }
    }

    public static class ConnectionConfig {

        private String poolId;
        private int minConnections;
        private int maxConnections;
        private long timeoutMillis;
        private Long seed;

        public ConnectionConfig(String poolId, int minConnections, int maxConnections, long timeoutMillis) {
            this.poolId = poolId;
            this.minConnections = minConnections;
            this.maxConnections = maxConnections;
            this.timeoutMillis = timeoutMillis;
        }

        // Getters and Setters
        public String getPoolId() { return poolId; }
        public int getMinConnections() { return minConnections; }
        public int getMaxConnections() { return maxConnections; }
        public long getTimeoutMillis() { return timeoutMillis; }
        public Long getSeed() { return seed; }

        public void setSeed(Long seed) { this.seed = seed; }
    }

    public interface Connection {
        // Define connection related methods
    }

    public interface ConnectionHealthChecker {
        boolean isHealthy(Connection conn);
    }
}
