import sqlite3
import psycopg2
from mysql.connector import connect as mysql_connect
import jsonschema

# Define DatabaseConnector class
class DatabaseConnector:
    def __init__(self, config):
        self.config = config
        self.connection = None
        self.cursor = None
        self.connect()

    def connect(self):
        db_type = self.config['db_type']

        if db_type == 'sqlite':
            self.connection = sqlite3.connect(self.config['connection_string'])
        elif db_type == 'postgresql':
            self.connection = psycopg2.connect(**self.config['connection_dict'])
        elif db_type == 'mysql':
            self.connection = mysql_connect(
                host=self.config['host'],
                user=self.config['user'],
                password=self.config['password'],
                database=self.config['database'],
                connection_timeout=self.config.get('timeout', 5)
            )

        self.cursor = self.connection.cursor()

    def execute_query(self, query, params=()):
        try:
            self.cursor.execute(query, params)
            if query.strip().upper().startswith("SELECT"):
                return self.cursor.fetchall()
            else:
                self.connection.commit()
        except Exception as e:
            self.connection.rollback()
            raise e

    def start_transaction(self):
        self.connection.autocommit = False

    def commit_transaction(self):
        self.connection.commit()

    def rollback_transaction(self):
        self.connection.rollback()

    def close_connection(self):
        if self.cursor:
            self.cursor.close()
        if self.connection:
            self.connection.close()

# Define GraphQL resolvers
def update_user_profile_resolver(user_id, profile_data):
    user_schema = {
        "type": "object",
        "properties": {
            "name": {"type": "string"},
            "email": {"type": "string", "format": "email"}
        },
        "required": ["name", "email"]
    }

    try:
        jsonschema.validate(instance=profile_data, schema=user_schema)

        # Assuming `db_connector` is an instance of DatabaseConnector
        update_query = """
            UPDATE users SET name=%s, email=%s WHERE id=%s
        """
        db_connector.execute_query(update_query, (profile_data['name'], profile_data['email'], user_id))

        # Fetch updated profile data
        select_query = "SELECT * FROM users WHERE id=%s"
        updated_profile = db_connector.execute_query(select_query, (user_id,))
        return {"status": "success", "updated_user": updated_profile[0]}

    except jsonschema.exceptions.ValidationError as e:
        return {"status": "error", "message": str(e)}

def delete_user_profile_resolver(user_id):
    try:
        # Assuming `db_connector` is an instance of DatabaseConnector
        delete_query = "DELETE FROM users WHERE id=%s"
        db_connector.execute_query(delete_query, (user_id,))

        return {"status": "success", "message": f"User {user_id} deleted successfully"}

    except Exception as e:
        return {"status": "error", "message": str(e)}
