#include <forward_list>
#include <memory>
#include <string>
#include <iostream>

class LogEntry {
public:
    std::string level;
    std::string message;

    LogEntry(const std::string& lvl, const std::string& msg)
        : level(lvl), message(msg) {}
};

// Simulated external logging API function
bool sendLogToAPI(const LogEntry& logEntry) {
    // This would normally interact with an actual logging system.
    return true; // Assume success for simulation purposes
}

void insertAndLog(std::forward_list<std::shared_ptr<LogEntry>>& logs, 
                  const std::string& targetLevel, 
                  const std::string& newMessage,
                  int repeatCount = 1) {

    if (logs.empty() || targetLevel.empty() || newMessage.empty()) return;

    auto it = logs.before_begin();
    for (auto curr_it = logs.begin(); curr_it != logs.end(); ++curr_it, ++it) {
        if ((*curr_it)->level == targetLevel) {
            for (int i = 0; i < repeatCount; ++i) {
                try {
                    auto newLogEntry = std::make_shared<LogEntry>(targetLevel, newMessage);
                    logs.insert_after(curr_it, newLogEntry);

                    // Attempt to send the log entry using the external API
                    int attempts = 0;
                    while (attempts < 3 && !sendLogToAPI(*newLogEntry)) {
                        ++attempts; // Retry up to 3 times for transient errors
                    }

                    if (!sendLogToAPI(*newLogEntry)) {
                        throw std::runtime_error("Failed to send log entry after retries.");
                    }

                } catch (const std::exception& e) {
                    std::cerr << "Error: " << e.what() << std::endl;
                }
            }
        }
    }

    if (it == logs.before_begin()) { // Level not found, insert at the end
        try {
            auto newLogEntry = std::make_shared<LogEntry>(targetLevel, newMessage);
            logs.push_back(newLogEntry);

            int attempts = 0;
            while (attempts < 3 && !sendLogToAPI(*newLogEntry)) {
                ++attempts; // Retry up to 3 times for transient errors
            }

            if (!sendLogToAPI(*newLogEntry)) {
                throw std::runtime_error("Failed to send log entry after retries.");
            }

        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << std::endl;
        }
    }
}
