using Dapper; // Assuming use of Dapper ORM for SQL databases

// Define interface for handling different database types
public interface IDatabaseHandler
{
    Task<DataTable> ExecuteQueryAsync(string query, object parameters);
}

// Implementation for SQL Database Handler using Dapper ORM
public class SqlDatabaseHandler : IDatabaseHandler
{
    private readonly IDbConnection _connection;
    private readonly ILogger<SqlDatabaseHandler> _logger;

    public SqlDatabaseHandler(IDbConnection connection, ILogger<SqlDatabaseHandler> logger)
    {
        _connection = connection ?? throw new ArgumentNullException(nameof(connection));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<DataTable> ExecuteQueryAsync(string query, object parameters)
    {
        try
        {
            using (var transaction = await _connection.BeginTransactionAsync())
            {
                var result = await _connection.QueryAsync(query, parameters, transaction);
                transaction.Commit();
                return ConvertToDataTable(result);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error executing SQL query: {Query}", query);
            throw;
        }
    }

    private DataTable ConvertToDataTable(IEnumerable<dynamic> data)
    {
        var dataTable = new DataTable();
        foreach (var row in data)
        {
            if (dataTable.Columns.Count == 0)
            {
                foreach (var property in ((IDictionary<string, object>)row).Keys)
                    dataTable.Columns.Add(property);
            }
            dataTable.Rows.Add(((IDictionary<string, object>)row).Values.ToArray());
        }
        return dataTable;
    }
}

