using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class ResourceFileEncryptionService {
    private readonly byte[] _key;
    private readonly byte[] _nonce; // Typically a 12-byte nonce for AES-GCM

    public ResourceFileEncryptionService(byte[] key, byte[] nonce) {
        if (key.Length != 32 || nonce.Length != 12)
            throw new ArgumentException("Invalid key or nonce size.");
        _key = key;
        _nonce = nonce;
    }

    public void EncryptFile(string inputFilePath, string outputFilePath) {
        using (var aesGcm = new AesGCM(_key)) {
            byte[] plaintext = File.ReadAllBytes(inputFilePath);
            byte[] ciphertext = new byte[plaintext.Length];
            byte[] tag = new byte[AesGcm.TagByteSizes.MaxSize];

            aesGcm.Encrypt(_nonce, plaintext, ciphertext, tag);

            using (var fileStream = new FileStream(outputFilePath, FileMode.Create)) {
                fileStream.Write(ciphertext, 0, ciphertext.Length);
                fileStream.Write(tag, 0, tag.Length);
                fileStream.Write(_nonce, 0, _nonce.Length);
            }
        }
    }

    public void DecryptFile(string inputFilePath, string outputFilePath) {
        using (var aesGcm = new AesGCM(_key)) {
            byte[] combinedData = File.ReadAllBytes(inputFilePath);
            int tagSize = AesGcm.TagByteSizes.MaxSize;
            int nonceSize = 12;

            byte[] ciphertext = new byte[combinedData.Length - tagSize - nonceSize];
            Array.Copy(combinedData, 0, ciphertext, 0, ciphertext.Length);

            byte[] tag = new byte[tagSize];
            Array.Copy(combinedData, ciphertext.Length, tag, 0, tag.Length);

            byte[] nonce = new byte[nonceSize];
            Array.Copy(combinedData, ciphertext.Length + tag.Length, nonce, 0, nonce.Length);

            byte[] plaintext = new byte[ciphertext.Length];
            aesGcm.Decrypt(nonce, ciphertext, tag, plaintext);

            File.WriteAllBytes(outputFilePath, plaintext);
        }
    }

    public static void Main(string[] args) {
        // Example usage
        byte[] key = Convert.FromBase64String("your-base64-encoded-32-byte-key");
        byte[] nonce = new byte[12]; // Use a random 12-byte nonce

        ResourceFileEncryptionService service = new ResourceFileEncryptionService(key, nonce);

        string originalFilePath = "path/to/original/file.txt";
        string encryptedFilePath = "path/to/encrypted/file.enc";

        service.EncryptFile(originalFilePath, encryptedFilePath);

        string decryptedFilePath = "path/to/decrypted/file.txt";

        service.DecryptFile(encryptedFilePath, decryptedFilePath);
    }
}
