```rust
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use std::fs;
use std::thread;
use std::time::{Duration, Instant};
use serde_json::json;
use log::{info, warn, error, debug};

// Simulated logging framework
fn setup_logging() {
    // Setup the logging here (e.g., using env_logger)
}

struct CompilerConfig {
    max_threads: usize,
}

impl Default for CompilerConfig {
    fn default() -> Self {
        Self { max_threads: num_cpus::get() }
    }
}

#[derive(Debug, Clone)]
struct CompilationResult {
    path: PathBuf,
    success: bool,
    error_message: Option<String>,
    duration_ms: u128,
}

fn compile_files(file_paths: Vec<PathBuf>, config: CompilerConfig) -> Result<Vec<CompilationResult>, String> {
    setup_logging();

    let results = Arc::new(Mutex::new(Vec::new()));
    let mut handles = vec![];

    // Caching mechanism (in-memory for simplicity)
    let dependency_cache = Arc::new(Mutex::new(HashMap::new()));

    let start_time = Instant::now();

    for path in file_paths {
        let results = Arc::clone(&results);
        let cache = Arc::clone(&dependency_cache);

        if handles.len() >= config.max_threads {
            for handle in &handles {
                handle.join().unwrap();
            }
            handles.clear();
        }

        let handle = thread::spawn(move || {
            debug!("Starting compilation of {:?}", path);

            let mut result = CompilationResult {
                path: path.clone(),
                success: false,
                error_message: None,
                duration_ms: 0,
            };

            // Simulate dependency fetching with caching
            {
                let cache = cache.lock().unwrap();
                if !cache.contains_key(&path) {
                    debug!("Fetching dependencies for {:?}", path);
                    std::thread::sleep(Duration::from_millis(100)); // Simulate network delay

                    cache.insert(path.clone(), true);  // Cache hit/miss simulation
                }
            }

            let compile_start = Instant::now();
            if fs::metadata(&path).is_ok() {
                // Simulated compilation process
                debug!("Compiling {:?}", path);
                std::thread::sleep(Duration::from_millis(200));  // Simulate CPU work

                result.success = true; // Assume success for simplicity
            } else {
                result.error_message = Some(format!("File not found: {:?}", path));
                error!("{}", result.error_message.as_ref().unwrap());
            }

            result.duration_ms = compile_start.elapsed().as_millis();

            let mut results_lock = results.lock().unwrap();
            results_lock.push(result);
        });

        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    // Collecting and reporting performance metrics
    let duration_ms = start_time.elapsed().as_millis();
    info!("Total compilation time: {} ms", duration_ms);

    let results_lock = results.lock().unwrap();
    for result in &*results_lock {
        if result.success {
            info!("Compiled {:?} successfully in {} ms", result.path, result.duration_ms);
        } else {
            warn!(
                "Failed to compile {:?}: {:?}",
                result.path,
                result.error_message.as_ref().map(String::as_str).unwrap_or("Unknown error")
            );
        }
    }

    let json_results = json!({
        "total_time": duration_ms,
        "results": &*results_lock
    });

    info!("Compilation JSON Report: {}", serde_json::to_string_pretty(&json_results).unwrap());

    Ok(results.lock().unwrap().clone())
}

fn main() {
    // Example file paths to compile
    let files_to_compile = vec![
        PathBuf::from("src/main.rs"),
        PathBuf::from("src/lib.rs"),
        // Add more file paths here...
    ];

    let config = CompilerConfig::default();
    match compile_files(files_to_compile, config) {
        Ok(results) => {
            for result in results {
                println!("{:?}", result);
            }
        },
        Err(e) => eprintln!("Compilation failed with error: {}", e),
    }
}
```

### Explanation:

1. **Parallel Compilation**: The function uses threads to compile files concurrently, managing the number of active threads based on `max_threads` from the configuration.

2. **Resource Management**: Uses an in-memory cache (`HashMap`) for dependencies and limits thread creation to avoid overwhelming system resources.

3. **External Dependencies**: Simulated dependency fetching with caching to minimize redundant fetches.

4. **Error Handling**: Captures errors during compilation, logs them, and continues processing other files.

5. **Performance Metrics**: Measures total compilation time using `std::time`, logging it in JSON format for easy integration with monitoring tools.

6. **Detailed Logging**: Uses a simulated logging setup to capture different log levels (info, debug, error).

7. **System Integration**: Designed to be flexible and adaptable to changes in the build system requirements.

8. **User Interface**: The CLI interface is not explicitly implemented here but can be extended using libraries like `clap` for argument parsing.

9. **Testing and Validation**: While unit tests are not included in this snippet, they should cover various scenarios such as file existence checks, compilation success/failure, and dependency cache behavior.

