using System;

public class HighPerformanceRandomValueGenerator
{
    private readonly double minValue;
    private readonly double maxValue;
    private readonly string distributionType;
    private static readonly Random random = new Random();

    public HighPerformanceRandomValueGenerator(double minValue, double maxValue, string distributionType)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Minimum value must be less than maximum value.");

        this.minValue = minValue;
        this.maxValue = maxValue;

        switch (distributionType.ToLower())
        {
            case "uniform":
            case "normal":
                this.distributionType = distributionType.ToLower();
                break;
            default:
                throw new NotSupportedException($"Distribution type {distributionType} is not supported.");
        }
    }

    public float GenerateRandomFloat()
    {
        return GenerateValueInRange(distributionType);
    }

    public int GenerateRandomInteger()
    {
        return (int)GenerateValueInRange(distributionType);
    }

    public float GenerateRandomFloatWithinQuantile(float lowerQuantile, float upperQuantile)
    {
        double quantileRange = upperQuantile - lowerQuantile;
        if (quantileRange <= 0 || lowerQuantile < 0 || upperQuantile > 1)
            throw new ArgumentOutOfRangeException("Invalid quantile range.");

        double mean = (minValue + maxValue) / 2.0;
        double stdDev = (maxValue - minValue) / 6.0; // Approximation for uniform distribution

        return (float)(mean + random.NextDouble() * quantileRange * stdDev);
    }

    public int GenerateRandomIntegerWithinStandardDeviations(int numStdDevs)
    {
        if (numStdDevs <= 0)
            throw new ArgumentOutOfRangeException("Number of standard deviations must be positive.");

        double mean = (minValue + maxValue) / 2.0;
        double stdDev = (maxValue - minValue) / 6.0; // Approximation for uniform distribution
        return (int)(mean + random.NextDouble() * numStdDevs * stdDev);
    }

    private double GenerateValueInRange(string distribution)
    {
        switch (distribution)
        {
            case "uniform":
                return random.NextDouble() * (maxValue - minValue) + minValue;

            case "normal":
                // Simple approximation of normal distribution using Box-Muller transform
                var u1 = 1.0 - random.NextDouble(); // uniform(0,1] random doubles
                var u2 = 1.0 - random.NextDouble();
                double randStdNormal = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Sin(2.0 * Math.PI * u2); // standard normal random
                double mean = (maxValue + minValue) / 2.0;
                double stdDev = (maxValue - minValue) / 6.0; // Approximation for uniform distribution's equivalent std deviation
                return mean + stdDev * randStdNormal;

            default:
                throw new NotSupportedException($"Distribution type {distribution} is not supported.");
        }
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}], Distribution: {distributionType}";
    }
}
