```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <signal.h>

#define BUFFER_SIZE 1024

typedef struct {
    FILE *file;
    char *buffer;
    size_t bufferSize;
    long currentLine;
} FileProcessor;

void logMessage(const char *level, const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp)-1] = '\0'; // remove newline
    printf("[%s] [%s] %s\n", timestamp, level, message);
}

int isNumber(const char *str) {
    if (*str == '-' || *str == '+') str++;
    while (isdigit(*str) || *str == '.' || *str == 'e' || *str == 'E' || *str == '-') str++;
    return *str == '\0';
}

void processLine(FileProcessor *fp, FILE *outputFile) {
    char *token = strtok(fp->buffer, " ");
    double nums[3] = {0};
    int count = 0;

    while (token != NULL && count < 3) {
        if (isNumber(token)) {
            nums[count++] = atof(token);
        } else {
            logMessage("WARNING", "Non-numeric value encountered.");
        }
        token = strtok(NULL, " ");
    }

    if (count == 3) {
        double average = (nums[0] + nums[1] + nums[2]) / 3.0;
        fprintf(outputFile, "%f\n", average);
    } else {
        logMessage("INFO", "Skipping line with less than three numbers.");
    }
}

void signalHandler(int signum) {
    logMessage("INFO", "Interrupt received, saving progress...");
    // Implement saving state logic here
    exit(0);
}

void processFile(const char *inputFileName, const char *outputFileName) {
    FileProcessor fp;
    FILE *inputFile = fopen(inputFileName, "r");
    if (!inputFile) {
        logMessage("ERROR", "Could not open input file.");
        return;
    }

    FILE *outputFile = fopen(outputFileName, "w");
    if (!outputFile) {
        logMessage("ERROR", "Could not open output file.");
        fclose(inputFile);
        return;
    }

    fp.file = inputFile;
    fp.buffer = malloc(BUFFER_SIZE);
    fp.currentLine = 0;

    signal(SIGINT, signalHandler);

    while (fgets(fp.buffer, BUFFER_SIZE, inputFile) != NULL) {
        fp.currentLine++;
        processLine(&fp, outputFile);
    }

    free(fp.buffer);
    fclose(inputFile);
    fclose(outputFile);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        logMessage("ERROR", "Usage: program <input_file> <output_file>");
        return EXIT_FAILURE;
    }

    processFile(argv[1], argv[2]);
    return EXIT_SUCCESS;
}
```

### Key Points:

- **Memory Management**: The program reads lines into a buffer, dynamically allocated with `malloc`, and processes them line by line to avoid excessive memory usage.

- **Signal Handling**: A simple signal handler is implemented to handle interruptions gracefully.

- **Logging System**: Logs messages with timestamps for different levels (INFO, WARNING, ERROR).

- **Error Handling**: Checks are in place for file operations and non-numeric values.

- **Modular Design**: Functions are used to separate concerns like reading lines, processing data, and logging.

