```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define MAX_THREADS 10
#define RATE_LIMIT_DELAY_BASE 1 // seconds

// Semaphore for synchronizing access to the shared resource
sem_t semaphore;

typedef struct {
    int *data;
    size_t length;
} IntegerArray;

typedef struct {
    pthread_mutex_t mutex;
    int active_connections;
    int max_rate_limit;
} ConnectionPool;

void log_message(const char *message) {
    FILE *log_file = fopen("activity_log.txt", "a");
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %s\n", ctime(&now), message);
        fclose(log_file);
    }
}

int read_integers_from_stdin(IntegerArray *array) {
    size_t capacity = 10;
    array->data = malloc(capacity * sizeof(int));
    if (array->data == NULL) {
        log_message("Memory allocation failed.");
        return -1;
    }

    int value;
    array->length = 0;

    while (scanf("%d", &value) == 1) {
        if (array->length >= capacity) {
            capacity *= 2;
            array->data = realloc(array->data, capacity * sizeof(int));
            if (array->data == NULL) {
                log_message("Memory reallocation failed.");
                return -1;
            }
        }
        array->data[array->length++] = value;
    }

    if (ferror(stdin)) {
        log_message("Error reading from stdin.");
        free(array->data);
        return -1;
    }

    return 0;
}

void* access_shared_resource(void *arg) {
    ConnectionPool *pool = (ConnectionPool *)arg;

    pthread_mutex_lock(&pool->mutex);
    while (pool->active_connections >= pool->max_rate_limit) {
        pthread_mutex_unlock(&pool->mutex);
        sem_wait(&semaphore);
        pthread_mutex_lock(&pool->mutex);
    }
    pool->active_connections++;
    pthread_mutex_unlock(&pool->mutex);

    log_message("Accessing shared resource...");

    // Simulate accessing the external server
    sleep(1); 

    pthread_mutex_lock(&pool->mutex);
    pool->active_connections--;
    if (pool->active_connections < pool->max_rate_limit) {
        sem_post(&semaphore);
    }
    pthread_mutex_unlock(&pool->mutex);

    return NULL;
}

void setup_semaphore(ConnectionPool *pool, int max_connections) {
    sem_init(&semaphore, 0, max_connections - pool->max_rate_limit);
    log_message("Semaphore initialized.");
}

int find_max_in_array(const IntegerArray *array) {
    if (array->length == 0) return INT_MIN;

    int max = array->data[0];
    for (size_t i = 1; i < array->length; ++i) {
        if (array->data[i] > max) {
            max = array->data[i];
        }
    }

    log_message("Finding maximum in the array...");
    return max;
}

void cleanup_resources(ConnectionPool *pool, IntegerArray *array) {
    free(array->data);
    pthread_mutex_destroy(&pool->mutex);
    sem_destroy(&semaphore);
    log_message("Resources cleaned up.");
}

int main() {
    ConnectionPool pool = { .active_connections = 0, .max_rate_limit = 3 };
    pthread_mutex_init(&pool.mutex, NULL);

    setup_semaphore(&pool, MAX_THREADS);

    IntegerArray integer_array;
    if (read_integers_from_stdin(&integer_array) != 0) {
        log_message("Failed to read integers.");
        cleanup_resources(&pool, &integer_array);
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        int delay = RATE_LIMIT_DELAY_BASE * pool.active_connections;

        if (pthread_create(&threads[i], NULL, access_shared_resource, &pool) != 0) {
            log_message("Failed to create thread.");
            continue;
        }

        sleep(delay);
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    int max_value = find_max_in_array(&integer_array);
    printf("The maximum integer in the array is: %d\n", max_value);

    cleanup_resources(&pool, &integer_array);

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Semaphore Management**: Controls concurrent access to the shared resource.
- **Rate Limiting**: Configurable delay based on active connections.
- **Logging System**: Logs all significant actions and errors to a file.
- **Error Handling**: Checks for memory allocation failures, I/O errors, and thread creation issues.

