    SessionManager() : retryDelay(100ms), maxRetries(10) {}

    std::string generateUniqueSessionID() {
        for (int attempts = 0; attempts < maxRetries; ++attempts) {
            std::string sessionID = createSessionID();
            if (distributedDatabase.isSessionIDUnique(sessionID)) {
                distributedDatabase.storeSessionID(sessionID);
                cache.insert(sessionID); // Cache the new ID
                return sessionID;
