typedef struct {
    int numDigits;
    char fileType[10];
} Config;

void retryWithExponentialBackoff(int retries, void (*action)()) {
    for (int i = 0; i < retries; ++i) {
        if (action() == 0) return;
        sleep((1 << i) + rand() % 100 / 100.0);
    }
}

// Simulated cloud storage API call
int storeFileInCloud(const char* fileName) {
    printf("Storing file: %s in cloud...\n", fileName);
    // Simulate failure/success
    return rand() % 2;
}

void renameAndStoreFile(const char* filename, Config config) {
    char newFileName[256];
    snprintf(newFileName, sizeof(newFileName), "%.*s.%d.%s",
             strlen(filename), filename, config.numDigits, config.fileType);

    retryWithExponentialBackoff(5, storeFileInCloud);

    printf("New file name: %s\n", newFileName);
}
