```rust
use std::env;
use std::fs;
use std::os::unix::fs::PermissionsExt;

pub fn setup_environment_dir(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let env_var = "MY_APP_DIR";
    if let Ok(existing_path) = env::var(env_var) {
        println!("Using existing directory path from environment variable.");
        return Ok(());
    }

    let new_dir = format!("/tmp/{}", dir_name);

    if !Path::new(&new_dir).exists() {
        fs::create_dir_all(&new_dir)?;

        // Set permissions
        fs::metadata(&new_dir)?.permissions().set_mode(0o755);
    }

    env::set_var(env_var, &new_dir);
    println!("New directory path set in environment variable: {}", new_dir);

    Ok(())
}
