```python
import os
import hashlib
import threading
import concurrent.futures
import time
from queue import Queue
import requests
from cachetools import LRUCache
from sqlalchemy import create_engine, Column, Integer, String, LargeBinary, func
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker

# Database setup for caching hash values and logging integrity statuses.
DATABASE_URI = 'sqlite:///log_integrity.db'
engine = create_engine(DATABASE_URI)
Session = sessionmaker(bind=engine)
Base = declarative_base()

class LogFile(Base):
    __tablename__ = 'log_files'

    id = Column(Integer, primary_key=True)
    path = Column(String, unique=True, nullable=False)
    hash_value = Column(LargeBinary)

class IntegrityLog(Base):
    __tablename__ = 'integrity_logs'

    id = Column(Integer, primary_key=True)
    path = Column(String, unique=True, nullable=False)
    status = Column(String)
    timestamp = Column(func.now())

Base.metadata.create_all(engine)

# Configuration
LOG_DIR = '/path/to/log_directory'
API_ENDPOINT = 'https://api.monitoring-system.com/report'
EXCLUDE_PATTERNS = ['*.tmp', '*.old']
THREAD_POOL_SIZE = 10
CHECK_INTERVAL = 60

class LogMonitor:
    def __init__(self):
        self.file_cache = LRUCache(maxsize=1000)
        self.session = Session()
        self.queue = Queue()

    def get_files_to_check(self):
        for root, _, files in os.walk(LOG_DIR):
            for file in files:
                if not any(fnmatch.fnmatch(file, pattern) for pattern in EXCLUDE_PATTERNS):
                    full_path = os.path.join(root, file)
                    try:
                        if self.file_exists_in_db(full_path):
                            yield full_path
                    except Exception as e:
                        self.log_error(f"Error checking file {full_path}: {e}")

    def compute_hash(self, filepath):
        sha256 = hashlib.sha256()
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):  # Read in chunks to handle large files
                sha256.update(chunk)
        return sha256.digest()

    def file_exists_in_db(self, path):
        return self.session.query(LogFile).filter_by(path=path).first() is not None

    def check_integrity(self, filepath):
        try:
            if filepath in self.file_cache:
                current_hash = self.file_cache[filepath]
            else:
                current_hash = self.compute_hash(filepath)
                self.file_cache[filepath] = current_hash
                log_entry = LogFile(path=filepath, hash_value=current_hash)
                self.session.add(log_entry)

            existing_record = self.session.query(LogFile).filter_by(path=filepath).first()
            if existing_record and existing_record.hash_value == current_hash:
                return True

            # Report integrity issue to monitoring system
            self.report_to_monitoring_system(filepath, 'Integrity Check Failed')
            return False

        except Exception as e:
            self.log_error(f"Error during integrity check of {filepath}: {e}")
            return False

    def report_to_monitoring_system(self, path, status):
        try:
            payload = {'file': os.path.basename(path), 'status': status}
            response = requests.post(API_ENDPOINT, json=payload)
            if response.status_code != 200:
                self.log_error(f"Failed to report {path} with status: {response.text}")
        except Exception as e:
            self.log_error(f"Error reporting to monitoring system for {path}: {e}")

    def log_error(self, message):
        error_log = IntegrityLog(path='', status=message)
        self.session.add(error_log)
        self.session.commit()

    def process_queue(self):
        with concurrent.futures.ThreadPoolExecutor(max_workers=THREAD_POOL_SIZE) as executor:
            while True:
                filepath = self.queue.get()
                if filepath:
                    future = executor.submit(self.check_integrity, filepath)
                    self.queue.task_done()

                time.sleep(CHECK_INTERVAL)

    def run(self):
        threading.Thread(target=self.process_queue, daemon=True).start()

        while True:
            for file in self.get_files_to_check():
                self.queue.put(file)

            # Commit changes to the database and clear session
            self.session.commit()
            self.session.close()

if __name__ == '__main__':
    monitor = LogMonitor()
    monitor.run()
```

