    private RateLimiter rateLimiter = new RateLimiter();
    private TokenService tokenService = new TokenService();
    private ProductService productService = new ProductService();
    private TransactionManager transactionManager = new TransactionManager();
    private EmailService emailService = new EmailService();

    public void handlePostRequest(HttpServletRequest request, HttpServletResponse response) {
        try {
            if (!rateLimiter.isAllowed(request.getRemoteAddr())) {
                response.setStatus(HttpServletResponse.SC_TOO_MANY_REQUESTS);
                return;
            }

            String userId = request.getParameter("userId");
            String sessionToken = request.getHeader("Session-Token");

            if (!tokenService.validate(userId, sessionToken)) {
                response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
                return;
            }

            ObjectMapper objectMapper = new ObjectMapper();
            ProductCart productCart = objectMapper.readValue(request.getReader(), ProductCart.class);

            SchemaValidator schemaValidator = new SchemaValidator();
            if (!schemaValidator.isValid(productCart)) {
                response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
                return;
            }

            transactionManager.beginTransaction();

            try (Connection connection = Database.getConnection()) {
                productService.updateUserCart(connection, userId, productCart);
                logger.info("Cart updated for user: {}, timestamp: {}", userId, System.currentTimeMillis());
                emailService.sendConfirmationEmail(userId);
            } catch (SQLException e) {
                transactionManager.rollback();
                response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
                logger.error("Transaction failed for user: {}", userId, e);
                return;
            }

            transactionManager.commit();

            response.setStatus(HttpServletResponse.SC_OK);

        } catch (IOException e) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            logger.error("Invalid JSON data", e);
