```cpp
#include <iostream>
#include <memory>
#include <mutex>

struct Point {
    float x, y, z;
};

class OctreeNode {
public:
    bool isLeaf;
    std::vector<Point> points;
    std::array<std::unique_ptr<OctreeNode>, 8> children;

    OctreeNode() : isLeaf(true) {}
};

class Octree {
private:
    OctreeNode* root;
    int sizeLimit;
    std::mutex mtx; // Mutex for thread safety

public:
    Octree(int limit) : sizeLimit(limit), root(nullptr) {}

    ~Octree() {
        clear(root);
    }

    void clear(OctreeNode* node) {
        if (!node) return;
        for (auto& child : node->children) {
            clear(child.get());
        }
    }

    OctreeNode* initialize(int pointCount, float xMin, float yMin, float zMin,
                           float xMax, float yMax, float zMax) {
        std::lock_guard<std::mutex> lock(mtx);

        if (pointCount > sizeLimit || pointCount <= 0) {
            return nullptr;
        }

        root = new OctreeNode();
        if (!root) {
            throw std::runtime_error("Memory allocation failed");
        }

        // Define a recursive function to subdivide and initialize the tree
        auto createNodeRecursively = [&](OctreeNode* node, float xMin, float yMin, float zMin,
                                         float xMax, float yMax, float zMax) -> void {
            if (node->isLeaf && pointCount > 0) {
                // Subdivide the space and allocate children
                float midX = (xMin + xMax) / 2.0f;
                float midY = (yMin + yMax) / 2.0f;
                float midZ = (zMin + zMax) / 2.0f;

                node->isLeaf = false;

                for (int i = 0; i < 8; ++i) {
                    auto childNode = std::make_unique<OctreeNode>();
                    if (!childNode) {
                        throw std::runtime_error("Memory allocation failed");
                    }
                    // Define the bounds for each octant and initialize
                    float newXMin, newXMax, newYMin, newYMax, newZMin, newZMax;
                    // Calculate child bounds based on i value
                    // (Example calculation)
                    if (i & 1) { newXMin = midX; } else { newXMin = xMin; }
                    if (i & 2) { newYMin = midY; } else { newYMin = yMin; }
                    if (i & 4) { newZMin = midZ; } else { newZMin = zMin; }

                    if (!(i & 1)) { newXMax = midX; } else { newXMax = xMax; }
                    if (!(i & 2)) { newYMax = midY; } else { newYMax = yMax; }
                    if (!(i & 4)) { newZMax = midZ; } else { newZMax = zMax; }

                    node->children[i] = std::move(childNode);
                    createNodeRecursively(node->children[i].get(), newXMin, newYMin, newZMin,
                                          newXMax, newYMax, newZMax);
                }
            }
        };

        try {
            createNodeRecursively(root, xMin, yMin, zMin, xMax, yMax, zMax);
        } catch (const std::runtime_error& e) {
            clear(root);
            root = nullptr;
            std::cerr << "Initialization error: " << e.what() << std::endl;
            return nullptr;
        }

        return root;
    }
};

