        var plaintextBytes = DecryptCiphertext(ciphertext, decryptionKey, iv);

        Console.WriteLine($"Decrypted Text: {Encoding.UTF8.GetString(plaintextBytes)}");

        // Start the background service to check for configuration updates
        Task.Run(() => PeriodicConfigurationCheck(apiUrl));
    }

    public static byte[] DecryptCiphertext(byte[] ciphertext, byte[] key, byte[] iv)
    {
        using var aes = Aes.Create();
        aes.Key = key;
        aes.IV = iv;
        aes.Mode = CipherMode.CBC;

        using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        using var ms = new MemoryStream(ciphertext);
        using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
        using var sr = new StreamReader(cs);

        return Encoding.UTF8.GetBytes(sr.ReadToEnd());
    }

    public static async Task<JsonDocument> FetchConfigurationAsync(string apiUrl)
    {
        try
        {
            if (_cache.TryGetValue("ConfigSettings", out string config))
                return JsonDocument.Parse(config);

            using HttpClient client = new HttpClient();
            HttpResponseMessage response = await client.GetAsync(apiUrl);

            response.EnsureSuccessStatusCode();

            string json = await response.Content.ReadAsStringAsync();
            ValidateConfiguration(json);  // Implement validation logic

            _cache.Set("ConfigSettings", json, CacheExpiration);

            return JsonDocument.Parse(json);
        }
        catch (Exception ex)
        {
            LogError(ex, "FetchConfigurationAsync");
            throw;
        }
    }

    private static void ValidateConfiguration(string json)
    {
        var document = JsonDocument.Parse(json);

        if (!document.RootElement.TryGetProperty("tileSize", out var tileSize) ||
            !tileSize.Value.IsPositiveInteger())
            throw new InvalidOperationException("Invalid configuration data.");

        // Additional validation logic for other properties...
    }

    public static bool IsPositiveInteger(JsonElement element)
    {
        return int.TryParse(element.GetRawText(), out int result) && result > 0;
    }

    private static void LogError(Exception ex, string operationType)
    {
        Console.WriteLine($"[{DateTime.UtcNow}] [ERROR] [{operationType}] {ex.Message}");
    }

    public static async Task PeriodicConfigurationCheck(string apiUrl)
    {
        while (true)
        {
            try
            {
                var newConfig = await FetchConfigurationAsync(apiUrl);

                // Logic to check if configuration has changed and update accordingly

                Console.WriteLine("Configuration checked.");
            }
            catch (Exception ex)
            {
                LogError(ex, "PeriodicConfigurationCheck");
            }

            await Task.Delay(TimeSpan.FromMinutes(5));
        }
    }
}
