#### API Interaction with Retry Logic

```java
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;

public class ApiService {
    private static final int MAX_RETRIES = 3;

    public String callApi(String endpointUrl) throws IOException {
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            try {
                URL url = new URL(endpointUrl);
                HttpURLConnection connection = (HttpURLConnection) url.openConnection();
                connection.setRequestMethod("GET");

                int responseCode = connection.getResponseCode();
                if (responseCode == HttpURLConnection.HTTP_OK) {
                    Logger.log(LogLevel.INFO, "API call successful");
                    return connection.getInputStream().toString();
                } else {
                    Logger.log(LogLevel.WARNING, "API call failed with code: " + responseCode);
                }
            } catch (IOException e) {
                Logger.log(LogLevel.ERROR, "Network error on attempt " + (attempt + 1));
            }
        }
        Logger.log(LogLevel.ERROR, "Failed to call API after " + MAX_RETRIES + " attempts");
        throw new IOException("API request failed");
    }
}
