### C++: DynamicOctreeSpatialPartitioner

```cpp
#include <iostream>
#include <memory>
#include <mutex>
#include <vector>
#include <functional>

class OctreeNode {
public:
    struct Bounds {
        float minX, minY, minZ;
        float maxX, maxY, maxZ;
    };

    bool isLeaf = true;
    int dataCapacity;
    std::vector<int> data; // Simplified to store integer IDs for demonstration
    std::unique_ptr<OctreeNode[]> children;

    OctreeNode(const Bounds& bounds, int capacity)
        : dataCapacity(capacity), children(nullptr) {
        if (capacity <= 0) throw std::invalid_argument("Data capacity must be positive.");
    }

    ~OctreeNode() = default;
};

class DynamicOctreeSpatialPartitioner {
public:
    using NodeBounds = OctreeNode::Bounds;

private:
    std::unique_ptr<OctreeNode> root;
    int maxDepth;
    int nodeCapacity;
    std::mutex octreeMutex;  // For thread safety

    void subdivideNode(OctreeNode* node, int depth) {
        if (depth >= maxDepth || node->data.size() <= nodeCapacity)
            return;

        auto newBounds = calculateNewBounds(node);
        node->children.reset(new OctreeNode[maxChildren]);

        for (int i = 0; i < maxChildren; ++i) {
            auto childNode = std::make_unique<OctreeNode>(newBounds[i], nodeCapacity);
            subdivideNode(childNode.get(), depth + 1);
        }

        node->isLeaf = false;
    }

    NodeBounds calculateNewBounds(const OctreeNode* node) {
        // Simplified bounds calculation
        NodeBounds base = node->getBounds();
        std::vector<NodeBounds> newBounds(maxChildren);
        float xMid = (base.minX + base.maxX) / 2.0f;
        float yMid = (base.minY + base.maxY) / 2.0f;
        float zMid = (base.minZ + base.maxZ) / 2.0f;

        newBounds[0] = {base.minX, base.minY, base.minZ, xMid, yMid, zMid};
        // Other bounds omitted for brevity
        return newBounds;
    }

public:
    DynamicOctreeSpatialPartitioner(const NodeBounds& initialBounds, int depth, int capacity)
        : maxDepth(depth), nodeCapacity(capacity) {
        if (depth <= 0 || capacity <= 0) throw std::invalid_argument("Invalid initialization parameters.");

        root = std::make_unique<OctreeNode>(initialBounds, capacity);
    }

    void addDataPoint(int dataId, const NodeBounds& pointBounds) {
        std::lock_guard<std::mutex> lock(octreeMutex);
        if (!root) throw std::runtime_error("Octree is not initialized.");

        // Simplified adding logic
        root->data.push_back(dataId);
        if (root->isLeaf && root->data.size() > nodeCapacity) {
            subdivideNode(root.get(), 0);
        }
    }

    const OctreeNode* query(const NodeBounds& bounds) const {
        std::lock_guard<std::mutex> lock(octreeMutex);
        // Simplified querying logic
        return root.get();
    }
};

