### JavaScript: FindElementsBySelector

```javascript
function findElementsBySelector(startNode, selector, callback) {
    if (!startNode || typeof selector !== 'string' || typeof callback !== 'function') {
        throw new Error('Invalid input parameters');
    }

    const result = [];

    function traverse(node) {
        if (!node) return;

        // Check current node against the callback
        if (callback(node)) {
            result.push(node);
        }

        // If the node has children, continue traversing
        for (let child = node.firstElementChild; child; child = child.nextElementSibling) {
            traverse(child);
        }

        // Traverse sibling nodes as well
        if (!node.parentNode.done && node.nextSibling) {
            traverse(node.nextSibling);
        }

        node.parentNode.done = true;
    }

    traverse(startNode);

    return result;
}

// Example callback function
function isMatchingElement(element) {
    const idMatch = element.id === 'desired-id';
    const classMatch = element.classList.contains('desired-class');
    return idMatch || classMatch;
}
```

