```c
#include <stdio.h>
#include <stdlib.h>

// Define the structure for adjacency list representation of graph
typedef struct Node {
    int vertex;
    struct Node* next;
} Node;

// Function to add an edge to the graph (undirected)
void addEdge(Node** adjList, int src, int dest) {
    // Add edge from src to dest
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->vertex = dest;
    newNode->next = adjList[src];
    adjList[src] = newNode;

    // Since the graph is undirected, add an edge from dest to src also
    newNode = (Node*)malloc(sizeof(Node));
    newNode->vertex = src;
    newNode->next = adjList[dest];
    adjList[dest] = newNode;
}

// Function to perform BFS and find all reachable nodes within max hops
Node* bfsReachableNodes(Node** adjList, int totalNodes, int startNode, int maxHops) {
    if (startNode < 0 || startNode >= totalNodes) return NULL;

    // Initialize visited array and queue for BFS
    int* visited = (int*)calloc(totalNodes, sizeof(int));
    Node* queue[totalNodes];
    int front = 0, rear = 0;

    // Enqueue the starting node and mark it as visited
    queue[rear++] = (Node*)malloc(sizeof(Node));
    queue[front]->vertex = startNode;
    queue[front]->next = NULL;
    visited[startNode] = 1;

    // To store all reachable nodes within max hops
    Node* resultHead = NULL, *resultTail = NULL;

    while (front < rear && maxHops > 0) {
        Node* current = queue[front++];
        int vertex = current->vertex;
        free(current);  // Free the dequeued node

        // Add current node to reachable nodes list
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) { // Handle memory allocation failure
            while (front > 0) free(queue[--rear]);
            if (visited[startNode]) free(visited);
            return NULL;
        }

        newNode->vertex = vertex;
        newNode->next = NULL;

        if (!resultHead) {
            resultHead = newNode;
            resultTail = newNode;
        } else {
            resultTail->next = newNode;
            resultTail = newNode;
        }

        // Explore neighbors
        Node* neighbor = adjList[vertex];
        while (neighbor) {
            if (!visited[neighbor->vertex]) {
                visited[neighbor->vertex] = 1;

                Node* queueNode = (Node*)malloc(sizeof(Node));
                if (!queueNode) { // Handle memory allocation failure
                    while (front > 0) free(queue[--rear]);
                    if (visited[startNode]) free(visited);
                    return NULL;
                }

                queueNode->vertex = neighbor->vertex;
                queueNode->next = NULL;
                queue[rear++] = queueNode;
            } else {
                // Detect cycle: node already visited
                printf("Cycle detected involving node %d\n", neighbor->vertex);
            }

            neighbor = neighbor->next;
        }
        maxHops--;
    }

    free(visited);  // Free the visited array

    if (front == rear && maxHops > 0) {
        // No more nodes to visit but still hops available
        printf("All reachable nodes within %d hops found.\n", maxHops);
    } else if (maxHops == 0) {
        printf("Max hops limit reached.\n");
    }

    return resultHead;
}

// Example Usage
int main() {
    int totalNodes = 5;
    Node* adjList[totalNodes];

    // Initialize adjacency list
    for (int i = 0; i < totalNodes; ++i) {
        adjList[i] = NULL;
    }

    // Add edges to the graph
    addEdge(adjList, 0, 1);
    addEdge(adjList, 0, 2);
    addEdge(adjList, 1, 3);
    addEdge(adjList, 1, 4);

    int startNode = 0;
    int maxHops = 2;

    // Get all nodes reachable within max hops from start node
    Node* reachableNodes = bfsReachableNodes(adjList, totalNodes, startNode, maxHops);

    if (reachableNodes) {
        printf("Reachable Nodes: ");
        for (Node* temp = reachableNodes; temp != NULL; temp = temp->next) {
            printf("%d ", temp->vertex);
        }
        printf("\n");

        // Free the result list
        while (reachableNodes != NULL) {
            Node* next = reachableNodes->next;
            free(reachableNodes);
            reachableNodes = next;
        }
    } else {
        printf("Memory allocation failed or invalid input.\n");
    }

    return 0;
}
