import java.nio.channels.CompletionHandler;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.Random;

public class GameClient {
    private static final int SERVER_PORT = 8080;
    private static final String SERVER_ADDRESS = "game.server.address";

    private ConcurrentHashMap<String, Long> cooldownMap = new ConcurrentHashMap<>();
    private ExecutorService executorService = Executors.newCachedThreadPool();
    private AttackStrategy attackStrategy = new RandomAttackSelection();

    public void connectToServer() throws IOException {
        AsynchronousSocketChannel channel = AsynchronousSocketChannel.open().get();
        InetSocketAddress address = new InetSocketAddress(SERVER_ADDRESS, SERVER_PORT);

        channel.connect(address).whenComplete((result, exc) -> {
            if (exc == null) {
                System.out.println("Connected to server");
            } else {
                System.err.println("Connection failed: " + exc.getMessage());
            }
        });

        ByteBuffer buffer = ByteBuffer.allocate(1024);

        channel.read(buffer, null, new CompletionHandler<Integer, Void>() {
            @Override
            public void completed(Integer result, Void attachment) {
                // Handle server messages here
                // Read more data if necessary and call channel.read again
            }

            @Override
            public void failed(Throwable exc, Void attachment) {
                System.err.println("Read failed: " + exc.getMessage());
            }
        });
    }

    public void selectAndExecuteAttack(String characterId) {
        long currentTime = System.currentTimeMillis();

        cooldownMap.compute(characterId, (id, lastTime) -> {
            if (lastTime == null || currentTime - lastTime >= 1000) { // Cooldown period of 1 second
                int attackNumber = attackStrategy.selectAttack();
                executeAttack(characterId, attackNumber);
                return currentTime;
            }
            return lastTime;
        });
    }

    private void executeAttack(String characterId, int attackNumber) {
        System.out.println("Character " + characterId + " is executing attack number: " + attackNumber);

        logAttack(characterId, attackNumber);
    }

    private void logAttack(String characterId, int attackNumber) {
        String logMessage = String.format("{\"character_id\": \"%s\", \"attack_number\": %d, \"timestamp\": %d}",
                characterId, attackNumber, System.currentTimeMillis());

        executorService.submit(() -> {
            try (AsynchronousSocketChannel channel = AsynchronousSocketChannel.open().get()) {
                ByteBuffer buffer = ByteBuffer.wrap(logMessage.getBytes());

                InetSocketAddress serverAddress = new InetSocketAddress(SERVER_ADDRESS, SERVER_PORT);
                channel.connect(serverAddress).whenComplete((result, exc) -> {
                    if (exc == null) {
                        channel.write(buffer).whenComplete((writeResult, writeException) -> {
                            if (writeException != null) {
                                System.err.println("Write failed: " + writeException.getMessage());
                            }
                        });
                    } else {
                        System.err.println("Log connection failed: " + exc.getMessage());
                    }
                });
            } catch (IOException e) {
                System.err.println("Logging failed: " + e.getMessage());
            }
        });
    }

    public interface AttackStrategy {
        int selectAttack();
    }

    private static class RandomAttackSelection implements AttackStrategy {
        private final Random random = new Random();

        @Override
        public int selectAttack() {
            return 1 + random.nextInt(2); // Randomly select between 1 and 2
        }
    }

    public static void parseTiffImage(String filePath) throws IOException {
        try (BufferedInputStream bis = new BufferedInputStream(new FileInputStream(filePath))) {
            TIFFReader tiffReader = new TIFFReader();
            TiffDirectory dir = tiffReader.read(bis);

            int bitsPerSample = dir.getInt(258, 1); // Sample tag
            if (!isValidBits(bitsPerSample)) {
                System.err.println("Unsupported bits per sample: " + bitsPerSample);
                return;
            }

            int samplesPerPixel = dir.getShort(277, 1); // Samples per pixel tag

            long extraSamples = calculateExtraSamples(dir);

            System.out.printf("Bits per Sample: %d\n", bitsPerSample);
            System.out.printf("Samples Per Pixel: %d\n", samplesPerPixel);
            if (extraSamples > 0) {
                System.out.printf("Extra Samples: %d\n", extraSamples);
            }
        }
    }

