import hashlib
from typing import Any, Dict, Callable, List
import logging

# Setup logging
logging.basicConfig(level=logging.DEBUG)

class JSONParser:
    _registry = {}

    def __init__(self, data: Dict[str, Any] = None):
        self.data = data or {}

    @classmethod
    def from_json(cls, json_str: str) -> 'JSONParser':
        try:
            data = json.loads(json_str)
            return cls(data)
        except json.JSONDecodeError as e:
            logging.error(f"Failed to decode JSON: {e}")
            raise

    def to_json(self) -> str:
        return json.dumps(self.data)

    @classmethod
    def register_factory(cls, id_: str, factory_func: Callable[..., 'JSONParser']) -> None:
        cls._registry[id_] = factory_func

    @classmethod
    def create_instance(cls, id_: str, *args, **kwargs) -> 'JSONParser':
        if id_ not in cls._registry:
            logging.error(f"No registered factory function for ID: {id_}")
            raise ValueError(f"ID '{id_}' is not registered.")

        return cls._registry[id_](*args, **kwargs)

    async def load_and_execute_json_files(self, urls: List[str]) -> None:
        try:
            tasks = [self.load_file(url) for url in urls]
            responses = await asyncio.gather(*tasks)
            for response in responses:
                if isinstance(response, Exception):
                    logging.error(f"Error loading file: {response}")
                else:
                    self.execute_json_data(response)
        except Exception as e:
            logging.error(f"Failed to load JSON files: {e}")

    async def load_file(self, url: str) -> Any:
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(url) as response:
                    if response.status == 200:
                        return await response.json()
                    else:
                        logging.error(f"Failed to fetch {url}: HTTP status {response.status}")
                        return Exception(f"HTTP error: {response.status}")
        except aiohttp.ClientError as e:
            logging.error(f"Network error fetching {url}: {e}")
            return e

    def execute_json_data(self, data: Any) -> None:
        try:
            json_parser = self.from_json(json.dumps(data))
            # Process the JSON object (execute logic specific to your application)
            logging.info(f"Successfully executed JSON data: {json_parser.data}")
        except Exception as e:
            logging.error(f"Error executing JSON data: {e}")

    def deserialize_and_hash(self, byte_data: bytes, password: str) -> str:
        try:
            obj = json.loads(byte_data.decode('utf-8'))
            random_string = self.generate_random_string(obj)
            hashed_password = hashlib.sha256(password.encode()).hexdigest()
            logging.info(f"Hashed Password: {hashed_password}, Random String: {random_string}")
            return f"{hashed_password}:{random_string}"
        except Exception as e:
            logging.error(f"Deserialization or hashing failed: {e}")
            raise

    def generate_random_string(self, obj: Any) -> str:
        # Implement the logic to convert object data into a random string
        # This is a placeholder for your own implementation
        return ''.join(str(obj))

    def insert_into_forward_list(
        self,
        forward_list: List[str],
        target_str: str,
        new_str: str,
        position_index: int = None,
        multiple_inserts: Dict[int, int] = {}
    ) -> List[str]:
        try:
            if position_index is not None and 0 <= position_index < len(forward_list):
                index = forward_list.index(target_str, position_index)
                if index != -1:
                    forward_list.insert(index + 1, new_str)

            for pos, count in multiple_inserts.items():
                for _ in range(count):
                    if 0 <= pos < len(forward_list) and target_str in forward_list[pos:]:
                        index = forward_list.index(target_str, pos)
                        if index != -1:
                            forward_list.insert(index + 1, new_str)

            # Insert at the end if not found
            if target_str not in forward_list:
                forward_list.append(new_str)

            logging.info(f"Updated forward list: {forward_list}")
            return forward_list

        except Exception as e:
            logging.error(f"Error inserting into forward list: {e}")
            raise

# Example of a factory function for a subclass
def example_subclass_factory(data):
    # Assume some specific logic to create a subclass instance from JSON data
    return JSONParser(data)

# Register the factory function
JSONParser.register_factory("example", example_subclass_factory)
