function rateLimitTokenGeneration($maxAttempts = 5, $cooldownPeriod = 60) {
    if (!isset($_SESSION['token_attempts'])) {
        $_SESSION['token_attempts'] = ['count' => 0, 'last_attempt_time' => time()];
    }

    $currentTime = time();
    if ($_SESSION['token_attempts']['count'] >= $maxAttempts && ($currentTime - $_SESSION['token_attempts']['last_attempt_time']) < $cooldownPeriod) {
        throw new Exception("Rate limit exceeded. Please try again later.");
    }

    if (($currentTime - $_SESSION['token_attempts']['last_attempt_time']) > $cooldownPeriod) {
        $_SESSION['token_attempts'] = ['count' => 0, 'last_attempt_time' => time()];
    }

    $_SESSION['token_attempts']['count']++;
}

// Usage
