const fs = require('fs');
const path = require('path');

/**
 * Reads a file synchronously and returns its contents.
 *
 * @param {string} filePath - The full path of the file to read.
 * @returns {Buffer|string|null} The contents of the file as Buffer or string, or null if an error occurred.
 */
function readFileSynchronously(filePath) {
    try {
        const fullPath = path.resolve(__dirname, filePath);

        // Check if file exists and is readable
        if (!fs.existsSync(fullPath)) {
            throw new Error(`File not found: ${filePath}`);
        }

        const stats = fs.statSync(fullPath);

        // Handle different file types (text or binary)
        if (stats.isFile()) {
            return 'utf8' in stats && !stats.isDirectory() ? fs.readFileSync(fullPath, 'utf8') : fs.readFileSync(fullPath);
        }

        throw new Error(`The path is not a file: ${filePath}`);
    } catch (error) {
        console.error(`Error reading file ${filePath}:`, error.message);
        return null;
    }
}

// Usage
const fileContents = readFileSynchronously('example.txt');
if (fileContents !== null) {
    console.log(fileContents);
}
