#include <condition_variable>
#include <chrono>
#include <algorithm>
#include <numeric>

const int MIN_INT = -1000000;
const int MAX_INT = 1000000;

std::mutex mtx;
std::unordered_map<int, int> histogram;
int largest_integer = std::numeric_limits<int>::min();
long long total_sum = 0;
size_t count = 0;
std::atomic<size_t> processed_files(0);

void log(const std::string& message) {
    // Simulated logging function
    std::cout << "[LOG]: " << message << std::endl;
}

bool isValid(int number) {
    return number >= MIN_INT && number <= MAX_INT;
}

void processFile(const std::string& filename, int thread_id) {
    log("Processing file: " + filename);
    std::ifstream infile(filename);

    if (!infile.is_open()) {
        log("Error opening file: " + filename);
        return;
    }

    std::mutex file_mtx;

    while (true) {
        std::unique_lock<std::mutex> lock(file_mtx);
        int number;
        if (!(infile >> number)) break; // End of file

        if (!isValid(number)) continue;

        {
            std::lock_guard<std::mutex> guard(mtx); // Critical section
            largest_integer = std::max(largest_integer, number);
            total_sum += number;
            ++count;
            ++histogram[number];
        }
    }

    infile.close();
    log("Completed processing file: " + filename);

    {
        std::lock_guard<std::mutex> lock(file_mtx);
        processed_files++;
    }
}

void worker_thread(const std::vector<std::string>& filenames, size_t start_idx, size_t end_idx) {
    for (size_t i = start_idx; i < end_idx; ++i) {
        processFile(filenames[i], 0);
    }
}

void printHistogram() {
    for (const auto& [key, value] : histogram) {
        if (value > 0)
            std::cout << key << ": " << std::string(value, '*') << std::endl;
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        log("Usage: program <file1> [<file2> ...]");
        return 1;
    }

    std::vector<std::string> filenames(argv + 1, argv + argc);
    const size_t num_threads = std::thread::hardware_concurrency();
    std::vector<std::thread> threads;

    // Divide work among threads
    size_t files_per_thread = filenames.size() / num_threads;
    for (size_t i = 0; i < num_threads; ++i) {
        size_t start_idx = i * files_per_thread;
        size_t end_idx = (i == num_threads - 1) ? filenames.size() : start_idx + files_per_thread;

        threads.emplace_back(worker_thread, std::cref(filenames), start_idx, end_idx);
    }

    for (auto& thread : threads)
        thread.join();

    log("Processing completed.");

    if (count == 0) {
        log("No valid integers found in the range specified.");
        return 1;
    }

    double average = static_cast<double>(total_sum) / count;

    std::cout << "Largest integer: " << largest_integer << "\n";
    std::cout << "Average of all integers: " << average << "\n";
    printHistogram();

    log("Program finished execution.");
    return 0;
}
