### Documentation

**Concurrency**: The `selectAttack` function uses asynchronous fetching with `std::async` to handle network operations without blocking. A mutex (`cacheMutex`) ensures thread-safe access to the cache, and atomic variables manage state updates like real-time database changes.

**Error Handling**: Network latency is simulated using sleep, while errors during data retrieval are logged and handled gracefully by returning a default message ("No attack available").

**Performance Optimization**: The caching mechanism reduces redundant HTTP requests by storing previously fetched attack details. Real-time updates via WebSockets ensure the cache is refreshed immediately when changes occur.

**Real-Time Updates**: WebSocket integration allows for immediate updating of the attack database, maintaining consistency across all characters.

**Thread Safety and Statelessness**: The function design ensures thread safety through proper locking mechanisms and uses atomic variables to manage shared state. It operates without relying on instance-specific data, making it suitable for multi-threaded applications.

**Distributed Logging System**: While placeholders are used here, actual logging should integrate with a distributed system (e.g., using libraries like `spdlog` or external services) to capture both successful selections and errors efficiently.

This design aims to provide an efficient, scalable solution capable of supporting high-concurrency environments while maintaining responsiveness through caching and real-time updates.

```python
import os
import sys
import argparse
from collections import defaultdict
from datetime import datetime

def parse_arguments():
    parser = argparse.ArgumentParser(description='Process IoT device log files.')
    parser.add_argument('directory', type=str, help='Path to the directory containing log files')
    parser.add_argument('--output', type=str, default=None, help='Output file path')
    parser.add_argument('--exclude', nargs='*', default=[], help='File types to exclude (e.g., .log .txt)')
    return parser.parse_args()

def filter_files(directory, exclude):
    for root, _, files in os.walk(directory):
        for file in files:
            if not any(file.endswith(ext) for ext in exclude):
                yield os.path.join(root, file)

def process_log_file(filepath):
    try:
        with open(filepath, 'r') as file:
            lines = file.readlines()

        num_lines = len(lines)
        num_words = sum(len(line.split()) for line in lines)
        num_chars = sum(len(line) for line in lines)

        # Example extraction of device ID and timestamp from filename
        _, basename = os.path.split(filepath)
        parts = basename.split('_')
        if len(parts) >= 2:
            try:
                timestamp_str = '_'.join(parts[-3:-1])
                timestamp = datetime.strptime(timestamp_str, '%Y%m%d%H%M%S')  # Adjust format as needed
                device_id = parts[0]
            except ValueError:
                device_id, timestamp = 'unknown', None

        return (device_id, timestamp), num_lines, num_words, num_chars

    except Exception as e:
        print(f"Error processing {filepath}: {e}", file=sys.stderr)
        return None

def compile_statistics(directory, exclude):
    stats = defaultdict(lambda: {'lines': 0, 'words': 0, 'chars': 0})

    for filepath in filter_files(directory, exclude):
        result = process_log_file(filepath)

        if result:
            (device_id, timestamp), lines, words, chars = result
            key = (device_id, timestamp.strftime('%Y-%m-%d %H:%M:%S') if timestamp else 'unknown')

            stats[key]['lines'] += lines
            stats[key]['words'] += words
            stats[key]['chars'] += chars

    return stats

def generate_report(stats, output):
    report_lines = []

    for key, counts in stats.items():
        report_line = f"Device ID: {key[0]}, Time: {key[1]} - Lines: {counts['lines']}, Words: {counts['words']}, Characters: {counts['chars']}"
        report_lines.append(report_line)

    report_content = "\n".join(report_lines)

    if output:
        with open(output, 'w') as file:
            file.write(report_content)
    else:
        print(report_content)

def main():
    args = parse_arguments()

    try:
        stats = compile_statistics(args.directory, args.exclude)
        generate_report(stats, args.output)

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()
```

This Python program processes a directory of IoT device log files, compiling statistics and categorizing logs by device ID and timestamp. It supports command-line arguments to specify the directory path, output file, and file types to exclude. The solution is modularized for maintainability and includes error handling for invalid paths or inaccessible files.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <sys/time.h>
#include <errno.h>

#define MAX_CACHE_SIZE 100
#define RATE_LIMIT 5 // Max queries per second
#define RETRY_MAX 3

typedef struct {
    char hostname[256];
    u_char ip[16]; // Supports both IPv4 and IPv6
    time_t timestamp;
} DNSCacheEntry;

typedef struct {
    const char *servers[10];
    int timeout; // in milliseconds
    int preferredIPVersion; // 0 for any, 1 for IPv4, 2 for IPv6
} DNSConfig;

static DNSCacheEntry cache[MAX_CACHE_SIZE];
static pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t rateLimitMutex = PTHREAD_MUTEX_INITIALIZER;
static int queryCount = 0;
static time_t lastResetTime = 0;

int resolveHostWithTimeout(const char *hostname, u_char *ipAddress, size_t ipAddressLength, const DNSConfig *config) {
    if (!hostname || !ipAddress || !config) return -1; // Invalid parameters

    pthread_mutex_lock(&rateLimitMutex);
    time_t currentTime = time(NULL);
    if (currentTime > lastResetTime + 1) { // Reset every second
        queryCount = 0;
        lastResetTime = currentTime;
    }
    if (queryCount >= RATE_LIMIT) {
        pthread_mutex_unlock(&rateLimitMutex);
        return -2; // Rate limit exceeded
    }
    queryCount++;
    pthread_mutex_unlock(&rateLimitMutex);

    pthread_mutex_lock(&cacheMutex);
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0 &&
            (currentTime - cache[i].timestamp) < config->timeout / 1000) {
            memcpy(ipAddress, cache[i].ip, ipAddressLength);
            pthread_mutex_unlock(&cacheMutex);
            return 0; // Cache hit
        }
    }
    pthread_mutex_unlock(&cacheMutex);

    struct addrinfo hints = {0}, *res, *rp;
    int retryCount = 0;
    while (retryCount < RETRY_MAX) {
        if (config->preferredIPVersion == 1) {
            hints.ai_family = AF_INET;
        } else if (config->preferredIPVersion == 2) {
            hints.ai_family = AF_INET6;
        }

        struct timeval tv;
        fd_set readfds;
        int rv;

        for (int i = 0; config->servers[i] != NULL; i++) {
            setenv("DNS_SERVER", config->servers[i], 1);

            if ((rv = getaddrinfo(hostname, NULL, &hints, &res)) == 0) break;

            if (rv != EAI_AGAIN && rv != EAGAIN) {
                retryCount++;
                continue;
            }

            int sockfd = socket(res->ai_family, res->ai_socktype | SOCK_NONBLOCK, res->ai_protocol);
            if (sockfd < 0) continue;

            tv.tv_sec = config->timeout / 1000;
            tv.tv_usec = (config->timeout % 1000) * 1000;
            FD_ZERO(&readfds);
            FD_SET(sockfd, &readfds);

            rv = select(sockfd + 1, &readfds, NULL, NULL, &tv);
            close(sockfd);
            if (rv > 0) {
                if ((rv = getaddrinfo(hostname, NULL, &hints, &res)) == 0) break;
            } else {
                retryCount++;
            }
        }

        if (rv == 0) break;

        if (retryCount >= RETRY_MAX) return -3; // Retry limit reached
    }

    if (rv != 0) return -4; // DNS resolution failed

    for (rp = res; rp; rp = rp->ai_next) {
        void *addr;
        socklen_t len = rp->ai_addrlen;

        if (rp->ai_family == AF_INET || rp->ai_family == AF_INET6) {
            addr = &(((struct sockaddr_in*)rp->ai_addr)->sin_addr);
        } else {
            continue; // Unsupported address family
        }

        if (inet_ntop(rp->ai_family, addr, ipAddress, ipAddressLength) != NULL) break;
    }

    freeaddrinfo(res);

    pthread_mutex_lock(&cacheMutex);
    for (int i = 0; i < MAX_CACHE_SIZE; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) { // Update cache
            memcpy(cache[i].ip, ipAddress, ipAddressLength);
            cache[i].timestamp = time(NULL);
            break;
        } else if (cache[i].hostname[0] == '\0') { // Empty slot
            strncpy(cache[i].hostname, hostname, sizeof(cache[i].hostname));
            memcpy(cache[i].ip, ipAddress, ipAddressLength);
            cache[i].timestamp = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&cacheMutex);

    return 0; // Success
}

// Example usage
int main() {
    DNSConfig config = {{"8.8.8.8", "1.1.1.1"}, 5000, 0};
    u_char ipAddress[16];
    int result = resolveHostWithTimeout("example.com", ipAddress, sizeof(ipAddress), &config);
    if (result == 0) {
        printf("Resolved IP: %s\n", inet_ntop(AF_INET, ipAddress, NULL, INET6_ADDRSTRLEN));
    } else {
        printf("DNS resolution failed with error code: %d\n", result);
    }
    return 0;
}
```

