// Function to update cache with real-time updates from WebSockets
void listenForUpdates() {
    asio::ip::tcp::iostream websocketStream("ws://attackdb.example.com/updates");
    if (!websocketStream) {
        throw std::runtime_error("Failed to connect to WebSocket for updates.");
    }

    while (true) { // Continuously listen for updates
        std::string update;
        std::getline(websocketStream, update);

        std::lock_guard<std::mutex> lock(cacheMutex);
        // Simulate parsing and updating cache based on real-time data.
        attackCache["NewAttack"] = {"NewAttack", 7};
    }
}

// Select an attack for the character
std::string selectAttack(const std::string& userText, const std::string& characterType) {
    std::lock_guard<std::mutex> lock(cacheMutex);

    // Extract potential attacks from user text using regex
    std::smatch matches;
    if (std::regex_search(userText, matches, ATTACK_REGEX)) {
        for (const auto& match : matches) {
            if (attackCache.find(match.str()) != attackCache.end()) {
                return match.str();
            }
        }
    }

    // Fetch from cache or database
    std::vector<Attack> attacks = fetchAttacksFromDatabase();

    for (const auto& attack : attacks) {
        if ((cacheMissCheck(attack.name, characterType))) { // Assume this checks cooldowns and availability
            return attack.name;
        }
    }

    throw std::runtime_error("No valid attack selected.");
}

