        std::thread updateListener(listenForUpdates);

        // Simulate concurrent requests
        std::vector<std::future<std::string>> futures;

        for (int i = 0; i < 1000; ++i) {
            futures.push_back(std::async(std::launch::async, selectAttack, "Use Fireball", "Warrior"));
        }

        for (auto& future : futures) {
