use std::env;
use std::fs;
use std::path::{Path, PathBuf};

#[no_mangle]
pub extern "C" fn create_directory_and_set_env(file_name: *const libc::c_char) {
    let c_str = unsafe { CStr::from_ptr(file_name) };
    let file_name_str = match c_str.to_str() {
        Ok(s) => s,
        Err(_) => return,
    };

    if env::var("MY_ENV_VAR").is_ok() {
        println!("Environment variable is already set.");
        return;
    }

    let dir_path = PathBuf::from(file_name_str);
    match fs::create_dir_all(&dir_path) {
        Ok(_) => {
            env::set_var("MY_ENV_VAR", dir_path.to_string_lossy());
        }
        Err(err) => eprintln!("Failed to create directory: {}", err),
    }
}
