class SecureTokenManager {
    private $tokenCharSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';

    /**
     * Generates a secure random string for URL tokens.
     *
     * @param int $length Length of the token to generate.
     * @return string|false The generated token or false on failure.
     */
    public function generateToken($length) {
        if (!is_int($length) || $length <= 0) {
            return false;
        }

        $token = '';
        $maxIndex = strlen($this->tokenCharSet) - 1;

        for ($i = 0; $i < $length; $i++) {
            $randomIndex = random_int(0, $maxIndex);
            $token .= $this->tokenCharSet[$randomIndex];
        }

        return $token;
    }

    /**
     * Hashes and salts a password using the specified algorithm.
     *
     * @param string $password The plain text password to hash.
     * @param string $algorithm The hashing algorithm (e.g., 'bcrypt', 'argon2id').
     * @return string|false The hashed password or false on failure.
     */
    public function hashPassword($password, $algorithm = 'bcrypt') {
        if (!is_string($password) || empty($password)) {
            return false;
        }

        switch ($algorithm) {
            case 'argon2id':
                $options = ['memory_cost' => 1<<17, 'time_cost' => 4, 'threads' => 2];
                return password_hash($password, PASSWORD_ARGON2ID, $options);

            case 'bcrypt':
            default:
                return password_hash($password, PASSWORD_BCRYPT);
        }
    }

    /**
     * Deletes session tokens and hashed passwords securely.
     *
     * @param string &$data Reference to the data containing the token/passwords.
     */
    public function deleteSecureData(&$data) {
