use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use chrono::Utc;
use log::{info, error};
use tokio::sync::Semaphore;
use clap::{App, Arg};

// Simulated external logging service integration
struct LoggingService;

impl LoggingService {
    fn new() -> Self {
        LoggingService {}
    }

    async fn log(&self, message: &str) {
        // Placeholder for actual logging logic
        info!("{}", message);
    }
}

struct DirectoryManager {
    base_path: PathBuf,
    logging_service: Arc<LoggingService>,
    semaphore: Arc<Semaphore>,
}

impl DirectoryManager {
    pub fn new(base_path: impl Into<PathBuf>, max_concurrent_tasks: usize) -> Self {
        let base_path = base_path.into();
        let logging_service = Arc::new(LoggingService::new());
        let semaphore = Arc::new(Semaphore::new(max_concurrent_tasks));

        DirectoryManager {
            base_path,
            logging_service,
            semaphore,
        }
    }

    pub async fn create_directory(&self, name: &str) -> Result<PathBuf, String> {
        let timestamp = Utc::now().format("%Y%m%d%H%M%S").to_string();
        let dir_name = format!("{}_{}", name, timestamp);
        let path = self.base_path.join(dir_name);

        let _permit = self.semaphore.acquire().await.unwrap();

        match fs::create_dir_all(&path) {
            Ok(_) => {
                let log_message = format!("Directory created: {}", path.display());
                self.logging_service.log(&log_message).await;
                info!("{}", log_message);
                Ok(path)
            }
            Err(e) => {
                let error_msg = format!("Failed to create directory {}: {:?}", path.display(), e);
                error!("{}", error_msg);
                self.logging_service.log(&error_msg).await;
                Err(error_msg)
            }
        }
    }

    pub async fn cleanup_directories(&self, age_limit_days: u64) -> Result<(), String> {
        let now = Utc::now();
        for entry in fs::read_dir(&self.base_path).map_err(|e| e.to_string())? {
            let path = entry?.path();

            if path.is_dir() {
                if let Ok(metadata) = fs::metadata(&path) {
                    if let Ok(modified_time) = metadata.modified() {
                        let modified: chrono::DateTime<Utc> = modified_time.into();
                        if now.signed_duration_since(modified).num_days() > age_limit_days as i64 {
                            match fs::remove_dir_all(&path) {
                                Ok(_) => {
                                    let log_message = format!("Directory cleaned up: {}", path.display());
                                    self.logging_service.log(&log_message).await;
                                    info!("{}", log_message);
                                }
                                Err(e) => {
                                    let error_msg = format!("Failed to clean up directory {}: {:?}", path.display(), e);
                                    error!("{}", error_msg);
                                    self.logging_service.log(&error_msg).await;
                                }
                            }
                        }
                    }
                }
            }
        }

        Ok(())
    }
}

#[tokio::main]
async fn main() {
    let matches = App::new("DirectoryManager")
        .version("1.0")
        .author("Your Name <you@example.com>")
        .about("Manages directories with logging and cleanup features")
        .arg(Arg::with_name("base_path").required(true).help("Base directory path"))
        .arg(Arg::with_name("name").required(false).short('n').long("name").takes_value(true).help("Directory name prefix"))
        .arg(Arg::with_name("cleanup").long("cleanup").takes_value(true).help("Cleanup directories older than N days"))
        .get_matches();

    let base_path = matches.value_of("base_path").unwrap();
    let directory_manager = DirectoryManager::new(base_path, 10);

    if let Some(name) = matches.value_of("name") {
        match directory_manager.create_directory(name).await {
            Ok(path) => println!("Directory created at: {}", path.display()),
            Err(e) => eprintln!("Error: {}", e),
        }
    }

    if let Some(cleanup_days) = matches.value_of("cleanup").and_then(|s| s.parse().ok()) {
        match directory_manager.cleanup_directories(cleanup_days).await {
            Ok(_) => println!("Cleanup completed."),
            Err(e) => eprintln!("Error during cleanup: {}", e),
        }
    }
}
```

