<?php

class SessionManager {
    private $dbConnection;
    private const DEFAULT_CHARSET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';

    public function __construct($dbConfig) {
        // Establish a connection to the NoSQL database (e.g., Cassandra)
        try {
            $this->dbConnection = new \Cassandra\Client(['hosts' => [$dbConfig['host']]]);
        } catch (\Exception $e) {
            throw new \RuntimeException("Database connection failed: " . $e->getMessage());
        }
    }

    public function generateToken($length = 64, $charset = self::DEFAULT_CHARSET): string {
        // Validate input
        if (!is_int($length) || $length <= 0) {
            throw new InvalidArgumentException('Length must be a positive integer.');
        }

        if (!is_string($charset) || empty($charset)) {
            throw new InvalidArgumentException('Charset must be a non-empty string.');
        }

        $randomBytes = random_bytes(ceil($length / 2));
        $token = '';

        for ($i = 0; $i < $length; $i++) {
            $index = ord($randomBytes[$i % strlen($randomBytes)]) % strlen($charset);
            $token .= $charset[$index];
        }

        return $token;
    }

    public function validatePassword($password): bool {
        // Implement password validation logic according to constraints
        if (strlen($password) < 8 || !preg_match('/[A-Z]/', $password) ||
            !preg_match('/[a-z]/', $password) || !preg_match('/\d/', $password)) {
            return false;
        }

        return true;
    }

    public function hashPassword($password): string {
        if (!$this->validatePassword($password)) {
            throw new InvalidArgumentException('Invalid password format.');
        }

        // Use a secure hashing algorithm
        return password_hash($password, PASSWORD_BCRYPT);
    }

    public function createSession($userId, $token) {
        try {
            // Ensure atomicity and consistency when storing session data
            $this->dbConnection->executeBatch([
                new \Cassandra\SimpleStatement("INSERT INTO user_sessions (user_id, token) VALUES (?, ?)", [$userId, $token])
            ], [
                'consistency' => \Cassandra::CONSISTENCY_QUORUM
            ]);
        } catch (\Exception $e) {
            throw new RuntimeException('Failed to create session: ' . $e->getMessage());
        }
    }

    public function validateSession($userId, $token): bool {
        try {
            $result = $this->dbConnection->executeQuery(
                "SELECT token FROM user_sessions WHERE user_id = ?",
                [$userId],
                ['consistency' => \Cassandra::CONSISTENCY_QUORUM]
            );

            foreach ($result as $row) {
                if ($row['token'] === $token) {
                    return true;
                }
            }

            return false;
        } catch (\Exception $e) {
            throw new RuntimeException('Failed to validate session: ' . $e->getMessage());
        }
    }
}

// Example of usage
$dbConfig = ['host' => '127.0.0.1'];
$sessionManager = new SessionManager($dbConfig);
$token = $sessionManager->generateToken();
echo "Generated Token: $token";

if ($sessionManager->validatePassword('SecurePass123')) {
    echo "Password is valid.";
} else {
    echo "Invalid password format.";
}

