const fs = require('fs');
const path = require('path');

function readFileContents(directoryPath) {
  let fileContents = '';

  function readDirectory(dir) {
    const files = fs.readdirSync(dir, { withFileTypes: true });

    files.forEach(dirent => {
      const fullPath = path.join(dir, dirent.name);

      if (dirent.isDirectory()) {
        readDirectory(fullPath);
      } else {
        // Efficiently handle large file content
        let chunk;
        const stream = fs.createReadStream(fullPath, { encoding: 'utf-8' });

        stream.on('data', (chunk) => {
          fileContents += chunk;
        });

        stream.on('error', (err) => {
          console.error(`Error reading file ${fullPath}:`, err);
        });

        stream.on('end', () => {
          // File read completed
        });
      }
    });
  }

  try {
    readDirectory(directoryPath);
  } catch (err) {
    console.error(`Error accessing directory ${directoryPath}:`, err);
  }

  return fileContents;
}

// Example of usage
const content = readFileContents('/path/to/directory');
console.log(content);

module.exports = { readFileContents };

