import logging

def generate_widget_html(widgets):
    html_parts = []

    for widget in widgets:
        try:
            widget_type = widget.get('widget_type')
            size = widget.get('size', 'medium')  # Default to medium if not specified
            content = widget.get('content', '')

            if widget_type == 'text':
                html_part = f'<div class="widget text-widget" style="font-size: {size};">{content}</div>'

            elif widget_type == 'image':
                image_src = content  # Assuming the content is the image URL
                html_part = f'<div class="widget image-widget" style="width: {size}; height: auto;"><img src="{image_src}" alt="Image"></div>'

            elif widget_type == 'button':
                button_text = content
                html_part = f'<div class="widget button-widget" style="font-size: {size};"><button>{button_text}</button></div>'

            else:
                logging.warning(f'Invalid widget type encountered: {widget_type}')
                continue  # Skip invalid widgets

            html_parts.append(html_part)

        except Exception as e:
            logging.error(f'Error processing widget: {e}')

    return ''.join(html_parts)

# Example usage
widgets = [
    {'widget_type': 'text', 'size': 'large', 'content': 'Hello, World!'},
    {'widget_type': 'image', 'size': '300px', 'content': 'https://example.com/image.png'},
    {'widget_type': 'button', 'size': 'medium', 'content': 'Click Me'},
]

print(generate_widget_html(widgets))
