from threading import Lock

# Mock external API and audit system
def fetch_delivery_person_info(delivery_person_id):
    # Simulate network call with a delay
    time.sleep(0.1)
    return {"id": delivery_person_id, "name": f"DeliveryPerson {delivery_person_id}"}

def log_to_audit_system(message):
    print(f"Audit Log: {message}")

# Rate limiting setup
rate_limit_lock = Lock()
last_request_time = {}

def rate_limited(max_requests_per_minute):
    def decorator(func):
        min_interval = 60.0 / max_requests_per_minute

        def wrapper(*args, **kwargs):
            nonlocal last_request_time
            with rate_limit_lock:
                current_time = time.time()
                if args[0] in last_request_time:
                    elapsed_time = current_time - last_request_time[args[0]]
                    if elapsed_time < min_interval:
                        time.sleep(min_interval - elapsed_time)
                last_request_time[args[0]] = time.time()
            return func(*args, **kwargs)

        return wrapper

    return decorator

# Order processing function
@rate_limited(10)  # Individual rate limit: 10 requests/minute per source
def batch_process_orders(order_ids, updates):
    successful_updates = []
    updated_count = 0
    cache_expiration_times = {"Preparing": 60, "Delivered": 3600}

    def is_valid_status_update(current_status, new_status):
        valid_transitions = {
            None: ["Preparing"],
            "Preparing": ["On the Way", "Cancelled"],
            "On the Way": ["Delivered"],
            "Delivered": [],
        }
        return new_status in valid_transitions.get(current_status, [])

    def process_order(order_id, update_info):
        try:
            # Simulate fetching order from DB
            current_status = "Preparing"  # Placeholder for fetched status

            if not is_valid_status_update(current_status, update_info['status']):
                raise ValueError(f"Invalid status transition for order {order_id}")

            # External API interaction with retry mechanism
            for _ in range(3):  # Retry up to 3 times
                try:
                    delivery_person_info = fetch_delivery_person_info(update_info['delivery_person_id'])
                    break
                except Exception as e:
                    log_to_audit_system(f"API error for order {order_id}: {e}")
                    time.sleep(1)  # Wait before retrying
            else:
                raise RuntimeError("Failed to fetch delivery person info after retries")

            # Simulate updating the database transactionally
            # Placeholder for actual DB update logic

            cache.set(order_id, {'status': update_info['status'], 'delivery_time': update_info['actual_delivery_time']}, 
                      cache_expiration_times.get(update_info['status'], 300))

            successful_updates.append({
                "order_id": order_id,
                "updated_fields": update_info
            })
            updated_count += 1

        except Exception as e:
            log_to_audit_system(f"Failed to process order {order_id}: {e}")

    # Caching setup with LRU cache for frequent reads
    @lru_cache(maxsize=1024)
    def get_order_from_cache(order_id):
        return cache.get(order_id)

    # Rate limiting for batch processing
    if len(order_ids) > 100:
        raise RuntimeError("Batch size exceeds the limit of 100 orders per 5 minutes")

    # Process each order
    for order_id in order_ids:
        if order_id in updates:
            process_order(order_id, updates[order_id])

    return {
        "message": f"Successfully updated {updated_count} out of {len(order_ids)} orders.",
        "updated_orders": successful_updates,
        "total_updated": updated_count
    }

