namespace MyWebApp.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ElementController : ControllerBase
    {
        private readonly IElementService _elementService;
        private readonly IMessageQueueClient _messageQueueClient;
        private readonly IAuditLogger _auditLogger;

        public ElementController(IElementService elementService, IMessageQueueClient messageQueueClient, IAuditLogger auditLogger)
        {
            _elementService = elementService ?? throw new ArgumentNullException(nameof(elementService));
            _messageQueueClient = messageQueueClient ?? throw new ArgumentNullException(nameof(messageQueueClient));
            _auditLogger = auditLogger ?? throw new ArgumentNullException(nameof(auditLogger));
        }

        [HttpPost]
        public async Task<IActionResult> UpdateElementHtml([FromQuery] string sectionId, [FromQuery] string elementId, 
                                                           [FromBody] HtmlContentUpdateRequest request)
        {
            try
            {
                if (!await _elementService.ValidateIds(sectionId, elementId))
                    return BadRequest("Invalid Section ID or Element ID.");

                if (!request.HtmlContent.IsWellFormed())
                    return BadRequest("HTML content is not well-formed.");

                var versionMatch = await _elementService.CheckVersionMatch(elementId, request.VersionId);

                if (!versionMatch)
                    return Conflict("Version mismatch. Please refresh and try again with the latest version.");

                await RateLimiter.EnforceRateLimit();

                using (await _elementService.LockElementForUpdate(elementId))
                {
                    var previousContent = await _elementService.GetElementHtml(elementId);
                    bool updateSuccess = await _elementService.UpdateElementHtml(elementId, request.HtmlContent.Content);

                    if (!updateSuccess)
                        return StatusCode(500, "Failed to update the element's HTML content.");

                    await _messageQueueClient.PublishPageRefreshMessage(sectionId);

                    await _auditLogger.LogUpdateAttempt(
                        user: User.Identity.Name,
                        elementId: elementId,
                        oldVersion: previousContent.Version,
                        newVersion: request.VersionId,
                        timestamp: DateTime.UtcNow
                    );

                    return Ok("Element HTML updated successfully.");
                }
            }
            catch (NetworkException ex)
            {
                await _auditLogger.LogError(ex, "Network failure during message queue notification or database interaction.");
                return StatusCode(503, "Service temporarily unavailable. Please try again later.");
            }
            catch (Exception ex)
            {
                await _auditLogger.LogError(ex, "Unexpected error occurred while updating element HTML.");
                return StatusCode(500, "An unexpected error occurred. Please contact support.");
            }
        }

        private class HtmlContentUpdateRequest
        {
            public string VersionId { get; set; }
            public HtmlContent Content { get; set; }

