class OctreeNode {
public:
    float x, y, z; // Center of the node
    float size; // Half-size of the node
    bool isLeaf;
    std::vector<OctreeNode*> children;
    std::mutex nodeMutex;

    OctreeNode(float cx, float cy, float cz, float s)
        : x(cx), y(cy), z(cz), size(s), isLeaf(true) {}

    ~OctreeNode() {
        for (auto child : children) delete child;
    }

    bool split();
};

bool OctreeNode::split() {
    if (!isLeaf || children.size()) return false;

    float newSize = size / 2.0f;
    for (int i = 0; i < 8; ++i) {
        int dx = (i & 1) ? newSize : -newSize;
        int dy = ((i >> 1) & 1) ? newSize : -newSize;
        int dz = ((i >> 2) & 1) ? newSize : -newSize;

        children.push_back(new OctreeNode(x + dx, y + dy, z + dz, newSize));
    }

    isLeaf = false;
    return true;
}

class AdvancedOctreeManager {
private:
    std::atomic<OctreeNode*> root;
    std::mutex resourceMutex;
    std::condition_variable cv;

public:
    AdvancedOctreeManager(float size) : root(new OctreeNode(0, 0, 0, size)) {}

