    void PopulateFromDataSource(std::string dataSourceType, std::string dataSourceId);
    void MonitorSystemResources();

private:
    void internalInsert(OctreeNode* node, const float x, const float y, const float z);
};

void AdvancedOctreeManager::insertPoint(const float x, const float y, const float z) {
    std::unique_lock<std::mutex> lock(resourceMutex);

    if (!root) return;

    internalInsert(root.get(), x, y, z);
}

void AdvancedOctreeManager::internalInsert(OctreeNode* node, const float x, const float y, const float z) {
    std::lock_guard<std::mutex> guard(node->nodeMutex);

    // Check if point fits in the current node
    if (x >= node->x - node->size && x <= node->x + node->size &&
        y >= node->y - node->size && y <= node->y + node->size &&
        z >= node->z - node->size && z <= node->z + node->size) {

        if (node->isLeaf && /* some condition for splitting */) {
            if (node->split()) {
                // Reinsert point into appropriate child
                internalInsert(node, x, y, z);
            }
        } else if (!node->isLeaf) {
            for (auto child : node->children) {
                internalInsert(child, x, y, z);
            }
        }
    }
}

