using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
import System.Security.Cryptography;
import System.Text;
using System.Threading.Tasks;
using NLog;

public class StringHasherSettings
{
    public string HashAlgorithm { get; set; } = "MD5";
}

public class StringHasher
{
    private static readonly Logger logger = LogManager.GetCurrentClassLogger();
    private readonly ConcurrentDictionary<string, byte[]> _hashCache = new();

    private readonly StringHasherSettings _settings;

    public StringHasher(StringHasherSettings settings)
    {
        _settings = settings ?? throw new ArgumentNullException(nameof(settings));
    }

    public string ComputeHash(string input)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty", nameof(input));

        if (_hashCache.TryGetValue(input, out var cachedHash))
            return Convert.ToBase64String(cachedHash);

        using var hashAlgorithm = GetHashAlgorithm();
        byte[] computedHash;

        try
        {
            hashAlgorithm.ComputeHash(Encoding.UTF8.GetBytes(input));
            computedHash = hashAlgorithm.Hash;
            _hashCache[input] = computedHash;
            return Convert.ToBase64String(computedHash);
        }
        catch (Exception ex)
        {
            logger.Error(ex, "Error computing hash");
            throw;
        }
    }

    public async Task<IEnumerable<string>> ComputeHashesInParallelAsync(string[] inputs, IProgress<double> progress = null)
    {
        if (inputs == null) throw new ArgumentNullException(nameof(inputs));

        var results = new ConcurrentBag<string>();
        int total = inputs.Length;
        var rangePartitioner = Partitioner.Create(0, total);

        await Task.Run(() =>
        {
            Parallel.ForEach(rangePartitioner, async (range, loopState) =>
            {
                for (int i = range.Item1; i < range.Item2; i++)
                {
                    if (!string.IsNullOrEmpty(inputs[i]))
                        results.Add(await ComputeHashAsync(inputs[i]));

                    progress?.Report((double)i / total);
                }
            });
        });

        return results;
    }

    public bool ValidateHash(string input, string expectedHash)
    {
        var computedHash = ComputeHash(input);
        return computedHash == expectedHash;
    }

    private HashAlgorithm GetHashAlgorithm()
    {
        switch (_settings.HashAlgorithm.ToUpper())
        {
            case "MD5":
                return MD5.Create();
            case "SHA256":
                return SHA256.Create();
            // Add more algorithms as needed
            default:
                throw new NotSupportedException($"The hash algorithm '{_settings.HashAlgorithm}' is not supported.");
        }
    }

    private async Task<string> ComputeHashAsync(string input)
    {
        return await Task.Run(() => ComputeHash(input));
    }
}

