def retry_with_backoff(func, retries=5):
    for attempt in range(retries):
        try:
            return func()
        except Exception as e:
            wait_time = (RETRY_BACKOFF_FACTOR ** attempt) + random.uniform(0, 1)
            logging.warning(f"Retrying due to {e}. Waiting {wait_time:.2f} seconds.")
            time.sleep(wait_time)

def send_to_analytics(data):
