// app.js

const express = require('express');
const axios = require('axios');
const NodeCache = require('node-cache');

const app = express();
const PORT = process.env.PORT || 3000;
const config = require('./config');
const cache = new NodeCache({ stdTTL: config.cacheTimeout });

app.get('/weather/:location', async (req, res) => {
    const { location } = req.params;
    const cachedData = cache.get(location);

    if (cachedData) {
        return res.json(cachedData);
    }

    try {
        const weatherAPIData = await Promise.all([
            fetchWeatherFromOpenWeatherMap(location),
            fetchWeatherFromWeatherAPI(location),
            fetchWeatherFromAccuWeather(location)
        ]);

        const aggregatedReport = aggregateWeatherData(weatherAPIData);

        cache.set(location, aggregatedReport);

        res.json(aggregatedReport);
    } catch (error) {
        console.error('Error fetching weather data:', error.message);
        res.status(500).json({ error: 'Unable to fetch weather information at this time.' });
    }
});

app.listen(PORT, () => {
