```javascript
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');

// Assume a logging service is available
const logService = {
    info: console.log,
    error: console.error
};

async function loadPlugin(pluginName) {
    const pluginPath = path.resolve(__dirname, 'plugins', `${pluginName}.js`);
    try {
        if (fs.existsSync(pluginPath)) {
            const module = await promisify(require)(pluginPath);
            return { name: pluginName, module };
        } else {
            logService.error(`Plugin not found: ${pluginName}`);
            throw new Error(`Missing file for plugin: ${pluginName}`);
        }
    } catch (error) {
        logService.error(`Failed to load plugin: ${pluginName}`, error);
        return null;
    }
}

async function runTest(label, f, plugins) {
    const testResults = await Promise.allSettled(
        plugins.map(async (pluginName) => {
            const startTime = Date.now();
            try {
                const plugin = await loadPlugin(pluginName);

                if (!plugin) return { status: 'rejected', reason: `Plugin ${pluginName} could not be loaded.` };

                logService.info(`Running test for plugin: ${plugin.name}`);
                f(plugin.module);

                const duration = Date.now() - startTime;
                logService.info(`Test completed for plugin: ${plugin.name} in ${duration}ms`);
                return { status: 'fulfilled', value: `Plugin ${plugin.name}: Test passed` };
            } catch (error) {
                logService.error(`Error running test for plugin: ${pluginName}`, error);
                return { status: 'rejected', reason: `Test failed for ${pluginName}. Error: ${error.message}` };
            }
        })
    );

    // Handle results
    testResults.forEach(result => {
        if (result.status === 'fulfilled') {
            logService.info(result.value);
        } else {
            logService.error(`Failed Test - Reason: ${result.reason}`);
        }
    });
}

module.exports = runTest;
```

### Explanation

- **Loading Plugins**: The `loadPlugin` function loads a plugin module dynamically from the specified directory. It checks for file existence and logs errors if loading fails.

- **Running Tests in Parallel**: The `runTest` function uses `Promise.allSettled` to execute tests concurrently, collecting results even if some fail.

- **Logging**: Logs are captured using a mock logging service that logs test execution details like plugin names, durations, and any errors encountered.

- **Error Handling**: Errors during loading or testing are logged with detailed information for troubleshooting. The function gracefully handles failures due to missing files or runtime exceptions within tests.

- **Maintainability**: This structure allows easy addition of new plugins by simply adding them to the `plugins` directory without modifying the core test-running logic.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>

#define MAX_THREADS 4
#define BUFFER_SIZE 1024

typedef struct {
    char **data;
    size_t capacity;
} LineBuffer;

typedef struct {
    char *filepath;
    FILE *file;
    size_t line_num;
    int skip_line;
} FileProcessorArgs;

typedef struct {
    pthread_mutex_t lock;
    size_t total_lines_processed;
    size_t total_files_processed;
} SharedState;

void log_message(const char *level, const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s: %s\n", level, ctime(&now), message);
}

void handle_signal(int sig) {
    log_message("INFO", "Signal received. Exiting gracefully.");
    exit(EXIT_SUCCESS);
}

LineBuffer* allocate_line_buffer(size_t initial_capacity) {
    LineBuffer *buffer = malloc(sizeof(LineBuffer));
    buffer->capacity = initial_capacity;
    buffer->data = malloc(initial_capacity * sizeof(char *));
    return buffer;
}

void free_line_buffer(LineBuffer *buffer) {
    for (size_t i = 0; i < buffer->capacity; ++i) {
        free(buffer->data[i]);
    }
    free(buffer->data);
    free(buffer);
}

int read_line(FILE *file, char **line, size_t *line_len, const char delimiter) {
    if (getline(line, line_len, file) == -1) return 0;
    for (char *p = *line; *p != '\0'; ++p) {
        if (*p == delimiter || *p == '\n') *p = ' ';
    }
    return 1;
}

float* parse_line(const char *line, size_t *num_values, const char delimiter) {
    LineBuffer *buffer = allocate_line_buffer(10);
    buffer->data[0] = strtok(strdup(line), &delimiter);
    for (size_t i = 1; i < buffer->capacity; ++i) {
        buffer->data[i] = strtok(NULL, &delimiter);
        if (!buffer->data[i]) break;
    }
    *num_values = 0;
    while (*num_values < buffer->capacity && buffer->data[*num_values]) ++(*num_values);

    float *values = malloc(*num_values * sizeof(float));
    for (size_t i = 0; i < *num_values; ++i) {
        char *endptr;
        values[i] = strtof(buffer->data[i], &endptr);
        if (*endptr != '\0') {
            log_message("WARNING", "Non-numeric value encountered, skipping line.");
            free(values);
            free_line_buffer(buffer);
            return NULL;
        }
    }

    free_line_buffer(buffer);
    return values;
}

void process_file(FileProcessorArgs *args, SharedState *shared_state) {
    char *line = NULL;
    size_t len = 0;

    while (read_line(args->file, &line, &len, ' ')) {
        pthread_mutex_lock(&shared_state->lock);
        args->line_num++;
        shared_state->total_lines_processed++;
        pthread_mutex_unlock(&shared_state->lock);

        if (!args->skip_line) {
            size_t num_values;
            float *values = parse_line(line, &num_values, ' ');
            if (values && num_values >= 3) {
                float avg = (values[num_values - 1] + values[num_values - 2] + values[num_values - 3]) / 3.0f;
                printf("%zu: %.2f\n", args->line_num, avg);
                free(values);
            }
        }

        free(line);
        line = NULL;

        if (args->skip_line) {
            log_message("INFO", "Skipping incomplete or invalid line.");
            args->skip_line = 0;
        }
    }

    fclose(args->file);
}

void *thread_func(void *arg) {
    FileProcessorArgs *args = (FileProcessorArgs *)arg;
    SharedState *shared_state = (SharedState *)args->next_arg;

    process_file(args, shared_state);

    pthread_mutex_lock(&shared_state->lock);
    shared_state->total_files_processed++;
    pthread_mutex_unlock(&shared_state->lock);

    return NULL;
}

void initialize_shared_state(SharedState *state) {
    pthread_mutex_init(&state->lock, NULL);
    state->total_lines_processed = 0;
    state->total_files_processed = 0;
}

void cleanup_shared_state(SharedState *state) {
    pthread_mutex_destroy(&state->lock);
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <input_dir> <output_dir>\n", argv[0]);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    SharedState shared_state;
    initialize_shared_state(&shared_state);

    DIR *dir = opendir(argv[1]);
    if (!dir) {
        perror("Failed to open directory");
        cleanup_shared_state(&shared_state);
        return EXIT_FAILURE;
    }

    struct dirent *entry;
    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            FileProcessorArgs args;
            args.filepath = entry->d_name;
            char filepath[PATH_MAX];
            snprintf(filepath, sizeof(filepath), "%s/%s", argv[1], entry->d_name);
            args.file = fopen(filepath, "r");
            if (!args.file) {
                perror("Failed to open file");
                continue;
            }
            args.line_num = 0;
            args.skip_line = 0;

            pthread_create(&threads[thread_count++ % MAX_THREADS], NULL, thread_func, &args);
        }
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    closedir(dir);

    log_message("INFO", "Processing completed.");
    cleanup_shared_state(&shared_state);
    return EXIT_SUCCESS;
}
