#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} record;

// Mutex for ensuring thread safety during memory allocation
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int initialize_arrays(long num_elements, long **offsets, int **keys, record ***records) {
    // Ensure thread-safe access to dynamic allocation
    if (pthread_mutex_lock(&lock) != 0) {
        fprintf(stderr, "Failed to acquire mutex\n");
        return -1;
    }

    *offsets = malloc(num_elements * sizeof(long));
    *keys = malloc(num_elements * sizeof(int));
    *records = malloc(num_elements * sizeof(record*));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(*offsets);
        free(*keys);
        free(*records);
        if (pthread_mutex_unlock(&lock) != 0) { // Ensure mutex is unlocked even on failure
            fprintf(stderr, "Failed to release mutex after allocation failure\n");
        }
        return -1;
    }

    for (long i = 0; i < num_elements; ++i) {
        (*records)[i] = malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for record at index %ld\n", i);
            // Free previously allocated memory
            while (i-- > 0) free((*records)[i]);
            free(*offsets);
            free(*keys);
            free(*records);
            if (pthread_mutex_unlock(&lock) != 0) {
                fprintf(stderr, "Failed to release mutex after allocation failure\n");
            }
            return -1;
        }

        (*offsets)[i] = i * 10; // Example initialization
        (*keys)[i] = i + 100;   // Example initialization
        (*records)[i]->offset = (*offsets)[i];
        (*records)[i]->key = (*keys)[i];
    }

    if (pthread_mutex_unlock(&lock) != 0) {
        fprintf(stderr, "Failed to release mutex after successful allocation\n");
        return -1;
    }

    return 0; // Success
}

void free_resources(long *offsets, int *keys, record **records, long num_elements) {
    for (long i = 0; i < num_elements; ++i) {
        if (records[i] != NULL) {
            free(records[i]);
        }
    }

    if (offsets != NULL) {
        free(offsets);
    }

    if (keys != NULL) {
        free(keys);
    }

    if (records != NULL) {
        free(records);
    }
}

// Example usage
int main() {
    long num_elements = 1000;
    long *offsets = NULL;
    int *keys = NULL;
    record **records = NULL;

    if (initialize_arrays(num_elements, &offsets, &keys, &records) != 0) {
        fprintf(stderr, "Failed to initialize arrays\n");
        return -1;
    }

    // Use the allocated arrays and records...

    free_resources(offsets, keys, records, num_elements);

    return 0;
}
