        UserProfileFetcher fetcher = new UserProfileFetcher();
        Map<String, Object> results = fetcher.fetchUserProfiles(userIds, apiClientMock, cacheManagerMock).get();

        Assertions.assertEquals(profileData, results.get("user1"));
