// Function to validate file type based on MIME types and extensions
function isValidFileType(fileUrl, allowedMimeTypes, allowedExtensions) {
    const url = new URL(fileUrl);
    const fileName = url.pathname.split('/').pop();
    const extension = fileName.split('.').pop().toLowerCase();

    // Fetch content-type from server or determine by extension
    return fetch(fileUrl)
        .then(response => {
            const contentType = response.headers.get('Content-Type') || '';
            if (allowedMimeTypes.includes(contentType) && allowedExtensions.includes(extension)) {
                return true;
            }
            console.error(`Unsupported file type: ${contentType} for file ${fileName}`);
            return false;
        });
}

// Function to upload a stream to S3
async function uploadStreamToS3(bucketName, key, stream, metadata = {}, params = {}) {
    const s3Params = {
        Bucket: bucketName,
        Key: key,
        Body: stream,
        ...params,
        Metadata: metadata
    };

    try {
        const result = await s3.upload(s3Params).promise();
        return result.Location;
    } catch (error) {
        console.error(`Upload error for ${key}:`, error);
        throw error;
    }
}

// Function to download file and upload in chunks if necessary
async function downloadAndUploadFile(fileUrl, bucketName, key, metadata = {}, params = {}) {
    const chunkSize = 50 * 1024 * 1024; // 50 MB
    const maxRetries = 5;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
            const response = await fetch(fileUrl);
            if (!response.ok) throw new Error(`Failed to download file: ${response.statusText}`);

            const totalSize = parseInt(response.headers.get('content-length'), 10);
            let downloadedBytes = 0;
            const stream = new PassThrough();

            response.body.pipe(stream, { end: false });

            // Check if we need to handle as a chunked upload
            if (totalSize > chunkSize) {
                for (let offset = 0; offset < totalSize; offset += chunkSize) {
                    const chunkStream = new PassThrough();

                    stream.on('data', (chunk, enc, cb) => {
                        if (offset <= downloadedBytes && downloadedBytes < offset + chunk.length) {
                            chunkStream.write(chunk.slice(downloadedBytes - offset));
                        }
                        downloadedBytes += chunk.length;
                        cb();
                    });

                    stream.on('end', () => chunkStream.end());

                    const partKey = `${key}.part${Math.floor(offset / chunkSize)}`;
                    await uploadStreamToS3(bucketName, partKey, chunkStream);
                }

                // Additional logic to assemble chunks on server-side
            } else {
                await uploadStreamToS3(bucketName, key, stream, metadata, params);
            }

            return `https://${bucketName}.s3.amazonaws.com/${key}`;
        } catch (error) {
            if (attempt < maxRetries) {
                const backoff = Math.pow(2, attempt) * 1000;
                console.log(`Retry ${attempt + 1} for file: ${fileUrl}, retrying in ${backoff / 1000}s`);
                await new Promise(resolve => setTimeout(resolve, backoff));
            } else {
                throw error;
            }
        }
    }
}

// Main upload function
async function uploadFileFromUrl(fileUrl, userId, bucketName, keyPrefix) {
    if (!await isAuthenticated(userId)) {
        return { error: "User not authenticated" };
    }

    const allowedMimeTypes = ['image/jpeg', 'image/png', 'application/pdf']; // Add other types as needed
    const allowedExtensions = ['jpg', 'png', 'pdf'];

    const isValidFile = await isValidFileType(fileUrl, allowedMimeTypes, allowedExtensions);
    if (!isValidFile) {
        return { error: "Unsupported file type" };
    }

    const key = `${keyPrefix}/${new Date().toISOString()}-${fileUrl.split('/').pop()}`;
    const metadata = {
        'Content-Disposition': 'attachment',
        'Cache-Control': 'max-age=31536000'
    };

    try {
        const uploadedFileUrl = await downloadAndUploadFile(fileUrl, bucketName, key, metadata);
        return { url: uploadedFileUrl };
    } catch (error) {
        console.error(`Failed to upload file from URL ${fileUrl}:`, error);
        return { error: "Upload failed after multiple attempts" };
    }
}

// Example usage:
uploadFileFromUrl('https://example.com/image.jpg', 'user123', 'my-s3-bucket', 'uploads')
    .then(result => console.log(result))
    .catch(error => console.error("Error:", error));
