import java.util.Base64;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ContentManager {

    private static final Logger logger = Logger.getLogger(ContentManager.class.getName());
    private static final String AES_ALGORITHM = "AES/CBC/PKCS5Padding";

    // Simulated cache for demonstration purposes
    private static final Cache<String, JsonNode> elementCache = new Cache<>();

    public static String handleIncomingRequest(String pageId, String sectionId, String elementId, 
                                               String encryptedContentJson, byte[] aesKey, byte[] iv) {
        try (ObjectMapper objectMapper = new ObjectMapper()) {
            // Validate and decrypt the JSON content
            JsonNode decryptedContent = decryptJsonContent(encryptedContentJson, aesKey, iv);

            // Update the database with the new content
            boolean success = updateElementInDatabase(pageId, sectionId, elementId, decryptedContent);

            if (success) {
                return "{\"status\":\"success\"}";
            } else {
                return "{\"status\":\"failure\",\"message\":\"Failed to update element.\"}";
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error processing request", e);
            return "{\"status\":\"error\",\"message\":\"" + e.getMessage() + "\"}";
        }
    }

    private static JsonNode decryptJsonContent(String encryptedContentJson, byte[] aesKey, byte[] iv)
            throws Exception {
        SecretKeySpec keySpec = new SecretKeySpec(aesKey, "AES");
        IvParameterSpec ivSpec = new IvParameterSpec(iv);

        Cipher cipher = Cipher.getInstance(AES_ALGORITHM);
        cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);

        byte[] decodedContent = Base64.getDecoder().decode(encryptedContentJson);
        byte[] decryptedBytes = cipher.doFinal(decodedContent);

        ObjectMapper objectMapper = new ObjectMapper();
        return objectMapper.readTree(decryptedBytes);
    }

    private static boolean updateElementInDatabase(String pageId, String sectionId, 
                                                   String elementId, JsonNode updatedContent) {
        try (Connection connection = Database.getConnection()) {
            // Check cache first
            String cacheKey = generateCacheKey(pageId, sectionId, elementId);
            if (elementCache.contains(cacheKey)) {
                return true;  // Assume cached version is still valid
            }

            // SQL update statement
            String sql = "UPDATE elements SET properties = ? WHERE page_id = ? AND section_id = ? AND element_id = ?";

            try (PreparedStatement preparedStatement = connection.prepareStatement(sql)) {
                preparedStatement.setString(1, updatedContent.toString());
                preparedStatement.setString(2, pageId);
                preparedStatement.setString(3, sectionId);
                preparedStatement.setString(4, elementId);

                int rowsAffected = preparedStatement.executeUpdate();

                // Update cache
                if (rowsAffected > 0) {
                    elementCache.put(cacheKey, updatedContent);
                    return true;
                } else {
                    return false;
                }
            }
        } catch (SQLException e) {
            logger.log(Level.WARNING, "Database operation failed", e);
            return false;
        }
    }

    private static String generateCacheKey(String pageId, String sectionId, String elementId) {
        return pageId + "-" + sectionId + "-" + elementId;
    }
}

// Simulated cache class
