import os
import re
import threading
from concurrent.futures import ThreadPoolExecutor
import json
import requests
from typing import Tuple

class FileManager:
    def __init__(self, config_path: str):
        self.config = self.load_config(config_path)

    def load_config(self, path: str) -> dict:
        with open(path, 'r') as file:
            return json.load(file)

    def read_and_sort_file(self, file_path: str) -> list:
        try:
            with open(file_path, 'r') as file:
                lines = file.readlines()
                lines.sort()
                if not lines:
                    raise ValueError("File is empty.")

                last_line = lines[-1]
                sequence_number = self.extract_sequence(last_line)
                return lines, sequence_number
        except Exception as e:
            print(f"Error reading file {file_path}: {e}")
            return [], None

    def extract_sequence(self, line: str) -> int:
        match = re.search(r'\b\d+\b', line)
        if not match:
            raise ValueError("No sequence number found.")
        return int(match.group())

    def modify_filename(self, file_path: str) -> str:
        try:
            base_name, ext = os.path.splitext(file_path)
            new_ext = self.config.get('default_extension', '.new')

            # Handle multiple extensions
            if '.' in ext:
                parts = ext.split('.')
                ext = f".{'.'.join(parts[1:])}"

            # Generate new filename ensuring length <= 255
            prefix = self.config.get('prefix', '')
            suffix = self.config.get('suffix', '')
            digits = self.config.get('default_digits', 3)

            if not os.path.basename(file_path).replace(ext, '').isalnum():
                raise ValueError("Invalid characters in filename.")

            new_filename = f"{base_name}{new_ext.zfill(digits)}{prefix}{suffix}"
            if len(new_filename) > 255:
                raise ValueError("Filename exceeds maximum length of 255 characters.")

            return os.path.join(os.path.dirname(file_path), new_filename)
        except Exception as e:
            print(f"Error modifying filename for {file_path}: {e}")
            return file_path

class ContainerManager:
    def __init__(self, api_url: str):
        self.api_url = api_url
        self.cache = {}

    def fetch_container_metrics(self) -> dict:
        try:
            response = requests.get(f"{self.api_url}/metrics")
            response.raise_for_status()
            return response.json()
        except Exception as e:
            print(f"Error fetching container metrics: {e}")
            return {}

    def manage_containers(self, operation: str, config: dict):
        try:
            # Simulate registry lookup and update
            registry = "containers_registry"
            if not self.is_conflict_free(config):
                raise ValueError("Resource allocation conflict detected.")

            response = requests.post(f"{self.api_url}/manage", json={
                'operation': operation,
                'config': config
            })
            response.raise_for_status()
        except Exception as e:
            print(f"Error managing containers for {operation}: {e}")

    def is_conflict_free(self, config: dict) -> bool:
        # Simplified check; assumes unique port bindings
        ports = config.get('ports', [])
        return all(port not in self.cache for port in ports)

    def start_container(self, config_id: str):
        self.manage_containers('start', self.cache.get(config_id, {}))

    def stop_container(self, config_id: str):
        self.manage_containers('stop', self.cache.get(config_id, {}))

    def restart_container(self, config_id: str):
        self.manage_containers('restart', self.cache.get(config_id, {}))

def main():
    file_manager = FileManager('config.json')
    container_manager = ContainerManager('http://k8s-api.local')

    # Example file operations
    with ThreadPoolExecutor(max_workers=2) as executor:
        future_read_sort = executor.submit(file_manager.read_and_sort_file, 'sample.txt')
        future_modify_filename = executor.submit(file_manager.modify_filename, 'sample.txt')

        lines, sequence_number = future_read_sort.result()
        new_filename = future_modify_filename.result()

    # Example container management operations
    metrics = container_manager.fetch_container_metrics()
    print(f"Container Metrics: {metrics}")

if __name__ == "__main__":
    main()
