from flask import Flask, jsonify, request
from flask_login import LoginManager, UserMixin, login_required
from flask_principal import Principal, Permission, RoleNeed
import json
import asyncio
import aiohttp
import aiomysql
import os
import logging
from PIL import Image
import io

app = Flask(__name__)
login_manager = LoginManager(app)
principal = Principal(app)

# Setup logging
logging.basicConfig(level=logging.INFO)

# User model for Flask-Login
class User(UserMixin):
    def __init__(self, id, roles=[]):
        self.id = id
        self.roles = roles

@login_manager.user_loader
def load_user(user_id):
    # Implement user loading logic here
    return User(user_id)

# Role-based access control setup
admin_permission = Permission(RoleNeed('admin'))

# Registry for factory functions
class_registry = {}

def register_factory(id, factory_func):
    class_registry[id] = factory_func

def create_instance_from_registry(id, *args, **kwargs):
    if id in class_registry:
        return class_registry[id](*args, **kwargs)
    else:
        raise ValueError(f"No registered factory for ID: {id}")

# Base JSON handler class
class JsonHandler:
    def __init__(self, data=None):
        self.data = data or {}

    @classmethod
    async def load_from_file(cls, file_path):
        async with aiohttp.ClientSession() as session:
            async with session.get(file_path) as response:
                if response.status == 200:
                    content = await response.text()
                    return cls(json.loads(content))
                else:
                    logging.error(f"Failed to load JSON from {file_path}")
                    return None

    def to_json_string(self):
        return json.dumps(self.data)

    @classmethod
    def from_json_string(cls, json_str):
        data = json.loads(json_str)
        return cls(data)

# Asynchronous loading of multiple JSON files
async def load_all_files(file_paths):
    tasks = [JsonHandler.load_from_file(path) for path in file_paths]
    results = await asyncio.gather(*tasks, return_exceptions=True)
    for result in results:
        if isinstance(result, Exception):
            logging.error(f"Error loading file: {result}")
    return results

# Database connection and query execution
async def get_employee_details(supervisor_id, db_config):
    try:
        conn = await aiomysql.connect(**db_config)
        async with conn.cursor() as cur:
            query = """
                SELECT employee_name, city, address FROM Employees WHERE supervisor_id = %s
            """
            await cur.execute(query, (supervisor_id,))
            result = await cur.fetchone()
            logging.info(f"Executed Query: {query}")
            return result
    except Exception as e:
        logging.error(f"Database error: {e}")
    finally:
        conn.close()

# Profile picture update and caching
class ProfileDAO:
    def __init__(self, cache_dir):
        self.cache_dir = cache_dir

    def validate_image(self, image_file):
        try:
            img = Image.open(image_file)
            if img.format not in ['JPEG', 'PNG']:
                raise ValueError("Unsupported image format")
            if img.size[0] * img.size[1] > 5_000_000:  # Max size check
                raise ValueError("Image too large")
        except Exception as e:
            logging.error(f"Image validation error: {e}")
            return False
        return True

    def update_profile_picture(self, user_id, image_file):
        if not self.validate_image(image_file):
            return "Invalid image file"

        # Simulate caching and cloud storage integration
        cache_path = os.path.join(self.cache_dir, f"{user_id}_profile.png")
        with open(cache_path, 'wb') as f:
            f.write(image_file.read())

        # Cloud storage upload simulation
        logging.info(f"Uploading {cache_path} to cloud storage for user {user_id}")

        return "Profile picture updated successfully"

# Define a route for updating profile pictures
@app.route('/update_profile_picture', methods=['POST'])
@login_required
@admin_permission.require(http_exception=403)
