public class CustomPasswordValidator : IPasswordValidator<ApplicationUser>
{
    public PasswordOptions PasswordOptions { get; set; }

    public Task<IdentityResult> ValidateAsync(UserManager<ApplicationUser> manager, ApplicationUser user, string password)
    {
        if (password.Length < PasswordOptions.RequiredLength)
            return Task.FromResult(IdentityResult.Failed("Password too short."));

        if (!password.Any(char.IsUpper) || !password.Any(char.IsLower))
            return Task.FromResult(IdentityResult.Failed("Password must have uppercase and lowercase letters."));

        foreach (var forbiddenWord in new[] { "admin", "password" })
        {
            if (password.Contains(forbiddenWord, StringComparison.OrdinalIgnoreCase))
                return Task.FromResult(IdentityResult.Failed($"Password cannot contain the word '{forbiddenWord}'."));
        }

        return Task.FromResult(IdentityResult.Success);
    }
}

