```java
import javax.net.ssl.*;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.security.KeyStore;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Logger;

public class SecureConnectionPool {
    private static final Logger logger = Logger.getLogger(SecureConnectionPool.class.getName());
    private final ExecutorService connectionManager = Executors.newCachedThreadPool();
    private final ConcurrentMap<String, Channel> pool = new ConcurrentHashMap<>();
    private final SSLContext sslContext;
    private final int maxConnections;
    private final long connectionTimeoutMillis;

    public SecureConnectionPool(String keystorePath, String keystorePassword, int maxConnections, long connectionTimeoutMillis) throws Exception {
        this.maxConnections = maxConnections;
        this.connectionTimeoutMillis = connectionTimeoutMillis;

        // Load keystore and initialize SSL context
        KeyStore keyStore = KeyStore.getInstance("JKS");
        try (var inStream = new java.io.FileInputStream(keystorePath)) {
            keyStore.load(inStream, keystorePassword.toCharArray());
        }
        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        tmf.init(keyStore);

        sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, tmf.getTrustManagers(), null);
    }

    public Channel acquireConnection(String host, int port) throws InterruptedException {
        String key = host + ":" + port;

        return pool.computeIfAbsent(key, k -> {
            Future<Channel> future = connectionManager.submit(() -> createSecureChannel(host, port));
            try {
                return future.get(connectionTimeoutMillis, TimeUnit.MILLISECONDS);
            } catch (ExecutionException | TimeoutException e) {
                logger.severe("Connection creation failed: " + e.getMessage());
                future.cancel(true);
                throw new RuntimeException(e.getCause());
            }
        });
    }

    private Channel createSecureChannel(String host, int port) throws IOException {
        AsynchronousSocketChannel rawChannel = AsynchronousSocketChannel.open();
        SocketChannel channel = rawChannel;

        try {
            // Perform SSL handshake
            SSLEngine sslEngine = sslContext.createSSLEngine(host, port);
            sslEngine.setUseClientMode(true);

            // Initiate the SSL connection
            channel.connect(new InetSocketAddress(host, port)).get(connectionTimeoutMillis, TimeUnit.MILLISECONDS);
            performHandshake(channel, sslEngine);

            return channel;
        } catch (IOException | InterruptedException e) {
            logger.severe("SSL handshake failed: " + e.getMessage());
            throw new IOException(e.getMessage(), e);
        }
    }

    private void performHandshake(SocketChannel channel, SSLEngine sslEngine) throws IOException, InterruptedException {
        ByteBuffer appData = ByteBuffer.allocateDirect(sslEngine.getSession().getApplicationBufferSize());
        ByteBuffer netData = ByteBuffer.allocateDirect(sslEngine.getSession().getPacketBufferSize());

        boolean handshakeComplete = false;
        while (!handshakeComplete) {
            switch (sslEngine.getHandshakeStatus()) {
                case NEED_TASK:
                    for (Runnable task : sslEngine.getDelegatedTasks()) {
                        task.run();
                    }
                    break;

                case NEED_WRAP:
                    netData.clear();
                    int writtenBytes = sslEngine.wrap(appData, netData);
                    if (writtenBytes > 0) {
                        channel.write(netData).get(connectionTimeoutMillis, TimeUnit.MILLISECONDS);
                        netData.flip();
                    }
                    break;

                case NEED_UNWRAP:
                    ByteBuffer buffer = ByteBuffer.allocateDirect(sslEngine.getSession().getApplicationBufferSize());
                    int bytesRead = channel.read(buffer).get(connectionTimeoutMillis, TimeUnit.MILLISECONDS);
                    if (bytesRead > 0) {
                        buffer.flip();
                        sslEngine.unwrap(buffer, appData);
                    }
                    break;

                case FINISHED:
                    handshakeComplete = true;
                    break;

                case NOT_HANDSHAKING:
                    throw new IllegalStateException("NOT_HANDSHAKING in the middle of a handshake");
            }
        }

        // Schedule connection cleanup
        Executors.newSingleThreadScheduledExecutor().schedule(() -> {
            try {
                if (channel.isOpen()) {
                    channel.close();
                    pool.remove(channel.toString());
                }
            } catch (IOException e) {
                logger.warning("Failed to close idle connection: " + e.getMessage());
            }
        }, 30, TimeUnit.SECONDS);
    }

    public void shutdown() throws InterruptedException {
        connectionManager.shutdownNow();
        for (Channel channel : pool.values()) {
            try {
                if (!channel.isOpen())
                    continue;
                channel.close().get(connectionTimeoutMillis, TimeUnit.MILLISECONDS);
            } catch (IOException | InterruptedException e) {
                logger.severe("Failed to close pooled connection: " + e.getMessage());
            }
        }
    }

    // Unit tests and stress tests would typically be implemented in a separate test class.
}
```

This Java code provides a skeleton for establishing secure, high-performance connections using NIO channels with SSL/TLS support. It includes connection pooling and graceful handling of errors and resources. For testing the correctness and performance under various conditions, you would implement unit tests in a separate test class using JUnit or another testing framework, focusing on stress testing with multiple threads, handling network failures, and ensuring that connections are reused efficiently within the pool.

