const fs = require('fs');
const { execSync } = require('child_process');
const path = require('path');

// Configuration and Logger Setup
const config = JSON.parse(fs.readFileSync(path.resolve(__dirname, 'config.json'), 'utf-8'));
const logger = (level, message) => {
    if (['info', 'error', 'debug'].includes(level)) {
        console.log(`[${level.toUpperCase()}] ${new Date().toISOString()}: ${message}`);
    }
};

// Module Loader Class
class ModuleLoader {
    constructor(config) {
        this.config = config;
        this.loadedModules = new Set();
        this.dependencyGraph = {};
    }

    loadModule(moduleName) {
        if (this.loadedModules.has(moduleName)) {
            return Promise.resolve(this.dependencyGraph[moduleName]);
        }

        logger('info', `Loading module: ${moduleName}`);

        try {
            const modulePath = path.resolve(__dirname, 'modules', `${moduleName}.js`);
            const module = require(modulePath);

            // Detect circular dependencies
            if (this.detectCycle(moduleName)) {
                throw new Error(`Circular dependency detected with module: ${moduleName}`);
            }

            this.loadedModules.add(moduleName);
            this.dependencyGraph[moduleName] = module;

            return Promise.resolve(module)
                .then(() => logger('info', `Successfully loaded module: ${moduleName}`))
                .catch(error => {
                    logger('error', `Failed to load module: ${moduleName} - Error: ${error.message}`);
                    throw error;
                });
        } catch (error) {
            logger('error', `Module not found or failed to load: ${moduleName} - ${error.message}`);
            return Promise.reject(new Error(`Cannot load module ${moduleName}`));
        }
    }

    detectCycle(moduleName, visited = new Set()) {
        if (visited.has(moduleName)) return true;
        visited.add(moduleName);

        const moduleDependancies = this.dependencyGraph[moduleName];
        if (!moduleDependancies) return false;

        for (const dep of moduleDependancies.dependencies || []) {
            if (this.detectCycle(dep, new Set(visited))) return true;
        }

        return false;
    }
}

// Initialize Module Loader
async function initializeModules() {
    const loader = new ModuleLoader(config);
    for (const moduleName of config.sequence) {
        try {
            await loader.loadModule(moduleName);
        } catch (error) {
            logger('debug', `Error during module loading: ${error.message}`);
        }
    }
}

// Install Dependencies Automatically
function installDependencies() {
    const packageManager = config.packageManager || 'npm';
    execSync(`${packageManager} install`, { stdio: 'inherit' });
    logger('info', `${packageManager} dependencies installed.`);
}

// Entry Point
installDependencies().then(() => initializeModules())
    .catch(error => logger('error', `Initialization failed: ${error.message}`));

