#include <stdio.h>
#include <tiffio.h>

typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamples;
} TIFFInfo;

TIFFInfo* parseTiff(const char *filename) {
    TIFF *tiff = TIFFOpen(filename, "r");
    if (!tiff) return NULL;

    TIFFInfo *info = malloc(sizeof(TIFFInfo));
    if (TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &info->bitsPerSample)) {
        logger("error", "Failed to get bits per sample.");
        free(info);
        TIFFClose(tiff);
        return NULL;
    }

    if (TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &info->samplesPerPixel)) {
        logger("error", "Failed to get samples per pixel.");
        free(info);
        TIFFClose(tiff);
        return NULL;
    }

    // Extra samples handling can be expanded here
    info->extraSamples = 0;

    TIFFClose(tiff);
    return info;
}
