```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class SqlQueryExecutor
{
    private readonly IMemoryCache _cache;
    private readonly ILogger<SqlQueryExecutor> _logger;
    private readonly string _connectionString;
    private readonly int _cacheSize;
    private readonly TimeSpan _cacheExpiration;

    public SqlQueryExecutor(IMemoryCache cache, ILogger<SqlQueryExecutor> logger, string connectionString, int cacheSize = 1000, int cacheExpirationMinutes = 60)
    {
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _connectionString = connectionString ?? throw new ArgumentException("Connection string cannot be null or empty", nameof(connectionString));

        // Read from configuration
        _cacheSize = cacheSize;
        _cacheExpiration = TimeSpan.FromMinutes(cacheExpirationMinutes);

        ConfigureCache();
    }

    private void ConfigureCache()
    {
        var cacheEntryOptions = new MemoryCacheEntryOptions()
            .SetSize(1)
            .SetSlidingExpiration(_cacheExpiration);

        // Set maximum number of items in the cache
        _cache.Set("MaxItems", _cacheSize, cacheEntryOptions);
    }

    public async Task<IEnumerable<T>> ExecuteQueryAsync<T>(string commandTemplate, IDictionary<string, object> parameters) where T : new()
    {
        if (string.IsNullOrEmpty(commandTemplate))
            throw new ArgumentException("Command template cannot be null or empty", nameof(commandTemplate));

        var cacheKey = GenerateCacheKey(commandTemplate, parameters);

        // Check cache first
        if (_cache.TryGetValue(cacheKey, out IEnumerable<T> cachedResult))
        {
            return cachedResult;
        }

        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            using (var transaction = connection.BeginTransaction())
            {
                try
                {
                    using (var command = new SqlCommand(commandTemplate, connection, transaction))
                    {
                        // Add parameters to prevent SQL injection
                        foreach (var param in parameters)
                        {
                            var sqlParam = command.Parameters.AddWithValue(param.Key, param.Value ?? DBNull.Value);
                            if (param.Value is string) sqlParam.DbType = DbType.String;
                            else if (param.Value is int) sqlParam.DbType = DbType.Int32;
                            // Handle other data types as needed
                        }

                        using (var reader = await command.ExecuteReaderAsync())
                        {
                            var results = new List<T>();
                            while (await reader.ReadAsync())
                            {
                                var result = new T();
                                for (int i = 0; i < reader.FieldCount; i++)
                                {
                                    // Use reflection or a mapping library to map columns to object properties
                                    var property = typeof(T).GetProperty(reader.GetName(i));
                                    if (property != null && !reader.IsDBNull(i))
                                        property.SetValue(result, Convert.ChangeType(reader.GetValue(i), property.PropertyType));
                                }
                                results.Add(result);
                            }

                            // Cache the result
                            _cache.Set(cacheKey, results, new MemoryCacheEntryOptions().SetSlidingExpiration(_cacheExpiration));

                            return results;
                        }
                    }
                }
                catch (Exception ex)
                {
                    transaction.Rollback();
                    _logger.LogError(ex, "Error executing SQL query.");
                    throw; // Re-throw to let the caller handle it
                }
            }
        }
    }

    private string GenerateCacheKey(string commandTemplate, IDictionary<string, object> parameters)
    {
        var keyBuilder = new System.Text.StringBuilder(commandTemplate);

        foreach (var param in parameters)
        {
            keyBuilder.Append($"_{param.Key}:{param.Value}");
        }

        return Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(keyBuilder.ToString()));
    }

    // Additional helper methods for query optimization, logging integration, etc., can be added here
}
```

**Explanation:**

1. **MemoryCache**: Used to store and retrieve frequently executed queries and their results.
2. **ILogger**: Integrated to log errors during query execution.
3. **SqlConnection and SqlCommand**: Manage database connections with connection pooling enabled by default in ADO.NET.
4. **Asynchronous Execution**: Utilizes async/await for non-blocking I/O operations.
5. **Parameterization**: Safeguards against SQL injection through parameterized queries.
6. **Cache Key Generation**: Constructs unique cache keys based on the command template and parameters to ensure distinct caching for different queries.
7. **Configuration via Constructor**: Allows configuration of cache size and expiration policies, which can be adjusted externally.

This approach ensures thread safety by using `MemoryCache`, supports multiple concurrent requests efficiently, and handles large result sets gracefully through asynchronous execution.

