import random
import time
from threading import Lock

# Simulated Database (for demonstration purposes)
orders_db = {}
refunds_log = []
customers_cache = {}

class NetworkError(Exception):
    pass

class PaymentGateway:
    def process_payment(self, order_id, payment_method, amount):
        # Simulate network error for retry logic
        if random.choice([True, False]):
            raise NetworkError("Network timeout")
        return "Success"

class CreditCardGateway(PaymentGateway):
    pass

class PayPalGateway(PaymentGateway):
    pass

gateway_map = {
    'credit_card': CreditCardGateway(),
    'paypal': PayPalGateway()
}

class PaymentProcessor:
    def __init__(self):
        self.lock = Lock()

    def processPayment(self, order_id, payment_method, amount):
        if not isinstance(order_id, int) or not isinstance(amount, (int, float)) or amount <= 0:
            return "Invalid parameters"

        gateway = gateway_map.get(payment_method)
        if not gateway:
            return "Unsupported payment method"

        for _ in range(3):  # Retry logic
            try:
                result = gateway.process_payment(order_id, payment_method, amount)
                return f"Payment {result} for order {order_id}"
            except NetworkError as e:
                time.sleep(1)  # Wait before retrying

        return "Payment failed due to network issues"

    def refundPayment(self, order_id, refund_amount):
        if not isinstance(order_id, int) or not isinstance(refund_amount, (int, float)) or refund_amount <= 0:
            return "Invalid parameters"

        with self.lock:  # Handle concurrency
            if (order_id, refund_amount) in refunds_log:
                return "Refund already processed for this amount"

            # Simulate finding transaction details and processing refund
            success = random.choice([True, False])
            refunds_log.append((order_id, refund_amount))
            return "Refund successful" if success else "Refund failed"

    def createOrder(self, customer_id, items, total_amount):
        if not isinstance(customer_id, int) or not isinstance(total_amount, (int, float)) or total_amount <= 0:
            return "Invalid parameters"

        # Check cache for frequent access
        customer_data = customers_cache.get(customer_id)
        if not customer_data:
            # Simulate fetching from DB and caching
            customer_data = {"id": customer_id}
            customers_cache[customer_id] = customer_data

        order_id = random.randint(1000, 9999)  # Generate unique order ID
        orders_db[order_id] = {
            "customer_id": customer_id,
            "items": items,
            "total_amount": total_amount,
            "status": "pending"
        }

        return f"Order {order_id} created successfully"

    def getOrderDetails(self, order_id):
        if not isinstance(order_id, int) or order_id not in orders_db:
            return "Order not found"

        # Simulate pagination
        start = 0
        limit = 10
        data = list(orders_db.items())[start:start + limit]
        return {k: v for k, v in data}

    def updateOrderStatus(self, order_id, new_status):
        if not isinstance(order_id, int) or order_id not in orders_db:
            return "Invalid order ID"

        with self.lock:  # Handle race conditions
            current_order = orders_db.get(order_id)
            if not current_order:
                return "Order not found"

            # Simulate optimistic locking by checking status hasn't changed unexpectedly
            if current_order['status'] != 'pending':
                return "Cannot update order status from a non-pending state"

            current_order['status'] = new_status
            return f"Order {order_id} status updated to {new_status}"
