class Program
{
    private static readonly ILogger logger = LoggerFactory.Create(builder => builder.AddConsole()).CreateLogger<Program>();

    static void Main(string[] args)
    {
        string configPath = Environment.GetEnvironmentVariable("CONFIG_PATH") ?? "config.xml";

        try
        {
            var configSettings = LoadConfig(configPath);

            byte[][] ciphertexts = { /* Example Ciphertexts */ };
            (byte[] key, byte[] iv)[] keysAndIvs = { /* Corresponding Keys and IVs */ };

            foreach (var i in Enumerable.Range(0, ciphertexts.Length))
            {
                try
                {
                    byte[] plaintext = DecryptCiphertext(ciphertexts[i], keysAndIvs[i].key, keysAndIvs[i].iv);
                    ValidatePlaintextIntegrity(plaintext); // Implement this method to validate integrity
                }
                catch (Exception ex)
                {
                    logger.LogError(ex, "Error during decryption");
                }
            }
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Error loading configuration");
        }
    }

    private static bool ValidateKeyAndIV(byte[] key, byte[] iv)
    {
        // Example: Validate lengths
        return key.Length == 32 && iv.Length == 16;
    }

    private static byte[] DecryptCiphertext(byte[] ciphertext, byte[] key, byte[] iv)
    {
        if (!ValidateKeyAndIV(key, iv))
            throw new ArgumentException("Invalid Key or IV");

        using var aes = Aes.Create();
        aes.Key = key;
        aes.IV = iv;
        aes.Mode = CipherMode.CBC;

        ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

        byte[] decryptedBytes;
        using (var ms = new MemoryStream(ciphertext))
        {
            using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
            using var dt = new MemoryStream();
            cs.CopyTo(dt);
            decryptedBytes = dt.ToArray();
        }

        return decryptedBytes;
    }

    private static ConfigSettings LoadConfig(string path)
    {
        try
        {
            var xDocument = XDocument.Load(path);
            var configRoot = xDocument.Element("Configuration");

            return new ConfigSettings
            {
                TileSize = int.Parse(configRoot.Element("TileSize").Value),
                WorldWidth = int.Parse(configRoot.Element("WorldWidth").Value),
                WorldHeight = int.Parse(configRoot.Element("WorldHeight").Value),
                CameraSpeed = double.Parse(configRoot.Element("CameraSpeed").Value)
            };
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Error parsing configuration file");
            throw;
        }
    }

    private static void ValidatePlaintextIntegrity(byte[] plaintext)
    {
        // Example: Check against a known hash
        var expectedHash = /* Known Hash */;
        using var sha256 = SHA256.Create();
        byte[] actualHash = sha256.ComputeHash(plaintext);

        if (!actualHash.SequenceEqual(expectedHash))
            throw new InvalidOperationException("Plaintext integrity check failed");
    }

    private class ConfigSettings
    {
        public int TileSize { get; set; }
        public int WorldWidth { get; set; }
        public int WorldHeight { get; set; }
        public double CameraSpeed { get; set; }
    }
}
