```java
import java.io.*;
import java.net.InetSocketAddress;
import java.nio.channels.SocketChannel;
import java.util.Random;
import java.util.Scanner;
import java.util.concurrent.locks.ReentrantLock;

public class GameCharacterConnection {

    private static final int MAX_RETRIES = 5; // configurable max retries
    private static final long RETRY_DELAY_MS = 2000; // delay between retries in milliseconds
    private static final long ATTACK_COOLDOWN_MS = 9000; // cooldown period in milliseconds

    private String remoteAddress;
    private int port;
    private Random random = new Random();
    private ReentrantLock lock = new ReentrantLock();

    private volatile boolean attackReady = true;
    private volatile long lastAttackTime = System.currentTimeMillis();

    public GameCharacterConnection(String address, int port) {
        this.remoteAddress = address;
        this.port = port;
    }

    public void runGameLogic() {
        if (!isValidAddress(remoteAddress)) {
            logToFile("Invalid connection details provided.");
            return;
        }

        establishConnectionWithRetries();

        while (true) {
            if (attackReady && canAttack()) {
                lock.lock();
                try {
                    int attack = random.nextInt(2) + 1; // selects either 1 or 2
                    System.out.println("Selected Attack: " + attack);
                    logToFile("Selected Attack: " + attack);
                    lastAttackTime = System.currentTimeMillis();
                    attackReady = false;
                } finally {
                    lock.unlock();
                }
            }

            try {
                Thread.sleep(1000); // check every second
            } catch (InterruptedException e) {
                logToFile("Thread interrupted: " + e.getMessage());
            }
        }
    }

    private boolean canAttack() {
        return System.currentTimeMillis() - lastAttackTime >= ATTACK_COOLDOWN_MS;
    }

    private void establishConnectionWithRetries() {
        int attempt = 0;
        while (attempt < MAX_RETRIES) {
            try {
                SocketChannel socketChannel = SocketChannel.open();
                socketChannel.connect(new InetSocketAddress(remoteAddress, port));
                if (socketChannel.finishConnect()) {
                    logToFile("Successfully connected to " + remoteAddress + ":" + port);
                    return;
                }
            } catch (IOException e) {
                logToFile("Connection attempt failed: " + e.getMessage());
            }

            attempt++;
            try {
                Thread.sleep(RETRY_DELAY_MS);
            } catch (InterruptedException ie) {
                logToFile("Interrupted during retry delay: " + ie.getMessage());
            }
        }
        logToFile("Failed to establish connection after " + MAX_RETRIES + " attempts.");
    }

    private boolean isValidAddress(String address) {
        // Basic validation: ensure no special characters and valid IP format
        return address.matches("[0-9]+(?:\\.[0-9]+){3}");
    }

    private void logToFile(String message) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter("game_logs.txt", true))) {
            writer.write(message);
            writer.newLine();
            // Send to external logging service
            sendToExternalLoggingService(message);
        } catch (IOException e) {
            System.err.println("Error writing log: " + e.getMessage());
        }
    }

    private void sendToExternalLoggingService(String message) {
        // Simulated method for sending logs to an external service
        System.out.println("Sending to logging service: " + message);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter remote address: ");
        String address = scanner.nextLine();

        System.out.print("Enter port number: ");
        int port = Integer.parseInt(scanner.nextLine());

        GameCharacterConnection gameCharacter = new GameCharacterConnection(address, port);
        gameCharacter.runGameLogic();
    }
}
```

