Below is a C++ program that implements a high-performance, multi-threaded custom random number generator with support for various probability distributions. The program uses `std::mt19937_64` and thread-local storage to ensure efficient handling of concurrent threads.

```cpp
#include <iostream>
#include <fstream>
#include <random>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <nlohmann/json.hpp> // Include this header for JSON parsing

namespace Simulation {

    class RandomGenerator {
    public:
        RandomGenerator(const std::string& config_file);
        ~RandomGenerator();

        int uniformInt(int min, int max);
        double uniformDouble(double min, double max);

        double normalDouble(double mean, double stddev);
        double exponentialDouble(double lambda);
        int poissonInt(double lambda);
        int geometricInt(double p);

        static void reconfigure(const std::string& config_file);

    private:
        struct Config {
            // Add configuration parameters here
            bool log_enabled;
            // Other distribution-specific parameters can be added as needed
        };

        static thread_local std::mt19937_64 rng;
        static std::mutex config_mutex;
        static Config config;

        void loadConfig(const std::string& config_file);
        void logEvent(const std::string& event);

        static void initializeGenerator(unsigned long seed);
    };

    thread_local std::mt19937_64 RandomGenerator::rng;
    std::mutex RandomGenerator::config_mutex;
    RandomGenerator::Config RandomGenerator::config = {};

    RandomGenerator::RandomGenerator(const std::string& config_file) {
        loadConfig(config_file);
        initializeGenerator(std::random_device{}());
    }

    RandomGenerator::~RandomGenerator() {}

    void RandomGenerator::initializeGenerator(unsigned long seed) {
        rng.seed(seed);
    }

    int RandomGenerator::uniformInt(int min, int max) {
        std::uniform_int_distribution<int> dist(min, max);
        return dist(rng);
    }

    double RandomGenerator::uniformDouble(double min, double max) {
        std::uniform_real_distribution<double> dist(min, max);
        return dist(rng);
    }

    double RandomGenerator::normalDouble(double mean, double stddev) {
        std::normal_distribution<double> dist(mean, stddev);
        return dist(rng);
    }

    double RandomGenerator::exponentialDouble(double lambda) {
        std::exponential_distribution<double> dist(lambda);
        return dist(rng);
    }

    int RandomGenerator::poissonInt(double lambda) {
        std::poisson_distribution<int> dist(lambda);
        return dist(rng);
    }

    int RandomGenerator::geometricInt(double p) {
        std::bernoulli_distribution bern(p);
        int count = 0;
        while (!bern(rng)) ++count;
        return count;
    }

    void RandomGenerator::reconfigure(const std::string& config_file) {
        std::lock_guard<std::mutex> lock(config_mutex);
        loadConfig(config_file);
    }

    void RandomGenerator::loadConfig(const std::string& config_file) {
        std::ifstream file(config_file);
        if (!file.is_open()) {
            throw std::runtime_error("Could not open configuration file.");
        }
        nlohmann::json j;
        file >> j;
        config.log_enabled = j.value("log_enabled", false);
        // Load other configurations as needed
    }

    void RandomGenerator::logEvent(const std::string& event) {
        if (config.log_enabled) {
            // Implement logging logic here, e.g., write to a log file or console
            std::cout << "Log: " << event << std::endl;
        }
    }
}

int main() {
    try {
        Simulation::RandomGenerator generator("config.json");

        int uniform = generator.uniformInt(1, 100);
        double normal = generator.normalDouble(0.0, 1.0);

        std::cout << "Uniform: " << uniform << ", Normal: " << normal << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
```

### Key Points:
- **Thread-local Storage**: The `std::mt19937_64` instance is stored in thread-local storage to minimize contention.
- **Configuration Handling**: Uses a JSON file for configuration, with error handling for missing or malformed files.
- **Logging Interface**: A simple logging mechanism is included, which can be expanded or replaced as needed.
- **Reconfiguration**: Allows dynamic reconfiguration of the generator using a mutex to ensure thread safety.

### Dependencies:
- The program uses the `nlohmann/json` library for JSON parsing. You need to include this library in your project. It can be found [here](https://github.com/nlohmann/json).

### Testing and Validation:
- Unit tests should be written separately to validate each distribution method, ensuring correctness under various conditions.
- Performance testing should be conducted to ensure the generator performs well under high concurrency.

This code provides a robust foundation for a multi-threaded random number generator suitable for large-scale simulations.

