        Cache cache;
        Logger logger;  // Assume Logger is properly initialized

        executeSQLCommand("sqlite::memory:", {"param1", "param2"}, "myStoredProcedure", cache, logger);
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

