```javascript
function copyBytesFromChunks(chunks, byteCount) {
  const resultBuffer = Buffer.alloc(byteCount);
  let copiedBytes = 0;

  chunks.forEach(chunk => {
    if (typeof chunk !== 'buffer' || !Buffer.isBuffer(chunk)) {
      throw new Error('Chunk is not a valid buffer');
    }

    const bytesToCopy = Math.min(chunk.length, byteCount - copiedBytes);

    if (bytesToCopy < 0) {
      throw new Error('Requested byte count exceeds available data');
    }

    chunk.copy(resultBuffer, copiedBytes, 0, bytesToCopy);
    copiedBytes += bytesToCopy;

    if (copiedBytes === byteCount) return; // Exit early once we have copied enough
  });

  if (copiedBytes < byteCount) {
    throw new Error('Not enough data to fulfill the requested byte count');
  }

  console.log(`Copied ${byteCount} bytes`, { source: chunks.length, destination: resultBuffer });

  return resultBuffer;
}

// Example usage:
const chunk1 = Buffer.from([0x01, 0x02, 0x03]);
const chunk2 = Buffer.from([0x04, 0x05, 0x06]);
try {
  const result = copyBytesFromChunks([chunk1, chunk2], 4);
  console.log(result); // Outputs: <Buffer 01 02 03 04>
} catch (error) {
  console.error(error.message);
}
```

### C++ Session Management Program

```cpp
#include <iostream>
#include <random>
#include <string>
#include <ctime>
#include <openssl/rand.h> 
#include <boost/uuid/uuid_generators.hpp>
#include <base64.h>
#include "redis_client.h" // Assume this is a wrapper for Redis client operations

namespace SessionManager {

class Session {
public:
    std::string sessionId;

    Session() : sessionId(generateUniqueSessionId()) {}

    ~Session() {
        // Clean up resources if needed
    }

private:
    static std::mt19937_64 rng;

    static void seedRandomGenerator() {
        unsigned seed = std::chrono::system_clock::now().time_since_epoch().count();

        RAND_bytes(reinterpret_cast<unsigned char*>(&seed), sizeof(seed));

        rng.seed(seed);
    }

    static std::string generateUniqueSessionId() {
        if (!rng) seedRandomGenerator();

        std::uniform_int_distribution<std::uint64_t> dist(0, UINT64_MAX);

        std::string sessionId;
        bool isUnique = false;

        while (!isUnique) {
            // Generate a 22-character base64 string
            unsigned char randomBytes[16];
            RAND_bytes(randomBytes, sizeof(randomBytes));

            std::string base64String(base64_encode(std::span<char>(randomBytes, 16)));
            sessionId = base64String.substr(0, 22);

            isUnique = RedisClient::acquireLock(sessionId);
        }

        return sessionId;
    }
};

std::mt19937_64 Session::rng;

} // namespace SessionManager

int main() {
    using namespace SessionManager;

    Session session1;
    std::cout << "Session ID: " << session1.sessionId << std::endl;

    return 0;
}
```

