```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>
#include <unistd.h>

// Structure to hold log processing data
typedef struct {
    char *log_file;
    double *sums; // Array to store sums for each line's last two numerical fields
    int count;    // Count of processed lines
} LogData;

// Function to parse binary file and generate output based on rules
void process_binary_file(const char* input_file, const char* output_file, const char* rules) {
    FILE *in = fopen(input_file, "rb");
    if (!in) {
        perror("Failed to open input file");
        exit(EXIT_FAILURE);
    }

    // Implement binary parsing logic here based on the rules
    // For demonstration, assume we write processed data directly to output

    FILE *out = fopen(output_file, "w");
    if (!out) {
        fclose(in);
        perror("Failed to open output file");
        exit(EXIT_FAILURE);
    }

    // Example: reading and writing binary data (actual implementation will vary)
    unsigned char buffer[1024];
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), in)) > 0) {
        fwrite(buffer, 1, bytes_read, out);
    }

    fclose(in);
    fclose(out);
}

// Function to calculate the average of last two numerical fields in a log file
void* process_log_file(void *arg) {
    LogData *data = (LogData *)arg;
    FILE *file = fopen(data->log_file, "r");
    if (!file) {
        perror("Failed to open log file");
        pthread_exit(NULL);
    }

    char line[256];
    double num1, num2;
    while (fgets(line, sizeof(line), file)) {
        int nfields = sscanf(line, "%*[^ ] %*[^ ] %lf %lf", &num1, &num2);
        if (nfields == 2) { // Ensure both numbers are present
            data->sums[data->count * 2]     += num1;
            data->sums[data->count * 2 + 1] += num2;
            data->count++;
        }
    }

    fclose(file);
    pthread_exit(NULL);
}

// Main function to handle command-line arguments and initiate processing
int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <rules> <log_dir>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_file = argv[1];
    const char *output_file = argv[2];
    const char *rules = argv[3];
    const char *log_dir = argv[4];

    // Process the binary file
    process_binary_file(input_file, output_file, rules);

    // Directory processing for log files
    DIR *dir = opendir(log_dir);
    if (!dir) {
        perror("Failed to open directory");
        return EXIT_FAILURE;
    }

    struct dirent *entry;
    pthread_t threads[256];
    int thread_count = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // If the entry is a regular file
            char path[1024];
            snprintf(path, sizeof(path), "%s/%s", log_dir, entry->d_name);

            LogData *data = malloc(sizeof(LogData));
            data->log_file = strdup(path);
            data->sums = calloc(256, sizeof(double)); // Assuming max 128 lines with 2 numbers each
            data->count = 0;

            pthread_create(&threads[thread_count++], NULL, process_log_file, data);

            if (thread_count >= 256) {
                for (int i = 0; i < thread_count; ++i)
                    pthread_join(threads[i], NULL);

                thread_count = 0;
            }
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < thread_count; ++i)
        pthread_join(threads[i], NULL);

    closedir(dir);

    return EXIT_SUCCESS;
}
```

