    'provider_name',
    **app.config['OAUTH_CREDENTIALS']
)

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

@app.route('/login')
@limiter.limit("10 per minute")
def login():
    callback=url_for('authorized', _external=True)
    return provider.authorize(callback=callback)

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('index'))

@app.route('/login/authorized')
def authorized():
    resp = provider.authorized_response()
    if resp is None or resp.get('access_token') is None:
        return 'Access denied: reason={0} error={1}'.format(
            request.args['error_reason'],
            request.args['error_description']
        )

    session['oauth_token'] = (resp['access_token'], '')
    me = provider.get('/userinfo')
    user = User.query.filter_by(email=me.data['email']).first()
    if not user:
        user = User(email=me.data['email'])
        db.session.add(user)
        db.session.commit()

    login_user(user)
    return redirect(url_for('index'))

@provider.tokengetter
def get_oauth_token():
    return session.get('oauth_token')

@app.route('/')
@login_required
def index():
    return 'Welcome {}!'.format(current_user.email)

# RBAC check decorator
from functools import wraps
def role_required(*roles):
    def wrapper(fn):
        @wraps(fn)
        def decorated_view(*args, **kwargs):
            if not any(role.name in roles for role in current_user.roles):
                return 'Access Denied', 403
            return fn(*args, **kwargs)
        return decorated_view
    return wrapper

@app.route('/admin')
@login_required
@role_required('Admin')
def admin():
    return 'Admin Dashboard'

if __name__ == '__main__':
    db.create_all()
    app.run(threaded=True)

