using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;

public class DynamicRandomValueGenerator
{
    private static readonly HttpClient _httpClient = new HttpClient();
    private ConcurrentDictionary<string, (int MinInt, int MaxInt)> _intRangeCache = new();
    private ConcurrentDictionary<string, (float MinFloat, float MaxFloat)> _floatRangeCache = new();

    public async Task<int> CustomRangeAsync(string key, bool isExclusive, bool seeded, int? seed)
    {
        var range = await GetOrFetchIntRangeAsync(key);

        Random random;
        if (seeded && seed.HasValue)
        {
            random = new Random(seed.Value);
        }
        else
        {
            random = new Random();
        }

        int min = range.MinInt;
        int max = isExclusive ? range.MaxInt : range.MaxInt + 1;

        return random.Next(min, max);
    }

    public async Task<float> CustomRangeAsync(string key, bool isExclusive, bool seeded, int? seed)
    {
        var range = await GetOrFetchFloatRangeAsync(key);

        Random random;
        if (seeded && seed.HasValue)
        {
            random = new Random(seed.Value);
        }
        else
        {
            random = new Random();
        }

        float min = range.MinFloat;
        float max = isExclusive ? range.MaxFloat : range.MaxFloat + 1;

        return min + (float)random.NextDouble() * (max - min);
    }

    private async Task<(int MinInt, int MaxInt)> GetOrFetchIntRangeAsync(string key)
    {
        if (!_intRangeCache.TryGetValue(key, out var cached))
        {
            var range = await FetchIntRangeFromSourceAsync(key);
            _intRangeCache[key] = range;
            return range;
        }

        return cached;
    }

    private async Task<(float MinFloat, float MaxFloat)> GetOrFetchFloatRangeAsync(string key)
    {
        if (!_floatRangeCache.TryGetValue(key, out var cached))
        {
            var range = await FetchFloatRangeFromSourceAsync(key);
            _floatRangeCache[key] = range;
            return range;
        }

        return cached;
    }

    private async Task<(int MinInt, int MaxInt)> FetchIntRangeFromSourceAsync(string key)
    {
        try
        {
            string url = $"https://api.example.com/intervals/{key}";
            var response = await _httpClient.GetStringAsync(url);
            // Assume JSON deserialization to a tuple (MinInt, MaxInt) happens here
            return (0, 100); // Placeholder for actual deserialized data
        }
        catch (Exception)
        {
            throw new InvalidOperationException("Failed to fetch interval boundaries.");
        }
    }

    private async Task<(float MinFloat, float MaxFloat)> FetchFloatRangeFromSourceAsync(string key)
    {
        try
        {
            string url = $"https://api.example.com/float-intervals/{key}";
            var response = await _httpClient.GetStringAsync(url);
            // Assume JSON deserialization to a tuple (MinFloat, MaxFloat) happens here
            return (0.0f, 1.0f); // Placeholder for actual deserialized data
        }
        catch (Exception)
        {
            throw new InvalidOperationException("Failed to fetch interval boundaries.");
        }
    }

    public void ClearCache()
    {
        _intRangeCache.Clear();
        _floatRangeCache.Clear();
    }
}
