```python
import lz4.frame
import os
import hashlib
import json
from concurrent.futures import ThreadPoolExecutor, as_completed
import requests

class CompressionService:
    def __init__(self, config_service_url):
        self.config_service_url = config_service_url

    def fetch_compression_settings(self):
        response = requests.get(f"{self.config_service_url}/compression-settings")
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception("Failed to fetch compression settings")

    def store_metadata(self, file_path, metadata):
        headers = {'Content-Type': 'application/json'}
        response = requests.post(f"{self.config_service_url}/metadata", data=json.dumps(metadata), headers=headers)
        if response.status_code != 201:
            raise Exception("Failed to store metadata")

    def _compress_file(self, file_path, compression_level):
        with open(file_path, 'rb') as input_file, \
             open(f"{file_path}.lz4", 'wb') as output_file:

            while True:
                data = input_file.read(64 * 1024)  # Read in chunks of 64 KB
                if not data:
                    break
                compressed_data = lz4.frame.compress(data, compression_level=compression_level)
                output_file.write(compressed_data)

    def _decompress_file(self, file_path):
        with open(file_path, 'rb') as input_file, \
             open(f"{file_path[:-5]}", 'wb') as output_file:  # Remove .lz4 extension

            while True:
                data = input_file.read(64 * 1024)  # Read in chunks of 64 KB
                if not data:
                    break
                decompressed_data = lz4.frame.decompress(data)
                output_file.write(decompressed_data)

    def compress(self, file_path):
        settings = self.fetch_compression_settings()
        compression_level = settings.get('compression_level', 1)

        try:
            self._compress_file(file_path, compression_level)

            metadata = {
                'file_name': os.path.basename(file_path),
                'original_size': os.path.getsize(file_path),
                'compressed_size': os.path.getsize(f"{file_path}.lz4"),
                'checksum': self.calculate_checksum(file_path)
            }
            self.store_metadata(file_path, metadata)

        except Exception as e:
            print(f"Error during compression: {e}")

    def decompress(self, file_path):
        try:
            self._decompress_file(file_path)

            # Verify integrity
            original_file = f"{file_path[:-5]}"  # Remove .lz4 extension
            metadata_response = requests.get(f"{self.config_service_url}/metadata/{os.path.basename(original_file)}")
            if metadata_response.status_code == 200:
                metadata = metadata_response.json()

                decompressed_checksum = self.calculate_checksum(original_file)
                if decompressed_checksum != metadata['checksum']:
                    raise Exception("Data integrity check failed after decompression")

        except Exception as e:
            print(f"Error during decompression: {e}")

    def calculate_checksum(self, file_path):
        sha256_hash = hashlib.sha256()
        with open(file_path, "rb") as f:
            for byte_block in iter(lambda: f.read(4096), b""):
                sha256_hash.update(byte_block)
        return sha256_hash.hexdigest()

def batch_compress_decompress(files_to_process, action='compress'):
    compression_service = CompressionService(config_service_url="https://config-service-url")

    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = []

        for file_path in files_to_process:
            if action == 'compress':
                futures.append(executor.submit(compression_service.compress, file_path))
            elif action == 'decompress':
                futures.append(executor.submit(compression_service.decompress, f"{file_path}.lz4"))
            else:
                raise ValueError("Unsupported action. Use 'compress' or 'decompress'.")

        for future in as_completed(futures):
            try:
                future.result()
            except Exception as e:
                print(f"File processing failed: {e}")

# Usage example
files_to_compress = ['file1.txt', 'large_file.dat']
batch_compress_decompress(files_to_compress, action='compress')
