class ConfigLoader {

    private $logger: LoggerInterface;
    private $environment;

    public function __construct(LoggerInterface $logger)
    {
        $this->logger = $logger;
        $this->environment = $this->detectEnvironment();
        $this->loadConfiguration();
    }

    private function detectEnvironment() 
    {
        // Implement logic to detect server environment
        return getenv('APP_ENV') ?: 'production';
    }

    private function loadConfiguration()
    {
        ob_start();

        if ($configData = $this->fetchConfigFromDatabase()) {
            $configContent = $this->generateConfigFile($configData);
            file_put_contents('/path/to/config.php', $configContent);
        } else {
            $this->logger->error('Failed to fetch configuration from database, using defaults.');
            copy('/path/to/default_config.php', '/path/to/config.php');
        }

        ob_end_flush();
    }

    private function fetchConfigFromDatabase()
    {
        // Assume an asynchronous query method is available
        return async_query('SELECT * FROM configurations WHERE environment = ?', [$this->environment]);
    }

    private function generateConfigFile($configData)
    {
        $content = "<?php\nreturn " . var_export($configData, true) . ";\n";
        return $content;
    }
}

