// Define a structure to manage the directory
struct FileManager {
    work_dir: Arc<ParkingLotMutex<PathBuf>>,
}

impl FileManager {
    fn new() -> io::Result<Self> {
        let env_var = env::var("WORK_DIR").map_err(|_| io::Error::new(io::ErrorKind::NotFound, "WORK_DIR not set"))?;
        let work_dir_path = PathBuf::from(env_var);

        if Self::validate_directory(&work_dir_path)? {
            debug!("Using existing WORK_DIR: {:?}", work_dir_path);
            Ok(FileManager {
                work_dir: Arc::new(ParkingLotMutex::new(work_dir_path)),
            })
        } else {
            let temp_dir = TempDir::new_in("/tmp")?;
            let tmp_path = temp_dir.path().to_path_buf();
            debug!("Created new temporary WORK_DIR: {:?}", tmp_path);
            Ok(FileManager {
                work_dir: Arc::new(ParkingLotMutex::new(tmp_path)),
            })
        }
    }

    fn validate_directory(path: &Path) -> io::Result<bool> {
        path.exists() && fs::metadata(&path)?.permissions().readonly() == false
