function copyBytesFromChunks(chunks, byteCount, encoding = 'utf8') {
    let resultBuffer = Buffer.alloc(0);
    let totalCopiedBytes = 0;

    try {
        chunks.forEach(chunk => {
            if (!Buffer.isBuffer(chunk)) {
                throw new Error(`Invalid chunk type: expected Buffer, got ${typeof chunk}`);
            }

            const remainingByteCount = byteCount - totalCopiedBytes;
            if (remainingByteCount <= 0) return;

            if (chunk.length < remainingByteCount) {
                resultBuffer = Buffer.concat([resultBuffer, chunk]);
                totalCopiedBytes += chunk.length;
            } else {
                const portionToCopy = Buffer.from(chunk.slice(0, remainingByteCount), encoding);
                resultBuffer = Buffer.concat([resultBuffer, portionToCopy]);
                totalCopiedBytes += remainingByteCount;
            }
        });

        if (totalCopiedBytes < byteCount) {
            throw new Error(`Requested ${byteCount} bytes but only ${totalCopiedBytes} bytes available.`);
        }

    } catch (error) {
        const logData = {
            timestamp: new Date().toISOString(),
            errorDetails: error.message,
            sourceIdentifier: uuidv4(), // Example unique identifier for logging
        };
        logToDatabase(logData);
        throw new Error(`Failed to copy bytes due to an error: ${error.message}`);
    }

    return resultBuffer;
}

// Usage example with mock data:
(async () => {
  const chunks = [
      Buffer.from('Hello ', 'utf8'),
      Buffer.from('World!', 'utf8')
  ];

  try {
      const copiedData = copyBytesFromChunks(chunks, 11); // Expecting to copy "Hello World!"
      console.log(copiedData.toString()); // Output: Hello World!
  } catch (error) {
      console.error(error.message);
  }
})();
