from threading import Lock
from collections import defaultdict
import logging

class UserSessionManager:
    def __init__(self):
        self.sessions = {}
        self.cache = {}
        self.lock = Lock()
        self.rate_limits = defaultdict(int)
        self.logger = logging.getLogger(__name__)

    def update_session_data(self, user_id, last_activity, ip_address, device_type):
        with self.lock:
            current_time = time.time()

            # Rate limiting
            if self.rate_limits[user_id] > 5 and (current_time - self.rate_limits[user_id]) < 60:
                raise Exception("Rate limit exceeded")
            self.rate_limits[user_id] = current_time

            # Update session data
            session_data = {
                "last_activity": last_activity,
                "ip_address": ip_address,
                "device_type": device_type
            }

            if user_id in self.sessions:
                self.sessions[user_id].update(session_data)
            else:
                self.sessions[user_id] = session_data

            # Update cache
            self.cache[user_id] = current_time

    def validate_user_session(self, user_id, ip_address, device_type):
        with self.lock:
            if user_id not in self.sessions:
                return False

            session_data = self.sessions.get(user_id)

            if (time.time() - session_data["last_activity"]) > 3600:  # Session timeout
                self.logger.warning(f"Session expired for user {user_id}")
                return False

            if session_data["ip_address"] != ip_address or session_data["device_type"] != device_type:
                self.logger.error(f"Invalid session for user {user_id} - possible hijack attempt")
                return False

            # External API authentication check (mocked)
            if not self.external_auth_check(user_id):
                return False

            return True

    def external_auth_check(self, user_id):
        # Mock of an external API call
        return True

    def flush_expired_sessions(self):
        current_time = time.time()
        expired_sessions = [user_id for user_id, cache_time in self.cache.items() if (current_time - cache_time) > 3600]

        with self.lock:
            for user_id in expired_sessions:
                del self.sessions[user_id]
                del self.cache[user_id]

    def session_to_json(self, user_id):
        return json.dumps(self.sessions.get(user_id))

    def create_session_from_json(self, json_string):
        session_data = json.loads(json_string)
        return UserSessionManager.Session(session_data)

    class Session:
        def __init__(self, data):
            self.data = data

    @staticmethod
    def register_factory_function(factory_func):
        # Implement factory function registration logic
        pass

    @classmethod
    def create_session_instance(cls, session_type, *args, **kwargs):
        # Create a new session instance based on the type
        if session_type == 'default':
            return cls.Session(kwargs)
        raise ValueError(f"Unknown session type: {session_type}")


