import unittest

class TestUserSessionManager(unittest.TestCase):

    def setUp(self):
        self.manager = UserSessionManager()

    def test_update_and_validate_session(self):
        user_id = "test_user"
        last_activity = time.time()
        ip_address = "127.0.0.1"
        device_type = "desktop"

        # Update session
        self.manager.update_session_data(user_id, last_activity, ip_address, device_type)

        # Validate session - should be valid
        self.assertTrue(self.manager.validate_user_session(user_id, ip_address, device_type))

    def test_rate_limiting(self):
        user_id = "rate_limited_user"
        last_activity = time.time()
        ip_address = "127.0.0.1"
        device_type = "desktop"

        # Update session to hit rate limit
        for _ in range(6):
            self.manager.update_session_data(user_id, last_activity, ip_address, device_type)

        with self.assertRaises(Exception):
            self.manager.update_session_data(user_id, last_activity, ip_address, device_type)

    def test_session_timeout(self):
        user_id = "timeout_user"
        last_activity = time.time() - 4000
        ip_address = "127.0.0.1"
        device_type = "desktop"

        # Update session with old timestamp
        self.manager.update_session_data(user_id, last_activity, ip_address, device_type)

        # Validate session - should be invalid due to timeout
        self.assertFalse(self.manager.validate_user_session(user_id, ip_address, device_type))

    def test_session_hijack_detection(self):
        user_id = "hijack_user"
        last_activity = time.time()
        ip_address = "127.0.0.1"
        device_type = "desktop"

        # Update session
        self.manager.update_session_data(user_id, last_activity, ip_address, device_type)

        # Attempt to validate with different IP or device type - should be invalid
        self.assertFalse(self.manager.validate_user_session(user_id, "192.168.1.1", "mobile"))

    def test_json_conversion(self):
        user_id = "json_test_user"
        session_data = {
            "last_activity": time.time(),
            "ip_address": "127.0.0.1",
            "device_type": "desktop"
        }

        # Update session
        self.manager.update_session_data(user_id, **session_data)

        # Convert to JSON and back
        json_str = self.manager.session_to_json(user_id)
        new_session = self.manager.create_session_from_json(json_str)

        self.assertEqual(new_session.data, session_data)


if __name__ == '__main__':
    unittest.main()
