const { MongoClient } = require('mongodb');
const net = require('net');

async function collectAndSaveData(serverAddress, port, dbName, collectionName) {
    let db;
    let socket;
    let isPaused = false;

    const client = new MongoClient(process.env.MONGODB_URI, {
        useNewUrlParser: true,
        useUnifiedTopology: true
    });

    try {
        await client.connect();
        console.log("Connected to MongoDB");
        db = client.db(dbName);

        socket = net.createConnection({ host: serverAddress, port }, () => {
            console.log('Network stream connected');
            receiveData();
        });

        socket.on('data', (chunk) => {
            if (!isPaused) {
                processData(chunk);
            }
        });

        socket.on('error', (err) => {
            console.error("Network error:", err.message);
            // Implement retry logic or other error handling
        });

        socket.on('close', () => {
            console.log("Network stream closed");
            client.close();
        });

    } catch (err) {
        console.error("MongoDB connection error:", err.message);
        // Handle database errors, e.g., retrying the connection
    }

    async function receiveData() {
        try {
            while (socket.connected) {
                if (!isPaused) {
                    await processDataChunk();
                }
            }
        } catch (err) {
            console.error("Error receiving data:", err.message);
            // Handle errors, possibly resume or retry logic
        }
    }

    async function processData(chunk) {
        try {
            const documents = parseDataIntoDocuments(chunk);
            if (documents.length > 0) {
                await db.collection(collectionName).insertMany(documents);
            }
        } catch (err) {
            console.error("Error processing data:", err.message);
            // Handle parsing errors, maybe log the chunk or retry
        }
    }

    async function processDataChunk() {
        const buffer = Buffer.alloc(1024 * 64); // Adjust size based on expected data volume
        let bytesRead = await new Promise((resolve, reject) => {
            socket.on('data', (chunk) => {
                chunk.copy(buffer, bytesRead);
                bytesRead += chunk.length;
                if (bytesRead >= buffer.length) resolve(bytesRead);
            });

            socket.once('end', () => resolve(bytesRead));
        });

        processData(buffer.slice(0, bytesRead));
    }

    function parseDataIntoDocuments(dataBuffer) {
        // Parse the raw data into an array of documents
        return JSON.parse(dataBuffer.toString()); // Example parsing logic; adjust as needed
    }

    function pause() {
        isPaused = true;
        console.log("Data collection paused.");
    }

    function resume() {
        if (isPaused) {
            isPaused = false;
            console.log("Data collection resumed.");
        }
    }

    return { pause, resume };
}

// Example usage:
const dataHandler = collectAndSaveData('localhost', 3000, 'myDatabase', 'dataCollection');
// To pause/resume
// dataHandler.pause();
// dataHandler.resume();
