// Function to execute tests
void runModuleTests(const std::string& moduleLabel,
                    const std::vector<std::function<void(const std::string&, std::function<void()>)>>& testSuite,
                    const std::string& loggingLevel,
                    int cooldown,
                    std::unique_ptr<ResourceManager> resourceManager) {

    MockingLibrary mockLib;

    for (size_t i = 0; i < testSuite.size(); ++i) {
        // Initialize mocking library with configurations
        auto config = resourceManager->getConfigForTest(i);
        mockLib.initialize(config);

        // Run the test asynchronously in an isolated environment
        auto attackFunction = [&, i]() {
            try {
                std::cout << "Running Test #" << (i + 1) << " for module: " << moduleLabel << std::endl;

                testSuite[i](moduleLabel, [&mockLib]() {
                    // Attack function logic here; using mock library
                });

                if (loggingLevel == "info") {
                    std::cout << "Test #" << (i + 1) << " passed." << std::endl;
                }
            } catch (const std::exception& e) {
                std::cerr << "Test #" << (i + 1) << " failed: " << e.what() << std::endl;

                if (loggingLevel == "error") {
                    std::cerr << "Error details for Test #" << (i + 1) << ": " << e.what() << std::endl;
                }
            } catch (...) {
                std::cerr << "Test #" << (i + 1) << " failed with unknown error." << std::endl;

                if (loggingLevel == "error") {
                    std::cerr << "Unknown error details for Test #" << (i + 1) << std::endl;
                }
            }

            // Reset mocking library to ensure no side effects
            resourceManager->cleanUp(mockLib);
        };

        attackFunction();

        // Cooldown period between tests
        std::this_thread::sleep_for(std::chrono::seconds(cooldown));
    }
}
