using System;
using System.Data.SqlClient;
using System.Security.Cryptography;
using BCrypt.Net;
using Konscious.Security.Cryptography;

public enum HashAlgorithmType
{
    SHA256,
    Bcrypt,
    Argon2
}

public class PasswordManager
{
    private readonly string connectionString;
    private HashAlgorithmType currentAlgorithm;

    public PasswordManager(string dbConnectionString, HashAlgorithmType defaultAlgorithm = HashAlgorithmType.Argon2)
    {
        this.connectionString = dbConnectionString;
        this.currentAlgorithm = defaultAlgorithm;
    }

    public string GenerateSalt()
    {
        using (var rng = RandomNumberGenerator.Create())
        {
            byte[] saltBytes = new byte[16];
            rng.GetBytes(saltBytes);
            return Convert.ToBase64String(saltBytes);
        }
    }

    public string HashPassword(string password, string salt = null)
    {
        switch (currentAlgorithm)
        {
            case HashAlgorithmType.SHA256:
                using (var sha256 = SHA256.Create())
                {
                    var bytes = System.Text.Encoding.UTF8.GetBytes(password + (salt ?? GenerateSalt()));
                    return Convert.ToBase64String(sha256.ComputeHash(bytes));
                }

            case HashAlgorithmType.Bcrypt:
                return BCrypt.Net.BCrypt.HashPassword(password, salt ?? GenerateSalt());

            case HashAlgorithmType.Argon2:
                var argon2 = new Argon2id(Encoding.UTF8);
                return Convert.ToBase64String(argon2.GetBytes(password, (salt ?? GenerateSalt()).ToCharArray()));
        }

        throw new InvalidOperationException("Unsupported hashing algorithm.");
    }

    public bool VerifyPassword(string password, string hashedPassword, string salt)
    {
        switch (currentAlgorithm)
        {
            case HashAlgorithmType.SHA256:
                using (var sha256 = SHA256.Create())
                {
                    var bytes = System.Text.Encoding.UTF8.GetBytes(password + salt);
                    return Convert.ToBase64String(sha256.ComputeHash(bytes)) == hashedPassword;
                }

            case HashAlgorithmType.Bcrypt:
                return BCrypt.Net.BCrypt.Verify(password, hashedPassword);

            case HashAlgorithmType.Argon2:
                var argon2 = new Argon2id(Encoding.UTF8);
                var computedBytes = argon2.GetBytes(password, salt.ToCharArray());
                return Convert.ToBase64String(computedBytes) == hashedPassword;
        }

        throw new InvalidOperationException("Unsupported hashing algorithm.");
    }

    public void StorePassword(string username, string hashedPassword, string salt)
    {
        using (var connection = new SqlConnection(connectionString))
        {
            var command = new SqlCommand(
                "INSERT INTO UserPasswords (Username, HashedPassword, Salt) VALUES (@Username, @HashedPassword, @Salt)", 
                connection);
            command.Parameters.AddWithValue("@Username", username);
            command.Parameters.AddWithValue("@HashedPassword", hashedPassword);
            command.Parameters.AddWithValue("@Salt", salt);

            connection.Open();
            command.ExecuteNonQuery();
        }
    }

    public (string HashedPassword, string Salt) RetrievePassword(string username)
    {
        using (var connection = new SqlConnection(connectionString))
        {
            var command = new SqlCommand(
                "SELECT HashedPassword, Salt FROM UserPasswords WHERE Username = @Username", 
                connection);
            command.Parameters.AddWithValue("@Username", username);

            connection.Open();
            using (var reader = command.ExecuteReader())
            {
                if (reader.Read())
                {
                    return (reader.GetString(0), reader.GetString(1));
                }
            }
        }

        throw new ArgumentException("User not found.");
    }

    public void SwitchAlgorithm(HashAlgorithmType algorithm)
    {
        currentAlgorithm = algorithm;
    }

    // Method to integrate with external authentication API, handle MFA, and rate limiting
    public void IntegrateExternalAuthAPI()
    {
        // Placeholder for integration logic
    }

    // Method to log password-related activities
    private void LogActivity(string message)
    {
        // Placeholder for logging implementation
    }

    // Unit tests can be written using a testing framework like NUnit or MSTest
}

// Example usage in a test class:
