    {
        var manager = new PasswordManager("YourConnectionStringHere");

        string password = "TestPassword123!";
        string salt = manager.GenerateSalt();
        string hashedPassword = manager.HashPassword(password, salt);

        bool isVerified = manager.VerifyPassword(password, hashedPassword, salt);
        Console.WriteLine($"Password verified: {isVerified}");
    }
