    }

    // Method to decrypt a message using AES-CBC
    public async Task<byte[]> DecryptMessageAsync(byte[] cipherText, byte[] key, byte[] iv)
    {
        if (!AuthenticateWithExternalService()) return null;

        try
        {
            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = key;
                aesAlg.IV = iv;
                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                using (MemoryStream msDecrypt = new MemoryStream(cipherText))
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                using (MemoryStream result = new MemoryStream())
                {
                    await csDecrypt.CopyToAsync(result);
                    return result.ToArray();
                }
            }
        }
        catch (CryptographicException ex)
        {
            LogError("Decryption failed: " + ex.Message);
            throw new Exception("Decryption failed. Please check your key and IV.", ex);
        }
    }

    private bool AuthenticateWithExternalService()
    {
