    public string HashPasswordSHA256(string password, string salt = null)
    {
        using (SHA256 sha256Hash = SHA256.Create())
        {
            byte[] data = Encoding.UTF8.GetBytes(salt ?? GenerateSalt(16) + password);
            byte[] hashBytes = sha256Hash.ComputeHash(data);

            return Convert.ToBase64String(hashBytes);
        }
    }

    public string HashPasswordBcrypt(string password)
    {
        // Use BCrypt.Net library (Install-Package BCrypt-Net)
        return BCrypt.Net.BCrypt.HashPassword(password, workfactor: 12);
    }

    public bool VerifyHashedPasswordBcrypt(string hashedPassword, string password)
    {
        return BCrypt.Net.BCrypt.Verify(password, hashedPassword);
    }

    public string HashPasswordArgon2(string password, string salt = null)
    {
        // Use Konscious.Security.Cryptography.Argon2 library (Install-Package Argon2)
        byte[] passBytes = Encoding.UTF8.GetBytes(salt ?? GenerateSalt(16) + password);
        return Convert.ToBase64String(Argon2.Compute(
            pass: passBytes,
            salt: Encoding.UTF8.GetBytes(salt),
            parallelism: 4, // Number of threads
            iterations: 3, // Iterations
            memorySizeKB: 2048, // Memory size in kilobytes
            hashLength: 32)); // Hash length in bytes
    }

    public bool VerifyHashedPasswordArgon2(string hashedPassword, string password, string salt)
    {
        byte[] passBytes = Encoding.UTF8.GetBytes(salt + password);
        byte[] hashBytes = Convert.FromBase64String(hashedPassword);

        return Argon2.Verify(hashBytes, passBytes, Encoding.UTF8.GetBytes(salt));
    }

    private string GenerateSalt(int size)
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            var saltBytes = new byte[size];
            rng.GetBytes(saltBytes);
            return Convert.ToBase64String(saltBytes);
        }
    }

