Below is an example JavaScript implementation addressing the outlined challenges. This code provides a basic structure using modern practices like Promises and async/await for asynchronous script loading, error handling, performance optimization, and user interface feedback.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Dynamic Script Loader</title>
    <style>
        #loading-spinner {
            display: none;
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            font-size: 24px;
        }
    </style>
</head>
<body>

<div id="loading-spinner">Loading...</div>

<script>
class ScriptLoader {
    constructor() {
        this.loadedScripts = new Set();
    }

    async loadScript(src, priority = 0) {
        if (this.loadedScripts.has(src)) return Promise.resolve();

        try {
            const script = document.createElement('script');
            script.src = src;
            script.async = true;

            // Visual feedback
            this.showLoadingIndicator(true);

            // Performance: Add priority handling logic here if needed

            return new Promise((resolve, reject) => {
                script.onload = () => {
                    this.loadedScripts.add(src);
                    resolve();
                };
                script.onerror = (error) => {
                    console.error(`Error loading script ${src}:`, error);
                    reject(new Error(`Failed to load script: ${src}`));
                };

                document.head.appendChild(script);
            });
        } catch (error) {
            this.handleError(error);
            return Promise.reject(error);
        }
    }

    async loadScripts(scripts, fallbacks = {}) {
        const loadingPromises = scripts.map(async (scriptInfo) => {
            try {
                await this.loadScript(scriptInfo.src, scriptInfo.priority);
            } catch (error) {
                console.warn(`Loading ${scriptInfo.src} failed. Attempting fallback...`);
                if (fallbacks[scriptInfo.src]) {
                    await this.loadScript(fallbacks[scriptInfo.src]);
                }
            }
        });

        return Promise.all(loadingPromises);
    }

    showLoadingIndicator(show) {
        const spinner = document.getElementById('loading-spinner');
        spinner.style.display = show ? 'block' : 'none';
    }

    handleError(error) {
        // Implement robust error handling and user feedback
        console.error("Script loading error:", error);
        alert(`An error occurred while loading scripts: ${error.message}`);
    }
}

const scriptLoader = new ScriptLoader();

(async () => {
    const scriptsToLoad = [
        { src: 'https://cdn.jsdelivr.net/npm/vue@2.6.14/dist/vue.js', priority: 1 },
        // Add more scripts with priorities
    ];

    const fallbacks = {
        'https://cdn.jsdelivr.net/npm/vue@2.6.14/dist/vue.js': 'path/to/local/fallback/vue.js',
        // Add more fallback paths for other libraries if needed
    };

    try {
        await scriptLoader.loadScripts(scriptsToLoad, fallbacks);
        console.log('All scripts loaded successfully');
        scriptLoader.showLoadingIndicator(false); // Hide spinner once done
    } catch (error) {
        scriptLoader.handleError(error);
    }
})();
</script>

</body>
</html>
```

### Explanation of Key Features:

1. **Asynchronous Loading**: Uses `async/await` and Promises to load scripts asynchronously, allowing other operations to proceed without waiting for all scripts to be loaded.

2. **Error Handling**: Catches errors during script loading, logs them, and provides user feedback via console and alerts.

3. **Performance Optimization**: Scripts are loaded with the `async` attribute set to true to avoid blocking rendering. Visual indicators inform users of ongoing operations.

4. **Scalability**: The `loadScripts` method handles multiple scripts concurrently using `Promise.all`, which helps in efficiently managing multiple requests.

5. **Fallback Mechanism**: If a primary script fails, attempts are made to load an alternative from the fallback configuration.

6. **User Experience**: Includes a simple loading spinner that is displayed during script loading and hidden once done.

7. **Maintainability**: The code is modular, with clear separation of concerns (script loading, error handling), making it easier to maintain and extend in the future.

