const fs = require('fs');
const path = require('path');
const { MongoClient } = require('mongodb');
const EventEmitter = require('events');

// Configuration loader
function loadConfigurations(configFilePath) {
    try {
        const configContent = fs.readFileSync(configFilePath, 'utf-8');
        return JSON.parse(configContent);
    } catch (error) {
        console.error(`Failed to load configurations: ${error.message}`);
        return [];
    }
}

// Protocol loader with caching
class ProtocolLoader extends EventEmitter {
    constructor(directoryPath) {
        super();
        this.directoryPath = directoryPath;
        this.protocolCache = {};
    }

    async loadProtocols() {
        const files = fs.readdirSync(this.directoryPath);

        for (const file of files) {
            try {
                if (file.endsWith('.js')) {
                    const protocolModule = await import(path.join(this.directoryPath, file));
                    const protocolConfig = require(path.join(this.directoryPath, `${file}.json`));

                    this.protocolCache[protocolConfig.name] = {
                        implementation: protocolModule,
                        config: protocolConfig
                    };

                    this.emit('protocolLoaded', protocolConfig.name);
                }
            } catch (error) {
                console.error(`Error loading protocol from ${file}: ${error.message}`);
            }
        }
    }

    getProtocol(name) {
        return this.protocolCache[name];
    }
}

// Network stream handler
class StreamHandler {
    constructor(dbUri, dbName, collectionName) {
        this.dbUri = dbUri;
        this.dbName = dbName;
        this.collectionName = collectionName;
        this.paused = false;
        this.client = new MongoClient(this.dbUri);
        this.dataBuffer = [];
    }

    async connect() {
        try {
            await this.client.connect();
            console.log('Connected to MongoDB');
        } catch (error) {
            console.error(`Failed to connect to database: ${error.message}`);
        }
    }

    disconnect() {
        if (this.client.isConnected()) {
            this.client.close().then(() => console.log('Disconnected from MongoDB'));
        }
    }

    async saveData(data) {
        try {
            const db = this.client.db(this.dbName);
            await db.collection(this.collectionName).insertMany(data);
            console.log(`Saved ${data.length} records to the database`);
        } catch (error) {
            console.error(`Failed to save data: ${error.message}`);
        }
    }

    async processData(stream, protocol) {
        for await (const chunk of stream) {
            if (!this.paused) {
                this.dataBuffer.push(...chunk);
                const batch = this.dataBuffer.splice(0, 100); // Process in batches
                await this.saveData(batch);
            }
        }
    }

    pause() {
        this.paused = true;
    }

    resume() {
        this.paused = false;
    }

    async handleError(error) {
        console.error(`Stream error: ${error.message}`);
        await this.disconnect();
        // Implement retry logic or alert user as needed
    }
}

// Main function to collect data from a network stream and save it to MongoDB
async function collectAndSaveData(stream, protocolName, dbUri, dbName, collectionName) {
    const protocolLoader = new ProtocolLoader(path.join(__dirname, 'protocols'));
    await protocolLoader.loadProtocols();

    const protocolConfig = protocolLoader.getProtocol(protocolName);
    if (!protocolConfig) {
        console.error(`Protocol ${protocolName} not found`);
        return;
    }

    const streamHandler = new StreamHandler(dbUri, dbName, collectionName);
    await streamHandler.connect();

    try {
        await streamHandler.processData(stream, protocolConfig.implementation);
    } catch (error) {
        await streamHandler.handleError(error);
    } finally {
        await streamHandler.disconnect();
    }
}

