```c
#include <stdio.h>
#include <stdlib.h>

// Define the Task struct
typedef struct Task {
    int id;
    int priority;
    long deadline;
    void (*execute)(void); // Function pointer to execute the task
    struct Task *next;     // Pointer to the next task in the list
} Task;

/**
 * Create a new task node.
 *
 * @param id The unique task ID.
 * @param priority The priority level of the task.
 * @param deadline The deadline timestamp for the task.
 * @param execute Function pointer to execute the task.
 * @return Pointer to the newly created task, or NULL if memory allocation fails.
 */
Task* create_task(int id, int priority, long deadline, void (*execute)(void)) {
    Task *new_task = (Task*)malloc(sizeof(Task));
    if (!new_task) return NULL;

    new_task->id = id;
    new_task->priority = priority;
    new_task->deadline = deadline;
    new_task->execute = execute;
    new_task->next = NULL;

    return new_task;
}

/**
 * Filter tasks based on priority and deadline, creating a new task list.
 *
 * @param tasks Pointer to an array of Task structs.
 * @param num_tasks The number of tasks in the input array.
 * @param min_priority Minimum priority level for tasks to be included.
 * @param current_timestamp Current timestamp against which deadlines are checked.
 * @return Pointer to the head of a new task list meeting criteria, or NULL if memory allocation fails.
 */
Task* filter_tasks(Task *tasks[], int num_tasks, int min_priority, long current_timestamp) {
    if (!tasks || num_tasks <= 0) return NULL;

    Task *head = NULL;
    Task **last_ptr = &head;

    for (int i = 0; i < num_tasks; ++i) {
        Task *current_task = tasks[i];

        if (current_task->priority >= min_priority && current_task->deadline > current_timestamp) {
            Task *new_node = create_task(current_task->id, current_task->priority, 
                                         current_task->deadline, current_task->execute);
            if (!new_node) {
                // Free already allocated nodes in case of error
                while (head != NULL) {
                    Task *temp = head;
                    head = head->next;
                    free(temp);
                }
                return NULL;  // Memory allocation failure
            }

            *last_ptr = new_node;
            last_ptr = &new_node->next;
        }
    }

    return head;
}

// Example usage of the filter_tasks function
void example_execute_function(void) {
    printf("Executing task...\n");
}
