use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use serde_json::json;
use reqwest;
use std::time::Instant;
use tokio::sync::mpsc;
use tokio::task;
use log::{info, warn};

struct CompilationResult {
    file_path: String,
    success: bool,
    warnings: Vec<String>,
    duration_ms: u64,
}

async fn compile_file(file_path: &str, language: &str) -> Option<CompilationResult> {
    let start_time = Instant::now();

    // Example command selection based on language
    let mut cmd = match language.to_lowercase().as_str() {
        "rust" => Command::new("cargo").arg("build"),
        "c" => Command::new("gcc").args(&[file_path, "-o", &file_path.replace(".c", ".out")]),
        "python" => Command::new("python3").arg(file_path),
        _ => return None,
    };

    cmd.arg("-v").stdout(Stdio::null()).stderr(Stdio::piped());

    match cmd.status() {
        Ok(status) if status.success() => {
            let duration = start_time.elapsed().as_millis();
            Some(CompilationResult {
                file_path: file_path.to_string(),
                success: true,
                warnings: vec![], // Capture actual warnings from stderr
                duration_ms: duration,
            })
        }
        Ok(status) => {
            warn!("Compilation failed for {:?}, status: {:?}", file_path, status);
            let duration = start_time.elapsed().as_millis();
            Some(CompilationResult {
                file_path: file_path.to_string(),
                success: false,
                warnings: vec![], // Capture actual errors from stderr
                duration_ms: duration,
            })
        }
        Err(e) => {
            warn!("Error compiling {:?}: {:?}", file_path, e);
            None
        }
    }
}

async fn compile_files_in_parallel(files: Vec<(String, String)>) -> HashMap<String, CompilationResult> {
    let (tx, mut rx) = mpsc::channel(32);

    for (file_path, language) in files {
        let tx = tx.clone();
        task::spawn(async move {
            if let Some(result) = compile_file(&file_path, &language).await {
                tx.send((file_path, result)).await.unwrap();
            }
        });
    }

    drop(tx);

    let mut results: HashMap<String, CompilationResult> = HashMap::new();

    while let Some((file_path, result)) = rx.recv().await {
        results.insert(file_path, result);
    }

    results
}

async fn compile_from_vcs(repo_url: &str) -> Vec<(String, String)> {
    // Example fetching logic (simplified)
    let output = Command::new("git")
        .arg("clone")
        .arg(repo_url)
        .output()
        .expect("failed to clone repository");

    if !output.status.success() {
        warn!("Failed to clone repo: {}", String::from_utf8_lossy(&output.stderr));
        return vec![];
    }

    // Example logic to list files and determine language
    let file_list = vec![("src/main.rs".to_string(), "rust".to_string())];
    file_list
}

async fn main() {
    env_logger::init();

    info!("Starting compilation process...");

    let repo_url = "https://github.com/user/repo.git";
    let files_to_compile = compile_from_vcs(repo_url).await;

    let results = compile_files_in_parallel(files_to_compile).await;

    // Output results in JSON format
    println!("{}", json!({ "results": results }).to_string());

    info!("Compilation process completed.");
}

#[tokio::main]
async fn main() {
