```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <vector>
#include <queue>
#include <memory>
#include <condition_variable>
#include <openssl/ssl.h>
#include <openssl/err.h>
#include "sandesh_client_https.h" // Assume this is a custom header for Sandesh HTTPS client

class InterfaceTableTestDouble {
public:
    virtual std::string FindVmUuidFromMetadataIp(const std::string& ip) = 0;
};

class TestInterfaceTable : public InterfaceTableTestDouble {
public:
    std::string FindVmUuidFromMetadataIp(const std::string& ip) override {
        // Simulate different network conditions and test edge cases
        if (ip == "192.168.1.100") return "vm-uuid-123";
        else if (ip == "10.0.0.200") throw std::runtime_error("Network error");
        else return "";
    }
};

class ConnectionPool {
public:
    ConnectionPool(size_t poolSize);
    ~ConnectionPool();

    std::shared_ptr<SSL_CTX> GetConnection();
    void ReturnConnection(std::shared_ptr<SSL_CTX> conn);

private:
    std::queue<std::shared_ptr<SSL_CTX>> connections_;
    std::mutex mtx_;
    std::condition_variable cv_;
};

ConnectionPool::ConnectionPool(size_t poolSize) {
    SSL_library_init();
    OpenSSL_add_all_algorithms();
    SSL_load_error_strings();

    const SSL_METHOD* method = TLS_client_method();
    auto ctx = std::make_shared<SSL_CTX>(SSL_CTX_new(method));

    for (size_t i = 0; i < poolSize; ++i) {
        connections_.push(ctx);
    }
}

ConnectionPool::~ConnectionPool() {
    while (!connections_.empty()) {
        connections_.pop();
    }
}

std::shared_ptr<SSL_CTX> ConnectionPool::GetConnection() {
    std::unique_lock<std::mutex> lock(mtx_);
    cv_.wait(lock, [this] { return !connections_.empty(); });

    auto conn = connections_.front();
    connections_.pop();
    return conn;
}

void ConnectionPool::ReturnConnection(std::shared_ptr<SSL_CTX> conn) {
    std::lock_guard<std::mutex> lock(mtx_);
    connections_.push(conn);
    cv_.notify_one();
}

class SandeshClientManager {
public:
    SandeshClientManager(size_t poolSize);

    void FetchMetadata(const std::string& serverUrl, const TestInterfaceTable& testTable);
    void Shutdown();

private:
    void WorkerThreadFunction();
    void LogRequestResult(bool success, const std::string& details);

    ConnectionPool connPool_;
    std::vector<std::thread> workers_;
    bool stop_ = false;
};

SandeshClientManager::SandeshClientManager(size_t poolSize) : connPool_(poolSize) {
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        workers_.emplace_back(&SandeshClientManager::WorkerThreadFunction, this);
    }
}

void SandeshClientManager::FetchMetadata(const std::string& serverUrl, const TestInterfaceTable& testTable) {
    auto conn = connPool_.GetConnection();
    try {
        // Assume SandeshClientHttps is a custom class handling HTTPS requests
        SandeshClientHttps client(conn, serverUrl);
        bool success = client.FetchData(); // Simplified for example

        std::string vmUuid;
        if (success) {
            vmUuid = testTable.FindVmUuidFromMetadataIp("example-ip");
            LogRequestResult(true, "Success: VM UUID " + vmUuid);
        } else {
            throw std::runtime_error("FetchData failed");
        }
    } catch (const std::exception& e) {
        LogRequestResult(false, e.what());
    }

    connPool_.ReturnConnection(conn);
}

void SandeshClientManager::WorkerThreadFunction() {
    while (!stop_) {
        // Fetch tasks from a task queue and process them
    }
}

void SandeshClientManager::LogRequestResult(bool success, const std::string& details) {
    if (success) {
        std::cout << "Request successful: " << details << std::endl;
    } else {
        std::cerr << "Request failed: " << details << std::endl;
    }
}

void SandeshClientManager::Shutdown() {
    stop_ = true;
    for (auto& worker : workers_) {
        if (worker.joinable()) {
            worker.join();
        }
    }
}

int main() {
    try {
        size_t poolSize = 10; // Example pool size
        SandeshClientManager manager(poolSize);

        TestInterfaceTable testTable;

        // Simulate fetching metadata concurrently
        for (int i = 0; i < 100; ++i) { // Assume 100 concurrent requests
            std::thread(&SandeshClientManager::FetchMetadata, &manager, "https://metadata-server.example.com", testTable).detach();
        }

        std::this_thread::sleep_for(std::chrono::seconds(10)); // Let threads run

        manager.Shutdown();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
