import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.concurrent.ConcurrentHashMap;
import javax.imageio.ImageIO;

public class ImageProcessingTool {

    public enum InterpolationMethod {
        NEAREST_NEIGHBOR, BILINEAR, BICUBIC
    }

    private static final ConcurrentHashMap<String, BufferedImage> imageCache = new ConcurrentHashMap<>();

    interface Filter {
        void applyFilter(BufferedImage image);
    }

    public static class Builder {
        private String imagePath;
        private int targetWidth;
        private int targetHeight;
        private InterpolationMethod interpolationMethod;

        public Builder setImagePath(String imagePath) {
            this.imagePath = imagePath;
            return this;
        }

        public Builder setTargetSize(int width, int height) {
            this.targetWidth = width;
            this.targetHeight = height;
            return this;
        }

        public Builder setInterpolationMethod(InterpolationMethod method) {
            this.interpolationMethod = method;
            return this;
        }

        public ImageProcessingTool build() {
            return new ImageProcessingTool(imagePath, targetWidth, targetHeight, interpolationMethod);
        }
    }

    private final String imagePath;
    private final int targetWidth;
    private final int targetHeight;
    private final InterpolationMethod interpolationMethod;

    private ImageProcessingTool(String imagePath, int targetWidth, int targetHeight, InterpolationMethod interpolationMethod) {
        this.imagePath = imagePath;
        this.targetWidth = targetWidth;
        this.targetHeight = targetHeight;
        this.interpolationMethod = interpolationMethod;
    }

    public BufferedImage resizeImage() throws IOException {
        synchronized (imageCache) {
            if (imageCache.containsKey(imagePath)) {
                return imageCache.get(imagePath);
            }

            BufferedImage originalImage = ImageIO.read(new File(imagePath));
            int type = determineType(originalImage);

            int newWidth, newHeight;
            if ((double) targetWidth / targetHeight > (double) originalImage.getWidth() / originalImage.getHeight()) {
                newWidth = originalImage.getWidth();
                newHeight = (int) (((double) originalImage.getHeight() * targetWidth) / originalImage.getWidth());
            } else {
                newWidth = (int) (((double) originalImage.getWidth() * targetHeight) / originalImage.getHeight());
                newHeight = originalImage.getHeight();
            }

            BufferedImage resizedImage = new BufferedImage(newWidth, newHeight, type);
            Graphics2D g = resizedImage.createGraphics();

            switch (interpolationMethod) {
                case NEAREST_NEIGHBOR:
                    g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
                            RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
                    break;
                case BILINEAR:
                    g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
                    break;
                case BICUBIC:
                    g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
                    break;
            }

            g.drawImage(originalImage, 0, 0, newWidth, newHeight, null);
            g.dispose();

            imageCache.put(imagePath, resizedImage);

            return resizedImage;
        }
    }

    private int determineType(BufferedImage original) {
        if (original.getColorModel().hasAlpha()) {
            return BufferedImage.TYPE_INT_ARGB;
        } else {
            return BufferedImage.TYPE_INT_RGB;
        }
    }

    public void applyFilter(Filter filter) throws IOException {
        synchronized (imageCache) {
            BufferedImage image = resizeImage();
            filter.applyFilter(image);
            // Cache the filtered image
            imageCache.put(imagePath, image);
        }
    }

    private static class ExternalFilter implements Filter {
        @Override
        public void applyFilter(BufferedImage image) {
            // Placeholder for external filter logic
        }
    }

    public static void main(String[] args) throws IOException {
        ImageProcessingTool tool = new Builder()
                .setImagePath("path/to/image.jpg")
                .setTargetSize(800, 600)
                .setInterpolationMethod(InterpolationMethod.BICUBIC)
                .build();

        BufferedImage resizedImage = tool.resizeImage();
        // Save or display the resized image as needed
    }
}
