// JavaScript function to dynamically render footer scripts

const scriptCache = new Map();
const cacheExpirationTime = 300000; // Cache expiration time in milliseconds (5 minutes)

function fetchScriptsFromAPI(endpoint) {
    return fetch(endpoint)
        .then(response => response.json())
        .catch(error => {
            console.error('Error fetching scripts from API:', error);
            throw error;
        });
}

function loadScript(script, index, totalScripts) {
    return new Promise((resolve, reject) => {
        const scriptElement = document.createElement('script');
        scriptElement.type = script.type || 'text/javascript';
        scriptElement.src = script.src || '';

        if (script.code) {
            scriptElement.innerHTML = script.code;
        }

        // Loading spinner logic
        showLoadingSpinner(index, totalScripts);

        scriptElement.onload = () => {
            hideLoadingSpinner();
            resolve();
        };

        scriptElement.onerror = (error) => {
            console.error('Error loading script:', error);
            reject(error);
        };

        document.body.appendChild(scriptElement);
    });
}

function renderFooter(scripts) {
    const validScripts = scripts.filter(script => script.code || script.src);
    return Promise.all(validScripts.map((script, index) =>
        loadScript(script, index + 1, validScripts.length)
    )).then(() => `
        <footer>
            ${validScripts.map((script, idx) => `<script key="${idx}" type="${script.type || 'text/javascript'}" innerHTML="${script.code || ''}"></script>`).join('')}
        </footer>`
    );
}

function showLoadingSpinner(current, total) {
    console.log(`Loading script ${current} of ${total}`);
    // Implement spinner display logic
}

function hideLoadingSpinner() {
    console.log('Hiding loading spinner');
    // Implement spinner hiding logic
}

// Example usage:
fetchScriptsFromAPI('/api/scripts')
    .then(renderFooter)
    .catch(error => console.error('Failed to render footer:', error));

