```csharp
// C# Method for parameterized SQL command execution

using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class DatabaseHelper
{
    public IDataReader ExecuteParameterizedQuery(string connectionString, string sqlCommandText, List<object> parameters)
    {
        using (var connection = new SqlConnection(connectionString))
        {
            connection.Open();
            using (var command = new SqlCommand(sqlCommandText, connection))
            {
                AddParameters(command, parameters);
                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
        }
    }

    private void AddParameters(SqlCommand command, List<object> parameters)
    {
        for (int i = 0; i < parameters.Count; i++)
        {
            var parameter = command.Parameters.Add($"@param{i}", SqlDbType.Variant); // Adjust type as necessary
            parameter.Value = parameters[i];
        }
    }

    // Example method to handle resource updates with optimistic concurrency control
    public void UpdateResource(string connectionString, int resourceId, Dictionary<string, object> updatedData, int? versionNumber)
    {
        using (var connection = new SqlConnection(connectionString))
        {
            connection.Open();
            using (var transaction = connection.BeginTransaction())
            {
                try
                {
                    var commandText = "UPDATE Resources SET ... WHERE Id = @ResourceId AND Version = @Version"; // Define query appropriately

                    var parameters = new List<object>
                    {
                        resourceId,
                        versionNumber
                    };

                    foreach (var data in updatedData)
                    {
                        parameters.Add(data.Value);
                        commandText += $" , {data.Key} = @{data.Key}";
                    }

                    using (var command = new SqlCommand(commandText, connection, transaction))
                    {
                        AddParameters(command, parameters);
                        int rowsAffected = command.ExecuteNonQuery();

                        if (rowsAffected == 0)
                        {
                            throw new InvalidOperationException("Concurrency conflict or resource not found.");
                        }

                        transaction.Commit();
                    }
                }
                catch
                {
                    transaction.Rollback();
                    throw;
                }
            }
        }
    }
}
