// Utility function to log errors
function logError(message) {
  console.error(message);
}

// Cache management functions
const scriptCache = new Map();

function isScriptCached(scriptId) {
  const cachedData = scriptCache.get(scriptId);
  return cachedData && Date.now() < cachedData.expiry;
}

function cacheScript(scriptId, scriptCode, version) {
  const expiryTime = 5 * 60 * 1000; // Cache expiry time: 5 minutes
  scriptCache.set(scriptId, { code: scriptCode, expiry: Date.now() + expiryTime, version });
}

function getCachedScript(scriptId) {
  return scriptCache.get(scriptId)?.code;
}

// Function to fetch scripts from an external API
async function fetchScripts(apiEndpoint, retryCount = 3) {
  try {
    const response = await fetch(apiEndpoint);
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

    const data = await response.json();
    return data.scripts || [];
  } catch (error) {
    logError(error.message);

    if (retryCount > 0) {
      setTimeout(() => fetchScripts(apiEndpoint, retryCount - 1), 1000);
    }

    return [];
  }
}

// Function to render scripts into HTML
function renderScripts(scriptsArray) {
  const scriptElements = scriptsArray.map((script, index) => {
    if (!script.code || !script.id) return null;

    return `<script key="${index}" ${script.type ? `type="${script.type}"` : ''} ${script.src ? `src="${script.src}"` : ''}>
              ${script.code}
            </script>`;
  }).filter(Boolean);

  return scriptElements.join('\n');
}

// Function to dynamically load scripts
async function loadScripts(apiEndpoint) {
  const spinner = document.createElement('div');
  spinner.textContent = 'Loading...';
  document.body.appendChild(spinner);

  try {
    const scriptsArray = await fetchScripts(apiEndpoint);

    const renderedScriptsHTML = renderScripts(scriptsArray);

    // Append the scripts to the footer
    const footerElement = document.getElementById('footer') || document.createElement('div');
    footerElement.id = 'footer';
    footerElement.innerHTML = renderedScriptsHTML;

    document.body.appendChild(footerElement);

    spinner.remove();
  } catch (error) {
    logError(`Failed to load scripts: ${error.message}`);
    spinner.textContent = 'Failed to load scripts. Please try again later.';
  }
}

// Function to clean up unused script elements
function cleanupUnusedScripts() {
  const allScriptElements = document.querySelectorAll('script[key]');
  allScriptElements.forEach(script => {
    const key = parseInt(script.getAttribute('key'), 10);
    if (isNaN(key) || !isScriptCached(`script_${key}`)) {
      script.remove();
    }
  });
}

// Main function to manage the dynamic footer
async function setupDynamicFooter(apiEndpoint) {
  await loadScripts(apiEndpoint);

  // Periodically clean up unused scripts
  setInterval(cleanupUnusedScripts, 10 * 60 * 1000); // Every 10 minutes

  window.addEventListener('beforeunload', cleanupUnusedScripts);
}

// Initiate script loading with API endpoint
setupDynamicFooter('/api/scripts');
