# Semaphore for controlling concurrent deployments
deployment_semaphore = threading.Semaphore(2)

def validate_manifest(manifest):
    # Basic validation logic here
    if 'apiVersion' not in manifest or 'kind' not in manifest:
        raise ValueError("Invalid manifest: Missing required fields.")
    # Add more complex validations as needed

@retry(wait_exponential_multiplier=1000, wait_exponential_max=10000, stop_max_attempt_number=5)
def deploy_application(manifest_path):
    with deployment_semaphore:
        config.load_kube_config()
        api_instance = client.AppsV1Api()

        with open(manifest_path) as file:
            manifest = yaml.safe_load(file)

        validate_manifest(manifest)

        # Perform the Kubernetes deployment
        try:
            api_response = api_instance.create_namespaced_deployment(
                body=manifest,
                namespace="default"
            )
            print(f"Deployment created. Status='{api_response.status}'")
            monitor_deployment_status(api_response.metadata.name, manifest_path)

        except client.exceptions.ApiException as e:
            if e.status == 409:  # Conflict - Resource already exists
                api_instance.patch_namespaced_deployment(
                    name=manifest['metadata']['name'],
                    namespace="default",
                    body=manifest,
                )
                print("Deployment updated.")
            else:
                raise

def monitor_deployment_status(deployment_name, manifest_path):
    config.load_kube_config()
    api_instance = client.AppsV1Api()

    while True:
        deployment = api_instance.read_namespaced_deployment(
            name=deployment_name,
            namespace="default"
        )

        if deployment.status.ready_replicas == deployment.spec.replicas:
            print("Deployment succeeded.")
            break

        # Example of a simple cleanup mechanism
        elif deployment.status.failed_replicas > 0:
            print("Deployment failed. Cleaning up...")
            api_instance.delete_namespaced_deployment(
                name=deployment_name,
                namespace="default",
                body=client.V1DeleteOptions(propagation_policy='Foreground', grace_period_seconds=5),
            )
            break

        # Check the deployment status every few seconds
