    }

    LogEntry entry;
    while (fscanf(file, "%[^,],%f,%d,%d,%[^\n]\\n", entry.timestamp,
                  &entry.response_time, &entry.error_rate,
                  &entry.request_count, entry.severity) != EOF) {

        if(strcmp(entry.severity, "Critical") == 0 || entry.error_rate > 50) {
            printf("High severity event at %s with error rate: %d\n", entry.timestamp, entry.error_rate);
        }
    }

    fclose(file);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        printf("Usage: %s <log_file>\n", argv[0]);
        return 1;
    }
    analyze_log(argv[1]);
}
