def compile_and_run_c(log_file):
    # Write the C code to a temporary file
    c_filename = "log_analysis.c"
    with open(c_filename, 'w') as c_file:
        c_file.write(log_analysis_source)

    # Compile and execute the C program
    subprocess.run(["gcc", c_filename, "-o", "log_analysis"])
    subprocess.run(["./log_analysis", log_file])
    os.remove(c_filename)
    os.remove("log_analysis")

def analyze_logs(log_file):
    if os.path.exists(log_file):
        compile_and_run_c(log_file)
    else:
        print(f"Log file {log_file} does not exist.")

