using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

public class FileMetadataProcessor
{
    private readonly string _directoryPath;
    private readonly long _minFileSize;
    private readonly long _maxFileSize;

    public FileMetadataProcessor(string directoryPath, long minFileSize, long maxFileSize)
    {
        if (!Directory.Exists(directoryPath))
            throw new ArgumentException("Invalid directory path");

        ValidateSizeRange(minFileSize, maxFileSize);

        _directoryPath = directoryPath;
        _minFileSize = minFileSize;
        _maxFileSize = maxFileSize;

        LogActivity($"Initialized with size range: {_minFileSize} - {_maxFileSize}");
    }

    private void ValidateSizeRange(long minFileSize, long maxFileSize)
    {
        if (minFileSize > maxFileSize)
            throw new ArgumentException("Minimum file size must be less than or equal to maximum file size");
    }

    public IEnumerable<string> GetFilePaths(bool includeSubdirectories = false)
    {
        var searchOption = includeSubdirectories ? SearchOption.AllDirectories : SearchOption.TopDirectoryOnly;

        try
        {
            return Directory.EnumerateFiles(_directoryPath, "*.*", searchOption);
        }
        catch (Exception ex)
        {
            LogError($"Error retrieving file paths: {ex.Message}");
            yield break;
        }
    }

    public IEnumerable<FileMetadata> GetFileMetadatas(Func<FileMetadata, bool> filter = null, int batchSize = 100)
    {
        var files = GetFilePaths().Where(filePath => 
            _minFileSize <= new FileInfo(filePath).Length && new FileInfo(filePath).Length <= _maxFileSize);

        return ProcessFilesInBatches(files, filter, batchSize);
    }

    private IEnumerable<FileMetadata> ProcessFilesInBatches(IEnumerable<string> filePaths, Func<FileMetadata, bool> filter, int batchSize)
    {
        var fileMetadatas = from filePath in filePaths
                            select new FileMetadata(filePath);

        return fileMetadatas.AsParallel()
            .AsOrdered()
            .Batch(batchSize)
            .SelectMany(batch => batch.AsParallel())
            .Where(filter ?? (fm => true))
            .ToList();
    }

    public override string ToString()
    {
        return $"Size Range: [{_minFileSize / 1024}, {_maxFileSize / 1024}] KB";
    }

    private void LogActivity(string message)
    {
        // External logging integration
        Console.WriteLine($"[INFO] {message}");
    }

    private void LogError(string message)
    {
        // External logging integration
        Console.Error.WriteLine($"[ERROR] {message}");
    }
}

public class FileMetadata
{
    public string FilePath { get; }
    public long SizeBytes => new FileInfo(FilePath).Length;
    public DateTime CreationDate => new FileInfo(FilePath).CreationTimeUtc;
    public DateTime LastModifiedDate => new FileInfo(FilePath).LastWriteTimeUtc;

    public FileMetadata(string filePath)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException("File not found", filePath);

        FilePath = filePath;
    }

    public override string ToString()
    {
        return $"{Path.GetFileName(FilePath)} - {SizeBytes} bytes, Created: {CreationDate}, Last Modified: {LastModifiedDate}";
    }
}

public static class EnumerableExtensions
{
    public static IEnumerable<IEnumerable<T>> Batch<T>(this IEnumerable<T> source, int size)
    {
        using (var enumerator = source.GetEnumerator())
            while (enumerator.MoveNext())
                yield return YieldBatchElements(enumerator, size - 1);
    }

    private static IEnumerable<T> YieldBatchElements<T>(IEnumerator<T> source, int count)
    {
        yield return source.Current;
        for (int i = 0; i < count && source.MoveNext(); i++)
            yield return source.Current;
    }
}
```

This code provides a `FileMetadataProcessor` class that meets the specified requirements. It includes methods to retrieve and process file metadata within a given size range, supports batch processing, and uses parallelism for efficiency. The class also integrates basic logging functionality for activity tracking and error reporting.

