using System;
using System.Collections.Generic;
using System.Data;
using System.Diagnostics;
using System.IO;
using System.Security.Cryptography;
using MySql.Data.MySqlClient; // Ensure appropriate MySQL connector is installed.

public class DynamicQueryExecutor
{
    private readonly string _connectionString;
    private const int MaxRetries = 3;

    public DynamicQueryExecutor(string connectionString)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
    }

    public IDataReader ExecuteDynamicQuery(string sqlTemplate, List<object> values, EncryptionMode encryptionMode)
    {
        var retries = 0;
        while (retries < MaxRetries)
        {
            try
            {
                using var connection = new MySqlConnection(_connectionString);
                connection.Open();

                using var command = new MySqlCommand(sqlTemplate, connection);
                AddParameters(command, values);

                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
            catch (MySqlException ex) when (IsTransientError(ex))
            {
                LogError(ex);
                retries++;
                if (retries >= MaxRetries)
                    throw;

                // Optional: Introduce a delay before retrying
                System.Threading.Thread.Sleep(1000 * retries);
            }
        }

        return null; // Should never reach here due to exception thrown on max retries.
    }

    private void AddParameters(MySqlCommand command, List<object> values)
    {
        for (int i = 0; i < values.Count; i++)
        {
            var param = new MySqlParameter($"@p{i}", values[i] ?? DBNull.Value);
            command.Parameters.Add(param);
        }
    }

    private bool IsTransientError(MySqlException ex)
    {
        // Customize this method based on known transient error codes for your MySQL version.
        return ex.Number == 1205 || ex.Number == 1099;
    }

    private void LogError(Exception ex)
    {
        Debug.WriteLine($"[{DateTime.Now}] Error: {ex.Message}");
    }

    public IntPtr CreateCipher(EncryptionMode mode, string key = null)
    {
        IntPtr cipherPtr = IntPtr.Zero;

        try
        {
            using var des = new TripleDESCryptoServiceProvider();

            switch (mode)
            {
                case EncryptionMode.ECB:
                    cipherPtr = EVP_CIPHER_create("des-ecb");
                    break;
                case EncryptionMode.EDE:
                    cipherPtr = EVP_CIPHER_create("des-ede3");
                    break;
                case EncryptionMode.EDE3:
                    cipherPtr = EVP_CIPHER_create("des-ede3-cbc");
                    break;
                case EncryptionMode.CFB:
                    cipherPtr = EVP_CIPHER_create("des-cfb128");
                    break;
                case EncryptionMode.NullEncryption:
                    cipherPtr = IntPtr.Zero; // No encryption.
                    break;
            }

            if (cipherPtr != IntPtr.Zero && key != null)
            {
                des.Key = Convert.FromBase64String(key);
                des.Mode = CipherMode.ECB; // Default mode for TripleDES, modify per mode.
            }
        }
        catch (Exception ex)
        {
            LogError(ex);
        }

        return cipherPtr;
    }

    [UnmanagedFunctionPointer(CallingConvention.Cdecl)]
    private delegate IntPtr EVP_CIPHER_create(string name);

    public enum EncryptionMode
    {
        ECB,
        EDE,
        EDE3,
        CFB,
        NullEncryption
    }
}

