```csharp
using System;
using UnityEngine;

public class ValueGenerator : MonoBehaviour
{
    private int minInt, maxInt;
    private float minFloat, maxFloat;
    private ObjectPool arrayPool;

    public ValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");

        minInt = minValue;
        maxInt = maxValue;
        arrayPool = new ObjectPool(ArrayPoolSize);
        UnityEngine.Random.InitState(System.DateTime.Now.Millisecond);
    }

    public float GenerateRandomFloat(float lowerBound = 0.0f, float upperBound = 1.0f)
    {
        return Mathf.Lerp(lowerBound, upperBound, UnityEngine.Random.value);
    }

    public int GenerateRandomInt()
    {
        return UnityEngine.Random.Range(minInt, maxInt + 1);
    }

    public int[] GenerateIntArray(int size)
    {
        var array = arrayPool.GetArray(size);
        for (int i = 0; i < size; i++)
        {
            array[i] = GenerateRandomInt();
        }
        return array;
    }

    public int[] GenerateWeightedRandomIntArray(int size, float[] weights)
    {
        if (weights.Length != maxInt - minInt + 1)
            throw new ArgumentException("Weights length must match the range of integers.");

        var array = arrayPool.GetArray(size);
        for (int i = 0; i < size; i++)
        {
            int value = Mathf.RoundToInt(UnityEngine.Random.Range(0f, weights.Sum()));
            array[i] = minInt + value;
        }
        return array;
    }

    public float[] GenerateFloatArray(int size)
    {
        var array = arrayPool.GetArray(size);
        for (int i = 0; i < size; i++)
        {
            array[i] = UnityEngine.Random.value * (maxFloat - minFloat) + minFloat;
        }
        return array;
    }

    public float[] GenerateGaussianFloatArray(int size, float mean, float stdDev)
    {
        var array = arrayPool.GetArray(size);
        for (int i = 0; i < size; i++)
        {
            array[i] = Mathf.Max(minFloat, Mathf.Min(maxFloat, UnityEngine.Random.Gaussian(mean, stdDev)));
        }
        return array;
    }

    public override string ToString()
    {
        return $"Range: {minInt} to {maxInt}, Float Bounds: {minFloat} to {maxFloat}";
    }

    private void OnDestroy()
    {
        foreach (var arr in arrayPool)
            Destroy(arr);
    }

    public void SerializeState(SerializationInfo info)
    {
        info.AddValue("MinInt", minInt);
        info.AddValue("MaxInt", maxInt);
        info.AddValue("MinFloat", minFloat);
        info.AddValue("MaxFloat", maxFloat);
    }

    public void DeserializeState(SerializationInfo info)
    {
        minInt = (int)info.GetValue("MinInt", typeof(int));
        maxInt = (int)info.GetValue("MaxInt", typeof(int));
        minFloat = (float)info.GetValue("MinFloat", typeof(float));
        maxFloat = (float)info.GetValue("MaxFloat", typeof(float));
    }

    public int[] GenerateSequenceWithStepSize(int size, int step)
    {
        var sequence = new int[size];
        for (int i = 0; i < size; i++)
        {
            sequence[i] = minInt + i * step;
            if (sequence[i] > maxInt) break;
        }
        return sequence;
    }

    private class ObjectPool
    {
        private readonly Stack<int[]> pool;

        public ObjectPool(int initialSize)
        {
            pool = new Stack<int[]>();
            for (int i = 0; i < initialSize; i++)
                pool.Push(new int[initialSize]);
        }

        public int[] GetArray(int size)
        {
            if (pool.Count > 0)
                return pool.Pop();
            else
                return new int[size];
        }

        public void ReturnArray(int[] array)
        {
            pool.Push(array);
        }
    }

    private static int ArrayPoolSize => 10;
}
