#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

void logOperation(const char *original, size_t sizeLimit, const char *trimmed, int slashAppended) {
    FILE *logFile = fopen("operation_log.txt", "a");
    if (logFile == NULL) return;

    time_t now;
    time(&now);
    char *timestamp = ctime(&now);

    timestamp[strcspn(timestamp, "\n")] = '\0'; // Remove newline from timestamp

    fprintf(logFile, "[%s] Original: '%s', Size Limit: %zu, Trimmed Length: %zu, Slash Appended: %d\n",
            timestamp, original, sizeLimit, strlen(trimmed), slashAppended);

    fclose(logFile);
}

char *trimAndAppendSlash(const char *input, size_t sizeLimit) {
    if (sizeLimit == 0) return NULL;

    // Trim leading whitespace
    const char *start = input;
    while (*start && isspace((unsigned char)*start)) start++;

    // Trim trailing whitespace
    const char *end = start + strlen(start) - 1;
    while (end > start && isspace((unsigned char)*end)) end--;

    size_t trimmedLength = end >= start ? end - start + 1 : 0;

    if (trimmedLength == 0 || trimmedLength >= sizeLimit) {
        logOperation(input, sizeLimit, "", 0);
        return NULL;
    }

    // Allocate memory for the result
    char *result = malloc(trimmedLength + 2); // +1 for null terminator, +1 for slash
    if (result == NULL) return NULL;

    strncpy(result, start, trimmedLength);
    result[trimmedLength] = '\0';

    int slashAppended = 0;
    if (trimmedLength + 1 < sizeLimit) {
        result[trimmedLength] = '/';
        result[trimmedLength + 1] = '\0';
        slashAppended = 1;
    }

    logOperation(input, sizeLimit, result, slashAppended);
    return result;
}
```

