```python
from collections import defaultdict, deque
import requests

class ProjectDependencyGraph:
    def __init__(self):
        self.graph = defaultdict(list)
        self.cache = {}
        # Assuming the project management API base URL is provided
        self.api_base_url = "https://api.projectmanagement.com/tasks"

    def build_graph(self, dag):
        for task, dependencies in dag.items():
            for dep in dependencies:
                self.graph[task].append(dep)

    def fetch_task_metadata(self, task_id):
        response = requests.get(f"{self.api_base_url}/{task_id}")
        if response.status_code == 200:
            return response.json()
        else:
            return None

    def detect_cycle_util(self, v, visited, rec_stack):
        visited[v] = True
        rec_stack[v] = True

        for neighbor in self.graph[v]:
            if not visited[neighbor]:
                if self.detect_cycle_util(neighbor, visited, rec_stack):
                    return True
            elif rec_stack[neighbor]:
                return True

        rec_stack[v] = False
        return False

    def detect_cycle(self):
        visited = {key: False for key in self.graph}
        rec_stack = {key: False for key in self.graph}

        for node in self.graph:
            if not visited[node]:
                if self.detect_cycle_util(node, visited, rec_stack):
                    return True
        return False

    def find_executable_tasks(self, start_task, max_depth):
        # Check cache first
        if (start_task, max_depth) in self.cache:
            return self.cache[(start_task, max_depth)]

        # Detect cycle in the graph
        if self.detect_cycle():
            raise ValueError("Cycle detected in the dependency graph")

        executable_tasks = []
        queue = deque([(start_task, 0)])

        while queue:
            current_task, depth = queue.popleft()
            if depth > max_depth:
                continue

            for neighbor in self.graph[current_task]:
                # Fetch and print task metadata
                metadata = self.fetch_task_metadata(neighbor)
                if metadata is not None:
                    print(f"Task: {neighbor}, Description: {metadata.get('description')}, Duration: {metadata.get('duration')}")

                executable_tasks.append(neighbor)
                queue.append((neighbor, depth + 1))

        # Cache the result
        self.cache[(start_task, max_depth)] = executable_tasks

        return executable_tasks

# Example usage:
dag = {
    "A": ["B", "C"],
    "B": ["D"],
    "C": ["E"],
    "D": [],
    "E": []
}

graph_obj = ProjectDependencyGraph()
graph_obj.build_graph(dag)

try:
    tasks = graph_obj.find_executable_tasks("A", 2)
    print(tasks)
except ValueError as e:
    print(e)
