#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <pthread.h>

#define BUFFER_SIZE 4096

typedef void (*ProgressCallback)(size_t, size_t);

struct KeyStorage {
    char *key;
    pthread_mutex_t lock;
};

// Function prototypes
int FileSessionEncryptor(const char *file_path, const char *output_file_path, ProgressCallback progress_cb);
void LogAction(const char *message);
void EncryptFileChunk(EVP_CIPHER_CTX *ctx, unsigned char *input, size_t length, unsigned char **encrypted_data, int *len, struct KeyStorage *key_storage);
struct KeyStorage* CreateKeyStorage();
void DestroyKeyStorage(struct KeyStorage *key_storage);

int FileSessionEncryptor(const char *file_path, const char *output_file_path, ProgressCallback progress_cb) {
    FILE *input_file = fopen(file_path, "rb");
    if (!input_file) {
        LogAction("Error: Unable to open input file.");
        return -1;
    }

    FILE *output_file = fopen(output_file_path, "wb");
    if (!output_file) {
        LogAction("Error: Unable to create output file.");
        fclose(input_file);
        return -1;
    }

    struct KeyStorage *key_storage = CreateKeyStorage();
    pthread_mutex_init(&key_storage->lock, NULL);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        LogAction("Error: Unable to create cipher context.");
        fclose(input_file);
        fclose(output_file);
        DestroyKeyStorage(key_storage);
        return -1;
    }

    const EVP_CIPHER *cipher = EVP_aes_256_cbc(); // Default cipher, can be extended
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_BLOCK_SIZE];

    pthread_mutex_lock(&key_storage->lock);
    strncpy((char *)key, key_storage->key, sizeof(key));
    memcpy(iv, "1234567890123456", EVP_BLOCK_SIZE); // Example IV; replace with secure mechanism
    pthread_mutex_unlock(&key_storage->lock);

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv) <= 0) {
        LogAction("Error: Unable to initialize encryption.");
        fclose(input_file);
        fclose(output_file);
        EVP_CIPHER_CTX_free(ctx);
        DestroyKeyStorage(key_storage);
        return -1;
    }

    size_t total_size = 0;
    unsigned char *buffer = (unsigned char *)malloc(BUFFER_SIZE);
    if (!buffer) {
        LogAction("Error: Unable to allocate buffer.");
        fclose(input_file);
        fclose(output_file);
        EVP_CIPHER_CTX_free(ctx);
        DestroyKeyStorage(key_storage);
        return -1;
    }

    int len;
    unsigned char *encrypted_data = NULL;

    while (fread(buffer, 1, BUFFER_SIZE, input_file) > 0) {
        size_t bytes_read = fread(buffer, 1, BUFFER_SIZE, input_file);
        EncryptFileChunk(ctx, buffer, bytes_read, &encrypted_data, &len, key_storage);

        fwrite(encrypted_data, 1, len, output_file);
        total_size += len;

        free(encrypted_data);
        progress_cb(total_size, 0); // Assuming 0 as placeholder for total file size

        encrypted_data = NULL;
    }

    unsigned char final_block[256];
    int final_len;

    if (EVP_EncryptFinal_ex(ctx, final_block, &final_len) <= 0) {
        LogAction("Error: Unable to finalize encryption.");
    } else {
        fwrite(final_block, 1, final_len, output_file);
        total_size += final_len;
        progress_cb(total_size, 0);
    }

    free(buffer);
    EVP_CIPHER_CTX_free(ctx);
    fclose(input_file);
    fclose(output_file);
    DestroyKeyStorage(key_storage);

    return 0;
}

void EncryptFileChunk(EVP_CIPHER_CTX *ctx, unsigned char *input, size_t length, unsigned char **encrypted_data, int *len, struct KeyStorage *key_storage) {
    pthread_mutex_lock(&key_storage->lock);

    // Calculate buffer sizes and allocate memory
    *encrypted_data = (unsigned char *)malloc(length + EVP_MAX_BLOCK_LENGTH);
    if (!*encrypted_data) {
        LogAction("Error: Memory allocation failed for encryption.");
        pthread_mutex_unlock(&key_storage->lock);
        return;
    }

    if (EVP_EncryptUpdate(ctx, *encrypted_data, len, input, length) <= 0) {
        LogAction("Error: Encryption update failed.");
        free(*encrypted_data);
        *encrypted_data = NULL;
    }

    pthread_mutex_unlock(&key_storage->lock);
}

struct KeyStorage* CreateKeyStorage() {
    struct KeyStorage *ks = (struct KeyStorage *)malloc(sizeof(struct KeyStorage));
    if (!ks) return NULL;

    ks->key = "0123456789abcdef"; // Example key; replace with secure mechanism
    pthread_mutex_init(&ks->lock, NULL);

    return ks;
}

void DestroyKeyStorage(struct KeyStorage *key_storage) {
    if (key_storage) {
        free(key_storage->key);
        pthread_mutex_destroy(&key_storage->lock);
        free(key_storage);
    }
}

void LogAction(const char *message) {
    FILE *log_file = fopen("encryption_log.txt", "a");
    if (!log_file) return;

    fprintf(log_file, "%s\n", message);
    fclose(log_file);
}
