                                  {"ip_address", ip_address},
                                  {"device_type", device_type}};

    // Implement additional logging and error handling as needed.
}

bool UserSessionManager::validate_user_session(const std::string &session_id) const {
    std::lock_guard<std::mutex> lock(cache_mutex_);

    if (session_cache_.find(session_id) == session_cache_.end()) {
        LogAction("Session validation failed: Session not found.");
        return false;
    }

    // Validate against last activity, IP address, and device type.
    const auto &session_data = session_cache_[session_id];

    if (is_external_api_check_required(session_id)) {
        // Call external API for additional checks.
    }

    return true;
}

std::string UserSessionManager::session_to_json(const std::unordered_map<std::string, std::string> &session_data) const {
