import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Level;
import java.util.logging.Logger;

public class FileHashValidator {

    private static final Logger logger = Logger.getLogger(FileHashValidator.class.getName());
    private final int maxRetries;

    public FileHashValidator(int maxRetries) {
        this.maxRetries = maxRetries;
    }

    public Map<String, String> validateFileHashes(List<Path> filePaths) throws HashMismatchException {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        Map<String, String> hashMap = new ConcurrentHashMap<>();
        Map<String, Boolean> mismatchedFiles = new ConcurrentHashMap<>();

        for (Path path : filePaths) {
            executor.submit(() -> {
                try {
                    String md5Hash = computeMD5(path);
                    if (!validateWithExternalService(path.toString(), md5Hash)) {
                        synchronized (mismatchedFiles) {
                            mismatchedFiles.put(path.toString(), true);
                        }
                    } else {
                        hashMap.put(path.toString(), md5Hash);
                    }
                } catch (Exception e) {
                    logger.log(Level.SEVERE, "Error processing file: " + path, e);
                }
            });
        }

        executor.shutdown();
        while (!executor.isTerminated()) {
            // Wait for all tasks to finish
        }

        if (!mismatchedFiles.isEmpty()) {
            throw new HashMismatchException("Hash mismatch found in files: " + mismatchedFiles.keySet());
        }

        return hashMap;
    }

    private String computeMD5(Path path) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        try (InputStream fis = Files.newInputStream(path)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }
        byte[] digest = md.digest();
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private boolean validateWithExternalService(String filePath, String computedHash) {
        int attempts = 0;
        while (attempts < maxRetries) {
            try {
                // Simulate external service call
                String externalHash = ExternalHashingService.getMD5Hash(filePath);
                if (computedHash.equals(externalHash)) {
                    return true;
                }
                logger.warning("Hash mismatch for file: " + filePath + ", retrying...");
            } catch (IOException | InterruptedException e) {
                logger.log(Level.WARNING, "Network error or timeout during hash validation for file: " + filePath, e);
            }
            attempts++;
        }
        return false;
    }

    public static class HashMismatchException extends Exception {
        public HashMismatchException(String message) {
            super(message);
        }
    }

    // Mock external service
    private static class ExternalHashingService {
        static String getMD5Hash(String filePath) throws IOException, InterruptedException {
            // Simulate network call and potential delay
            Thread.sleep(100);
            return "dummyhash"; // Replace with actual API call logic
        }
    }
}
