// Function to send notifications to system administrators
async function notifyAdmin(subject, message) {
  const transporter = nodemailer.createTransport({
    service: 'gmail',
    auth: {
      user: 'your-email@gmail.com',
      pass: 'your-password'
    }
  });

  const mailOptions = {
    from: 'your-email@gmail.com',
    to: 'admin@example.com',
    subject,
    text: message
  };

  try {
    await transporter.sendMail(mailOptions);
  } catch (error) {
    logger.error('Error sending notification email', error);
  }
}

// Consolidated buffer for data aggregation
let consolidatedBuffer = [];

// Handle errors and notify admin
function handleError(error) {
  logger.error('Error in service: ', error);
  notifyAdmin('Service Error Notification', `An error occurred: ${error.message}`);
}

// HTTP Server to handle incoming requests
const httpServer = http.createServer((req, res) => {
  if (req.method === 'POST') {
    let body = '';
    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      consolidatedBuffer.push(body);
      res.end('Data received');
    });
  } else {
    res.statusCode = 404;
    res.end('Not Found');
  }
});

// WebSocket Server to handle incoming connections
const wsServer = new WebSocketServer({ server: httpServer });

wsServer.on('connection', socket => {
  socket.on('message', message => {
    consolidatedBuffer.push(message);
  });

  socket.on('error', error => handleError(error));
});

// MQTT Client to subscribe to topics and receive messages
const mqttClient = mqtt.connect('mqtt://broker.hivemq.com');

mqttClient.on('connect', () => {
  mqttClient.subscribe('topic/data', (err) => {
    if (err) handleError(err);
  });
});

mqttClient.on('message', (topic, message) => {
  consolidatedBuffer.push(message.toString());
});

mqttClient.on('error', error => handleError(error));

// Periodically consolidate and process data
setInterval(() => {
  try {
    // Process the consolidated buffer (e.g., batch save to DB)
    console.log(consolidatedBuffer);
    consolidatedBuffer = [];
  } catch (error) {
    handleError(error);
  }
}, 5000);

// Start HTTP Server
httpServer.listen(3000, () => {
  console.log('Data aggregation service running on port 3000');
});
