function authenticateUser($clientId, $clientSecret, $redirectUri, $provider) {
    session_start();

    // Configure provider-specific details
    $config = [
        'google' => [
            'authUrl' => 'https://accounts.google.com/o/oauth2/auth',
            'tokenUrl' => 'https://oauth2.googleapis.com/token',
            'userInfoUrl' => 'https://www.googleapis.com/oauth2/v1/userinfo',
            'scopes' => ['email', 'profile']
        ],
        'facebook' => [
            'authUrl' => 'https://www.facebook.com/dialog/oauth',
            'tokenUrl' => 'https://graph.facebook.com/oauth/access_token',
            'userInfoUrl' => 'https://graph.facebook.com/me?fields=id,name,email',
            'scopes' => ['email']
        ],
        'github' => [
            'authUrl' => 'https://github.com/login/oauth/authorize',
            'tokenUrl' => 'https://github.com/login/oauth/access_token',
            'userInfoUrl' => 'https://api.github.com/user',
            'scopes' => []
        ]
    ];

    $providerConfig = $config[$provider];

    if (!isset($_SESSION['oauth_access_token']) || !isset($_SESSION['oauth_expires_at'])) {
        // Redirect user to OAuth provider login page
        $authUrl = $providerConfig['authUrl'] . '?' .
            http_build_query([
                'response_type' => 'code',
                'client_id' => $clientId,
                'redirect_uri' => $redirectUri,
                'scope' => implode(' ', $providerConfig['scopes'])
            ]);

        header("Location: $authUrl");
        exit;
    }

    // Check if token has expired
    if (time() >= $_SESSION['oauth_expires_at']) {
        unset($_SESSION['oauth_access_token']);
        return authenticateUser($clientId, $clientSecret, $redirectUri, $provider);
