    def fetch_data_from_api(self, api_name, city, params=None):
        if api_name == "openweathermap":
            url = f"http://api.openweathermap.org/data/2.5/weather?q={city}&appid={self.api_keys['openweathermap']}"
        elif api_name == "weatherapi":
            url = f"https://api.weatherapi.com/v1/current.json?key={self.api_keys['weatherapi']}&q={city}"
