            if data:
                city = data['name'] if 'name' in data else data['location']['name']
                if city not in aggregated_data:
                    aggregated_data[city] = []
                aggregated_data[city].append(data)
        return aggregated_data

    def fetch_and_enqueue(self, api_name, city):
        data = self.fetch_data_from_api(api_name, city)
        if data:
            self.data_queue.put(data)

