# JavaScript function to copy specified bytes from buffered data chunks

const copyBufferedData = (dataChunks, byteCount) => {
  let resultBuffer = Buffer.alloc(byteCount);
  let bytesRead = 0;

  for (let chunk of dataChunks) {
    const toCopy = Math.min(chunk.length, byteCount - bytesRead);
    chunk.copy(resultBuffer, bytesRead, 0, toCopy);
    bytesRead += toCopy;

    if (bytesRead >= byteCount) break;
  }

  return resultBuffer.slice(0, bytesRead);
};


