using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Caching.Memory;

public class DataService
{
    private readonly ILogger<DataService> _logger;
    private readonly IMemoryCache _cache;
    private readonly string _filePath;

    public DataService(ILogger<DataService> logger, IMemoryCache cache, string filePath)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _filePath = filePath ?? throw new ArgumentNullException(nameof(filePath));
    }

    public async Task<T> LoadDataAsync<T>() where T : class
    {
        try
        {
            if (_cache.TryGetValue(_filePath, out T cachedData))
            {
                _logger.LogInformation("Data loaded from cache.");
                return cachedData;
            }

            using (FileStream fileStream = new FileStream(_filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite, bufferSize: 4096, useAsync: true))
            {
                BinaryFormatter formatter = new BinaryFormatter();

                T data = null;
                try
                {
                    data = (T)formatter.Deserialize(fileStream);
                }
                catch (SerializationException ex)
                {
                    _logger.LogError(ex, "Deserialization error for file {FilePath}.", _filePath);
                    throw;
                }
                catch (EndOfStreamException ex)
                {
                    _logger.LogWarning(ex, "File stream ended unexpectedly for {FilePath}. Possible partial corruption.", _filePath);
                    // Handle incomplete deserialization logic here
                }

                if (data != null)
                {
                    _cache.Set(_filePath, data, TimeSpan.FromMinutes(5));
                }

                return data;
            }
        }
        catch (IOException ex) when ((ex.HResult & 0x80004005) == 0x80004005) // E_ACCESSDENIED
        {
            _logger.LogError(ex, "Access denied to file {FilePath}.", _filePath);
            throw new UnauthorizedAccessException("Unable to access the specified file.", ex);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while loading data from {FilePath}.", _filePath);
            // Consider implementing retry logic or fallback mechanism here
            throw;
        }
    }
}
