class DirectoryManager:
    def __init__(self, monitoring_service=None):
        self.lock = Lock()
        self.monitoring_service = monitoring_service

    @retry(stop_max_attempt_number=5, wait_exponential_multiplier=1000)
    def create_directory(self, path: str) -> None:
        with self.lock:
            if not os.path.exists(path):
                try:
                    os.makedirs(path)
                    logging.info(f"Directory created at {path}")
                    if self.monitoring_service:
                        self.monitoring_service.log("directory_created", {"path": path})
                except Exception as e:
                    logging.error(f"Failed to create directory at {path}: {e}")
                    raise

    def remove_directory(self, path: str) -> None:
        with self.lock:
            if os.path.exists(path):
                try:
                    shutil.rmtree(path)
                    logging.info(f"Directory removed at {path}")
                    if self.monitoring_service:
                        self.monitoring_service.log("directory_removed", {"path": path})
                except Exception as e:
                    logging.error(f"Failed to remove directory at {path}: {e}")

    def manage_temporary_file(self, suffix: str = None):
        return tempfile.NamedTemporaryFile(delete=False, suffix=suffix)


