package main

import (
	"fmt"
	"log"
	"os"
	"path/filepath"
)

func checkAndCreateConfig(envVar, defaultConfigPath, configDir string) {
	if os.Getenv(envVar) == "" {
		configFilePath := filepath.Join(configDir, "config.cfg")

		if _, err := os.Stat(configDir); os.IsNotExist(err) {
			err = os.MkdirAll(configDir, os.ModePerm)
			if err != nil {
				log.Fatalf("Failed to create config directory: %v", err)
			}
		}

		// Create a symbolic link if needed
		if _, err := os.Stat(configFilePath); os.IsNotExist(err) {
			err = os.Symlink(defaultConfigPath, configFilePath)
			if err != nil {
				log.Fatalf("Failed to create symlink: %v", err)
			}
		}

		// Validate configuration file integrity here if needed
		fmt.Println("Configuration link created and verified")
	} else {
		fmt.Println("Environment variable set with necessary configuration.")
	}
}

func main() {
	envVar := "MY_APP_CONFIG"
	defaultConfigPath := "/etc/myapp/default_config.cfg"
	configDir := "/etc/myapp/config"

	checkAndCreateConfig(envVar, defaultConfigPath, configDir)
}
