```csharp
using System;
using UnityEngine;

public enum RangeType { Closed, Open, HalfOpen }

public class CustomInterval<T> where T : IComparable
{
    public T Min { get; }
    public T Max { get; }
    public RangeType Type { get; }

    public CustomInterval(T min, T max, RangeType type)
    {
        if (min.CompareTo(max) > 0) throw new ArgumentException("Min must be less than or equal to Max.");

        Min = min;
        Max = max;
        Type = type;
    }
}

public class AdvancedRandomGenerator
{
    private System.Random random;

    public delegate void SeedCallback(int seed);

    private static object seedLock = new object();
    private int? currentSeed;

    public event SeedCallback OnNewSeedGenerated;

    public AdvancedRandomGenerator()
    {
        random = new System.Random();
    }

    public void SetSeed(int seed)
    {
        lock (seedLock)
        {
            if (!currentSeed.HasValue || currentSeed != seed)
            {
                UnityEngine.Random.InitState(seed);
                random = new System.Random(seed);
                currentSeed = seed;
                OnNewSeedGenerated?.Invoke(seed);
            }
        }
    }

    public T CustomRange<T>(CustomInterval<T> interval) where T : IComparable, IConvertible
    {
        double rangeLength = Convert.ToDouble(interval.Max - interval.Min);
        double factor;

        switch (interval.Type)
        {
            case RangeType.Closed:
                factor = random.NextDouble();
                break;
            case RangeType.Open:
                factor = 1 + random.NextDouble() / (double)int.MaxValue; // Avoids exact min and max
                break;
            case RangeType.HalfOpen:
                factor = random.NextDouble();
                if (interval.Min.CompareTo(interval.Max) < 0)
                    factor *= rangeLength; // [min, max)
                else
                    factor *= -rangeLength; // [max, min)
                break;
            default:
                throw new ArgumentException("Invalid RangeType.");
        }

        return (T)(object)(Convert.ToDecimal(interval.Min) + Convert.ToDecimal(factor * rangeLength));
    }

    public void RegisterSeedCallback(SeedCallback callback)
    {
        OnNewSeedGenerated += callback;
    }
}
```

### Explanation

- **RangeType Enum**: Defines the types of intervals (`Closed`, `Open`, and `HalfOpen`).

- **CustomInterval Class**: Represents a range with specified bounds and type. Validates that `min <= max`.

- **AdvancedRandomGenerator Class**:
  - Implements methods to set seed values in a thread-safe manner.
  - Uses delegates (`SeedCallback`) for external customization of seed generation.
  - Provides a method (`CustomRange<T>`) to generate random numbers within specified ranges, handling different interval types.

- **Thread Safety**: Utilizes locks when setting seeds to prevent race conditions.

- **Event Handling**: Allows registration of callbacks for seed changes, enabling integration with external systems. 

This class supports advanced features such as reproducibility through seeding and customizable range generation while ensuring robustness and efficiency in its operations.

