```javascript
const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');
const axios = require('axios');
const os = require('os');

class TestRunner {
  constructor(config) {
    this.config = config;
    this.testResults = [];
    this.concurrencyLimit = os.cpus().length || 4; // Default concurrency to number of CPUs
    this.activeTests = 0;
  }

  async run() {
    const modules = await this.discoverModules(this.config.moduleDirectory);
    await Promise.all(modules.map(modulePath => this.runModuleTests(modulePath)));
    this.reportResults();
  }

  async discoverModules(directory) {
    try {
      const files = fs.readdirSync(directory);
      return files
        .map(file => path.join(directory, file))
        .filter(filePath => fs.lstatSync(filePath).isDirectory());
    } catch (error) {
      console.error(`Error discovering modules: ${error.message}`);
      return [];
    }
  }

  async runModuleTests(modulePath) {
    try {
      const module = require(modulePath);
      if (!module.testSuites || !Array.isArray(module.testSuites)) {
        throw new Error('No test suites found');
      }

      for (const suite of module.testSuites) {
        await this.runTestSuite(suite, modulePath);
      }
    } catch (error) {
      console.error(`Error running tests in ${modulePath}: ${error.message}`);
    }
  }

  async runTestSuite(testSuite, modulePath) {
    const jestProcess = spawn('jest', ['--config', path.join(modulePath, 'jest.config.js')]);

    jestProcess.stdout.on('data', (data) => this.logData(data.toString(), 'stdout'));
    jestProcess.stderr.on('data', (data) => this.logError(data.toString(), modulePath));

    jestProcess.on('close', async (code) => {
      if (code !== 0) {
        console.error(`Test suite ${testSuite.name} in ${modulePath} failed with code ${code}`);
      }
      --this.activeTests;
      await this.waitForConcurrencyLimit();
    });

    ++this.activeTests;

    jestProcess.on('error', error => {
      console.error(`Failed to start jest process for ${testSuite.name}: ${error.message}`);
    });
  }

  logData(data, type) {
    axios.post(this.config.logServerUrl, { data, type })
      .catch(error => console.error(`Logging failed: ${error.message}`));
  }

  logError(errorMessage, modulePath) {
    const errorLog = `Error in ${modulePath}: ${errorMessage}`;
    this.testResults.push({ success: false, message: errorLog });
    axios.post(this.config.logServerUrl, { data: errorLog, type: 'stderr' })
      .catch(error => console.error(`Logging failed: ${error.message}`));
  }

  reportResults() {
    console.log('Test Results:', this.testResults);
    // Optionally send to a log server or CI/CD system
  }

  async waitForConcurrencyLimit() {
    while (this.activeTests >= this.concurrencyLimit) {
      await new Promise(resolve => setTimeout(resolve, 100));
    }
  }
}

// Usage Example
const config = {
  moduleDirectory: './modules',
  logServerUrl: 'http://example.com/logs'
};

(async () => {
  const testRunner = new TestRunner(config);
  await testRunner.run();
})();
```

