from apscheduler.schedulers.background import BackgroundScheduler
from flask import Flask, jsonify, request

# Configure logging
logging.basicConfig(level=logging.INFO)

# Configuration file
config = {
    'api_keys': ['API_KEY_1', 'API_KEY_2'],
    'base_urls': {
        'alpha_vantage': 'https://www.alphavantage.co/query',
        'yahoo_finance': 'https://query1.finance.yahoo.com/v8/finance/chart'
    },
    'retry_after': 60,  # Default retry after rate limit
}

# Cache dictionary
cache = {}

def get_api_key():
    for key in config['api_keys']:
        yield key

def fetch_stock_data(company, start_date, end_date, api='alpha_vantage'):
    key_generator = get_api_key()
    url = config['base_urls'][api]

    params = {
        'function': 'TIME_SERIES_DAILY',
        'symbol': company,
        'apikey': next(key_generator),
        'outputsize': 'full'
    }

    response = requests.get(url, params=params)
    if response.status_code == 429:  # Rate limit
        retry_after = int(response.headers.get('Retry-After', config['retry_after']))
        time.sleep(retry_after)
        return fetch_stock_data(company, start_date, end_date, api)  # Retry

    elif response.ok:
        data = response.json()
        if 'Time Series (Daily)' in data:
            df = pd.DataFrame(data['Time Series (Daily)']).T.astype(float)
            df.index = pd.to_datetime(df.index)
            df = df[(df.index >= start_date) & (df.index <= end_date)]
            return df
    else:
        logging.error(f"Failed to fetch data for {company} from {api}: {response.text}")

    raise Exception("API error")

def calculate_statistics(df, interval):
    moving_avg = df['close'].rolling(window=interval).mean()
    std_dev = df['close'].std()
    return {
        'moving_average': moving_avg.tolist(),
        'standard_deviation': std_dev
    }

def store_in_db(company, data):
    conn = sqlite3.connect('stock_data.db')
    cursor = conn.cursor()
    cursor.execute('''CREATE TABLE IF NOT EXISTS stock_prices 
                      (company TEXT, date DATE, open REAL, high REAL, low REAL, close REAL)''')

    for index, row in data.iterrows():
        cursor.execute("INSERT INTO stock_prices VALUES (?, ?, ?, ?, ?, ?)",
                       (company, index.date(), row['1. open'], row['2. high'], 
                        row['3. low'], row['4. close']))
    conn.commit()
    conn.close()

def update_stock_data(company):
    start_date = datetime.now() - timedelta(days=365)
    end_date = datetime.now()
    try:
        df = fetch_stock_data(company, start_date, end_date)
        store_in_db(company, df)
        stats = calculate_statistics(df, interval=20)  # Customizable interval
        logging.info(f"Updated data for {company}: {stats}")
    except Exception as e:
        logging.error(f"Error updating stock data for {company}: {e}")

def periodic_update():
    scheduler = BackgroundScheduler()
    companies = ['AAPL', 'GOOGL']  # Example companies
    for company in companies:
        scheduler.add_job(update_stock_data, 'interval', days=1, args=[company])
    scheduler.start()

# Web interface setup using Flask
app = Flask(__name__)

@app.route('/update/<company>', methods=['GET'])
def update_company(company):
    update_stock_data(company)
    return jsonify({'message': f'Stock data updated for {company}'})

@app.route('/stats/<company>', methods=['GET'])
def get_stats(company):
    conn = sqlite3.connect('stock_data.db')
    df = pd.read_sql_query(f"SELECT * FROM stock_prices WHERE company='{company}'", conn)
    stats = calculate_statistics(df, interval=20)  # Customizable interval
    return jsonify(stats)

if __name__ == '__main__':
    periodic_update()
    app.run(debug=True)
```

