    virtual std::string toJsonString() const = 0;
    static std::unique_ptr<Json> fromJsonString(const std::string& jsonString);
};

std::unique_ptr<Json> Json::fromJsonString(const std::string& jsonString) {
    // Implement parsing logic here
    return nullptr; // Placeholder for actual JSON parsing
}

// Registry and factory functions
class FactoryRegistry {
public:
    using FactoryFunc = std::function<std::unique_ptr<Json>()>;

    void addFactoryFunction(int id, FactoryFunc func) {
        std::lock_guard<std::mutex> lock(mutex_);
        registry_[id] = std::move(func);
    }

    std::unique_ptr<Json> createInstance(int id) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = registry_.find(id);
        if (it != registry_.end()) {
            return it->second();
        }
        throw std::runtime_error("Invalid factory ID");
    }

private:
    mutable std::mutex mutex_;
    std::unordered_map<int, FactoryFunc> registry_;
};

// JSON subclass example
class JsonSubClass : public Json {
public:
    void setExampleData(const std::string& data) { exampleData_ = data; }
    std::string toJsonString() const override {
        return "{\"exampleData\": \"" + exampleData_ + "\"}";
    }

private:
    std::string exampleData_;
};

// File loading and management
class FileManager {
public:
    FileManager() {}

    void loadFilesAsync(const std::vector<std::string>& fileUrls) {
        for (const auto& url : fileUrls) {
            tasks_.emplace_back(std::async(std::launch::async, &FileManager::loadFile, this, url));
        }
    }

    void waitForCompletion() {
        for (auto& task : tasks_) {
            if (task.valid()) {
                try {
                    task.get();
                } catch (const std::exception& e) {
                    logError(e.what());
                }
            }
        }
    }

private:
    void loadFile(const std::string& url) {
        // Simulate file loading
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        // Check for errors and handle them appropriately
    }

    void logError(const std::string& message) const {
        std::cerr << "[ERROR] " << message << std::endl;
    }

    std::vector<std::future<void>> tasks_;
};

// Main application logic
class Application {
public:
    Application() : factoryRegistry_(), fileManager_() {}

    void setupFactories() {
        // Add factory functions to the registry
        factoryRegistry_.addFactoryFunction(1, [] { return std::make_unique<JsonSubClass>(); });
    }

    void execute() {
        setupFactories();

        std::vector<std::string> filesToLoad = {"file1.json", "file2.js"};
        fileManager_.loadFilesAsync(filesToLoad);
        fileManager_.waitForCompletion();

        try {
            auto instance = factoryRegistry_.createInstance(1);
            if (instance) {
                std::cout << instance->toJsonString() << std::endl;
            }
        } catch (const std::exception& e) {
            logError(e.what());
        }
    }

private:
    void logError(const std::string& message) const {
        std::cerr << "[ERROR] " << message << std::endl;
    }

    FactoryRegistry factoryRegistry_;
    FileManager fileManager_;
};

int main() {
    Application app;
    app.execute();
    return 0;
}
```

