```csharp
using System;
using System.Collections.Concurrent;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

namespace MultiTenantApp.DatabaseManagement
{
    public class DatabaseConnectionManager : IDisposable
    {
        private readonly string _connectionStringTemplate;
        private readonly ConcurrentDictionary<string, SqlConnection> _connectionPool = new();
        private readonly ConcurrentDictionary<string, string> _tenantMapping = new();

        public DatabaseConnectionManager(string connectionStringTemplate)
        {
            _connectionStringTemplate = connectionStringTemplate;
        }

        public void AddTenantMapping(string tenantId, string databaseName)
        {
            _tenantMapping[tenantId] = databaseName;
        }

        private string GetTenantConnectionString(string tenantId)
        {
            if (_tenantMapping.TryGetValue(tenantId, out var dbName))
            {
                return _connectionStringTemplate.Replace("{Database}", dbName);
            }
            throw new InvalidOperationException($"No connection string found for tenant ID: {tenantId}");
        }

        public async Task<SqlConnection> EstablishConnectionAsync(string tenantId)
        {
            var connectionString = GetTenantConnectionString(tenantId);

            if (_connectionPool.TryGetValue(connectionString, out var connection))
            {
                return connection;
            }

            connection = new SqlConnection(connectionString);
            await connection.OpenAsync();
            _connectionPool[connectionString] = connection;

            return connection;
        }

        public async Task<SqlDataReader> ExecuteQueryAsync(string tenantId, string query)
        {
            using var connection = await EstablishConnectionAsync(tenantId);
            using var command = new SqlCommand(query, connection);

            try
            {
                return await command.ExecuteReaderAsync();
            }
            catch (Exception ex)
            {
                // Log the exception with detailed information
                throw new InvalidOperationException("Failed to execute query", ex);
            }
        }

        public async Task<IDbTransaction> BeginTransactionAsync(string tenantId)
        {
            var connection = await EstablishConnectionAsync(tenantId);
            return await connection.BeginTransactionAsync();
        }

        public void CommitTransaction(IDbTransaction transaction)
        {
            if (transaction == null || transaction.Connection == null)
                throw new InvalidOperationException("Invalid transaction state");

            transaction.Commit();
        }

        public void RollbackTransaction(IDbTransaction transaction)
        {
            if (transaction == null || transaction.Connection == null)
                throw new InvalidOperationException("Invalid transaction state");

            transaction.Rollback();
        }

        public async Task CloseConnectionAsync(string tenantId)
        {
            var connectionString = GetTenantConnectionString(tenantId);
            if (_connectionPool.TryGetValue(connectionString, out var connection) && connection.State == ConnectionState.Open)
            {
                await connection.CloseAsync();
                _connectionPool.TryRemove(connectionString, out _);
            }
        }

        public override string ToString()
        {
            return $"DatabaseConnectionManager with {_tenantMapping.Count} tenants and {_connectionPool.Count} active connections.";
        }

        public void Dispose()
        {
            foreach (var conn in _connectionPool.Values)
            {
                if (conn != null && conn.State == ConnectionState.Open)
                    conn.Dispose();
            }
            _connectionPool.Clear();
            _tenantMapping.Clear();
        }
    }
}
```

