import asyncio
import json
import logging
from typing import Callable, Dict, Any
import hashlib
import os

# Set up basic configuration for logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class JSONHandler:
    _registry: Dict[str, Callable[[Dict], 'JSONHandler']] = {}

    def __init__(self, data: Dict):
        self.data = data

    @classmethod
    def from_json_string(cls, json_str: str) -> 'JSONHandler':
        try:
            data = json.loads(json_str)
            return cls(data)
        except json.JSONDecodeError as e:
            logger.error("Failed to decode JSON: %s", e)
            raise

    def to_json_string(self) -> str:
        return json.dumps(self.data)

    @classmethod
    def register_factory(cls, id_: str, factory_function: Callable[[Dict], 'JSONHandler']):
        cls._registry[id_] = factory_function

    @classmethod
    async def load_files_async(cls, file_paths: list[str]) -> Dict[str, Any]:
        tasks = [asyncio.to_thread(cls.load_file, path) for path in file_paths]
        results = await asyncio.gather(*tasks, return_exceptions=True)

        loaded_data = {}
        for i, result in enumerate(results):
            if isinstance(result, Exception):
                logger.error("Failed to load file: %s", file_paths[i])
                raise result
            else:
                loaded_data[file_paths[i]] = result
        return loaded_data

    @staticmethod
    def load_file(file_path: str) -> Dict[str, Any]:
        try:
            with open(file_path, 'r') as f:
                logger.info("Loading file: %s", file_path)
                return json.load(f)
        except Exception as e:
            logger.error("Error loading file %s: %s", file_path, e)
            raise

    @classmethod
    def create_instance(cls, id_: str, data: Dict) -> 'JSONHandler':
        if id_ in cls._registry:
            return cls._registry[id_](data)
        else:
            logger.error("No factory registered for ID: %s", id_)
            raise ValueError(f"No factory function registered for ID {id_}")

    @staticmethod
    def deserialize_byte_array(byte_data: bytes) -> 'JSONHandler':
        try:
            json_str = byte_data.decode('utf-8')
            return JSONHandler.from_json_string(json_str)
        except Exception as e:
            logger.error("Failed to deserialize byte array: %s", e)
            raise

    @staticmethod
    def hash_password_and_generate_random(password: str) -> str:
        hashed = hashlib.sha256(password.encode()).hexdigest()
        random_string = os.urandom(16).hex()
        return f"{random_string}:{hashed}"

async def main(file_paths):
    try:
        loaded_data = await JSONHandler.load_files_async(file_paths)

        # Example of how to use the registry
        class SubClass(JSONHandler):
            pass

        # Register factory function for a specific ID
        JSONHandler.register_factory('subclass', lambda data: SubClass(data))

        for file, content in loaded_data.items():
            instance = JSONHandler.create_instance('subclass', content)
            print(instance.to_json_string())

    except Exception as e:
        logger.error("An error occurred during execution: %s", e)

if __name__ == "__main__":
    asyncio.run(main(['file1.json', 'file2.json']))  # Example file paths
```

