```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <json-c/json.h>
#include <string.h>
#include <time.h>

#define MAX_RESOURCES 5
#define INITIAL_PERMITS 10

typedef struct {
    char *type;
    sem_t semaphore;
    int permits;
} ResourcePool;

ResourcePool resourcePools[MAX_RESOURCES];
pthread_mutex_t configMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t loadCondition = PTHREAD_COND_INITIALIZER;
int maxPermitsPerType[MAX_RESOURCES];
char *resourceTypes[MAX_RESOURCES] = {"db_connection", "api_call", "file_handle"};
int activeThreads = 0;
size_t cacheSize = 1024; // Example cache size in bytes
void *cache;

typedef struct {
    time_t timestamp;
    char data[256]; // Simplified caching mechanism
} CacheEntry;

pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;

// Dummy function to simulate cloud service interaction
void callCloudService(const char *resourceType) {
    printf("Calling cloud service for resource: %s\n", resourceType);
}

// Load configuration from JSON file
void loadConfiguration(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open config file");
        exit(EXIT_FAILURE);
    }

    struct json_object *parsed_json;
    struct json_object *max_permits_obj;

    size_t len;
    char *json_string = fread_to_string(file, &len);

    parsed_json = json_tokener_parse(json_string);
    for (int i = 0; i < MAX_RESOURCES; ++i) {
        const char key[16];
        sprintf(key, "max_permits_%d", i);
        if (json_object_object_get_ex(parsed_json, key, &max_permits_obj)) {
            maxPermitsPerType[i] = json_object_get_int(max_permits_obj);
        } else {
            maxPermitsPerType[i] = INITIAL_PERMITS;
        }
    }

    fclose(file);
}

// Initialize resource pools
void initializeResourcePools() {
    for (int i = 0; i < MAX_RESOURCES; ++i) {
        pthread_mutex_init(&resourcePools[i].semaphore, NULL);
        sem_init(&resourcePools[i].semaphore, 0, maxPermitsPerType[i]);
        resourcePools[i].permits = maxPermitsPerType[i];
        strncpy(resourcePools[i].type, resourceTypes[i], sizeof(char) * (strlen(resourceTypes[i]) + 1));
    }
}

// Cache management
void cacheData(const char *data) {
    pthread_mutex_lock(&cacheMutex);
    // Simplified cache logic: overwrites old data
    memcpy(cache, data, strlen(data) < cacheSize ? strlen(data) : cacheSize - 1);
    pthread_mutex_unlock(&cacheMutex);
}

char* getCachedData() {
    pthread_mutex_lock(&cacheMutex);
    char *cached = malloc(cacheSize);
    memcpy(cached, cache, cacheSize - 1);
    cached[cacheSize - 1] = '\0';
    pthread_mutex_unlock(&cacheMutex);
    return cached;
}

// Thread function to manage resource usage
void* resourceManager(void *arg) {
    int index = *(int*)arg;
    free(arg);

    while (1) {
        pthread_mutex_lock(&configMutex);
        sem_wait(&resourcePools[index].semaphore);
        activeThreads++;
        pthread_mutex_unlock(&configMutex);

        callCloudService(resourcePools[index].type);

        // Dynamic load balancing and smart throttling logic
        sleep(1);  // Simulate work

        pthread_mutex_lock(&configMutex);
        sem_post(&resourcePools[index].semaphore);
        activeThreads--;
        pthread_cond_signal(&loadCondition);
        pthread_mutex_unlock(&configMutex);
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config.json>\n", argv[0]);
        return EXIT_FAILURE;
    }

    loadConfiguration(argv[1]);

    initializeResourcePools();
    cache = malloc(cacheSize);

    pthread_t threads[MAX_RESOURCES];
    for (int i = 0; i < MAX_RESOURCES; ++i) {
        int *index = malloc(sizeof(int));
        *index = i;
        pthread_create(&threads[i], NULL, resourceManager, index);
    }

    // Join threads (not typically done in high-concurrency scenarios)
    for (int i = 0; i < MAX_RESOURCES; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&resourcePools[0].semaphore); // Clean up
    free(cache);

    return EXIT_SUCCESS;
}
