import java.util.Optional;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;
import javax.transaction.Transactional;

@RestController
@RequestMapping("/api/v1/tenants/{tenantId}/users/{userId}")
public class UserAccountUpgradeController {

    @Autowired
    private UserService userService;

    @Autowired
    private BillingService billingService;

    @Autowired
    private NotificationService notificationService;

    @Autowired
    private CacheManager cacheManager; // Assume a custom cache manager

    @PutMapping("/upgrade")
    @Transactional
    public ResponseEntity<String> upgradeUserAccount(
            @PathVariable String tenantId,
            @PathVariable String userId,
            @RequestBody UpgradePlanRequest upgradePlan) {

        try {
            validateInputs(tenantId, userId, upgradePlan);

            Optional<UserAccount> userAccount = userService.getUserAccount(tenantId, userId);

            if (!userAccount.isPresent()) {
                throw new ResourceNotFoundException("User or tenant not found");
            }

            // Cache the current plan details for fast access
            String cachedPlanDetails = cacheManager.getCache().get(userId);
            if (cachedPlanDetails == null) {
                userService.updateUserAccount(userAccount.get(), upgradePlan);

                // Update cache after successful database operation
                cacheManager.getCache().put(userId, userAccount.get().getPlanDetails());

                billingService.notifyUpgrade(tenantId, userId, upgradePlan);
                notificationService.notifyUser(userId, "Your account plan has been upgraded.");
            } else {
                throw new ConcurrencyException("Upgrade request is already being processed for this user.");
            }

            return ResponseEntity.ok("User account successfully upgraded");
        } catch (Exception e) {
            logError(e);
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(e.getMessage());
        }
    }

    private void validateInputs(String tenantId, String userId, UpgradePlanRequest upgradePlan) {
        if (tenantId == null || userId == null || upgradePlan == null ||
                upgradePlan.getSubscriptionTier() == null || upgradePlan.getExpirationDate() == null) {
            throw new InvalidInputException("Invalid input data");
        }
    }

    private void logError(Exception e) {
        // Detailed logging for audit trail and debugging
        System.out.println("An error occurred: " + e.getMessage());
        e.printStackTrace();
    }
}

