```python
import threading
import queue
from datetime import datetime
import requests

class LogProcessor:
    def __init__(self, log_queue, filter_criteria):
        self.log_queue = log_queue
        self.filter_criteria = filter_criteria

    def process_logs(self):
        while True:
            try:
                log_entry = self.log_queue.get(timeout=1)
                if self.apply_filters(log_entry):
                    self.handle_log_entry(log_entry)
                self.log_queue.task_done()
            except queue.Empty:
                continue

    def apply_filters(self, log_entry):
        # Example filter: check if a specific keyword is in the message
        return any(criterion in log_entry['message'] for criterion in self.filter_criteria)

    def handle_log_entry(self, log_entry):
        # Send to external log management service
        try:
            requests.post('https://external-log-service.com/api/logs', json=log_entry)
        except Exception as e:
            print(f"Error sending log: {e}")

        # Store in distributed storage system (simulated with a local file for this example)
        self.store_in_distributed_system(log_entry)

    def store_in_distributed_system(self, log_entry):
        try:
            with open('distributed_storage.log', 'a') as f:
                f.write(f"{datetime.now()} - {log_entry}\n")
        except Exception as e:
            print(f"Error storing log: {e}")

class LogPipelineManager:
    def __init__(self):
        self.log_queue = queue.Queue()
        self.processors = []
        self.is_paused = threading.Event()

    def start_pipeline(self, filter_criteria):
        processor = LogProcessor(self.log_queue, filter_criteria)
        thread = threading.Thread(target=processor.process_logs)
        thread.start()
        self.processors.append(thread)

    def pause_pipeline(self):
        self.is_paused.set()

    def resume_pipeline(self):
        self.is_paused.clear()

    def add_log_entry(self, log_entry):
        if not self.is_paused.is_set():
            self.log_queue.put(log_entry)

    def stop_pipeline(self):
        for processor in self.processors:
            processor.join()

# Example usage
if __name__ == "__main__":
    manager = LogPipelineManager()
    manager.start_pipeline(filter_criteria=['ERROR', 'CRITICAL'])

    # Simulate incoming log entries
    logs = [
        {'message': 'This is an ERROR message'},
        {'message': 'This is a DEBUG message'},
        {'message': 'This is another CRITICAL issue'}
    ]

    for log in logs:
        manager.add_log_entry(log)

    # Pause and resume example
    manager.pause_pipeline()
    print("Pipeline paused")

    import time
    time.sleep(2)  # Simulate pause duration

    manager.resume_pipeline()
    print("Pipeline resumed")

    # Add more logs after resuming
    additional_logs = [{'message': 'RESUMED: INFO log entry'}]
    for log in additional_logs:
        manager.add_log_entry(log)

    manager.stop_pipeline()
```

This code provides a basic structure for a logging pipeline with modularity, real-time processing, filtering, and integration points for external services. It uses threading to handle concurrency and queues for managing log entries efficiently. The `LogProcessor` class processes logs based on user-defined filters and handles both sending to an external service and storing in a simulated distributed storage system. The `LogPipelineManager` manages the lifecycle of the pipeline, including starting, pausing, resuming, and stopping the processing threads.

