#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>

#define MAX_THREADS 4

typedef struct {
    char *input_file;
} ThreadData;

void* convert_jpeg_to_pdf(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    char command[256];
    snprintf(command, sizeof(command), "convert %s output.pdf", data->input_file);

    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Error converting file: %s\n", strerror(errno));
    }

    free(data);
    return NULL;
}

int validate_file(const char *file_path) {
    struct stat st;
    if (stat(file_path, &st) == -1) {
        fprintf(stderr, "File does not exist or cannot be accessed: %s\n", file_path);
        return 0;
    }
    if (!S_ISREG(st.st_mode)) {
        fprintf(stderr, "%s is not a regular file.\n", file_path);
        return 0;
    }

    FILE *file = fopen(file_path, "rb");
    if (file == NULL) {
        fprintf(stderr, "Cannot open file: %s\n", file_path);
        return 0;
    }
    fclose(file);

    // Perform JPEG format validation here if necessary
    return 1;
}

void convert_files_to_pdf(const char *config_file_path, char **input_files, int num_files) {
    pthread_t threads[MAX_THREADS];
    ThreadData *thread_data = malloc(num_files * sizeof(ThreadData));

    for (int i = 0; i < num_files; ++i) {
        if (!validate_file(input_files[i])) continue;

        thread_data[i].input_file = strdup(input_files[i]);

        int idx = i % MAX_THREADS;
        pthread_create(&threads[idx], NULL, convert_jpeg_to_pdf, &thread_data[i]);
    }

    for (int i = 0; i < num_files; ++i) {
        int idx = i % MAX_THREADS;
        if (pthread_join(threads[idx], NULL)) {
            fprintf(stderr, "Error joining thread: %s\n", strerror(errno));
        }
    }

    free(thread_data);
}

// Example usage:
