    const char *config_path = "path/to/config";
    char *files[] = {"image1.jpg", "image2.jpg"};
    int num_files = sizeof(files) / sizeof(files[0]);

    convert_files_to_pdf(config_path, files, num_files);
    return 0;
}
*/
