double calculate_average_of_last_two_numbers(char *line);
void read_binary_file_and_generate_output(const char *input_filename, const char *output_filename, const char *rules);
void submit_log_message_async(const char *message);

int main(int argc, char *argv[]) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <binary input file> <output file> <rules> <log directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *input_file = argv[1];
    const char *output_file = argv[2];
    const char *rules = argv[3];
    const char *log_directory = argv[4];

    // Process binary file and generate output
    read_binary_file_and_generate_output(input_file, output_file, rules);

    // Process log files in the directory concurrently
    DIR *dir;
    struct dirent *entry;

    if ((dir = opendir(log_directory)) == NULL) {
        perror("Failed to open directory");
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (thread_count >= MAX_THREADS || !is_file_regular(entry->d_name, log_directory)) {
            continue; // Skip non-regular files or if max threads reached
        }

        char file_path[1024];
        snprintf(file_path, sizeof(file_path), "%s/%s", log_directory, entry->d_name);

        pthread_create(&threads[thread_count++], NULL, (void *(*)(void *))process_log_file, strdup(file_path));
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    closedir(dir);
    return EXIT_SUCCESS;
}

void read_binary_file_and_generate_output(const char *input_filename, const char *output_filename, const char *rules) {
    FILE *in_file = fopen(input_filename, "rb");
    if (!in_file) {
        perror("Failed to open input file");
        exit(EXIT_FAILURE);
    }

    // Binary parsing logic and output generation based on rules would go here

    fclose(in_file);
}

void process_log_file(const char *file_path) {
    pthread_mutex_lock(&cache_lock);

    if (concurrent_reads >= MAX_THREADS) {
        fprintf(stderr, "Maximum concurrent reads reached.\n");
        pthread_mutex_unlock(&cache_lock);
        return;
    }

    ++concurrent_reads;

    pthread_mutex_unlock(&cache_lock);

    FILE *file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open log file");
        --concurrent_reads;
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        double average = calculate_average_of_last_two_numbers(line);
        // Log or process the calculated average
    }

    fclose(file);

    pthread_mutex_lock(&cache_lock);
    --concurrent_reads;
    pthread_mutex_unlock(&cache_lock);
}

double calculate_average_of_last_two_numbers(char *line) {
    int numbers[2] = {0};
    char *token = strtok(line, " ");
    int count = 0;

    while (token != NULL && count < 2) {
        if (isdigit(token[0]) || (token[0] == '-' && isdigit(token[1]))) {
            numbers[count++] = atoi(token);
        }
        token = strtok(NULL, " ");
    }

    if (count < 2) return -1; // Not enough numbers to calculate average

    return ((double)numbers[0] + numbers[1]) / 2.0;
}

int is_file_regular(const char *filename, const char *directory) {
    struct stat path_stat;
    char filepath[1024];

    snprintf(filepath, sizeof(filepath), "%s/%s", directory, filename);
    if (stat(filepath, &path_stat) != 0) {
        return 0;
    }

    return S_ISREG(path_stat.st_mode);
}

