<?php

class OAuth2AuthModule {
    private $clientId;
    private $clientSecret;
    private $providerUrl;
    private $redirectUri;

    public function __construct($clientId, $clientSecret, $providerUrl, $redirectUri) {
        $this->clientId = $clientId;
        $this->clientSecret = $clientSecret;
        $this->providerUrl = $providerUrl;
        $this->redirectUri = $redirectUri;
    }

    public function redirectToProvider() {
        $authUrl = $this->providerUrl . '/authorize?' .
            http_build_query([
                'response_type' => 'code',
                'client_id'     => $this->clientId,
                'redirect_uri'  => $this->redirectUri,
                'scope'         => 'profile email'
            ]);

        header('Location: ' . $authUrl);
        exit();
    }

    public function handleProviderCallback() {
        if (isset($_GET['code'])) {
            $token = $this->fetchAccessToken($_GET['code']);
            if ($token) {
                $_SESSION['access_token'] = $token;
                return $this->getUserInfo($token);
            } else {
                // Fallback mechanism
                $this->handleFailedAuthentication();
            }
        }

        // Redirect to start flow again or show error message
    }

    private function fetchAccessToken($code) {
        $url = $this->providerUrl . '/token';
        $data = [
            'grant_type' => 'authorization_code',
            'client_id'  => $this->clientId,
            'client_secret' => $this->clientSecret,
            'redirect_uri'  => $this->redirectUri,
            'code'       => $code
        ];

        $response = $this->sendRequest($url, $data);

        if (isset($response['access_token'])) {
            return $response['access_token'];
        }

        return false;
    }

    private function getUserInfo($accessToken) {
        $url = $this->providerUrl . '/userinfo';
        $headers = [
            'Authorization: Bearer ' . $accessToken
        ];

        $userInfo = $this->sendRequest($url, [], $headers);

        if ($userInfo) {
            $cacheKey = 'user_' . md5(json_encode($userInfo));
            $cachedUser = apcu_fetch($cacheKey);

            if (!$cachedUser) {
                apcu_store($cacheKey, $userInfo, 3600); // Cache for an hour
            }

            return $userInfo;
        }

        return false;
    }

    private function sendRequest($url, $data = [], $headers = []) {
        $options = [
            'http' => [
                'header' => implode("\r\n", $headers),
                'method'  => 'POST',
                'content' => http_build_query($data)
            ]
        ];

        $context  = stream_context_create($options);
        try {
            $response = file_get_contents($url, false, $context);
            if ($response === FALSE) {
                return false;
            }

            return json_decode($response, true);
        } catch (Exception $e) {
            // Handle exception or log error
            return false;
        }
    }

    private function handleFailedAuthentication() {
        // Implement fallback mechanism, e.g., redirect to login page with an error message
    }
}

