```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Logging;

public class UserProfileService
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly ILogger<UserProfileService> _logger;

    public UserProfileService(HttpClient httpClient, IDistributedCache cache, ILogger<UserProfileService> logger)
    {
        _httpClient = httpClient;
        _cache = cache;
        _logger = logger;
    }

    public async Task<Dictionary<string, string>> FetchUserProfilesAsync(
        List<string> userIds,
        string apiBaseUri,
        string apiKey,
        TimeSpan? cacheExpirationTime = null)
    {
        if (!userIds.All(IsValidUserId))
        {
            throw new ArgumentException("Invalid user IDs provided.");
        }

        var userProfiles = new Dictionary<string, string>();
        var tasks = userIds.Select(userId => FetchUserProfileAsync(userId, apiBaseUri, apiKey, cacheExpirationTime));
        var results = await Task.WhenAll(tasks);

        foreach (var result in results)
        {
            if (!string.IsNullOrEmpty(result.Value))
            {
                userProfiles[result.Key] = result.Value;
            }
        }

        return userProfiles;
    }

    private async Task<(string Key, string Value)> FetchUserProfileAsync(
        string userId,
        string apiBaseUri,
        string apiKey,
        TimeSpan? cacheExpirationTime)
    {
        var cacheKey = $"userProfile:{userId}";
        if (_cache.TryGetValue(cacheKey, out byte[] cachedValue))
        {
            return (userId, JsonSerializer.Deserialize<string>(cachedValue));
        }

        for (int attempt = 0; attempt < 3; attempt++)
        {
            try
            {
                _httpClient.DefaultRequestHeaders.Add("Authorization", $"Bearer {apiKey}");
                var response = await _httpClient.GetAsync($"{apiBaseUri}/users/{userId}");

                if (response.IsSuccessStatusCode)
                {
                    var content = await response.Content.ReadAsStringAsync();
                    var userProfile = JsonSerializer.Deserialize<string>(content);

                    var cacheOptions = new DistributedCacheEntryOptions
                    {
                        AbsoluteExpirationRelativeToNow = cacheExpirationTime ?? TimeSpan.FromMinutes(5)
                    };
                    _cache.Set(cacheKey, System.Text.Encoding.UTF8.GetBytes(userProfile), cacheOptions);

                    return (userId, userProfile);
                }
                else if ((int)response.StatusCode == 429)
                {
                    await Task.Delay(TimeSpan.FromSeconds(2)); // Handle rate limiting
                }
                else
                {
                    _logger.LogWarning($"Failed to fetch user profile for {userId}. Attempt {attempt + 1}.");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error fetching user profile for {userId}. Attempt {attempt + 1}.");
            }
        }

        return (userId, null);
    }

    private bool IsValidUserId(string userId) => !string.IsNullOrEmpty(userId) && userId.All(char.IsDigit);
}
```

