def load_config(config_path):
    with open(config_path, 'r') as file:
        return yaml.safe_load(file)

def parse_log(log_entry, schema):
    # Implement dynamic parsing based on the provided schema
    try:
        if schema == "json":
            return json.loads(log_entry)
        else:
            # Add other formats handling here (e.g., CSV, plain text with regex)
            pass
    except Exception as e:
        logger.error(f"Failed to parse log: {e}")
        return None

def apply_filters(parsed_log, filters):
    for key, condition in filters.items():
        if key not in parsed_log or not eval(condition.format(value=parsed_log[key])):
            return False
    return True

def process_logs(config_path):
    config = load_config(config_path)

    # Connect to Kafka
    consumer = KafkaConsumer(
        bootstrap_servers=config['kafka']['bootstrap_servers'],
        group_id=config['kafka']['group_id'],
        auto_offset_reset='earliest'
    )

    # Connect to Elasticsearch
    es_client = Elasticsearch([config['elasticsearch']['host']])

    for topic in config['topics']:
        consumer.subscribe([topic])

        while True:
            try:
                for message in consumer:
                    log_entry = message.value.decode('utf-8')

                    parsed_log = parse_log(log_entry, config['schema'])
                    if not parsed_log:
                        continue

                    # Apply user-defined filters
                    if apply_filters(parsed_log, config['filters']):
                        doc_id = f"{parsed_log.get('id', 'unknown')}_{message.offset}"
                        try:
                            es_client.index(
                                index=config['elasticsearch']['index'],
                                id=doc_id,
                                body=parsed_log
                            )
                        except Exception as e:
                            logger.error(f"Failed to index log: {e}")

            except KeyboardInterrupt:
                break
            except Exception as e:
                logger.error(f"Processing error: {e}")
                # Implement fault-tolerant mechanisms, like retries or backoff strategies

if __name__ == "__main__":
    config_file = os.environ.get('CONFIG_PATH', 'config.yaml')
    process_logs(config_file)
```

### Explanation of Key Components:

- **Configuration Loading**: The function loads configuration from a YAML file. This includes Kafka and Elasticsearch settings, filtering criteria, log schema details, etc.

- **Kafka Consumer Setup**: Connects to the specified Kafka broker(s) for consuming messages from topics listed in the configuration file.

- **Elasticsearch Client Initialization**: Establishes a connection to Elasticsearch where logs will be indexed.

- **Log Parsing**: Dynamically parses incoming log entries based on defined schemas (e.g., JSON). Extendable to handle other formats like CSV or plain text with regular expressions.

- **Filtering Logic**: Applies user-defined filters using Python’s `eval`, which interprets filter conditions dynamically. This allows for flexible filtering criteria without code changes.

- **Fault Tolerance**: Includes error handling and logging mechanisms. Implement further strategies (e.g., retries, backoff) as needed to enhance fault tolerance.

- **Concurrent Processing**: Built-in support for concurrent processing via Kafka’s consumer groups; can be expanded using multiprocessing or threading for additional performance improvements if necessary.

