# log_monitor.py

import hashlib
import os
import threading
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

class LogHandler(FileSystemEventHandler):
    def __init__(self, monitoring_api):
        self.monitoring_api = monitoring_api

    def on_modified(self, event):
        if not event.is_directory:
            file_path = event.src_path
            try:
                hash_value = self.compute_sha256(file_path)
                self.monitoring_api.report_integrity_status(file_path, hash_value)
            except Exception as e:
                print(f"Error processing {file_path}: {e}")

    def compute_sha256(self, file_path):
        sha256_hash = hashlib.sha256()
        with open(file_path, "rb") as f:
            for byte_block in iter(lambda: f.read(4096), b""):
                sha256_hash.update(byte_block)
        return sha256_hash.hexdigest()

class LogMonitor:
    def __init__(self, log_directory, monitoring_api):
        self.log_directory = log_directory
        self.monitoring_api = monitoring_api

    def start(self):
        event_handler = LogHandler(self.monitoring_api)
        observer = Observer()
        observer.schedule(event_handler, self.log_directory, recursive=True)
        observer.start()

        try:
            while True:
                pass  # Run indefinitely or until a condition is met
        except KeyboardInterrupt:
            observer.stop()
        observer.join()

class MonitoringAPI:
    def report_integrity_status(self, file_path, hash_value):
        # Implementation for reporting to external monitoring system API
        print(f"Reporting {file_path} with SHA256: {hash_value}")

if __name__ == "__main__":
    log_directory = "/path/to/log/directory"
    monitoring_api = MonitoringAPI()

    monitor = LogMonitor(log_directory, monitoring_api)
    monitor_thread = threading.Thread(target=monitor.start)
    monitor_thread.start()
