#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAX_MEMORY_USAGE_BYTES (50 * 1024 * 1024) // 50 MB

int findMax(int* array, int size) {
    if (size == 0) return INT_MIN;

    int max = INT_MIN;
    for (int i = 0; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

int main() {
    int *numbers = NULL;
    int count = 0, capacity = 100000;
    long long memoryUsage = sizeof(int) * capacity;

    numbers = malloc(memoryUsage);
    if (!numbers) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    while (1) {
        if (memoryUsage > MAX_MEMORY_USAGE_BYTES && count == capacity) {
            fprintf(stderr, "Exceeded maximum memory usage limit of 50MB\n");
            break;
        }

        int number;
        char line[12]; // Enough to hold INT_MAX string
        if (!fgets(line, sizeof(line), stdin)) {
            break; // EOF or error
        }

        if (sscanf(line, "%d", &number) != 1) {
            fprintf(stderr, "Invalid input detected: %s", line);
            continue;
        }

        if (count == capacity) {
            capacity *= 2;
            memoryUsage = sizeof(int) * capacity;

            int* temp = realloc(numbers, memoryUsage);
            if (!temp) {
                free(numbers);
                fprintf(stderr, "Memory allocation failed during resize\n");
                return EXIT_FAILURE;
            }
            numbers = temp;
        }

        numbers[count++] = number;
    }

    int maxNumber = findMax(numbers, count);
    if (maxNumber != INT_MIN) {
        printf("The largest integer is: %d\n", maxNumber);
    } else {
        fprintf(stderr, "No valid integers were read\n");
    }

    free(numbers);
    return EXIT_SUCCESS;
}
