```csharp
using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class SqlQueryExecutor
{
    private readonly ILogger _logger; // Assume an ILogger interface is implemented elsewhere
    private readonly IAuthenticationService _authService; // Assume this service is available for checking permissions

    public SqlQueryExecutor(ILogger logger, IAuthenticationService authService)
    {
        _logger = logger;
        _authService = authService;
    }

    public async Task<IEnumerable<T>> ExecuteDynamicSqlAsync<T>(
        string connectionString,
        string sqlCommandTemplate,
        Dictionary<string, object> parameters,
        bool isSensitiveQuery = false)
    {
        if (isSensitiveQuery && !_authService.HasPermission())
        {
            throw new UnauthorizedAccessException("User does not have permission to execute this query.");
        }

        using var connection = new SqlConnection(connectionString);
        await connection.OpenAsync();

        using var command = new SqlCommand(sqlCommandTemplate, connection);

        foreach (var param in parameters)
        {
            if (param.Value == null) continue;

            command.Parameters.AddWithValue(param.Key, param.Value ?? DBNull.Value);
        }

        try
        {
            using var reader = await command.ExecuteReaderAsync();
            return SqlMapperExtensions.ReadAsList<T>(reader); // Assume this extension method is implemented elsewhere for ORM mapping.
        }
        catch (Exception ex)
        {
            _logger.LogError("Error executing SQL query", ex);
            throw;
        }
    }
}
