```rust
use std::env;
use std::fs::{self, DirEntry};
use std::io;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, SystemTime};
use log::{info, warn, error};
use rusqlite::{params, Connection, Result as SqlResult};

const DEFAULT_DIR: &str = "/tmp/file_processing_dir";
const MIN_FREE_SPACE_PERCENTAGE: u32 = 20;

struct DirectoryManager {
    work_dir: PathBuf,
    cleanup_duration: Duration,
    db_connection: Arc<Mutex<Connection>>,
}

impl DirectoryManager {
    fn new(db_path: &str, cleanup_duration_secs: u64) -> io::Result<Self> {
        let mut manager = Self {
            work_dir: Self::get_work_dir()?,
            cleanup_duration: Duration::from_secs(cleanup_duration_secs),
            db_connection: Arc::new(Mutex::new(Connection::open(db_path)?)),
        };
        manager.record_metadata()?;
        Ok(manager)
    }

    fn get_work_dir() -> io::Result<PathBuf> {
        if let Some(prefix) = env::var_os("WORK_DIR_PREFIX") {
            let instance_id = std::thread::current().id();
            return Ok(PathBuf::from(format!("{}/{}_{}", prefix, instance_id, chrono::Utc::now().timestamp())));

        }
        Ok(PathBuf::from(DEFAULT_DIR))
    }

    fn validate_directory(&self) -> io::Result<()> {
        if !self.work_dir.exists() || !self.work_dir.is_dir() {
            fs::create_dir_all(&self.work_dir)?;
        }
        let metadata = self.work_dir.metadata()?;
        if !metadata.permissions().readonly() {
            Ok(())
        } else {
            Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                "Directory is not writable",
            ))
        }
    }

    fn record_metadata(&self) -> SqlResult<()> {
        let conn = self.db_connection.lock().unwrap();
        conn.execute(
            "INSERT INTO directory_metadata (path, creation_time, last_cleanup_time, current_disk_usage) VALUES (?1, ?2, ?3, ?4)",
            params![
                self.work_dir.to_str().unwrap(),
                SystemTime::now().duration_since(SystemTime::UNIX_EPOCH)?.as_secs(),
                0,
                Self::get_disk_usage(&self.work_dir)?
            ],
        )?;
        Ok(())
    }

    fn get_disk_usage(dir: &Path) -> io::Result<u64> {
        let metadata = fs::metadata(dir)?;
        Ok(metadata.len())
    }

    fn cleanup_directory(&self) -> io::Result<()> {
        // Implement cleanup logic based on file age and type
        info!("Cleaning up directory {:?}", self.work_dir);
        for entry in fs::read_dir(self.work_dir)? {
            let entry = entry?;
            let path = entry.path();
            if path.is_file() && Self::is_old_enough(&path) {
                fs::remove_file(path)?;
            }
        }
        let mut conn = self.db_connection.lock().unwrap();
        conn.execute(
            "UPDATE directory_metadata SET last_cleanup_time = ?1 WHERE path = ?2",
            params![
                SystemTime::now().duration_since(SystemTime::UNIX_EPOCH)?.as_secs(),
                self.work_dir.to_str().unwrap()
            ],
        )?;
        Ok(())
    }

    fn is_old_enough(path: &Path) -> bool {
        let metadata = fs::metadata(path).ok()?;
        let age = SystemTime::now().duration_since(metadata.modified()?).ok()?;
        age > Self::cleanup_duration
    }

    fn monitor_disk_usage(&self) -> io::Result<()> {
        if Self::get_free_space_percentage(&self.work_dir)? < MIN_FREE_SPACE_PERCENTAGE {
            self.cleanup_directory()?;
        }
        Ok(())
    }

    fn get_free_space_percentage(dir: &Path) -> io::Result<u32> {
        let metadata = fs::metadata(dir)?;
        let total = metadata.len();
        let used = Self::get_disk_usage(dir)?;
        let free = total - used;
        Ok((free as f64 / total as f64 * 100.0) as u32)
    }
}

fn setup_logging() {
    // Set up logging configuration
}

fn main() -> io::Result<()> {
    setup_logging();

    let db_path = "metadata.db";
    let manager = DirectoryManager::new(db_path, 3600)?;

    if let Err(e) = manager.validate_directory() {
        error!("Error validating directory: {}", e);
        return Err(io::Error::new(io::ErrorKind::Other, "Failed to validate directory"));
    }

    let manager_arc = Arc::new(manager);

    // Directory cleanup thread
    let cleanup_manager = manager_arc.clone();
    thread::spawn(move || {
        loop {
            if let Err(e) = cleanup_manager.cleanup_directory() {
                warn!("Cleanup error: {}", e);
            }
            thread::sleep(cleanup_manager.cleanup_duration);
        }
    });

    // Disk usage monitoring thread
    let monitor_manager = manager_arc.clone();
    thread::spawn(move || {
        loop {
            if let Err(e) = monitor_manager.monitor_disk_usage() {
                warn!("Disk usage error: {}", e);
            }
            thread::sleep(Duration::from_secs(60));
        }
    });

    // Main processing logic
    loop {
        // Simulate file processing
        thread::sleep(Duration::from_secs(5));
    }
}
