    private readonly IMessageQueue _messageQueue;
    private static readonly RateLimiter Limiter = new RateLimiter(5, TimeSpan.FromMinutes(1));

    public ContentController(IContentService contentService, IMessageQueue messageQueue)
    {
        _contentService = contentService;
        _messageQueue = messageQueue;
    }

    [HttpPost("updateElement")]
    public async Task<IActionResult> UpdateElement(int pageSectionId, int elementId, string htmlContent)
    {
        if (!Limiter.IsAllowed())
        {
            return StatusCode(429, "Rate limit exceeded");
        }

        try
        {
            // Validate input
            if (string.IsNullOrWhiteSpace(htmlContent))
                throw new ArgumentException("HTML content cannot be empty.");

            // Update HTML content in distributed cache
            bool updateSuccess = await _contentService.UpdateElementHtmlAsync(pageSectionId, elementId, htmlContent);

            if (!updateSuccess)
                throw new Exception("Failed to update HTML content.");

            // Notify message queue for page refresh
            await _messageQueue.PublishMessageAsync(new RefreshPageMessage(pageSectionId));

            return Ok();
        }
        catch (Exception ex)
        {
            // Log error details
            Console.Error.WriteLine(ex.Message);
            return StatusCode(500, "An error occurred while processing the request.");
        }
    }
}

