    const scriptsCache = new Map();

    for (const script of scriptObjects) {
      if (!script.code && !script.src) continue;

      const key = `${scriptId}_${scriptId}`;

      if (scriptsCache.has(key)) {
        renderedHTML += `<script>${scriptsCache.get(key)}</script>`;
        continue;
      }

      let scriptContent;
      if (scriptId) { // Inline Script
        scriptContent = `async ${scriptId ? 'defer' : ''} type="${scriptId}" innerHTML=${JSON.stringify(script.code)}`;
      } else { // External Script
        const cachedScript = await fetchWithCache(script.src);
        scriptContent = `src="${script.src}" async="true" crossorigin="anonymous"`;
      }

      scriptsCache.set(key, scriptContent);

      renderedHTML += `<script ${scriptId ? 'key="' + key + '"' : ''} ${scriptId ? `innerHTML=${JSON.stringify(script.code)}` : scriptContent}></script>`;
    }

    footer.innerHTML = renderedHTML;
  } catch (error) {
    console.error('Error rendering scripts:', error);
  }

  return renderedHTML;
}

async function fetchWithCache(url) {
  const cacheKey = url;

  if (sessionStorage.getItem(cacheKey)) {
    return sessionStorage.getItem(cacheKey);
  }

  try {
    const response = await fetch(url, { timeout: 5000 });
    if (!response.ok) throw new Error('Network response was not ok.');

    const data = await response.text();
    sessionStorage.setItem(cacheKey, data);

    // Set cache expiration (e.g., 5 minutes)
    setTimeout(() => sessionStorage.removeItem(cacheKey), 300000);
    return data;
  } catch (error) {
    console.error('Fetch error:', error);
    if (isCriticalScript(url)) throw new Error('Failed to load critical script');
    return '';
  }
}

function isCriticalScript(src) {
  const criticalScripts = ['critical1.js', 'critical2.js'];
  return criticalScripts.includes(src.split('/').pop());
}
</script>
```

