fn get_work_dir() -> Result<PathBuf, io::Error> {
    match env::var("WORK_DIR") {
        Ok(dir) => {
            let path = PathBuf::from(dir);
            if path.exists() && path.is_dir() && fs::metadata(&path)?.permissions().readonly() == false {
                info!("Using existing WORK_DIR: {:?}", path);
                Ok(path)
            } else {
                error!("Invalid WORK_DIR: {:?}.", path);
                Err(io::Error::new(io::ErrorKind::Other, "Invalid WORK_DIR"))
            }
        },
        Err(_) => {
            let temp_dir = TempDir::new_in("/tmp")?;
            info!("Created temporary directory: {:?}", temp_dir.path());
            Ok(temp_dir.into_path())
        }
    }
}

fn setup_workdir() -> Result<PathBuf, io::Error> {
    let work_dir = get_work_dir()?;
    // Additional plugin integration and configuration logic here
    Ok(work_dir)
}

fn cleanup_workdir(path: &PathBuf) -> io::Result<()> {
    if path.is_absolute() && path.exists() {
        fs::remove_dir_all(path)?;
        info!("Cleaned up directory: {:?}", path);
    }
    Ok(())
