class DynamicLoader {
public:
    using FactoryFunc = std::function<std::unique_ptr<json>(const json&)>;

    void addFactory(const std::string& id, FactoryFunc factory) {
        std::lock_guard<std::mutex> lock(mutex_);
        registry_[id] = std::move(factory);
    }

    void removeFactory(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        registry_.erase(id);
    }

    std::unique_ptr<json> createInstance(const std::string& id, const json& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = registry_.find(id);
        if (it != registry_.end()) {
            return it->second(data);
        }
        throw std::runtime_error("Factory not found");
    }

    void loadFilesConcurrently(const std::vector<std::string>& filepaths) {
        std::vector<std::future<void>> futures;
        for (const auto& filepath : filepaths) {
            futures.push_back(std::async(std::launch::async, &DynamicLoader::loadFile, this, filepath));
        }
        for (auto& fut : futures) {
            fut.get();
        }
