// directory_manager.rs
pub mod directory_manager {
    use std::fs;
    use std::io;
    use std::path::{Path, PathBuf};
    use std::sync::{Arc, Mutex};
    use log::info;

    pub fn ensure_directory(dir_path: Arc<Mutex<PathBuf>>) -> (PathBuf, bool) {
        let path = dir_path.lock().unwrap();
        if !path.exists() {
            match fs::create_dir_all(path.clone()) {
                Ok(_) => info!("Created directory: {}", path.display()),
                Err(e) => {
                    error!("Failed to create directory {}: {:?}", path.display(), e);
                    return (PathBuf::new(), false);  // Fallback mechanism
                }
            }
            (path.clone(), true)
        } else {
            (path.clone(), false)
        }
    }

    pub fn cleanup_directory(dir_path: &Arc<Mutex<PathBuf>>) {
        let path = dir_path.lock().unwrap();
        if path.exists() && path.is_dir() {
            match fs::read_dir(path) {
                Ok(entries) => {
                    for entry in entries.flatten() {
                        if let Err(e) = fs::remove_file(entry.path()) {
                            error!("Failed to remove file {}: {:?}", entry.file_name(), e);
                        }
                    }
                    info!("Cleaned up directory: {}", path.display());
                }
                Err(e) => {
                    warn!("Failed to read directory {}: {:?}", path.display(), e);
                }
            }
        }
    }

    pub fn check_disk_usage(path: &PathBuf) -> f64 {
        match fs::metadata(&path.parent().unwrap()) {
            Ok(meta) => meta.used_space() as f64 / meta.total_space() as f64,
            Err(e) => {
                error!("Failed to get disk usage for {}: {:?}", path.display(), e);
                0.0
            }
        }
    }
}

