import subprocess
from threading import Lock
from time import sleep

class K8sOrchestrator:
    def __init__(self):
        self.lock = Lock()

    def create_namespace(self, namespace):
        with self.lock:
            try:
                subprocess.run(["kubectl", "create", "namespace", namespace], check=True)
            except subprocess.CalledProcessError as e:
                self.retry_creation(namespace)

    def retry_creation(self, namespace):
        for _ in range(3):  # Retry strategy
            sleep(2)  # Backoff before retrying
            try:
                subprocess.run(["kubectl", "create", "namespace", namespace], check=True)
                break
            except subprocess.CalledProcessError:
                continue

    def deploy_application(self, manifest_path):
