using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml;
using System.Xml.Linq;
using System.Xml.Schema;
using Microsoft.Extensions.Logging;

public class XPathParserAndValidator
{
    private static readonly HttpClient httpClient = new HttpClient();
    private readonly ConcurrentDictionary<string, XElement> _cache = new ConcurrentDictionary<string, XElement>();
    private readonly int _cacheSizeLimit;
    private readonly ILogger<XPathParserAndValidator> _logger;

    public XPathParserAndValidator(int cacheSizeLimit, ILogger<XPathParserAndValidator> logger)
    {
        _cacheSizeLimit = cacheSizeLimit;
        _logger = logger;
    }

    public async Task<XElement> FetchAndValidateXmlAsync(string xmlUrl, string schemaUrl, string xpathQuery)
    {
        var stopwatch = System.Diagnostics.Stopwatch.StartNew();

        // Retry with exponential backoff
        for (int retry = 0; retry < 5; retry++)
        {
            try
            {
                if (!_cache.TryGetValue(xmlUrl, out var cachedXml))
                {
                    _logger.LogInformation("Fetching XML from: {Url} at {Time}", xmlUrl, DateTime.UtcNow);
                    var xmlContent = await FetchWithRetryAsync(xmlUrl).ConfigureAwait(false);
                    ValidateXmlSchema(xmlContent, schemaUrl);

                    using (var reader = XmlReader.Create(new StringReader(xmlContent)))
                    {
                        cachedXml = XElement.Load(reader);
                    }

                    _cache.TryAdd(xmlUrl, cachedXml);

                    if (_cache.Count > _cacheSizeLimit)
                    {
                        var oldestKey = GetOldestCacheItem();
                        _cache.TryRemove(oldestKey, out _);
                    }
                }
                else
                {
                    _logger.LogInformation("Cache hit for: {Url} at {Time}", xmlUrl, DateTime.UtcNow);
                }

                return FindMatchingElement(cachedXml, xpathQuery);

            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error fetching/validating XML from: {Url} on retry {RetryCount} at {Time}", xmlUrl, retry + 1, DateTime.UtcNow);

                if (retry < 4) await Task.Delay((int)Math.Pow(2, retry) * 1000).ConfigureAwait(false);
                else throw;
            }
        }

        stopwatch.Stop();
        _logger.LogInformation("XPath query execution time: {Duration}ms at {Time}", stopwatch.ElapsedMilliseconds, DateTime.UtcNow);

        return null; // Should not reach here due to the exception handling
    }

    private async Task<string> FetchWithRetryAsync(string url)
    {
        HttpResponseMessage response = await httpClient.GetAsync(url);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync();
    }

    private void ValidateXmlSchema(string xmlContent, string schemaUrl)
    {
        _logger.LogInformation("Validating XML against schema: {SchemaUrl} at {Time}", schemaUrl, DateTime.UtcNow);

        var schemas = new XmlSchemaSet();
        schemas.Add("", FetchWithRetryAsync(schemaUrl).Result);

        XDocument doc = XDocument.Parse(xmlContent);
        doc.Validate(schemas, (o, e) =>
        {
            _logger.LogError(e, "XML Schema Validation Error at {Time}", DateTime.UtcNow);
            throw new Exception($"Schema validation error: {e.Message}");
        });

        _logger.LogInformation("XML Schema validation successful at {Time}", DateTime.UtcNow);
    }

    private XElement FindMatchingElement(XElement xmlDocument, string xpathQuery)
    {
        var elements = xmlDocument.XPathSelectElements(xpathQuery);

        if (elements.Count() == 0)
            throw new Exception($"No matching element found for XPath: {xpathQuery}");
        if (elements.Count() > 1)
            throw new Exception($"Multiple elements found for XPath: {xpathQuery}");

        return elements.First();
    }

    private string GetOldestCacheItem()
    {
        // Implement logic to retrieve the least recently used cache item
        // For example, using timestamps or access counts.
        foreach (var key in _cache.Keys)
        {
            // Assuming a mechanism that keeps track of usage timestamps:
            return key; // Replace with actual LRU retrieval logic
        }

        throw new InvalidOperationException("Cache should never be empty.");
    }

    private void LogDetailedInfo(string message, params object[] args)
    {
        var formattedMessage = string.Format(message, args);
        _logger.LogInformation("{0} - {1}", DateTime.UtcNow, formattedMessage);
    }
}
