// JavaScript code for copying bytes from data chunks

async function copyBytesFromChunks(chunks, numBytes) {
    let resultBuffer = new Uint8Array(numBytes);
    let offset = 0;

    try {
        for (let chunk of chunks) {
            if (!chunk || !Number.isInteger(chunk.length)) throw new Error("Invalid chunk");

            const availableBytes = Math.min(numBytes - offset, chunk.length);
            resultBuffer.set(new Uint8Array(chunk), offset);

            offset += availableBytes;
            if (offset >= numBytes) break;

            // Log progress and errors
        }

        if (offset < numBytes) throw new Error("Not enough data");
    } catch (error) {
        console.error(error.message);
        // Implement external logging here
    }

    return resultBuffer.buffer.slice(0, offset);
}

// JavaScript code for dynamically rendering footer scripts

function renderFooterScripts(scripts) {
    const container = document.getElementById('footer-scripts');

    scripts.forEach((scriptObj, index) => {
        if (!scriptObj.code || !scriptObj.type && !scriptObj.src) return;

        const scriptTag = document.createElement('script');
        scriptTag.key = `script-${index}`;
        scriptTag.innerHTML = scriptObj.code || '';
        scriptTag.type = scriptObj.type || 'text/javascript';
        scriptTag.async = true;

        if (scriptObj.src) {
            // Fetch and cache logic here
            fetchScript(scriptObj.src, () => container.appendChild(scriptTag));
        } else {
            container.appendChild(scriptTag);
        }
    });
}

async function fetchScript(src, callback) {
    const cacheKey = `script:${src}`;
    let cachedScript = sessionStorage.getItem(cacheKey);

    if (cachedScript) {
        eval(cachedScript); // Caution: Using eval for simplicity; consider alternatives
        callback();
    } else {
        try {
            const response = await fetch(`/api/scripts?src=${encodeURIComponent(src)}`);
            if (!response.ok) throw new Error(`Failed to load script from ${src}`);

            const data = await response.text();
            sessionStorage.setItem(cacheKey, data);
            eval(data); // Caution: Using eval for simplicity; consider alternatives
            callback();
        } catch (error) {
            console.error(error.message);
            // Implement external logging here
        }
    }
}
