```java
import java.io.IOException;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.List;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ImageDownloader {

    private static final Logger logger = Logger.getLogger(ImageDownloader.class.getName());
    private final ExecutorService executor;
    private final ConcurrentHashMap<String, byte[]> imageCache = new ConcurrentHashMap<>();
    private final int maxRetries = 3;
    private final long retryDelayMillis = 1000; // initial delay for retries
    private final int cacheSizeLimit = 10; // limit number of images cached

    public ImageDownloader(int threadPoolSize) {
        this.executor = Executors.newFixedThreadPool(threadPoolSize);
    }

    public void downloadImageResources(List<String> imageUrls) {
        List<Callable<Void>> tasks = imageUrls.stream()
                .filter(this::isValidImageUrl)
                .map(url -> (Callable<Void>) () -> downloadWithRetry(url))
                .toList();

        try {
            executor.invokeAll(tasks, 10, TimeUnit.MINUTES); // configurable timeout
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            logger.log(Level.SEVERE, "Download process interrupted", e);
        }
    }

    private boolean isValidImageUrl(String urlString) {
        if (urlString == null || !urlString.startsWith("https://")) return false;

        try {
            new URL(urlString).toURI(); // Validates URL format and accessibility
        } catch (MalformedURLException | IOException e) {
            logger.log(Level.WARNING, "Invalid image URL: " + urlString, e);
            return false;
        }
        return true;
    }

    private void downloadWithRetry(String url) {
        int attempt = 0;
        while (attempt < maxRetries) {
            try {
                byte[] imageData = downloadImage(url);
                if (imageData != null) {
                    imageCache.putIfAbsent(url, imageData);
                    manageCacheSize();
                    return; // Successful download
                }
            } catch (Exception e) {
                logger.log(Level.WARNING, "Download attempt " + (attempt + 1) + " failed for URL: " + url, e);
            }

            try {
                Thread.sleep((long) Math.pow(2, attempt) * retryDelayMillis); // Exponential backoff
            } catch (InterruptedException ie) {
                Thread.currentThread().interrupt();
                return;
            }
            attempt++;
        }
        logger.log(Level.SEVERE, "Failed to download image after retries: " + url);
    }

    private byte[] downloadImage(String urlString) throws IOException {
        if (imageCache.containsKey(urlString)) {
            logger.info("Using cached image for URL: " + urlString);
            return imageCache.get(urlString);
        }

        URL url = new URL(urlString);
        try (var connection = url.openConnection()) {
            // Set timeout
            connection.setConnectTimeout(5000);  // Configurable per need
            connection.setReadTimeout(10000);

            byte[] imageData = connection.getInputStream().readAllBytes();
            logger.info("Downloaded image from: " + urlString);

            return processImage(imageData); // Assume processing like resizing happens here
        }
    }

    private void manageCacheSize() {
        if (imageCache.size() > cacheSizeLimit) {
            imageCache.entrySet().removeIf(entry -> true /* criteria for eviction */);
            logger.info("Cache size managed to limit");
        }
    }

    private byte[] processImage(byte[] imageData) {
        // Integrate with an image processing library
        return imageData; // Placeholder for resizing and converting logic
    }
}
