// Dependency Manager
class DependencyManager {
  constructor(config) {
    this.config = config;
    this.loadedFiles = new Map();
    this.loadingPromises = [];
    this.circularDependencies = new Set();
  }

  async loadFile(url, visited = new Set()) {
    if (this.loadedFiles.has(url)) return this.loadedFiles.get(url);
    if (visited.has(url)) throw new Error(`Circular dependency detected for ${url}`);

    const promise = this.createLoadPromise(url, visited).catch(error => {
      console.error(`Error loading file: ${error.message}`);
      // Log error to a logging service
    });

    this.loadingPromises.push(promise);
    if (this.loadingPromises.length >= this.config.maxConcurrentLoads) {
      await Promise.race(this.loadingPromises);
      this.loadingPromises = [];
    }

    return promise;
  }

  async createLoadPromise(url, visited) {
    visited.add(url);
    const script = document.createElement('script');
    script.src = url;
    script.async = true;

    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        script.remove();
        reject(new Error(`Loading timeout for ${url}`));
      }, this.config.timeout);

      script.onload = () => {
        clearTimeout(timer);
        resolve(url);
      };

      script.onerror = (error) => {
        clearTimeout(timer);
        reject(error);
      };

      document.head.appendChild(script);
    }).then(() => {
      visited.delete(url);
      return url;
    });
  }

  async loadFiles(fileUrls, featureFlags = {}) {
    try {
      const filteredFileUrls = fileUrls.filter(
        (url) => !featureFlags[url] || featureFlags[url]
      );

      await Promise.all(filteredFileUrls.map(url => this.loadFile(url)));

      console.log('All files loaded successfully');
      // Log success to a logging service
    } catch (error) {
      console.error(`Failed to load files: ${error.message}`);
      // Log error to a logging service
    }
  }

  markAsLoaded(url) {
    this.loadedFiles.set(url, true);
  }
}

