struct EncryptionResult {
    int exitCode;
    double encryptionTime;
    size_t memoryUsage;
};

std::vector<EncryptionResult> encryptFiles(
    const std::vector<std::string>& filePaths,
    const std::string& configFilePath
) {
    loadConfiguration(configFilePath);

    auto start = high_resolution_clock::now();
    std::vector<std::thread> threads;
    std::vector<EncryptionResult> results;

    for (const auto& filePath : filePaths) {
        threads.emplace_back([filePath, &results]{
            EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
            if (!ctx) {
                logMessage("Failed to create cipher context");
                return;
            }

            // Example usage of AES with CBC mode
            const EVP_CIPHER* cipher = EVP_aes_256_cbc();

            int exitCode = 0;
            auto fileStart = high_resolution_clock::now();
            encryptFile(filePath, cipher, EVP_CIPH_CBC_MODE, [](int progress) {
                std::cout << "Encryption progress: " << progress << "%" << std::endl;
            });
            auto fileEnd = high_resolution_clock::now();

            double encryptionTime = duration<double>(fileEnd - fileStart).count();
            size_t memoryUsage = get_current_memory_usage(); // Implement this function for your system

            results.push_back({exitCode, encryptionTime, memoryUsage});

            EVP_CIPHER_CTX_free(ctx);
        });
    }

    for (auto &t : threads) {
        t.join();
    }

    auto end = high_resolution_clock::now();
    double totalEncryptionTime = duration<double>(end - start).count();

    logMessage("Total encryption time: " + std::to_string(totalEncryptionTime) + " seconds");

    return results;
}

void encryptFile(const std::string& filePath, const EVP_CIPHER* cipher, int mode, ProgressCallback callback) {
    // Implement file validation and preparation here
    // Example: check if file exists, permissions are correct

    // Initialize encryption context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    // Handle errors for EVP_CIPHER_CTX_new()

    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    getEncryptionKeyAndIV(key, iv); // Implement this function based on your KMS

    int len;
    int ciphertext_len;

    std::ifstream inFile(filePath.c_str(), std::ios::binary);
    if (!inFile) {
        logMessage("Failed to open file: " + filePath);
        return;
    }

    const size_t bufferSize = 4096; // Adjust based on memory management needs
    unsigned char* buffer = new unsigned char[bufferSize];
    unsigned char* ciphertext = new unsigned char[bufferSize + EVP_MAX_BLOCK_LENGTH];

    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        logMessage("Encryption initialization failed");
        return;
    }

    while (inFile.read(reinterpret_cast<char*>(buffer), bufferSize) || inFile.gcount()) {
        // Encrypt
        if (!EVP_EncryptUpdate(ctx, ciphertext, &len, buffer, inFile.gcount())) {
            logMessage("Encryption update failed");
            break;
        }
        ciphertext_len = len;

        // Example progress callback usage
        int progress = static_cast<int>(inFile.tellg() * 100 / inFile.seekg(0, std::ios_base::end).tellg());
        if (callback) {
            callback(progress);
        }

        // Write encrypted data to file or another destination...
    }

    if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        logMessage("Encryption finalization failed");
    }
    ciphertext_len += len;

    // Handle the encryption output...

    inFile.close();
    delete[] buffer;
    delete[] ciphertext;
    EVP_CIPHER_CTX_free(ctx);
}

void loadConfiguration(const std::string &configFilePath) {
    std::ifstream configFile(configFilePath);
    json config;
    if (configFile.is_open()) {
        configFile >> config;
    }
