const fs = require('fs');
const path = require('path');
const { promisify } = require('util');

// Asynchronous version of reduce method for arrays
async function asyncReduce(array, initialValue, callback) {
  let accumulator = initialValue;

  for (let i = 0; i < array.length; i++) {
    try {
      accumulator = await callback(accumulator, array[i], i, array);
    } catch (error) {
      throw new Error(`Error during reduction at index ${i}: ${error.message}`);
    }
  }

  return accumulator;
}

