#include <stdio.h>
#include <stdlib.h>

typedef struct {
  int bitsPerSample;
  int samplesPerPixel;
  int extraSamplesCount;
  char *extraSamplesInfo; // Simplified representation
} ImageInfo;

ImageInfo parseTiff(const char *filePath) {
  ImageInfo info = {0, 0, 0, NULL};

  FILE *file = fopen(filePath, "rb");
  if (!file) {
    fprintf(stderr, "Failed to open file: %s\n", filePath);
    exit(EXIT_FAILURE);
  }

  // Simplified TIFF parsing logic
  unsigned short bitsPerSample;
  unsigned short samplesPerPixel;

  fseek(file, 16, SEEK_SET); // Example offset for bitsPerSample
  fread(&bitsPerSample, sizeof(unsigned short), 1, file);

  fseek(file, 18, SEEK_SET); // Example offset for samplesPerPixel
  fread(&samplesPerPixel, sizeof(unsigned short), 1, file);

  if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 &&
      bitsPerSample != 8 && bitsPerSample != 16) {
    fprintf(stderr, "Unsupported bits per sample: %d\n", bitsPerSample);
    fclose(file);
    exit(EXIT_FAILURE);
  }

  info.bitsPerSample = bitsPerSample;
  info.samplesPerPixel = samplesPerPixel;

  // Example logic for extra samples
  if (samplesPerPixel > 3) {
    int extraSamples = samplesPerPixel - 3;
    info.extraSamplesCount = extraSamples;
    info.extraSamplesInfo = "Extra sample information";
  }

  fclose(file);
  return info;
}

int main() {
  const char *filePath = "example.tiff"; // Replace with your TIFF file path
  ImageInfo info = parseTiff(filePath);

  printf("Bits per Sample: %d\n", info.bitsPerSample);
  printf("Samples per Pixel: %d\n", info.samplesPerPixel);
  if (info.extraSamplesCount > 0) {
    printf("Extra Samples Count: %d\n", info.extraSamplesCount);
    printf("Extra Samples Info: %s\n", info.extraSamplesInfo);
  }

  free(info.extraSamplesInfo); // Assuming dynamic allocation for extra samples info
  return 0;
}
