```javascript
angular.module('dialogApp', [])
  .service('ApiService', function($http, $q) {
    const cache = {};
    let authToken;
    const authRefreshUrl = 'https://api.example.com/auth/refresh';

    // Function to refresh token
    function refreshToken() {
      return $http.post(authRefreshUrl).then(response => {
        authToken = response.data.token;
      });
    }

    this.getDataForField = function(resourceId, field) {
      const cacheKey = `${resourceId}-${field}`;

      if (cache[cacheKey]) {
        return $q.resolve(cache[cacheKey]);
      }

      return $http.get(`https://api.example.com/resources/${resourceId}/${field}`, {
        headers: { 'Authorization': `Bearer ${authToken}` }
      }).then(response => {
        cache[cacheKey] = response.data;
        return response.data;
      }).catch(error => {
        if (error.status === 401) {
          return refreshToken().then(() => this.getDataForField(resourceId, field));
        }
        throw error;
      });
    };
  })
  .controller('DialogController', function($scope, ApiService, $timeout) {
    $scope.dialogFields = [
      { name: 'field1' },
      { name: 'field2' },
      // Add more fields as needed
    ];

    const toRefreshFields = [];

    this.refreshFields = function(resourceId, url, fieldNames) {
      toRefreshFields.length = 0; // Clear previous queue

      fieldNames.forEach(fieldName => {
        if (toRefreshFields.includes(fieldName)) return;

        const field = $scope.dialogFields.find(f => f.name === fieldName);
        if (!field) {
          console.error(`Field ${fieldName} not found`);
          return;
        }

        toRefreshFields.push(field);

        ApiService.getDataForField(resourceId, fieldName).then(data => {
          applyJsonPatch(field, data); // Assume this function applies JSON-PATCH
          updateUI(field);
        }).catch(error => {
          console.error(`Error fetching data for ${fieldName}:`, error);
          retryAfterDelay(() => refreshFields(resourceId, url, [fieldName]), 3000);
        });
      });
    };

    function applyJsonPatch(targetField, patchData) {
      // Apply JSON-PATCH to update only modified parts
      targetField.data = Object.assign({}, targetField.data, patchData);
    }

    function retryAfterDelay(action, delay) {
      $timeout(() => action(), delay);
    }

    function updateUI(field) {
      console.log(`Updated field: ${field.name}`);
      // Add UI updates like removing spinner or updating progress
    }
  });
```

### Explanation

1. **ApiService**: Manages API calls, caching, and token refreshing.
2. **DialogController**: Orchestrates the refresh operation for specified fields using promises to handle concurrency.
3. **Error Handling**: Includes retries with delays on failures, particularly after authentication issues.
4. **UI Updates**: Placeholder functions (`updateUI`, `applyJsonPatch`) are included where UI logic and JSON-PATCH application can be implemented.

