import java.io.File;
import java.nio.file.*;
import java.util.List;
import java.util.concurrent.*;
import java.util.function.Consumer;

// Assume Rule is an interface that all validation rules implement
interface Rule {
    boolean validate(Path file);
}

// Assume MetadataExtractionService is a class with methods to extract metadata
class MetadataExtractionService {
    public void extractMetadata(Path file, Consumer<Metadata> callback) {
        // Dummy implementation
        Metadata metadata = new Metadata(file.getFileName().toString(), "Author", "2023-10-01");
        callback.accept(metadata);
    }
}

// Assume Metadata is a class representing extracted metadata
class Metadata {
    private String fileName;
    private String author;
    private String date;

    public Metadata(String fileName, String author, String date) {
        this.fileName = fileName;
        this.author = author;
        this.date = date;
    }

    @Override
    public String toString() {
        return "Metadata{" +
                "fileName='" + fileName + '\'' +
                ", author='" + author + '\'' +
                ", date='" + date + '\'' +
                '}';
    }
}

public class FileProcessor {

    private static final int THREAD_POOL_SIZE = 10;

    public void processFileBatchWithValidationAndMetadata(
            String inputDirectory,
            String outputDirectory,
            List<Class<? extends Rule>> validationRules,
            MetadataExtractionService metadataService) {

        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        try (Stream<Path> paths = Files.walk(Paths.get(inputDirectory))) {
            paths.filter(Files::isRegularFile)
                    .forEach(file -> executor.submit(() -> processFile(file, outputDirectory, validationRules, metadataService)));
        } catch (IOException e) {
            System.err.println("Error accessing input directory: " + e.getMessage());
        }

        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    private void processFile(Path file, String outputDirectory, List<Class<? extends Rule>> validationRules, MetadataExtractionService metadataService) {
        try {
            System.out.println("Processing file: " + file.getFileName());

            // Load and apply validation rules
            boolean isValid = true;
            for (Class<? extends Rule> ruleClass : validationRules) {
                Rule ruleInstance = ruleClass.getDeclaredConstructor().newInstance();
                if (!ruleInstance.validate(file)) {
                    System.err.println("Validation failed for file: " + file.getFileName() + " using rule: " + ruleClass.getName());
                    isValid = false;
                    break; // Stop further validations on failure
                }
            }

            if (isValid) {
                // Extract metadata asynchronously
                metadataService.extractMetadata(file, metadata -> {
                    System.out.println("Extracted Metadata for file: " + metadata);

                    // Write valid file and metadata to output directory
                    Path destination = Paths.get(outputDirectory, file.getFileName().toString() + ".validated");
                    Files.copy(file, destination, StandardCopyOption.REPLACE_EXISTING);

                    // For demonstration, let's print the metadata details
                    System.out.println("Metadata: " + metadata);
                });
            }

        } catch (Exception e) {
            System.err.println("Error processing file: " + file.getFileName() + ", Error: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // Example usage
        List<Class<? extends Rule>> validationRules = List.of(SampleRule.class);
        MetadataExtractionService metadataService = new MetadataExtractionService();

        FileProcessor processor = new FileProcessor();
        processor.processFileBatchWithValidationAndMetadata(
                "inputDirectoryPath",
                "outputDirectoryPath",
                validationRules,
                metadataService
        );
    }
}

// Dummy Rule implementation for demonstration
class SampleRule implements Rule {
    @Override
    public boolean validate(Path file) {
        // Implement actual validation logic here
        return true;
    }
}
