```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using UnityEngine;

public interface IRangeProvider
{
    double? GetMinimum();
    double? GetMaximum();
}

public interface IDistributionFunction
{
    double Generate(double minimum, double maximum);
}

public class CustomRandomGenerator : IDisposable
{
    private readonly object _lock = new object();
    private Random _random;
    private int _seed;
    private Dictionary<string, Func<double>> _distributionFunctions;

    public event Action<int> OnNewSeedGenerated;

    public CustomRandomGenerator(int seed)
    {
        SetSeed(seed);
        _distributionFunctions = new Dictionary<string, Func<double>>();
    }

    public void Dispose()
    {
        if (_random != null)
            _random.Dispose();
    }

    private void SetSeed(int seed)
    {
        lock (_lock)
        {
            _seed = seed;
            UnityEngine.Random.InitState(seed);
            OnNewSeedGenerated?.Invoke(_seed);

            _random = new Random(seed);
        }
    }

    public T CustomRange<T>(double min, double max, bool inclusiveMin, bool inclusiveMax) where T : struct
    {
        lock (_lock)
        {
            try
            {
                if (min > max || (inclusiveMin && inclusiveMax && EqualityComparer<double>.Default.Equals(min, max)))
                    throw new ArgumentException("Invalid range provided.");

                Func<double> generateValue = () =>
                {
                    double value;
                    var rangeType = (inclusiveMin ? 1 : 0) + (inclusiveMax ? 2 : 0);

                    switch (rangeType)
                    {
                        case 0: // Exclusive-Exclusive
                            value = _random.NextDouble() * (max - min) + min;
                            return Math.Min(Math.Max(min, value), max - double.Epsilon);
                        case 1: // Inclusive-Minimum
                            value = _random.NextDouble() * (max - min) + min;
                            return Math.Min(value, max - double.Epsilon);
                        case 2: // Maximum-Inclusive
                            value = _random.NextDouble() * (max - min) + min;
                            return Math.Max(value, min + double.Epsilon);
                        default: // Inclusive-Inclusive
                            value = _random.NextDouble() * (max - min) + min;
                            return value;
                    }
                };

                if (typeof(T).IsEnum)
                {
                    var values = Enum.GetValues(typeof(T));
                    int index = (int)Math.Floor(generateValue());
                    return (T)values.GetValue(index);
                }

                // If T is a numeric type, convert accordingly
                TypeConverter converter = TypeDescriptor.GetConverter(typeof(T));

                if (!converter.IsValid(value: generateValue()))
                    throw new InvalidOperationException("Cannot convert the generated value to the specified type.");

                return (T)converter.ConvertFrom(generateValue());
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error generating random range: {ex.Message}");
                throw;
            }
        }
    }

    public void LoadRangeLimitsFromXml(string filePath, IRangeProvider provider)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException("Configuration file not found.");

        try
        {
            // Simulated XML loading process for simplicity
            var xmlContent = File.ReadAllText(filePath);
            double? min = provider.GetMinimum();
            double? max = provider.GetMaximum();

            if (min == null || max == null)
                throw new InvalidOperationException("Invalid range limits in configuration.");

            // Assuming the loaded values are parsed from XML content into the provider
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading range limits: {ex.Message}");
            throw;
        }
    }

    public void RegisterCustomDistribution(string name, Func<double> distributionFunction)
    {
        if (_distributionFunctions.ContainsKey(name))
            throw new ArgumentException("A distribution with this name already exists.");

        _distributionFunctions[name] = distributionFunction;
    }

    public double GenerateWithCustomDistribution(string name, double min, double max)
    {
        lock (_lock)
        {
            if (!_distributionFunctions.TryGetValue(name, out var func))
                throw new ArgumentException("The specified distribution function does not exist.");

            return Math.Max(min, Math.Min(max, func()));
        }
    }

    public void ConfigureFromConsole()
    {
        Console.WriteLine("Enter seed:");
        int seed = int.Parse(Console.ReadLine());
        SetSeed(seed);

        Console.WriteLine("Enter range minimum:");
        double min = double.Parse(Console.ReadLine());

        Console.WriteLine("Enter range maximum:");
        double max = double.Parse(Console.ReadLine());

        // Further configuration logic...
    }
}

// Example Usage:
class Program
{
    static void Main(string[] args)
    {
        var generator = new CustomRandomGenerator(seed: 12345);

        try
        {
            int randomInt = generator.CustomRange(1, 10, true, false); // Range [1, 9]
            double randomDouble = generator.CustomRange(0.5, 2.5, true, true); // Range [0.5, 2.5]

            Console.WriteLine($"Random Int: {randomInt}, Random Double: {randomDouble}");
        }
        finally
        {
            generator.Dispose();
        }
    }
}
```

### Key Points

- **Seeding**: Uses both `UnityEngine.Random.Seed` and a standard C# random for different types of seeds.
- **Thread Safety**: Achieved using locks to synchronize access to shared resources.
- **Custom Distribution**: Allows users to register custom distribution functions.
- **Error Handling**: Uses exception handling to log errors during random generation.
- **Configuration**: Demonstrates loading range limits from an XML configuration file and provides a basic console-based interface for user input. 

