typedef struct {
    int int_value;
} record;

typedef struct {
    char *file_name;
    time_t last_modified;
} JSFile;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define NUM_RECORDS 100
#define JS_FILES_COUNT 5

void *load_js_file(void *arg) {
    // Simulate loading a file and executing it.
    JSFile *file = (JSFile *)arg;
    printf("Loading JavaScript File: %s\n", file->file_name);
    sleep(1); // Simulate delay for loading
    return NULL;
}

int has_circular_dependency(const char *file, const char *dependencies[], int size) {
    for (int i = 0; i < size; ++i) {
        if (strcmp(file, dependencies[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

void initialize_and_execute() {
    long *offsets = malloc(NUM_RECORDS * sizeof(long));
    int *keys = malloc(NUM_RECORDS * sizeof(int));
    record *records = malloc(NUM_RECORDS * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_RECORDS; ++i) {
        offsets[i] = rand() % 10000;
        keys[i] = rand() % 1000;
        records[i].int_value = rand() % 100;
    }

    NFAPI_CRC_INDICATION_PDU_T *nfapi_cdu_list = malloc(JS_FILES_COUNT * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfapi_cdu_list) {
        fprintf(stderr, "Memory allocation failed for nfapi_cdu_list\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < JS_FILES_COUNT; ++i) {
        nfapi_cdu_list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        nfapi_cdu_list[i].RNTI = rand() % 10000;
        nfapi_cdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    JSFile js_files[JS_FILES_COUNT] = {
        {"file1.js", time(NULL)},
        {"file2.js", time(NULL)},
        {"file3.js", time(NULL)},
        {"file4.js", time(NULL)},
        {"file5.js", time(NULL)}
    };

    pthread_t threads[JS_FILES_COUNT];
    for (int i = 0; i < JS_FILES_COUNT; ++i) {
        if (!has_circular_dependency(js_files[i].file_name, js_files[i].file_name, i)) {
            if (pthread_create(&threads[i], NULL, load_js_file, &js_files[i]) != 0) {
                fprintf(stderr, "Error creating thread for file: %s\n", js_files[i].file_name);
            }
        } else {
            fprintf(stderr, "Circular dependency detected in file: %s\n", js_files[i].file_name);
        }
    }

    for (int i = 0; i < JS_FILES_COUNT; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup
    free(offsets);
    free(keys);
    free(records);
    free(nfapi_cdu_list);

    printf("All JavaScript files loaded and executed.\n");
}

int main() {
    srand(time(NULL));
    initialize_and_execute();
    return 0;
}
