```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using Microsoft.Extensions.Logging;

public class AesGcmEncryptionService
{
    private readonly ILogger<AesGcmEncryptionService> _logger;
    private readonly IKeyManagementService _keyManagementService;

    public AesGcmEncryptionService(ILogger<AesGcmEncryptionService> logger, IKeyManagementService keyManagementService)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _keyManagementService = keyManagementService ?? throw new ArgumentNullException(nameof(keyManagementService));
    }

    public byte[] Encrypt(byte[] plaintext, byte[] additionalAuthenticatedData)
    {
        try
        {
            var encryptionKey = RetrieveEncryptionKey();
            using var aesGcm = new AesGcm(encryptionKey);

            byte[] nonce = new byte[AesGcm.NonceByteSizes.MaxSize];
            RandomNumberGenerator.Fill(nonce);

            byte[] ciphertext = new byte[plaintext.Length];
            byte[] tag = new byte[AesGcm.TagByteSizes.MaxSize];

            aesGcm.Encrypt(nonce, plaintext, ciphertext, tag, additionalAuthenticatedData);

            using var memoryStream = new MemoryStream();
            memoryStream.Write(nonce, 0, nonce.Length);
            memoryStream.Write(tag, 0, tag.Length);
            memoryStream.Write(ciphertext, 0, ciphertext.Length);

            return memoryStream.ToArray();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Encryption failed.");
            throw;
        }
    }

    public byte[] Decrypt(byte[] encryptedData, byte[] additionalAuthenticatedData)
    {
        try
        {
            var encryptionKey = RetrieveEncryptionKey();

            using var aesGcm = new AesGcm(encryptionKey);

            int nonceSize = AesGcm.NonceByteSizes.MaxSize;
            int tagSize = AesGcm.TagByteSizes.MaxSize;

            byte[] nonce = new byte[nonceSize];
            byte[] tag = new byte[tagSize];

            using var memoryStream = new MemoryStream(encryptedData);
            memoryStream.Read(nonce, 0, nonce.Length);
            memoryStream.Read(tag, 0, tag.Length);

            int ciphertextLength = encryptedData.Length - nonceSize - tagSize;
            byte[] ciphertext = new byte[ciphertextLength];
            memoryStream.Read(ciphertext, 0, ciphertext.Length);

            byte[] plaintext = new byte[ciphertextLength];

            aesGcm.Decrypt(nonce, ciphertext, tag, plaintext, additionalAuthenticatedData);

            return plaintext;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Decryption failed.");
            throw;
        }
    }

    private byte[] RetrieveEncryptionKey()
    {
        try
        {
            var keyId = "your-key-id"; // Replace with actual key ID retrieval logic
            return _keyManagementService.GetKey(keyId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to retrieve encryption key.");
            throw;
        }
    }

    public void Dispose()
    {
        // Implement IDisposable if required for KMS client or other resources
    }
}

public interface IKeyManagementService
{
    byte[] GetKey(string keyId);
}
