```rust
use clap::{App, Arg};
use env_logger::Builder;
use log::{info, warn, error};
use signal_hook::{iterator::Signals, SIGINT};
use tokio::signal::ctrl_c;
use tokio_postgres::{NoTls, Error as PgError};
use reqwest::Client as ReqwestClient;

mod network;
mod database;
mod file_ops;
mod utils;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let matches = App::new("Async Rust CLI")
        .version("1.0")
        .author("Author Name <author@example.com>")
        .about("Performs various async operations based on command line input.")
        .arg(
            Arg::with_name("command")
                .help("The operation to perform: fetch, query, readwrite")
                .required(true)
                .index(1),
        )
        .get_matches();

    setup_logging(matches.is_present("verbose"));

    let command = matches.value_of("command").unwrap();
    match command {
        "fetch" => network::execute_fetch().await?,
        "query" => database::execute_query().await?,
        "readwrite" => file_ops::perform_file_operations().await?,
        _ => eprintln!("Invalid command"),
    }

    // Handling graceful shutdown on SIGINT
    let signals = Signals::new(&[SIGINT])?;
    tokio::spawn(async move {
        for _ in signals.forever() {
            info!("Received SIGINT, shutting down gracefully...");
            std::process::exit(0);
        }
    });

    Ok(())
}

fn setup_logging(verbose: bool) {
    let level = if verbose { "debug" } else { "info" };
    Builder::new()
        .format(|buf, record| writeln!(buf, "{} - {}", record.level(), record.args()))
        .filter_level(log::LevelFilter::from_str(level).unwrap())
        .init();
}

// network.rs
pub mod network {
    use reqwest::Client;
    use log::{info, error};
    use std::env;

    pub async fn execute_fetch() -> Result<(), Box<dyn std::error::Error>> {
        let api_key = env::var("API_KEY").expect("API_KEY must be set");
        let client = Client::new();
        let response = client.get("https://api.example.com/data")
            .header("Authorization", format!("Bearer {}", api_key))
            .send()
            .await?;

        if response.status().is_success() {
            info!("Successfully fetched data: {:?}", response.text().await?);
        } else {
            error!("Failed to fetch data: {:?}", response.status());
        }

        Ok(())
    }
}

// database.rs
pub mod database {
    use tokio_postgres::{Client, NoTls};
    use log::{info, error};

    pub async fn execute_query() -> Result<(), Box<dyn std::error::Error>> {
        let conn_str = env!("DATABASE_URL");
        let (client, connection) =
            tokio_postgres::connect(conn_str.parse()?, NoTls).await?;

        tokio::spawn(async move {
            if let Err(e) = connection.await {
                error!("Connection error: {}", e);
            }
        });

        let rows = client.query("SELECT * FROM users", &[]).await?;

        for row in rows {
            info!("User: {:?}", row.get::<_, String>(0));
        }

        Ok(())
    }
}

// file_ops.rs
pub mod file_ops {
    use tokio::fs;
    use log::{info, error};

    pub async fn perform_file_operations() -> Result<(), Box<dyn std::error::Error>> {
        let content = fs::read_to_string("input.txt").await?;
        info!("Read from input.txt: {}", content);

        fs::write("output.txt", &content).await?;
        info!("Written to output.txt");

        Ok(())
    }
}

// utils.rs
pub mod utils {
    use log::{info, error};

    pub fn retry<F>(operation: F) -> Result<(), Box<dyn std::error::Error>>
    where
        F: Fn() -> Result<(), Box<dyn std::error::Error>>,
    {
        let mut attempts = 0;
        loop {
            match operation() {
                Ok(_) => return Ok(()),
                Err(e) if attempts < 3 => {
                    attempts += 1;
                    error!("Attempt {} failed: {}. Retrying...", attempts, e);
                }
                Err(e) => return Err(Box::new(e)),
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_network_fetch() {
        network::execute_fetch().await.unwrap();
    }

    #[tokio::test]
    async fn test_database_query() {
        database::execute_query().await.unwrap();
    }

    #[tokio::test]
    async fn test_file_operations() {
        file_ops::perform_file_operations().await.unwrap();
    }
}
```

### Explanation
- **Modules**: The code is organized into modules (`network`, `database`, `file_ops`, and `utils`) to separate concerns.
- **Logging**: Uses the `env_logger` crate for logging with configurable levels.
- **Signal Handling**: Handles graceful shutdown on SIGINT using both `signal_hook` and Tokio's async capabilities.
- **Environment Variables**: Fetches API keys and database URLs from environment variables.
- **Asynchronous Functions**: Demonstrates fetching data over HTTP, querying a PostgreSQL database, and performing file I/O operations asynchronously with error handling.
- **CLI**: Uses `clap` for command-line argument parsing.
- **Tests**: Includes simple tests for each module's main function.

Ensure you have the appropriate dependencies in your `Cargo.toml`, such as `tokio`, `reqwest`, `tokio-postgres`, `clap`, and `env_logger`. Adjust the database connection string and API endpoints to match your actual configuration.

