using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;
using Newtonsoft.Json;
using HtmlAgilityPack;

public class HttpPostHandler
{
    private readonly IUpdateService _updateService;
    private readonly ILogger<HttpPostHandler> _logger;
    private readonly IMemoryCache _cache;
    private readonly IDatabaseLogger _databaseLogger;
    private readonly INotificationService _notificationService;
    private static readonly TimeSpan RateLimitPeriod = TimeSpan.FromMinutes(1);
    private static readonly int MaxRequestsPerMinute = 60;

    public HttpPostHandler(
        IUpdateService updateService,
        ILogger<HttpPostHandler> logger,
        IMemoryCache cache,
        IDatabaseLogger databaseLogger,
        INotificationService notificationService)
    {
        _updateService = updateService;
        _logger = logger;
        _cache = cache;
        _databaseLogger = databaseLogger;
        _notificationService = notificationService;
    }

    [HttpPost("UpdateElement")]
    public async Task<IActionResult> UpdateElement(string pageSectionId, string elementId, string encryptedHtmlContent)
    {
        try
        {
            // Rate Limiting Logic
            var ipAddress = HttpContext.Connection.RemoteIpAddress.ToString();
            var requestCount = _cache.GetOrCreate(ipAddress, entry =>
            {
                entry.AbsoluteExpirationRelativeToNow = RateLimitPeriod;
                return 0;
            });

            if (requestCount >= MaxRequestsPerMinute)
                return StatusCode(429, "Too Many Requests");

            _cache.Set(ipAddress, ++requestCount);

            // Decrypt HTML Content
            string decryptedHtmlContent = await Task.Run(() => DecryptHtmlContent(encryptedHtmlContent));

            // Validate Decrypted HTML
            if (!IsValidHtml(decryptedHtmlContent))
                return BadRequest("Invalid HTML content.");

            // Update Element with Service
            bool isUpdated = _updateService.UpdateElement(pageSectionId, elementId, decryptedHtmlContent);

            if (!isUpdated)
                return StatusCode(500, "Failed to update the element.");

            // Logging for Auditing Purposes
            _databaseLogger.LogUpdate(ipAddress, pageSectionId, elementId, DateTime.UtcNow);

            // Cache Management
            ManageCache(pageSectionId, elementId, decryptedHtmlContent);

            // Send Notification in case of critical updates
            if (isUpdated && IsCriticalUpdate(decryptedHtmlContent))
                await _notificationService.SendAlertAsync("Critical update performed.");

            return Ok();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing UpdateElement request.");
            _notificationService.SendAlertAsync($"Error: {ex.Message}");
            return StatusCode(500, "Internal server error");
        }
    }

    private string DecryptHtmlContent(string encryptedText)
    {
        byte[] key = Encoding.UTF8.GetBytes("your-32-byte-key-here"); // Must be 24 or 32 bytes
        byte[] iv = Encoding.UTF8.GetBytes("your-16-byte-iv--"); // Must be 16 bytes

        using (TripleDES tripleDes = TripleDESCryptoServiceProvider.Create())
        {
            tripleDes.Key = key;
            tripleDes.IV = iv;

            ICryptoTransform decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV);

            byte[] buffer = Convert.FromBase64String(encryptedText);
            using (MemoryStream msDecrypt = new MemoryStream(buffer))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                    {
                        return srDecrypt.ReadToEnd();
                    }
                }
            }
        }
    }

    private bool IsValidHtml(string htmlContent)
    {
        var allowedTags = new[] { "p", "div", "span", "a" }; // Extend as needed
        var doc = new HtmlDocument();
        doc.LoadHtml(htmlContent);

        foreach (var node in doc.DocumentNode.SelectNodes("//*"))
        {
            if (!allowedTags.Contains(node.Name))
                return false;

            foreach (var attribute in node.Attributes)
            {
                if (!new[] { "href", "title" }.Contains(attribute.Name)) // Extend as needed
                    return false;
            }
        }

        return true; // Extend with schema validation as necessary
    }

    private void ManageCache(string pageSectionId, string elementId, string htmlContent)
    {
        var cacheKey = $"{pageSectionId}-{elementId}";
        _cache.Set(cacheKey, htmlContent, TimeSpan.FromMinutes(5)); // Adjust caching strategy as needed
    }

    private bool IsCriticalUpdate(string content)
    {
        // Define logic for what constitutes a critical update
        return false; 
    }
}

