using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml;
using System.Xml.Schema;
using System.Xml.XPath;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

public interface IXmlCacheProvider
{
    XmlDocument GetOrAdd(string key, Func<string, XmlDocument> valueFactory);
}

public class ConcurrentXmlCacheProvider : IXmlCacheProvider
{
    private readonly ConcurrentDictionary<string, Lazy<XmlDocument>> _cache = new();

    public XmlDocument GetOrAdd(string key, Func<string, XmlDocument> valueFactory)
    {
        return _cache.GetOrAdd(key, k => new Lazy<XmlDocument>(() =>
        {
            var doc = new XmlDocument();
            valueFactory(k).LoadXml(doc.OuterXml);
            return doc;
        })).Value;
    }
}

public class DynamicXmlManager
{
    private readonly IOptionsMonitor<AppSettings> _settings;
    private readonly ILogger<DynamicXmlManager> _logger;
    private readonly HttpClient _httpClient;
    private readonly IXmlCacheProvider _cacheProvider;

    public DynamicXmlManager(
        IOptionsMonitor<AppSettings> settings,
        ILogger<DynamicXmlManager> logger,
        HttpClient httpClient,
        IXmlCacheProvider cacheProvider)
    {
        _settings = settings;
        _logger = logger;
        _httpClient = httpClient;
        _cacheProvider = cacheProvider;
    }

    public XmlDocument ParseAndValidateXml(string xmlContent, string xsdPath)
    {
        var xmlDoc = new XmlDocument();
        xmlDoc.LoadXml(xmlContent);

        var schemaSet = new XmlSchemaSet();
        schemaSet.Add("", xsdPath);

        xmlDoc.Schemas.Add(schemaSet);
        xmlDoc.Validate((sender, e) =>
        {
            _logger.LogError(e.Message);
            throw new XmlSchemaValidationException(e.Message);
        });

        return xmlDoc;
    }

    public XmlNode GetElementByXPath(XmlDocument xmlDocument, string xpathExpression)
    {
        ValidateUserInput(xpathExpression);

        var stopwatch = Stopwatch.StartNew();
        var nav = xmlDocument.CreateNavigator();
        var nodes = nav.Select(xpathExpression).Cast<XmlNode>().ToArray();

        if (nodes.Length == 0) throw new InvalidOperationException("No matching element found.");
        if (nodes.Length > 1) throw new InvalidOperationException("Multiple elements match the XPath expression.");

        _logger.LogInformation($"XPath query executed in {stopwatch.ElapsedMilliseconds} ms");
        return nodes[0];
    }

    private void ValidateUserInput(string xpathExpression)
    {
        try
        {
            XPathNodeIterator dummy = null;
            dummy.MoveNext();
        }
        catch (XmlException ex)
        {
            _logger.LogError($"Invalid XPath: {xpathExpression}. Error: {ex.Message}");
            throw new ArgumentException("Provided XPath expression is invalid.", nameof(xpathExpression));
        }
    }

    public async Task RefreshCacheIfNeeded(string url, string cacheKey)
    {
        var settings = _settings.CurrentValue;

        if (settings.AutoRefreshCache)
        {
            using var response = await _httpClient.GetAsync(url);
            if (response.IsSuccessStatusCode)
            {
                var newContent = await response.Content.ReadAsStringAsync();
                _cacheProvider.GetOrAdd(cacheKey, key => new XmlDocument { InnerXml = newContent });

                _logger.LogInformation($"XML cache refreshed for key: {cacheKey}");
            }
        }
    }

    public void MonitorSchemaChanges(string schemaUrl)
    {
        Task.Run(async () =>
        {
            while (true)
            {
                var settings = _settings.CurrentValue;
                using var response = await _httpClient.GetAsync(schemaUrl);

                if (response.IsSuccessStatusCode)
                {
                    var currentSchema = await response.Content.ReadAsStringAsync();
                    if (_lastKnownSchema != currentSchema)
                    {
                        _logger.LogInformation("XML Schema has changed. Revalidating cached documents.");

                        // Logic to revalidate or refresh the cache
                        // Example: Clear relevant caches and reload

                        _lastKnownSchema = currentSchema;
                    }
                }

                await Task.Delay(settings.SchemaCheckInterval);
            }
        });
    }

    private string _lastKnownSchema;

    public XmlDocument ConvertToInMemoryRepresentation(string xmlContent)
    {
        var xmlDoc = new XmlDocument();
        xmlDoc.LoadXml(xmlContent);

        // Convert to a more efficient representation if needed
        return xmlDoc; 
    }
}

public class AppSettings
{
