import json
import os
import asyncio
import hashlib
import random
import string
from typing import List, Callable, Dict

class BaseClass:
    _registry = {}

    def __init__(self, data: dict):
        self.data = data

    @classmethod
    def from_json_string(cls, json_str: str):
        data = json.loads(json_str)
        cls_id = data.get('id')
        if cls_id in cls._registry:
            return cls._registry[cls_id](data)
        raise ValueError(f"No factory function registered for ID: {cls_id}")

    def to_json_string(self) -> str:
        return json.dumps(self.data)

    @classmethod
    def register_factory(cls, id_: str, factory_func: Callable):
        cls._registry[id_] = factory_func

class JSONHandler(BaseClass):

    async def load_files_async(self, file_paths: List[str]):
        loop = asyncio.get_event_loop()
        tasks = [loop.run_in_executor(None, self.load_file, path) for path in file_paths]
        await asyncio.gather(*tasks)

    def load_file(self, file_path):
        try:
            with open(file_path, 'r') as file:
                data = json.load(file)
                return BaseClass(data)
        except Exception as e:
            print(f"Error loading {file_path}: {e}")
            raise

    @staticmethod
    def deserialize_byte_array(byte_array: bytes) -> str:
        try:
            # Simulating Java-like serialization with Python
            decoded_str = byte_array.decode('utf-8')
            return decoded_str
        except Exception as e:
            print(f"Deserialization error: {e}")
            raise

    @staticmethod
    def generate_random_string(byte_array: bytes) -> str:
        random.seed(byte_array)
        return ''.join(random.choices(string.ascii_letters + string.digits, k=10))

    @staticmethod
    def hash_password(password: str) -> str:
        return hashlib.sha256(password.encode()).hexdigest()

    def manipulate_forward_list(self, forward_list: List[str], first_str: str, second_str: str, position_index: int = None):
        try:
            if position_index is not None and (position_index < 0 or position_index >= len(forward_list)):
                raise IndexError("Position index out of bounds")

            found = False
            for i in range(position_index if position_index else 0, len(forward_list)):
                if forward_list[i] == first_str:
                    forward_list.insert(i + 1, second_str)
                    found = True

            if not found and position_index is None:
                forward_list.append(second_str)

        except Exception as e:
            print(f"Error manipulating list: {e}")
            raise

    def load_string_pairs_from_file(self, file_path):
        try:
            with open(file_path, 'r') as file:
                lines = file.readlines()
                return [tuple(line.strip().split(',')) for line in lines]
        except Exception as e:
            print(f"Error reading from {file_path}: {e}")
            raise

    def process_files(self, files: List[str], threshold: int = 5):
        try:
            if len(files) > threshold:
                asyncio.run(self.load_files_async(files))
            else:
                for file in files:
                    self.load_file(file)
        except Exception as e:
            print(f"Error processing files: {e}")

# Example of subclass registration
def example_subclass_factory(data):
    return JSONHandler(data)

BaseClass.register_factory("example_id", example_subclass_factory)

# Usage
handler = JSONHandler({})
files_to_process = ['file1.json', 'file2.json']
handler.process_files(files_to_process)

byte_array_example = b'some_byte_data'
random_string = handler.generate_random_string(byte_array_example)
hashed_password = handler.hash_password("mypassword123")

print(f"Random String: {random_string}")
print(f"Hashed Password: {hashed_password}")

# Example of forward list manipulation
forward_list = ["start", "middle", "end"]
handler.manipulate_forward_list(forward_list, "middle", "inserted")
print(forward_list)
