import java.util.concurrent.*;
import java.util.logging.*;
import java.util.Map;
import java.util.HashMap;
import java.util.List;

public class TaskService {

    private static final Logger logger = Logger.getLogger(TaskService.class.getName());
    private final ExecutorService executorService;
    private final Map<String, String> cache; // Simple in-memory cache for API responses
    private final ScheduledExecutorService scheduler;
    private int maxThreads;
    private final long apiRateLimit;

    public TaskService(int initialMaxThreads, long apiRateLimit) {
        this.maxThreads = initialMaxThreads;
        this.apiRateLimit = apiRateLimit;
        this.executorService = new ThreadPoolExecutor(
                0, maxThreads,
                60L, TimeUnit.SECONDS,
                new SynchronousQueue<>(),
                Executors.defaultThreadFactory()
        );
        this.cache = new ConcurrentHashMap<>();
        this.scheduler = Executors.newScheduledThreadPool(1);
    }

    public void adjustThreadPoolSize(int newSize) {
        if (newSize > executorService.getMaximumPoolSize()) {
            executorService.setMaximumPoolSize(newSize);
        }
    }

    private String fetchFromApi(String taskId, String taskData) throws InterruptedException {
        // Simulated API call
        Thread.sleep((long)(Math.random() * 1000)); // simulate network latency

        if (cache.containsKey(taskId)) {
            return cache.get(taskId); // retrieve from cache if available
        }

        // Fetch data from third-party API
        String response = "api-response-for-" + taskId; // Placeholder for actual API call
        cache.put(taskId, response);

        return response;
    }

    public void executeTask(String taskId, String taskData) {
        Runnable task = () -> {
            try {
                logger.info("Executing task: " + taskId);
                String apiResponse = fetchFromApi(taskId, taskData);
                // Process the API response
                processApiResponse(apiResponse);
                logger.info("Successfully executed task: " + taskId);

            } catch (InterruptedException e) {
                logger.severe("Task execution interrupted for: " + taskId);
            } catch (Exception e) {
                logger.warning("Failed to execute task: " + taskId + ", retrying...");
                retryTask(taskId, taskData); // Implement a retry policy
            }
        };

        executorService.submit(task);
    }

    private void processApiResponse(String response) {
        // Process the API response
    }

    private void retryTask(String taskId, String taskData) {
        int retries = 3;
        while (retries > 0) {
            try {
                executeTask(taskId, taskData);
                return;
            } catch (Exception e) {
                retries--;
                logger.warning("Retry failed for task: " + taskId + ", attempts left: " + retries);
            }
        }
    }

    public void shutdown() {
        executorService.shutdown();
        scheduler.shutdown();
    }

    public static void main(String[] args) {
        TaskService service = new TaskService(10, 1000L);

        // Example usage
        for (int i = 0; i < 20; i++) {
            service.executeTask("task-" + i, "data");
        }

        service.shutdown();
    }

    public static void runLoadBalancerSimulation(TaskService service) {
        List<String> taskIds = List.of("task-1", "task-2", "task-3");

        for (String taskId : taskIds) {
            service.executeTask(taskId, "data");
            try {
                Thread.sleep(500); // simulate varying load
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        service.adjustThreadPoolSize(20);
    }
}
