```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <mutex>
#include <thread>
#include <sstream>
#include <memory>
#include <stdexcept>
#include "rapidjson/document.h"
#include "rapidjson/writer.h"
#include "rapidjson/stringbuffer.h"

class Node {
public:
    int key;
    std::string value;
    int version;

    Node(int k, const std::string& v, int ver = 0) : key(k), value(v), version(ver) {}
};

using NodeList = std::vector<Node>;

class DistributedCacheManager {
private:
    NodeList nodes;
    mutable std::mutex mtx;
    std::ofstream logFile;

public:
    DistributedCacheManager(const std::string& configFilePath, const std::string& logPath)
        : logFile(logPath, std::ios_base::app) {
        if (!logFile.is_open()) throw std::runtime_error("Failed to open log file");
        loadConfig(configFilePath);
    }

    ~DistributedCacheManager() {
        logFile.close();
    }

    void loadConfig(const std::string& configFilePath) {
        std::ifstream configFile(configFilePath);
        if (!configFile.is_open()) throw std::runtime_error("Failed to open configuration file");

        rapidjson::Document doc;
        configFile >> doc; // Assuming the config is already a JSON document

        for (const auto& kv : doc.GetObject()) {
            int key = kv.name.GetUint();
            std::string value = kv.value.GetString();
            nodes.emplace_back(key, value);
            logOperation("Loaded", "Key: " + std::to_string(key) + ", Value: " + value);
        }
    }

    void addNode(const Node& node) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::find_if(nodes.begin(), nodes.end(), [&node](const Node& n){ return n.key == node.key; });
        if (it != nodes.end()) throw std::runtime_error("Key already exists");

        nodes.push_back(node);
        logOperation("Added", "Key: " + std::to_string(node.key) + ", Value: " + node.value);
    }

    void updateNode(int key, const std::string& newValue, int newVersion) {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = std::find_if(nodes.begin(), nodes.end(), [&key](const Node& n){ return n.key == key; });
        if (it == nodes.end()) throw std::runtime_error("Key not found");
        if (newVersion <= it->version) throw std::runtime_error("Invalid version ID");

        it->value = newValue;
        it->version = newVersion;

        logOperation("Updated", "Key: " + std::to_string(key) + ", New Value: " + newValue);
    }

    void removeNode(int key) {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = std::remove_if(nodes.begin(), nodes.end(), [&key](const Node& n){ return n.key == key; });
        if (it == nodes.end()) throw std::runtime_error("Key not found");

        logOperation("Removed", "Key: " + std::to_string(key));
        nodes.erase(it, nodes.end());
    }

    std::string serializeToJson() const {
        rapidjson::Document doc;
        doc.SetObject();

        for (const auto& node : nodes) {
            rapidjson::Value keyVal(node.key);
            rapidjson::Value valueVal(node.value.c_str(), doc.GetAllocator());
            rapidjson::Value versionVal(node.version);

            rapidjson::Value obj(rapidjson::kObjectType);
            obj.AddMember("key", keyVal, doc.GetAllocator());
            obj.AddMember("value", valueVal, doc.GetAllocator());
            obj.AddMember("version", versionVal, doc.GetAllocator());

            doc.PushBack(obj, doc.GetAllocator());
        }

        rapidjson::StringBuffer buffer;
        rapidjson::Writer<rapidjson::StringBuffer> writer(buffer);
        doc.Accept(writer);

        return buffer.GetString();
    }

private:
    void logOperation(const std::string& action, const std::string& details) {
        auto now = std::chrono::system_clock::now();
        std::time_t currentTime = std::chrono::system_clock::to_time_t(now);
        logFile << std::ctime(&currentTime)
                << "Action: " << action
                << ", Details: " << details 
                << "\n";
    }
};

// Example usage in main function.
int main() {
    try {
        DistributedCacheManager manager("config.json", "operation.log");

        manager.addNode(Node(1, "Value 1"));
        manager.updateNode(1, "Updated Value 1", 2);
        std::cout << "Serialized JSON: \n" << manager.serializeToJson() << "\n";

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }

    return 0;
}
```

This code provides a basic implementation of the described C++ application. It includes:

- A `Node` class to represent each element in the dynamic array.
- A `DistributedCacheManager` class that manages the nodes, including adding, updating, and removing nodes with thread safety using a mutex.
- Configuration loading from a JSON file using RapidJSON for deserialization.
- Serialization of the current state of nodes into JSON format.
- Logging operations to a specified log file.
- Error handling mechanisms throughout.

This design allows scalability by modularizing node management functionalities and ensuring thread-safe concurrent access, making it suitable for integration with distributed systems.

```javascript
async function fetchScripts(apiEndpoint) {
    const cache = new Map();

    async function loadScript(scriptObj, loadedScripts = []) {
        if (cache.has(scriptObj.id)) return cache.get(scriptObj.id);

        // Resolve dependencies first
        for (const dependencyId of scriptObj.dependencies || []) {
            const depScript = loadedScripts.find(s => s.id === dependencyId);
            if (!depScript) await loadScript({ id: dependencyId }, loadedScripts);
        }

        try {
            const response = await fetch(`${apiEndpoint}/${scriptId}`);
            if (!response.ok) throw new Error(`Failed to fetch script with ID ${scriptId}`);

            const scriptData = await response.json();
            const scriptTag = createScriptTag(scriptData, loadedScripts.length);

            cache.set(scriptData.id, scriptTag);
            return scriptTag;
        } catch (error) {
            logError(error.message);
            return null;
        }
    }

    async function renderFooter(apiEndpoint) {
        try {
            const response = await fetch(apiEndpoint);
            if (!response.ok) throw new Error('Failed to fetch scripts list');

            const scriptsList = await response.json();
            const loadedScripts = [];

            for (const scriptObj of scriptsList) {
                const scriptTag = await loadScript(scriptObj, loadedScripts);
                if (scriptTag) loadedScripts.push(scriptTag);
            }

            return `<footer>${loadedScripts.map(s => s.outerHTML).join('')}</footer>`;
        } catch (error) {
            logError(error.message);
            return '<footer>Error loading scripts</footer>';
        }
    }

    function createScriptTag({ id, code, async = false, defer = false, src = '', type = 'text/javascript', ...customAttributes }, key) {
        const attrs = [
            `key="${key}"`,
            `async=${async}`,
            `defer=${defer}`,
            `src="${src}"`,
            `type="${type}"`
        ];

        for (const [attrName, attrValue] of Object.entries(customAttributes)) {
            if (attrValue) attrs.push(`${attrName}="${attrValue}"`);
        }

        return `<script ${attrs.join(' ')}>${code}</script>`;
    }

    function logError(message) {
        // Assuming a centralized logging system
        console.error(message);
    }

    return { renderFooter };
}

// Usage example:
// const scriptRenderer = await fetchScripts('https://api.example.com/scripts');
// const footerHTML = await scriptRenderer.renderFooter('https://api.example.com/scriptList');

module.exports = fetchScripts;
