#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_BUFFER_SIZE 1024

typedef struct {
    char *key;
    char *value;
} ResourceItem;

typedef struct {
    ResourceItem **items;
    size_t count;
} ResourceBundle;

int validate_request(const char* token) {
    // Dummy validation function, implement actual logic
    return strcmp(token, "valid_token") == 0;
}

ResourceBundle* load_resource_bundle(const char *filepath) {
    FILE *file = fopen(filepath, "r");
    if (!file) return NULL;

    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    bundle->items = NULL;
    bundle->count = 0;

    char line[MAX_BUFFER_SIZE];
    while (fgets(line, MAX_BUFFER_SIZE, file)) {
        line[strcspn(line, "\n")] = '\0'; // Remove newline
        if (strstr(line, "=") != NULL) { 
            size_t key_len = strcspn(line, "=");
            size_t value_len = strlen(line) - key_len - 1;

            bundle->items = realloc(bundle->items, sizeof(ResourceItem *) * (bundle->count + 1));
            ResourceItem *item = malloc(sizeof(ResourceItem));
            item->key = strndup(line, key_len);
            item->value = strdup(line + key_len + 1);

            bundle->items[bundle->count++] = item;
        }
    }

    fclose(file);
    return bundle;
}

void free_resource_bundle(ResourceBundle *bundle) {
    for (size_t i = 0; i < bundle->count; ++i) {
        free(bundle->items[i]->key);
        free(bundle->items[i]->value);
        free(bundle->items[i]);
    }
    free(bundle->items);
    free(bundle);
}

