    send_confirmation_email("confirmation", data);
    return "{\"status\": \"success\", \"message\": \"User account created successfully.\"}";
}

const char* update_user_account(const char *data) {
    perform_database_operation("UPDATE", data);
    return "{\"status\": \"success\", \"message\": \"User account updated successfully.\"}";
}

const char* delete_user_account(const char *data) {
    perform_database_operation("DELETE", data);
    return "{\"status\": \"success\", \"message\": \"User account deleted successfully.\"}";
}

const char* load_and_process_resource_bundle(const char *filepath, const char *token) {
    if (!validate_request(token)) {
        return "{\"status\": \"error\", \"message\": \"Invalid token.\"}";
    }

    ResourceBundle *bundle = load_resource_bundle(filepath);
    if (!bundle) {
        return "{\"status\": \"error\", \"message\": \"Failed to load resource bundle.\"}";
    }

    char sub_action[MAX_BUFFER_SIZE] = {0};
    for (size_t i = 0; i < bundle->count; ++i) {
        if (strcmp(bundle->items[i]->key, "sub_action") == 0) {
            strncpy(sub_action, bundle->items[i]->value, MAX_BUFFER_SIZE);
            break;
        }
    }

    const char *response = "{\"status\": \"error\", \"message\": \"Invalid operation.\"}";
    for (size_t i = 0; i < bundle->count; ++i) {
        if (strcmp(bundle->items[i]->key, "user_data") == 0) {
            const char *(*operation_func)(const char *) =
                strcmp(sub_action, "create") == 0 ? create_user_account :
                strcmp(sub_action, "update") == 0 ? update_user_account :
                strcmp(sub_action, "delete") == 0 ? delete_user_account : NULL;

            if (operation_func) {
                response = operation_func(bundle->items[i]->value);
                break;
            }
        }
    }

    free_resource_bundle(bundle);
    return response;
}
