// Function to safely execute a shell command
function executeCommand(command, pattern) {
  return new Promise((resolve, reject) => {
    // Use execFile for better security against injection attacks
    const args = command.split(' ');
    const safeArgs = args.map(arg => arg.replace(/[^a-zA-Z0-9_\-\.]/g, ''));

    execFile(safeArgs[0], safeArgs.slice(1), (error, stdout, stderr) => {
      if (error) {
        logError(`Command execution error: ${stderr}`);
        reject(error);
        return;
      }

      const filteredOutput = filterOutput(stdout, pattern);

      // Example database integration
      integrateWithDatabase(filteredOutput)
        .then(() => resolve(filteredOutput))
        .catch(dbError => {
          logError(`Database integration error: ${dbError.message}`);
          reject(dbError);
        });
    });
  });
}

// Filter output based on a specific pattern
function filterOutput(output, pattern) {
  const lines = output.split('\n');
  return lines.filter(line => line.includes(pattern));
}

