import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class ManageDistributedCachingSystem {
    private static final Logger logger = Logger.getLogger(ManageDistributedCachingSystem.class.getName());
    private final Map<String, CacheNode> cacheNodes;
    private final MetadataService metadataService;
    private final ConcurrentMap<String, SerializableCacheValue> cacheStore;
    private final ScheduledExecutorService evictionScheduler;

    public ManageDistributedCachingSystem(List<String> nodeAddresses) {
        this.cacheNodes = new ConcurrentHashMap<>();
        this.metadataService = new MetadataService();
        this.cacheStore = new ConcurrentHashMap<>();
        this.evictionScheduler = Executors.newScheduledThreadPool(1);

        initializeCacheNodes(nodeAddresses);
        scheduleEvictionPolicy();
    }

    private void initializeCacheNodes(List<String> nodeAddresses) {
        for (String address : nodeAddresses) {
            CacheNode node = new CacheNode(address);
            cacheNodes.put(address, node);
            connectToNode(node);
        }
    }

    private void connectToNode(CacheNode node) {
        try {
            logger.info("Connecting to cache node: " + node.getAddress());
            node.connect();
            logger.info("Connected successfully.");
        } catch (Exception e) {
            logger.severe("Failed to connect to cache node: " + node.getAddress() + ". Retrying...");
            retryWithBackoff(() -> node.connect(), 3);
        }
    }

    private void scheduleEvictionPolicy() {
        evictionScheduler.scheduleAtFixedRate(this::evictEntries, 0, 1, TimeUnit.HOURS);
    }

    private void evictEntries() {
        long currentTime = System.currentTimeMillis();
        cacheStore.entrySet().removeIf(entry -> entry.getValue().getTtl() < currentTime);
        logger.info("Cache eviction completed.");
    }

    public SerializableCacheValue get(String key) {
        return cacheStore.get(key);
    }

    public void put(String key, SerializableCacheValue value) {
        cacheStore.put(key, value);
        notifyMicroservices(key, "PUT");
    }

    public void remove(String key) {
        cacheStore.remove(key);
        notifyMicroservices(key, "REMOVE");
    }

    private void retryWithBackoff(Runnable action, int maxRetries) {
        int attempt = 0;
        long waitTime = 100; // Initial backoff time in milliseconds
        while (attempt < maxRetries) {
            try {
                action.run();
                return;
            } catch (Exception e) {
                logger.warning("Attempt " + (attempt + 1) + " failed. Retrying after " + waitTime + " ms.");
                try {
                    Thread.sleep(waitTime);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
                attempt++;
                waitTime = calculateBackoffWithJitter(waitTime);
            }
        }
    }

    private long calculateBackoffWithJitter(long baseWaitTime) {
        Random random = new Random();
        return baseWaitTime + random.nextInt((int) (baseWaitTime / 2));
    }

    private void notifyMicroservices(String key, String actionType) {
        // Implement notification logic using messaging queues or HTTP callbacks
    }

    public static class CacheNode {
        private final String address;

        public CacheNode(String address) {
            this.address = address;
        }

        public String getAddress() {
            return address;
        }

        public void connect() throws Exception {
