using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

public class DynamicFileMetadataAnalyzer
{
    private readonly string _directoryPath;
    private readonly long _minFileSize;
    private readonly long _maxFileSize;
    private readonly int _batchSize;
    private readonly Action<FileMetadata, ProcessedMetadata> _callback;

    public DynamicFileMetadataAnalyzer(
        string directoryPath,
        long minFileSize,
        long maxFileSize,
        int batchSize,
        Action<FileMetadata, ProcessedMetadata> callback)
    {
        if (minFileSize > maxFileSize)
            throw new ArgumentException("Minimum file size must be less than or equal to maximum file size.");

        _directoryPath = directoryPath ?? throw new ArgumentNullException(nameof(directoryPath));
        _minFileSize = minFileSize;
        _maxFileSize = maxFileSize;
        _batchSize = batchSize;
        _callback = callback ?? throw new ArgumentNullException(nameof(callback));

        ValidateDirectory();
    }

    private void ValidateDirectory()
    {
        if (!Directory.Exists(_directoryPath))
            throw new DirectoryNotFoundException($"The directory {_directoryPath} does not exist.");
    }

    public IEnumerable<ProcessedMetadata> AnalyzeFiles()
    {
        try
        {
            var files = Directory.EnumerateFiles(_directoryPath, "*.*", SearchOption.TopDirectoryOnly);

            foreach (var fileBatch in Batch(files, _batchSize))
            {
                Parallel.ForEach(fileBatch, file =>
                {
                    try
                    {
                        var metadata = GetFileMetadata(file);
                        if (metadata.IsValid)
                        {
                            ProcessedMetadata processed;
                            _callback(metadata, out processed);
                            yield return processed;
                        }
                    }
                    catch (Exception ex)
                    {
                        LogError($"Error processing file {file}: {ex.Message}");
                    }
                });
            }
        }
        catch (Exception ex)
        {
            LogError($"Error analyzing files in directory {_directoryPath}: {ex.Message}");
        }
    }

    private IEnumerable<string> Batch(IEnumerable<string> files, int batchSize)
    {
        var list = new List<string>(batchSize);
        foreach (var file in files)
        {
            list.Add(file);

            if (list.Count == batchSize)
            {
                yield return list;
                list.Clear();
            }
        }

        if (list.Any())
        {
            yield return list;
        }
    }

    private FileMetadata GetFileMetadata(string filePath)
    {
        try
        {
            var fileInfo = new FileInfo(filePath);
            return new FileMetadata
            {
                FilePath = filePath,
                Size = fileInfo.Length,
                CreationDate = fileInfo.CreationTimeUtc,
                LastModifiedDate = fileInfo.LastWriteTimeUtc,
                IsValid = fileInfo.Length >= _minFileSize && fileInfo.Length <= _maxFileSize
            };
        }
        catch (Exception ex)
        {
            LogError($"Error retrieving metadata for file {filePath}: {ex.Message}");
            return new FileMetadata { IsValid = false };
        }
    }

    private void LogError(string message)
    {
        // Integrate with an external logging system
        Console.Error.WriteLine(message);
    }
}

public class FileMetadata
{
    public string FilePath { get; set; }
    public long Size { get; set; }
    public DateTime CreationDate { get; set; }
    public DateTime LastModifiedDate { get; set; }
    public bool IsValid { get; set; }
}

public class ProcessedMetadata
{
    // Define properties as needed for processed metadata
}

// Example usage of the callback function
void ExampleCallback(FileMetadata metadata, out ProcessedMetadata processed)
{
    // Implement transformation logic here
    processed = new ProcessedMetadata();
}
```

