void Octree::balanceAsync() {
    while (true) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return insertQueue.size() > 10 && !rebalancing.load(); });

        rebalancing.store(true);

        // Rebalancing logic
        while (!insertQueue.empty()) {
            Point p = insertQueue.front();
            insertQueue.pop();

            // Insert point into octree and adjust structure
        }

        rebalancing.store(false);
    }
}

void Octree::logError(const std::string& error) {
    std::cerr << "Error: " << error << std::endl;
}

int main() {
    Octree octree;

    octree.initFromDataSource("CSV", Octree::loadPoints);

    std::thread balanceThread(&Octree::balanceAsync, &octree);
    balanceThread.detach();

    // Example usage
    Point p = {1.0f, 2.0f, 3.0f};
    octree.insertPoint(p);

    return 0;
}
```

