        return 1; // Success
    }
    return 0; // Failure
}

// Encryption function
int encrypt_file(const char* file_path, const char* cipher_name, const char* mode_name) {
    FILE* in_file = fopen(file_path, "rb");
    if (!in_file) {
        log_action("Failed to open input file.");
        return -1;
    }

    // Initialize encryption context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    unsigned char* key = NULL;
    size_t key_len = 0;

    if (!retrieve_key_from_kms("dummy_provider", &key, &key_len)) {
        log_action("Failed to retrieve key.");
        fclose(in_file);
        return -1;
    }

    int encrypt_ok = 1;
    EVP_CIPHER* cipher = EVP_get_cipherbyname(cipher_name);
    if (!cipher) {
        log_action("Invalid cipher name.");
        encrypt_ok = 0;
    } else {
        // Set up encryption context
        if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, NULL) != 1) {
            log_action("Encryption initialization failed.");
            encrypt_ok = 0;
        }
    }

    // Measure start time for performance metrics
    clock_t start_time = clock();

    FILE* out_file = fopen("encrypted_output", "wb");
    if (!out_file) {
        log_action("Failed to open output file.");
        encrypt_ok = 0;
    }

    const int buffer_len = 1024;
    unsigned char in_buffer[buffer_len];
    unsigned char out_buffer[buffer_len + EVP_MAX_BLOCK_LENGTH];

    size_t read_len, encrypted_len;

    while ((read_len = fread(in_buffer, 1, buffer_len, in_file)) > 0) {
        if (!EVP_EncryptUpdate(ctx, out_buffer, &encrypted_len, in_buffer, read_len)) {
            log_action("Encryption update failed.");
            encrypt_ok = 0;
            break;
        }
        fwrite(out_buffer, 1, encrypted_len, out_file);
    }

    if (encrypt_ok) {
        if (!EVP_EncryptFinal_ex(ctx, out_buffer, &encrypted_len)) {
            log_action("Final encryption step failed.");
            encrypt_ok = 0;
        } else {
            fwrite(out_buffer, 1, encrypted_len, out_file);
        }
    }

    clock_t end_time = clock();
    double encryption_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;

    fclose(in_file);
    if (out_file) fclose(out_file);

    unsigned char* memory_usage = OPENSSL_malloc(buffer_len + EVP_MAX_BLOCK_LENGTH); // Simulated
    size_t mem_usage_size = buffer_len + EVP_MAX_BLOCK_LENGTH; // Example size

    EVP_CIPHER_CTX_free(ctx);
    OPENSSL_free(key);
    OPENSSL_free(memory_usage);

    log_action("File encryption completed.");

    return encrypt_ok ? 0 : -1;
}

// Main function to process multiple files
std::vector<EncryptionResult> encrypt_files(const std::vector<std::string>& file_paths) {
    std::vector<EncryptionResult> results;

    for (const auto& path : file_paths) {
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        int exit_code = encrypt_file(path.c_str(), "aes-256-cbc", NULL);

        clock_gettime(CLOCK_MONOTONIC, &end);
        double encryption_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;

        size_t memory_usage = 1024; // Placeholder for actual memory usage calculation

        results.push_back({exit_code, encryption_time, memory_usage});
    }

    return results;
}
```

