// Rust Function for Directory Creation and Environment Variable Setting

use std::env;
use std::fs::{self, DirBuilder};
use std::path::Path;

#[no_mangle]
pub extern "C" fn create_directory_and_set_env_var(directory_name: *const c_char) {
    let dir_name = unsafe { CStr::from_ptr(directory_name).to_str().unwrap() };

    let env_var_value = env::var("USER_PROFILE_DIR").ok();

    match env_var_value {
        Some(path) => println!("Using existing directory path: {}", path),
        None => {
            let new_dir_path = Path::new(&format!("./{}", dir_name));

            if let Err(e) = DirBuilder::new().recursive(true).create(new_dir_path) {
                eprintln!("Failed to create directory: {:?}", e);
                return;
            }

            env::set_var("USER_PROFILE_DIR", new_dir_path.to_str().unwrap());
            println!("New directory path set: {}", new_dir_path.display());
        }
    }
}

