public delegate void SeedCallback(int seed);

public class SeedManager
{
    private static int _currentSeed;
    private static readonly object _lockObject = new object();
    private static readonly int _seedThreshold = 10000;

    public static int GetNextSeed()
    {
        lock (_lockObject)
        {
            if (_currentSeed >= _seedThreshold)
                Reseed();

            return ++_currentSeed;
        }
    }

    private static void Reseed()
    {
        _currentSeed = UnityEngine.Random.Range(0, 10000);
    }

    public static event SeedCallback OnNewSeedGenerated;

    protected static void RaiseOnNewSeedGenerated(int seed)
    {
        OnNewSeedGenerated?.Invoke(seed);
    }
}

public class AdvancedRandomGenerator
{
    private readonly Random _random;

    public AdvancedRandomGenerator()
    {
        int seed = UnityEngine.Random.Range(0, int.MaxValue);
        SeedManager.RaiseOnNewSeedGenerated(seed);
        _random = new Random(seed);
    }

    public T CustomRange<T>(CustomInterval<T> interval) where T : IComparable<T>, IConvertible
    {
        double min = Convert.ToDouble(interval.Min);
        double max = Convert.ToDouble(interval.Max);

        switch (interval.Type)
        {
            case RangeType.Closed:
                return (T)(object)(_random.NextDouble() * (max - min) + min);
            case RangeType.Open:
                return (T)(object)((_random.NextDouble() * (max - min) + min + double.Epsilon));
            case RangeType.HalfOpen:
                if (min.Equals(interval.Min))
                    return (T)(object)(_random.NextDouble() * (max - min) + min);
                else
                    return (T)(object)((_random.NextDouble() * (max - min) + min + double.Epsilon));
            default:
                throw new ArgumentOutOfRangeException(nameof(interval.Type), "Invalid range type");
        }
    }

    public void RegisterSeedCallback(SeedCallback callback)
    {
        SeedManager.OnNewSeedGenerated += callback;
    }

    private static double ConvertToDouble(object value)
    {
        return System.Convert.ToDouble(value, System.Globalization.CultureInfo.InvariantCulture);
    }

    private T ConvertFromDouble<T>(double value) where T : IConvertible
    {
        return (T)(object)value;
    }
}
```

