import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.concurrent.*;
import java.util.logging.*;
import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;

public class ImageDownloader {
    private final int maxRetries = 3;
    private final long backoffTimeInMillis = 1000; // 1 second
    private final ConcurrentHashMap<String, BufferedImage> cache = new ConcurrentHashMap<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);

    public void downloadImageResources(List<String> imageUrls) {
        for (String imageUrl : imageUrls) {
            executorService.submit(() -> processImage(imageUrl));
        }
        executorService.shutdown();
        try {
            executorService.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Reset interrupt status
        }
    }

    private void processImage(String imageUrl) {
        int attempt = 0;
        while (attempt < maxRetries) {
            try {
                if (!isValidUrl(imageUrl)) {
                    log("Invalid URL: " + imageUrl);
                    return;
                }

                BufferedImage image = cache.computeIfAbsent(imageUrl, this::downloadAndProcessImage);

                // Process and display or store the image
                saveResizedImage(image, 200, 200); // Example resize to 200x200

                log("Successfully processed: " + imageUrl);
                return;
            } catch (IOException e) {
                attempt++;
                if (attempt < maxRetries) {
                    try {
                        Thread.sleep(backoffTimeInMillis * attempt);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                    }
                } else {
                    log("Failed to download: " + imageUrl + ", after " + attempt + " attempts");
                }
            } catch (Exception e) {
                log("Error processing image from URL: " + imageUrl + " - " + e.getMessage());
                break;
            }
        }
    }

    private BufferedImage downloadAndProcessImage(String imageUrl) throws IOException {
        URL url = new URL(imageUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setConnectTimeout(5000); // 5 seconds timeout
        connection.setRequestProperty("User-Agent", "Mozilla/5.0");

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            BufferedImage image = ImageIO.read(connection.getInputStream());
            return resizeImage(image, 512, 512); // Resize to a max dimension for example
        } else {
            throw new IOException("Failed to fetch image: HTTP error code " + responseCode);
        }
    }

    private boolean isValidUrl(String urlString) {
        try {
            new URL(urlString).toURI();
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private BufferedImage resizeImage(BufferedImage original, int width, int height) throws IOException {
        // Utilize an image library like Thumbnailator
        // This is a placeholder for resizing logic
        return original.getScaledInstance(width, height, java.awt.Image.SCALE_SMOOTH);
    }

    private void saveResizedImage(BufferedImage resizedImage, int width, int height) throws IOException {
        File outputFile = new File("output_" + System.currentTimeMillis() + ".png");
        ImageIO.write(resizedImage, "png", outputFile);
    }

    private void log(String message) {
        Logger.getLogger(ImageDownloader.class.getName()).log(Level.INFO, message);
    }
}
