    {
        var configBuilder = new ConfigurationBuilder()
            .AddAzureAppConfiguration(options =>
                options.Connect(Environment.GetEnvironmentVariable("ConnectionString"))
                        .ConfigureCacheExpiration(TimeSpan.FromMinutes(5)));

        return configBuilder.Build();
    }

    private void InitializeConnections()
    {
        string[] providers = { "MySQL", "PostgreSQL", "SQLite" };
        foreach (string provider in providers)
        {
            var connectionString = configuration.GetConnectionString(provider);
            if (!string.IsNullOrEmpty(connectionString))
            {
                connectionStrings[provider] = new DbConnectionString
                {
                    Provider = provider,
                    ConnectionString = connectionString
                };
            }
        }
    }

    public void ManageConnection(string provider, Action<DbConnection> operation)
    {
        try
        {
            if (connectionStrings.TryGetValue(provider, out var dbConnStr))
            {
                using (var connection = new DbConnection(dbConnStr.ConnectionString))
                {
                    operation(connection);
                }
            }
            else
            {
                throw new InvalidOperationException($"No configuration found for provider: {provider}");
            }
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            // Fallback logic or retry mechanism can be added here
        }
