public class DatabaseConnectionManager : IDisposable
{
    private readonly ConcurrentDictionary<string, object> _lockObjects = new();
    private readonly ConcurrentBag<Lazy<IDbConnection>> _connectionPools = new();
    private readonly ConcurrentDictionary<string, (string Provider, string ConnectionString)> _configurations = new();

    public IDbConnection GetConnection(string provider, string connectionString)
    {
        if (!_configurations.ContainsKey(provider))
            throw new InvalidOperationException("Provider not initialized.");

        var connectionLazy = new Lazy<IDbConnection>(() =>
        {
            return InitializeConnection(provider, connectionString);
        });

        lock (_lockObjects.GetOrAdd(provider, new object()))
        {
            foreach (var lazy in _connectionPools)
            {
                if (!lazy.IsValueCreated && lazy.Value.Provider == provider)
                {
                    lazy = connectionLazy;
                    break;
                }
            }

            var connections = GetConnectionsFromPool(provider);
            return connections.FirstOrDefault(c => !c.IsOpen) ?? connectionLazy.Value;
        }
    }

    public void ReleaseConnection(IDbConnection connection)
    {
        if (connection == null || connection.State != ConnectionState.Open)
            throw new InvalidOperationException("Invalid or closed connection.");

        lock (_lockObjects.GetOrAdd(connection.DataSource, new object()))
        {
            // Implement logic to return the connection back to the pool
        }
    }

    public void InitializeFromConfiguration(string configSource)
    {
        // Placeholder for loading configuration from external sources (Azure App Configuration, AWS SSM, etc.)
        _configurations["MySQL"] = ("MySql.Data.MySqlClient", "server=localhost;database=test;uid=root;");
        _configurations["PostgreSQL"] = ("Npgsql", "Host=myhost;Database=mydb;Username=foo;Password=bar;");
        _configurations["SQLite"] = ("Microsoft.Data.Sqlite", "Data Source=:memory:;");
    }

    public override string ToString()
    {
        return $"Connection Manager - Total Pools: {_connectionPools.Count}, Active Connections: {GetActiveConnectionsCount()}";
    }

    private IDbConnection InitializeConnection(string provider, string connectionString)
    {
        return provider switch
        {
            "MySql.Data.MySqlClient" => new MySqlConnection(connectionString),
            "Npgsql" => new NpgsqlConnection(connectionString),
            "Microsoft.Data.Sqlite" => new SqliteConnection(connectionString),
            _ => throw new NotSupportedException($"Provider '{provider}' is not supported."),
        };
    }

    private IEnumerable<IDbConnection> GetConnectionsFromPool(string provider)
    {
        return _connectionPools.Where(pool =>
            pool.Value.IsValueCreated && pool.Value.Value.Provider == provider);
    }

    private int GetActiveConnectionsCount()
    {
        // Efficient way to count active connections
        return _connectionPools.Count(pool => pool.IsValueCreated && pool.Value.IsOpen);
    }

    public void Dispose()
    {
        foreach (var connection in _connectionPools)
        {
            if (connection.IsValueCreated && connection.Value.State == ConnectionState.Open)
                connection.Value.Dispose();
        }

        _connectionPools.Clear();
    }
}
