// Logging module
mod logging {
    use chrono::{Local, DateTime, TimeZone};
    use std::fs::{OpenOptions, File};
    use std::io::{Write, Seek, SeekFrom};

    pub fn log(message: &str) {
        let timestamp: DateTime<Local> = Local::now();
        println!("[{}] {}", timestamp.format("%Y-%m-%d %H:%M:%S"), message);

        // Implementing log rotation
        static mut LOG_ROTATION_SIZE: usize = 10 * 1024 * 1024; // 10 MB for example
        let filename = "app.log";
        let mut file = OpenOptions::new()
            .append(true)
            .create(true)
            .open(filename)
            .expect("Failed to open log file");

        let message_len = format!("[{}] {}\n", timestamp.format("%Y-%m-%d %H:%M:%S"), message).len();

        if unsafe { &mut LOG_ROTATION_SIZE } > 0 {
            let mut current_size = file.seek(SeekFrom::End(0)).unwrap();
            if current_size + message_len >= *unsafe { &mut LOG_ROTATION_SIZE } {
                file.set_len(0);
                current_size = 0;
            }
        }

        writeln!(file, "{}", message).expect("Failed to write log");
    }
}

