    pub fn get_or_create_directory(custom_prefix: &str) -> PathBuf {
        let default_path = "/tmp/my_dir";
        let path = if let Ok(dir) = env::var("MY_DIR_PATH") {
            PathBuf::from(dir)
        } else {
            PathBuf::from(default_path)
        };

        if path.exists() && path.is_dir() {
            log(&format!("Using existing directory: {:?}", path));
            return path;
        }

        let new_path = match fs::read_dir("/tmp").unwrap().next() {
            Some(entry) => entry.unwrap().path(),
            None => PathBuf::from(default_path),
        };

        new_path.push(format!("{}_{}", custom_prefix, Utc::now().timestamp()));

        if !new_path.exists() {
            match fs::create_dir_all(&new_path) {
                Ok(_) => log(&format!("Created directory: {:?}", new_path)),
                Err(e) => log(&format!("Failed to create directory {}: {}", new_path.display(), e)),
            };
        } else {
            log(&format!("Directory already exists: {:?}", new_path));
        }

        new_path
    }
