MAX_CALLS_PER_SECOND = 10

@sleep_and_retry
@limits(calls=MAX_CALLS_PER_SECOND, period=1)
def sync_data(data):
    try:
        data_compressed = zlib.compress(pickle.dumps(data))
        response = requests.post(API_URL, data=data_compressed)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        retry_with_backoff(sync_data, data, retries=5)

def retry_with_backoff(func, *args, retries=3):
    delay = 1
    for i in range(retries):
        try:
            return func(*args)
        except Exception as e:
            time.sleep(delay)
            delay *= 2

