```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CHAR_LENGTH 100

typedef struct NestedSubNode {
    char *str;
    float value;
} NestedSubNode;

typedef struct SubNode {
    char str[MAX_CHAR_LENGTH + 1];
    double value;
    struct SubNode *next;
    NestedSubNode *nestedHead;
} SubNode;

typedef struct Node {
    int value;
    SubNode *subHead;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

char* generateRandomString(size_t maxLength) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    size_t length = rand() % (maxLength + 1);
    char *randomStr = malloc(length + 1);
    if (!randomStr) return NULL;

    for (size_t i = 0; i < length; i++) {
        randomStr[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    randomStr[length] = '\0';
    return randomStr;
}

NestedSubNode* createNestedSubNode() {
    NestedSubNode *nested = malloc(sizeof(NestedSubNode));
    if (!nested) return NULL;

    nested->str = generateRandomString(MAX_CHAR_LENGTH);
    if (!nested->str) {
        free(nested);
        return NULL;
    }

    nested->value = (float)(rand() % 100 + rand() / (RAND_MAX + 1.0));
    nested->next = NULL;

    return nested;
}

SubNode* createSubNode(int subNodesCount) {
    SubNode *node = malloc(sizeof(SubNode));
    if (!node) return NULL;

    strcpy(node->str, generateRandomString(MAX_CHAR_LENGTH));
    node->value = (double)(rand() % 100 + rand() / (RAND_MAX + 1.0));

    pthread_mutex_lock(&lock);
    SubNode *current = node;
    for (int i = 0; i < subNodesCount - 1; ++i) {
        current->next = createSubNode(0); // No nested nodes in SubNodes
        if (!current->next) {
            while (node) {
                SubNode *temp = node;
                node = node->next;
                free(temp);
            }
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        current = current->next;
    }
    current->next = NULL;

    // Create nested nodes
    current = node;
    while (current) {
        int nestedNodesCount = rand() % 5; // Random count for demonstration
        if (nestedNodesCount > 0) {
            current->nestedHead = createNestedSubNode();
            NestedSubNode *nestedCurrent = current->nestedHead;
            for (int i = 1; i < nestedNodesCount; ++i) {
                nestedCurrent->next = createNestedSubNode();
                if (!nestedCurrent->next) {
                    while (current->nestedHead) {
                        NestedSubNode *temp = current->nestedHead;
                        current->nestedHead = temp->next;
                        free(temp->str);
                        free(temp);
                    }
                    pthread_mutex_unlock(&lock);
                    return NULL;
                }
                nestedCurrent = nestedCurrent->next;
            }
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);

    return node;
}

Node* createNodes(int nodesCount, int subNodesPerNode) {
    Node *nodesArray = malloc(nodesCount * sizeof(Node));
    if (!nodesArray) return NULL;

    for (int i = 0; i < nodesCount; ++i) {
        nodesArray[i].value = rand() % 100;
        nodesArray[i].subHead = createSubNode(subNodesPerNode);
        if (!nodesArray[i].subHead) {
            while (--i >= 0) {
                SubNode *current = nodesArray[i].subHead;
                while (current) {
                    SubNode *temp = current;
                    current = current->next;
                    free(temp->str);
                    while (temp->nestedHead) {
                        NestedSubNode *nestedTemp = temp->nestedHead;
                        temp->nestedHead = nestedTemp->next;
                        free(nestedTemp->str);
                        free(nestedTemp);
                    }
                    free(temp);
                }
            }
            free(nodesArray);
            return NULL;
        }
    }

    return nodesArray;
}

void freeNodes(Node *nodes, int nodesCount) {
    for (int i = 0; i < nodesCount; ++i) {
        SubNode *current = nodes[i].subHead;
        while (current) {
            SubNode *temp = current;
            current = current->next;
            free(temp->str);
            while (temp->nestedHead) {
                NestedSubNode *nestedTemp = temp->nestedHead;
                temp->nestedHead = nestedTemp->next;
                free(nestedTemp->str);
                free(nestedTemp);
            }
            free(temp);
        }
    }
    free(nodes);
}

int main() {
    int nodesCount = 5; // Example count
    int subNodesPerNode = 3; // Example count

    Node *nodesArray = createNodes(nodesCount, subNodesPerNode);
    if (!nodesArray) {
        fprintf(stderr, "Failed to allocate memory for nodes.\n");
        return EXIT_FAILURE;
    }

    // Use the nodes here...

    freeNodes(nodesArray, nodesCount);

    pthread_mutex_destroy(&lock);

    return 0;
}
```

