using UnityEngine;

public class AdvancedRandomValueGenerator
{
    // Generates a random float between min and max (inclusive)
    public static float GenerateRandomFloat(double min, double max)
    {
        return (float)UnityEngine.Random.Range((float)min, (float)(max + 1));
    }

    // Generates a random integer between min and max (inclusive)
    public static int GenerateRandomInteger(int min, int max)
    {
        return UnityEngine.Random.Range(min, max + 1);
    }

    // Generates an IEnumerable of random float values within the specified range
    public static IEnumerable<double> GenerateRandomValues(int count, double min, double max, int pageSize = 100)
    {
        for (int i = 0; i < count; i += pageSize)
        {
            int currentCount = Math.Min(pageSize, count - i);
            for (int j = 0; j < currentCount; j++)
            {
                yield return GenerateRandomFloat(min, max);
            }
        }
    }
}
