function FindElementsBySelector(root, selector, testFunc) {
    let result = [];

    if (!root || !testFunc) return result;

    const queue = [root];

    while (queue.length > 0) {
        const node = queue.shift();

        if (node.nodeType === Node.ELEMENT_NODE && matches(node, selector)) {
            if (testFunc(node)) {
                result.push(node);
            }
        }

        // Enqueue child nodes
        for (let i = 0; i < node.childNodes.length; i++) {
            queue.push(node.childNodes[i]);
        }
    }

    return result;
}

function matches(element, selector) {
    const styleSheet = document.styleSheets[0];
    if (!styleSheet) return false;

    try {
        for (let rule of styleSheet.cssRules || []) {
            if (rule.selectorText === selector && element.matches(rule.selectorText)) {
                return true;
            }
        }
    } catch (e) {
        console.error('Error matching CSS rules:', e);
    }

    // Fallback to using querySelectorAll for more complex selectors
    const elements = document.querySelectorAll(selector);
    return Array.from(elements).includes(element);
}
