#include <iostream>
#include <random>
#include <thread>
#include <vector>
#include <mutex>

namespace RandomService {

    class ThreadSafeGenerator {
    public:
        ThreadSafeGenerator() : gen(SeedFromThreadID()) {}

        static std::uint64_t SeedFromThreadID() {
            return std::hash<std::thread::id>{}(std::this_thread::get_id());
        }

        std::uint32_t GenerateRandomNumber() {
            return gen();
        }

    private:
        std::mt19937_64 gen;
        static thread_local std::random_device rd;
    };

    // Define the thread-local random device instance
    thread_local std::random_device RandomService::ThreadSafeGenerator::rd;

} // namespace RandomService

void generateRandomNumbers(size_t count) {
    for (size_t i = 0; i < count; ++i) {
        RandomService::ThreadSafeGenerator generator;
        std::cout << "Generated: " << generator.GenerateRandomNumber() << "\n";
    }
}

void testThreadSafety() {
    const size_t threadCount = 10;
    const size_t numbersPerThread = 5;

    std::vector<std::thread> threads;
    for (size_t i = 0; i < threadCount; ++i) {
        threads.emplace_back(generateRandomNumbers, numbersPerThread);
    }

    for (auto& th : threads) {
        if (th.joinable()) {
            th.join();
        }
    }
}

int main() {
    testThreadSafety();

    return 0;
}
```

This program implements a multi-threaded random number generator service using the Mersenne Twister algorithm. The `RandomService::ThreadSafeGenerator` class ensures each thread has its own instance of the generator, initialized with a unique seed derived from the thread ID. Thread-local storage is used to manage resources effectively and prevent interference between threads. The `testThreadSafety` function demonstrates the concurrent use of this service by multiple threads.

