// Node.js Program for Dynamic Module Loading

const fs = require('fs');
const path = require('path');

class ModuleLoader {
  constructor(configPath) {
    this.config = JSON.parse(fs.readFileSync(configPath, 'utf-8'));
    this.loadedModules = new Map();
    this.semaphore = require('async-semaphore')(this.config.concurrency || 2);
  }

  async loadAndExecute() {
    try {
      for (const moduleName of this.config.modules) {
        await this.loadModule(moduleName);
      }
    } catch (error) {
      console.error(`Error loading modules: ${error.message}`);
    }
  }

  async loadModule(moduleName) {
    if (this.loadedModules.has(moduleName)) return;

    try {
      const modulePath = path.resolve(__dirname, moduleName);
      await this.semaphore.acquire();
      const module = require(modulePath);

      console.log(`Loaded module: ${moduleName}`);
      this.loadedModules.set(moduleName, module);

      if (module.onLoad) {
        await module.onLoad(this);
      }

    } catch (error) {
      console.error(`Failed to load module ${moduleName}: ${error.message}`);
    } finally {
      this.semaphore.release();
    }
  }
}

// Usage
const loader = new ModuleLoader('./config.json');
loader.loadAndExecute();

// Asynchronous reduce function

async function asyncReduce(array, initialValue, callback) {
  if (!Array.isArray(array)) throw new Error('Input must be an array');

  let result = initialValue;
  const totalElements = array.length;

  for (let i = 0; i < totalElements; i++) {
    await semaphore.acquire();

    try {
      [result] = await Promise.all([callback(result, array[i])]);
    } catch (error) {
      console.error(`Error during reduction at index ${i}:`, error);
      return { error: error.message };
    } finally {
      semaphore.release();
    }
  }

  return result;
}

const semaphore = require('async-semaphore')(4); // Control concurrency

// Usage
(async () => {
  try {
    const sampleArray = [1, 2, 3, 4, 5];
    const sum = await asyncReduce(sampleArray, 0, (acc, val) => Promise.resolve(acc + val));
    console.log('Sum:', sum);
  } catch (error) {
    console.error('Reduction failed:', error.message);
  }
})();

