typedef struct {
  int bitsPerSample;
  int samplesPerPixel;
  int extraSamples;
} TiffInfo;

TiffInfo parseTiff(const char *filePath) {
  FILE *file = fopen(filePath, "rb");
  if (!file) {
    fprintf(stderr, "Error opening file\n");
    exit(EXIT_FAILURE);
  }

  // Example logic for parsing TIFF
  unsigned short bitsPerSample;
  fread(&bitsPerSample, sizeof(bitsPerSample), 1, file);

  TiffInfo info = {0};
  switch (bitsPerSample) {
    case 1:
    case 2:
    case 4:
    case 8:
    case 16:
      info.bitsPerSample = bitsPerSample;
      break;
    default:
      fprintf(stderr, "Unsupported bits per sample: %d\n", bitsPerSample);
      fclose(file);
      exit(EXIT_FAILURE);
  }

  // Assume samplesPerPixel and extraSamples are determined similarly
  info.samplesPerPixel = 3; // Example value
  info.extraSamples = 1; // Example value

  fclose(file);
  return info;
}

int main() {
  const char *filePath = "sample.tiff";
  TiffInfo info = parseTiff(filePath);

  printf("Bits per Sample: %d\n", info.bitsPerSample);
  printf("Samples per Pixel: %d\n", info.samplesPerPixel);
  printf("Extra Samples: %d\n", info.extraSamples);

  return 0;
}
