```java
import java.net.URL;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ImageDownloader {

    private static final Logger logger = Logger.getLogger(ImageDownloader.class.getName());
    private final ExecutorService executorService;
    private final Semaphore semaphore;
    private final ConcurrentHashMap<String, SoftReference<byte[]>> imageCache;
    private final int maxConcurrentDownloads;
    private final long downloadTimeout;
    private final String primaryApiUrl;
    private final String fallbackApiUrl;

    public ImageDownloader(int maxConcurrentDownloads, long downloadTimeout) {
        this.maxConcurrentDownloads = maxConcurrentDownloads;
        this.downloadTimeout = downloadTimeout;
        this.executorService = Executors.newFixedThreadPool(maxConcurrentDownloads);
        this.semaphore = new Semaphore(maxConcurrentDownloads);
        this.imageCache = new ConcurrentHashMap<>();
        this.primaryApiUrl = "https://api.unsplash.com/photos/";
        this.fallbackApiUrl = "https://api.pexels.com/v1/search";
    }

    public void downloadImageResources(List<String> imageUrls) {
        List<Callable<Void>> tasks = new ArrayList<>();

        for (String url : imageUrls) {
            if (!isValidUrl(url)) continue;

            Callable<Void> task = () -> {
                semaphore.acquireUninterruptibly();
                try {
                    byte[] imageData = fetchImageDataWithRetry(url);
                    if (imageData != null) {
                        processAndCacheImage(url, imageData);
                    }
                } catch (Exception e) {
                    logger.log(Level.SEVERE, "Failed to download image from URL: " + url, e);
                } finally {
                    semaphore.release();
                }
                return null;
            };
            tasks.add(task);
        }

        try {
            executorService.invokeAll(tasks);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            logger.log(Level.SEVERE, "Download process interrupted", e);
        }
    }

    private boolean isValidUrl(String urlString) {
        try {
            new URL(urlString).toURI();
            return true;
        } catch (Exception e) {
            logger.log(Level.WARNING, "Invalid URL format: " + urlString, e);
            return false;
        }
    }

    private byte[] fetchImageDataWithRetry(String url) throws InterruptedException {
        int attempt = 0;
        while (attempt < 5) {
            try {
                return downloadImage(url);
            } catch (IOException | TimeoutException e) {
                long backoffTime = (long) Math.pow(2, attempt) + randomJitter();
                logger.log(Level.WARNING, "Retrying after failure: " + url + ", Attempt: " + attempt, e);
                Thread.sleep(backoffTime);
                attempt++;
            }
        }
        return null;
    }

    private byte[] downloadImage(String urlString) throws IOException, TimeoutException {
        try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
            HttpGet request = new HttpGet(urlString);
            request.setConfig(RequestConfig.custom()
                    .setSocketTimeout((int) downloadTimeout)
                    .setConnectTimeout((int) downloadTimeout).build());

            Future<HttpResponse> future = executorService.submit(() -> httpClient.execute(request));
            HttpResponse response;

            try {
                response = future.get(downloadTimeout, TimeUnit.MILLISECONDS);
            } catch (ExecutionException | TimeoutException e) {
                throw new TimeoutException("Download timed out for URL: " + urlString, e);
            }

            if (response.getStatusLine().getStatusCode() == 200) {
                HttpEntity entity = response.getEntity();
                return EntityUtils.toByteArray(entity);
            } else if (response.getStatusLine().getStatusCode() == 429) {
                // Handle rate limiting
                logger.log(Level.WARNING, "Rate limited by API: " + urlString);
                throw new IOException("Rate limit exceeded");
            }

            throw new IOException("Failed to download image from URL: " + urlString);
        }
    }

    private void processAndCacheImage(String url, byte[] imageData) {
        // Use an existing image processing library to resize and convert images
        // Example: ImageProcessor.resizeAndConvert(imageData);

        // Cache the processed image
        imageCache.put(url, new SoftReference<>(imageData));
    }

    private long randomJitter() {
        return (long) (Math.random() * 1000);
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        ImageDownloader downloader = new ImageDownloader(10, 5000);
        List<String> imageUrls = Arrays.asList("https://example.com/image1.jpg", "https://example.com/image2.jpg");
        downloader.downloadImageResources(imageUrls);
        downloader.shutdown();
    }
}
```

**Notes:**
- This code uses a fixed thread pool and semaphore to manage concurrent downloads.
- It incorporates exponential backoff with jitter for retrying failed downloads.
- The image cache is implemented using `ConcurrentHashMap` with `SoftReference` for automatic eviction based on memory pressure.
- Proper error handling and logging are included, though the actual logging configuration and external library integration would need to be set up separately.

