### Semaphore Manager

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>

typedef struct {
    sem_t semaphore;
    pthread_mutex_t lock;  // For dynamic adjustments and throttling control
} resource_semaphore;

void initialize_semaphore(resource_semaphore *rs, int initial_value) {
    sem_init(&rs->semaphore, 0, initial_value);
    pthread_mutex_init(&rs->lock, NULL);
}

void destroy_semaphore(resource_semaphore *rs) {
    sem_destroy(&rs->semaphore);
    pthread_mutex_destroy(&rs->lock);
}

bool acquire_resource(resource_semaphore *rs) {
    if (pthread_mutex_trylock(&rs->lock) == 0) { // Try to lock for throttling
        bool result = sem_trywait(&rs->semaphore) == 0;
        pthread_mutex_unlock(&rs->lock);
        return result;
    }
    return false; // If we couldn't acquire the lock, assume resource is too busy
}

void release_resource(resource_semaphore *rs) {
    sem_post(&rs->semaphore);
}

void adjust_semaphore_load(resource_semaphore *rs, int new_value) {
    pthread_mutex_lock(&rs->lock);
    sem_wait(&rs->semaphore);  // Reduce count before setting a new value
    while (new_value-- > 0 && sem_trywait(&rs->semaphore) == 0);
    sem_post(&rs->semaphore);  // Restore initial state and then set the new value
    pthread_mutex_unlock(&rs->lock);
}

void smart_throttle(resource_semaphore *rs, int max_requests_per_timeframe, long timeframe_ns) {
    static long last_request_time = 0;
    long current_time = time(NULL);

    if ((current_time - last_request_time) < timeframe_ns) {
        // Throttle requests
        usleep(timeframe_ns - (current_time - last_request_time));
    }
    last_request_time = time(NULL);
}
```

