    private readonly IMemoryCache _cache;
    private const int MaxRequestsPerSecond = 5;
    private const int BatchLimitIn10Seconds = 100;
    private readonly Dictionary<string, int> _transactionRequestCounts = new();
    private readonly List<DateTime> _batchTransactionTimestamps = new();

    public TransactionProcessor(IMemoryCache cache)
    {
        _cache = cache;
    }

    public void ProcessUserTransactions(List<string> transactionIds, Dictionary<string, (string Status, decimal AccountBalance, decimal Amount)> updates)
    {
        foreach (var transactionId in transactionIds)
        {
            if (!RateLimitCheck(transactionId))
                continue;

            var updateInfo = updates[transactionId];
            ValidateAndUpdateTransaction(transactionId, updateInfo);
        }
    }

    private bool RateLimitCheck(string transactionId)
    {
        Interlocked.Increment(ref _transactionRequestCounts[transactionId]);
        var currentTime = DateTime.UtcNow;

        if (_batchTransactionTimestamps.Count >= BatchLimitIn10Seconds)
        {
            if ((currentTime - _batchTransactionTimestamps[0]).TotalSeconds < 10)
                return false; // Exceed batch limit
            _batchTransactionTimestamps.RemoveAt(0); // Remove oldest timestamp
        }
        _batchTransactionTimestamps.Add(currentTime);

        var requestCount = Interlocked.Increment(ref _transactionRequestCounts[transactionId]);
        if (requestCount > MaxRequestsPerSecond)
        {
            Thread.Sleep(TimeSpan.FromSeconds(1));
            return false; // Rate limit exceeded
        }

        return true;
    }

