use std::env;
use std::fs::{self, File};
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::sync::Mutex;

lazy_static! {
    static ref LOG_MUTEX: Mutex<()> = Mutex::new(());
}

extern "C" fn log_operation(
    message: *const i8,
    total_length: size_t,
    trimmed_length: size_t,
    slash_appended: bool,
    dir_path: *const i8
) {
    let msg = unsafe { std::ffi::CStr::from_ptr(message).to_string_lossy().into_owned() };
    let mut file = match File::create("operation_log.txt") {
        Ok(file) => file,
        Err(_) => return, // Handle the error gracefully if unable to create log file
    };

    let log_message = format!(
        "{} - Total Length: {}, Trimmed Length: {}, Slash Appended: {}, Directory Path: {}",
        chrono::Utc::now().to_rfc3339(),
        total_length,
        trimmed_length,
        slash_appended,
        unsafe { std::ffi::CStr::from_ptr(dir_path).to_string_lossy() }
    );

    if let Err(_) = file.write_all(log_message.as_bytes()) {
        // Handle the error gracefully if unable to write log message
    }
}

fn create_dir_with_logger(
    dir_name: &str,
    size_limit: usize,
    logger: extern "C" fn(*const i8, size_t, size_t, bool, *const i8),
) -> Option<PathBuf> {
    let path_var = "MY_DIR_PATH";

    // Check if environment variable is set
    match env::var(path_var) {
        Ok(existing_path) => return Some(PathBuf::from(existing_path)),
        Err(_) => {}
    }

    // Create a new directory and set the environment variable
    let dir_path = PathBuf::from(dir_name).strip_prefix(".").unwrap_or(&dir_name.into());

    if !dir_path.exists() {
        fs::create_dir_all(&dir_path).ok()?;
        env::set_var(path_var, dir_path.to_str().unwrap_or("")); // Set the environment variable
    }

    // Securely trim leading and trailing whitespace
    let trimmed_dir: String = dir_path.to_string_lossy()
        .trim()
        .to_string();

    if trimmed_dir.len() > size_limit {
        return None; // Return None if it exceeds size limit
    }

    let slash_appended = !trimmed_dir.ends_with('/');

    if !slash_appended {
        trimmed_dir.push('/');
    }

    let final_path = PathBuf::from(trimmed_dir);

    // Log the operation details with provided logger function pointer
    unsafe {
        log_operation(
            std::ffi::CString::new("Directory created/used")
                .unwrap()
                .as_ptr(),
            dir_name.len() as size_t,
            trimmed_dir.len() as size_t,
            slash_appended,
            final_path.to_str().unwrap_or("").as_ptr() as *const i8
        );
    }

    Some(final_path)
}

#[macro_use]
extern crate lazy_static;

fn main() {
    // Example usage
    if let Some(path) = create_dir_with_logger("example_directory", 256, log_operation) {
        println!("Directory path: {:?}", path);
    } else {
        eprintln!("Failed to create or access directory within size limits.");
    }
}
