// dir_manager.rs

use std::{env, fs};
use std::path::PathBuf;
use tokio::time::sleep;
use std::sync::{Arc, Mutex};
use crate::logger;
use crate::db::Database;

pub struct Config {
    pub base_path: PathBuf,
    pub cleanup_interval: Duration,
    pub prefix: String,
}

impl Config {
    pub fn from_env() -> Self {
        let base_path = PathBuf::from(env::var("MY_DIR_PATH").unwrap_or_else(|_| "/tmp/my_dir".to_string()));
        let prefix = env::var("DIR_PREFIX").unwrap_or_else(|_| "my_app_".to_string());

        Config {
            base_path,
            cleanup_interval: Duration::from_secs(600), // Default 10 minutes
            prefix,
        }
    }
}

pub struct DirectoryManager {
    config: Config,
    db: Arc<Mutex<Database>>,
}

impl DirectoryManager {
    pub async fn new(config: Config) -> Self {
        let db = Database::connect("database_url").await;
        DirectoryManager { config, db: Arc::new(Mutex::new(db)) }
    }

    pub async fn manage_directory(&self) -> Result<(), String> {
        let path = self.ensure_directory().await?;

        logger::log_info(format!("Using directory at {:?}", path));

        // Start background cleanup task
        tokio::spawn(async move {
            loop {
                sleep(self.config.cleanup_interval).await;
                if let Err(e) = self.cleanup_directory(&path).await {
                    error!("{}", e);
                }
            }
        });

        Ok(())
    }

    async fn ensure_directory(&self) -> Result<PathBuf, String> {
        if Path::new(&self.config.base_path).exists() {
            return Ok(self.config.base_path.clone());
        }

        let dir_name = format!("{}{}", self.config.prefix, chrono::Utc::now().timestamp());
        let path = self.config.base_path.join(dir_name);

        fs::create_dir_all(&path)
            .map_err(|e| format!("Failed to create directory: {}", e))?;

        env::set_var("MY_DIR_PATH", path.to_str().unwrap_or_default());

        Ok(path)
    }

    async fn cleanup_directory(&self, path: &PathBuf) -> Result<(), String> {
        if !path.exists() {
            return Err("Directory does not exist".to_string());
        }

        let metadata = fs::metadata(path).map_err(|e| format!("Failed to get directory metadata: {}", e))?;
        let used_space = metadata.len();

        let disk_usage_threshold = 0.8 * self.get_disk_total_space().await;

        if used_space > disk_usage_threshold {
            logger::log_info(format!("Cleaning up directory at {:?}", path));
            fs::remove_dir_all(path)
                .map_err(|e| format!("Failed to clean up directory: {}", e))?;

            let mut db = self.db.lock().unwrap();
            db.update_last_cleanup_time(path.to_str().unwrap_or_default()).await;
        }

        Ok(())
    }

    async fn get_disk_total_space(&self) -> u64 {
        // Platform-specific code for getting total disk space
        std::fs::metadata(self.config.base_path.clone())
            .map(|meta| meta.len())
            .unwrap_or(0)
    }
}

