// compiler.rs
use std::process::{Command, Stdio};
use tokio::task;

pub async fn compile_sources(sources: Vec<String>, cache: Arc<Mutex<cache::Cache>>, notifier: Arc<Mutex<notifier::Notifier>>) {
    let handles = sources.into_iter().map(|source| {
        let cache_clone = Arc::clone(&cache);
        let notifier_clone = Arc::clone(&notifier);

        task::spawn(async move {
            if cache_clone.lock().unwrap().is_cached(source.clone()) {
                return;
            }

            match Command::new("cargo").arg("build")
                .stdin(Stdio::null())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
            {
                Ok(mut child) => {
                    let output = child.wait_with_output().await;

                    if output.status.success() {
                        cache_clone.lock().unwrap().cache(source.clone());
                    } else {
                        notifier_clone.lock().unwrap().notify_failure(&source);
                    }
                },
                Err(_) => notifier_clone.lock().unwrap().notify_error(&source),
            }
        })
    }).collect::<Vec<_>>();

    for handle in handles {
        let _ = handle.await;
    }

    notifier.lock().unwrap().notify_completion();
}

