use hyper::{Body, Response, Server};
use std::convert::Infallible;
use tokio::sync::Mutex;

pub async fn start_server(cache: Arc<Mutex<Cache>>, notifier: Arc<Mutex<Notifier>>) {
    let make_svc = make_service_fn(|_conn| async {
        Ok::<_, Infallible>(service_fn(move |req| handle_request(req, Arc::clone(&cache), Arc::clone(&notifier))))
    });

    let addr = ([127, 0, 0, 1], 3000).into();
    let server = Server::bind(&addr).serve(make_svc);

    if let Err(e) = server.await {
        eprintln!("server error: {}", e);
    }
}

async fn handle_request(_req: hyper::Request<Body>, cache: Arc<Mutex<Cache>>, notifier: Arc<Mutex<Notifier>>) -> Result<Response<Body>, Infallible> {
    // Handle incoming HTTP requests, provide real-time status and health check
    Ok(Response::new(Body::from("Hello World")))
}

// health.rs
use hyper::{Response, Body};

pub fn health_check() -> Response<Body> {
    Response::builder()
        .status(200)
        .body(Body::from("OK"))
        .unwrap()
}
