import redis.clients.jedis.Jedis;
import redis.clients.jedis.JedisCluster;
import redis.clients.jedis.params.SetParams;

import java.util.HashMap;
import java.util.Map;

public class DistributedCacheSystem {

    private JedisCluster jedisCluster;
    private final Map<String, Long> categoryExpirationMap = new HashMap<>();

    public DistributedCacheSystem(String[] nodes) {
        this.jedisCluster = new JedisCluster(nodes);
        initializeCategoryExpirations();
    }

    private void initializeCategoryExpirations() {
        // Example expiration times in seconds for different categories
        categoryExpirationMap.put("electronics", 3600L);  // 1 hour
        categoryExpirationMap.put("clothing", 7200L);     // 2 hours
        categoryExpirationMap.put("food", 1800L);         // 30 minutes
    }

    public void cacheProduct(String productId, String productData, String category) {
        long expirationTime = categoryExpirationMap.getOrDefault(category, 3600L);
        SetParams setParams = new SetParams().nx().px((int) expirationTime * 1000);

        jedisCluster.set(setParams, "product:" + productId, productData);
    }

    public void invalidateProductCache(String productId) {
        jedisCluster.del("product:" + productId);
    }

    public String getProductFromCache(String productId) {
        return jedisCluster.get("product:" + productId);
    }

    public double getCacheHitRate() {
        // This is a simplistic way to calculate hit rate
        long hits = jedisCluster.info().split("\\n")[5].split(": ")[1].longValue();
        long misses = jedisCluster.info().split("\\n")[6].split(": ")[1].longValue();
        return (double) hits / (hits + misses);
    }

    public void manageMemoryUsage() {
        // Evict least recently used keys if memory usage is high
        jedisCluster.configSet("maxmemory-policy", "volatile-lru");
    }

    public void handleNetworkFailure(Exception e) {
        System.err.println("Network failure encountered: " + e.getMessage());
        // Implement retry logic or fallback mechanisms here
    }

    public static void main(String[] args) {
        String[] nodes = {"127.0.0.1:7000", "127.0.0.1:7001", "127.0.0.1:7002"};

        DistributedCacheSystem cacheSystem = new DistributedCacheSystem(nodes);

        try {
            cacheSystem.cacheProduct("12345", "{\"name\":\"Laptop\",\"price\":999}", "electronics");
            String productData = cacheSystem.getProductFromCache("12345");

            if (productData != null) {
                System.out.println("Cache hit: " + productData);
            } else {
                System.out.println("Cache miss.");
            }

            double hitRate = cacheSystem.getCacheHitRate();
            System.out.println("Current cache hit rate: " + hitRate);

        } catch (Exception e) {
            cacheSystem.handleNetworkFailure(e);
        }
    }
}
