    const limit = require('p-limit');
    const runConcurrently = limit(concurrencyLevel);

    for (const moduleName of executionOrder) {
      try {
        await runConcurrently(() => this.loadModule(moduleName));
      } catch (error) {
        // Handle errors gracefully and log them
      }
    }
  }

