using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public class SecureCipherService
{
    private readonly HttpClient _httpClient;
    private readonly string _tokenEndpoint;
    private readonly TimeSpan _cacheExpiration = TimeSpan.FromMinutes(5);
    private readonly ConcurrentDictionary<string, (string Token, DateTime Expiry)> _tokenCache =
        new ConcurrentDictionary<string, (string, DateTime)>();

    public SecureCipherService(string tokenEndpoint)
    {
        _httpClient = new HttpClient();
        _tokenEndpoint = tokenEndpoint;
    }

    public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext, byte[] key, byte[] iv, long offset, CancellationToken cancellationToken = default)
    {
        if (ciphertext.Length <= 0 || key == null || iv == null)
            throw new ArgumentException("Invalid input parameters.");

        string token = await GetValidTokenAsync(cancellationToken);

        using var aes = Aes.Create();
        aes.Key = key;
        aes.IV = iv;
        aes.Mode = CipherMode.CBC;
        aes.Padding = PaddingMode.PKCS7;

        using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        using var resultStream = new MemoryStream(ciphertext.Length);

        await DecryptAsync(ciphertext, offset, decryptor, resultStream, cancellationToken);

        return resultStream.ToArray();
    }

    private async Task<string> GetValidTokenAsync(CancellationToken cancellationToken)
    {
        string cachedToken;
        if (_tokenCache.TryGetValue("auth_token", out var cacheEntry) && DateTime.UtcNow < cacheEntry.Expiry)
        {
            return cacheEntry.Token;
        }

        int retryCount = 0;
        while (retryCount < 3)
        {
            try
            {
                var response = await _httpClient.GetAsync(_tokenEndpoint, cancellationToken);
                if (!response.IsSuccessStatusCode)
                {
                    throw new HttpRequestException("Failed to retrieve token.");
                }

                cachedToken = await response.Content.ReadAsStringAsync();
                var expiryTime = DateTime.UtcNow.AddMinutes(30); // Assume 30 min lifetime
                _tokenCache["auth_token"] = (cachedToken, expiryTime);
                return cachedToken;
            }
            catch (HttpRequestException ex)
            {
                retryCount++;
                Console.WriteLine($"Token retrieval attempt {retryCount} failed: {ex.Message}");
                if (retryCount >= 3) throw;
                await Task.Delay(1000 * retryCount, cancellationToken); // Exponential backoff
            }
        }

        throw new InvalidOperationException("Failed to obtain a valid token after multiple attempts.");
    }

    private async Task DecryptAsync(byte[] ciphertext, long offset, ICryptoTransform decryptor, Stream resultStream, CancellationToken cancellationToken)
    {
        const int bufferSize = 4096;
        using var cryptoStream = new CryptoStream(resultStream, decryptor, CryptoStreamMode.Write);

        for (long i = offset; i < ciphertext.Length; i += bufferSize)
        {
            if (cancellationToken.IsCancellationRequested)
                return;

            int chunkSize = Math.Min(bufferSize, ciphertext.Length - i);
            await cryptoStream.WriteAsync(ciphertext, (int)i, chunkSize, cancellationToken);
        }

        await cryptoStream.FlushFinalBlockAsync();
    }
}
```

### Key Features Implemented:

- **Token Management**: Handles token retrieval with retries and caching.
- **AES-CBC Decryption**: Decrypts data using AES-CBC mode with PKCS7 padding.
- **Concurrency**: Supports multiple concurrent decryption operations through `async` methods.
- **Resilience**: Includes retry logic for network issues during token retrieval.
- **Error Handling**: Throws exceptions for invalid input and logs errors during token retrieval.
- **CancellationToken Support**: Allows cancellation of ongoing decryption tasks.

