using System;
using System.Data;
using System.Data.SqlClient;

public class DatabaseHelper
{
    private string _connectionString;

    public DatabaseHelper(string connectionString)
    {
        _connectionString = connectionString;
    }

    public DataTableReader ExecuteQueryAndReturnReader(byte[] queryData)
    {
        if (queryData == null || queryData.Length == 0)
            throw new ArgumentException("Query data cannot be null or empty.");

        string query = System.Text.Encoding.UTF8.GetString(queryData);

        using (var connection = new SqlConnection(_connectionString))
        {
            var command = new SqlCommand(query, connection);

            try
            {
                connection.Open();

                // Use SqlDataAdapter to handle large datasets efficiently
                var adapter = new SqlDataAdapter(command);
                var dataSet = new DataSet();

                adapter.Fill(dataSet);

                return dataSet.CreateDataReader();
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"Error executing query: {ex.Message}");
                throw;
            }
        }
    }
}
