```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <json-c/json.h>  // Assuming json-c library for JSON parsing
// Include other necessary libraries like libxml2 for XML parsing

typedef struct {
    char *data;
    size_t length;
    time_t last_modified;
} ResourceBundle;

typedef enum { FORMAT_JSON, FORMAT_XML, FORMAT_BINARY } FormatType;

pthread_mutex_t resource_bundle_lock = PTHREAD_MUTEX_INITIALIZER;
ResourceBundle global_resource_bundle;
char *current_format_path[3];
FormatType current_format;
time_t last_reload_time;

// Helper functions for loading from different formats
static int load_json(const char *path);
static int load_xml(const char *path);
static int load_binary(const char *path);

// Function to load resource bundle based on format
int load_resource_bundle(const char *file_path, FormatType format) {
    pthread_mutex_lock(&resource_bundle_lock);

    struct stat file_stat;
    if (stat(file_path, &file_stat)) {
        perror("Failed to get file status");
        pthread_mutex_unlock(&resource_bundle_lock);
        return -1;
    }

    time_t current_mod_time = file_stat.st_mtime;

    // Check if reload is necessary
    if (current_format == format && global_resource_bundle.last_modified >= last_reload_time) {
        pthread_mutex_unlock(&resource_bundle_lock);
        return 0;  // No need to reload
    }

    switch (format) {
        case FORMAT_JSON:
            if (load_json(file_path)) {
                fprintf(stderr, "Failed to load JSON\n");
                pthread_mutex_unlock(&resource_bundle_lock);
                return -1;
            }
            break;

        case FORMAT_XML:
            if (load_xml(file_path)) {
                fprintf(stderr, "Failed to load XML\n");
                pthread_mutex_unlock(&resource_bundle_lock);
                return -1;
            }
            break;

        case FORMAT_BINARY:
            if (load_binary(file_path)) {
                fprintf(stderr, "Failed to load binary\n");
                pthread_mutex_unlock(&resource_bundle_lock);
                return -1;
            }
            break;

        default:
            fprintf(stderr, "Unsupported format\n");
            pthread_mutex_unlock(&resource_bundle_lock);
            return -1;
    }

    global_resource_bundle.last_modified = current_mod_time;
    last_reload_time = time(NULL);

    // Update current format path
    if (current_format != format) {
        free(current_format_path[0]);
        free(current_format_path[1]);
        free(current_format_path[2]);
        current_format_path[0] = strdup(file_path);
        current_format = format;
    }

    pthread_mutex_unlock(&resource_bundle_lock);
    return 0;
}

// Example implementations for loading different formats
static int load_json(const char *path) {
    FILE *file = fopen(path, "r");
    if (!file) return -1;

    struct json_object *parsed_json;
    struct json_object *error;

    parsed_json = json_object_from_file(file);
    fclose(file);

    if (!parsed_json) return -1;

    // Deserialize JSON into global_resource_bundle
    json_object_to_xml_string_ext(parsed_json, 0);  // Example conversion

    json_object_put(parsed_json);
    return 0;
}

static int load_xml(const char *path) {
    FILE *file = fopen(path, "r");
    if (!file) return -1;

    // Use libxml2 or similar to parse XML
    // Deserialize into global_resource_bundle
    fclose(file);
    return 0;
}

static int load_binary(const char *path) {
    FILE *file = fopen(path, "rb");
    if (!file) return -1;

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    global_resource_bundle.data = malloc(file_size);
    if (!global_resource_bundle.data) {
        fclose(file);
        return -1;
    }

    fread(global_resource_bundle.data, 1, file_size, file);
    global_resource_bundle.length = file_size;

    fclose(file);
    return 0;
}

// Database fallback function
int load_from_database() {
    // Implement database loading logic here
    // Fallback if file-based resource bundle fails
    return -1;  // Example error
}

// Function to watch for changes and reload resources
void *resource_watcher(void *arg) {
    char *path = (char *)arg;
    while (1) {
        struct stat file_stat;
        if (stat(path, &file_stat)) continue;

        if (global_resource_bundle.last_modified < file_stat.st_mtime) {
            load_resource_bundle(path, current_format);
        }

        sleep(5);  // Check every 5 seconds
    }
}

// API to get resource data
const char *get_resource_data() {
    pthread_mutex_lock(&resource_bundle_lock);

    if (!global_resource_bundle.data) {
        // Attempt to load from database as fallback
        load_from_database();
    }

    const char *data = global_resource_bundle.data;
    pthread_mutex_unlock(&resource_bundle_lock);
    return data;
}

// User-level API documentation
/*
 * Function: load_resource_bundle
 * Description: Load resource bundle from specified file path and format.
 * Parameters:
 *   - file_path: Path to the resource file.
 *   - format: Resource format (FORMAT_JSON, FORMAT_XML, FORMAT_BINARY).
 * Return: 0 on success, non-zero on failure.

 * Function: get_resource_data
 * Description: Retrieve loaded resource data.
 * Return: Pointer to resource data or NULL if not available.
 */
```

### Explanation:
- **Thread Safety**: The use of `pthread_mutex_t` ensures that concurrent access is managed safely. Locks are used around critical sections where shared resources are accessed.
- **Format Handling**: Separate functions handle different formats (JSON, XML, Binary). These can be extended to support additional formats.
- **Dynamic Updates**: A separate thread (`resource_watcher`) monitors changes in the resource file and reloads it as necessary.
- **Database Fallback**: If loading from the file fails, a fallback mechanism attempts to load data from a database.
- **Caching**: The `global_resource_bundle` structure caches loaded resources, reducing disk/database access frequency.
- **Modular Design**: Functions are designed to be easily extended for additional formats and storage backends.

```javascript
async function renderFooterScripts(apiEndpoint, logger) {
    const cache = new Map();
    const scriptContainer = document.createElement('div');

    async function fetchScripts() {
        if (cache.has(apiEndpoint)) return cache.get(apiEndpoint);

        try {
            let attempts = 0;
            while (attempts < 3) { // Retry up to 3 times
                try {
                    const response = await fetch(apiEndpoint);
                    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

                    const scriptsData = await response.json();
                    cache.set(apiEndpoint, scriptsData);
                    return scriptsData;
                } catch (err) {
                    attempts++;
                    logger.warn(`Fetch attempt ${attempts} failed for ${apiEndpoint}: ${err.message}`);
                    await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempts) * 100)); // Exponential backoff
                }
            }

            throw new Error('Failed to fetch scripts after multiple attempts');
        } catch (error) {
            logger.error(`Error fetching script details from API: ${error.message}`);
            return [];
        }
    }

    function createScriptElement(scriptData, customAttributes = {}) {
        const { src, async, defer, type, dependencies = [] } = scriptData;
        const script = document.createElement('script');

        if (src) script.src = src;
        if (async !== undefined) script.async = async;
        if (defer !== undefined) script.defer = defer;
        if (type) script.type = type;

        Object.entries(customAttributes).forEach(([key, value]) => {
            script.setAttribute(key, value);
        });

        return { element: script, dependencies };
    }

    function loadScripts(scriptsData) {
        const loadedScripts = new Map();

        async function loadScript(scriptInfo) {
            if (loadedScripts.has(scriptInfo.element)) return;

            for (const dependency of scriptInfo.dependencies) {
                await loadScript(loadedScripts.get(dependency));
            }

            scriptContainer.appendChild(scriptInfo.element);
            loadedScripts.set(scriptInfo.element, scriptInfo);

            scriptInfo.element.onload = () => logger.info(`Loaded script: ${scriptInfo.element.src}`);
            scriptInfo.element.onerror = (e) => logger.error(`Error loading script: ${scriptInfo.element.src}, ${e.message}`);
        }

        scriptsData.forEach((scriptData) => {
            const { element, dependencies } = createScriptElement(scriptData);
            loadedScripts.set(element, { element, dependencies });
        });

        for (const [_, scriptInfo] of loadedScripts.entries()) {
            loadScript(scriptInfo);
        }
    }

    function updateFooter() {
        const existingContainer = document.getElementById('footer-scripts');

        if (existingContainer) {
            existingContainer.remove();
        }

        scriptContainer.id = 'footer-scripts';
        document.body.appendChild(scriptContainer);
    }

    async function renderScripts() {
        const scriptsData = await fetchScripts();
        loadScripts(scriptsData);
        updateFooter();
    }

    return {
        addScript: (scriptId, customAttributes) => {
            if (!cache.has(apiEndpoint)) {
                logger.warn(`Cannot add script. Scripts not fetched yet.`);
                return;
            }

            const updatedScripts = cache.get(apiEndpoint).map(scriptData => 
                scriptData.id === scriptId ? { ...scriptData, ...customAttributes } : scriptData
            );

            cache.set(apiEndpoint, updatedScripts);
            renderScripts();
        },
        removeScript: (scriptId) => {
            if (!cache.has(apiEndpoint)) {
                logger.warn(`Cannot remove script. Scripts not fetched yet.`);
                return;
            }

            const filteredScripts = cache.get(apiEndpoint).filter(scriptData => scriptData.id !== scriptId);

            cache.set(apiEndpoint, filteredScripts);
            renderScripts();
        },
        updateScript: (scriptId, customAttributes) => {
            if (!cache.has(apiEndpoint)) {
                logger.warn(`Cannot update script. Scripts not fetched yet.`);
                return;
            }

            const updatedScripts = cache.get(apiEndpoint).map(scriptData => 
                scriptData.id === scriptId ? { ...scriptData, ...customAttributes } : scriptData
            );

            cache.set(apiEndpoint, updatedScripts);
            renderScripts();
        },
    };
}
```

