    if (!fs::exists(webConfig)) {
        logMessage("web.config not found in directory: " + dirPath.string());
        throw std::runtime_error("Missing web.config");
    }
}

std::vector<int> readFileIntegers(const fs::path& filePath) {
    std::vector<int> integers;
    if (!isValidFile(filePath)) return integers;

    std::ifstream file(filePath);
    int value;
    while (file >> value) {
        integers.push_back(value);
    }
    return integers;
}

std::vector<int> readFilesAsync(const std::vector<fs::path>& filePaths, SelectorCache& cache) {
    std::mutex cacheMutex;
    std::atomic<bool> hasErrors(false);

    auto processFile = [&](const fs::path& path) -> std::pair<std::vector<int>, bool> {
        try {
            validateWebConfig(path.parent_path());
            return {readFileIntegers(path), false};
        } catch (const std::exception&) {
            logMessage("Error processing file: " + path.string());
            hasErrors = true;
            return {{}, true};
        }
    };

    std::vector<std::future<std::pair<std::vector<int>, bool>>> futures;
    for (const auto& filePath : filePaths) {
        futures.push_back(std::async(std::launch::async, processFile, filePath));
    }

    std::vector<int> allIntegers;
    for (auto& future : futures) {
        auto [integers, hasError] = future.get();
        if (!hasError) {
            std::lock_guard<std::mutex> lock(cacheMutex);
            allIntegers.insert(allIntegers.end(), integers.begin(), integers.end());
        }
    }

    if (hasErrors) {
        throw std::runtime_error("Some files failed to process");
    }

    return allIntegers;
}

std::shared_ptr<State> recursiveTraverse(FSA* fsa, int lastStateId, const std::string& selector, SelectorCache& cache) {
    auto it = cache.find(selector);
    if (it != cache.end()) return nullptr; // Assuming already processed

    std::vector<int> matchedStates;
    // Recursively traverse the FSA and collect matching states
    // Placeholder logic for traversal
    for (int stateId = 0; stateId <= lastStateId; ++stateId) {
        if (compareState(stateId, selector)) {
            matchedStates.push_back(stateId);
        }
    }

    auto newList = std::make_shared<State>();
    newList->id = static_cast<int>(matchedStates.size());
    cache[selector] = matchedStates;

    return newList;
}

