public class XmlService
{
    private readonly IMemoryCache _cache = new MemoryCache(new MemoryCacheOptions());
    private static readonly HttpClient _httpClient = new HttpClient();
    private const int MaxRetries = 3;
    private readonly ILogger<XmlService> _logger;

    public XmlService(ILogger<XmlService> logger)
    {
        _logger = logger;
    }

    public XElement GetFirstElement(string url, string xpathQuery)
    {
        if (string.IsNullOrWhiteSpace(url) || string.IsNullOrWhiteSpace(xpathQuery))
            throw new ArgumentException("URL and XPath query must be provided.");

        return ExecuteWithRetry(() =>
        {
            var cachedXmlDocument = GetCachedXmlDocument(url);
            if (cachedXmlDocument == null)
            {
                _logger.LogInformation("Cache miss for URL: {Url}", url);

                var response = FetchAndValidateXmlDocument(url);
                cachedXmlDocument = ParseToXPathDocument(response.Content);
                CacheXmlDocument(url, cachedXmlDocument);
            }
            else
            {
                _logger.LogInformation("Cache hit for URL: {Url}", url);
            }

            var stopwatch = Stopwatch.StartNew();
            var nodes = cachedXmlDocument.XPathSelectElements(xpathQuery);

            stopwatch.Stop();
            _logger.LogInformation("XPath query executed in {Time} ms", stopwatch.ElapsedMilliseconds);

            if (!nodes.Any())
                throw new InvalidOperationException($"No elements found for the XPath: {xpathQuery}");

            if (nodes.Count() > 1)
                throw new InvalidOperationException($"Multiple elements found for the XPath: {xpathQuery}");

            return nodes.First();
        });
    }

    private XmlDocument FetchAndValidateXmlDocument(string url)
    {
        var retries = 0;
        while (retries < MaxRetries)
        {
            try
            {
                _logger.LogInformation("Fetching XML document from URL: {Url}", url);
                var response = _httpClient.GetAsync(url).Result;

                if (!response.IsSuccessStatusCode)
                    throw new HttpRequestException($"Error fetching XML: {response.StatusCode}");

                var content = response.Content.ReadAsStringAsync().Result;

                // Schema validation logic here
                // Log schema validation results

                return new XmlDocument();
            }
            catch (HttpRequestException e) when (retries < MaxRetries - 1)
            {
                _logger.LogWarning("Attempt {RetryNumber} failed: {Message}", retries + 1, e.Message);
                Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, retries))).Wait(); // Exponential backoff
                retries++;
            }
        }

        throw new HttpRequestException("Failed to fetch XML document after multiple attempts.");
    }

    private XPathDocument ParseToXPathDocument(string xmlContent)
    {
        using var reader = XmlReader.Create(new StringReader(xmlContent));
        return new XPathDocument(reader);
    }

    private void CacheXmlDocument(string url, XPathDocument document)
    {
        _cache.Set(url, document, TimeSpan.FromMinutes(10)); // Example TTL
    }

    private XPathDocument GetCachedXmlDocument(string url)
    {
        if (_cache.TryGetValue(url, out var cachedDocument))
            return (XPathDocument)cachedDocument;

        return null;
    }

    private T ExecuteWithRetry<T>(Func<T> operation)
    {
        int retries = 0;
        while (true)
        {
            try
            {
                return operation();
            }
            catch (Exception ex) when (retries < MaxRetries - 1 && ShouldRetry(ex))
            {
                _logger.LogWarning("Operation failed: {Message}. Retrying...", ex.Message);
                Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, retries))).Wait(); // Exponential backoff
                retries++;
            }
        }
    }

    private bool ShouldRetry(Exception exception)
    {
        // Logic to determine if the operation should be retried based on exception type or message.
        return true;
    }

