import json
import logging
from abc import ABC, abstractmethod
from typing import Dict, Any, Type
import requests
import threading
import cachetools.func
from flask import Flask, jsonify, request

# Set up basic logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Base class for JSON serializable entities
class JsonSerializable(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    @abstractmethod
    def from_json(cls, json_str: str) -> 'JsonSerializable':
        pass

# Entity classes inheriting from JsonSerializable
class User(JsonSerializable):
    def __init__(self, user_id: int, name: str):
        self.user_id = user_id
        self.name = name

    def to_json(self) -> str:
        return json.dumps({"user_id": self.user_id, "name": self.name})

    @classmethod
    def from_json(cls, json_str: str) -> 'User':
        data = json.loads(json_str)
        return cls(user_id=data['user_id'], name=data['name'])

class Product(JsonSerializable):
    def __init__(self, product_id: int, title: str):
        self.product_id = product_id
        self.title = title

    def to_json(self) -> str:
        return json.dumps({"product_id": self.product_id, "title": self.title})

    @classmethod
    def from_json(cls, json_str: str) -> 'Product':
        data = json.loads(json_str)
        return cls(product_id=data['product_id'], title=data['title'])

class Order(JsonSerializable):
    def __init__(self, order_id: int, user: User, products: list[Product]):
        self.order_id = order_id
        self.user = user
        self.products = products

    def to_json(self) -> str:
        return json.dumps({
            "order_id": self.order_id,
            "user": self.user.to_json(),
            "products": [product.to_json() for product in self.products]
        })

    @classmethod
    def from_json(cls, json_str: str) -> 'Order':
        data = json.loads(json_str)
        user = User.from_json(data['user'])
        products = [Product.from_json(p) for p in data['products']]
        return cls(order_id=data['order_id'], user=user, products=products)

# Factory registration and creation
entity_factories: Dict[str, Type[JsonSerializable]] = {
    'User': User,
    'Product': Product,
    'Order': Order
}

def register_factory(entity_type: str, factory: Type[JsonSerializable]):
    entity_factories[entity_type] = factory

# Fetch JSON files from external API and parse them
@cachetools.func.ttl_cache(maxsize=128, ttl=300)
def fetch_and_parse_json_file(file_url: str) -> Dict[str, Any]:
    response = requests.get(file_url)
    if response.status_code != 200:
        logger.error(f"Failed to load JSON file from {file_url}")
        return {}

    try:
        json_data = response.json()
    except ValueError as e:
        logger.error(f"Invalid JSON format for {file_url}: {e}")
        return {}

    entity_type = json_data.get("type")
    if entity_type in entity_factories:
        factory = entity_factories[entity_type]
        return {"data": factory.from_json(response.text)}

    logger.warning(f"No registered factory for entity type: {entity_type}")
    return {}

# RESTful API using Flask
app = Flask(__name__)

@app.route('/entities/<string:entity_id>', methods=['GET'])
def get_entity(entity_id):
    # Simulating fetching JSON file from a URL based on ID
    file_url = f"https://example.com/json/{entity_id}.json"

    result = fetch_and_parse_json_file(file_url)
    if not result:
        return jsonify({"error": "Entity not found or failed to parse"}), 404

    entity_data = result.get("data")
    return jsonify(entity_data.to_json())

# Dependency graph generator
def generate_dependency_graph(entities: Dict[str, JsonSerializable]) -> Dict[str, list]:
    # Implement a basic dependency graph generation logic here
    dependency_graph = {}
    for entity_id, entity in entities.items():
        dependencies = []  # Extract dependencies from entity if applicable
        dependency_graph[entity_id] = dependencies

    return dependency_graph

# Main execution for setting up the server
if __name__ == "__main__":
    app.run(debug=True)
