    // Pseudo code for reading TIFF files using a library like libtiff
    TIFF *tiff = TIFFOpen(filePath, "r");
    if (!tiff) return info;

    int bitsPerSample;
    TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &info.samplesPerPixel);
    TIFFGetFieldDefaulted(tiff, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);

    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 &&
        bitsPerSample != 8 && bitsPerSample != 16) {
        fprintf(stderr, "Unsupported bits per sample: %d\n", bitsPerSample);
        TIFFClose(tiff);
        return info;
