Below is a C program that meets the requirements described. Note that this is a high-level implementation outline. For brevity, some components like external logging service integration and message queue setup are assumed to be available as libraries or APIs.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <dirent.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <ctype.h>

#define MAX_FILES 10000
#define MAX_THREADS 64

typedef struct {
    char *filename;
} FileTask;

typedef struct {
    pthread_mutex_t lock;
    int count;
    int max_count;
    FileTask tasks[MAX_FILES];
} ThreadPool;

void log_message(const char *message) {
    // Placeholder for logging to external service
}

void error_report(const char *error) {
    log_message(error);
}

double calculate_average_of_last_two_numbers(char *line) {
    char *token, *last_num1 = NULL, *last_num2 = NULL;
    int count = 0;

    token = strtok(line, " \t\n");
    while (token != NULL) {
        if (count >= 2) last_num2 = last_num1;
        if (isdigit(token[0]) || (token[0] == '-' && isdigit(token[1]))) {
            last_num1 = token;
        }
        count++;
        token = strtok(NULL, " \t\n");
    }

    double num1 = last_num1 ? atof(last_num1) : 0.0;
    double num2 = last_num2 ? atof(last_num2) : 0.0;

    return (num1 + num2) / 2;
}

void *process_file(void *arg) {
    FileTask *file_task = (FileTask *)arg;
    int fd, file_size;
    char *data;
    double total_avg = 0.0, line_count = 0;

    if ((fd = open(file_task->filename, O_RDONLY)) == -1) {
        error_report("Failed to open file");
        return NULL;
    }

    if ((file_size = lseek(fd, 0, SEEK_END)) == -1) {
        close(fd);
        error_report("Failed to seek file");
        return NULL;
    }

    data = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (data == MAP_FAILED) {
        close(fd);
        error_report("Memory mapping failed");
        return NULL;
    }

    for (char *line = data; line < data + file_size; ) {
        char *end_line = strchr(line, '\n');
        if (!end_line) break;

        double avg = calculate_average_of_last_two_numbers(line);
        total_avg += avg;
        line_count++;

        line = end_line + 1;
    }

    munmap(data, file_size);
    close(fd);

    log_message("Processed file: ");
    log_message(file_task->filename);
    log_message(", Average: ");

    if (line_count > 0) {
        printf("%.2f\n", total_avg / line_count);
    } else {
        printf("No valid lines found.\n");
    }

    free(file_task->filename);
    free(file_task);

    return NULL;
}

void *thread_worker(void *arg) {
    ThreadPool *pool = (ThreadPool *)arg;

    while (1) {
        pthread_mutex_lock(&pool->lock);
        if (pool->count == 0) {
            pthread_mutex_unlock(&pool->lock);
            break;
        }

        FileTask task = pool->tasks[--pool->count];
        pthread_mutex_unlock(&pool->lock);

        process_file(&task);
    }

    return NULL;
}

void init_thread_pool(ThreadPool *pool, int max_threads) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->count = 0;
    pool->max_count = MAX_FILES;

    for (int i = 0; i < max_threads; ++i) {
        pthread_t thread;
        pthread_create(&thread, NULL, thread_worker, pool);
        pthread_detach(thread);
    }
}

void enqueue_task(ThreadPool *pool, FileTask task) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count < pool->max_count) {
        pool->tasks[pool->count++] = task;
    } else {
        error_report("Thread pool is full");
    }
    pthread_mutex_unlock(&pool->lock);
}

void process_directory(const char *directory, ThreadPool *pool) {
    DIR *dir = opendir(directory);
    struct dirent *entry;

    if (!dir) {
        error_report("Failed to open directory");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            char *filename = malloc(strlen(entry->d_name) + 1);
            strcpy(filename, entry->d_name);

            FileTask task = { .filename = filename };
            enqueue_task(pool, task);
        }
    }

    closedir(dir);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *log_dir = argv[1];
    ThreadPool pool;

    init_thread_pool(&pool, MAX_THREADS);
    process_directory(log_dir, &pool);

    // Wait for all threads to complete
    pthread_mutex_lock(&pool.lock);
    while (pool.count > 0) {
        pthread_mutex_unlock(&pool.lock);
        usleep(100000); // Sleep for 100ms
        pthread_mutex_lock(&pool.lock);
    }
    pthread_mutex_unlock(&pool.lock);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Concurrency**: Uses a thread pool to manage worker threads.
- **Memory Mapping**: Utilizes `mmap` for efficient file reading.
- **Error Handling**: Gracefully handles errors like missing files and non-numeric data.
