using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Xml.Linq;
using Microsoft.Extensions.Logging;

namespace ConfigurationLoaderAndDecryptor
{
    public class ConfigurationManager
    {
        private static readonly HttpClient httpClient = new HttpClient();
        private string serverUrl;
        private string xmlFilePath;
        private ILogger logger;

        public ConfigurationManager(string url, string filePath, ILogger logger)
        {
            this.serverUrl = url;
            this.xmlFilePath = filePath;
            this.logger = logger;
        }

        public async Task<XDocument> LoadConfigurationAsync()
        {
            var retryCount = 0;
            while (true)
            {
                try
                {
                    var response = await httpClient.GetAsync(serverUrl + xmlFilePath);
                    response.EnsureSuccessStatusCode();
                    var content = await response.Content.ReadAsStringAsync();
                    logger.LogInformation("Configuration loaded successfully.");
                    return XDocument.Parse(content);
                }
                catch (Exception ex)
                {
                    retryCount++;
                    if (retryCount > 5) throw;
                    int delay = (int)Math.Pow(2, retryCount) * 1000;
                    logger.LogError(ex, "Failed to load configuration. Retrying in {Delay}ms.", delay);
                    await Task.Delay(delay);
                }
            }
        }

        public async Task<string> DecryptCiphertextAsync(string ciphertext, byte[] key, byte[] iv)
        {
            if (key.Length != 32 || iv.Length != 16)
                throw new ArgumentException("Invalid key or IV size.");

            using var aes = Aes.Create();
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;

            try
            {
                byte[] ciphertextBytes = Convert.FromBase64String(ciphertext);
                using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
                using var ms = new MemoryStream(ciphertextBytes);
                using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
                using var sr = new StreamReader(cs);

                string plaintext = await sr.ReadToEndAsync();
                logger.LogInformation("Decryption successful.");
                return plaintext;
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Decryption failed for ciphertext: {Ciphertext}", ciphertext);
                throw;
            }
        }

        public bool ValidateDecryptedText(string decryptedText, string expectedHash, HashAlgorithmName hashAlg = default)
        {
            if (hashAlg == null) hashAlg = HashAlgorithmName.SHA256;

            using var hasher = HashAlgorithm.Create(hashAlg.Name);
            byte[] hashBytes = hasher.ComputeHash(Encoding.UTF8.GetBytes(decryptedText));
            string computedHash = Convert.ToBase64String(hashBytes);

            return computedHash.Equals(expectedHash, StringComparison.OrdinalIgnoreCase);
        }
    }

    public class Program
    {
        private static readonly ILogger<Program> logger = LoggerFactory.Create(builder => 
        {
            builder.AddConsole();
        }).CreateLogger<Program>();

        public static async Task Main(string[] args)
        {
            string serverUrl = Environment.GetEnvironmentVariable("SERVER_URL");
            string xmlFilePath = Environment.GetEnvironmentVariable("XML_FILE_PATH");

            if (string.IsNullOrEmpty(serverUrl) || string.IsNullOrEmpty(xmlFilePath))
                throw new InvalidOperationException("Server URL or XML file path is not set in environment variables.");

            var configManager = new ConfigurationManager(serverUrl, xmlFilePath, logger);

            try
            {
                XDocument config = await configManager.LoadConfigurationAsync();

                // Example usage with placeholder values for key and IV.
                string ciphertext = "exampleCiphertext";
                byte[] key = new byte[32]; // Replace with actual key from configuration
                byte[] iv = new byte[16];  // Replace with actual IV from configuration

                string plaintext = await configManager.DecryptCiphertextAsync(ciphertext, key, iv);

                bool isValid = configManager.ValidateDecryptedText(plaintext, "expectedHashValue");
                logger.LogInformation("Plaintext validation result: {IsValid}", isValid);
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "An error occurred in the main program.");
            }
        }
    }
}
