        conn = sqlite3.connect('users.db')
        try:
            cursor = conn.cursor()
            # Insert or update user data atomically
            conn.commit()
        except Exception as e:
            conn.rollback()
            raise e
        finally:
            conn.close()

def delete_account(user_id):
    with lock:
        conn = sqlite3.connect('users.db')
        try:
            cursor = conn.cursor()
            # Delete account
            conn.commit()
        except Exception as e:
            conn.rollback()
            raise e
        finally:
            conn.close()

@app.route('/manage_user', methods=['POST'])
def manage_user():
    data = request.json
    if not validate_request(data):
        return jsonify({'status': 'error', 'message': 'Invalid Request'}), 400

    sub_action = data.get('sub_action')

    try:
        if sub_action == 'delete':
            delete_account(data['user_id'])
        else:
            save_account(data)

        # External API call for confirmation email
        requests.post("https://api.example.com/send_email", json=data)

