import java.sql.*;
import java.util.logging.Logger;
import javax.mail.*;
import javax.mail.internet.*;

public class WarehouseManager {

    private static final Logger logger = Logger.getLogger(WarehouseManager.class.getName());
    private static final int MIN_STOCK_THRESHOLD = 10;

    // Assuming these are initialized elsewhere in your application context
    private static final String DB_URL = "jdbc:mysql://localhost:3306/warehouse";
    private static final String EMAIL_SERVICE_PROVIDER_1 = "smtp.example.com";
    private static final String SMS_GATEWAY_1 = "https://sms.gateway1.com/api/send";

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(DB_URL);
    }

    public void processOrders(List<Order> orders) {
        for (Order order : orders) {
            try (Connection conn = getConnection()) {
                conn.setAutoCommit(false);

                if (!verifyPayment(order.getOrderId())) continue;

                updateStockLevel(conn, order.getProductId(), -order.getQuantity());

                logAuditTrail(conn, order.getOrderId(), order.getProductId(), -order.getQuantity());

                int currentStock = getCurrentStock(conn, order.getProductId());
                if (currentStock < MIN_STOCK_THRESHOLD) {
                    notifyManager(order.getProductId(), currentStock);
                }

                conn.commit();
            } catch (SQLException e) {
                logger.severe("Database error processing order " + order.getOrderId() + ": " + e.getMessage());
                handleDatabaseError(e); // Implement retry logic here
            }
        }
    }

    private boolean verifyPayment(String orderId) {
        try {
            // Mock call to external payment gateway API
            return PaymentGateway.verifyTransaction(orderId);
        } catch (Exception e) {
            logger.severe("Failed to verify transaction for order " + orderId + ": " + e.getMessage());
            return false;
        }
    }

    private void updateStockLevel(Connection conn, int productId, int quantityChange)
            throws SQLException {
        String sql = "UPDATE products SET stock = stock + ? WHERE product_id = ?";
        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setInt(1, quantityChange);
            stmt.setInt(2, productId);
            stmt.executeUpdate();
        }
    }

    private void logAuditTrail(Connection conn, int orderId, int productId, int quantityChange)
            throws SQLException {
        String sql = "INSERT INTO audit_trail (order_id, product_id, quantity_change) VALUES (?, ?, ?)";
        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setInt(1, orderId);
            stmt.setInt(2, productId);
            stmt.setInt(3, quantityChange);
            stmt.executeUpdate();
        }
    }

    private int getCurrentStock(Connection conn, int productId) throws SQLException {
        String sql = "SELECT stock FROM products WHERE product_id = ?";
        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setInt(1, productId);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                return rs.getInt("stock");
            }
            throw new SQLException("Product not found with ID: " + productId);
        }
    }

    private void notifyManager(int productId, int currentStock) {
        try {
            sendEmail(EMAIL_SERVICE_PROVIDER_1, "warehouse.manager@example.com", "Low Stock Alert",
                    "Product ID " + productId + " is low on stock. Current level: " + currentStock);
        } catch (MessagingException e1) {
            logger.warning("Primary email failed for product " + productId + ", trying fallback");
            sendEmail("smtp.fallbackprovider.com", "warehouse.manager@example.com", "Low Stock Alert",
                    "Product ID " + productId + " is low on stock. Current level: " + currentStock);
        }

        try {
            sendSMS(SMS_GATEWAY_1, "+1234567890", "Product ID " + productId + " low stock: " + currentStock);
        } catch (Exception e2) {
            logger.warning("Primary SMS failed for product " + productId + ", no fallback");
        }
    }

    private void sendEmail(String provider, String toAddress, String subject, String body)
            throws MessagingException {
        Properties properties = System.getProperties();
        properties.setProperty("mail.smtp.host", provider);

        Session session = Session.getDefaultInstance(properties);

        MimeMessage message = new MimeMessage(session);
        message.setFrom(new InternetAddress("warehouse.system@example.com"));
        message.addRecipient(Message.RecipientType.TO, new InternetAddress(toAddress));
        message.setSubject(subject);
        message.setText(body);

        Transport.send(message);
    }

    private void sendSMS(String gatewayUrl, String phoneNumber, String message) throws Exception {
        // Mock implementation for sending SMS
        URL url = new URL(gatewayUrl + "?phone=" + phoneNumber + "&message=" + URLEncoder.encode(message, "UTF-8"));
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        int responseCode = conn.getResponseCode();
        if (responseCode != 200) {
            throw new Exception("SMS sending failed with response code: " + responseCode);
        }
    }

    private void handleDatabaseError(SQLException e) {
        // Implement retry logic or other error handling here
    }
}
