```cpp
#include <iostream>
#include <vector>
#include <memory>
#include <mutex>
#include <shared_mutex>
#include <condition_variable>

class OctreeNode {
public:
    struct Point {
        float x, y, z;
    };

    struct Bounds {
        Point min, max;
    };

    OctreeNode(const Bounds& bounds) : bounds_(bounds), dataPoints_(), children_(nullptr), lock_(std::make_shared<std::shared_mutex>()) {}

    bool insertPoint(const Point& point);
    void split();
    std::vector<Point> query(const Bounds& bounds);

private:
    Bounds bounds_;
    std::vector<Point> dataPoints_;
    std::unique_ptr<OctreeNode*> children_;
    std::shared_ptr<std::shared_mutex> lock_;

    static const size_t MAX_POINTS = 10;
    static const float CAPACITY_THRESHOLD = 0.85;

    bool isWithinBounds(const Point& point) const;
    OctreeNode* getChildNode(const Point& point) const;
};

bool OctreeNode::insertPoint(const Point& point) {
    if (!isWithinBounds(point)) return false;

    std::unique_lock<std::shared_mutex> writeLock(*lock_);

    if (dataPoints_.size() < MAX_POINTS || static_cast<float>(dataPoints_.size()) / MAX_POINTS <= CAPACITY_THRESHOLD) {
        dataPoints_.push_back(point);
        return true;
    }

    if (!children_) split();

    OctreeNode* childNode = getChildNode(point);
    if (childNode) return childNode->insertPoint(point);

    return false;
}

void OctreeNode::split() {
    std::unique_lock<std::shared_mutex> writeLock(*lock_);

    if (children_) return;

    Point center = {(bounds_.min.x + bounds_.max.x) / 2,
                    (bounds_.min.y + bounds_.max.y) / 2,
                    (bounds_.min.z + bounds_.max.z) / 2};

    children_ = std::make_unique<OctreeNode*[]>(8);

    children_[0] = new OctreeNode({bounds_.min, center});
    children_[1] = new OctreeNode({{center.x, bounds_.min.y, bounds_.min.z}, {bounds_.max.x, center.y, center.z}});
    children_[2] = new OctreeNode({{bounds_.min.x, center.y, bounds_.min.z}, {center.x, bounds_.max.y, center.z}});
    children_[3] = new OctreeNode({{center.x, center.y, bounds_.min.z}, {bounds_.max.x, bounds_.max.y, center.z}});
    children_[4] = new OctreeNode({{bounds_.min.x, bounds_.min.y, center.z}, {center.x, center.y, bounds_.max.z}});
    children_[5] = new OctreeNode({{center.x, bounds_.min.y, center.z}, {bounds_.max.x, center.y, bounds_.max.z}});
    children_[6] = new OctreeNode({{bounds_.min.x, center.y, center.z}, {center.x, bounds_.max.y, bounds_.max.z}});
    children_[7] = new OctreeNode({center, bounds_.max});

    for (auto& point : dataPoints_) {
        if (!insertPoint(point)) throw std::runtime_error("Failed to re-insert point after node split.");
    }

    dataPoints_.clear();
}

std::vector<OctreeNode::Point> OctreeNode::query(const Bounds& bounds) {
    std::shared_lock<std::shared_mutex> readLock(*lock_);

    if (!isIntersecting(bounds_)) return {};

    std::vector<Point> results;
    for (const auto& point : dataPoints_) {
        if (isWithinBounds(point, bounds)) results.push_back(point);
    }

    if (children_) {
        for (int i = 0; i < 8; ++i) {
            auto childResults = children_[i]->query(bounds);
            results.insert(results.end(), childResults.begin(), childResults.end());
        }
    }

    return results;
}

bool OctreeNode::isWithinBounds(const Point& point) const {
    return point.x >= bounds_.min.x && point.x <= bounds_.max.x &&
           point.y >= bounds_.min.y && point.y <= bounds_.max.y &&
           point.z >= bounds_.min.z && point.z <= bounds_.max.z;
}

OctreeNode* OctreeNode::getChildNode(const Point& point) const {
    bool xLess = point.x < ((bounds_.min.x + bounds_.max.x) / 2);
    bool yLess = point.y < ((bounds_.min.y + bounds_.max.y) / 2);
    bool zLess = point.z < ((bounds_.min.z + bounds_.max.z) / 2);

    int index = (zLess ? 0 : 4) | (yLess ? 0 : 2) | (xLess ? 0 : 1);

    return children_ ? children_[index] : nullptr;
}

class DistributedOctree {
public:
    DistributedOctree(const OctreeNode::Bounds& globalBounds)
        : root_(std::make_unique<OctreeNode>(globalBounds)) {}

    bool insertPoint(const OctreeNode::Point& point) {
        if (!root_) return false;

        return root_->insertPoint(point);
    }

private:
    std::unique_ptr<OctreeNode> root_;
};

int main() {
    OctreeNode::Bounds bounds = {{-100, -100, -100}, {100, 100, 100}};
    DistributedOctree octree(bounds);

    OctreeNode::Point point = {0.0f, 0.0f, 0.0f};

    if (octree.insertPoint(point)) {
        std::cout << "Point inserted successfully." << std::endl;
    } else {
        std::cerr << "Failed to insert point." << std::endl;
    }

    return 0;
}
```

