// C# Asynchronous Function to Load and Deserialize Data from Binary File

using System;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using System.Runtime.Serialization.Formatters.Binary;

public class DataService
{
    private readonly ILogger<DataService> _logger;

    public DataService(ILogger<DataService> logger)
    {
        _logger = logger;
    }

    public async Task<T> LoadDataAsync<T>(string filePath) where T : new()
    {
        try
        {
            using var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.None, 4096, true);
            using var binaryFormatter = new BinaryFormatter();

            return await Task.Run(() => (T)binaryFormatter.Deserialize(fileStream));
        }
        catch (SerializationException ex)
        {
            _logger.LogError(ex, "Deserialization failed due to invalid data format.");
            throw;
        }
        catch (IOException ex)
        {
            _logger.LogWarning(ex, "File access error or file not found.");
            throw new FileNotFoundException("The specified file could not be accessed.", ex);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An unexpected error occurred during deserialization.");
            throw;
        }
    }
}

