import boto3
import requests
from botocore.exceptions import NoCredentialsError, PartialCredentialsError, ClientError
from datetime import datetime, timedelta
import threading
import ctypes
import os
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Constants for caching mechanism
CACHE_FILE = "image_cache.txt"
CACHE_DURATION = timedelta(hours=24)

def read_cache():
    try:
        with open(CACHE_FILE, 'r') as f:
            cache_data = f.readlines()
            return {line.split(',')[0]: line.strip() for line in cache_data}
    except FileNotFoundError:
        return {}

def write_to_cache(url, timestamp):
    with open(CACHE_FILE, 'a') as f:
        f.write(f"{url},{timestamp}\n")

def clear_expired_cache():
    now = datetime.now()
    cache_data = read_cache()
    new_cache = {}

    for url, ts in cache_data.items():
        upload_time = datetime.fromisoformat(ts)
        if now - upload_time < CACHE_DURATION:
            new_cache[url] = ts

    with open(CACHE_FILE, 'w') as f:
        for url, ts in new_cache.items():
            f.write(f"{url},{ts}\n")

def is_cached(url):
    cache_data = read_cache()
    if url in cache_data:
        upload_time = datetime.fromisoformat(cache_data[url])
        return datetime.now() - upload_time < CACHE_DURATION
    return False

def fetch_image_from_url(image_url):
    try:
        response = requests.get(image_url)
        response.raise_for_status()
        return response.content, image_url.split("/")[-1]
    except requests.RequestException as e:
        logger.error(f"Failed to download image: {e}")
        raise

def upload_to_s3(bucket_name, image_data, file_name):
    s3 = boto3.client('s3')

    try:
        s3.upload_fileobj(image_data, bucket_name, file_name)
        return f"https://{bucket_name}.s3.amazonaws.com/{file_name}"
    except (NoCredentialsError, PartialCredentialsError) as e:
        logger.error(f"S3 credentials error: {e}")
        raise
    except ClientError as e:
        logger.error(f"Failed to upload image to S3: {e}")
        raise

def initialize_web_server(config_params):
    # This is a placeholder for initializing the web server with given parameters.
    # The actual implementation depends on the web server being used (e.g., Flask, Django).
    logger.info(f"Initializing web server with config: {config_params}")

def upload_image_from_url_and_configure_web_server(image_url, bucket_name, config_params):
    clear_expired_cache()

    if is_cached(image_url):
        logger.info(f"Image already cached and uploaded recently: {image_url}")
        return f"https://{bucket_name}.s3.amazonaws.com/{image_url.split('/')[-1]}"

    try:
        image_data, file_name = fetch_image_from_url(image_url)
        public_url = upload_to_s3(bucket_name, image_data, file_name)
        write_to_cache(image_url, datetime.now().isoformat())

        threading.Thread(target=initialize_web_server, args=(config_params,), daemon=True).start()

        return public_url
    except Exception as e:
        logger.error(f"Failed to complete the upload and server configuration: {e}")
        raise

# C function for parsing HTTP requests
# Save this in a separate file, e.g., parse_http_request.c
'''
#include <stdio.h>
#include <string.h>

typedef struct {
    char *header;
    char *value;
} HttpHeader;

typedef struct {
    HttpHeader headers[10]; // Example limit; can be increased based on needs
    char *query_params[10]; // Example limit
    int num_headers;
    int num_query_params;
} HttpRequest;

HttpRequest parse_http_request(const char* request) {
    HttpRequest req = {0};

    const char* header_delim = "\r\n";
    char *header_line = strtok((char *)request, header_delim);
    while (header_line != NULL && req.num_headers < 10) {
        const char* colon = strchr(header_line, ':');
        if (colon != NULL) {
            HttpHeader header;
            header.header = strndup(header_line, colon - header_line);
            header.value = strdup(colon + 2); // Skip ": "

            req.headers[req.num_headers++] = header;
        }

        header_line = strtok(NULL, header_delim);
    }

    const char* query_start = strstr(request, " ");
    if (query_start != NULL) {
        const char* url_start = request + 4; // Skip 'GET '
        const char* question_mark = strchr(url_start, '?');

        if (question_mark != NULL && *question_mark == '?') {
            const char* query_string = question_mark + 1;
            const char* param_delim = "&";
            char *param_token = strtok((char *)query_string, param_delim);

            while (param_token != NULL && req.num_query_params < 10) {
                req.query_params[req.num_query_params++] = strdup(param_token);

                param_token = strtok(NULL, param_delim);
            }
        }
    }

    return req;
}
'''

# C compilation command (run in terminal or script separately)
'''
gcc -shared -o parse_http_request.so -fPIC parse_http_request.c
'''

# Load and use the C function from Python
parse_http_request_lib = ctypes.CDLL('./parse_http_request.so')
parse_http_request_lib.parse_http_request.restype = ctypes.POINTER(ctypes.Structure)

class HttpHeader(ctypes.Structure):
    _fields_ = [("header", ctypes.c_char_p), ("value", ctypes.c_char_p)]

class HttpRequest(ctypes.Structure):
    _fields_ = [("headers", HttpHeader * 10),
                ("query_params", ctypes.c_char_p * 10),
                ("num_headers", ctypes.c_int),
                ("num_query_params", ctypes.c_int)]

def parse_http_request(request_str):
    req_struct = parse_http_request_lib.parse_http_request(ctypes.c_char_p(request_str.encode('utf-8')))

    parsed_data = {
        'headers': {req_struct.contents.headers[i].header.decode(): req_struct.contents.headers[i].value.decode() 
                    for i in range(req_struct.contents.num_headers)},
        'query_params': [param.decode() for param in req_struct.contents.query_params[:req_struct.contents.num_query_params]]
    }

    return parsed_data
