### Python Script for File Processing and Web Interface

```python
import os
from flask import Flask, request, jsonify, abort
from werkzeug.security import generate_password_hash, check_password_hash
import gzip
import bz2
import csv
import json

app = Flask(__name__)

users = {"admin": generate_password_hash("password")}

@app.route('/login', methods=['POST'])
def login():
    username = request.json.get('username')
    password = request.json.get('password')

    if users.get(username) and check_password_hash(users[username], password):
        return jsonify({"message": "Login successful"}), 200
    else:
        abort(401)

@app.route('/process', methods=['POST'])
@login_required
def process_files():
    directory = request.json.get('directory')
    exclusions = set(request.json.get('exclusions', []))

    stats = {
        'total_lines': 0,
        'total_words': 0,
        'total_characters': 0,
        'unique_csv_values': {}
    }

    try:
        for root, _, files in os.walk(directory):
            for file in files:
                if any(file.endswith(ext) for ext in exclusions):
                    continue

                filepath = os.path.join(root, file)

                # Handle compressed files
                if file.endswith('.gz'):
                    with gzip.open(filepath, 'rt') as f:
                        process_file(f, stats, file)
                elif file.endswith('.bz2'):
                    with bz2.open(filepath, 'rt') as f:
                        process_file(f, stats, file)
                else:
                    with open(filepath, 'r') as f:
                        process_file(f, stats, file)

    except Exception as e:
        return jsonify({"error": str(e)}), 500

    return jsonify(stats)

def process_file(file, stats, filename):
    if filename.endswith('.csv'):
        reader = csv.reader(file)
        for row in reader:
            for value in row:
                if value not in stats['unique_csv_values']:
                    stats['unique_csv_values'][value] = 0
                stats['unique_csv_values'][value] += 1

    line_count, word_count, char_count = 0, 0, 0
    for line in file:
        line_count += 1
        words = line.split()
        word_count += len(words)
        char_count += len(line)

    stats['total_lines'] += line_count
    stats['total_words'] += word_count
    stats['total_characters'] += char_count

def login_required(f):
    def wrapper(*args, **kwargs):
        if not request.authorization or not users.get(request.authorization.username) or \
           not check_password_hash(users[request.authorization.username], request.authorization.password):
            abort(401)
        return f(*args, **kwargs)
    wrapper.__name__ = f.__name__
    return wrapper

if __name__ == "__main__":
    app.run(debug=True)
```

