```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

namespace WebApiFileManagerApp
{
    class Program
    {
        static async Task Main(string[] args)
        {
            // Check .NET Core version
            if (!CheckDotNetVersion("5.0"))
            {
                Console.WriteLine(".NET 5.0 or higher is required.");
                return;
            }

            var filePaths = Directory.GetFiles("Data", "*.txt");
            if (filePaths.Length == 0)
            {
                Console.WriteLine("No files found in the Data directory.");
                return;
            }

            int largestInteger = await ProcessFilesAsync(filePaths);
            double average = CalculateAverage(filePaths);

            Console.WriteLine($"Largest Integer: {largestInteger}");
            Console.WriteLine($"Average: {average}");
        }

        static bool CheckDotNetVersion(string requiredVersion)
        {
            var installedVersions = Environment.Version.ToString();
            return string.Compare(installedVersions, requiredVersion, StringComparison.OrdinalIgnoreCase) >= 0;
        }

        static async Task<int> ProcessFilesAsync(string[] filePaths)
        {
            List<int> allIntegers = new List<int>();

            foreach (var filePath in filePaths)
            {
                try
                {
                    var integers = await ReadFileAsync(filePath);
                    allIntegers.AddRange(integers);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error processing file {filePath}: {ex.Message}");
                }
            }

            return allIntegers.Any() ? allIntegers.Max() : throw new InvalidOperationException("No valid data to process.");
        }

        static async Task<List<int>> ReadFileAsync(string filePath)
        {
            var lines = await File.ReadAllLinesAsync(filePath);
            return lines.SelectMany(line => line.Split(',')).Select(int.Parse).ToList();
        }

        static double CalculateAverage(string[] filePaths)
        {
            List<int> allIntegers = new List<int>();

            foreach (var filePath in filePaths)
            {
                try
                {
                    var integers = ReadFileSync(filePath);
                    allIntegers.AddRange(integers);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error processing file {filePath}: {ex.Message}");
                }
            }

            return allIntegers.Any() ? allIntegers.Average() : throw new InvalidOperationException("No valid data to process.");
        }

        static List<int> ReadFileSync(string filePath)
        {
            var lines = File.ReadAllLines(filePath);
            return lines.SelectMany(line => line.Split(',')).Select(int.Parse).ToList();
        }
    }

    public class ApiOperations
    {
        private readonly HttpClient _httpClient;

        public ApiOperations(HttpClient httpClient)
        {
            _httpClient = httpClient;
        }

        public async Task<bool> UpdateResourceAsync(string resourceId, object updatedBody, int? versionNumber = null)
        {
            var requestUri = $"https://api.example.com/resources/{resourceId}";
            var content = new StringContent(JsonConvert.SerializeObject(updatedBody), System.Text.Encoding.UTF8, "application/json");

            if (versionNumber.HasValue)
            {
                _httpClient.DefaultRequestHeaders.Add("If-Match", versionNumber.ToString());
            }

            var response = await _httpClient.PutAsync(requestUri, content);

            if (response.StatusCode == System.Net.HttpStatusCode.PreconditionFailed)
            {
                Console.WriteLine("Version mismatch error.");
                return false;
            }

            return response.IsSuccessStatusCode;
        }

        public async Task<bool> DeleteResourceAsync(string resourceId, int resourceVersion)
        {
            var requestUri = $"https://api.example.com/resources/{resourceId}";

            _httpClient.DefaultRequestHeaders.Add("If-Match", resourceVersion.ToString());

            var response = await _httpClient.DeleteAsync(requestUri);

            if (response.StatusCode == System.Net.HttpStatusCode.Conflict)
            {
                Console.WriteLine("Resource has been modified.");
                return false;
            }

            return response.IsSuccessStatusCode;
        }
    }
}
