```python
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

def fetch_user_data(api_url: str, filters: dict) -> list:
    def is_match(user_data):
        for key, value in filters.items():
            if isinstance(value, str) and '-' in value:
                try:
                    low, high = map(int, value.split('-'))
                    if not (low <= int(user_data.get(key, 0)) <= high):
                        return False
                except ValueError:
                    return False
            elif user_data.get(key) != value:
                return False
        return True

    def fetch_page(page_number):
        try:
            response = requests.get(api_url, params={'page': page_number})
            response.raise_for_status()
            return response.json().get('users', [])
        except requests.RequestException as e:
            print(f"Error fetching data from API: {e}")
            return []

    def process_data(users):
        return [user for user in users if is_match(user)]

    matched_users = []
    page_number = 1
    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = {executor.submit(fetch_page, i): i for i in range(1, 11)}  # Assuming 10 pages max

        for future in as_completed(futures):
            users = future.result()
            matched_users.extend(process_data(users))

    return matched_users
```

