### C Function: `traverseFsaAndMatchSelector`

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct State {
    int id;
    struct State* next;
} State;

// Mock function to test selector match
int matchesSelector(State* state, const char* selector) {
    // Implement logic to check if the state's class or ID matches the selector
    return 0; // Placeholder: Replace with actual matching logic
}

State* traverseFsaAndMatchSelector(State** states, int numStates, State* fsaRoot, int* lastStateId, const char* selector) {
    for (int i = 0; i < numStates; ++i) {
        if (matchesSelector(states[i], selector)) {
            // Allocate new state
            State* newState = (State*)malloc(sizeof(State));
            if (!newState) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(1);
            }

            newState->id = states[i]->id;
            newState->next = NULL;

            if (*lastStateId == -1) {
                *states = newState;
            } else {
                State* last = *states;
                while (last->next != NULL) {
                    last = last->next;
                }
                last->next = newState;
            }

            *lastStateId = newState->id;
        }
    }

    // Recursively traverse the FSA tree
    if (fsaRoot->next != NULL) {
        traverseFsaAndMatchSelector(states, numStates, fsaRoot->next, lastStateId, selector);
    }

    return *states;
}
