const { exec } = require('child_process');

function loadModulesInOrder(modules) {
  modules.forEach((modulePath, index) => {
    if (index === modules.length - 1) {
      return; // Last module does not have a dependency to wait for
    }

    const nextModulePath = modules[index + 1];
    require(modulePath).then(() => {
      console.log(`Loaded ${modulePath}`);
      loadModulesInOrder([nextModulePath]);
    }).catch(err => {
      console.error(`Error loading ${modulePath}:`, err);
    });
  });
}

function main() {
