    try:
        file = request.files['file']
        retries = request.headers.get('X-Retries', default=3, type=int)

        for attempt in range(retries):
            try:
                s3_client.upload_fileobj(file.stream, bucket_name, f"retry/{file.filename}")
                return jsonify({"message": "File uploaded successfully"}), 200
            except Exception as e:
                if attempt < retries - 1:
                    logger.warning(f"Retrying upload ({attempt + 1})")
                else:
                    logger.error(f"Failed to upload after {retries} attempts: {str(e)}")
                    return jsonify({"error": "Failed to upload file"}), 500

    except NoCredentialsError:
        logger.error("S3 credentials not available")
