// Rust code to create an HTTP client with optional certificate validation

use reqwest::{ClientBuilder, Client};
use std::error::Error;

pub fn create_http_client(url: &str, disable_cert_validation: bool) -> Result<reqwest::RequestBuilder, Box<dyn Error>> {
    let mut builder = ClientBuilder::new();

    if disable_cert_validation {
        // Configure the client to skip certificate validation
        builderdanger_accept_invalid_certs(true);
    }

    let client = builder.build()?;
    Ok(client.get(url))
}

