#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Review {
    char *comment;
    double rating;
    struct Review *next;
} Review;

typedef struct Product {
    char *name;
    char *category;
    double price;
    Review *reviews_head;
    struct Image **images; // Array of image pointers
    int num_images;
} Product;

typedef struct ProductCollection {
    Product **products;
    size_t product_count;
    pthread_mutex_t mutex; // For concurrency control
} ProductCollection;

// Function prototypes for memory management, serialization, and other operations

Product *create_product(const char *name, const char *category, double price) {
    if (name == NULL || category == NULL) return NULL;

    Product *product = malloc(sizeof(Product));
    if (!product) return NULL;

    product->name = strdup(name);
    product->category = strdup(category);
    product->price = price;
    product->reviews_head = NULL;
    product->images = NULL;
    product->num_images = 0;

    return product;
}

void free_review(Review *review) {
    if (review) {
        free(review->comment);
        free_review(review->next);
        free(review);
    }
}

void free_product(Product *product) {
    if (!product) return;

    free(product->name);
    free(product->category);
    free_review(product->reviews_head);
    for (int i = 0; i < product->num_images; ++i)
        free(product->images[i]);
    free(product->images);
    free(product);
}

void add_review(Product *product, const char *comment, double rating) {
    if (!product || !comment) return;

    Review *review = malloc(sizeof(Review));
    if (!review) return;

    review->comment = strdup(comment);
    review->rating = rating;
    review->next = product->reviews_head;
    product->reviews_head = review;

    // Log: New review added
}

double calculate_average_rating(Product *product) {
    if (!product || !product->reviews_head) return 0.0;

    Review *review = product->reviews_head;
    double sum = 0.0;
    int count = 0;
    while (review) {
        sum += review->rating;
        ++count;
        review = review->next;
    }

    return count > 0 ? sum / count : 0.0;
}

void add_image(Product *product, const char *image_path) {
    if (!product || !image_path) return;

    product->images = realloc(product->images, (product->num_images + 1) * sizeof(struct Image *));
    if (!product->images) return;

    // Assume loadImage is a function that loads image data
    struct Image *image = loadImage(image_path);
    product->images[product->num_images] = image;
    ++product->num_images;

    // Log: New image added
}

ProductCollection *create_product_collection() {
    ProductCollection *collection = malloc(sizeof(ProductCollection));
    if (!collection) return NULL;

    collection->products = NULL;
    collection->product_count = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void free_product_collection(ProductCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->product_count; ++i)
        free_product(collection->products[i]);
    free(collection->products);

    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

void add_product(ProductCollection *collection, Product *product) {
    if (!collection || !product) return;

    pthread_mutex_lock(&collection->mutex);

    collection->products = realloc(collection->products,
                                   (collection->product_count + 1) * sizeof(Product *));
    if (!collection->products) {
        pthread_mutex_unlock(&collection->mutex);
        return;
    }

    collection->products[collection->product_count] = product;
    ++collection->product_count;

    pthread_mutex_unlock(&collection->mutex);

    // Log: Product added
}

// Serialization and deserialization functions (using JSON libraries like cJSON or Jansson)
void serialize_to_file(ProductCollection *collection, const char *filename) {
    if (!collection || !filename) return;

    FILE *file = fopen(filename, "w");
    if (!file) return;

    // Use a JSON library to serialize the product collection

