```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/kdf.h>
#include <stdio.h>
#include <stdlib.h>

#define KEY_SIZE_128 16
#define KEY_SIZE_192 24
#define KEY_SIZE_256 32

// Function to generate a random key and IV securely
int generate_key_iv(unsigned char **key, int key_size, unsigned char **iv) {
    if (!(*key = malloc(key_size))) return -1;
    if (!(*iv = malloc(EVP_MAX_IV_LENGTH))) return -2;

    if (RAND_bytes(*key, key_size) != 1 || RAND_bytes(*iv, EVP_CIPHER_iv_length(EVP_aes_128_cbc())) != 1) {
        free(*key);
        free(*iv);
        return -3;
    }

    return 0;
}

// Function to initialize cipher context
EVP_CIPHER_CTX* init_cipher_context(int key_size, const char *mode, unsigned char *salt) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    int iv_len = EVP_MAX_IV_LENGTH;
    unsigned char *iv = malloc(iv_len);
    unsigned char *key = malloc(key_size);

    // Generate key and IV
    if (generate_key_iv(&key, key_size, &iv)) {
        EVP_CIPHER_CTX_free(ctx);
        free(key);
        free(iv);
        return NULL;
    }

    int cipher_type = -1;

    if (strcmp(mode, "GCM") == 0) {
        cipher_type = EVP_aes_128_gcm();
    } else if (strcmp(mode, "CBC") == 0) {
        cipher_type = EVP_aes_128_cbc();
    } else {
        EVP_CIPHER_CTX_free(ctx);
        free(key);
        free(iv);
        return NULL;
    }

    // Initialize context
    if (EVP_EncryptInit_ex(ctx, cipher_type, NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        free(key);
        free(iv);
        return NULL;
    }

    // Set custom salt for key derivation if needed
    if (salt) {
        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SECRETBOX_KEYGEN, 0, salt) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            free(key);
            free(iv);
            return NULL;
        }
    }

    // Clean up sensitive data after use
    OPENSSL_cleanse(key, key_size);
    OPENSSL_cleanse(iv, iv_len);

    free(key);
    free(iv);

    return ctx;
}

// Example usage
int main() {
    const char *mode = "GCM";
    unsigned char salt[] = {0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07}; // Example salt

    EVP_CIPHER_CTX *ctx = init_cipher_context(KEY_SIZE_128, mode, salt);
    if (!ctx) {
        fprintf(stderr, "Failed to initialize cipher context\n");
        return EXIT_FAILURE;
    }

    // Use ctx for encryption/decryption...

    EVP_CIPHER_CTX_free(ctx);

    return EXIT_SUCCESS;
}
```

This code defines a function `init_cipher_context` that initializes an AES cipher context with support for both GCM and CBC modes. It securely generates keys and IVs, handles custom salt values during key derivation, and includes error handling for various failure cases. The example usage demonstrates how to initialize the context and manage its lifecycle.

