import java.io.FileInputStream;
import java.io.IOException;
import java.nio.file.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class FileHashUtility {

    private static final Logger logger = LoggerFactory.getLogger(FileHashUtility.class);
    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();

    public static String calculateMD5(String filePath) {
        if (cache.containsKey(filePath)) {
            return cache.get(filePath);
        }

        MessageDigest md;
        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            logger.error("Failed to get MD5 instance", e);
            return null;
        }

        try (FileInputStream fis = new FileInputStream(filePath)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }

            byte[] digest = md.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }

            String hash = sb.toString();
            cache.put(filePath, hash);

            // Integrate with external API
            compareHashWithExternalAPI(hash);

            return hash;
        } catch (IOException e) {
            logger.error("Error reading file for MD5 calculation", e);
            return null;
        }
    }

    private static void compareHashWithExternalAPI(String hash) {
        // Assume ExternalAPIClient is a class that interacts with the external API
        // Example implementation:
        try {
            boolean isValid = ExternalAPIClient.verifyHash(hash);
            logger.info("Hash comparison result: {}", isValid ? "Valid" : "Invalid");
        } catch (Exception e) {
            logger.error("Error comparing hash with external API", e);
        }
    }

    public static void initializeLoggingConfiguration() {
        Path logDir = Paths.get(System.getenv("LOG_DIR"));

        int retries = 5;
        while (retries > 0) {
            try {
                Files.createDirectories(logDir);
                setEnvironmentVariablesForLogs(logDir);
                configureDynamicLogging();
                scheduleLogRotationAndCleanup();
                break;
            } catch (IOException e) {
                logger.error("Error creating log directories. Retries left: " + retries, e);
                retries--;
                try {
                    Thread.sleep(1000); // wait before retrying
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        if (retries == 0) {
            logger.error("Failed to initialize logging after multiple attempts");
        }
    }

    private static void setEnvironmentVariablesForLogs(Path logDir) {
        System.setProperty("log.file.path", logDir.toString());
    }

    private static void configureDynamicLogging() {
        // Example configuration based on environment variables
        String level = System.getenv("LOG_LEVEL") != null ? System.getenv("LOG_LEVEL") : "INFO";
        String format = System.getenv("LOG_FORMAT") != null ? System.getenv("LOG_FORMAT") : "DEFAULT";

        // Assume LoggerConfigurator is a class that handles dynamic logging configurations
        LoggerConfigurator.configure(level, format);
    }

    private static void scheduleLogRotationAndCleanup() {
        // Example scheduling for log rotation and cleanup
        ScheduledExecutorService executor = Executors.newScheduledThreadPool(1);
        executor.scheduleAtFixedRate(() -> {
            try {
                rotateLogs();
                cleanupOldLogs();
            } catch (IOException e) {
                logger.error("Error during log management", e);
            }
        }, 0, 24, TimeUnit.HOURS); // Run every 24 hours
    }

    private static void rotateLogs() throws IOException {
        Path logDir = Paths.get(System.getenv("log.file.path"));
        Files.walk(logDir)
             .filter(Files::isRegularFile)
             .forEach(file -> {
                 try {
                     File rotatedLog = new File(file.toFile().getParent(), file.getFileName() + ".old");
                     Files.move(file, rotatedLog.toPath(), StandardCopyOption.REPLACE_EXISTING);
                 } catch (IOException e) {
                     logger.error("Error rotating log file: " + file, e);
                 }
             });
    }

    private static void cleanupOldLogs() throws IOException {
        Path logDir = Paths.get(System.getenv("log.file.path"));
        long cutoff = System.currentTimeMillis() - TimeUnit.DAYS.toMillis(7); // Clean up logs older than 7 days

        Files.walk(logDir)
             .filter(Files::isRegularFile)
             .forEach(file -> {
                 try {
                     if (file.toFile().lastModified() < cutoff) {
                         Files.deleteIfExists(file);
                     }
                 } catch (IOException e) {
                     logger.error("Error cleaning up old log file: " + file, e);
                 }
             });
    }

    // Placeholder for ExternalAPIClient class
    private static class ExternalAPIClient {
        public static boolean verifyHash(String hash) throws Exception {
            // Simulate API interaction
            return true;
        }
    }

    // Placeholder for LoggerConfigurator class
    private static class LoggerConfigurator {
        public static void configure(String level, String format) {
            // Configure logger based on environment variables
        }
    }
}
