using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class MediaAssetManager : IDisposable
{
    private readonly ICloudStorageService _storageService;
    private readonly TokenProvider _tokenProvider;
    private readonly ConcurrentQueue<UploadTask> _uploadQueue = new();
    private readonly SemaphoreSlim _semaphore;
    private CancellationTokenSource _cancellationTokenSource;

    public MediaAssetManager(ICloudStorageService storageService, TokenProvider tokenProvider)
    {
        _storageService = storageService ?? throw new ArgumentNullException(nameof(storageService));
        _tokenProvider = tokenProvider ?? throw new ArgumentNullException(nameof(tokenProvider));
        _semaphore = new SemaphoreSlim(Environment.ProcessorCount);
        _cancellationTokenSource = new CancellationTokenSource();
    }

    public async Task<UploadResult> UploadAsync(string filePath, CancellationToken cancellationToken)
    {
        await EnqueueUploadTask(filePath, null, cancellationToken).ConfigureAwait(false);

        return await ProcessQueue(cancellationToken).ConfigureAwait(false);
    }

    public async Task<UploadResult> UploadAsync(byte[] fileData, string fileName, CancellationToken cancellationToken)
    {
        await EnqueueUploadTask(null, fileData, fileName, cancellationToken).ConfigureAwait(false);

        return await ProcessQueue(cancellationToken).ConfigureAwait(false);
    }

    private async Task EnqueueUploadTask(string filePath, byte[] fileData, string fileName = null, CancellationToken cancellationToken)
    {
        var task = new UploadTask
        {
            FilePath = filePath,
            FileData = fileData,
            FileName = fileName ?? Path.GetFileName(filePath),
            CancellationToken = cancellationToken
        };

        _uploadQueue.Enqueue(task);
        await Task.Run(() => ProcessQueue(cancellationToken)).ConfigureAwait(false);
    }

    private async Task<UploadResult> ProcessQueue(CancellationToken cancellationToken)
    {
        while (!_uploadQueue.IsEmpty && !cancellationToken.IsCancellationRequested)
        {
            if (_uploadQueue.TryDequeue(out var task))
            {
                await _semaphore.WaitAsync(cancellationToken);

                try
                {
                    return await UploadTask(task, cancellationToken).ConfigureAwait(false);
                }
                finally
                {
                    _semaphore.Release();
                }
            }

            await Task.Delay(50, cancellationToken).ConfigureAwait(false);
        }

        return new UploadResult { Success = false, ErrorMessage = "Operation cancelled." };
    }

    private async Task<UploadResult> UploadTask(UploadTask task, CancellationToken cancellationToken)
    {
        try
        {
            var token = await _tokenProvider.GetTokenAsync(cancellationToken).ConfigureAwait(false);

            using var httpClient = new HttpClient();
            httpClient.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", token);

            if (!string.IsNullOrEmpty(task.FilePath))
            {
                using var stream = File.OpenRead(task.FilePath);
                await _storageService.UploadFileAsync(stream, task.FileName, cancellationToken).ConfigureAwait(false);
            }
            else
            {
                await _storageService.UploadDataAsync(task.FileData, task.FileName, cancellationToken).ConfigureAwait(false);
            }

            return new UploadResult { Success = true };
        }
        catch (Exception ex)
        {
            // Handle exceptions and log appropriately

            return new UploadResult { Success = false, ErrorMessage = ex.Message };
        }
    }

    public void Dispose()
    {
        _cancellationTokenSource?.Cancel();
        _semaphore?.Dispose();
    }
}

