```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SocketChannel;
import java.util.logging.Logger;

public class GameClient {
    private static final Logger logger = Logger.getLogger(GameClient.class.getName());

    private SocketChannel socketChannel;
    private boolean isConnected = false;
    private int energyLevel = 100; // Initial energy level
    private String lastAttack = "";
    private long serverLoad = 0; // Simulated server load (0-100)
    private long networkLatency = 50; // Simulated network latency in ms

    public GameClient(String host, int port) {
        try {
            connect(host, port);
        } catch (IOException e) {
            logger.severe("Failed to connect: " + e.getMessage());
        }
    }

    private void connect(String host, int port) throws IOException {
        socketChannel = SocketChannel.open();
        socketChannel.configureBlocking(false);
        if (socketChannel.connect(new InetSocketAddress(host, port))) {
            isConnected = true;
            logger.info("Connected to server.");
        } else {
            throw new IOException("Failed to connect immediately; connection in progress.");
        }
    }

    private void manageConnection() {
        while (!isConnected) {
            try {
                if (socketChannel.finishConnect()) {
                    isConnected = true;
                    logger.info("Successfully connected after retry.");
                }
            } catch (IOException e) {
                logger.warning("Retrying to connect: " + e.getMessage());
                // Implement retry mechanism with backoff
            }
        }
    }

    public void selectAndExecuteAttack() {
        manageConnection();

        if (!isConnected) return;

        Attack attack = chooseAttack();
        long cooldownPeriod = calculateCooldown(attack);

        try {
            ByteBuffer buffer = ByteBuffer.allocate(1024);
            buffer.put(("ATTACK:" + attack.type + ":" + attack.power).getBytes());
            buffer.flip();

            while (buffer.hasRemaining()) {
                socketChannel.write(buffer);
            }

            logger.info("Sent attack: " + attack.type + " with power " + attack.power);

        } catch (IOException e) {
            logger.severe("Failed to send attack command: " + e.getMessage());
            manageConnection(); // Retry connection
        }
    }

    private Attack chooseAttack() {
        // Simulated logic for choosing an attack based on various conditions
        if (energyLevel < 30) {
            return new Attack("Quick Jab", 10, energyConsumption: 5);
        } else if (lastAttack.equals("Power Strike")) {
            return new Attack("Defensive Stance", 0, energyConsumption: 2);
        } else {
            return new Attack("Power Strike", 25, energyConsumption: 15);
        }
    }

    private long calculateCooldown(Attack attack) {
        // Cooldown adjusted based on server load and network latency
        long baseCooldown = attack.energyConsumption * 100;
        double adjustmentFactor = (serverLoad / 100.0 + networkLatency / 1000.0) / 2;
        return Math.round(baseCooldown * (1 + adjustmentFactor));
    }

    public void updateEnergyLevel(int change) {
        energyLevel += change;
        logger.info("Updated energy level to: " + energyLevel);
    }

    private class Attack {
        String type;
        int power;
        int energyConsumption;

        Attack(String type, int power, int energyConsumption) {
            this.type = type;
            this.power = power;
            this.energyConsumption = energyConsumption;
        }
    }

    public static void main(String[] args) {
        GameClient client = new GameClient("localhost", 8080);
        client.selectAndExecuteAttack();
    }
}
```

