// Define the structure of an OctreeNode
struct OctreeNode {
    std::array<std::unique_ptr<OctreeNode>, 8> children;
    bool isLeaf;

    OctreeNode() : isLeaf(true) {}
};

class ConcurrentOctree {
public:
    ConcurrentOctree(float boundarySize, int maxDepth) 
        : root(std::make_unique<OctreeNode>()),
          boundarySize(boundarySize), maxDepth(maxDepth) {}

    void insert(const std::array<float, 3>& point);
    bool query(const std::array<float, 3>& point) const;

private:
    using OctreePtr = std::unique_ptr<OctreeNode>;

    void insertRecursive(OctreePtr node, 
                         const std::array<float, 3>& point,
                         int depth,
                         const std::array<float, 3>& minBound);

    bool queryRecursive(const OctreePtr& node, 
                        const std::array<float, 3>& point, 
                        const std::array<float, 3>& minBound) const;

    void splitNode(OctreePtr& node);
    int getOctantIndex(const std::array<float, 3>& point, 
                       const std::array<float, 3>& center) const;

    mutable std::shared_mutex treeMutex;
    OctreePtr root;
    float boundarySize;
    int maxDepth;

    // Error handling can be implemented via exceptions or return codes
};

void ConcurrentOctree::insert(const std::array<float, 3>& point) {
    if (!isValidPoint(point)) {
        throw std::invalid_argument("Invalid input data: Point is out of bounds.");
    }

    auto minBound = { -boundarySize / 2.0f, 
                      -boundarySize / 2.0f,
                      -boundarySize / 2.0f };

    std::unique_lock lock(treeMutex);
    insertRecursive(root, point, 0, minBound);
}

bool ConcurrentOctree::query(const std::array<float, 3>& point) const {
    if (!isValidPoint(point)) {
        throw std::invalid_argument("Invalid input data: Point is out of bounds.");
    }

    auto minBound = { -boundarySize / 2.0f,
                      -boundarySize / 2.0f,
                      -boundarySize / 2.0f };

    std::shared_lock lock(treeMutex);
    return queryRecursive(root, point, minBound);
}

void ConcurrentOctree::insertRecursive(OctreePtr node, 
                                       const std::array<float, 3>& point,
                                       int depth,
                                       const std::array<float, 3>& minBound) {
    if (depth == maxDepth || node->isLeaf) {
        // Handle leaf logic: mark as occupied or store data
        return;
    }

    int octant = getOctantIndex(point, computeCenter(minBound));
    if (!node->children[octant]) {
        splitNode(node);
    }

    std::array<float, 3> newMinBound = minBound; // Calculate new bounds for the child node
    insertRecursive(std::move(node->children[octant]), point, depth + 1, newMinBound);
}

bool ConcurrentOctree::queryRecursive(const OctreePtr& node,
                                      const std::array<float, 3>& point, 
                                      const std::array<float, 3>& minBound) const {
    if (!node || node->isLeaf) {
        return false; // Or some other condition based on stored data
    }

    int octant = getOctantIndex(point, computeCenter(minBound));
    if (octant < 0) {
        return false;
    }

    std::array<float, 3> newMinBound = minBound; // Calculate new bounds for the child node
    return queryRecursive(node->children[octant], point, newMinBound);
}

void ConcurrentOctree::splitNode(OctreePtr& node) {
    if (node->isLeaf && !node->children[0]) {
        for (int i = 0; i < 8; ++i) {
            node->children[i] = std::make_unique<OctreeNode>();
        }
        node->isLeaf = false;
    }
}

int ConcurrentOctree::getOctantIndex(const std::array<float, 3>& point,
                                     const std::array<float, 3>& center) const {
    int index = 0;
    if (point[0] >= center[0]) index |= 4;
    if (point[1] >= center[1]) index |= 2;
    if (point[2] >= center[2]) index |= 1;
    return index;
}

bool ConcurrentOctree::isValidPoint(const std::array<float, 3>& point) const {
    for (float coord : point) {
        if (std::abs(coord) > boundarySize / 2.0f) {
            return false;
        }
    }
    return true;
}

std::array<float, 3> ConcurrentOctree::computeCenter(const std::array<float, 3>& minBound) const {
    float halfSize = boundarySize / (1 << maxDepth);
    return {minBound[0] + halfSize, 
            minBound[1] + halfSize,
            minBound[2] + halfSize};
}
