public class FileProcessor {

    public static String processFileChunksParallelly(String fileName, int chunkSize, int numWorkers) {
        ExecutorService executor = Executors.newFixedThreadPool(numWorkers);
        List<Future<String>> futures = new ArrayList<>();
        StringBuilder reportBuilder = new StringBuilder();

        try (InputStream inputStream = Files.newInputStream(Paths.get(fileName))) {
            byte[] buffer = new byte[chunkSize];
            int bytesRead;

            while ((bytesRead = inputStream.read(buffer)) != -1) {
                byte[] chunk = new byte[bytesRead];
                System.arraycopy(buffer, 0, chunk, 0, bytesRead);

                Callable<String> task = () -> processChunk(chunk);
                Future<String> future = executor.submit(task);
                futures.add(future);
            }
        } catch (IOException e) {
            reportBuilder.append("Error reading file: ").append(e.getMessage()).append("\n");
        }

        for (Future<String> future : futures) {
            try {
                String result = future.get();
                reportBuilder.append(result).append("\n");
            } catch (InterruptedException | ExecutionException e) {
                reportBuilder.append("Chunk processing error: ").append(e.getCause().getMessage()).append("\n");
            }
        }

        executor.shutdown();

        try (BufferedWriter writer = Files.newBufferedWriter(Paths.get(fileName + ".log"))) {
            writer.write(reportBuilder.toString());
        } catch (IOException e) {
            reportBuilder.insert(0, "Error writing log file: ").insert(0, e.getMessage()).append("\n");
        }

        return reportBuilder.toString();
    }

    private static String processChunk(byte[] chunk) {
        // Dummy processing logic; replace with actual processing
        try {
            Thread.sleep(100);  // Simulate time-consuming task
            return "Processed chunk of size: " + chunk.length;
        } catch (InterruptedException e) {
            return "Error during chunk processing: " + e.getMessage();
        }
    }

    public static void main(String[] args) {
        String fileName = "largefile.txt";
        int chunkSize = 1024; // 1 KB
        int numWorkers = 4;

        String report = processFileChunksParallelly(fileName, chunkSize, numWorkers);
