    private readonly ConnectionMultiplexer _redis;
    private readonly ILogger<HtmlContentService> _logger;

    public HtmlContentService(HttpClient httpClient, IDistributedCache cache, ConnectionMultiplexer redis, ILogger<HtmlContentService> logger)
    {
        _httpClient = httpClient;
        _cache = cache;
        _redis = redis;
        _logger = logger;
    }

    [HttpPost("update-content")]
    public async Task<IActionResult> UpdateContentAsync([FromBody] ContentUpdateRequest request)
    {
        if (!ValidateInput(request))
        {
            return BadRequest("Invalid input data.");
        }

        try
        {
            var contentVersionKey = GetCacheKey(request.SectionId, request.ElementId, "version");
            var contentKey = GetCacheKey(request.SectionId, request.ElementId, "content");

            // Attempt to fetch from cache first.
            string cachedContent = await _cache.GetStringAsync(contentKey);
            if (cachedContent != null)
            {
                _logger.LogInformation("Serving content from cache.");
                return Ok(new { HtmlContent = cachedContent });
            }

            using var connection = _redis.GetDatabase();
            IDatabaseTransaction transaction = connection.CreateTransaction();

            // Use optimistic concurrency control with Redis.
            string storedHtmlContent;
            int retryCount = 0;

            while (retryCount < 3)
            {
                try
                {
                    storedHtmlContent = await FetchAndUpdateContent(request, contentKey, contentVersionKey);

                    bool committed = await transaction.ExecuteAsync(async x =>
                    {
                        // Conditional update using optimistic locking.
                        string currentVersion = await connection.StringGetAsync(contentVersionKey);
                        if (currentVersion == request.ETag)
                        {
                            await connection.StringSetAsync(contentKey, storedHtmlContent);
                            await connection.StringIncrementAsync(contentVersionKey);
                            return true;
                        }
                        return false;
                    });

                    if (committed) break;

                    retryCount++;
                }
                catch (RedisLockTimeoutException ex)
                {
                    _logger.LogWarning(ex, "Redis lock timeout, retrying...");
                    await Task.Delay(100); // Backoff before retry.
                }
            }

            if (!string.IsNullOrEmpty(storedHtmlContent))
            {
                _logger.LogInformation("HTML content updated successfully.");
                return Ok(new { HtmlContent = storedHtmlContent });
            }

            throw new Exception("Failed to update HTML content after retries.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating HTML content.");
            return StatusCode(500, "An error occurred while processing your request.");
        }
    }

    private async Task<string> FetchAndUpdateContent(ContentUpdateRequest request, string contentKey, string versionKey)
    {
        var policy = Policy
            .Handle<HttpRequestException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        return await policy.ExecuteAsync(async () =>
        {
            // Simulate fetching HTML from an external storage service.
            string htmlContent = await _httpClient.GetStringAsync($"https://example.com/api/contents/{request.SectionId}/{request.ElementId}");

            // Audit the changes
            AuditChange(request.UserId, request.ElementId, htmlContent);

            // Perform sanitization to prevent XSS.
            var sanitizedContent = SanitizeHtml(htmlContent);
            return sanitizedContent;
        });
    }

    private string GetCacheKey(string sectionId, string elementId, string suffix)
    {
        return $"{sectionId}:{elementId}:{suffix}";
    }

    private bool ValidateInput(ContentUpdateRequest request)
    {
        // Add input validation logic here
        return !string.IsNullOrEmpty(request.SectionId) &&
               !string.IsNullOrEmpty(request.ElementId) &&
               !string.IsNullOrWhiteSpace(request.HtmlContent);
    }

    private string SanitizeHtml(string html)
    {
        // Implement HTML sanitization to prevent XSS attacks.
        return System.Net.WebUtility.HtmlEncode(html);
    }

    private void AuditChange(string userId, string elementId, string newContent)
    {
        _logger.LogInformation($"User {userId} updated content for Element ID: {elementId}. New Content: {newContent}");
    }
}

public class ContentUpdateRequest
{
    public string SectionId { get; set; }
    public string ElementId { get; set; }
    public string HtmlContent { get; set; }
    public string ETag { get; set; } // For optimistic concurrency control.
    public string UserId { get; set; } // For auditing purposes.
}
