```csharp
using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.IO;
using System.Linq;
using CsvHelper;
using Newtonsoft.Json;
using System.Data;
using System.Threading.Tasks;

namespace DataProcessingLibrary
{
    public class DataLoader
    {
        private string dataSourceType;
        private string connectionString;
        private Dictionary<string, Type> schemaDefinition = new();

        public DataLoader(string type, string connString)
        {
            this.dataSourceType = type;
            this.connectionString = connString;
        }

        public List<Dictionary<string, object>> LoadDataFromSource()
        {
            switch (dataSourceType.ToLower())
            {
                case "csv":
                    return LoadCsvData();
                case "json":
                    return LoadJsonData();
                case "sql":
                    return LoadSqlData();
                default:
                    throw new ArgumentException("Unsupported data source type.");
            }
        }

        private List<Dictionary<string, object>> LoadCsvData()
        {
            var data = new List<Dictionary<string, object>>();
            using (var reader = new StreamReader(File.OpenRead(connectionString)))
            using (var csv = new CsvReader(reader, System.Globalization.CultureInfo.InvariantCulture))
            {
                csv.Read();
                csv.ReadHeader();

                while (csv.Read())
                {
                    var row = csv.GetRecord<dynamic>();
                    data.Add(row.ToDictionary());
                }
            }

            return data;
        }

        private List<Dictionary<string, object>> LoadJsonData()
        {
            var jsonData = File.ReadAllText(connectionString);
            return JsonConvert.DeserializeObject<List<Dictionary<string, object>>>(jsonData);
        }

        private List<Dictionary<string, object>> LoadSqlData()
        {
            var data = new List<Dictionary<string, object>>();
            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();
                using (var command = new SqlCommand("SELECT * FROM YourTable", connection))
                using (var reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        var row = new Dictionary<string, object>();
                        for (int i = 0; i < reader.FieldCount; i++)
                        {
                            row[reader.GetName(i)] = reader.GetValue(i);
                        }
                        data.Add(row);
                    }
                }
            }

            return data;
        }

        public List<Dictionary<string, object>> PreprocessData(List<Dictionary<string, object>> rawData)
        {
            Parallel.ForEach(rawData, row =>
            {
                foreach (var key in schemaDefinition.Keys.ToList())
                {
                    if (!row.ContainsKey(key))
                    {
                        row[key] = null; // Handle missing values
                    }
                    else if (schemaDefinition[key] == typeof(int) || schemaDefinition[key] == typeof(double))
                    {
                        var value = Convert.ToDouble(row[key]);
                        row[key] = NormalizeValue(value, key);
                    }
                }
            });

            return rawData;
        }

        private double NormalizeValue(double value, string columnName)
        {
            // Example normalization: Min-Max scaling assuming min=0 and max=1 for simplicity
            double minValue = 0; 
            double maxValue = 100; 

            if (value < minValue) value = minValue;
            if (value > maxValue) value = maxValue;

            return (value - minValue) / (maxValue - minValue);
        }

        public void ValidateSchema(List<Dictionary<string, object>> data)
        {
            foreach (var row in data)
            {
                foreach (var column in schemaDefinition.Keys.ToList())
                {
                    if (!row.ContainsKey(column))
                        throw new ArgumentException($"Missing expected column: {column}.");

                    var expectedType = schemaDefinition[column];
                    var actualValue = row[column];

                    if (actualValue != null && !expectedType.IsInstanceOfType(actualValue))
                        throw new ArgumentException($"Column '{column}' has incorrect type. Expected: {expectedType}, Found: {actualValue.GetType()}");
                }
            }
        }

        public List<Dictionary<string, object>> GetSampleData(int sampleSize)
        {
            var data = LoadDataFromSource();
            return data.OrderBy(x => Guid.NewGuid()).Take(sampleSize).ToList();
        }

        public void SavePreprocessedData(List<Dictionary<string, object>> preprocessedData, string filePath)
        {
            using (var writer = new StreamWriter(File.OpenWrite(filePath)))
            using (var csv = new CsvWriter(writer, System.Globalization.CultureInfo.InvariantCulture))
            {
                csv.WriteRecords(preprocessedData);
            }
        }

        public override string ToString()
        {
            return $"DataSourceType: {dataSourceType}, ConnectionString: {connectionString}, SchemaDefinition: {string.Join(", ", schemaDefinition.Select(kvp => $"{kvp.Key}: {kvp.Value}"))}";
        }
    }
}
