// JavaScript Function to Render Secure Footer

const scriptCache = new Map();

async function fetchScripts(endpoint) {
  try {
    const response = await fetch(endpoint);
    if (!response.ok) throw new Error(`Network error: ${response.statusText}`);
    return await response.json();
  } catch (error) {
    console.error("Error fetching scripts:", error);
    // Implement retry logic here, if needed
    throw error;
  }
}

function getCacheKey(script) {
  return `${script.src || script.code}-${(script.version || Date.now()).toString()}`;
}

async function loadAndRenderScripts(scripts, endpoint = '/api/scripts') {
  let allScriptsData = [...scripts];
  try {
    const fetchedScripts = await fetchScripts(endpoint);
    allScriptsData = allScriptsData.concat(fetchedScripts);

    for (const script of allScriptsData) {
      if (!script.code && !script.src) continue;

      const key = getCacheKey(script);
      if (scriptCache.has(key)) continue;

      scriptCache.set(key, { code: script.code || '', src: script.src });

      renderScriptElement(script);
    }
  } catch (error) {
    console.error("Error during script loading:", error);
  }
}

function renderScriptElement({ code = '', type = 'text/javascript', src = '' }) {
  const key = getCacheKey({ code, type, src });
  const scriptTag = document.createElement('script');

  scriptTag.type = type;
  scriptTag.async = true;

  if (src) {
    scriptTag.src = src;
  } else {
    scriptTag.innerHTML = code;
  }

  scriptTag.setAttribute('key', key);
  document.body.appendChild(scriptTag);

  console.log(`Rendered script: ${key}`);
}

function cleanupOldScripts() {
  Array.from(document.querySelectorAll('script[key]')).forEach((element) => {
    if (!scriptCache.has(element.getAttribute('key'))) {
      element.remove();
    }
  });
}

// Calling loadAndRenderScripts with a sample array of scripts
loadAndRenderScripts([
  { code: "console.log('Inline script example');" },
  // Add more script objects here as needed
]);

