<?php

function generateSecureRandomString($length, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
    if ($length <= 0 || empty($charset)) {
        throw new InvalidArgumentException("Invalid parameters for generating random string.");
    }

    $randomString = '';
    $maxIndex = mb_strlen($charset) - 1;

    for ($i = 0; $i < $length; ++$i) {
        $randomString .= $charset[random_int(0, $maxIndex)];
    }

    return $randomString;
}

function hashPasswordWithAlgorithm($password, $algorithm = PASSWORD_BCRYPT, $options = []) {
    if (!defined($algorithm)) {
        throw new InvalidArgumentException("Unsupported hash algorithm: $algorithm");
    }

    return password_hash($password, $algorithm, $options);
}

function manageSessionTokens() {
    session_start();
    if (!isset($_SESSION['tokens'])) {
        $_SESSION['tokens'] = [];
    }

    return $_SESSION['tokens'];
}

// Usage example
try {
    $randomString = generateSecureRandomString(32);
    $hashedPassword = hashPasswordWithAlgorithm('examplePassword');

    $sessionTokens = manageSessionTokens();
    $sessionTokens[] = ['token' => $randomString, 'hashed_password' => $hashedPassword];

    $_SESSION['tokens'] = $sessionTokens;
} catch (Exception $e) {
    error_log($e->getMessage());
}

