Below is a Java program that processes an image directory to generate metadata reports, using command-line arguments to specify input and output paths. This implementation uses `java.nio.file` for directory traversal, handles concurrency, and integrates with a C++ function via JNI for resizing images.

```java
import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import javax.imageio.ImageIO;

public class ImageProcessor {

    private static final List<String> EXCLUDED_FORMATS = Arrays.asList(".svg", ".psd");
    private static ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public static void main(String[] args) {
        if (args.length < 1 || args.length > 2) {
            System.out.println("Usage: java ImageProcessor <directory> [output file]");
            return;
        }

        Path directoryPath = Paths.get(args[0]);
        String outputFilePath = args.length == 2 ? args[1] : null;

        if (!Files.isDirectory(directoryPath)) {
            System.err.println("Invalid directory path.");
            return;
        }

        processImages(directoryPath, outputFilePath);
    }

    private static void processImages(Path directoryPath, String outputFilePath) {
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(directoryPath)) {
            List<Future<ImageMetadata>> futures = new ArrayList<>();

            for (Path entry : stream) {
                if (Files.isRegularFile(entry) && !EXCLUDED_FORMATS.contains(getExtension(entry).toLowerCase())) {
                    futures.add(executorService.submit(() -> processImage(entry)));
                }
            }

            StringBuilder reportBuilder = new StringBuilder();
            for (Future<ImageMetadata> future : futures) {
                try {
                    ImageMetadata metadata = future.get();
                    if (outputFilePath != null) {
                        appendToFile(outputFilePath, metadata.toString());
                    } else {
                        System.out.println(metadata);
                    }
                    reportBuilder.append(metadata).append("\n");
                } catch (InterruptedException | ExecutionException e) {
                    System.err.println("Error processing image: " + e.getMessage());
                }
            }

            if (outputFilePath != null) {
                Files.write(Paths.get(outputFilePath), reportBuilder.toString().getBytes());
            }
        } catch (IOException e) {
            System.err.println("Error accessing directory: " + e.getMessage());
        }
    }

    private static ImageMetadata processImage(Path imagePath) {
        try {
            // Assuming nativeResize is a JNI method to invoke the C++ resizing function
            long startTime = System.nanoTime();
            nativeResize(imagePath.toString(), 800, 600); // Example resolution
            long endTime = System.nanoTime();

            return new ImageMetadata(
                imagePath.getFileName().toString(),
                (endTime - startTime) / 1_000_000,
                "Resized successfully"
            );
        } catch (Exception e) {
            return new ImageMetadata(imagePath.getFileName().toString(), 0, "Error: " + e.getMessage());
        }
    }

    private static String getExtension(Path path) {
        return path.toString().substring(path.toString().lastIndexOf('.') + 1);
    }

    private static void appendToFile(String filePath, String content) throws IOException {
        Path file = Paths.get(filePath);
        Files.write(file, (content + "\n").getBytes(), StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }

    // Placeholder for JNI native method declaration
    private static native void nativeResize(String imagePath, int width, int height);

    private static class ImageMetadata {
        private final String fileName;
        private final long resizeTimeMs;
        private final String status;

        public ImageMetadata(String fileName, long resizeTimeMs, String status) {
            this.fileName = fileName;
            this.resizeTimeMs = resizeTimeMs;
            this.status = status;
        }

        @Override
        public String toString() {
            return "Image: " + fileName + ", Resize Time (ms): " + resizeTimeMs + ", Status: " + status;
        }
    }
}
```

### C++ Function (JNI)

```cpp
#include <jni.h>
#include <opencv2/opencv.hpp>
#include <chrono>
#include <iostream>

extern "C"
JNIEXPORT void JNICALL
Java_ImageProcessor_nativeResize(JNIEnv* env, jobject obj, jstring imagePath, jint width, jint height) {
    const char *nativeImagePath = env->GetStringUTFChars(imagePath, 0);

    cv::Mat image = cv::imread(nativeImagePath);
    if (image.empty()) {
        throw std::runtime_error("Image not found or corrupted");
    }

    auto start = std::chrono::high_resolution_clock::now();
    int newWidth = width;
    int newHeight = height;

    double aspectRatio = static_cast<double>(image.cols) / image.rows;
    if (aspectRatio > 1.0) {
        newHeight = static_cast<int>(width / aspectRatio);
    } else {
        newWidth = static_cast<int>(height * aspectRatio);
    }

    cv::Mat resizedImage;
    cv::resize(image, resizedImage, cv::Size(newWidth, newHeight));

    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed = end - start;

    // Simulate progress callback
    std::cout << "Resized image: " << nativeImagePath << " to (" 
              << resizedImage.cols << ", " << resizedImage.rows << ") in "
              << elapsed.count() * 1000 << " ms" << std::endl;

    env->ReleaseStringUTFChars(imagePath, nativeImagePath);

    // Example of logging (thread-safe implementation needed for real-world scenarios)
    std::ofstream logFile("resize.log", std::ios_base::app);
    if (logFile.is_open()) {
        logFile << "Resized image: " << nativeImagePath << " to (" 
                << resizedImage.cols << ", " << resizedImage.rows << ") in "
                << elapsed.count() * 1000 << " ms" << std::endl;
        logFile.close();
    }
}
```

