### C++ Octree Implementation

```cpp
#include <iostream>
#include <mutex>
#include <openssl/evp.h>
#include <memory>

constexpr size_t MAX_NODES = 10000000;

struct OctreeNode {
    // Node data (e.g., spatial information)
    int id;
    std::unique_ptr<OctreeNode> children[8];

    OctreeNode(int node_id) : id(node_id) {}
};

class ThreadSafeOctree {
public:
    ThreadSafeOctree() : root(nullptr), node_count(0) {}

    ~ThreadSafeOctree() {
        deleteNode(root);
    }

    void initialize() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!root) {
            root = new OctreeNode(0);  // Root node
            node_count = 1;
        }
    }

private:
    OctreeNode* root;
    size_t node_count;
    mutable std::mutex mutex_;

    void deleteNode(OctreeNode* node) {
        if (node) {
            for (auto& child : node->children) {
                deleteNode(child.get());
            }
            delete node;
        }
    }

public:
    // Example function to demonstrate thread-safe insertion
    bool insert(int id) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (node_count >= MAX_NODES) return false;

        // Implement your spatial logic here...
        root->children[0] = std::make_unique<OctreeNode>(id);
        ++node_count;
        return true;
    }
};

int main() {
    ThreadSafeOctree octree;
    octree.initialize();

    // Example usage
    if (octree.insert(1)) {
        std::cout << "Node inserted successfully." << std::endl;
    }

    return 0;
}
