```python
import os
import gzip
import bz2
import json
import csv
from flask import Flask, request, jsonify
from flask_oauthlib.provider import OAuth2Provider
from collections import defaultdict
from threading import Thread

app = Flask(__name__)
oauth = OAuth2Provider(app)

# Example OAuth setup (configure according to your needs)
@app.route('/token', methods=['POST'])
def access_token():
    # Implement token generation logic here...
    return jsonify(token="example-token")

@app.route('/stats', methods=['GET'])
def stats():
    directory = request.args.get('directory')
    exclusions = request.args.getlist('exclude_pattern')

    file_stats = process_directory(directory, exclusions)

    return jsonify(file_stats)

def decompress_file(filepath):
    if filepath.endswith('.gz'):
        with gzip.open(filepath, 'rt') as f:
            return f.read()
    elif filepath.endswith('.bz2'):
        with bz2.open(filepath, 'rt') as f:
            return f.read()
    else:
        raise ValueError("Unsupported compression format")

def process_csv_data(data):
    reader = csv.DictReader(data.splitlines())
    summary = defaultdict(int)

    for row in reader:
        # Process CSV data here...
        pass

    return summary

def extract_csv_stats(filepath):
    with open(filepath, 'r') as file:
        data = file.read()

    return process_csv_data(data)

def process_directory(directory, exclusions):
    stats = {
        'text': defaultdict(int),
        'log': defaultdict(int),
        'csv': defaultdict(int),
        'json': defaultdict(int)
    }

    for root, _, files in os.walk(directory):
        for file in files:
            if any(excl in file for excl in exclusions):
                continue

            filepath = os.path.join(root, file)

            try:
                with open(filepath, 'rb') as f:
                    content = f.read()

                if filepath.endswith(('.gz', '.bz2')):
                    content = decompress_file(filepath).encode('utf-8')

                if filepath.endswith('.csv'):
                    stats['csv'] = extract_csv_stats(content.decode('utf-8'))

                elif filepath.endswith('.json'):
                    data = json.loads(content)
                    # Process JSON data here...

                else:
                    text_content = content.decode('utf-8')
                    line_count = len(text_content.splitlines())
                    word_count = len(text_content.split())
                    char_count = len(text_content)

                    if '.txt' in file:
                        stats['text']['lines'] += line_count
                        stats['text']['words'] += word_count
                        stats['text']['chars'] += char_count

                    elif '.log' in file:
                        stats['log']['lines'] += line_count
                        stats['log']['words'] += word_count
                        stats['log']['chars'] += char_count

            except Exception as e:
                print(f"Error processing {file}: {e}")

    return stats

if __name__ == '__main__':
    app.run(debug=True)
