```java
import java.io.IOException;
import java.nio.file.Files;
import java.util.concurrent.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.multipart.MultipartFile;

public class FileUploadProcessor {

    private static final Logger logger = LoggerFactory.getLogger(FileUploadProcessor.class);

    public void processFileUploads(Queue<MultipartFile> uploadQueue, int maxConcurrency, 
                                   StorageHandlerFactory storageHandlerFactory) {
        ExecutorService executorService = Executors.newFixedThreadPool(maxConcurrency);

        try (CompletionService<Void> completionService = new ExecutorCompletionService<>(executorService)) {

            while (!uploadQueue.isEmpty()) {
                MultipartFile file = uploadQueue.poll();

                if (file != null) {
                    final long startTime = System.currentTimeMillis();

                    // Submit the upload task to the executor service
                    Future<Void> future = completionService.submit(() -> {
                        try {
                            logger.info("Starting upload for file: {}", file.getOriginalFilename());

                            StorageHandler storageHandler = storageHandlerFactory.createStorageHandler();

                            try (var inputStream = file.getInputStream()) {
                                long fileSize = Files.size(file.getResource().getFile());

                                // Perform the actual file upload
                                storageHandler.upload(inputStream, file.getOriginalFilename(), fileSize);

                                logger.info("Completed upload for file: {}, Size: {} bytes, Duration: {} ms",
                                            file.getOriginalFilename(),
                                            fileSize,
                                            System.currentTimeMillis() - startTime);
                            } catch (IOException e) {
                                logger.error("Failed to process input stream for file: {}", file.getOriginalFilename(), e);
                                throw new RuntimeException("Error processing file input stream", e);
                            }
                        } catch (Exception e) {
                            logger.error("Upload failed for file: {}, Error: {}", file.getOriginalFilename(), e.getMessage());
                            handleUploadFailure(file, e);
                        }

                        return null;
                    });

                    // Handle completion and potential retry logic
                    try {
                        future.get();  // Wait for the task to complete or fail
                    } catch (ExecutionException | InterruptedException e) {
                        logger.error("Error during upload handling for file: {}", file.getOriginalFilename(), e);
                        handleUploadFailure(file, e);
                    }
                }
            }

        } catch (IOException e) {
            logger.error("Error accessing file resource", e);
        } finally {
            executorService.shutdown();
            try {
                if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                    executorService.shutdownNow();
                }
            } catch (InterruptedException ie) {
                executorService.shutdownNow();
            }
        }
    }

    private void handleUploadFailure(MultipartFile file, Exception e) {
        // Implement retry logic or error response handling as needed
        logger.error("Retrying upload for file: {}", file.getOriginalFilename());
        // Example placeholder for retry mechanism (not implemented here)
    }
}

// Placeholder interface for storage handler creation
interface StorageHandlerFactory {
    StorageHandler createStorageHandler();
}

// Placeholder interface for storage operations
interface StorageHandler {
    void upload(InputStream inputStream, String filename, long fileSize) throws IOException;
}
```

This solution uses a fixed thread pool to manage concurrency and process each file upload in an asynchronous manner. It handles logging for both successful uploads and errors while providing a structure that supports future enhancements such as retry mechanisms or integration with additional storage systems. The use of `CompletionService` ensures efficient task management, allowing the main processing loop to handle tasks as they complete.

