// Function to fetch attack data from the database
std::string fetchAttackData(const std::string& attack_name) {
    // Check Redis cache first
    {
        std::lock_guard<std::mutex> lock(cache_mutex);
        auto cached_data = redis.get(attack_name);
        if (!cached_data.empty()) {
            return cached_data;
        }
    }

    // If not in cache, fetch from HTTP endpoint
    try {
        http_client client;
        std::string response = client.get("http://api.example.com/attacks/" + attack_name);

        // Store in Redis for future use
        redis.set(attack_name, response);

        return response;
    } catch (const std::exception& e) {
        logger.log_error("Failed to fetch attack data: " + std::string(e.what()));
        throw; // Rethrow after logging
    }
}

// Function to handle WebSocket updates
void onWebSocketUpdate(const std::string& message) {
    try {
        auto update_data = parseWebSocketMessage(message); // Parse the incoming message

        // Update Redis cache with new data
        {
            std::lock_guard<std::mutex> lock(cache_mutex);
            for (const auto& attack : update_data.attacks) {
                redis.set(attack.name, attack.data);
            }
        }

    } catch (const std::exception& e) {
        logger.log_error("WebSocket update error: " + std::string(e.what()));
    }
}

// Function to select the optimal attack
std::string selectOptimalAttack(const std::string& user_input, const std::string& character_type) {
    try {
        std::smatch matches;
        if (!std::regex_search(user_input, matches, std::regex(ATTACK_REGEX))) {
            throw std::invalid_argument("No valid attack found in input.");
        }

        std::string requested_attack = matches[1];

        // Fetch attack data (either from cache or API)
        auto attack_data_future = std::async(std::launch::async, fetchAttackData, requested_attack);

        // Simulate cooldown logic based on character type
        int cooldown_period = calculateCooldown(character_type);

        // Wait for the async call to complete with a timeout for network latency management
        if (attack_data_future.wait_for(std::chrono::milliseconds(500)) == std::future_status::ready) {
            return attack_data_future.get();
        } else {
            throw std::runtime_error("Timeout occurred while fetching attack data.");
        }
    } catch (const std::exception& e) {
        logger.log_error("Error in selecting optimal attack: " + std::string(e.what()));
        return {}; // Return empty string or handle the error appropriately
    }
}

int main() {
    websocket_client ws("ws://api.example.com/updates");
    ws.on_message(onWebSocketUpdate);

    std::vector<std::thread> threads;
    for (int i = 0; i < MAX_CONCURRENT_CHARACTERS; ++i) {
