# app.py

from flask import Flask, request, jsonify, render_template_string
import requests
import redis
import logging
import time
from functools import wraps
from threading import Lock
from datetime import datetime, timedelta

app = Flask(__name__)

# Configuration
API_KEY = 'your_openweathermap_api_key'
BASE_URL = "http://api.openweathermap.org/data/2.5/weather"
CACHE_EXPIRATION_SECONDS = 600  # 10 minutes
RATE_LIMIT = 60  # Max requests per minute
REDIS_HOST = 'localhost'
REDIS_PORT = 6379

# Setup Redis
cache = redis.StrictRedis(host=REDIS_HOST, port=REDIS_PORT, decode_responses=True)
lock = Lock()

# Logging configuration
logging.basicConfig(filename='api_calls.log', level=logging.INFO)

# Rate limiter
request_times = []

def rate_limiter(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        with lock:
            current_time = time.time()
            request_times[:] = [t for t in request_times if current_time - t < 60]
            if len(request_times) >= RATE_LIMIT:
                raise Exception("Rate limit exceeded. Try again later.")
            request_times.append(current_time)
        return func(*args, **kwargs)
    return wrapper

def log_api_call(endpoint, params):
    logging.info(f"API Call: {endpoint} | Params: {params} | Timestamp: {datetime.now()}")

@rate_limiter
@app.route('/weather', methods=['GET'])
def get_weather():
    location = request.args.get('location')
    if not location:
        return jsonify({"error": "Location parameter is required."}), 400

    cache_key = f"weather:{location}"
    cached_data = cache.get(cache_key)

    if cached_data:
        return jsonify(eval(cached_data))  # Use eval carefully, consider JSON parsing instead for production

    try:
        response = requests.get(BASE_URL, params={'q': location, 'appid': API_KEY})
        log_api_call(BASE_URL, {'q': location})

        if response.status_code != 200:
            return jsonify({"error": "Unable to fetch weather data."}), response.status_code

        data = response.json()
        cache.setex(cache_key, CACHE_EXPIRATION_SECONDS, str(data))

    except requests.exceptions.RequestException as e:
        logging.error(f"Network error: {e}")
        return jsonify({"error": "Network issue or invalid location input."}), 500

    return jsonify(data)

@app.route('/')
def index():
    html = '''
    <html>
        <body>
            <h1>Weather App</h1>
            <form action="/weather" method="get">
                Location: <input type="text" name="location"><br><br>
                <input type="submit" value="Get Weather">
            </form>
        </body>
    </html>
    '''
    return render_template_string(html)

if __name__ == '__main__':
    app.run(debug=True)
```

