// Cache functions
static Cache* find_in_cache(const char *criteria) {
    Cache *cache = /* access global or static cache list */;
    while (cache != NULL) {
        if (strcmp(cache->criteria, criteria) == 0) {
            return cache;
        }
        cache = cache->next;
    }
    return NULL;
}

static void add_to_cache(Cache **cache_list, const char *criteria, StateList *state_list) {
    Cache *new_cache = malloc(sizeof(Cache));
    new_cache->criteria = strdup(criteria);
    new_cache->state_list = state_list;
    new_cache->next = *cache_list;
    *cache_list = new_cache;
}

