from pathlib import Path

class DirectoryManager:
    def __init__(self, max_retries=5, retry_delay=1):
        self.max_retries = max_retries
        self.retry_delay = retry_delay
        self.executor = ThreadPoolExecutor(max_workers=10)

    async def create_directory(self, path: str, parent_dir: str = None) -> Path:
        base_path = Path(parent_dir or ".")
        target_path = base_path / path

        for attempt in range(self.max_retries):
            try:
                if not target_path.exists():
                    os.makedirs(target_path)
                return target_path
            except (OSError, IOError) as e:
                logging.error(f"Attempt {attempt + 1}: Failed to create directory {target_path} due to {e}")
                await asyncio.sleep(self.retry_delay)

        raise Exception(f"Failed to create directory {target_path} after {self.max_retries} attempts")

    async def cleanup_temp_directories(self, age_threshold: int = 3600):
        now = time.time()
        for temp_dir in Path(tempfile.gettempdir()).iterdir():
            if (now - os.path.getmtime(temp_dir)) > age_threshold:
                try:
                    shutil.rmtree(temp_dir)
                except Exception as e:
                    logging.error(f"Failed to remove temporary directory {temp_dir}: {e}")

    def list_cached_directories(self) -> List[str]:
