public class ServiceClusterManager {

    private final Map<String, ServiceInstance> instances = new ConcurrentHashMap<>();
    private final String monitoringUrl;
    private final int heartbeatInterval; // in milliseconds
    private Timer timer;

    public ServiceClusterManager(String monitoringUrl, int heartbeatInterval) {
        this.monitoringUrl = monitoringUrl;
        this.heartbeatInterval = heartbeatInterval;
        this.timer = new Timer(true);
    }

    public void addServiceInstance(String instanceId, String configUrl) {
        // Fetch configuration from external API
        ServiceConfig config = fetchConfigFromApi(configUrl);

        ServiceInstance service = new ServiceInstance(instanceId, config);
        instances.put(instanceId, service);

        startHeartbeat(service);
        loadBalance();
    }

    public void removeServiceInstance(String instanceId) {
        ServiceInstance instance = instances.remove(instanceId);
        if (instance != null) {
            stopHeartbeat(instance);
            redistributeLoad();
        }
    }

    private void startHeartbeat(ServiceInstance service) {
        TimerTask task = new TimerTask() {
            @Override
            public void run() {
                boolean isHealthy = sendHeartbeat(service);
                if (!isHealthy) {
                    triggerFailover(service);
                }
            }
        };
        timer.scheduleAtFixedRate(task, 0, heartbeatInterval);
    }

    private void stopHeartbeat(ServiceInstance service) {
        // Implementation to cancel the specific TimerTask for this instance
    }

    private boolean sendHeartbeat(ServiceInstance service) {
        try (Socket socket = new Socket("monitoring.server", 12345)) {
            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
            out.println(service.getInstanceId() + " heartbeat");
            return true;
        } catch (IOException e) {
            logError(e, service.getInstanceId());
            return false;
        }
    }

    private void triggerFailover(ServiceInstance service) {
        // Reassign responsibilities
        redistributeLoad();
    }

