            switch (command.toLowerCase()) {
                case "add":
                    System.out.println("Enter instance ID and config URL:");
                    String instanceId = scanner.nextLine();
                    String configUrl = scanner.nextLine();
                    manager.addServiceInstance(instanceId, configUrl);
                    break;
