function log(message, level = 'info') {
    console.log(`[${level.toUpperCase()}] ${message}`);
}

// Module loader and dependency resolver
async function loadModules(directory) {
    const files = await readdirAsync(directory);
    let modules = {};

    for (const file of files) {
        try {
            if (!file.endsWith('.js')) continue;

            const modulePath = path.join(directory, file);
            const moduleExports = require(modulePath);

            // Assume each module exports its dependencies
            const { name, version, dependsOn } = moduleExports;

            modules[name] = { 
                version,
                module: moduleExports,
                loaded: false,
                error: null
            };
        } catch (error) {
            log(`Error loading module ${file}: ${error.message}`, 'error');
        }
    }

    return resolveDependencies(modules);
}

function resolveDependencies(modules) {
    const resolved = {};

    function resolve(name) {
        if (resolved[name]) return;

        const moduleInfo = modules[name];
        if (!moduleInfo) {
            log(`Module ${name} is missing`, 'warn');
            return;
        }

        try {
            for (const dependency of moduleInfo.module.dependsOn || []) {
                resolve(dependency);
            }

            // Assume a `load` method exists on each module
            if (typeof moduleInfo.module.load === 'function') {
                moduleInfo.loaded = true;
                log(`Successfully loaded module ${name}`);
                resolved[name] = moduleInfo;
            } else {
                throw new Error('Module does not implement load function');
            }
        } catch (error) {
            moduleInfo.error = error.message;
            log(`Error resolving module ${name}: ${error.message}`, 'error');
        }
    }

    for (const name in modules) {
        resolve(name);
    }

    return resolved;
}

// Express app to expose API
const app = express();
app.use(express.json());

let cachedModules = {};

async function reloadModules() {
    const directory = './modules'; // Specify your module directory

    log('Reloading modules');
    try {
        const newCache = await loadModules(directory);

        if (JSON.stringify(newCache) !== JSON.stringify(cachedModules)) {
            cachedModules = newCache;
            log('Modules reloaded successfully');
        }
    } catch (error) {
        log(`Error during module reload: ${error.message}`, 'error');
    }
}

app.get('/modules', (req, res) => {
    res.json(cachedModules);
});

app.post('/reload-modules', async (req, res) => {
    await reloadModules();
    res.send('Modules reloaded');
});

// Directory watcher setup
const watcher = chokidar.watch('./modules', { persistent: true });
watcher.on('change', path => {
    log(`File changed: ${path}`);
    reloadModules();
});

// Start the server and load modules initially
(async () => {
    await reloadModules();
    app.listen(3000, () => log('Server is running on port 3000'));
})();
```

