        channel.close();
        assertFalse(manager.connectionPool.containsKey(channel), "Closed connections should not be in the pool");
    }

    @Test
    void testHealthCheck() throws IOException {
        SocketChannel channel = manager.acquireConnection();

        manager.releaseConnection(channel);

        manager.performHealthCheck();

        // Simulate a disconnected socket for health check validation

