import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime, timedelta
import time
import pytz
import logging

# Set up logging
logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO)

class WeatherDataFetcher:
    def __init__(self, primary_api_key, secondary_api_key, cache_duration=3600):
        self.primary_url = "https://api.openweathermap.org/data/2.5/weather"
        self.secondary_url = "https://alternative.weather.api/endpoint"  # Placeholder
        self.primary_api_key = primary_api_key
        self.secondary_api_key = secondary_api_key
        self.cache_duration = cache_duration
        self.cache = {}
        self.rate_limit_reset_time = time.time() + 60

    def fetch(self, city, api_url, api_key):
        if time.time() < self.rate_limit_reset_time:
            logger.info(f"Rate limit in place. Sleeping until {self.rate_limit_reset_time}")
            time.sleep(self.rate_limit_reset_time - time.time())

        response = None
        try:
            params = {'q': city, 'appid': api_key}
            response = requests.get(api_url, params=params)

            if response.status_code == 429:  # Rate limit reached
                logger.warning(f"Rate limited for city {city}. Retrying with backoff.")
                self.rate_limit_reset_time = time.time() + int(response.headers.get("Retry-After", 60))
                return None

            response.raise_for_status()

            data = response.json()
            if 'weather' in data:
                self.cache[city] = (datetime.now(), data)
            else:
                logger.error(f"Failed to fetch valid weather data for {city}.")

        except requests.exceptions.RequestException as e:
            logger.error(f"Error fetching weather data for {city}: {e}")

        return response.json() if response and 'weather' in response.json() else None

    def fetch_weather_data(self, cities, preferred_timezone='UTC'):
        results = {}

        with ThreadPoolExecutor(max_workers=5) as executor:
            futures = {
                executor.submit(self._get_weather_data, city, preferred_timezone): city for city in cities
            }

            for future in as_completed(futures):
                city = futures[future]
                try:
                    data = future.result()
                    if data:
                        results[city] = data
                except Exception as e:
                    logger.error(f"Exception occurred while fetching weather data for {city}: {e}")

        return results

    def _get_weather_data(self, city, preferred_timezone):
        now = datetime.now()

        # Check cache first
        if city in self.cache and (now - self.cache[city][0]).total_seconds() < self.cache_duration:
            logger.info(f"Using cached data for {city}")
            return self._format_weather_data(self.cache[city][1], preferred_timezone)

        # Fetch from primary API
        weather_data = self.fetch(city, self.primary_url, self.primary_api_key)

        if not weather_data:
            logger.warning(f"Falling back to secondary API for {city}")
            # Fall back to secondary API
            weather_data = self.fetch(city, self.secondary_url, self.secondary_api_key)

        if weather_data:
            return self._format_weather_data(weather_data, preferred_timezone)

        raise RuntimeError(f"Failed to retrieve weather data for {city}")

    def _format_weather_data(self, weather_data, preferred_timezone):
        local_tz = pytz.timezone(preferred_timezone)
        converted_time = datetime.fromtimestamp(
            weather_data['dt'], tz=pytz.utc).astimezone(local_tz)

        weather_data['formatted_date'] = converted_time.strftime('%Y-%m-%d %H:%M:%S')

        return weather_data

def fetchWeatherData(cities, primary_api_key, secondary_api_key, cache_duration=3600, preferred_timezone='UTC'):
    if not isinstance(cities, list) or not all(isinstance(city, str) for city in cities):
        raise ValueError("Cities must be a list of strings")

    fetcher = WeatherDataFetcher(primary_api_key, secondary_api_key, cache_duration)
    return fetcher.fetch_weather_data(cities, preferred_timezone)

# Example Usage
if __name__ == "__main__":
    cities = ["New York", "London", "Tokyo"]
    primary_api_key = 'your_primary_openweathermap_api_key'
    secondary_api_key = 'your_secondary_api_key'

    try:
        weather_data = fetchWeatherData(cities, primary_api_key, secondary_api_key)
        for city, data in weather_data.items():
            print(f"Weather for {city}: {data}")
    except Exception as e:
        logger.error(f"Error fetching weather data: {e}")
