using System;
using System.Collections.Generic;
using System.Linq;
import System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;
using Newtonsoft.Json;

public class UserProfileFetcher
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly string _apiBaseUrl = "https://external-api.com/users/";
    private const int MaxRetryAttempts = 3;

    public UserProfileFetcher(HttpClient httpClient, IDistributedCache cache)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
    }

    public async Task FetchUserProfilesAsync(List<string> userIds, string apiCredentials, TimeSpan? cacheExpirationTime = null)
    {
        if (userIds == null || !userIds.All(IsValidUserId))
            throw new ArgumentException("Invalid user IDs provided.");

        var tasks = userIds.Select(userId => ProcessUserProfileAsync(userId, apiCredentials, cacheExpirationTime)).ToList();
        await Task.WhenAll(tasks);
    }

    private async Task ProcessUserProfileAsync(string userId, string apiCredentials, TimeSpan? cacheExpirationTime)
    {
        int attempts = 0;
        while (attempts < MaxRetryAttempts)
        {
            try
            {
                var cacheKey = $"userProfile:{userId}";
                var cachedData = await _cache.GetStringAsync(cacheKey);

                if (!string.IsNullOrEmpty(cachedData))
                    return;

                var response = await _httpClient.GetAsync($"{_apiBaseUrl}{userId}?auth={apiCredentials}");
                response.EnsureSuccessStatusCode();

                var profile = JsonConvert.DeserializeObject<UserProfile>(await response.Content.ReadAsStringAsync());
                await CacheUserProfileAsync(profile, cacheKey, cacheExpirationTime);

                PerformIntegrityCheck(userId);
                return;
            }
            catch (Exception ex)
            {
                attempts++;
                LogFailure(userId, ex.Message);

                if (attempts >= MaxRetryAttempts) 
                    MarkAsFailure(userId);

                await Task.Delay(1000 * attempts); // Exponential back-off
            }
        }
    }

    private async Task CacheUserProfileAsync(UserProfile profile, string cacheKey, TimeSpan? expiration)
    {
        var options = new DistributedCacheEntryOptions()
            .SetSlidingExpiration(expiration ?? TimeSpan.FromMinutes(5));

        await _cache.SetStringAsync(cacheKey, JsonConvert.SerializeObject(profile), options);
    }

    private bool IsValidUserId(string userId) => Regex.IsMatch(userId, @"^\d{6}$");

    private void PerformIntegrityCheck(string userId)
    {
        var logFilePath = GetLogFilePathForUser(userId);
        var hash = CalculateSha256Hash(File.ReadAllBytes(logFilePath));

        if (ShouldExcludeFile(logFilePath))
            return;

        LogSuccess(hash);
        EncryptAndReportHashResult(hash, userId);
    }

    private string GetLogFilePathForUser(string userId) => $"/logs/{userId}.log";

    private bool ShouldExcludeFile(string filePath)
    {
        var excludePatterns = new[] { "*.tmp", ".*" };
        return excludePatterns.Any(pattern => Regex.IsMatch(filePath, pattern));
    }

    private void LogSuccess(string hash) 
    {
        Console.WriteLine($"Integrity check succeeded: {hash}");
    }

    private void MarkAsFailure(string userId)
    {
        Console.WriteLine($"User profile fetch failed for user ID: {userId}");
    }

    private void LogFailure(string userId, string message)
    {
        Console.WriteLine($"Error fetching user profile for {userId}: {message}");
    }

    private string CalculateSha256Hash(byte[] data)
    {
        using (var sha256 = SHA256.Create())
            return Convert.ToBase64String(sha256.ComputeHash(data));
    }

    private void EncryptAndReportHashResult(string hash, string userId)
    {
        // Assume an encryption service is available
        var encryptedHash = "encrypted_" + hash; 
        Console.WriteLine($"Encrypted hash for user {userId}: {encryptedHash}");
    }

    public class UserProfile
    {
        [JsonProperty("id")]
        public string Id { get; set; }

        [JsonProperty("name")]
        public string Name { get; set; }

        // Other properties as needed...
    }
}
