  // Function to update counts for matches found by a regex pattern
  function findMatches(regex) {
    let match;
    while ((match = regex.exec(normalizedText)) !== null) {
      const bookName = match[0].charAt(0).toUpperCase() + match[0].slice(1);

      // Check and update the count for each matched book
      if (languageBooks.includes(bookName)) {
        bookCount[bookName] = (bookCount[bookName] || 0) + 1;
      } else {
        console.warn(`Warning: No translation found for detected book name "${match[0]}"`);
      }
    }
  }

  // Find matches in the text using regex patterns
  findMatches(oldTestamentRegex);
  findMatches(newTestamentRegex);

  // Sort results by frequency of mentions in descending order
  const sortedBooks = Object.entries(bookCount).sort((a, b) => b[1] - a[1]);

  return Object.fromEntries(sortedBooks);
}

