class ModuleLoader {
    constructor() {
        this.modules = new Map();
    }

    async loadModule(filePath) {
        try {
            const modulePath = path.resolve(filePath);
            if (this.modules.has(modulePath)) return this.modules.get(modulePath);

            console.log(`Loading module: ${modulePath}`);
            const isAsync = fs.promises.readFile(modulePath, 'utf8').then(content => content.includes('async'));
            let mod;

            if (isAsync) {
                mod = await import(modulePath);
            } else {
                mod = require(modulePath);
            }

            this.modules.set(modulePath, mod.default || mod);
            console.log(`Module loaded: ${modulePath}`);
        } catch (error) {
            console.error(`Failed to load module at ${filePath}:`, error.message);
        }
    }

    async executeModulesInOrder(filePaths) {
        for (const filePath of filePaths) {
            await this.loadModule(filePath);
        }

        // Example execution, replace with actual usage logic
        const exec = () => {
            for (const [path, module] of this.modules.entries()) {
                if (module.init && typeof module.init === 'function') {
                    console.log(`Executing module at ${path}`);
                    try {
                        module.init();
                    } catch (error) {
                        console.error(`Error executing module at ${path}:`, error.message);
                    }
                }
            }
        };

        exec();
    }
}

