```cpp
#include <iostream>
#include <random>
#include <ctime>
#include <mutex>
#include <string>
#include <vector>
#include <openssl/rand.h>

class SessionManager {
    std::mt19937_64 rng;
    std::mutex lock;
    std::vector<std::string> idCache;

public:
    SessionManager() {
        std::random_device rd;
        std::seed_seq seed{static_cast<unsigned int>(rd()), 
                           static_cast<unsigned int>(time(nullptr)), 
                           // Add more entropy sources if needed
                           std::hash<std::thread::id>()(std::this_thread::get_id())};
        rng.seed(seed);
    }

    std::string generateSessionID() {
        std::lock_guard<std::mutex> guard(lock);

        unsigned char buf[24];
        RAND_bytes(buf, sizeof(buf));

        std::uniform_int_distribution<uint64_t> dist;
        for (int i = 0; i < 3; ++i) {
            rng.discard(dist(rng));
            RAND_add(&rng, nullptr, 8);
        }

        // Base64 encoding
        static const char* base64_chars =
            "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
            "abcdefghijklmnopqrstuvwxyz"
            "0123456789+/";

        std::string sessionID;
        for (int i = 0; i < 22; ++i) {
            int value = buf[i / 3] >> ((2 - (i % 3)) * 8) & 0x3F;
            sessionID += base64_chars[value];
        }

        // Check uniqueness and retry if needed
        return ensureUnique(sessionID);
    }

private:
    std::string ensureUnique(const std::string& id) {
        for (int i = 0; i < 5; ++i) {  // Retry mechanism
            if (std::find(idCache.begin(), idCache.end(), id) == idCache.end()) {
                idCache.push_back(id);
                return id;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }

        throw std::runtime_error("Failed to generate unique session ID after retries.");
    }

public:
    void invalidateOldSessions() {
        // Add logic for periodic invalidation
    }
};

int main() {
    SessionManager manager;

    try {
        std::string sessionId = manager.generateSessionID();
        std::cout << "Generated Session ID: " << sessionId << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error generating session ID: " << e.what() << std::endl;
    }

    return 0;
}
```

