#include <stdio.h>
#include <stdlib.h>

// Define the FSA structure
typedef struct State {
    int id;
    struct State** next_states; // Array of pointers to possible next states
} State;

// Define the transition function type
typedef int* (*TransitionFunction)(State*, int);

// Function to create a new state list based on transition condition
State** createStateList(int* initialStates, int numInitialStates, 
                       State* fsa[], TransitionFunction transFunc, 
                       int lastStateId, int terminationStateId) {
    if (initialStates == NULL || fsa == NULL || transFunc == NULL) return NULL;

    // Find the index of the last state
    State** lastState = NULL;
    for (int i = 0; i < numInitialStates; ++i) {
        for (int j = 0; fsa[j] != NULL; ++j) {
            if (fsa[j]->id == initialStates[i]) {
                // Check if this is the last state in the list
                if (initialStates[i + 1] == -1) { // Assuming -1 indicates end of list
                    lastState = &fsa[j];
                }
            }
        }
    }

    if (!lastState || *lastState == NULL) return NULL;

    // Allocate memory for new state list
    State** newStateList = (State**)malloc(sizeof(State*) * numInitialStates);
    if (!newStateList) return NULL;

    int newListSize = 0;
    for (int i = 0; i < numInitialStates; ++i) {
        int* nextStates = transFunc(fsa[initialStates[i]], terminationStateId);

        if (nextStates != NULL) {
            for (int j = 0; nextStates[j] != -1; ++j) { // Assuming -1 indicates end of list
                int found = 0;
                for (int k = 0; k < newListSize; ++k) {
                    if (newStateList[k]->id == nextStates[j]) {
                        found = 1;
                        break;
                    }
                }
                if (!found) {
                    State* state = fsa[nextStates[j]];
                    if (state != NULL) {
                        newStateList[newListSize++] = state;
                    }
                }
            }
        }

        free(nextStates);
    }

    *lastState = newStateList; // Update the 'next' pointer of the last state

    return newStateList;
}

// Example transition function
int* exampleTransitionFunction(State* currentState, int inputSymbol) {
    if (currentState == NULL) return NULL;

    // Mock transition logic: just return an array with -1 to indicate end
    int* nextStates = (int*)malloc(sizeof(int) * 2);
    if (!nextStates) return NULL;

    nextStates[0] = -1; // Assuming -1 indicates no valid next state
    return nextStates;
}

// Example usage
int main() {
    State states[3];
    states[0].id = 0;
    states[1].id = 1;
    states[2].id = 2;

    State* fsa[] = { &states[0], &states[1], &states[2], NULL };

    int initialStates[] = { 0, 1, -1 }; // -1 indicates end of list
    int lastStateId = 1;
    int terminationStateId = 2;

