using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class FileTransferService
{
    private readonly ITokenService _tokenService;
    private readonly IMessageQueue _messageQueue;
    private readonly ILogger<FileTransferService> _logger;
    private const int DefaultChunkSize = 4 * 1024 * 1024; // 4MB

    public FileTransferService(ITokenService tokenService, IMessageQueue messageQueue, ILogger<FileTransferService> logger)
    {
        _tokenService = tokenService ?? throw new ArgumentNullException(nameof(tokenService));
        _messageQueue = messageQueue ?? throw new ArgumentNullException(nameof(messageQueue));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task UploadFileAsync(string filePath, byte[] encryptionKey, byte[] iv, int chunkSize = DefaultChunkSize, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(filePath))
            throw new ArgumentException("Invalid file path", nameof(filePath));

        if (!File.Exists(filePath))
            throw new FileNotFoundException("File not found", filePath);

        string token;
        try
        {
            token = await _tokenService.GetAuthTokenAsync(cancellationToken);
        }
        catch (TokenException ex)
        {
            _logger.LogError(ex, "Failed to retrieve authentication token.");
            throw new UnauthorizedAccessException("Invalid or expired token.", ex);
        }

        using var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.None, 4096, useAsync: true);

        await UploadFileChunkedAsync(fileStream, encryptionKey, iv, chunkSize, cancellationToken);

        _logger.LogInformation($"File upload completed for {filePath}");
    }

    public async Task UploadFileAsync(byte[] fileData, byte[] encryptionKey, byte[] iv, int chunkSize = DefaultChunkSize, CancellationToken cancellationToken = default)
    {
        using var memoryStream = new MemoryStream(fileData);

        await UploadFileChunkedAsync(memoryStream, encryptionKey, iv, chunkSize, cancellationToken);

        _logger.LogInformation("Byte array upload completed.");
    }

    private async Task UploadFileChunkedAsync(Stream fileStream, byte[] encryptionKey, byte[] iv, int chunkSize, CancellationToken cancellationToken)
    {
        var token = await _tokenService.GetAuthTokenAsync(cancellationToken);

        if (fileStream.Length == 0) throw new ArgumentException("The stream is empty.", nameof(fileStream));

        using Aes aes = Aes.Create();
        aes.Key = encryptionKey;
        aes.IV = iv;

        int bytesRead;
        byte[] buffer = new byte[chunkSize];

        while ((bytesRead = await fileStream.ReadAsync(buffer, 0, chunkSize, cancellationToken)) > 0)
        {
            var encryptedChunk = EncryptData(buffer.AsSpan(0, bytesRead), aes);

            _messageQueue.EnqueueUploadTask(new UploadTask { Token = token, Data = encryptedChunk });

            int attempt = 0;
            bool success = false;

            while (!success && attempt < MaxRetries)
            {
                try
                {
                    await ProcessUploadFromQueue(cancellationToken);

                    success = true;
                }
                catch (Exception ex) when (IsRetryable(ex))
                {
                    _logger.LogWarning(ex, "Upload failed, retrying...");
                    attempt++;
                    await Task.Delay(ExponentialBackoff(attempt), cancellationToken);
                }
            }

            if (!success)
            {
                throw new UploadException("Failed to upload file after multiple attempts.", ex);
            }
        }
    }

    private byte[] EncryptData(Span<byte> data, Aes aes)
    {
        using var encryptor = aes.CreateEncryptor(aes.Key, aes.IV);
        using var ms = new MemoryStream();
        using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
        {
            cs.Write(data.ToArray(), 0, data.Length);
            cs.FlushFinalBlock();
        }

        return ms.ToArray();
    }

    private async Task ProcessUploadFromQueue(CancellationToken cancellationToken)
    {
        var uploadTask = await _messageQueue.DequeueAsync(cancellationToken);

        using var httpClient = new HttpClient { Timeout = TimeSpan.FromMinutes(5) };
        // Assume we have a method to get the cloud storage endpoint
        var content = new ByteArrayContent(uploadTask.Data);

        HttpResponseMessage response;
        try
        {
            response = await httpClient.PostAsync("https://cloud-storage-endpoint/upload", content, cancellationToken);
            if (!response.IsSuccessStatusCode)
                throw new CloudStorageException($"Failed upload with status code: {response.StatusCode}");
        }
        catch (HttpRequestException ex) when (IsNetworkIssue(ex))
        {
            _logger.LogError(ex, "Network issue during file upload.");
            throw;
        }

        // Handle more exceptions or edge cases as needed
    }

    private bool IsRetryable(Exception ex)
    {
        return ex is HttpRequestException || ex is CloudStorageException;
    }

    private TimeSpan ExponentialBackoff(int attempt) => TimeSpan.FromSeconds(Math.Pow(2, attempt));

    public const int MaxRetries = 5;

    private class UploadTask
    {
        public string Token { get; set; }
        public byte[] Data { get; set; }
    }
}

// Assume these interfaces are implemented elsewhere in your project.
public interface ITokenService
{
    Task<string> GetAuthTokenAsync(CancellationToken cancellationToken);
}

public interface IMessageQueue
{
    void EnqueueUploadTask(UploadTask task);
    Task<UploadTask> DequeueAsync(CancellationToken cancellationToken);
}

public class TokenException : Exception { }
public class UploadException : Exception 
{
    public UploadException(string message, Exception innerException) : base(message, innerException) {}
}
public class CloudStorageException : Exception
{
    public CloudStorageException(string message) : base(message) {}
}
