```rust
use std::env;
use std::fs::{self, DirBuilder};
use std::io;
use std::os::unix::fs::PermissionsExt;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use tokio::time::{self, Duration, Instant};
use log::{info, warn, error};

// Configuration for the working directory
#[derive(Debug)]
struct Config {
    work_dir: PathBuf,
    min_space_bytes: u64,
}

impl Default for Config {
    fn default() -> Self {
        let mut env_work_dir = env::var_os("WORK_DIR").map(PathBuf::from);
        if let Some(ref dir) = env_work_dir {
            if dir.exists() && has_enough_space(dir, 10 * 1024 * 1024) && check_permissions(dir, "rw") {
                info!("Using WORK_DIR: {}", dir.display());
            } else {
                warn!("WORK_DIR is invalid or insufficient permissions/space. Creating a temporary directory.");
                env_work_dir = None;
            }
        }

        let work_dir = env_work_dir.unwrap_or_else(|| create_temp_directory("/tmp", 10 * 1024 * 1024));

        Self {
            work_dir,
            min_space_bytes: 10 * 1024 * 1024, // minimum space requirement
        }
    }
}

fn has_enough_space(path: &PathBuf, required_bytes: u64) -> bool {
    match fs::metadata(path) {
        Ok(metadata) => metadata.len() as u64 + required_bytes <= metadata.st_size(),
        Err(_) => false,
    }
}

fn check_permissions(path: &PathBuf, permissions: &str) -> bool {
    let mode = path.metadata().and_then(|m| m.permissions()).map(|p| p.mode());

    match mode {
        Some(mode_value) if permissions.contains("r") && (mode_value & 0o400 != 0) => true,
        Some(mode_value) if permissions.contains("w") && (mode_value & 0o200 != 0) => true,
        Some(mode_value) if permissions.contains("x") && (mode_value & 0o100 != 0) => true,
        _ => false,
    }
}

fn create_temp_directory(base: &str, min_space_bytes: u64) -> PathBuf {
    let mut attempt = 0;
    loop {
        attempt += 1;
        let temp_dir = format!("{}/rust_workdir_{}", base, attempt);
        if has_enough_space(&PathBuf::from(temp_dir.clone()), min_space_bytes) {
            match DirBuilder::new().prefix("rust_workdir").create(temp_dir) {
                Ok(_) => return PathBuf::from(temp_dir),
                Err(e) => error!("Failed to create temp directory: {:?}", e),
            }
        } else {
            warn!("No sufficient space for temp directory attempt {}", attempt);
        }
    }
}

struct FileManager {
    config: Config,
    cleanup_interval: Duration,
    start_time: Instant,
}

impl FileManager {
    pub fn new(config: Config, cleanup_interval: Duration) -> Self {
        Self {
            config,
            cleanup_interval,
            start_time: Instant::now(),
        }
    }

    async fn manage_directory(&self) {
        let work_dir = Arc::new(Mutex::new(self.config.work_dir.clone()));

        // Periodic clean-up task
        let interval = time::interval(self.cleanup_interval);
        let work_dir_clone = work_dir.clone();
        tokio::spawn(async move {
            while let Some(_) = interval.next().await {
                let mut dir_lock = work_dir_clone.lock().unwrap();
                if Instant::now() - self.start_time > *dir_lock.read().unwrap() {
                    if let Err(e) = fs::remove_dir_all(&*dir_lock) {
                        error!("Failed to clean up directory: {:?}", e);
                    } else {
                        info!("Directory cleaned up successfully.");
                    }
                }
            }
        });

        // Example file operations
        tokio::spawn(async move {
            loop {
                if let Ok(mut dir_lock) = work_dir.lock() {
                    let path = &*dir_lock;
                    fs::write(path.join("example.txt"), b"Sample content").unwrap();
                }
                time::sleep(Duration::from_secs(5)).await; // Simulate work
            }
        });

    }
}

#[tokio::main]
async fn main() -> io::Result<()> {
    env_logger::init();

    let config = Config::default();
    let file_manager = FileManager::new(config, Duration::from_secs(60));

    file_manager.manage_directory().await;

    Ok(())
}
```

