// Custom Logger with Severity Levels
class CustomLogger {
    private static final Logger logger = LoggerFactory.getLogger(CustomLogger.class);

    enum Severity { INFO, WARNING, ERROR }

    public void log(Severity severity, String message) {
        LocalDateTime timestamp = LocalDateTime.now();
        switch (severity) {
            case INFO:
                logger.info("INFO - " + timestamp + ": " + message);
                break;
            case WARNING:
                logger.warn("WARNING - " + timestamp + ": " + message);
                break;
            case ERROR:
                logger.error("ERROR - " + timestamp + ": " + message);
                break;
        }
    }
}

// FSA Function
class FiniteStateMachine {
    static class StateNode {
        List<Integer> transitions;

        StateNode() {
            this.transitions = new ArrayList<>();
        }
    }

    public List<Integer> getReachableStates(StateNode[] states, int index) throws InterruptedException {
        Set<Integer> visited = ConcurrentHashMap.newKeySet();
        List<Integer> result = Collections.synchronizedList(new ArrayList<>());
        Deque<Integer> stack = new ArrayDeque<>();

        stack.push(index);

        while (!stack.isEmpty()) {
            Integer current = stack.pop();

            if (visited.add(current)) {
                result.add(current);
                for (Integer neighbor : states[current].transitions) {
                    if (!visited.contains(neighbor)) {
                        stack.push(neighbor);
                    }
                }
            }
        }

        return Collections.unmodifiableList(result);
    }
}

// RESTful API Client with Rate Limiting
class ApiClient {
    private static final int MAX_REQUESTS_PER_SECOND = 5;
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public String fetchData(String url) throws IOException, InterruptedException {
        Callable<String> task = () -> {
            // Simulate API call (replace with actual HTTP request)
            return "Response from: " + url;
        };

        BlockingQueue<Runnable> queue = new LinkedBlockingQueue<>();
        RateLimiter limiter = new GuavaRateLimiter(MAX_REQUESTS_PER_SECOND);

        while (!queue.isEmpty()) {
            Runnable job = queue.poll();
            if (job != null) {
                Future<String> future = scheduler.submit(() -> {
                    limiter.acquire();
                    return task.call();
                });
                try {
                    return future.get();
                } catch (ExecutionException | InterruptedException e) {
                    throw new IOException("Failed to fetch data", e);
                }
            }
        }

        throw new IOException("Queue is empty");
    }
}

// Redis Cache Management
class DistributedCacheManager {
    private final JedisPool pool;

    public DistributedCacheManager(String redisHost, int redisPort) {
        this.pool = new JedisPool(redisHost, redisPort);
    }

    public String getCachedData(String key) {
        try (var jedis = pool.getResource()) {
            return jedis.get(key);
        }
    }

    public void cacheData(String key, String value) {
        try (var jedis = pool.getResource()) {
            jedis.setex(key, 3600, value); // Cache for 1 hour
        }
    }
}

// JSON Serialization/Deserialization for FSA
class JsonFsaSerializer {
    private final ObjectMapper mapper = new ObjectMapper();

    public String serialize(StateNode[] states) throws IOException {
        return mapper.writeValueAsString(states);
    }

    public StateNode[] deserialize(String json) throws IOException {
        TypeReference<StateNode[]> typeRef = new TypeReference<>() {};
        return mapper.readValue(json, typeRef);
    }
}

// Main Application
public class MachineLearningApp {
    private static final CustomLogger logger = new CustomLogger();

    public static void main(String[] args) {
        // Example usage of the components

        // Setup Redis Cache Manager
        DistributedCacheManager cacheManager = new DistributedCacheManager("localhost", 6379);

        // Simulate FSA states
        StateNode[] states = new StateNode[10];
        for (int i = 0; i < states.length; i++) {
            states[i] = new StateNode();
        }
        states[0].transitions.add(1);
        states[1].transitions.add(2);
        states[2].transitions.addAll(Arrays.asList(0, 3)); // Loop and Dead End
        states[3].transitions.add(4);

        FiniteStateMachine fsa = new FiniteStateMachine();
        try {
            List<Integer> reachableStates = fsa.getReachableStates(states, 0);
            logger.log(CustomLogger.Severity.INFO, "Reachable States: " + reachableStates);
        } catch (InterruptedException e) {
            logger.log(CustomLogger.Severity.ERROR, "FSA processing interrupted");
        }

        // Serialize and Deserialize FSA
        JsonFsaSerializer serializer = new JsonFsaSerializer();
        try {
            String serialized = serializer.serialize(states);
            StateNode[] deserializedStates = serializer.deserialize(serialized);
            logger.log(CustomLogger.Severity.INFO, "FSA Serialized and Deserialized");
        } catch (IOException e) {
            logger.log(CustomLogger.Severity.ERROR, "Error in serialization/deserialization", e);
        }

        // Example API Client usage
        ApiClient apiClient = new ApiClient();
        try {
            String response = apiClient.fetchData("http://example.com/api/data");
            logger.log(CustomLogger.Severity.INFO, "API Response: " + response);
        } catch (IOException | InterruptedException e) {
            logger.log(CustomLogger.Severity.ERROR, "API call failed", e);
        }
    }
}
