public class WebsiteManager
{
    private const string WebConfigFileName = "web.config";

    public async Task<TaskResult> ManageWebsiteLifecycle(WebsiteOperation operation, DirectoryPath directory)
    {
        if (!File.Exists(Path.Combine(directory.Path, WebConfigFileName)))
        {
            LogError($"Web.config not found in directory: {directory.Path}");
            return TaskResult.Failure("Web.config is missing.");
        }

        switch (operation)
        {
            case WebsiteOperation.Add:
                return await AddWebsiteAsync(directory);
            case WebsiteOperation.Start:
                return await StartWebsiteAsync(directory);
            case WebsiteOperation.Stop:
                return await StopWebsiteAsync(directory);
            case WebsiteOperation.Remove:
                return await RemoveWebsiteAsync(directory);
            default:
                LogError($"Invalid operation: {operation}");
                return TaskResult.Failure("Unsupported website operation.");
        }
    }

    private async Task<TaskResult> AddWebsiteAsync(DirectoryPath directory)
    {
        // Check if the site already exists
        if (SiteExists(directory.Path))
        {
            LogError($"Site already exists at path: {directory.Path}");
            return TaskResult.Failure("Site already exists.");
        }

        // Validate application pool and bindings can be configured

        try
        {
            await AddSiteToIISAsync(directory);
            LogInfo($"Website added successfully at path: {directory.Path}");
            return TaskResult.Success("Site added successfully.");
        }
        catch (Exception ex)
        {
            LogError($"Failed to add website: {ex.Message}");
            return TaskResult.Failure("Failed to add site.");
        }
    }

    private async Task<TaskResult> StartWebsiteAsync(DirectoryPath directory)
    {
        if (!IsSiteRunning(directory.Path))
        {
            try
            {
                await StartSiteInIISAsync(directory);
                LogInfo($"Website started successfully at path: {directory.Path}");
                return TaskResult.Success("Site started successfully.");
            }
            catch (Exception ex)
            {
                LogError($"Failed to start website: {ex.Message}");
                return TaskResult.Failure("Failed to start site.");
            }
        }

        LogWarning($"Attempted to start a running site at path: {directory.Path}");
        return TaskResult.Success("Site is already running.");
    }

    private async Task<TaskResult> StopWebsiteAsync(DirectoryPath directory)
    {
        if (IsSiteRunning(directory.Path))
        {
            try
            {
                await StopSiteInIISAsync(directory);
                LogInfo($"Website stopped successfully at path: {directory.Path}");
                return TaskResult.Success("Site stopped successfully.");
            }
            catch (Exception ex)
            {
                LogError($"Failed to stop website: {ex.Message}");
                return TaskResult.Failure("Failed to stop site.");
            }
        }

        LogWarning($"Attempted to stop a non-running site at path: {directory.Path}");
        return TaskResult.Success("Site was not running.");
    }

    private async Task<TaskResult> RemoveWebsiteAsync(DirectoryPath directory)
    {
        if (!IsSiteRunning(directory.Path))
        {
            try
            {
                await RemoveSiteFromIISAsync(directory);
                LogInfo($"Website removed successfully at path: {directory.Path}");
                return TaskResult.Success("Site removed successfully.");
