import requests
import threading
import time
import logging
from cachetools import TTLCache, cachedmethod
from cachetools.keys import hashkey
from oauthlib.oauth2 import BackendApplicationClient
from requests_oauthlib import OAuth2Session


class WeatherProvider:
    def __init__(self, api_configurations, cache_ttl=1800, refresh_interval=900):
        self.api_configurations = api_configurations
        self.cache = TTLCache(maxsize=100, ttl=cache_ttl)
        self.refresh_interval = refresh_interval
        self.lock = threading.Lock()
        self.logger = logging.getLogger('weather_service')

    def _get_oauth_token(self, config):
        client = BackendApplicationClient(client_id=config['client_id'])
        oauth = OAuth2Session(client=client)
        token = oauth.fetch_token(token_url=config['token_url'], client_id=config['client_id'],
                                  client_secret=config['client_secret'])
        return token

    def _fetch_data_from_api(self, city, api_config):
        headers = {'Authorization': f"Bearer {api_config.get('access_token')}"}
        try:
            response = requests.get(api_config['url'].format(city=city), params={'units': 'metric'}, headers=headers)
            response.raise_for_status()
            return response.json()
        except requests.RequestException as e:
            self.logger.error(f'Error fetching data for {city}: {e}')
            time.sleep(2 ** self.retry_count)  # Exponential backoff
            self.retry_count += 1
            raise

    @cachedmethod(lambda self, city: hashkey(city), lock=lambda _: threading.RLock())
    def get_weather(self, city):
        for api_name, config in self.api_configurations.items():
            try:
                if 'access_token' not in config or time.time() > config['token_expiry']:
                    with self.lock:
                        token_info = self._get_oauth_token(config)
                        config.update(token_info)

                weather_data = self._fetch_data_from_api(city, config)
                return weather_data
            except Exception as e:
                self.logger.warning(f'Failed to fetch from {api_name}: {e}')
        raise RuntimeError('All API providers failed')

    def refresh_cache(self):
        while True:
            with self.lock:
                # Refresh cache logic if necessary
                pass
            time.sleep(self.refresh_interval)

