#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} Record;

// Error codes for different failure scenarios
#define SUCCESS 0
#define ALLOCATION_FAILED -1
#define DATA_SOURCE_ERROR -2

// Function prototypes
Record* initialize_records(int num_records, int* error_code);
void cleanup(Record* records);

// Mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Simulate fetching data from an external source asynchronously
int fetch_data_from_source(long* offset, int* key) {
    // Placeholder implementation: replace with actual data fetching logic
    *offset = rand() % 1000000;
    *key = rand() % 1000;

    // Return non-zero on failure to simulate error condition
    return 1; // Success by default, change as needed for simulation
}

Record* initialize_records(int num_records, int* error_code) {
    Record* records = NULL;

    if (num_records <= 0) {
        *error_code = DATA_SOURCE_ERROR;
        return NULL;
    }

    // Allocate memory for the records array
    records = malloc(num_records * sizeof(Record));
    if (!records) {
        *error_code = ALLOCATION_FAILED;
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_records; ++i) {
        long offset;
        int key;

        if (!fetch_data_from_source(&offset, &key)) {
            pthread_mutex_unlock(&mutex);
            *error_code = DATA_SOURCE_ERROR;
            cleanup(records);
            return NULL;
        }

        records[i].offset = offset;
        records[i].key = key;
    }

    pthread_mutex_unlock(&mutex);

    *error_code = SUCCESS;
    return records;
}

void cleanup(Record* records) {
    if (records) {
        free(records);
    }
}
```

**Explanation:**

1. **Data Structure**: A `struct` named `Record` is defined to hold the offset and key.

2. **Error Codes**: Defines error codes for different failure conditions like allocation failures or data source errors.

3. **Thread Safety**: Uses a mutex (`pthread_mutex_t`) to ensure thread-safe operations when accessing shared resources, such as during data fetching and initialization.

4. **Data Fetching**: A placeholder function `fetch_data_from_source` simulates fetching data from an external source asynchronously.

5. **Initialization Function**: The `initialize_records` function dynamically allocates memory for the records and populates them using simulated asynchronous data. It handles allocation failures gracefully by checking if `malloc` returned `NULL`.

6. **Cleanup Function**: A helper function `cleanup` is provided to free allocated resources in case of failure during initialization.

7. **Error Handling**: Error codes are set appropriately based on different failure conditions, and detailed error handling ensures memory leaks are avoided.

