// Logging level enum
enum class LogLevel {
    Info,
    Warn,
    Error
};

// Utility function to convert logging level from string to enum
LogLevel StringToLogLevel(const std::string& level) {
    if (level == "info") return LogLevel::Info;
    if (level == "warn") return LogLevel::Warn;
    return LogLevel::Error; // Default to error for any unknown levels
}

// Test function type definition
using TestFunction = std::function<void(const std::string&, std::function<void()>, const Configuration&)>;

// Scheduler class to manage concurrency and timeouts
class TestScheduler {
public:
    TestScheduler(int maxConcurrentTests, int testTimeout)
        : maxConcurrentTests_(maxConcurrentTests), testTimeout_(testTimeout) {}

    void RunTests(const std::vector<TestFunction>& tests, const std::string& moduleLabel,
                  LogLevel loggingLevel, ResourceManager& resourceManager,
                  DatabaseConnection& databaseConnection);

private:
    void TestWorker();

    int maxConcurrentTests_;
    int testTimeout_;
    std::queue<std::thread> threadPool_;
    std::mutex queueMutex_;
    std::condition_variable cv_;
    bool stop_ = false;
};

void TestScheduler::RunTests(const std::vector<TestFunction>& tests, const std::string& moduleLabel,
                             LogLevel loggingLevel, ResourceManager& resourceManager,
                             DatabaseConnection& databaseConnection) {
    for (const auto& test : tests) {
        MockLib::Initialize();
        Configuration config = databaseConnection.GetConfiguration(moduleLabel);

        threadPool_.push(std::thread([&, this]() {
            TestFunction testFunc = [test, moduleLabel, &resourceManager, loggingLevel, config]() {
                try {
                    std::function<void()> attackFunction;
                    test(moduleLabel, attackFunction, config);
                    MockLib::Reset();
                } catch (const std::exception& ex) {
                    if (loggingLevel == LogLevel::Error || loggingLevel == LogLevel::Warn) {
                        std::cerr << "Test failed: " << ex.what() << "\n";
                    }
                }
            };

            auto startTime = std::chrono::steady_clock::now();
            testFunc();
            auto endTime = std::chrono::steady_clock::now();

            double executionTime = std::chrono::duration<double>(endTime - startTime).count();
            if (loggingLevel == LogLevel::Info || loggingLevel == LogLevel::Warn) {
                std::cout << "Test executed in: " << executionTime << " seconds\n";
            }

            resourceManager.Cleanup();
        }));

        // Manage concurrency
        if (threadPool_.size() >= maxConcurrentTests_) {
            TestWorker();
        }
    }

    // Wait for all threads to complete
    while (!threadPool_.empty()) {
        TestWorker();
    }
}

void TestScheduler::TestWorker() {
    std::unique_lock<std::mutex> lock(queueMutex_);
    cv_.wait(lock, [this] { return !threadPool_.empty() || stop_; });

    if (!threadPool_.empty()) {
        threadPool_.front().join();
        threadPool_.pop();
    }
}

void runModuleTests(const std::string& moduleLabel, const std::vector<TestFunction>& testSuite,
                    const std::string& loggingLevel, int cooldown, ResourceManager& resourceManager,
                    DatabaseConnection& databaseConnection, int maxConcurrentTests, int testTimeout) {

    LogLevel logLevel = StringToLogLevel(loggingLevel);
    TestScheduler scheduler(maxConcurrentTests, testTimeout);

    for (const auto& test : testSuite) {
        MockLib::Reset();
        Configuration config = databaseConnection.GetConfiguration(moduleLabel);

        // Delay to simulate cooldown period
        std::this_thread::sleep_for(std::chrono::seconds(cooldown));

        scheduler.RunTests({test}, moduleLabel, logLevel, resourceManager, databaseConnection);
    }
}

int main() {
    // Example usage:
    ResourceManager resourceManager;
    DatabaseConnection dbConnection;

    std::vector<TestFunction> tests = {
        [](const std::string& label, std::function<void()> attackFunc, const Configuration& config) {
            // Simulate a test
            if (attackFunc) attackFunc();
            std::cout << "Running test for: " << label << "\n";
        }
    };

    runModuleTests("AttackModule", tests, "info", 2, resourceManager, dbConnection, 3, 10);

    return 0;
}
