#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>

// Error handling utility
void handleErrors(void) {
    fprintf(stderr, "An error occurred\n");
    exit(EXIT_FAILURE);
}

// Function to initialize EVP_CIPHER_CTX with AES and mode selection
EVP_CIPHER_CTX* initCipherContext(int keySizeBits, int mode, unsigned char *salt, size_t saltLen) {
    if (keySizeBits != 128 && keySizeBits != 192 && keySizeBits != 256) {
        fprintf(stderr, "Invalid key size. Must be 128, 192 or 256 bits.\n");
        return NULL;
    }

    int blockSize = keySizeBits / 8; // AES block size in bytes
    int cipherType = EVP_aes_128_cbc();

    switch (keySizeBits) {
        case 128: cipherType = EVP_aes_128_cbc(); break;
        case 192: cipherType = EVP_aes_192_cbc(); break;
        case 256: cipherType = EVP_aes_256_cbc(); break;
    }

    if (mode == EVP_CIPH_GCM_MODE) {
        switch (keySizeBits) {
            case 128: cipherType = EVP_aes_128_gcm(); break;
            case 192: cipherType = EVP_aes_192_gcm(); break;
            case 256: cipherType = EVP_aes_256_gcm(); break;
        }
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) handleErrors();

    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];

    // Simulate retrieval from external key management service
    int keyLength = RAND_bytes(key, blockSize);
    if (keyLength != 1) handleErrors(); // Securely generate a random key

    int ivLength = EVP_CIPHER_iv_length(cipherType);
    if (!RAND_bytes(iv, ivLength)) handleErrors(); // Securely generate a random IV

    if (!EVP_EncryptInit_ex(ctx, cipherType, NULL, key, iv)) handleErrors();

    return ctx;
}

// Example usage of the function
int main() {
    unsigned char salt[] = "example_salt"; // Use secure custom salt value from config or user input.
    size_t saltLen = sizeof(salt) - 1;

    EVP_CIPHER_CTX *ctx = initCipherContext(256, EVP_CIPH_GCM_MODE, salt, saltLen);
    if (!ctx) {
        handleErrors();
    }

    // Perform encryption/decryption operations with ctx
    // ...

    EVP_CIPHER_CTX_free(ctx);

    return 0;
}
```

