import asyncio
from threading import Lock
from typing import Callable, List

class Task:
    def __init__(self, func: Callable, *args, **kwargs):
        self.func = func
        self.args = args
        self.kwargs = kwargs
        self.custom_attributes = {}

    async def execute(self):
        await self.func(*self.args, **self.kwargs)

class TaskCustomizerCallback:
    def __call__(self, task: Task) -> Task:
        return task

class AsyncTaskQueueManager:
    def __init__(self):
        self.queues = {}
        self.lock = Lock()

    async def initialize_task_queue(self, name: str, max_size: int, concurrency_level: int):
        if not isinstance(max_size, int) or not isinstance(concurrency_level, int):
            raise ValueError("Max size and concurrency level must be integers.")
        if max_size <= 0 or concurrency_level <= 0:
            raise ValueError("Max size and concurrency level must be positive.")

        async def worker(name: str):
            queue = self.queues[name]
            semaphore = asyncio.Semaphore(concurrency_level)
            while True:
                task = await queue.get()
                if task is None:
                    break
                async with semaphore:
                    try:
                        await task.execute()
                    except Exception as e:
                        print(f"Task execution failed: {e}")
                    finally:
                        queue.task_done()

        self.queues[name] = asyncio.Queue(maxsize=max_size)
        for _ in range(concurrency_level):
            asyncio.create_task(worker(name))

    async def initialize_task_queue_with_customizers(self, name: str, max_size: int, concurrency_level: int,
                                                     customizer_callback: TaskCustomizerCallback = None):
        await self.initialize_task_queue(name, max_size, concurrency_level)

        if customizer_callback is not None:
            async def customized_worker(name: str):
                queue = self.queues[name]
                semaphore = asyncio.Semaphore(concurrency_level)
                while True:
                    task = await queue.get()
                    if task is None:
                        break
                    if customizer_callback:
                        task = customizer_callback(task)
                    async with semaphore:
                        try:
                            await task.execute()
                        except Exception as e:
                            print(f"Task execution failed: {e}")
                        finally:
                            queue.task_done()

            self.queues[name] = asyncio.Queue(maxsize=max_size)
            for _ in range(concurrency_level):
                asyncio.create_task(customized_worker(name))

    async def add_task(self, name: str, task: Task):
        if name not in self.queues:
            raise ValueError(f"Queue {name} does not exist.")

        await self.queues[name].put(task)

    async def stop_queue(self, name: str):
        if name in self.queues:
            await self.queues[name].put(None)
            del self.queues[name]

class TaskHealthChecker:
    def isHealthy(self, task: Task) -> bool:
        # Implement health check logic
        pass

async def main():
    manager = AsyncTaskQueueManager()

    async def example_task(x):
        print(f"Executing task with value {x}")

    await manager.initialize_task_queue("example", max_size=10, concurrency_level=3)
    for i in range(15):
        task = Task(example_task, i)
        await manager.add_task("example", task)

    await asyncio.sleep(2)  # Allow tasks to run
    await manager.stop_queue("example")

# Run the example
asyncio.run(main())
