```javascript
// Module for managing script fetching with caching and loading logic
const ScriptManager = (() => {
  const cache = new Map();

  async function fetchScripts(apiEndpoint) {
    try {
      const response = await fetch(apiEndpoint);
      if (!response.ok) throw new Error(`Network response was not ok: ${response.statusText}`);

      const scripts = await response.json();

      // Cache fetched scripts
      cache.clear(); // Clear old entries
      scripts.forEach(script => {
        if (script.version || script.timestamp) {
          cache.set(script.id, { ...script, timestamp: new Date().toISOString() });
        }
      });

      return scripts;
    } catch (error) {
      console.error('Error fetching scripts:', error);
      throw error; // Rethrow to allow retry logic
    }
  }

  function isCacheValid(script) {
    const cached = cache.get(script.id);
    if (!cached) return false;

    if (script.version && script.version !== cached.version) return false;
    if (script.timestamp && new Date(script.timestamp) > new Date(cached.timestamp)) return false;

    return true;
  }

  function getScripts(apiEndpoint, retryCount = 3) {
    return fetchScripts(apiEndpoint).catch(error => {
      if (retryCount === 0) throw error; // No more retries
      console.log(`Retrying... Attempts left: ${retryCount}`);
      return new Promise(resolve => setTimeout(() => resolve(getScripts(apiEndpoint, retryCount - 1)), 1000));
    });
  }

  function cleanupUnusedScripts(renderedScriptIds) {
    const existing = document.querySelectorAll('script[data-script-id]');
    existing.forEach(scriptElement => {
      if (!renderedScriptIds.includes(scriptElement.getAttribute('data-script-id'))) {
        scriptElement.remove();
      }
    });
  }

  return { getScripts, isCacheValid, cleanupUnusedScripts };
})();

// Module for rendering scripts
const ScriptRenderer = (() => {

  function createScriptTag(script) {
    const tag = document.createElement('script');

    if (script.src) {
      tag.src = script.src;
      tag.async = true; // Load asynchronously
    } else if (script.code) {
      tag.innerHTML = script.code;
    }

    if (script.type) {
      tag.type = script.type;
    }

    tag.setAttribute('data-script-id', script.id);

    return tag;
  }

  function renderScripts(scripts, container) {
    const scriptElements = scripts.map(script => createScriptTag(script)).filter(Boolean);

    // Append new scripts in order
    scriptElements.forEach(scriptElement => {
      container.appendChild(scriptElement);
    });

    return Array.from(scriptElements).map(el => el.getAttribute('data-script-id'));
  }

  function showLoadingIndicator(show) {
    const loader = document.getElementById('loading-spinner');
    if (loader) loader.style.display = show ? 'block' : 'none';
  }

  async function loadAndRenderScripts(apiEndpoint, containerId) {
    showLoadingIndicator(true);

    try {
      const scripts = await ScriptManager.getScripts(apiEndpoint);

      // Filter out cached and valid scripts
      const newScriptsToLoad = scripts.filter(script => !ScriptManager.isCacheValid(script));

      // Render all scripts to the footer
      const container = document.getElementById(containerId);
      if (!container) throw new Error('Container not found');

      const scriptIds = renderScripts(newScriptsToLoad, container);

      // Cleanup old scripts
      ScriptManager.cleanupUnusedScripts(scriptIds);

    } catch (error) {
      console.error('Error during script loading and rendering:', error);
    } finally {
      showLoadingIndicator(false);
    }
  }

  return { loadAndRenderScripts };
})();

// Usage example: Load scripts into a footer with the ID 'footer'
ScriptRenderer.loadAndRenderScripts('/api/scripts', 'footer');
```

