use std::env;
use std::fs::{self, DirEntry};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};
use tokio::fs as async_fs;
use tokio::task;
use log::{info, error, warn};
use std::collections::HashMap;
use uuid::Uuid;

mod directory_management {
    use super::*;
    pub fn get_or_create_directory(prefix: &str, default_path: &Path) -> Result<PathBuf, String> {
        let dir_env = env::var("MY_DIR_PATH").map_err(|_| "Failed to read environment variable")?;

        if Path::new(&dir_env).exists() {
            info!("Using existing directory from MY_DIR_PATH");
            return Ok(PathBuf::from(dir_env));
        }

        let mut path_buf = default_path.to_path_buf();
        path_buf.push(format!("{}_{}", prefix, Uuid::new_v4()));

        if !path_buf.exists() {
            match fs::create_dir_all(&path_buf) {
                Ok(_) => info!("Created new directory: {:?}", path_buf),
                Err(e) => return Err(format!("Failed to create directory: {}", e)),
            }
        }

        env::set_var("MY_DIR_PATH", path_buf.to_str().unwrap());

        Ok(path_buf)
    }

    pub async fn cleanup_directory(dir_path: &Path, interval: Duration) {
        let mut interval = interval;
        loop {
            if dir_path.exists() && dir_path.is_dir() {
                match async_fs::remove_dir_all(dir_path).await {
                    Ok(_) => info!("Cleaned up directory: {:?}", dir_path),
                    Err(e) => warn!("Failed to clean up directory: {}", e),
                }
            } else {
                info!("Directory does not exist or is not a directory: {:?}", dir_path);
            }

            tokio::time::sleep(interval).await;
        }
    }
}

mod logging {
    use super::*;
    pub fn setup_logging() {
        env_logger::init();
    }
}

mod database_interaction {
