    #[derive(Debug, Clone)]
    struct DirectoryMetadata {
        creation_time: Instant,
        last_cleanup_time: Option<Instant>,
    }

    impl DirectoryMetadata {
        pub fn new(creation_time: Instant) -> Self {
            Self {
                creation_time,
                last_cleanup_time: None,
            }
        }

        pub async fn record_metadata(&self, db_conn: &str) {
            // Simulated database interaction
            info!("Recording metadata for directory at {}: creation time {:?}, last cleanup {:?}", db_conn, self.creation_time, self.last_cleanup_time);
            // Here you would implement actual DB logic with error handling and retries.
        }
    }
}

async fn manage_persistent_directory() -> Result<(), String> {
    logging::setup_logging();

    let prefix = "my_app";
    let default_path = Path::new("/tmp/my_dir");
    let dir_path = directory_management::get_or_create_directory(prefix, default_path)?;

    let metadata = database_interaction::DirectoryMetadata::new(Instant::now());
    tokio::spawn(async move {
        metadata.record_metadata("database_connection_string").await;
    });

    let cleanup_interval = Duration::from_secs(600); // Default 10 minutes
    let _cleanup_task = directory_management::cleanup_directory(&dir_path, cleanup_interval);

    Ok(())
}

#[tokio::main]
async fn main() {
    if let Err(e) = manage_persistent_directory().await {
        error!("Error managing persistent directory: {}", e);
    }
}
