### Python Program to Compile Text File Statistics

```python
import os
import sys
from pathlib import Path
from datetime import datetime
import logging
import argparse
import multiprocessing as mp

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def file_stats(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
            num_lines = len(lines)
            words = sum(len(line.split()) for line in lines)
            chars = sum(len(line) for line in lines)
        return (num_lines, words, chars)
    except Exception as e:
        logging.error(f"Failed to read {file_path}: {e}")
        return None

def filter_files(directory, min_size=0, max_size=float('inf'), since=None):
    filtered_files = []
    for file in Path(directory).glob('*'):
        if file.suffix in ['.md', '.pdf']:
            continue
        size = file.stat().st_size
        if not (min_size <= size <= max_size):
            continue
        creation_date = datetime.fromtimestamp(file.stat().st_ctime)
        if since and creation_date < since:
            continue
        filtered_files.append(str(file))
    return filtered_files

def compile_statistics(directory, output_file=None, min_size=0, max_size=float('inf'), since=None):
    files = filter_files(directory, min_size, max_size, since)
    with mp.Pool() as pool:
        results = pool.map(file_stats, files)

    total_lines, total_words, total_chars = 0, 0, 0
    for result in results:
        if result:
            lines, words, chars = result
            total_lines += lines
            total_words += words
            total_chars += chars

    stats = f"Total Lines: {total_lines}\nTotal Words: {total_words}\nTotal Characters: {total_chars}"
    logging.info(stats)

    if output_file:
        with open(output_file, 'w') as out_f:
            out_f.write(stats)
    else:
        print(stats)

def main():
    parser = argparse.ArgumentParser(description="Compile text file statistics.")
    parser.add_argument("directory", type=str, help="Directory containing text files")
    parser.add_argument("--output", type=str, help="Output file to write results")
    parser.add_argument("--min-size", type=int, default=0, help="Minimum file size in bytes")
    parser.add_argument("--max-size", type=int, default=float('inf'), help="Maximum file size in bytes")
    parser.add_argument("--since", type=lambda s: datetime.strptime(s, '%Y-%m-%d'), help="Filter files created since (YYYY-MM-DD)")

    args = parser.parse_args()

    if not os.path.isdir(args.directory):
        logging.error("Invalid directory path.")
        sys.exit(1)

    compile_statistics(
        args.directory,
        output_file=args.output,
        min_size=args.min_size,
        max_size=args.max_size,
        since=args.since
    )

if __name__ == "__main__":
    main()
```

This solution provides a basic framework for implementing an advanced distributed octree in C++ and a Python program to compile statistics from text files, incorporating multiprocessing for improved performance. Both implementations consider fault tolerance, synchronization, and extensibility as per the requirements.

