```javascript
const fs = require('fs').promises;
const path = require('path');
const crypto = require('crypto');
const winston = require('winston');

class ConfigManager {
  constructor() {
    this.factoryRegistry = new Map();
    this.logger = winston.createLogger({
      level: 'info',
      format: winston.format.json(),
      transports: [
        new winston.transports.Console()
      ],
    });
  }

  async loadConfigFiles(baseDir, envs) {
    const tasks = envs.map(env => 
      fs.readFile(path.join(baseDir, `${env}.json`), 'utf8')
      .then(data => this.parseAndValidateJSON(data))
      .catch(err => this.handleError(`Error loading config for ${env}:`, err))
    );

    try {
      await Promise.all(tasks);
    } catch (error) {
      throw new Error('Failed to load all configuration files.');
    }
  }

  parseAndValidateJSON(jsonString) {
    let config;
    try {
      config = JSON.parse(jsonString);
    } catch (e) {
      throw new Error(`Invalid JSON: ${e.message}`);
    }

    // Implement specific validation logic here
    return config;
  }

  addFactoryFunction(envId, factoryFn) {
    if (this.factoryRegistry.has(envId)) {
      throw new Error(`Factory for environment "${envId}" already exists.`);
    }
    this.factoryRegistry.set(envId, factoryFn);
  }

  createConfigInstance(envId) {
    const factoryFn = this.factoryRegistry.get(envId);
    if (!factoryFn) {
      throw new Error(`No factory function registered for environment "${envId}".`);
    }
    return factoryFn();
  }

  convertToJSON(configObject) {
    return JSON.stringify(configObject, null, 2);
  }

  createInstanceFromJSON(jsonString) {
    const config = this.parseAndValidateJSON(jsonString);
    return new ConfigManager().loadConfigFiles('', [config.envId]).then(() => {
      return this.createConfigInstance(config.envId);
    });
  }

  handleError(message, error) {
    this.logger.error(`${message} ${error.message}`);
    throw error;
  }

  async readFromService(serviceClient, keyPath) {
    try {
      const encryptedData = await serviceClient.getParameter({ Name: keyPath }).promise();
      return this.decryptConfig(encryptedData.Parameter.Value);
    } catch (err) {
      throw new Error(`Error reading from service for key ${keyPath}: ${err.message}`);
    }
  }

  async writeToService(serviceClient, keyPath, configData) {
    const encryptedData = this.encryptConfig(configData);
    try {
      await serviceClient.putParameter({
        Name: keyPath,
        Value: encryptedData,
        Type: 'SecureString',
        Overwrite: true
      }).promise();
      return `Successfully wrote to ${keyPath}`;
    } catch (err) {
      throw new Error(`Error writing to service for key ${keyPath}: ${err.message}`);
    }
  }

  encryptConfig(data) {
    const token = crypto.randomBytes(16).toString('hex');
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(process.env.ENCRYPTION_KEY), Buffer.from(token));
    let encrypted = cipher.update(JSON.stringify(data), 'utf8', 'hex');
    encrypted += cipher.final('hex');
    return { token, data: encrypted };
  }

  decryptConfig(encryptedData) {
    const parts = JSON.parse(Buffer.from(encryptedData, 'hex').toString());
    const decipher = crypto.createDecipheriv('aes-256-cbc', Buffer.from(process.env.ENCRYPTION_KEY), Buffer.from(parts.token));
    let decrypted = decipher.update(parts.data, 'hex', 'utf8');
    decrypted += decipher.final('utf8');
    return JSON.parse(decrypted);
  }

  hashSecret(secret) {
    const hashed = crypto.createHash('sha256').update(secret).digest('hex');
    return { token: crypto.randomBytes(16).toString('hex'), hash: hashed };
  }
}

module.exports = ConfigManager;

