// FooterModule.js

class FooterModule {
    constructor(apiEndpoint) {
        this.apiEndpoint = apiEndpoint;
        this.scriptCache = new Set();
        this.spinnerElement = null;
    }

    // Initialize method to set up DOM elements and event listeners
    initialize() {
        this.createSpinner();
        this.renderFooterScripts().catch(error => console.error('Error loading footer scripts:', error));
    }

    // Create a loading spinner for better user experience
    createSpinner() {
        const spinnerContainer = document.createElement('div');
        spinnerContainer.style.position = 'fixed';
        spinnerContainer.style.bottom = '20px';
        spinnerContainer.style.left = '50%';
        spinnerContainer.style.transform = 'translateX(-50%)';

        this.spinnerElement = document.createElement('div');
        this.spinnerElement.innerText = 'Loading...';
        this.spinnerElement.style.border = '4px solid rgba(0, 0, 0, .1)';
        this.spinnerElement.style.borderTopColor = '#000';
        this.spinnerElement.style.borderRadius = '50%';
        this.spinnerElement.style.width = '40px';
        this.spinnerElement.style.height = '40px';
        this.spinnerElement.style.animation = 'spin 1s linear infinite';

        spinnerContainer.appendChild(this.spinnerElement);
        document.body.appendChild(spinnerContainer);

        // Automatically hide spinner after a reasonable timeout
        setTimeout(() => {
            if (this.spinnerElement) this.spinnerElement.style.display = 'none';
        }, 5000); // Timeout can be adjusted based on user experience requirements
    }

    // Fetch scripts from the API endpoint and handle various scenarios
    async fetchScripts() {
        try {
            const response = await fetch(this.apiEndpoint, { timeout: 5000 });
            if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
            const data = await response.json();

            if (!Array.isArray(data)) throw new TypeError('Expected an array of scripts from API');
            return data;
        } catch (error) {
            console.error('Failed to fetch scripts:', error);
            return [];
        }
    }

    // Render the footer based on fetched script objects
    async renderFooterScripts() {
        if (!this.spinnerElement) this.createSpinner();

        const scripts = await this.fetchScripts();

        if (!scripts.length) {
            if (this.spinnerElement) this.spinnerElement.style.display = 'none';
            console.warn('No scripts available to load.');
            return;
        }

        // Start loading scripts asynchronously
        for (const script of scripts) {
            if (this.isScriptCached(script.src)) continue;

            try {
                await this.loadScript(script);
                this.scriptCache.add(script.src);  // Cache the successfully loaded script
            } catch (error) {
                console.error(`Error loading script ${script.src}:`, error);
            }
        }

        if (this.spinnerElement) this.spinnerElement.style.display = 'none';
    }

    // Check if a script is already cached
    isScriptCached(src) {
        return this.scriptCache.has(src);
    }

    // Load individual scripts and handle their types
    async loadScript({ src, type }) {
        const elem = document.createElement(type === 'css' ? 'link' : 'script');

        if (type === 'css') {
            elem.rel = 'stylesheet';
            elem.href = src;
        } else {
            elem.src = src;
            elem.async = true;
        }

        return new Promise((resolve, reject) => {
            const timeoutId = setTimeout(() => {
                elem.onerror = null;
                elem.onload = null;
                document.head.removeChild(elem);
                reject(new Error(`Loading script timed out: ${src}`));
            }, 10000); // Timeout can be adjusted

            elem.onerror = () => {
                clearTimeout(timeoutId);
                reject(new Error(`Failed to load script: ${src}`));
            };

            elem.onload = () => {
                clearTimeout(timeoutId);
                resolve();
            };

            document.head.appendChild(elem);
        });
    }
}

// Usage
