```rust
use clap::{Arg, Command};
use config::{Config, ConfigError, Environment, File};
use env_logger::Env;
use log::{error, info, warn};
use reqwest::Client;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use tokio::signal;
use warp::{http::StatusCode, Filter};

#[derive(Debug, Deserialize)]
struct AppConfig {
    functions: HashMap<String, FunctionConfig>,
}

#[derive(Debug, Deserialize)]
struct FunctionConfig {
    name: String,
    auth_method: AuthMethod,
    rate_limit: u32,
    retry_attempts: u32,
}

#[derive(Debug, Deserialize)]
enum AuthMethod {
    OAuth2 { token: String },
    ApiKey { key: String },
    TokenBased { token: String },
}

async fn run_function(config: &FunctionConfig) -> Result<(), Box<dyn std::error::Error>> {
    match config.auth_method {
        AuthMethod::OAuth2 { token } => {
            // Handle OAuth2 authentication
            info!("Running function with OAuth2");
        }
        AuthMethod::ApiKey { key } => {
            // Handle API Key authentication
            info!("Running function with API Key");
        }
        AuthMethod::TokenBased { token } => {
            // Handle Token-based authentication
            info!("Running function with Token-Based auth");
        }
    }

    let client = Client::new();
    let response = retry_with_backoff(move || async {
        // Simulate API call
        client.get("https://api.example.com/resource").send().await
    }, config.retry_attempts).await?;

    match response.status() {
        StatusCode::OK => info!("Function executed successfully"),
        _ => error!("Failed to execute function"),
    }

    Ok(())
}

async fn retry_with_backoff<F, T>(mut operation: F, attempts: u32) -> Result<T, reqwest::Error>
where
    F: FnMut() -> tokio::task::JoinHandle<Result<T, reqwest::Error>>,
{
    let mut current_attempt = 0;
    loop {
        match (operation)().await {
            Ok(result) => return Ok(result),
            Err(err) if current_attempt < attempts => {
                warn!("Operation failed, retrying... Attempt: {}", current_attempt + 1);
                tokio::time::sleep(tokio::time::Duration::from_secs(2u64.pow(current_attempt as u32))).await;
                current_attempt += 1;
            }
            Err(err) => return Err(err),
        }
    }
}

async fn handle_health_check() -> Result<impl warp::Reply, warp::Rejection> {
    Ok(warp::reply::with_status("Service is up and running", StatusCode::OK))
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let matches = Command::new("DynamicExecutor")
        .version("1.0")
        .author("Author Name <email@example.com>")
        .about("Dynamically executes functions based on a configuration file.")
        .arg(Arg::new("config").short('c').long("config").takes_value(true).required(true))
        .get_matches();

    let config_file = matches.value_of("config").unwrap();
    let mut settings = Config::default();

    // Merge configuration from files and environment variables
    if let Err(e) = settings
        .merge(File::with_name(config_file))
        .and_then(|_| settings.merge(Environment::new())) {
            eprintln!("Error loading config: {}", e);
            return Ok(());
        }

    // Initialize logger
    env_logger::Builder::from_env(Env::default().default_filter_or("info")).init();

    let config: AppConfig = settings.try_into()?;

    for (name, func_config) in &config.functions {
        match tokio::spawn(async move { run_function(func_config).await }) {
            Ok(_) => info!("Function {} completed", name),
            Err(err) => error!("Error running function {}: {}", name, err),
        }
    }

    // Setup health check endpoint
    let health_route = warp::path("health")
        .and(warp::get())
        .map(|| handle_health_check().await.unwrap());

    tokio::spawn(warp::serve(health_route).run(([127, 0, 0, 1], 3030)));

    // Handle graceful shutdown
    let ctrl_c = async {
        signal::ctrl_c().await.expect("failed to install CTRL+C handler");
        info!("received Ctrl+C, shutting down");
    };

    tokio::select! {
        _ = ctrl_c => {},
        _ = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()) => {}
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_function_execution() -> Result<(), Box<dyn std::error::Error>> {
        let config = FunctionConfig {
            name: "TestFunction".to_string(),
            auth_method: AuthMethod::ApiKey { key: "test_key".to_string() },
            rate_limit: 10,
            retry_attempts: 3,
        };

        run_function(&config).await?;
        Ok(())
    }
}
