```javascript
// Utility functions

function fetchScriptsWithRetry(url, retries = 3, interval = 1000) {
    return new Promise((resolve, reject) => {
        const attemptFetch = (attempt) => {
            if (attempt > retries) {
                return reject(new Error(`Failed to fetch scripts after ${retries} attempts`));
            }

            fetch(url)
                .then(response => response.json())
                .then(data => resolve(data))
                .catch(error => {
                    console.error(`Fetch attempt ${attempt} failed:`, error);
                    setTimeout(() => attemptFetch(attempt + 1), interval);
                });
        };

        attemptFetch(0);
    });
}

function renderScriptTag(script) {
    const defaultType = "text/javascript";
    const code = script.code || "";
    const type = script.type || defaultType;

    return `<script type="${type}" async>${code}</script>`;
}

// Cache management

const scriptCache = new Map();

function cacheScripts(scripts, versionKey = 'version') {
    scripts.forEach(script => {
        if (script[versionKey]) {
            scriptCache.set(script.url || '', { ...script, cached: true });
        }
    });
}

function getCachedScript(url) {
    return scriptCache.get(url);
}

// DOM management

function cleanUpOldScripts() {
    const existingScriptTags = Array.from(document.querySelectorAll('script')).filter(
        script => !script.dataset.isManaged
    );

    existingScriptTags.forEach(script => {
        if (!getCachedScript(script.src)) {
            script.remove();
        }
    });
}

// Main function

async function renderFooterScripts(scripts, apiUrl) {
    const container = document.createElement("div");
    let loadingIndicator = createLoadingSpinner();

    document.body.appendChild(loadingIndicator);

    try {
        // Fetch scripts dynamically if needed
        if (apiUrl && !scripts.length) {
            console.log('Fetching scripts from API...');
            const fetchedScripts = await fetchScriptsWithRetry(apiUrl);
            scripts = fetchedScripts || [];
        }

        scripts.forEach(script => {
            const cachedScript = getCachedScript(script.url);

            // Check for cache hit
            if (cachedScript && cachedScript.cached) {
                console.log(`Cache hit for script: ${script.url}`);
                container.insertAdjacentHTML('beforeend', renderScriptTag(cachedScript));
            } else {
                console.log(`Fetching new script: ${script.url}`);
                const tag = document.createElement("script");
                tag.type = script.type || "text/javascript";
                tag.async = true;
                tag.src = script.url || '';
                tag.dataset.isManaged = true;

                container.appendChild(tag);
                cacheScripts([script]);
            }
        });

    } catch (error) {
        console.error('Error fetching scripts:', error);
        document.body.insertAdjacentHTML('beforeend', `<div class="error-message">Failed to load some scripts.</div>`);
    }

    loadingIndicator.remove();
    cleanUpOldScripts();

    return container.innerHTML;
}

function createLoadingSpinner() {
    const spinner = document.createElement("div");
    spinner.className = "spinner";
    spinner.textContent = 'Loading scripts...';
    return spinner;
}
