// Octree.h

#ifndef OCTREE_H
#define OCTREE_H

#include <mutex>
#include <vector>
#include <openssl/evp.h>
#include <openssl/rand.h>

class OctreeNode {
public:
    int id;
    std::vector<OctreeNode*> children;
    void* data;  // This will be the encrypted sensitive data.
    std::mutex node_mutex;

    OctreeNode() : id(0), data(nullptr) { }
    ~OctreeNode() {
        delete[] reinterpret_cast<char*>(data);
    }

    void encryptData(const unsigned char* key, const unsigned char* iv, size_t dataSize);
    void decryptData(const unsigned char* key, const unsigned char* iv);

private:
    EVP_CIPHER_CTX* getNewCipherCtx(bool isEncrypting) const;
};

class Octree {
public:
    OctreeNode* root;

    Octree() : root(new OctreeNode()) { }
    ~Octree() { deleteNode(root); }

    void insertData(int nodeId, size_t dataSize);
    void updateNode(int nodeId, const std::vector<unsigned char>& newData);

private:
    void deleteNode(OctreeNode* node);

    // Key management functions
    EVP_PKEY* generateRSAKeyPair();
    unsigned char* deriveAESKey(size_t keyLength) const;
};

#endif  // OCTREE_H

// Octree.cpp

#include "Octree.h"
#include <cstring>

void OctreeNode::encryptData(const unsigned char* key, const unsigned char* iv, size_t dataSize) {
    EVP_CIPHER_CTX* ctx = getNewCipherCtx(true);
    auto encryptedSize = static_cast<unsigned int>(dataSize + AES_BLOCK_SIZE);
    std::unique_ptr<unsigned char[]> cipherText(new unsigned char[encryptedSize]);

    // Initialize encryption
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, key, iv);

    // Encrypt the data
    EVP_EncryptUpdate(ctx, cipherText.get(), &encryptedSize, reinterpret_cast<const unsigned char*>(data), dataSize);
    int finalSize = 0;
    EVP_EncryptFinal_ex(ctx, cipherText.get() + encryptedSize, &finalSize);

    // Update size and assign encrypted data to node's data pointer
    delete[] reinterpret_cast<char*>(data);
    this->data = new char[encryptedSize + finalSize];
    std::memcpy(this->data, cipherText.get(), encryptedSize + finalSize);

    EVP_CIPHER_CTX_free(ctx);
}

void OctreeNode::decryptData(const unsigned char* key, const unsigned char* iv) {
    if (!data) return;

    size_t dataSize = strlen(reinterpret_cast<const char*>(data));
    auto decryptedSize = static_cast<unsigned int>(dataSize - AES_BLOCK_SIZE);
    std::unique_ptr<unsigned char[]> plainText(new unsigned char[decryptedSize]);

    EVP_CIPHER_CTX* ctx = getNewCipherCtx(false);

    // Initialize decryption
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, key, iv);

    // Decrypt the data
    int result = 0;
    EVP_DecryptUpdate(ctx, plainText.get(), &decryptedSize, reinterpret_cast<const unsigned char*>(data), dataSize);
    if (EVP_DecryptFinal_ex(ctx, plainText.get() + decryptedSize, &result) != 1)
        throw std::runtime_error("Decryption failed");

    delete[] reinterpret_cast<char*>(data);
    this->data = new char[decryptedSize];
    memcpy(this->data, plainText.get(), decryptedSize);

    EVP_CIPHER_CTX_free(ctx);
}

EVP_CIPHER_CTX* OctreeNode::getNewCipherCtx(bool isEncrypting) const {
    auto* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) throw std::runtime_error("Failed to create cipher context");
    return ctx;
}

void Octree::insertData(int nodeId, size_t dataSize) {
    // Example insertion logic here (thread-safe)
    // Obtain a unique key for AES encryption
    unsigned char* aesKey = deriveAESKey(32);  // 256-bit key
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, sizeof(iv));

    std::unique_lock<std::mutex> lock(root->node_mutex);
    OctreeNode* node = findNodeById(nodeId, root);
    if (node) {
        node->encryptData(aesKey, iv, dataSize);
        delete[] aesKey;
    } else {
        // Handle insertion of new nodes
    }
}

void Octree::updateNode(int nodeId, const std::vector<unsigned char>& newData) {
    // Similar logic as insertData but with existing data update logic.
}

EVP_PKEY* Octree::generateRSAKeyPair() {
    EVP_PKEY_CTX* pkeyCtx = EVP_PKEY_CTX_new_id(EVP_PKEY_RSA, nullptr);
    EVP_PKEY_keygen_init(pkeyCtx);
    EVP_PKEY_CTX_set_rsa_keygen_bits(pkeyCtx, 2048);

    EVP_PKEY* pkey = nullptr;
    if (EVP_PKEY_keygen(pkeyCtx, &pkey) <= 0)
        throw std::runtime_error("Failed to generate RSA key pair");

    EVP_PKEY_CTX_free(pkeyCtx);
    return pkey;
}

unsigned char* Octree::deriveAESKey(size_t keyLength) const {
    unsigned char* key = new unsigned char[keyLength];
    if (!RAND_bytes(key, keyLength))
        throw std::runtime_error("Failed to generate AES key");

    return key;
}
