# FileProcessor.py

import os
import json
import csv
import zlib
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler
import threading
from flask import Flask, jsonify, request

app = Flask(__name__)

file_stats = {
    "total_lines": 0,
    "total_words": 0,
    "total_characters": 0
}

class FileHandler(FileSystemEventHandler):
    def __init__(self, directory_to_watch, exclusions):
        self.directory_to_watch = directory_to_watch
        self.exclusions = exclusions

    def on_modified(self, event):
        if not event.is_directory:
            process_file(event.src_path)

def process_file(file_path):
    global file_stats
    try:
        with open(file_path, 'rb') as f:
            if file_path.endswith('.gz'):
                with zlib.decompressobj(16+zlib.MAX_WBITS) as decompressor:
                    data = decompressor.decompress(f.read())
            else:
                data = f.read()

        if file_path.endswith('.csv'):
            analyze_csv(data.decode('utf-8'))
        elif file_path.endswith('.json'):
            process_json(data)
        else:
            analyze_text(data)

    except Exception as e:
        print(f"Error processing file {file_path}: {e}")

def analyze_csv(csv_data):
    global file_stats
    reader = csv.reader(csv_data.splitlines())
    for row in reader:
        file_stats['total_lines'] += 1
        words_in_row = sum(len(cell.split()) for cell in row)
        file_stats['total_words'] += words_in_row
        file_stats['total_characters'] += len(row[0]) + sum(len(cell) for cell in row[1:])

def process_json(json_data):
    global file_stats
    data = json.loads(json_data)
    # Example JSON processing logic here

def analyze_text(text_data):
    global file_stats
    lines = text_data.splitlines()
    words = text_data.split()

    file_stats['total_lines'] += len(lines)
    file_stats['total_words'] += len(words)
    file_stats['total_characters'] += sum(len(line) for line in lines)

@app.route('/stats', methods=['GET'])
def get_stats():
    return jsonify(file_stats)

if __name__ == "__main__":
    directory = "/path/to/watch"
    exclusions = ["exclude_pattern", "exclude_file.txt"]

    event_handler = FileHandler(directory, exclusions)
    observer = Observer()
    observer.schedule(event_handler, path=directory, recursive=True)
    observer.start()

    try:
        app.run(port=5000)
    except KeyboardInterrupt:
        observer.stop()

    observer.join()
```

