using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using BCrypt.Net;
using Konscious.Security.Cryptography;

public interface IPasswordHasherService
{
    string HashPassword(string plainText, HashingAlgorithm algorithm);
    bool VerifyPassword(string hashedPassword, string plainText, HashingAlgorithm algorithm);
}

public enum HashingAlgorithm
{
    SHA256,
    Bcrypt,
    Argon2
}

public class PasswordManager : IPasswordHasherService
{
    private readonly ConcurrentDictionary<string, string> _passwordCache = new();
    private readonly ILogger _logger;
    private ExternalAuthenticator _authenticator;

    public PasswordManager(ILogger logger, ExternalAuthenticator authenticator)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _authenticator = authenticator ?? throw new ArgumentNullException(nameof(authenticator));
    }

    public string HashPassword(string plainText, HashingAlgorithm algorithm)
    {
        if (string.IsNullOrEmpty(plainText))
            throw new ArgumentException("Plain text password cannot be null or empty.", nameof(plainText));

        var salt = GenerateSalt();
        string hashedPassword;

        switch (algorithm)
        {
            case HashingAlgorithm.SHA256:
                using var sha256 = SHA256.Create();
                var bytesToHash = Encoding.UTF8.GetBytes(salt + plainText);
                byte[] hashBytes = sha256.ComputeHash(bytesToHash);
                hashedPassword = Convert.ToBase64String(hashBytes);

                break;

            case HashingAlgorithm.Bcrypt:
                hashedPassword = BCrypt.Net.BCrypt.HashPassword(plainText, salt);
                break;

            case HashingAlgorithm.Argon2:
                using var argon2 = new Argon2id(Encoding.UTF8.GetBytes(plainText), Encoding.UTF8.GetBytes(salt));
                hashedPassword = Convert.ToBase64String(argon2.GetBytes(1024));
                break;

            default:
                throw new ArgumentOutOfRangeException(nameof(algorithm), "Unsupported hashing algorithm.");
        }

        _logger.Log($"Hash generated for user: {hashedPassword}");
        return hashedPassword;
    }

    public bool VerifyPassword(string hashedPassword, string plainText, HashingAlgorithm algorithm)
    {
        if (string.IsNullOrEmpty(hashedPassword) || string.IsNullOrEmpty(plainText))
            throw new ArgumentException("Parameters cannot be null or empty.");

        var salt = ExtractSalt(hashedPassword);

        switch (algorithm)
        {
            case HashingAlgorithm.SHA256:
                using var sha256 = SHA256.Create();
                var bytesToVerify = Encoding.UTF8.GetBytes(salt + plainText);
                byte[] hashBytes = sha256.ComputeHash(bytesToVerify);
                string verificationHash = Convert.ToBase64String(hashBytes);

                return hashedPassword == verificationHash;

            case HashingAlgorithm.Bcrypt:
                return BCrypt.Net.BCrypt.Verify(plainText, hashedPassword);

            case HashingAlgorithm.Argon2:
                using var argon2 = new Argon2id(Encoding.UTF8.GetBytes(plainText), Encoding.UTF8.GetBytes(salt));
                string computedHash = Convert.ToBase64String(argon2.GetBytes(1024));

                return hashedPassword == computedHash;

            default:
                throw new ArgumentOutOfRangeException(nameof(algorithm), "Unsupported hashing algorithm.");
        }
    }

    private string GenerateSalt()
    {
        var randomBytes = new byte[16];
        using var rng = RandomNumberGenerator.Create();
        rng.GetBytes(randomBytes);
        return Convert.ToBase64String(randomBytes);
    }

    private string ExtractSalt(string hashedPassword)
    {
        // Implementation to extract salt from a stored hash if required
        throw new NotImplementedException();
    }

    public void HandleExternalAuth()
    {
        try
        {
            _authenticator.InitiateMFA();
            _logger.Log("Multi-Factor Authentication initiated.");
        }
        catch (Exception ex)
        {
            _logger.LogError($"Error during MFA: {ex.Message}");
            // Fallback or retry mechanism
        }
    }

    public void CachePassword(string userId, string hashedPassword)
    {
