    public async Task ConfigurePasswordPolicyAsync(string roleName)
    {
        var role = await _roleManager.FindByNameAsync(roleName);
        if (role != null)
        {
            foreach (var user in _userManager.Users)
            {
                if(await _userManager.IsInRoleAsync(user, roleName))
                {
                    var passwordOptions = new IdentityPasswordOptions
                    {
                        RequiredLength = GetRequiredPasswordLength(role.Name),
                        RequireNonAlphanumeric = role.Name.Contains("Admin"),
                        RequireDigit = true,
                        RequireLowercase = true,
                        RequireUppercase = true
                    };

                    await _userManager.SetUserClaimAsync(user, "PasswordPolicy", passwordOptions.ToString());
                }
            }
        }
    }

    public async Task ConfigureLockoutPolicyAsync(string roleName)
    {
        var role = await _roleManager.FindByNameAsync(roleName);
        if (role != null)
        {
            foreach (var user in _userManager.Users)
            {
                if(await _userManager.IsInRoleAsync(user, roleName))
                {
                    var lockoutOptions = new IdentityUserLockoutOptions
                    {
                        AllowedForNewUsers = true,
                        MaxFailedAccessAttemptsBeforeLockout = GetMaxFailedAccessAttempts(role.Name),
                        DefaultLockoutTimeSpan = TimeSpan.FromMinutes(GetLockoutDuration(role.Name))
                    };

                    await _userManager.SetUserClaimAsync(user, "LockoutPolicy", lockoutOptions.ToString());
                }
            }
        }
    }

