@SpringBootApplication
@EnableAsync
public class ConfigLoaderApplication {

    public static void main(String[] args) {
        SpringApplication.run(ConfigLoaderApplication.class, args);
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http, ClientRegistrationRepository clientRegistrationRepository) throws Exception {
        OAuth2LoginAuthenticationFilter oAuth2LoginAuthenticationFilter = new OAuth2LoginAuthenticationFilter(clientRegistrationRepository);
        http.addFilterBefore(oAuth2LoginAuthenticationFilter, UsernamePasswordAuthenticationFilter.class);

        // Configure RBAC and authentication
        http.authorizeRequests()
            .antMatchers("/admin/**").hasRole("ADMIN")
            .anyRequest().authenticated();

        return http.build();
    }

    public static class ConfigLoader {

        private final Map<String, Function<Map<String, Object>, ?>> factoryRegistry = new ConcurrentHashMap<>();
        private final ObjectMapper yamlMapper = new ObjectMapper(new YAMLFactory());

        public CompletableFuture<Void> loadConfigFilesAsync(List<String> fileNames) {
            return CompletableFuture.allOf(fileNames.stream()
                .map(fileName -> CompletableFuture.runAsync(() -> loadConfigFile(fileName)))
                .toArray(CompletableFuture[]::new));
        }

        private void loadConfigFile(String fileName) {
            // Load and parse YAML configuration
            try {
                Map<String, Object> config = yamlMapper.readValue(new File(fileName), Map.class);
                processConfiguration(config);
            } catch (IOException e) {
                System.err.println("Error loading configuration file: " + fileName + " - " + e.getMessage());
            }
        }

        private void processConfiguration(Map<String, Object> config) {
            // Implement logic to handle configuration and detect circular dependencies
        }

        public void registerFactory(String id, Function<Map<String, Object>, ?> factoryFunction) {
            factoryRegistry.put(id, factoryFunction);
        }

        public <T> T createFromYamlString(String yamlContent, Class<T> clazz) throws IOException {
            return yamlMapper.readValue(yamlContent, clazz);
        }

        public String convertToYamlString(Object obj) throws JsonProcessingException {
            return yamlMapper.writeValueAsString(obj);
        }
    }

