<?php

// Autoload classes using Composer or custom autoloader
require 'vendor/autoload.php';

use Psr\Http\Message\ServerRequestInterface as Request;
use Psr\Http\Message\ResponseInterface as Response;
use Firebase\JWT\JWT;

class AuthSystem {
    private $db;
    private $sessionManager;

    public function __construct($db, $sessionManager) {
        $this->db = $db;
        $this->sessionManager = $sessionManager;
    }

    // Registration
    public function register(Request $request): Response {
        $data = $request->getParsedBody();

        if (!$this->validateRegistrationData($data)) {
            return new \Slim\Psr7\Response(400, [], 'Invalid registration data');
        }

        $passwordHash = password_hash(
            $data['password'],
            PASSWORD_ARGON2ID // or PASSWORD_BCRYPT
        );

        // Save user to DB
        $stmt = $this->db->prepare("INSERT INTO users (username, email, password) VALUES (?, ?, ?)");
        $stmt->execute([$data['username'], $data['email'], $passwordHash]);

        return new \Slim\Psr7\Response(201);
    }

    // Login
    public function login(Request $request): Response {
        $data = $request->getParsedBody();

        if (!$this->validateLoginData($data)) {
            return new \Slim\Psr7\Response(400, [], 'Invalid login data');
        }

        $stmt = $this->db->prepare("SELECT * FROM users WHERE email = ?");
        $stmt->execute([$data['email']]);
        $user = $stmt->fetch();

        if (!$user || !password_verify($data['password'], $user['password'])) {
            return new \Slim\Psr7\Response(401, [], 'Invalid credentials');
        }

        // Generate JWT token
        $token = $this->generateToken($user);

        return new \Slim\Psr7\Response(200, ['token' => $token]);
    }

    // Token generation for API access
    private function generateToken(array $user): string {
        $secretKey = 'your_secret_key';
        $payload = [
            'iss' => 'auth-system',
            'aud' => 'api-client',
            'iat' => time(),
            'exp' => time() + 3600,
            'sub' => $user['id']
        ];

        return JWT::encode($payload, $secretKey);
    }

    // Secure random string generator
    private function generateRandomString(int $length = 32): string {
        $characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
        $charactersLength = strlen($characters);
        $randomString = '';

        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characters[random_int(0, $charactersLength - 1)];
        }

        return $randomString;
    }

    // Validation methods
    private function validateRegistrationData(array $data): bool {
        // Implement validation logic
        return true;
    }

    private function validateLoginData(array $data): bool {
        // Implement validation logic
        return true;
    }

    // Rate limiting and caching can be implemented here or in middleware

}

