class FileLoader {
public:
    using FutureResult = std::future<std::pair<bool, std::string>>;

    static FutureResult loadAsync(const std::string& filePath) {
        return std::async(std::launch::async, &FileLoader::loadFile, filePath);
    }

private:
    static std::pair<bool, std::string> loadFile(const std::string& filePath) {
        std::ifstream file(filePath);
        if (!file.is_open()) {
            return {false, "Failed to open file"};
        }

        std::stringstream buffer;
        buffer << file.rdbuf();
        return {true, buffer.str()};
    }
