public:
    static json fetchSchemaFromAPI(const std::string& apiUrl) {
        CURL* curl;
        CURLcode res;
        std::string readBuffer;

        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            curl_easy_setopt(curl, CURLOPT_URL, apiUrl.c_str());
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);
            res = curl_easy_perform(curl);
            if(res != CURLE_OK)
                SystemLogger::logError("curl_easy_perform() failed: " + std::string(curl_easy_strerror(res)));
            curl_easy_cleanup(curl);
        }
        curl_global_cleanup();

        return json::parse(readBuffer);
    }

private:
    static size_t writeCallback(void* contents, size_t size, size_t nmemb, void* userp) {
        ((std::string*)userp)->append((char*)contents, size * nmemb);
        return size * nmemb;
    }
};

int main() {
    // Example usage
    auto futureResult = FileLoader::loadAsync("example.json");
    auto [success, content] = futureResult.get();

    if (success) {
        json j = JsonManager::fromJson(content);
        std::string jsonString = JsonManager::toJson(j);
        SystemLogger::logInfo(jsonString);
    } else {
        SystemLogger::logError(content);  // content contains the error message
    }

    return 0;
}
