import hashlib
from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor

class DistributedFileStorageManager:
    def __init__(self):
        self.nodes = {}  # Simulated nodes storage
        self.cache = {}
        self.metadata = defaultdict(list)
        self.versioning = defaultdict(lambda: defaultdict(int))
        self.executor = ThreadPoolExecutor(max_workers=10)

    def _get_node(self, filename):
        hash_value = int(hashlib.md5(filename.encode()).hexdigest(), 16)
        return hash_value % len(self.nodes) if self.nodes else None

    def uploadFile(self, filename, fileContent):
        node_index = self._get_node(filename)

        # Simulate chunk distribution
        chunks = [fileContent[i:i+1024] for i in range(0, len(fileContent), 1024)]

        if node_index not in self.nodes:
            self.nodes[node_index] = {}

        for i, chunk in enumerate(chunks):
            node_file_name = f"{filename}.part{i}"
            self.nodes[node_index][node_file_name] = chunk

        # Update metadata and version
        self.metadata[filename].append({'version': self.versioning[filename]['current'] + 1})
        self.versioning[filename]['current'] += 1

    def downloadFile(self, filename):
        if filename in self.cache:
            return self.cache[filename]

        file_content = []
        for node_index, files in self.nodes.items():
            for key in files.keys():
                if key.startswith(filename + ".part"):
                    file_content.append(files[key])

        full_content = b"".join(file_content)

        # Update cache
        self.cache[filename] = full_content

        return full_content

    def listFiles(self, page=1, per_page=10):
        all_files = set()
        for files in self.nodes.values():
            for file in files.keys():
                original_filename = file.split(".part")[0]
                all_files.add(original_filename)

        # Pagination logic
        start = (page - 1) * per_page
        end = page * per_page
        return list(all_files)[start:end]

    def deleteFile(self, filename):
        for node_index in self.nodes.keys():
            files_to_delete = [key for key in self.nodes[node_index] if key.startswith(filename + ".part")]

            for file in files_to_delete:
                del self.nodes[node_index][file]

            # Notify other nodes (simulated)
            print(f"Node {node_index} notified of deletion of {filename}")

    def renameFile(self, oldFilename, newFilename):
        if any(file.startswith(newFilename + ".part") for node_files in self.nodes.values() for file in node_files.keys()):
            raise ValueError("New filename already exists.")

        # Update nodes
        for node_files in self.nodes.values():
            for key in list(node_files.keys()):
                if key.startswith(oldFilename + ".part"):
                    new_key = key.replace(oldFilename, newFilename)
                    node_files[new_key] = node_files.pop(key)

        # Update metadata and version
        self.metadata[newFilename] = self.metadata.pop(oldFilename)
        self.versioning[newFilename]['current'] = self.versioning[oldFilename]['current']

    def _simulate_node_failure(self):
        if self.nodes:
            failed_node_index = next(iter(self.nodes))
            del self.nodes[failed_node_index]
            print(f"Simulated failure of node {failed_node_index}")

# Example usage
storage_manager = DistributedFileStorageManager()
storage_manager.uploadFile("example.txt", b"Some large file content here..." * 1000)
print(storage_manager.downloadFile("example.txt"))
print(storage_manager.listFiles())
storage_manager.renameFile("example.txt", "renamed_example.txt")
storage_manager.deleteFile("renamed_example.txt")
```

