import threading
from abc import ABC, abstractmethod
import boto3
from google.cloud import storage as gcs
from azure.storage.blob import BlobServiceClient
import time

class StorageProvider(ABC):
    @abstractmethod
    def upload_file(self, bucket_name, file_path, destination_path):
        pass

    @abstractmethod
    def download_file(self, bucket_name, source_path, local_path):
        pass


class S3StorageProvider(StorageProvider):
    def __init__(self, access_key, secret_key):
        self.s3_client = boto3.client('s3', aws_access_key_id=access_key, aws_secret_access_key=secret_key)

    def upload_file(self, bucket_name, file_path, destination_path):
        try:
            self.s3_client.upload_file(file_path, bucket_name, destination_path)
            return True
        except Exception as e:
            print(f"S3 Upload Error: {e}")
            return False

    def download_file(self, bucket_name, source_path, local_path):
        try:
            self.s3_client.download_file(bucket_name, source_path, local_path)
            return True
        except Exception as e:
            print(f"S3 Download Error: {e}")
            return False


class GCSStorageProvider(StorageProvider):
    def __init__(self, credentials):
        self.gcs_client = gcs.Client(credentials=credentials)

    def upload_file(self, bucket_name, file_path, destination_path):
        try:
            bucket = self.gcs_client.get_bucket(bucket_name)
            blob = bucket.blob(destination_path)
            blob.upload_from_filename(file_path)
            return True
        except Exception as e:
            print(f"GCS Upload Error: {e}")
            return False

    def download_file(self, bucket_name, source_path, local_path):
        try:
            bucket = self.gcs_client.get_bucket(bucket_name)
            blob = bucket.blob(source_path)
            blob.download_to_filename(local_path)
            return True
        except Exception as e:
            print(f"GCS Download Error: {e}")
            return False


class AzureStorageProvider(StorageProvider):
    def __init__(self, connection_string):
        self.blob_service_client = BlobServiceClient.from_connection_string(connection_string)

    def upload_file(self, bucket_name, file_path, destination_path):
        try:
            container_client = self.blob_service_client.get_container_client(bucket_name)
            blob_client = container_client.get_blob_client(destination_path)
            with open(file_path, "rb") as data:
                blob_client.upload_blob(data)
            return True
        except Exception as e:
            print(f"Azure Upload Error: {e}")
            return False

    def download_file(self, bucket_name, source_path, local_path):
        try:
            container_client = self.blob_service_client.get_container_client(bucket_name)
            blob_client = container_client.get_blob_client(source_path)
            with open(local_path, "wb") as data:
                data.write(blob_client.download_blob().readall())
            return True
        except Exception as e:
            print(f"Azure Download Error: {e}")
            return False


class MultiProviderCache:
    def __init__(self):
        self.cache = {}
        self.lock = threading.Lock()

    def get_metadata(self, key):
        with self.lock:
            if key in self.cache and not self._is_expired(self.cache[key]):
                return self.cache[key]['data']
            return None

    def set_metadata(self, key, data, ttl=300):
        expiry_time = time.time() + ttl
        with self.lock:
            self.cache[key] = {'data': data, 'expiry': expiry_time}

    def _is_expired(self, cache_entry):
        return time.time() > cache_entry['expiry']


class FileStorageManager:
    def __init__(self, providers, cache_ttl=300):
        self.providers = providers
        self.cache = MultiProviderCache()
        self.cache_ttl = cache_ttl

    def upload_file(self, bucket_name, file_path, destination_path):
        for provider in self.providers:
            if provider.upload_file(bucket_name, file_path, destination_path):
                self.cache.set_metadata(destination_path, {'bucket': bucket_name}, self.cache_ttl)
                return True
        return False

    def download_file(self, bucket_name, source_path, local_path):
        metadata = self.cache.get_metadata(source_path)
        if metadata:
            bucket_name = metadata['bucket']
        for provider in self.providers:
            if provider.download_file(bucket_name, source_path, local_path):
                return True
        return False

# Example usage:
s3_provider = S3StorageProvider('aws_access_key', 'aws_secret_key')
gcs_provider = GCSStorageProvider('path_to_gcs_credentials.json')
azure_provider = AzureStorageProvider('connection_string')

manager = FileStorageManager([s3_provider, gcs_provider, azure_provider])

# Upload a file
success = manager.upload_file('my_bucket', '/local/path/to/file.txt', 'remote/path/to/file.txt')
if success:
    print("File uploaded successfully")

# Download a file
success = manager.download_file('my_bucket', 'remote/path/to/file.txt', '/local/path/to/downloaded_file.txt')
if success:
    print("File downloaded successfully")
``` 

