```csharp
using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.IO;
using System.Threading.Tasks;
using System.Xml.Linq;
using System.Xml.Schema;

public class XmlDocumentManager : IDisposable
{
    private readonly string _externalDataSourceUrl;
    private readonly XmlSchemaSet _schemas;
    private readonly ConcurrentDictionary<string, Lazy<Task<XDocument>>> _cache;
    private const int CacheDurationSeconds = 300; // Example cache duration

    public XmlDocumentManager(string externalDataSourceUrl, string xsdFilePath)
    {
        _externalDataSourceUrl = externalDataSourceUrl;
        _schemas = new XmlSchemaSet();
        _schemas.Add("", File.ReadAllText(xsdFilePath));
        _cache = new ConcurrentDictionary<string, Lazy<Task<XDocument>>>();
    }

    public async Task<XDocument> GetXmlAsync()
    {
        return await _cache.GetOrAdd(_externalDataSourceUrl,
            _ => new Lazy<Task<XDocument>>(async () =>
            {
                using (var client = new System.Net.Http.HttpClient())
                {
                    var response = await client.GetAsync(_externalDataSourceUrl);
                    response.EnsureSuccessStatusCode();
                    var content = await response.Content.ReadAsStringAsync();

                    var document = XDocument.Parse(content);
                    ValidateXml(document);

                    return document;
                }
            })).Value;
    }

    public async Task<XNode> ExecuteXPathQueryAsync(string xpath)
    {
        ValidateXPath(xpath);

        var watch = Stopwatch.StartNew();

        try
        {
            var document = await GetXmlAsync();
            var result = document.XPathSelectElements(xpath).FirstOrDefault() ?? 
                         document.XPathSelectSingleton(xpath);

            logExecution(watch.Elapsed, true, null);
            return result;
        }
        catch (Exception ex)
        {
            logExecution(watch.Elapsed, false, ex.Message);
            throw new InvalidOperationException("XPath execution failed.", ex);
        }
    }

    private void ValidateXml(XDocument document)
    {
        var validationErrors = new List<string>();

        document.Validate(_schemas, (o, e) =>
        {
            if (e.Severity == XmlSeverityType.Error || e.Severity == XmlSeverityType.Warning)
                validationErrors.Add(e.Message);
        });

        if (validationErrors.Count > 0)
        {
            throw new XmlSchemaValidationException(string.Join(Environment.NewLine, validationErrors));
        }
    }

    private void ValidateXPath(string xpath)
    {
        // Basic syntax check for XPath query
        try
        {
            XDocument dummyDoc = new XDocument();
            var result = dummyDoc.XPathSelectElements(xpath);
            if (result == null) throw new ArgumentException("Invalid XPath expression.");
        }
        catch (Exception)
        {
            throw new ArgumentException("Invalid XPath expression.", nameof(xpath));
        }
    }

    private void logExecution(TimeSpan executionTime, bool success, string errorMessage)
    {
        // Log to a file or monitoring system
        Console.WriteLine($"XPath Execution Time: {executionTime}, Success: {success}, Error Message: {errorMessage}");
    }

    public void Dispose()
    {
        _cache.Clear();
        _schemas.Dispose();
    }
}

public static class XPathExtensions
{
    public static XNode XPathSelectSingleton(this XContainer container, string xpath)
    {
        var nodes = container.XPathSelectElements(xpath).ToArray();
        return nodes.Length > 0 ? nodes[0] : null;
    }
}
```

