### Step 3: Node.js Application (app.js)

Load and execute modules dynamically:

```javascript
const fs = require('fs-extra');
const chalk = require('chalk');
const path = require('path');

// Load configuration
const config = JSON.parse(fs.readFileSync('./config.json', 'utf-8'));
const { modules, concurrencyLevel, dependencyGraph } = config;

let loadedModules = new Set();

async function loadModule(moduleName) {
  if (loadedModules.has(moduleName)) return;

  const dependencies = dependencyGraph[moduleName] || [];
  for (const dep of dependencies) {
    await loadModule(dep);
  }

  try {
    require(path.resolve(__dirname, `${moduleName}.js`));
    loadedModules.add(moduleName);
    console.log(chalk.green(`Loaded ${moduleName}`));
  } catch (error) {
    console.error(chalk.red(`Error loading ${moduleName}: ${error.message}`));
  }
}

async function executeModules() {
  const semaphore = new ConcurrencyLimiter(concurrencyLevel);

  for (const module of modules) {
    await semaphore.run(loadModule, module);
  }

  console.log(chalk.blue('All modules loaded successfully.'));
}

class ConcurrencyLimiter {
  constructor(limit) {
    this.limit = limit;
    this.currentlyRunning = 0;
    this.queue = [];
  }

  async run(fn, ...args) {
    if (this.currentlyRunning >= this.limit) {
      await new Promise(resolve => this.queue.push({ resolve, fn, args }));
    }

    this.execute();
  }

  execute() {
    if (this.queue.length > 0 && this.currentlyRunning < this.limit) {
      const { resolve, fn, args } = this.queue.shift();
      this.currentlyRunning++;

      Promise.resolve(fn(...args)).then(() => {
        this.currentlyRunning--;
        resolve();
        this.execute();
      }).catch(error => {
        console.error(chalk.red(`Error: ${error.message}`));
        this.currentlyRunning--;
        this.execute();
      });
    }
  }
}

executeModules().catch(err => console.error(chalk.red(err)));
```

### Step 4: C Function for DNS Resolution (dns.c)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_IP_LENGTH 16

int resolve_dns(const char *hostname, unsigned char *ip_array) {
    struct sockaddr_in addr;
    int result = gethostbyname_r(hostname, &addr, ip_array, sizeof(struct in_addr), NULL, NULL, 0);

    if (result == 0) {
        inet_ntop(AF_INET, &(addr.sin_addr), (char *)ip_array, MAX_IP_LENGTH);
        return 1;
    } else {
        fprintf(stderr, "DNS resolution failed for %s\n", hostname);
        return -1;
    }
}
```

