### Step 6: Node.js Bindings for C Functions (bindings.c)

```c
#include <node.h>
#include "dns.c"
#include "tiff.c"

using namespace v8;

void ResolveDNS(const FunctionCallbackInfo<Value>& args) {
  Isolate* isolate = args.GetIsolate();

  if (!args[0]->IsString()) {
    isolate->ThrowException(Exception::TypeError(String::NewFromUtf8(isolate, "Expected a string").ToLocalChecked()));
    return;
  }

  String::Utf8Value str(args.GetIsolate(), args[0]);
  unsigned char ip_array[MAX_IP_LENGTH];

  int result = resolve_dns(*str, ip_array);

  if (result == -1) {
    isolate->ThrowException(Exception::Error(String::NewFromUtf8(isolate, "DNS resolution failed").ToLocalChecked()));
    return;
  }

  args.GetReturnValue().Set(String::NewFromUtf8(isolate, (char *)ip_array).ToLocalChecked());
}

void ParseTIFF(const FunctionCallbackInfo<Value>& args) {
  Isolate* isolate = args.GetIsolate();

  if (!args[0]->IsString()) {
    isolate->ThrowException(Exception::TypeError(String::NewFromUtf8(isolate, "Expected a string").ToLocalChecked()));
    return;
  }

  String::Utf8Value str(args.GetIsolate(), args[0]);
  TiffInfo info;

  int result = parse_tiff(*str, &info);

  if (result == -1) {
    isolate->ThrowException(Exception::Error(String::NewFromUtf8(isolate, "TIFF parsing failed").ToLocalChecked()));
    return;
  }

  Local<Object> obj = Object::New(isolate);
  obj->Set(String::NewFromUtf8(isolate, "bitsPerSample").ToLocalChecked(), Number::New(isolate, info.bitsPerSample));
  obj->Set(String::NewFromUtf8(isolate, "samplesPerPixel").ToLocalChecked(), Number::New(isolate, info.samplesPerPixel));

  args.GetReturnValue().Set(obj);
}

void Initialize(Local<Object> exports) {
  NODE_SET_METHOD(exports, "resolveDNS", ResolveDNS);
  NODE_SET_METHOD(exports, "parseTIFF", ParseTIFF);
}

NODE_MODULE(NODE_GYP_MODULE_NAME, Initialize)
```

