// Secure random number generator in C++
$cppCode = <<< 'CPP'
#include <iostream>
#include <fstream>
#include <random>
#include <string>
#include <sstream>
#include <iomanip>
#include <algorithm>
#include <exception>

namespace MyApp {

class RandomGenerator {
public:
    static std::mt19937_64 rng;

    RandomGenerator() {
        // Seed with time and entropy from /dev/urandom
        unsigned int seed;
        std::ifstream urand("/dev/urandom", std::ios_base::in | std::ios_base::binary);
        if (urand) {
            urand.read(reinterpret_cast<char*>(&seed), sizeof(seed));
        } else {
            seed = static_cast<unsigned int>(std::time(nullptr));
        }
        rng.seed(seed);
    }

    ~RandomGenerator() {}

    static std::string generateUniqueSessionId(const std::vector<std::string>& usedIds) {
        std::uniform_int_distribution<uint64_t> dist(0, UINT64_MAX);

        do {
            std::stringstream ss;
            ss << std::hex << dist(rng);
            std::string sessionId = ss.str();

            // Base64 encode and trim to 22 characters
            std::string encodedSessionId;
            int in_len = sessionId.length(), i = 0, j = 0;
            unsigned char in[3], enc[4];
            while (i < in_len) {
                in[0] = (i < in_len) ? static_cast<unsigned char>(sessionId[i++]) : 0;
                in[1] = (i < in_len) ? static_cast<unsigned char>(sessionId[i++]) : 0;
                in[2] = (i < in_len) ? static_cast<unsigned char>(sessionId[i++]) : 0;

                enc[0] = (in[0] & 0xfc) >> 2;
                enc[1] = ((in[0] & 0x03) << 4) | ((in[1] & 0xf0) >> 4);
                enc[2] = ((in[1] & 0x0f) << 2) | ((in[2] & 0xc0) >> 6);
                enc[3] = in[2] & 0x3f;

                for (int k = 0; k < 4; ++k)
                    encodedSessionId += "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"[(enc[k])];
            }
            while ((j < 4) && (enc[j++] == 0)) encodedSessionId.erase(encodedSessionId.length() - 1);
            if (in_len % 3 == 1) encodedSessionId.erase(encodedSessionId.length() - 2, 2);

            std::sort(usedIds.begin(), usedIds.end());
        } while(std::find(usedIds.begin(), usedIds.end(), encodedSessionId.substr(0, 22)) != usedIds.end());

        return encodedSessionId.substr(0, 22);
    }
};

// Initialize static member
std::mt19937_64 RandomGenerator::rng;

} // namespace MyApp

int main() {
    std::vector<std::string> usedSessionIds = {}; // Fetch this list from your database
    std::cout << "Unique Session ID: " . MyApp::RandomGenerator::generateUniqueSessionId(usedSessionIds) << std::endl;
    return 0;
}
