function processFileWithPython($filePath) {
    $pythonCode = <<< 'PYTHON'
import sys

def read_sort_extract_sequence_number(file_path):
    try:
        with open(file_path, 'r') as f:
            lines = f.readlines()

        # Sort the lines and extract sequence number from last line
        lines.sort()
        last_line = lines[-1].strip()
        parts = last_line.split()

        if len(parts) < 2 or not parts[1].isdigit():
            raise ValueError("Invalid format in last line")

        return int(parts[1])
    except Exception as e:
        print(f"Error: {str(e)}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python script.py <file_path>", file=sys.stderr)
        sys.exit(1)

    sequence_number = read_sort_extract_sequence_number(sys.argv[1])
    print(sequence_number)
PYTHON;

    // Write Python code to a file
    $pythonScriptPath = __DIR__ . '/processFile.py';
    file_put_contents($pythonScriptPath, $pythonCode);

    // Execute the Python script and capture output
    exec("python3 " . escapeshellarg($pythonScriptPath) . " " . escapeshellarg($filePath), $output, $returnVar);

    if ($returnVar !== 0) {
        throw new Exception("Error executing Python script: " . implode("\n", $output));
    }

    return intval(array_shift($output));
}

