using System.Threading.Tasks;

public class SqlExecutor
{
    private readonly string _connectionString;
    private readonly Dictionary<string, Func<IDbConnection>> _providerFactories;
    private readonly int _maxOpenConnections;
    private readonly SemaphoreSlim _connectionSemaphore;
    private readonly ILogger _logger;
    private readonly ICryptoProvider _cryptoProvider;

    public SqlExecutor(string connectionString, 
                       Dictionary<string, Func<IDbConnection>> providerFactories,
                       int maxOpenConnections,
                       ILogger logger,
                       ICryptoProvider cryptoProvider)
    {
        _connectionString = connectionString ?? throw new ArgumentNullException(nameof(connectionString));
        _providerFactories = providerFactories ?? throw new ArgumentNullException(nameof(providerFactories));
        _maxOpenConnections = maxOpenConnections;
        _connectionSemaphore = new SemaphoreSlim(_maxOpenConnections);
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _cryptoProvider = cryptoProvider ?? throw new ArgumentNullException(nameof(cryptoProvider));
    }

    public async Task<IDataReader> ExecuteSqlQueryAsync(string providerKey, string commandTemplate, List<string> values)
    {
        if (!_providerFactories.ContainsKey(providerKey))
            throw new ArgumentException("Invalid database provider key.");

        await _connectionSemaphore.WaitAsync().ConfigureAwait(false);
        try
        {
            using (var connection = CreateDbConnection(providerKey))
            {
                await connection.OpenAsync().ConfigureAwait(false);

                var command = BuildCommand(connection, commandTemplate, values);
                return await ExecuteWithRetryAsync(command).ConfigureAwait(false);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error executing SQL query.");
            throw;
        }
        finally
        {
            _connectionSemaphore.Release();
        }
    }

    private IDbConnection CreateDbConnection(string providerKey) 
        => _providerFactories[providerKey]();

    private IDbCommand BuildCommand(IDbConnection connection, string commandTemplate, List<string> values)
    {
        var command = connection.CreateCommand();
        command.CommandText = commandTemplate;
        for (int i = 0; i < values.Count; i++)
        {
            var parameter = command.CreateParameter();
            parameter.ParameterName = $"@p{i}";
            parameter.Value = values[i];
            command.Parameters.Add(parameter);
        }
        return command;
    }

    private async Task<IDataReader> ExecuteWithRetryAsync(IDbCommand command)
    {
        int retryCount = 0;
        const int maxRetries = 3;

        while (retryCount < maxRetries)
        {
            try
            {
                return await command.ExecuteReaderAsync();
            }
            catch (TransientException ex) when (++retryCount <= maxRetries)
            {
                _logger.LogWarning(ex, "Transient error occurred. Retrying...");
                await Task.Delay(1000 * retryCount);
            }
        }

        throw new Exception("Max retries exceeded.");
    }

    public IntPtr GetCipherPointer(string cipherMode)
    {
        var cipher = _cryptoProvider.GetCipher(cipherMode);
        return cipher != null ? (IntPtr)cipher : IntPtr.Zero;
    }

    // Mock implementations for interfaces and classes used
    private interface ILogger 
    {
        void LogError(Exception ex, string message);
        void LogWarning(Exception ex, string message);
    }

    private interface ICryptoProvider 
    {
        Cipher GetCipher(string cipherMode);
    }

    private class TransientException : Exception { }

    public static async Task Main()
    {
        var logger = new ConsoleLogger();
        var cryptoProvider = new MockCryptoProvider();

        var providerFactories = new Dictionary<string, Func<IDbConnection>>
