<?php

require 'vendor/autoload.php';

use Predis\Client as RedisClient;
use Memcached;

class SecureTokenManager {
    private $redis;
    private $memcached;
    private $rateLimitConfig = [
        'tokenGeneration' => 10,
        'passwordHashing' => 5,
        'windowSeconds'   => 60
    ];

    public function __construct() {
        $this->redis = new RedisClient(['scheme' => 'tcp', 'host' => '127.0.0.1']);
        $this->memcached = new Memcached();
        $this->memcached->addServer('localhost', 11211);
    }

    private function rateLimit($key) {
        $currentCount = (int)$this->redis->get($key) ?: 0;

        if ($currentCount >= $this->rateLimitConfig['tokenGeneration']) {
            throw new \Exception("Rate limit exceeded for {$key}.");
        }

        $this->redis->incr($key);
        $this->redis->expire($key, $this->rateLimitConfig['windowSeconds']);
    }

    private function generateRandomString($length, $charSet) {
        $output = '';
        $maxIndex = strlen($charSet) - 1;

        for ($i = 0; $i < $length; ++$i) {
            $output .= $charSet[random_int(0, $maxIndex)];
        }

        return $output;
    }

    public function createToken($length, $charset, $identifier) {
        try {
            $this->rateLimit('token_generation_' . $identifier);

            $token = $this->generateRandomString($length, $charset);
            $hashedToken = hash('sha256', $token); // Example hashing

            $this->redis->set("token:{$identifier}", $token, 3600); // Store for an hour
            return $hashedToken;
        } catch (\Exception $e) {
            error_log($e->getMessage());
            throw new \Exception('Failed to generate token.');
        }
    }

    public function verifyToken($identifier, $hashedToken) {
        try {
            $storedToken = $this->redis->get("token:{$identifier}");
            if (!$storedToken) {
                return false;
            }

            return hash('sha256', $storedToken) === $hashedToken;
        } catch (\Exception $e) {
            error_log($e->getMessage());
            return false;
        }
    }

    public function hashPassword($password, $algorithm = 'bcrypt') {
        try {
            $this->rateLimit('password_hashing_' . session_id());

            if (!in_array($algorithm, ['bcrypt', 'argon2id'])) {
                throw new \Exception("Unsupported algorithm: {$algorithm}");
            }

            $hashOptions = [
                'cost' => 12
            ];

            switch ($algorithm) {
                case 'bcrypt':
                    $hashedPassword = password_hash($password, PASSWORD_BCRYPT, $hashOptions);
                    break;
                case 'argon2id':
                    $hashedPassword = password_hash($password, PASSWORD_ARGON2ID, [
                        'memory_cost' => 1<<16,
                        'time_cost'   => 4,
                        'threads'     => 2
                    ]);
                    break;
            }

            return $hashedPassword;
        } catch (\Exception $e) {
            error_log($e->getMessage());
            throw new \Exception('Failed to hash password.');
        }
    }

    public function verifyPassword($password, $storedHash) {
        try {
            return password_verify($password, $storedHash);
        } catch (\Exception $e) {
            error_log($e->getMessage());
            return false;
        }
    }

    private function cacheTokenOrPassword($key, $value, $expiry = 3600) {
        $this->memcached->set($key, $value, $expiry);
    }

    public function retrieveFromCache($key) {
        return $this->memcached->get($key);
    }
}

// Usage
$tokenManager = new SecureTokenManager();
try {
    $tokenHash = $tokenManager->createToken(32, '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ', uniqid('auth_', true));

    // Assume we retrieve the token hash from elsewhere in a real-world scenario.
    if ($tokenManager->verifyToken(uniqid('auth_', true), $tokenHash)) {
        echo "Token is valid!";
    } else {
        echo "Invalid token.";
    }

    $hashedPassword = $tokenManager->hashPassword("userPassword123", 'bcrypt');
    if ($tokenManager->verifyPassword("userPassword123", $hashedPassword)) {
        echo "Password matches!";
    } else {
        echo "Password does not match.";
    }
} catch (\Exception $e) {
    error_log($e->getMessage());
}
