class UserAuthentication {
private:
    struct UserData {
        std::string passwordHash;
        int failedAttempts;
        std::chrono::system_clock::time_point lastFailedAttemptTime;
    };

    std::unordered_map<std::string, UserData> userDatabase;
    std::mutex mtx;
    const size_t maxAttempts = 3;
    const std::chrono::minutes attemptWindow = std::chrono::minutes(5);

public:
    void initializeOctree(size_t featureSize, size_t numLeafNodes, size_t dataCapacity) {
        // Implement octree initialization logic here
        if (featureSize == 0 || numLeafNodes == 0 || dataCapacity == 0) {
            throw std::invalid_argument("Invalid parameters for octree initialization.");
        }
        // Allocate memory and update capacity based on the inputs
    }

    void initializeOctreeWithSeed(size_t featureSize, size_t numLeafNodes, size_t dataCapacity, int seed, SeedCallback callback = nullptr) {
        std::lock_guard<std::mutex> lock(mtx);
        if (callback) {
            callback(seed);
        }

        // Use the given seed for reproducibility
        srand(seed);

        initializeOctree(featureSize, numLeafNodes, dataCapacity);
    }

    bool authenticateUser(const std::string& username, const std::string& password) {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = userDatabase.find(username);
        if (it == userDatabase.end()) {
            return false; // Username not found
        }

        UserData& userData = it->second;
        auto currentTime = std::chrono::system_clock::now();

        if (userData.failedAttempts >= maxAttempts &&
            currentTime - userData.lastFailedAttemptTime < attemptWindow) {
            throw RateLimitExceededException();
        }

        bool isAuthenticated = verifyPassword(password, userData.passwordHash);
        if (!isAuthenticated) {
            ++userData.failedAttempts;
            userData.lastFailedAttemptTime = currentTime;
            return false; // Password incorrect
        } else {
            userData.failedAttempts = 0; // Reset on successful authentication
            return true;
        }
    }

    bool changeUserPassword(const std::string& username, const std::string& oldPassword, const std::string& newPassword) {
        if (authenticateUser(username, oldPassword)) {
            setPasswordHash(username, hashPassword(newPassword));
            return true;
        }
        return false; // Authentication failed
    }

private:
