// Global constants for cooldown periods.
const int COOLDOWN_ATTACK_1 = 5;
const int COOLDOWN_ATTACK_2 = 7;
const int COOLDOWN_ATTACK_3 = 10;

// Maximum usage count per attack in a session.
const int MAX_ATTACK_USAGE = 100;

// Energy reduction per attack type.
const int ENERGY_REDUCTION_ATTACK_1 = 10;
const int ENERGY_REDUCTION_ATTACK_2 = 15;
const int ENERGY_REDUCTION_ATTACK_3 = 20;

// Global variable to track the number of uses for each attack.
int usage_count[3] = {0};

// Global energy level for the character.
int current_energy = 100;

// Mutex for thread-safe access to shared resources.
std::mutex mtx;

void perform_attack() {
    std::lock_guard<std::mutex> lock(mtx); // Ensure thread safety.

    if (current_energy < 0) {
        current_energy = 100; // Reset energy level if it goes below zero.
    }

    int attack_number;

    do {
        attack_number = rand() % 3 + 1; // Randomly select an attack between 1 and 3.
    } while (usage_count[attack_number - 1] >= MAX_ATTACK_USAGE); // Ensure we haven't reached the max usage.

    if (++usage_count[attack_number - 1] > MAX_ATTACK_USAGE) {
        std::cerr << "Warning: Attack " << attack_number << " has exceeded its maximum allowed uses." << std::endl;
        return; // Prevent further use of this attack.
    }

    switch (attack_number) {
        case 1:
            current_energy -= ENERGY_REDUCTION_ATTACK_1;
            std::cout << "Selected Attack 1. Cooldown: " << COOLDOWN_ATTACK_1 << " seconds." << std::endl;
            break;
        case 2:
            current_energy -= ENERGY_REDUCTION_ATTACK_2;
            std::cout << "Selected Attack 2. Cooldown: " << COOLDOWN_ATTACK_2 << " seconds." << std::endl;
            break;
        case 3:
            current_energy -= ENERGY_REDUCTION_ATTACK_3;
            std::cout << "Selected Attack 3. Cooldown: " << COOLDOWN_ATTACK_3 << " seconds." << std::endl;
            break;
    }

    // Clamp energy level to the cap of 100.
    if (current_energy < 0) {
        current_energy = 0;
    }
}

// Unit tests for perform_attack function.
void test_perform_attack() {
    srand(static_cast<unsigned>(time(0))); // Seed random number generator.

    // Test multiple calls and edge cases
    for (int i = 0; i < MAX_ATTACK_USAGE * 3 + 10; ++i) {
        perform_attack();
    }

    // Expected: Each attack count should be <= 100.
    std::cout << "Usage Count Attack 1: " << usage_count[0] << "\n";
    std::cout << "Usage Count Attack 2: " << usage_count[1] << "\n";
    std::cout << "Usage Count Attack 3: " << usage_count[2] << "\n";

    // Test energy level bounds.
    if (current_energy > 100) {
        std::cerr << "Error: Energy level exceeds cap of 100." << std::endl;
    }
}

int main() {
    test_perform_attack();
    return 0;
}
