```csharp
using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Caching.Memory;
using Serilog;

public class HashService
{
    private static readonly MemoryCache _cache = new MemoryCache(new MemoryCacheOptions());
    private static readonly object _lockObject = new object();

    // Configure Serilog in your startup or entry point
    public HashService()
    {
        Log.Logger = new LoggerConfiguration()
            .WriteTo.Console()
            .CreateLogger();
    }

    public string ComputeSha256Hash(string input)
    {
        if (string.IsNullOrEmpty(input))
        {
            Log.Error("Input string is null or empty.");
            return null;
        }

        try
        {
            // Check cache first
            var cachedHash = GetCachedHash(input);
            if (!string.IsNullOrEmpty(cachedHash))
            {
                return cachedHash;
            }

            using (SHA256 sha256 = SHA256.Create())
            {
                byte[] bytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
                string hashString = BitConverter.ToString(bytes).Replace("-", "").ToLowerInvariant();

                // Store in cache
                SetCachedHash(input, hashString);

                return hashString;
            }
        }
        catch (Exception ex)
        {
            Log.Error(ex, "Error computing SHA-256 hash for input: {Input}", input);
            throw;  // Re-throw exception after logging it
        }
    }

    private string GetCachedHash(string input)
    {
        lock (_lockObject)
        {
            return _cache.Get<string>(input);
        }
    }

    private void SetCachedHash(string input, string hash)
    {
        lock (_lockObject)
        {
            _cache.Set(input, hash, TimeSpan.FromMinutes(5));  // Cache for 5 minutes
        }
    }
}
