#include <errno.h>

#define MAX_LINE_LENGTH 1024
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARNING 2
#define LOG_LEVEL_ERROR 3

typedef struct {
    char *filename;
    FILE *input_file;
    FILE *output_file;
} FileContext;

typedef struct {
    int thread_id;
    FileContext *file_context;
} ThreadData;

void log_message(int level, const char* message) {
    time_t now = time(NULL);
    printf("[%ld] ", (long)now);
    if(level == LOG_LEVEL_INFO) {
        printf("[INFO] ");
    } else if(level == LOG_LEVEL_WARNING) {
        printf("[WARNING] ");
    } else if(level == LOG_LEVEL_ERROR) {
        printf("[ERROR] ");
    }
    printf("%s\n", message);
}

void *process_file(void *arg) {
    ThreadData *data = (ThreadData *)arg;
    char line[MAX_LINE_LENGTH];
    double numbers[10];  // Assuming max 10 floating-point values per line
    int num_count;

    while(fgets(line, sizeof(line), data->file_context->input_file)) {
        char *token = strtok(line, " \t\n");
        num_count = 0;
        while(token != NULL && num_count < 10) {
            char *endptr;
            double value = strtod(token, &endptr);
            if(*endptr == '\0') { // Valid number
                numbers[num_count++] = value;
            } else if(strspn(token, "0123456789.-") != strlen(token)) {
                log_message(LOG_LEVEL_WARNING, "Non-numeric value detected in line.");
                break;  // Skip this line
            }
            token = strtok(NULL, " \t\n");
        }

        if(num_count >= 3) {  // We have at least three numbers to process
            double average = (numbers[num_count - 1] + numbers[num_count - 2] + numbers[num_count - 3]) / 3.0;
            fprintf(data->file_context->output_file, "%f,", average);
        }
    }

    fclose(data->file_context->input_file);
    fclose(data->file_context->output_file);
    return NULL;
}

void *thread_function(void *arg) {
    ThreadData *data = (ThreadData *)arg;
    log_message(LOG_LEVEL_INFO, "Processing file.");
    process_file(arg);
    return NULL;
}

void handle_signal(int signal) {
    // Implement graceful shutdown or checkpoint saving if necessary
    log_message(LOG_LEVEL_WARNING, "Signal received. Performing cleanup.");
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    if(argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int thread_count = sysconf(_SC_NPROCESSORS_ONLN);
    pthread_t threads[thread_count];
    ThreadData thread_data[thread_count];

    signal(SIGINT, handle_signal);

    for(int i = 1; i < argc && i <= thread_count; ++i) {
        FileContext *file_context = malloc(sizeof(FileContext));
        if(!(file_context->input_file = fopen(argv[i], "r"))) {
            log_message(LOG_LEVEL_ERROR, "Failed to open input file.");
            free(file_context);
            continue;
        }

        char output_filename[256];
        snprintf(output_filename, sizeof(output_filename), "%s_out.txt", argv[i]);

        if(!(file_context->output_file = fopen(output_filename, "w"))) {
            log_message(LOG_LEVEL_ERROR, "Failed to open output file.");
            fclose(file_context->input_file);
            free(file_context);
            continue;
        }

        thread_data[0].thread_id = 0;
        thread_data[0].file_context = file_context;

        if(pthread_create(&threads[0], NULL, thread_function, (void*)&thread_data[0])) {
            log_message(LOG_LEVEL_ERROR, "Failed to create thread.");
            fclose(file_context->input_file);
            fclose(file_context->output_file);
            free(file_context);
        }
    }

    for(int i = 0; i < thread_count && i < argc - 1; ++i) {
        pthread_join(threads[i], NULL);
    }

    log_message(LOG_LEVEL_INFO, "All files processed.");
    return EXIT_SUCCESS;
}
