```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <dirent.h>
#include <zlib.h>
#include <sys/types.h>
#include <sys/stat.h>

#define MAX_THREADS 10

typedef struct {
    char *input_file;
    char *output_file;
    char *rules;
    char *log_dir;
    char *service_url;
} ProgramArgs;

typedef struct {
    pthread_t thread_id;
    char *file_path;
} LogFileTask;

// Forward declarations
void process_log_file(ProgramArgs *args, const char *file_path);
double calculate_average_of_last_two_numerical_fields(const char *line);
void log_progress_and_errors(const char *message);
int compress_output(const char *input_file, const char *output_file);

// Thread function to process a single log file
void* log_file_thread_func(void *arg) {
    LogFileTask *task = (LogFileTask*) arg;
    ProgramArgs args; // Populate with actual arguments or shared resource
    process_log_file(&args, task->file_path);
    free(task->file_path);
    free(task);
    return NULL;
}

// Function to calculate the average of last two numerical fields in a line
double calculate_average_of_last_two_numerical_fields(const char *line) {
    // Implementation to extract and average last two numerical fields from `line`
    double num1 = 0, num2 = 0;
    int count = sscanf(line, "%*[^0123456789]%lf%*s%lf", &num1, &num2);
    if (count == 2) {
        return (num1 + num2) / 2.0;
    }
    return 0; // Return zero or handle error as needed
}

// Function to process a single log file
void process_log_file(ProgramArgs *args, const char *file_path) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        log_progress_and_errors("Error opening file.");
        return;
    }

    char buffer[1024];
    double total_average = 0.0;
    int line_count = 0;

    while (fgets(buffer, sizeof(buffer), file)) {
        total_average += calculate_average_of_last_two_numerical_fields(buffer);
        line_count++;
    }

    if (line_count > 0) {
        log_progress_and_errors("Processed file: average = ");
        printf("%f\n", total_average / line_count); // Or write to external service
    } else {
        log_progress_and_errors("No valid lines found.");
    }

    fclose(file);
}

// Function to log progress and errors (could be integrated with an external logging service)
void log_progress_and_errors(const char *message) {
    printf("%s\n", message); // Simple console output; replace as needed
}

// Function to compress the output file using zlib
int compress_output(const char *input_file, const char *output_file) {
    FILE *source = fopen(input_file, "rb");
    if (!source) return -1;

    gzFile dest = gzopen(output_file, "wb");
    if (!dest) {
        fclose(source);
        return -1;
    }

    int bytes_read;
    unsigned char buffer[1024];
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), source)) > 0) {
        if (gzwrite(dest, buffer, bytes_read) != bytes_read) {
            gzclose(dest);
            fclose(source);
            return -1;
        }
    }

    gzclose(dest);
    fclose(source);

    return 0; // Success
}

// Main function to handle program logic and concurrency
int main(int argc, char **argv) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <rules> <log_dir> <service_url>\n", argv[0]);
        return EXIT_FAILURE;
    }

    ProgramArgs args = {argv[1], argv[2], argv[3], argv[4], argv[5]};

    DIR *dir = opendir(args.log_dir);
    if (!dir) {
        log_progress_and_errors("Error opening directory.");
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    struct dirent *entry;
    while ((entry = readdir(dir)) && thread_count < MAX_THREADS) {
        if (entry->d_type == DT_REG) { // Regular file
            char *file_path = malloc(strlen(args.log_dir) + strlen(entry->d_name) + 2);
            sprintf(file_path, "%s/%s", args.log_dir, entry->d_name);

            LogFileTask *task = malloc(sizeof(LogFileTask));
            task->file_path = file_path;

            if (pthread_create(&threads[thread_count], NULL, log_file_thread_func, task) != 0) {
                free(file_path);
                free(task);
            } else {
                thread_count++;
            }
        }
    }

    closedir(dir);

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Compress output file
    if (compress_output(args.output_file, "output.gz") != 0) {
        log_progress_and_errors("Error compressing output.");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
