    'read': lambda claims: claims.get('scope') == 'read',
    'write': lambda claims: claims.get('scope') in ['write', 'admin']
}

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Rate limiting settings
RATE_LIMIT = {
    'production': ('1 per minute', 60),
    'staging': ('5 per minute', 300),
    'development': None
}.get(ENV, ('10 per minute', 600))

limiter = Limiter(
    key_func=get_remote_address,
    default_limits=[RATE_LIMIT[0]]
)

# Cache for revocation checks
@lru_cache(maxsize=1000)
def is_token_revoked(token):
    if ENV == 'development':
        return False
    # Simulate API call to revocation service
    response = simulate_api_call(REVOCATION_SERVICE_URL, token)
    return response.get('revoked', False)

# Mock function for external API calls (simulating network delay and response)
def simulate_api_call(url, payload):
    time.sleep(0.5)  # Simulate network delay
    # Mock response structure
    return {'revoked': False} if url else {}

request_counters = defaultdict(lambda: [time.time(), 0])

# Main validation function
@limiter.limit(RATE_LIMIT[1])
def validate_jwt(token_string):
    try:
        token = jwt.decode(
            token_string, JWT_SECRET, algorithms=['HS256'],
            options={"verify_exp": True}
        )

        # Check required fields
        required_fields = ['sub', 'exp', 'iat', 'aud', 'scope']
        if not all(field in token for field in required_fields):
            raise ValueError("Missing required fields")

        # Validate against revocation service
        if is_token_revoked(token_string):
            logging.warning(f"Token {token.get('jti')} has been revoked.")
            return {"status": "revoked"}

        # Custom scope validation
        token_scope = token['scope']
        for scope, rule in SCOPES_VALIDATION_RULES.items():
            if not rule(token):
                raise ValueError(f"Invalid scope: {token_scope}")

        logging.info(f"Token {token.get('jti')} is valid.")
        return {"status": "valid"}

    except jwt.ExpiredSignatureError:
        logging.error("JWT has expired")
        return {"status": "expired"}

    except jwt.InvalidTokenError as e:
        logging.error(f"Invalid token: {str(e)}")
        return {"status": "invalid"}

    except Exception as e:
        logging.error(f"Unexpected error during validation: {str(e)}")
        return {"status": "error", "message": str(e)}

# Tracking rate limit
def track_request(user_id):
    current_time, count = request_counters[user_id]
    if time.time() - current_time > RATE_LIMIT[1]:
        request_counters[user_id] = [time.time(), 1]
    else:
        if count >= int(RATE_LIMIT[0].split(' ')[0]):
            logging.warning(f"Rate limit exceeded for user {user_id}.")
            raise Exception("Rate limit exceeded.")
        request_counters[user_id][1] += 1

# Example usage
if __name__ == "__main__":
    jwt_token = '{"sub": "1234567890", "exp": 1716239028, "iat": 1716152428, "aud": "my_audience", "scope": "read"}'

    # Track request (replace 'user_id' with actual user identifier)
    track_request('user_id')

    validation_result = validate_jwt(jwt_token)
    print(validation_result)
```

