```javascript
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');
const fs = require('fs').promises;
const path = require('path');

async function loadPlugin(pluginName) {
  try {
    const pluginPath = path.join(__dirname, 'plugins', `${pluginName}.js`);
    const code = await fs.readFile(pluginPath, 'utf-8');
    return new Function(`return (${code})()`); // Dangerous in real apps due to security risks
  } catch (error) {
    throw new Error(`Failed to load plugin ${pluginName}: ${error.message}`);
  }
}

async function executeTestInWorker({ label, f, plugins }) {
  const results = [];
  for (const pluginName of plugins) {
    try {
      const pluginModule = await loadPlugin(pluginName);
      console.log(`Running test "${label}" on plugin "${pluginName}"`);

      const start = Date.now();
      await f(pluginModule);
      const duration = Date.now() - start;

      results.push({ label, pluginName, status: 'success', duration });
    } catch (error) {
      results.push({
        label,
        pluginName,
        status: 'failed',
        errorMessage: error.message || String(error),
      });
    }
  }
  return results;
}

async function executePluginTestsParallelly(label, f, plugins, numWorkers = Math.min(plugins.length, require('os').cpus().length)) {
  const workerPromises = [];
  const chunkSize = Math.ceil(plugins.length / numWorkers);

  for (let i = 0; i < numWorkers; i++) {
    const chunkPlugins = plugins.slice(i * chunkSize, (i + 1) * chunkSize);

    workerPromises.push(new Promise((resolve, reject) => {
      const worker = new Worker(__filename, { workerData: { label, f, plugins: chunkPlugins } });

      worker.on('message', resolve);
      worker.on('error', reject);
      worker.on('exit', (code) => {
        if (code !== 0)
          reject(new Error(`Worker stopped with exit code ${code}`));
      });
    }));
  }

  const results = await Promise.all(workerPromises);

  // Flatten the array of results
  return results.flat();
}

if (!isMainThread) {
  executeTestInWorker(workerData).then((results) => {
    parentPort.postMessage(results);
  }).catch((error) => {
    console.error(`Error in worker: ${error.message}`);
    parentPort.postMessage([{ label: 'worker-error', status: 'failed', errorMessage: error.message }]);
  });
}

module.exports = executePluginTestsParallelly;

// Usage example:
(async () => {
  const report = await executePluginTestsParallelly(
    'sampleTest',
    (plugin) => plugin.run(), // Sample test function
    ['plugin1', 'plugin2'],
    4
  );

  console.log('Test Report:', JSON.stringify(report, null, 2));

  await fs.writeFile('test-report.json', JSON.stringify(report, null, 2));
})();
```

### Explanation:
- **Dynamic Loading**: Plugins are dynamically loaded from the `plugins` directory.
- **Parallel Execution**: Tests run in parallel using Node.js worker threads based on the specified or default number of workers.
- **Error Handling & Logging**: Captures success/failure details with errors and durations. Results include detailed logging information for each test execution.
- **File Management**: Efficiently reads plugin files and writes results to a file.

