<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Library Loader</title>
  <style>
    #status {
      margin-top: 20px;
    }
  </style>
</head>
<body>

<div id="libraryList"></div>
<button onclick="addLibrary('https://example.com/library1.js')">Add Library 1</button>
<button onclick="addLibrary('https://example.com/library2.js')">Add Library 2</button>

<div id="status"></div>

<script>
class ScriptLoader {
  constructor() {
    this.cache = new Map();
    this.statusContainer = document.getElementById('status');
    window.onerror = this.logError.bind(this);
  }

  addLibrary(url) {
    if (this.cache.has(url)) {
      this.updateStatus(`Cached: ${url}`, 'cached');
      return;
    }

    const statusElement = document.createElement('div');
    statusElement.id = `status-${url}`;
    statusElement.textContent = `Loading: ${url}`;
    document.getElementById('libraryList').appendChild(statusElement);
    this.loadScript(url, () => {
      this.updateStatus(`Loaded: ${url}`, 'success', statusElement);
    }, (error) => {
      this.updateStatus(`Error loading: ${url} - ${error}`, 'error', statusElement);
    });
  }

  loadScript(src, successCallback, errorCallback) {
    if (!src) return;

    let script = document.createElement('script');
    script.src = src;
    script.async = true;

    script.onload = () => {
      this.cache.set(src, true);
      successCallback();
    };

    script.onerror = (e) => {
      this.cache.delete(src);
      errorCallback(e.message || 'Network Error');
    };

    document.head.appendChild(script);
  }

  updateStatus(message, statusClass, elementToUpdate) {
    const container = this.statusContainer;
    if (!elementToUpdate) {
      const newElement = document.createElement('div');
      newElement.textContent = message;
      newElement.className = statusClass;
      container.appendChild(newElement);
    } else {
      elementToUpdate.textContent = message;
      elementToUpdate.className = statusClass;
    }
  }

  logError(message, source, lineno, colno, error) {
    console.error(`Runtime Error: ${message} at ${source}:${lineno}:${colno}`, error);
    this.updateStatus(`Runtime Error: ${message}`, 'runtime-error');
  }
}

const scriptLoader = new ScriptLoader();

// Unit tests using a simple testing framework for demonstration
function runTests() {
  const cacheTest1 = scriptLoader.cache.has('https://example.com/library1.js');
  console.assert(!cacheTest1, "Library should not be cached yet.");

  scriptLoader.addLibrary('https://example.com/library1.js');

  setTimeout(() => {
    const cacheTest2 = scriptLoader.cache.has('https://example.com/library1.js');
    console.assert(cacheTest2, "Library should now be cached.");

    scriptLoader.addLibrary('https://example.com/library1.js');
    setTimeout(() => {
      const statusElementId = `status-${'https://example.com/library1.js'}`;
      const statusElement = document.getElementById(statusElementId);
      if (statusElement) {
        console.assert(statusElement.classList.contains('cached'), "Should be marked as cached.");
      }

      console.log("All tests passed!");
    }, 1000);

  }, 2000);
}

runTests();

</script>

</body>
</html>
```

### Key Concepts

- **ScriptLoader Class**: Manages loading scripts dynamically, handling caching, status updates, and error logging.
- **Cache Management**: Uses a `Map` to store loaded libraries' URLs.
- **Error Handling**: Captures script loading errors using the `onerror` event and runtime errors with `window.onerror`.
- **User Interface**: Provides visual feedback on loading status (loading, success, cached, error).
- **Retry Logic**: Allows for retrying failed loads via UI or programmatic methods by re-calling `addLibrary`.
- **Unit Tests**: Simple synchronous tests to check functionality and cache behavior.

This solution allows for scalable script management in a web page environment, supporting performance optimization through caching and robust error handling.

