import json
import asyncio
import aiofiles
import logging
from concurrent.futures import ThreadPoolExecutor
from hashlib import sha256
import os
from typing import Any, Callable, Dict

# Configure logging
logging.basicConfig(level=logging.INFO)

class JsonManager:
    _registry: Dict[str, Callable[..., 'JsonManager']] = {}

    def __init__(self):
        self.forward_list: list[str] = []

    @classmethod
    async def load_json_files(cls, file_paths: list[str]):
        loop = asyncio.get_event_loop()

        # Load files concurrently
        tasks = [loop.run_in_executor(None, cls._load_file, path) for path in file_paths]
        results = await asyncio.gather(*tasks)

        objects = []
        for result in results:
            if isinstance(result, Exception):
                logging.error(f"Failed to load JSON: {result}")
            else:
                objects.append(result)

        return objects

    @staticmethod
    def _load_file(file_path: str) -> Any:
        try:
            with open(file_path, 'r') as file:
                return json.load(file)
        except Exception as e:
            logging.error(f"Error loading {file_path}: {e}")
            return e

    @classmethod
    def register_factory(cls, id_: str, factory: Callable[..., 'JsonManager']):
        if id_ in cls._registry:
            logging.warning(f"Overwriting existing factory for ID: {id_}")
        cls._registry[id_] = factory

    @classmethod
    async def create_instance_from_id(cls, id_: str, *args, **kwargs) -> 'JsonManager':
        if id_ not in cls._registry:
            raise ValueError(f"No factory registered for ID: {id_}")

        try:
            return await asyncio.get_event_loop().run_in_executor(None, cls._registry[id_], *args, **kwargs)
        except Exception as e:
            logging.error(f"Error creating instance for ID {id_}: {e}")

    def to_json(self) -> str:
        return json.dumps({
            'forward_list': self.forward_list
        })

    @classmethod
    def from_json(cls, json_str: str) -> 'JsonManager':
        data = json.loads(json_str)
        instance = cls()
        instance.forward_list = data['forward_list']
        return instance

    def manipulate_forward_list(self, forward_list: list[str], first_arg: str, second_arg: str, position_index: int = None):
        if position_index is not None and (position_index < 0 or position_index >= len(forward_list)):
            logging.warning(f"Position index {position_index} out of bounds. Inserting at the end.")
            self.forward_list.append(second_arg)
            return

        try:
            idx = next(i for i, v in enumerate(forward_list) if v == first_arg and (i == position_index or position_index is None))
        except StopIteration:
            logging.info(f"{first_arg} not found. Appending {second_arg} to the list.")
            self.forward_list.append(second_arg)
        else:
            self.forward_list.insert(idx + 1, second_arg)

    @staticmethod
    def deserialize_and_hash(byte_array: bytes) -> str:
        # Simulate deserialization (this is a placeholder for actual logic)
        obj = json.loads(byte_array.decode('utf-8'))

        random_str = os.urandom(16).hex()
        hashed_password = sha256(obj.get("password", "").encode()).hexdigest()

        logging.info(f"Deserialized object: {obj}")
        return f"{random_str}-{hashed_password}"

    @staticmethod
    def read_string_pairs(file_path: str) -> list[tuple[str, str]]:
        pairs = []
        try:
            with open(file_path, 'r') as file:
                for line in file:
                    parts = line.strip().split(',')
                    if len(parts) == 2:
                        pairs.append((parts[0], parts[1]))
        except Exception as e:
            logging.error(f"Error reading string pairs from {file_path}: {e}")

        return pairs

# Usage example
async def main():
    json_manager = JsonManager()

    # Register a factory function
    def my_factory(data):
        instance = JsonManager.from_json(json.dumps(data))
        return instance

    JsonManager.register_factory("example", my_factory)

    # Load JSON files asynchronously
    objects = await JsonManager.load_json_files(["file1.json", "file2.json"])

    # Create an instance using the factory
    try:
        instance = await JsonManager.create_instance_from_id("example", {'forward_list': ["a", "b"]})
    except ValueError as e:
        logging.error(e)

    # Manipulate forward list
    instance.manipulate_forward_list(["a", "b", "c"], "b", "new_item")

if __name__ == "__main__":
    asyncio.run(main())
```

This code defines a `JsonManager` class that handles loading JSON files asynchronously, managing a registry of factory functions for creating instances from JSON data, and manipulating forward list-like structures. It includes error handling, logging, and methods to serialize/deserialize JSON objects and manage circular dependencies.

