```python
import logging
from jsonschema import validate, ValidationError
import time
from collections import deque
from threading import Lock

# Configuration
RATE_LIMIT = 10  # Messages per second
DEDUPLICATION_WINDOW = 60  # Seconds
BACKLOG_CAPACITY = 1000
SCHEMA = {
    "type": "object",
    "properties": {
        "device_id": {"type": "string"},
        "state": {"type": "string"},
    },
    "required": ["device_id", "state"]
}

# Global variables for deduplication and rate limiting
last_processed_time = time.time()
message_ids = set()
deduplication_queue = deque(maxlen=DEDUPLICATION_WINDOW * RATE_LIMIT)
message_lock = Lock()

def process_mqtt_message(topic, payload, qos):
    global last_processed_time

    # Validate message format against schema
    try:
        validate(instance=payload, schema=SCHEMA)
    except ValidationError as e:
        logging.error(f"Invalid payload: {e.message}")
        return

    # Deduplication logic
    message_id = f"{topic}-{payload['device_id']}-{time.time()}"
    with message_lock:
        if message_id in message_ids:
            logging.info("Duplicate message detected, skipping.")
            return
        deduplication_queue.append(message_id)
        message_ids.add(message_id)

        # Remove outdated messages from the set
        current_time = time.time()
        while deduplication_queue and (current_time - deduplication_queue[0] > DEDUPLICATION_WINDOW):
            old_message = deduplication_queue.popleft()
            message_ids.remove(old_message)

    # Rate limiting logic
    current_rate = time.time() - last_processed_time
    if len(deduplication_queue) >= RATE_LIMIT and current_rate < 1:
        logging.warning("Rate limit exceeded, delaying processing.")
        time.sleep(1 - current_rate)

    # Update the timestamp for rate limiting
    last_processed_time = time.time()

    # Dispatch message to appropriate handler based on topic
    try:
        if topic == "home/lights":
            handle_lights(payload)
        elif topic == "home/thermostat":
            handle_thermostat(payload)
        else:
            logging.warning(f"No handler for topic: {topic}")
    except Exception as e:
        logging.error(f"Error processing message: {e}")

