```javascript
class ScriptManager {
  constructor() {
    this.cache = new Map();
    this.loadingIndicator = document.getElementById('loading-spinner');
    this.scriptContainer = document.getElementById('script-container');
  }

  async loadAndExecuteScripts(scripts) {
    if (!scripts || !Array.isArray(scripts)) return;

    // Show loading indicator
    this.showLoading(true);

    try {
      const results = await Promise.all(
        scripts.map(async (script) => {
          const cachedScript = this.getCachedScript(script.scriptId);

          if (cachedScript) {
            return cachedScript;
          }

          await this.fetchAndCacheScript(script);
          return script;
        })
      );

      this.renderScripts(results.filter(script => script.actionType));
    } catch (error) {
      console.error('Error loading scripts:', error);
      // Implement fallback mechanisms as needed
    } finally {
      this.showLoading(false);
    }
  }

  async fetchAndCacheScript(script) {
    if (!script.url || !script.actionType || !scriptId) return;

    try {
      const response = await fetch(script.url, {
        mode: script.crossorigin || 'same-origin',
        credentials: 'omit',
        cache: 'no-cache'
      });

      if (!response.ok) throw new Error('Network response was not ok');

      const scriptContent = await response.text();
      this.cacheScript(script.scriptId, { content: scriptContent });
    } catch (error) {
      console.error(`Error fetching script ${scriptId}:`, error);
    }
  }

  cacheScript(scriptId, data) {
    const expiryTime = Date.now() + 5 * 60 * 1000; // Cache for 5 minutes
    this.cache.set(scriptId, { ...data, expiry: expiryTime });
  }

  getCachedScript(scriptId) {
    const cachedData = this.cache.get(scriptId);
    if (!cachedData || cachedData.expiry < Date.now()) {
      this.cache.delete(scriptId);
      return null;
    }
    return cachedData.content;
  }

  renderScripts(scripts) {
    scripts.forEach((script) => {
      const scriptElement = document.createElement('div');
      // Use eval, new Function(), or safer alternatives to execute
      // Remember to sanitize the content if necessary for security reasons

      try {
        // Example: Execute script content as a function (ensure it's safe)
        // new Function(script.content)();
        scriptElement.innerHTML = `Script executed with action: ${script.actionType}`;
      } catch (e) {
        console.error('Error executing script:', e);
      }

      this.scriptContainer.appendChild(scriptElement);
    });
  }

  showLoading(isLoading) {
    if (isLoading) {
      this.loadingIndicator.style.display = 'block';
    } else {
      this.loadingIndicator.style.display = 'none';
    }
  }
}

