```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_THREADS 4

typedef struct {
    char *data;
    size_t size;
} MemoryStruct;

typedef struct {
    const char *input_dir;
    const char *output_dir;
    int log_level;
} Config;

void log_message(const char *message, int level) {
    if (level >= Config.log_level) {
        printf("%s\n", message);
    }
}

size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->data, mem->size + realsize + 1);
    if (!ptr) {
        log_message("Not enough memory", 2);
        return 0;
    }

    mem->data = ptr;
    memcpy(&(mem->data[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->data[mem->size] = '\0';

    return realsize;
}

void fetch_scripts(MemoryStruct *scripts) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://localhost/api/scripts");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, scripts);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            log_message("CURL failed", 2);
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

double parse_and_compute_average(char *line) {
    double values[3];
    int count = sscanf(line, "%lf %lf %lf %*f", &values[0], &values[1], &values[2]);

    if (count < 3) return -1.0;
    return (values[0] + values[1] + values[2]) / 3;
}

void process_file(const char *input_filename, const char *output_filename, Config config) {
    FILE *infile = fopen(input_filename, "r");
    if (!infile) {
        log_message("Error opening input file", 2);
        return;
    }

    FILE *outfile = fopen(output_filename, "w");
    if (!outfile) {
        fclose(infile);
        log_message("Error opening output file", 2);
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), infile)) {
        double average = parse_and_compute_average(line);
        if (average != -1.0) {
            fprintf(outfile, "%f\n", average);
        }
    }

    fclose(infile);
    fclose(outfile);
}

void *thread_function(void *arg) {
    Config config = *(Config *)arg;
    // Example processing logic for demonstration purposes
    const char *input_filename = "example_input.txt";
    const char *output_filename = "example_output.txt";

    process_file(input_filename, output_filename, config);

    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <input_dir> <output_dir> <log_level>\n", argv[0]);
        return EXIT_FAILURE;
    }

    Config config = {argv[1], argv[2], atoi(argv[3])};

    log_message("Starting processing...", 1);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, &config)) {
            fprintf(stderr, "Error creating thread\n");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    MemoryStruct scripts = {NULL, 0};
    fetch_scripts(&scripts);

    log_message("Processing complete", 1);

    free(scripts.data);

    return EXIT_SUCCESS;
}
```

This C program demonstrates a basic structure for processing files in parallel using threads and fetching JavaScript scripts from an API endpoint. It includes logging functionality based on a configurable log level, processes each input line to compute averages, and writes the results to output files.

