```c
#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <string.h>

#define MAX_LOG_LEVELS 3
#define LOG_BUFFER_SIZE 1024

typedef struct {
    FILE* error_fp;
    FILE* warning_fp;
    FILE* info_fp;
    int log_to_console; // 0 or 1 to enable/disable console logging
} LoggerConfig;

LoggerConfig logger = { NULL, NULL, NULL, 1 };

void configureLogging(const char* errorFile, const char* warningFile, const char* infoFile, int logToConsole) {
    if (errorFile) logger.error_fp = fopen(errorFile, "a");
    if (warningFile) logger.warning_fp = fopen(warningFile, "a");
    if (infoFile) logger.info_fp = fopen(infoFile, "a");
    logger.log_to_console = logToConsole;
}

void closeLogFiles() {
    if (logger.error_fp) fclose(logger.error_fp);
    if (logger.warning_fp) fclose(logger.warning_fp);
    if (logger.info_fp) fclose(logger.info_fp);
}

const char* getLogLevelStr(int level) {
    switch(level) {
        case 0: return "ERROR";
        case 1: return "WARNING";
        case 2: return "INFO";
        default: return "UNKNOWN";
    }
}

int logLevelToInt(const char* level) {
    if (strcmp(level, "ERROR") == 0) return 0;
    if (strcmp(level, "WARNING") == 0) return 1;
    if (strcmp(level, "INFO") == 0) return 2;
    return -1; // Unknown log level
}

void logFormattedError(const char* levelStr, const char* format, ...) {
    int level = logLevelToInt(levelStr);
    if (level < 0 || (!logger.error_fp && level == 0) &&
        (!logger.warning_fp && level == 1) &&
        (!logger.info_fp && level == 2)) return;

    va_list args;
    char buffer[LOG_BUFFER_SIZE];
    time_t rawtime;
    struct tm* timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    snprintf(buffer, LOG_BUFFER_SIZE, "[%02d-%02d %02d:%02d:%02d] ", 
             timeinfo->tm_mon + 1, timeinfo->tm_mday,
             timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    va_start(args, format);
    vsnprintf(buffer + strlen(buffer), LOG_BUFFER_SIZE - strlen(buffer), format, args);
    va_end(args);

    FILE* log_fp = NULL;
    switch(level) {
        case 0: log_fp = logger.error_fp; break;
        case 1: log_fp = logger.warning_fp; break;
        case 2: log_fp = logger.info_fp; break;
    }

    if (log_fp && fprintf(log_fp, "%s\n", buffer) < 0) {
        perror("Failed to write to log file");
    }

    if (logger.log_to_console) {
        printf("%s\n", buffer);
    }
}

int main() {
    configureLogging("error.log", "warning.log", "info.log", 1);

    logFormattedError("ERROR", "File %s could not be opened.", "config.txt");
    logFormattedError("WARNING", "Low disk space on drive %c:", 'C');
    logFormattedError("INFO", "System started successfully.");

    closeLogFiles();
    return 0;
}
