```javascript
interface ElementMetadata {
    id: string;
    class: string;
    descriptions: Map<string, string>;
    images: Map<string, string>;
    isFetched: boolean;
}

class MetadataCache {
    private cache: Map<string, ElementMetadata>;

    constructor() {
        this.cache = new Map();
    }

    async fetchAndCacheMetadata(apiClientFactory: ApiClientFactory, elements: HTMLElement[]): Promise<void> {
        const fetchQueue = [...elements].map(async (element) => {
            const metadata = this.getElementMetadata(element);
            if (!metadata || !metadata.isFetched) {
                const apiClient = await apiClientFactory.createApiClient(`https://api.example.com/element/${element.id}`);
                try {
                    const { descriptions, images } = await apiClient.fetchMetadata();
                    const newMetadata: ElementMetadata = {
                        id: element.id,
                        class: element.className,
                        descriptions: new Map(descriptions),
                        images: new Map(images),
                        isFetched: true
                    };
                    this.cache.set(element.id, newMetadata);
                } catch (error) {
                    console.error(`Failed to fetch metadata for ${element.id}:`, error);
                }
            }
        });

        await Promise.all(fetchQueue);
    }

    getElementMetadata(element: HTMLElement): ElementMetadata | null {
        return this.cache.get(element.id) || null;
    }
}

class ApiClientFactory {
    createApiClient(url: string): Promise<ApiClient> {
        return new Promise((resolve, reject) => {
            // Simulate API client creation and configuration
            resolve(new ApiClient(url));
        });
    }
}

class ApiClient {
    private url: string;

    constructor(url: string) {
        this.url = url;
    }

    async fetchMetadata(): Promise<{ descriptions: [string, string][]; images: [string, string][] }> {
        // Simulate a network request to fetch metadata
        return new Promise((resolve, reject) => {
            setTimeout(() => {
                resolve({
                    descriptions: [['description', 'A sample description']],
                    images: [['thumbnail', 'https://example.com/sample.jpg']]
                });
            }, 1000);
        });
    }
}

async function fetchAndFilterDynamicContent(selector: string): Promise<HTMLElement[]> {
    const elements = Array.from(document.querySelectorAll(selector));
    const metadataCache = new MetadataCache();
    const apiClientFactory = new ApiClientFactory();

    await metadataCache.fetchAndCacheMetadata(apiClientFactory, elements);

    return elements.filter((element) => {
        const metadata = metadataCache.getElementMetadata(element);
        if (!metadata) return false;

        // Apply custom filtering logic based on metadata
        return metadata.descriptions.has('description') && metadata.images.size > 0;
    });
}

// Usage example:
fetchAndFilterDynamicContent('.dynamic-content').then((filteredElements) => {
    console.log(filteredElements);
});
