                save_to_database({'action': 'delete', 'product_id': product_id})

                message = 'success'
            else:
                return json.dumps({'message': 'error', 'data': None})

    except KeyError as e:
        return json.dumps({'message': 'error', 'data': {'details': f'Missing key: {str(e)}'}})
    except Exception as e:
        # General error handling, could be database connection issues etc.
        return json.dumps({'message': 'error', 'data': {'details': str(e)}})

    # Return a success response with any necessary data
    return json.dumps({'message': message, 'data': None if action == 'delete' else request_payload})

# Example usage:
# response = manage_inventory({
#     "action": "add",
#     "quantity": 10,
#     "price": 20.5,
