# Cache for storing fetched data
cache = {}
CACHE_EXPIRATION = timedelta(minutes=10)

def get_current_weather(city):
    now = datetime.now()

    if city in cache and (now - cache[city]['timestamp']) < CACHE_EXPIRATION:
        return cache[city]['data']

    # Fetch from OpenWeatherMap
    try:
        response = requests.get(
            f"http://api.openweathermap.org/data/2.5/weather?q={city}&appid={OPENWEATHER_API_KEY}")
        data = response.json()

        # Store in cache
        cache[city] = {'data': data, 'timestamp': now}

        return data
    except requests.RequestException as e:
        logging.error(f"Error fetching from OpenWeatherMap for {city}: {e}")

    # Fallback: Fetch from WeatherAPI or AccuWeather

def fetch_historical_weather(city):
    try:
        response = requests.get(
            f"http://api.weatherapi.com/v1/history.json?key={WEATHERAPI_KEY}&q={city}&dt=20230101")
        return response.json()
    except requests.RequestException as e:
        logging.error(f"Error fetching historical weather for {city}: {e}")

