using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class WeatherDataFetcher
{
    public IDataReader ExecuteQueryWithParameters(string connectionString, string sqlCommandText, List<object> parameters)
    {
        if (string.IsNullOrEmpty(connectionString)) throw new ArgumentException("Connection string cannot be null or empty.");
        if (string.IsNullOrEmpty(sqlCommandText)) throw new ArgumentException("SQL command text cannot be null or empty.");

        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            SqlCommand command = new SqlCommand(sqlCommandText, connection);

            for (int i = 0; i < parameters.Count; i++)
            {
                var parameter = command.Parameters.AddWithValue($"@p{i}", parameters[i]);
                // Set SqlDbType explicitly based on your data type
                parameter.SqlDbType = SqlDbType.NVarChar; 
            }

            try
            {
                connection.Open();
                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
            catch (SqlException ex)
            {
                Console.WriteLine($"SQL Error: {ex.Message}");
                throw;
            }
        }
    }
}

