public class AesGcmFileEncryptionService
{
    private const int ChunkSize = 10 * 1024 * 1024; // 10 MB chunks
    private readonly HsmKeyManager _hsmKeyManager;
    private readonly DistributedStorageClient _storageClient;
    private readonly AuthorizationService _authService;
    private readonly ILogger _logger;

    public AesGcmFileEncryptionService(HsmKeyManager hsmKeyManager, 
                                       DistributedStorageClient storageClient,
                                       AuthorizationService authService,
                                       ILogger logger)
    {
        _hsmKeyManager = hsmKeyManager ?? throw new ArgumentNullException(nameof(hsmKeyManager));
        _storageClient = storageClient ?? throw new ArgumentNullException(nameof(storageClient));
        _authService = authService ?? throw new ArgumentNullException(nameof(authService));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task EncryptFileAsync(string filePath)
    {
        if (!_authService.HasPermission("encrypt"))
            throw new UnauthorizedAccessException();

        byte[] key = await _hsmKeyManager.GetKeyAsync();
        using (AesGcm aesGcm = new AesGcm(key))
        {
            int nonceSize = 12;
            int tagSize = 16;

            long fileSize = new FileInfo(filePath).Length;
            int chunkCount = (int)Math.Ceiling(fileSize / (double)ChunkSize);

            for (int i = 0; i < chunkCount; i++)
            {
                await RateLimiter.WaitAsync();

                byte[] nonce = new byte[nonceSize];
                RandomNumberGenerator.Fill(nonce);
                byte[] tag = new byte[tagSize];

                using (FileStream fs = File.OpenRead(filePath))
                {
                    fs.Seek(i * ChunkSize, SeekOrigin.Begin);

                    byte[] buffer = new byte[ChunkSize];
                    int bytesRead = await fs.ReadAsync(buffer, 0, buffer.Length);

                    byte[] compressedBuffer = CompressData(buffer);
                    aesGcm.Encrypt(nonce, compressedBuffer.AsMemory(), tag);

                    var metadata = new FileMetadata
                    {
                        Nonce = nonce,
                        Tag = tag,
                        Iv = aesGcm.Iv
                    };

                    await _storageClient.StoreFileChunkAsync(filePath, i, compressedBuffer, metadata);
                }
            }

            byte[] signature = GenerateSignature(key, filePath);
            await _storageClient.StoreFileMetadataAsync(filePath, signature);

            RotateKeyIfNeeded();
        }
    }

    public async Task<byte[]> DecryptFileAsync(string filePath)
    {
        if (!_authService.HasPermission("decrypt"))
            throw new UnauthorizedAccessException();

        byte[] key = await _hsmKeyManager.GetKeyAsync();
        using (AesGcm aesGcm = new AesGcm(key))
        {
            int nonceSize = 12;
            int tagSize = 16;

            long fileSize = await _storageClient.GetFileSizeAsync(filePath);
            int chunkCount = (int)Math.Ceiling(fileSize / (double)ChunkSize);

            using (MemoryStream outputStream = new MemoryStream())
            {
                for (int i = 0; i < chunkCount; i++)
                {
                    await RateLimiter.WaitAsync();

                    var metadata = await _storageClient.GetFileMetadataAsync(filePath, i);
                    byte[] compressedBuffer = await _storageClient.ReadFileChunkAsync(filePath, i);

                    aesGcm.Decrypt(metadata.Nonce, compressedBuffer.AsMemory(), metadata.Tag);

                    if (!VerifyIntegrity(compressedBuffer))
                        throw new CryptographicException("Data integrity check failed.");

                    byte[] decompressedBuffer = DecompressData(compressedBuffer);
                    await outputStream.WriteAsync(decompressedBuffer, 0, decompressedBuffer.Length);
                }

                return outputStream.ToArray();
            }
        }
    }

    private byte[] CompressData(byte[] data)
    {
        using (MemoryStream compressedStream = new MemoryStream())
        {
            using (GZipStream gzip = new GZipStream(compressedStream, CompressionMode.Compress))
            {
                gzip.Write(data, 0, data.Length);
            }
            return compressedStream.ToArray();
        }
    }

    private byte[] DecompressData(byte[] data)
    {
        using (MemoryStream compressedStream = new MemoryStream(data))
        using (GZipStream gzip = new GZipStream(compressedStream, CompressionMode.Decompress))
        using (MemoryStream decompressedStream = new MemoryStream())
        {
            gzip.CopyTo(decompressedStream);
            return decompressedStream.ToArray();
        }
    }

