Below is a basic outline of how you might structure your PHP-based web API authentication module for integrating with an OAuth 2.0 provider. This implementation uses sessions to store access tokens securely and includes handling for PUT and DELETE requests.

```php
<?php

session_start();

class OAuthModule {
    private $client_id;
    private $client_secret;
    private $redirect_uri;
    private $auth_url;
    private $token_url;
    private $api_base_url;

    public function __construct($client_id, $client_secret, $redirect_uri, $auth_url, $token_url, $api_base_url) {
        $this->client_id = $client_id;
        $this->client_secret = $client_secret;
        $this->redirect_uri = $redirect_uri;
        $this->auth_url = $auth_url;
        $this->token_url = $token_url;
        $this->api_base_url = $api_base_url;
    }

    public function authenticate() {
        if (!isset($_SESSION['access_token'])) {
            // Redirect to OAuth provider for authorization
            header("Location: " . $this->auth_url . "?response_type=code&client_id=" . $this->client_id . "&redirect_uri=" . urlencode($this->redirect_uri));
            exit;
        }
    }

    public function handleOAuthCallback() {
        if (isset($_GET['code'])) {
            // Exchange authorization code for access token
            $data = [
                'grant_type' => 'authorization_code',
                'client_id' => $this->client_id,
                'client_secret' => $this->client_secret,
                'redirect_uri' => $this->redirect_uri,
                'code' => $_GET['code']
            ];

            $options = [
                'http' => [
                    'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
                    'method'  => 'POST',
                    'content' => http_build_query($data)
                ]
            ];

            $context  = stream_context_create($options);
            $result = file_get_contents($this->token_url, false, $context);

            if ($result) {
                $response = json_decode($result, true);
                $_SESSION['access_token'] = $response['access_token'];
            } else {
                // Handle failed token exchange
                http_response_code(500);
                echo "Failed to retrieve access token.";
            }
        }
    }

    public function makeApiRequest($method, $resource_id, $data = null) {
        $url = $this->api_base_url . '/' . $resource_id;

        if (!isset($_SESSION['access_token'])) {
            http_response_code(401);
            echo "Unauthorized: No access token found.";
            return;
        }

        $options = [
            'http' => [
                'header' => "Authorization: Bearer {$_SESSION['access_token']}\r\n" .
                            "Content-type: application/json\r\n",
                'method'  => strtoupper($method),
                'content' => json_encode($data)
            ]
        ];

        $context = stream_context_create($options);

        if ($method === 'DELETE') {
            $result = file_get_contents($url, false, $context);
            if ($result) {
                echo "Resource deleted. Returning default values.";
                // Return a new resource with default values here
            } else {
                http_response_code(500);
                echo "Failed to delete the resource.";
            }
        } elseif ($method === 'PUT') {
            $result = file_get_contents($url, false, $context);
            if ($result) {
                echo "Resource updated successfully.";
            } else {
                http_response_code(500);
                echo "Failed to update the resource.";
            }
        }
    }

    public function logout() {
        session_destroy();
    }
}

