Below is an implementation in C that addresses your requirements for recursively traversing a DOM tree represented as a finite state automaton (FSA) with various engineering focuses and functional enhancements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Forward declarations for the functions used within this implementation.
typedef struct FSAState {
    int id;
    char *class;
    char *id;
    // Additional attributes like tag name, etc., can be added here
} FSAState;

typedef struct SelectorCacheEntry {
    const char *selector;
    struct SelectorCacheEntry *next;
    int *matchedStates;
} SelectorCacheEntry;

typedef struct ThreadData {
    FSAState **states;
    size_t stateCount;
    FSAState *fsa;
    int lastStateId;
    const char *selector;
    int (*compareFunction)(const char *, const char *);
    SelectorCacheEntry **cache;
    pthread_mutex_t cacheMutex;
} ThreadData;

int compareSelectors(const char *elementAttr, const char *selector) {
    // Implement a basic comparison function (could be extended for various selectors)
    return strcmp(elementAttr, selector) == 0;
}

void addMatchedState(SelectorCacheEntry **cache, int stateId) {
    pthread_mutex_lock(&((ThreadData*)cache)->cacheMutex);
    SelectorCacheEntry *entry = *cache;
    while (entry != NULL) {
        if (strcmp(entry->selector, ((ThreadData*)cache)->selector) == 0) {
            entry->matchedStates = realloc(entry->matchedStates, sizeof(int) * (entry->matchedStates ? (2 * strlen((char *)entry->matchedStates) + 1) : 0));
            entry->matchedStates[strlen((char *)entry->matchedStates)] = stateId;
            entry->matchedStates[strlen((char *)entry->matchedStates) + 1] = '\0';
            pthread_mutex_unlock(&((ThreadData*)cache)->cacheMutex);
            return;
        }
        entry = entry->next;
    }

    // Cache miss, create a new cache entry
    SelectorCacheEntry *newEntry = malloc(sizeof(SelectorCacheEntry));
    newEntry->selector = strdup(((ThreadData*)cache)->selector);
    newEntry->matchedStates = malloc(sizeof(int) * 2); // Initial size for the state ID
    newEntry->matchedStates[0] = stateId;
    newEntry->next = *cache;
    *cache = newEntry;

    pthread_mutex_unlock(&((ThreadData*)cache)->cacheMutex);
}

void* traverseFSA(void *threadArg) {
    ThreadData *data = (ThreadData *)threadArg;

    // Traverse the FSA tree recursively
    for (size_t i = 0; i < data->stateCount; ++i) {
        if (strcmp(data->fsa[i].class, data->selector) == 0 ||
            strcmp(data->fsa[i].id, data->selector) == 0 ||
            (data->compareFunction && data->compareFunction(data->fsa[i].class, data->selector))) {

            addMatchedState(data->cache, data->fsa[i].id);
        }
    }

    return NULL;
}

int* matchSelectors(FSAState **states, size_t stateCount, FSAState *fsa, int lastStateId,
                    const char *selector, int (*compareFunction)(const char *, const char *)) {

    if (!states || !stateCount || !fsa || !selector) return NULL;

    SelectorCacheEntry *cache = malloc(sizeof(SelectorCacheEntry));
    cache->next = NULL;
    pthread_mutex_init(&((ThreadData*)cache)->cacheMutex, NULL);

    ThreadData threadData;
    memset(&threadData, 0, sizeof(ThreadData));
    threadData.states = states;
    threadData.stateCount = stateCount;
    threadData.fsa = fsa;
    threadData.lastStateId = lastStateId;
    threadData.selector = selector;
    threadData.compareFunction = compareFunction;
    threadData.cache = &cache;

    pthread_t threads[2];
    int result;

    // Launch parallel traversal
    for (int i = 0; i < 2; ++i) {
        result = pthread_create(&threads[i], NULL, traverseFSA, &threadData);
        if (result != 0) {
            perror("Failed to create thread");
            free(cache);
            return NULL;
        }
    }

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Retrieve the matched states from cache
    SelectorCacheEntry *entry = cache->next;
    if (!entry) {
        free(cache);
        return NULL;
    }

    int *matchedStates = (int *)malloc(sizeof(int) * strlen((char *)entry->matchedStates));
    if (!matchedStates) {
        free(entry->matchedStates);
        free(cache);
        return NULL;
    }

    for (size_t i = 0; entry->matchedStates[i] != '\0'; ++i) {
        matchedStates[i] = entry->matchedStates[i];
    }

    free(entry->matchedStates);
    free(cache);

    return matchedStates;
}

// Example usage
int main() {
    // Mock FSA and states setup for demonstration purposes
    FSAState fsa[] = {
        {0, "header", NULL},
        {1, "content", NULL},
        {2, "footer", "footer-id"},
        {3, "nav", NULL}
    };

    int *matchedStates = matchSelectors(NULL, 4, fsa, -1, "footer-id", compareSelectors);

    if (matchedStates) {
        printf("Matched States: ");
        for (int i = 0; matchedStates[i] != '\0'; ++i) {
            printf("%d ", matchedStates[i]);
        }
        printf("\n");
        free(matchedStates);
    } else {
        printf("No states matched or an error occurred.\n");
    }

    return 0;
}
```

