// Helper function to generate secure random seed
std::uint64_t generateSecureSeed() {
    std::random_device rd;
    std::array<unsigned char, 8> buffer;
    RAND_bytes(buffer.data(), buffer.size());
    return *reinterpret_cast<std::uint64_t*>(buffer.data());
}

class SessionIDGenerator {
public:
    SessionIDGenerator()
        : generator(generateSecureSeed()) {}

    // Generate a unique session ID
    std::string generateSessionID() {
        static std::mutex mtx;
        static std::atomic<int> retryCount{0};

        for (int attempt = 0; attempt < MAX_ATTEMPTS; ++attempt) {
            auto id = base64Encode(generateRawSessionID());

            if (!isDuplicate(id)) {
                storeSessionID(id);
                return id;
            }

            // Exponential backoff
            std::this_thread::sleep_for(std::chrono::milliseconds(100 * (1 << retryCount++)));
        }

        throw std::runtime_error("Failed to generate unique session ID");
    }

private:
    std::random_device rd;
    std::mt19937_64 generator;

    static constexpr int MAX_ATTEMPTS = 5;
    std::unordered_set<std::string> recentIDs;

    // Generate raw session ID
    std::string generateRawSessionID() {
        boost::uuids::basic_random_generator<boost::mt19937_64> uuid_gen(generator);
        boost::uuids::uuid uuid = uuid_gen();
        return to_string(uuid);
    }

    // Encode the session ID in base64 with a fixed length of 22 characters
    std::string base64Encode(const std::string &data) {
        static const char encoding_table[] =
            "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
            "abcdefghijklmnopqrstuvwxyz"
            "0123456789+/";

        size_t input_length = data.size();
        size_t output_length = ((input_length + 2) / 3) * 4;
        std::vector<char> encoded_chars(output_length);

        int i = 0, j = 0;
        unsigned char a, b, c, d;

        while (input_length--) {
            a = data[i++];
            b = input_length ? data[i++] : 0;
            c = input_length > 1 ? data[i++] : 0;

            d = (a << 16) | (b << 8) | c;
            encoded_chars[j++] = encoding_table[(d >> 18) & 0x3F];
            encoded_chars[j++] = encoding_table[(d >> 12) & 0x3F];
            encoded_chars[j++] =
                (input_length > 1) ? encoding_table[(d >> 6) & 0x3F] : '=';
            encoded_chars[j++] =
                (input_length) ? encoding_table[d & 0x3F] : '=';

        }

        return std::string(encoded_chars.begin(), encoded_chars.end());
    }

    // Check for duplicate IDs
    bool isDuplicate(const std::string &id) {
        std::lock_guard<std::mutex> lock(mtx);
        if (recentIDs.find(id) != recentIDs.end()) {
            return true;
        }
        // Simulate database query here.
        return false; 
    }

    void storeSessionID(const std::string &id) {
        std::lock_guard<std::mutex> lock(mtx);
        recentIDs.insert(id);
        if (recentIDs.size() > MAX_CACHE_SIZE) {
            recentIDs.erase(recentIDs.begin());
        }
    }

    static constexpr size_t MAX_CACHE_SIZE = 1000;
};

int main() {
    SessionIDGenerator idGen;

    try {
        std::string sessionId = idGen.generateSessionID();
        std::cout << "Generated session ID: " << sessionId << std::endl;
    } catch (const std::exception &e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
