import logging
from logging.handlers import RotatingFileHandler
import os
import time
from pathlib import Path
import requests

def initialize_logging(log_directory: str = "/var/log/myapp", max_bytes: int = 10 * 1024 * 1024, backup_count: int = 5):
    log_level = os.getenv('LOG_LEVEL', 'INFO').upper()
    log_format = os.getenv('LOG_FORMAT', '%(asctime)s - %(name)s - %(levelname)s - %(message)s')

    # Retry creating directory if it fails due to transient errors
    retries, delay = 3, 2
    for _ in range(retries):
        try:
            Path(log_directory).mkdir(parents=True, exist_ok=True)
            break
        except Exception as e:
            print(f"Error creating log directory: {e}. Retrying in {delay} seconds...")
            time.sleep(delay)
            delay *= 2

    # Initialize logger
    logging.basicConfig(level=log_level,
                        format=log_format)

    file_handler = RotatingFileHandler(
        filename=os.path.join(log_directory, 'app.log'),
        maxBytes=max_bytes,
        backupCount=backup_count
    )

    file_handler.setLevel(log_level)
    formatter = logging.Formatter(log_format)
    file_handler.setFormatter(formatter)
    logger = logging.getLogger()
    logger.addHandler(file_handler)

    # Example function to send logs to an external service
    def send_logs_to_external_service(log_message: str):
        try:
            response = requests.post(
                'https://logging-service.example.com/logs',
                json={'message': log_message},
                headers={'Authorization': f'Bearer {os.getenv("LOG_SERVICE_TOKEN")}'}
            )
            response.raise_for_status()
        except Exception as e:
            logger.error(f"Failed to send logs to external service: {e}")

    # Example of logging operation for this function
    logger.info("Logging initialized.")

    return logger, send_logs_to_external_service

# Usage example
logger, send_logs = initialize_logging()
logger.debug("Debugging message")
send_logs("This is a log sent externally.")
