```java
// Java: CacheManager.java

import java.util.concurrent.*;
import java.util.function.Function;

public class CacheManager<K, V> {
    private final Object inMemoryCache;
    private final RedisCache redisCache;
    private final PostgreSQLCache postgresCache;
    private volatile BackendType currentBackend = BackendType.IN_MEMORY;

    public enum BackendType { IN_MEMORY, REDIS, POSTGRESQL }

    // Constructor
    public CacheManager() {
        this.inMemoryCache = new ConcurrentHashMap<>();
        this.redisCache = new RedisCache();
        this.postgresCache = new PostgreSQLCache();

        initializeHealthMonitoring();
    }

    public V get(K key) {
        return switchBackendAndExecute(key, (Function<Cache<K, V>, V>) cache -> cache.get(key));
    }

    public void put(K key, V value) {
        ensureTransactionalOperation(() -> {
            switchBackendAndExecute(key, cache -> cache.put(key, value));
        });
    }

    private <R> R switchBackendAndExecute(K key, Function<Cache<K, V>, R> operation) {
        Cache<K, V> activeCache;
        try {
            switch (currentBackend) {
                case IN_MEMORY:
                    activeCache = new InMemoryCache<>(inMemoryCache);
                    break;
                case REDIS:
                    activeCache = redisCache;
                    if (!activeCache.isHealthy()) throw new RuntimeException("Redis is down");
                    break;
                case POSTGRESQL:
                    activeCache = postgresCache;
                    if (!activeCache.isHealthy()) throw new RuntimeException("PostgreSQL is down");
                    break;
                default:
                    throw new IllegalStateException("Unknown backend type: " + currentBackend);
            }
        } catch (Exception e) {
            // Fallback to another healthy backend
            for (BackendType type : BackendType.values()) {
                if (type != currentBackend && isHealthy(type)) {
                    activeCache = switchToBackend(type);
                    break;
                }
            }
        }

        return operation.apply(activeCache);
    }

    private <T> void ensureTransactionalOperation(Consumer<T> operation) {
        try {
            // Begin transaction
            operation.accept(null); 
            // Commit transaction
        } catch (Exception e) {
            // Rollback transaction
            throw new RuntimeException("Transaction failed", e);
        }
    }

    private boolean isHealthy(BackendType backend) {
        switch (backend) {
            case REDIS:
                return redisCache.isHealthy();
            case POSTGRESQL:
                return postgresCache.isHealthy();
            default:
                return true; // In-memory is always available
        }
    }

    private Cache<K, V> switchToBackend(BackendType backend) throws Exception {
        this.currentBackend = backend;
        return switch (backend) {
            case IN_MEMORY -> new InMemoryCache<>(inMemoryCache);
            case REDIS -> redisCache;
            case POSTGRESQL -> postgresCache;
        };
    }

    private void initializeHealthMonitoring() {
        ScheduledExecutorService executor = Executors.newScheduledThreadPool(1);
        executor.scheduleAtFixedRate(this::monitorBackends, 0, 10, TimeUnit.SECONDS);
    }

    private void monitorBackends() {
        // Health check logic and fallback
        if (!isHealthy(currentBackend)) {
            for (BackendType type : BackendType.values()) {
                if (type != currentBackend && isHealthy(type)) {
                    switchToBackend(type).rebuildCache();
                    break;
                }
            }
        }

        // Implement logging, GDPR compliance, eviction policies
    }

    interface Cache<K, V> {
        V get(K key);
        void put(K key, V value);
        boolean isHealthy();
        void rebuildCache();
    }

    private static class InMemoryCache<K, V> implements Cache<K, V> {
        private final ConcurrentHashMap<K, V> cache;

        public InMemoryCache(ConcurrentHashMap<K, V> cache) {
            this.cache = cache;
        }

        @Override
        public V get(K key) {
            return cache.get(key);
        }

        @Override
        public void put(K key, V value) {
            cache.put(key, value);
        }

        @Override
        public boolean isHealthy() {
            return true; // In-memory is always healthy
        }

        @Override
        public void rebuildCache() {
            // Implement logic for cache rebuilding if needed
        }
    }

    private static class RedisCache<K, V> implements Cache<K, V> {
        @Override
        public V get(K key) {
            // Fetch from Redis
            return null;
        }

        @Override
        public void put(K key, V value) {
            // Store to Redis with transaction support and retry mechanism
        }

        @Override
        public boolean isHealthy() {
            // Implement health check for Redis
            return false;
        }

        @Override
        public void rebuildCache() {
            // Rebuild cache logic if needed
        }
    }

    private static class PostgreSQLCache<K, V> implements Cache<K, V> {
        @Override
        public V get(K key) {
            // Fetch from PostgreSQL
            return null;
        }

        @Override
        public void put(K key, V value) {
            // Store to PostgreSQL with transaction support and retry mechanism
        }

        @Override
        public boolean isHealthy() {
            // Implement health check for PostgreSQL
            return false;
        }

        @Override
        public void rebuildCache() {
            // Rebuild cache logic if needed
        }
    }
}
