// selectAttack.cpp
#include "selectAttack.h"
#include <random>
#include <iostream>
#include <stdexcept>
#include <thread>  // For this example, we'll use threads to simulate concurrent environments

void AttackSelector::fetchAttackDetails(const std::string& attackName) {
    try {
        // Simulating network call and fetching data from an external database
        std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate latency
        if (attackName == "NetworkFailure") throw std::runtime_error("Failed to fetch details");

        std::cout << "Fetched details for attack: " << attackName << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error fetching attack details: " << e.what() << std::endl;
    }
}

std::string AttackSelector::selectAttack(int cooldownPeriod) {
    const std::vector<std::string> attacks = {"Sword Strike", "Fireball"};
    static int lastUsedIndex = -cooldownPeriod; // Initialize to allow both attacks initially

    try {
        if (lastUsedIndex < 0 || (std::rand() % cooldownPeriod) > 0) { // Simple random selection with cooldown
            int choice = std::rand() % attacks.size();
            while (choice == lastUsedIndex / cooldownPeriod) {  // Ensure cooldown compliance
                choice = std::rand() % attacks.size();
            }
            lastUsedIndex = choice * cooldownPeriod;
            fetchAttackDetails(attacks[lastUsedIndex / cooldownPeriod]);
            return attacks[lastUsedIndex / cooldownPeriod];
        } else {
            throw std::runtime_error("Cooldown not yet expired");
        }
    } catch (const std::exception& e) {
        std::cerr << "Error selecting attack: " << e.what() << std::endl;
        return "";
    }
}
