using System;
using System.Data;
using System.IO;
using System.Net.Sockets;

public class DatabaseExecutor
{
    public IDataReader ExecuteQueryAndReturnReader(byte[] queryBytes)
    {
        try
        {
            using (var client = new TcpClient("dbserver", 12345)) // Replace with actual server details
            using (NetworkStream stream = client.GetStream())
            {
                // Send the query to the database server
                stream.Write(queryBytes, 0, queryBytes.Length);

                // Read the response
                byte[] buffer = new byte[4096];
                int bytesRead;
                using (MemoryStream ms = new MemoryStream())
                {
                    while ((bytesRead = stream.Read(buffer, 0, buffer.Length)) != 0)
                    {
                        ms.Write(buffer, 0, bytesRead);
                    }

                    // Assuming the server returns a DataSet serialized as XML
                    var dataSet = new DataSet();
                    dataSet.ReadXml(ms);

                    return dataSet.CreateDataReader(); // Return DataTableReader equivalent
                }
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error executing query: {ex.Message}");
            throw;
        }
    }
}
