function copyBytesFromChunks(chunks, byteCount) {
    const bufferSize = Math.min(byteCount, chunks.reduce((sum, chunk) => sum + chunk.length, 0));
    const buffer = Buffer.alloc(bufferSize);
    let offset = 0;

    for (let i = 0; i < chunks.length && offset < bufferSize; ++i) {
        const chunk = chunks[i];

        if (!Buffer.isBuffer(chunk)) {
            throw new TypeError("Each chunk must be a Buffer.");
        }

        const bytesToCopy = Math.min(bufferSize - offset, chunk.length);
        buffer.copyWithin(offset, 0, bytesToCopy, 0);
        offset += bytesToCopy;
    }

    if (offset < byteCount) {
        throw new Error("Insufficient data in chunks to copy the requested number of bytes.");
    }

    return buffer.slice(0, offset);
}

async function mergeAndStreamBuffers(sources) {
    const streams = sources.map(source => source.createReadStream());
    const mergedStream = new stream.PassThrough();

    for (const s of streams) {
        s.on('data', chunk => mergedStream.write(chunk));
    }

    for (const s of streams) {
        s.on('end', () => mergedStream.end());
    }

    return mergedStream;
}
