using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using MyWebApp.Services;
using MyWebApp.Models;
using MyWebApp.Logging;

[ApiController]
[Route("api/[controller]")]
public class ElementController : ControllerBase
{
    private readonly IElementService _elementService;
    private readonly IMessageQueue _messageQueue;
    private readonly ILogger _logger;

    public ElementController(IElementService elementService, IMessageQueue messageQueue, ILogger logger)
    {
        _elementService = elementService ?? throw new ArgumentNullException(nameof(elementService));
        _messageQueue = messageQueue ?? throw new ArgumentNullException(nameof(messageQueue));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateElement(
        [FromBody] ElementUpdateRequest request)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        try
        {
            // Validate IDs and HTML content
            if (!_elementService.ValidateSectionId(request.SectionId) || !_elementService.ValidateElementId(request.ElementId))
            {
                _logger.LogError("Invalid section or element ID.");
                return BadRequest("Invalid section or element ID.");
            }

            if (!HtmlValidator.IsWellFormed(request.HtmlContent))
            {
                _logger.LogError("HTML content is not well-formed.");
                return BadRequest("Invalid HTML content.");
            }

            if (request.RevisionComment?.Length > 255)
            {
                _logger.LogError("Revision comment exceeds length limit.");
                return BadRequest("Revision comment is too long.");
            }

            // Perform update with concurrency control
            var success = await _elementService.UpdateElementAsync(
                request.SectionId, 
                request.ElementId, 
                request.HtmlContent, 
                request.RevisionComment);

            if (!success)
            {
                _logger.LogError("Failed to update element due to concurrency issue.");
                return StatusCode(409, "Concurrency conflict occurred. Please retry.");
            }

            // Send notification for page refresh
            await _messageQueue.SendAsync(new Message { Content = $"Element updated: {request.ElementId}" });

            _logger.LogInformation($"Element {request.ElementId} updated successfully.");

            return Ok();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while updating the element.");
            return StatusCode(500, "Internal server error. Please try again later.");
        }
    }
}

// Example of an ElementUpdateRequest model
public class ElementUpdateRequest
{
    public Guid SectionId { get; set; }
    public Guid ElementId { get; set; }
    public string HtmlContent { get; set; }
    public string RevisionComment { get; set; }
}
