### User Routes (userRoutes.js)

```javascript
const bcrypt = require('bcryptjs');

function userRouter(UserModel) {
  const router = express.Router();

  // Create a new user
  router.post('/', async (req, res, next) => {
    try {
      const { username, email, password } = req.body;
      const salt = await bcrypt.genSalt(10);
      const passwordHash = await bcrypt.hash(password, salt);

      const newUser = new UserModel({ username, email, passwordHash });
      await newUser.save();

      res.status(201).send({ message: 'User created successfully' });
    } catch (err) {
      next(err);
    }
  });

  // Update a user
  router.put('/:id', async (req, res, next) => {
    try {
      const { password } = req.body;
      if (password) {
        const salt = await bcrypt.genSalt(10);
        req.body.passwordHash = await bcrypt.hash(password, salt);
      }

      const updatedUser = await UserModel.findByIdAndUpdate(req.params.id, req.body, { new: true });
      res.send(updatedUser);
    } catch (err) {
      next(err);
    }
  });

  // Delete a user
  router.delete('/:id', async (req, res, next) => {
    try {
      await UserModel.findByIdAndDelete(req.params.id);
      res.send({ message: 'User deleted successfully' });
    } catch (err) {
      next(err);
    }
  });

  return router;
}

module.exports = userRouter;
```

### Transaction Routes (transactionRoutes.js)

```javascript
function transactionRouter(TransactionModel, paymentGateway) {
  const router = express.Router();

  // Initiate a new transaction
  router.post('/', async (req, res, next) => {
    try {
      const { userId, amount } = req.body;

      // Cache check for frequent requests
      const cacheKey = `user_${userId}_transactions`;
      let transactions = await memoryCache.wrap(cacheKey).get();

      if (!transactions) {
        transactions = await TransactionModel.find({ userId });
        await memoryCache.set(cacheKey, transactions);
      }

      // Call payment gateway API
      const response = await paymentGateway.charge({ amount });

      const newTransaction = new TransactionModel({
        userId,
        amount,
        status: response.status
      });

      await newTransaction.save();
      res.send(newTransaction);
    } catch (err) {
      next(err);
    }
  });

  return router;
}

module.exports = transactionRouter;
```

