#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_LENGTH 1024

// Mutex for thread safety
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *level, const char *message) {
    time_t now;
    char timestamp[20];
    time(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    pthread_mutex_lock(&log_mutex);

    FILE *logfile = fopen("operation_log.txt", "a");
    if (logfile) {
        fprintf(logfile, "[%s] [%s]: %s\n", timestamp, level, message);
        fclose(logfile);
    }

    pthread_mutex_unlock(&log_mutex);
}

char* secureTrimAndAppendSlash(const char *input_str, size_t size_limit) {
    if (!input_str || size_limit <= 0) {
        log_message("ERROR", "Invalid input: null pointer or non-positive size limit.");
        return NULL;
    }

    // Trim leading whitespace
    const char *start = input_str;
    while (isspace((unsigned char)*start)) start++;

    // Trim trailing whitespace
    const char *end = start + strlen(start) - 1;
    while (end > start && isspace((unsigned char)*end)) end--;

    size_t trimmed_length = end - start + 1;

    if (trimmed_length >= size_limit) {
        log_message("ERROR", "Trimmed string exceeds size limit.");
        return NULL;
    }

    // Allocate memory for the result
    char *result = (char *)malloc(size_t)(trimmed_length + 2); // +2 for null terminator and slash
    if (!result) {
        log_message("ERROR", "Memory allocation failed.");
        return NULL;
    }

    strncpy(result, start, trimmed_length);
    result[trimmed_length] = '/';
    result[trimmed_length + 1] = '\0';

    char original_msg[MAX_LOG_LENGTH];
    snprintf(original_msg, sizeof(original_msg), 
             "Original string: '%s', Size limit: %zu, Trimmed length: %zu", input_str, size_limit, trimmed_length);
    log_message("INFO", original_msg);

    return result;
}
