// Define constants for retries and backoff
#define MAX_RETRIES 3
#define INITIAL_BACKOFF_MS 100

// Thread pool size
#define THREAD_POOL_SIZE 10

typedef struct {
    char *url;
    double response_time; // Track average response time
    int reliability_score; // Higher is better
} ConfigServer;

