    const char *json_response = "{\"access_token\":\"abc123\",\"expires_in\":3600,\"token_type\":\"Bearer\",\"refresh_token\":\"xyz789\"}";

    validate_token(json_response);

    return 0;
}

// Function implementations

void validate_token(const char *json_response) {
    json_t *validation_rules = NULL;

    ConfigServer servers[] = {
        {"https://config-server-1.example.com", 0.2, 5},
        {"https://config-server-2.example.com", 0.3, 4}
    };
    size_t server_count = sizeof(servers) / sizeof(ConfigServer);

    if (fetch_validation_rules(servers, server_count, &validation_rules)) {
        json_error_t error;
        json_t *token_data = json_loads(json_response, 0, &error);

        if (!json_is_object(token_data)) {
            fprintf(stderr, "Invalid JSON: %s\n", error.text);
            return;
        }

        process_token_validation(token_data, validation_rules);

        json_decref(token_data);
    }
}

int fetch_validation_rules(ConfigServer servers[], size_t server_count, json_t **rules) {
    for (size_t attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        retry_with_backoff(attempt, fetch_rules_from_server);
        if (*rules) return 1;
    }
    return 0;
}

void retry_with_backoff(int attempt, int (*func)(ConfigServer *, json_t **)) {
    double backoff = calculate_exponential_backoff(attempt);
    sleep(backoff / 1000.0); // Convert ms to seconds

    func(NULL, NULL); // Placeholder for actual logic
}

double calculate_exponential_backoff(int attempt) {
    return INITIAL_BACKOFF_MS * (1 << attempt);
}

int fetch_rules_from_server(ConfigServer *servers, json_t **rules) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    headers = curl_slist_append(headers, "Accept: application/json");

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if(curl) {
        for (size_t i = 0; i < server_count; ++i) {
            char url[256];
            snprintf(url, sizeof(url), "%s/validation-rules", servers[i].url);

            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

            res = curl_easy_perform(curl);

            if(res == CURLE_OK) {
                char *response_buffer;
                size_t response_size;

                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &res);
                if (res == 200) {
                    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
                    res = curl_easy_perform(curl);

                    if(res == CURLE_OK && response_size > 0) {
                        *rules = json_loads(response_buffer, 0, NULL);
                        free(response_buffer);

                        if (json_is_object(*rules)) {
                            return 1;
                        }
                    }
                }
            }

            curl_easy_cleanup(curl);
        }
    }

    curl_global_cleanup();
    return 0;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    char **response_buffer = (char **)userp;

    *response_buffer = realloc(*response_buffer, realsize + 1);
    if (*response_buffer == NULL) {
        fprintf(stderr, "Not enough memory\n");
        return 0;
    }

    memcpy(*response_buffer + strlen(*response_buffer), contents, realsize);
    (*response_buffer)[realsize] = '\0';

    return realsize;
}

void process_token_validation(json_t *token_data, json_t *validation_rules) {
    // Placeholder for token validation logic
}

// Thread pool functions

void initialize_thread_pool(pthread_t *threads, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        pthread_create(&threads[i], NULL, token_validation_worker, NULL);
    }
}

void destroy_thread_pool(pthread_t *threads, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        pthread_cancel(threads[i]);
    }
}

void *token_validation_worker(void *arg) {
    // Placeholder for worker logic
    return NULL;
}

// Token cache functions

TokenCache* create_token_cache(size_t capacity, double expiration_time_sec) {
    TokenCache *cache = malloc(sizeof(TokenCache));
    cache->items = calloc(capacity, sizeof(CacheItem *));
    cache->capacity = capacity;
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
    cache->expiration_time_sec = expiration_time_sec;

    return cache;
}

void token_cache_put(TokenCache *cache, const char *key, const char *value) {
    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->count; ++i) {
        if (strcmp(cache->items[i]->key, key) == 0) {
            free(cache->items[i]->value);
            cache->items[i]->value = strdup(value);
            pthread_mutex_unlock(&cache->lock);
            return;
        }
    }

    if (cache->count < cache->capacity) {
        cache->items[cache->count] = malloc(sizeof(CacheItem));
        cache->items[cache->count]->key = strdup(key);
        cache->items[cache->count]->value = strdup(value);
        cache->count++;
    } else {
        // Handle full cache, e.g., by removing the oldest item
    }

    pthread_mutex_unlock(&cache->lock);
}

char* token_cache_get(TokenCache *cache, const char *key) {
    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->count; ++i) {
        if (strcmp(cache->items[i]->key, key) == 0) {
            char *value = strdup(cache->items[i]->value);
            pthread_mutex_unlock(&cache->lock);
            return value;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void destroy_token_cache(TokenCache *cache) {
    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->count; ++i) {
        free(cache->items[i]->key);
        free(cache->items[i]->value);
        free(cache->items[i]);
    }

    free(cache->items);
    pthread_mutex_unlock(&cache->lock);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}
