```c
#include <stdio.h>
#include <stdlib.h>

// Define a basic structure for State and FSA (Finite State Automaton)
typedef struct State {
    int id;
    struct State* next;
} State;

typedef struct {
    State* startState; // Pointer to the first state of the FSA
} FSA;

int integrateAndOptimizeFSACreator(int* states, size_t numStates, FSA* fsa, int lastStateId) {
    if (states == NULL || fsa == NULL) {
        return -1; // Error due to null pointer
    }

    State* currentState = fsa->startState;
    while (currentState != NULL && currentState->id != lastStateId) {
        currentState = currentState->next;
    }

    if (currentState == NULL) {
        return -2; // Last state not found in the FSA
    }

    for (size_t i = 0; i < numStates; ++i) {
        State* newState = (State*)malloc(sizeof(State));
        if (newState == NULL) {
            // Handle memory allocation failure
            while (currentState != NULL && currentState->id >= states[0]) {
                State* temp = currentState;
                currentState = currentState->next;
                free(temp);
            }
            return -3; // Error due to memory allocation failure
        }

        newState->id = states[i];
        newState->next = NULL;

        if (currentState == fsa->startState) { 
            // Ensure the new FSA start state is correctly set
            if (newState->id < currentState->id) {
                newState->next = currentState;
                fsa->startState = newState;
                currentState = newState;
            }
        } else {
            while (currentState != NULL && currentState->next != NULL && currentState->next->id < newState->id) {
                currentState = currentState->next;
            }

            newState->next = currentState->next;
            currentState->next = newState;
        }
    }

    return 0; // Success
}

int main() {
    int states[] = {3, 1, 4}; // Example states to be added
    FSA fsa = {NULL};

    // Initialize FSA with some states for demonstration purposes
    State* s1 = (State*)malloc(sizeof(State));
    s1->id = 2;
    s1->next = NULL;
    fsa.startState = s1;

    int result = integrateAndOptimizeFSACreator(states, sizeof(states) / sizeof(states[0]), &fsa, 2);

    if (result == 0) {
        printf("Integration successful.\n");
        State* temp = fsa.startState;
        while (temp != NULL) {
            printf("State ID: %d\n", temp->id);
            temp = temp->next;
        }
    } else {
        printf("Integration failed with error code: %d\n", result);
    }

    // Free allocated states
    while (fsa.startState != NULL) {
        State* temp = fsa.startState;
        fsa.startState = fsa.startState->next;
        free(temp);
    }

    return 0;
}
```

This code defines a function `integrateAndOptimizeFSACreator` to dynamically integrate states into an FSA structure. It handles memory allocation, error cases, and maintains the integrity of the linked list while optimizing for insertion order.

