using System;
using System.IO;
using System.Xml;
using System.Xml.XPath;
using System.Collections.Generic;

public class XmlParser
{
    private static readonly Dictionary<string, XmlDocument> _cache = new Dictionary<string, XmlDocument>();

    public static XmlNode GetFirstElementByName(string xmlInput, string xpath)
    {
        XmlDocument doc = LoadXmlDocument(xmlInput);

        ValidateWellFormedness(doc);

        XPathNavigator navigator = doc.CreateNavigator();
        XPathNodeIterator iterator = navigator.Select(xpath);

        int count = 0;
        XmlNode result = null;

        while (iterator.MoveNext())
        {
            if (++count > 1)
                throw new Exception($"Multiple elements found with the name '{xpath}'.");

            result = iterator.Current as IXmlLineInfo ? ((IXmlLineInfo)iterator.Current).GetCurrentNode() : navigator.SelectSingleNode(xpath);
        }

        if (result == null)
            throw new Exception($"No element found with the name '{xpath}'.");

        return result;
    }

    private static XmlDocument LoadXmlDocument(string xmlInput)
    {
        string key = GenerateKey(xmlInput);

        if (_cache.ContainsKey(key))
        {
            return _cache[key];
        }

        XmlDocument doc;

        using (var stream = GetStreamFromInput(xmlInput))
        {
            doc = new XmlDocument();
            try
            {
                doc.Load(stream);
            }
            catch (XmlException ex)
            {
                throw new Exception("Invalid XML format.", ex);
            }
        }

        _cache[key] = doc;
        return doc;
    }

    private static Stream GetStreamFromInput(string xmlInput)
    {
        if (File.Exists(xmlInput))
        {
            return File.OpenRead(xmlInput);
        }

        if (!string.IsNullOrEmpty(xmlInput))
        {
            return new MemoryStream(System.Text.Encoding.UTF8.GetBytes(xmlInput));
        }

        throw new ArgumentException("Invalid XML input.");
    }

    private static void ValidateWellFormedness(XmlDocument doc)
    {
        using (var stringReader = new StringReader(doc.OuterXml))
        {
            using (var xmlReader = XmlReader.Create(stringReader))
            {
                try
                {
                    while (xmlReader.Read()) { }
                }
                catch (XmlException ex)
                {
                    throw new Exception("XML is not well-formed.", ex);
                }
            }
        }
    }

    private static string GenerateKey(string input)
    {
        if (File.Exists(input))
        {
            return Path.GetFullPath(input);
        }

        return Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(input));
    }
}

public class XmlParserCLI
{
    public static void Main(string[] args)
    {
        if (args.Length < 2 || args.Contains("--help"))
        {
            Console.WriteLine("Usage: XmlParserCLI <XML Document> <XPath Expression>");
            return;
        }

        string xmlInput = args[0];
        string xpath = args[1];

        try
        {
            XmlNode node = XmlParser.GetFirstElementByName(xmlInput, xpath);
            Console.WriteLine($"Found Element: {node.OuterXml}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
