#include <boost/beast/websocket.hpp> // For WebSockets
#include "distributed_logger.h" // Custom distributed logging system

// Define regular expressions for parsing attack names and log entries
const std::regex ATTACK_NAME_REGEX(R"(attack_name: (\w+))");
const std::regex LOG_ENTRY_REGEX(R"(entry: (.+))");

class AttackSelector {
public:
    explicit AttackSelector(redis_async_client& redis, const std::string& db_url)
        : redis_(redis), db_url_(db_url) {}

    std::optional<std::string> selectAttack(const std::string& character_id, int difficulty_level);

private:
    void updateAttackDatabase();
    std::vector<std::string> fetchAvailableAttacks();
    std::unordered_map<std::string, int> getCooldowns(const std::string& character_id);
    std::vector<std::string> parsePriorityList(const nlohmann::json& profile);
    bool isAttackReady(const std::string& attack_name, const std::unordered_map<std::string, int>& cooldowns, int current_time);

    redis_async_client& redis_;
    std::string db_url_;

    mutable std::mutex cache_mutex_;
    std::unordered_map<std::string, nlohmann::json> attacks_cache_;
    std::chrono::steady_clock::time_point last_db_update_ = std::chrono::steady_clock::now();
};

std::optional<std::string> AttackSelector::selectAttack(const std::string& character_id, int difficulty_level) {
    // Fetch the latest attack data if necessary
    updateAttackDatabase();

    // Retrieve character profile from Redis
    nlohmann::json profile;
    auto redis_future = redis_.get("character:" + character_id);
    if (!redis_future.valid()) {
        logError("Failed to retrieve character profile for: " + character_id);
        return std::nullopt;
    }
    try {
        profile = redis_future.get();
    } catch (const std::exception& e) {
        logError("Exception while fetching Redis data: " + std::string(e.what()));
        return std::nullopt;
    }

    // Parse cooldowns
    auto cooldowns = getCooldowns(character_id);

    // Get priority list of attacks from the profile
    auto priority_list = parsePriorityList(profile);

    int current_time = std::chrono::duration_cast<std::chrono::seconds>(
        std::chrono::steady_clock::now().time_since_epoch()).count();

    // Attempt to select an attack based on priority and readiness
    for (const auto& attack : priority_list) {
        if (isAttackReady(attack, cooldowns, current_time)) {
            return attack;
        }
    }

    // If no valid attacks in priority list, fetch all available attacks
    auto available_attacks = fetchAvailableAttacks();
    for (const auto& attack : available_attacks) {
        if (isAttackReady(attack, cooldowns, current_time)) {
            return attack;
        }
    }

    logError("No suitable attack found for character: " + character_id);
    return std::nullopt;
}

void AttackSelector::updateAttackDatabase() {
    std::lock_guard<std::mutex> lock(cache_mutex_);
    auto now = std::chrono::steady_clock::now();
    if (std::chrono::duration_cast<std::chrono::minutes>(now - last_db_update_).count() < 5) {
        return; // Update once every 5 minutes
    }

    web::http::client::http_client client(U(db_url_));
    auto request = client.request(web::http::methods::GET);
    request.then([this](web::http::http_response response) -> std::future<void> {
        if (response.status_code() == web::http::status_codes::OK) {
            auto body = response.extract_string().get();
            nlohmann::json attack_data = nlohmann::json::parse(body);
            attacks_cache_ = {attack_data.begin(), attack_data.end()};
            last_db_update_ = std::chrono::steady_clock::now();
        } else {
            logError("Failed to update attack database. HTTP status: " + std::to_string(response.status_code()));
        }
    }).wait(); // Wait for the request to complete
}

std::vector<std::string> AttackSelector::fetchAvailableAttacks() {
    std::lock_guard<std::mutex> lock(cache_mutex_);
    std::vector<std::string> attacks;
    for (const auto& [name, _] : attacks_cache_) {
        attacks.push_back(name);
    }
    return attacks;
}

std::unordered_map<std::string, int> AttackSelector::getCooldowns(const std::string& character_id) {
    nlohmann::json profile;
    auto redis_future = redis_.get("character:" + character_id);
    if (!redis_future.valid()) {
        logError("Failed to retrieve cooldown data for: " + character_id);
        return {};
    }
    try {
        profile = redis_future.get();
    } catch (const std::exception& e) {
        logError("Exception while fetching Redis data: " + std::string(e.what()));
        return {};
    }

    std::unordered_map<std::string, int> cooldowns;
    for (auto& [key, value] : profile.items()) {
        if (std::regex_match(key.begin(), key.end(), ATTACK_NAME_REGEX)) {
            cooldowns[std::string(ATTACK_NAME_REGEX[1])] = value.get<int>();
        }
    }
    return cooldowns;
}

std::vector<std::string> AttackSelector::parsePriorityList(const nlohmann::json& profile) {
    std::vector<std::string> priority_list;
    if (profile.contains("priority_attacks")) {
        for (const auto& attack : profile["priority_attacks"]) {
            priority_list.push_back(attack.get<std::string>());
        }
    }
    return priority_list;
}

bool AttackSelector::isAttackReady(const std::string& attack_name, const std::unordered_map<std::string, int>& cooldowns, int current_time) {
    auto it = cooldowns.find(attack_name);
    if (it != cooldowns.end()) {
        // Assume some base cooldown value and adjust based on difficulty
        int base_cooldown = 10; // Example base cooldown
        int adjusted_cooldown = base_cooldown + (difficulty_level * 2); // Example adjustment

        return current_time >= it->second + adjusted_cooldown;
    }
    return false;
}

void logError(const std::string& message) {
    // Implement a distributed logging system to record errors
    DistributedLogger::log("ERROR", message);
}
