class TestEnvironment {
public:
    TestEnvironment(size_t numNodes, size_t subListSize) : numNodes(numNodes), subListSize(subListSize) {}

    ~TestEnvironment() {
        for (auto node : nodes) {
            SubNode* current = node.subListHead;
            while (current != nullptr) {
                SubNode* next = current->next;
                delete[] current->str;
                delete current;
                current = next;
            }
            delete[] node.subListHead;
        }
    }

    void initializeNodes(int minVal, int maxVal) {
        for (auto& node : nodes) {
            node.intValue = rand() % (maxVal - minVal + 1) + minVal;

            SubNode* head = nullptr;
            SubNode* current = nullptr;
            for (size_t i = 0; i < subListSize; ++i) {
                SubNode* newNode = new SubNode();
                newNode->str = new char[10];
                std::snprintf(newNode->str, 10, "Str%d", rand() % 100);
                newNode->value = static_cast<double>(rand()) / RAND_MAX * 100.0;
                newNode->next = nullptr;

                if (!head) {
                    head = newNode;
                } else {
                    current->next = newNode;
                }
                current = newNode;
            }

            node.subListHead = head;
        }
    }

private:
    size_t numNodes;
    size_t subListSize;
    std::vector<Node> nodes;

public:
    void allocateMemory() {
        nodes.resize(numNodes);
    }
};

