// C# Part

using Microsoft.Extensions.Caching.Distributed;
using Microsoft.AspNetCore.Http;
using System.Threading.Tasks;

public class HtmlContentUpdateService
{
    private readonly IDistributedCache _cache;
    private readonly IRateLimiter _rateLimiter; // Assuming some rate limiter service is available.
    private readonly IMessageQueueClient _messageQueueClient;

    public HtmlContentUpdateService(IDistributedCache cache, IRateLimiter rateLimiter, IMessageQueueClient messageQueueClient)
    {
        _cache = cache;
        _rateLimiter = rateLimiter;
        _messageQueueClient = messageQueueClient;
    }

    public async Task<IActionResult> UpdateHtmlContentAsync(string pageSectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrWhiteSpace(htmlContent))
        {
            return BadRequest("Invalid input parameters.");
        }

        if (!await _rateLimiter.AllowRequestAsync(HttpContext.Connection.RemoteIpAddress.ToString()))
        {
            return StatusCode(StatusCodes.Status429TooManyRequests, "Rate limit exceeded.");
        }

        try
        {
            var cacheKey = $"{pageSectionId}:{elementId}";
            await _cache.SetStringAsync(cacheKey, htmlContent);

            // Notify the message queue for page refresh.
            await _messageQueueClient.PublishMessageAsync($"RefreshPage:{pageSectionId}");

            return Ok("HTML content updated successfully.");
        }
        catch (Exception ex)
        {
            // Log errors
            Console.Error.WriteLine(ex);
            return StatusCode(StatusCodes.Status500InternalServerError, "An error occurred while updating the HTML content.");
        }
    }
}

