class ScriptManager {
    constructor(apiEndpoint) {
        this.apiEndpoint = apiEndpoint;
        this.scriptCache = new Map();
        this.cacheExpiryTime = 300000; // Cache for 5 minutes
    }

    async fetchScripts() {
        try {
            const response = await fetch(this.apiEndpoint);
            if (!response.ok) throw new Error('Network response was not ok.');

            const scripts = await response.json();
            return scripts.map(script => ({
                ...script,
                loaded: false,
                loadPromise: this.loadScript(script)
            }));
        } catch (error) {
            console.error("Failed to fetch scripts:", error);
            // Implement fallback mechanism for critical scripts
            return [];
        }
    }

    async loadScript({ src, async = true, defer = false, crossorigin }) {
        if (!this.scriptCache.has(src)) {
            const scriptTag = document.createElement('script');
            scriptTag.src = src;
            scriptTag.async = async;
            scriptTag.defer = defer;
            if (crossorigin) scriptTag.crossOrigin = crossorigin;

            return new Promise((resolve, reject) => {
                scriptTag.onload = () => resolve();
                scriptTag.onerror = () => reject(new Error(`Failed to load script: ${src}`));

                document.body.appendChild(scriptTag);
            }).then(() => {
                this.scriptCache.set(src, Date.now() + this.cacheExpiryTime);
            });
        }
    }

    async renderScripts() {
        const scripts = await this.fetchScripts();
        for (const { loaded, loadPromise } of scripts) {
            if (!loaded) {
                try {
                    await loadPromise;
                } catch (error) {
                    console.error(error);
                    // Handle critical script failure
                }
            }
        }
    }

    start() {
        setInterval(() => this.scriptCache.forEach((expiry, src) => {
            if (Date.now() > expiry) this.scriptCache.delete(src);
        }), 60000);

        this.renderScripts();
    }
}

// Usage Example
document.addEventListener("DOMContentLoaded", () => {
    const scriptManager = new ScriptManager('https://api.example.com/scripts');
    scriptManager.start();
});
```

