For comprehensive testing, you would use a framework like `unittest` or `pytest` to create test cases for different scenarios including edge cases and failure conditions. This setup should be extended with more robust error handling, security practices (e.g., secure storage of API keys), and thorough logging for auditing purposes in a production environment.

Below is a Python script implementing the specified requirements using various libraries such as `os`, `glob`, `csv`, `gzip`, `zipfile`, `logging`, `concurrent.futures`, `BeautifulSoup`, and `Flask` for the web interface, along with other supporting modules.

```python
import os
import logging
from collections import defaultdict, Counter
from concurrent.futures import ProcessPoolExecutor
from typing import List, Dict, Tuple
import csv
import statistics
from bs4 import BeautifulSoup
import gzip
import zipfile
from flask import Flask, jsonify, request

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Cache implementation
cache = {}
CACHE_LIMIT = 500


def cache_result(key: str, result):
    if len(cache) >= CACHE_LIMIT:
        cache.pop(next(iter(cache)))
    cache[key] = result


def get_cached_result(key: str):
    return cache.get(key)


def process_directory(directory_path: str):
    file_stats = defaultdict(lambda: {'lines': 0, 'words': 0, 'characters': 0})
    csv_unique_counts = defaultdict(Counter)
    try:
        with ProcessPoolExecutor() as executor:
            results = list(executor.map(process_file, [os.path.join(directory_path, f) for f in os.listdir(directory_path)]))

        for result in results:
            file_type, stats, unique_vals = result
            if file_type == 'csv':
                csv_unique_counts[file_type].update(unique_vals)

            file_stats[file_type]['lines'] += stats['lines']
            file_stats[file_type]['words'] += stats['words']
            file_stats[file_type]['characters'] += stats['characters']
    except Exception as e:
        logger.error(f"Error processing directory: {str(e)}")

    return file_stats, csv_unique_counts


def process_file(file_path: str) -> Tuple[str, Dict[str, int], Counter]:
    try:
        if not os.path.isfile(file_path):
            logger.warning(f"{file_path} is not a valid file.")
            return '', {'lines': 0, 'words': 0, 'characters': 0}, Counter()

        _, ext = os.path.splitext(file_path)
        if ext in ['.txt', '.log']:
            with open(file_path, 'r') as f:
                content = f.read()
                lines = content.split('\n')
                words = content.split()
                return ext, {'lines': len(lines), 'words': len(words), 'characters': len(content)}, Counter()

        elif ext == '.csv':
            unique_values = Counter()
            with open(file_path, newline='') as csvfile:
                reader = csv.reader(csvfile)
                for row in reader:
                    unique_values.update(row)  # Track each cell's uniqueness
            return ext, {'lines': sum(1 for _ in csvfile), 'words': len(unique_values.elements()), 'characters': sum(len(cell) for row in reader for cell in row)}, unique_values

        elif ext == '.gz' or ext == '.zip':
            if ext == '.gz':
                with gzip.open(file_path, 'rt') as f:
                    return process_file(f.name)

            if ext == '.zip':
                with zipfile.ZipFile(file_path) as z:
                    for name in z.namelist():
                        with z.open(name) as f:
                            file_type = os.path.splitext(name)[1]
                            if file_type in ['.txt', '.log', '.csv']:
                                return process_file(f.name)

        elif ext == '.html':
            with open(file_path, 'r') as f:
                content = f.read()
                soup = BeautifulSoup(content, 'html.parser')
                elements = soup.find_all(True)
                return ext, {'lines': len(elements), 'words': sum(len(e.get_text().split()) for e in elements),
                             'characters': sum(len(e.get_text()) for e in elements)}, Counter()

        else:
            logger.warning(f"Unsupported file type: {ext}")
            return '', {'lines': 0, 'words': 0, 'characters': 0}, Counter()
    except Exception as e:
        logger.error(f"Error processing file {file_path}: {str(e)}")
        return '', {'lines': 0, 'words': 0, 'characters': 0}, Counter()


def calculate_statistics(values: List[float]):
    if not values:
        return {}

    mean = statistics.mean(values)
    median = statistics.median(values)
    try:
        mode = statistics.mode(values)
    except statistics.StatisticsError:
        mode = "No unique mode found"

    return {'mean': mean, 'median': median, 'mode': mode}


def start_flask_app():
    app = Flask(__name__)

    @app.route('/stats', methods=['GET'])
    def get_stats():
        directory_path = request.args.get('directory')
        if not directory_path or not os.path.isdir(directory_path):
            return jsonify({'error': 'Invalid directory'}), 400

        file_stats, csv_unique_counts = process_directory(directory_path)

        # Calculate statistics for CSV columns
        csv_statistics = {
            col: calculate_statistics([float(val) for val in vals if val.replace('.', '', 1).isdigit()])
            for col, vals in csv_unique_counts.items()
        }

        return jsonify({
            'file_stats': file_stats,
            'csv_unique_counts': dict(csv_unique_counts),
            'csv_statistics': csv_statistics
        })

    app.run(debug=True)


if __name__ == '__main__':
    # Example usage:
    start_flask_app()
```

