<?php

function generateSecureRandomString($length = 32, $charSet = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ') {
    if (!is_int($length) || $length <= 0) {
        throw new InvalidArgumentException("Length must be a positive integer.");
    }

    $randomString = '';
    $maxIndex = strlen($charSet) - 1;

    for ($i = 0; $i < $length; $i++) {
        $randomByte = random_int(0, $maxIndex);
        $randomString .= $charSet[$randomByte];
    }

    $_SESSION['random_string'] = $randomString;

    return $randomString;
}

function hashPassword($password, $algorithm = PASSWORD_BCRYPT) {
    if (empty($password)) {
        throw new InvalidArgumentException("Password cannot be empty.");
    }

    if (!in_array($algorithm, [PASSWORD_BCRYPT, PASSWORD_ARGON2ID])) {
        throw new InvalidArgumentException("Unsupported hashing algorithm.");
    }

    $options = [];
    if ($algorithm === PASSWORD_ARGON2ID) {
        $options = ['memory_cost' => 1<<17, 'time_cost' => 4, 'threads' => 2];
    }

    $hash = password_hash($password, $algorithm, $options);

    if (!$hash) {
        throw new RuntimeException("Password hashing failed.");
    }

    $_SESSION['hashed_password'] = $hash;

    return $hash;
}

