import json
import asyncio
import aiohttp
from abc import ABC, abstractmethod
from concurrent.futures import ThreadPoolExecutor
from typing import Dict, Callable, Type
import logging
import time

logging.basicConfig(level=logging.INFO)

class ProductSerializable(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    @abstractmethod
    def from_json(cls, json_str: str):
        pass

class Electronics(ProductSerializable):
    def __init__(self, product_id: int, name: str, specs: Dict[str, str]):
        self.product_id = product_id
        self.name = name
        self.specs = specs

    def to_json(self) -> str:
        return json.dumps({'product_id': self.product_id, 'name': self.name, 'specs': self.specs})

    @classmethod
    def from_json(cls, json_str: str):
        data = json.loads(json_str)
        return cls(data['product_id'], data['name'], data['specs'])

class Books(ProductSerializable):
    def __init__(self, product_id: int, title: str, author: str):
        self.product_id = product_id
        self.title = title
        self.author = author

    def to_json(self) -> str:
        return json.dumps({'product_id': self.product_id, 'title': self.title, 'author': self.author})

    @classmethod
    def from_json(cls, json_str: str):
        data = json.loads(json_str)
        return cls(data['product_id'], data['title'], data['author'])

class ProductFactory:
    _registry: Dict[str, Callable[[str], ProductSerializable]] = {}

    @staticmethod
    def register_product_type(product_type: str, factory_func: Callable[[str], ProductSerializable]):
        ProductFactory._registry[product_type] = factory_func

    @staticmethod
    def create_instance(json_str: str) -> ProductSerializable:
        data = json.loads(json_str)
        product_type = data.get('type')
        if product_type in ProductFactory._registry:
            return ProductFactory._registry[product_type](json_str)
        raise ValueError(f"Unknown product type: {product_type}")

ProductFactory.register_product_type("electronics", Electronics.from_json)
ProductFactory.register_product_type("books", Books.from_json)

async def fetch_file_content(session, url):
    async with session.get(url) as response:
        return await response.text()

def parse_and_create(json_str: str):
    try:
        return ProductFactory.create_instance(json_str)
    except Exception as e:
        logging.error(f"Failed to create product instance: {e}")
        return None

async def load_file_async(file_path, session):
    retry_attempts = 3
    backoff_factor = 0.5

    for attempt in range(retry_attempts):
        try:
            async with aiohttp.ClientSession() as session:
                content = await fetch_file_content(session, file_path)
                return parse_and_create(content)
        except Exception as e:
            logging.error(f"Error loading {file_path}: {e}")
            time.sleep(backoff_factor * (2 ** attempt))

async def load_files_concurrently(file_paths):
    tasks = [load_file_async(fp) for fp in file_paths]
    return await asyncio.gather(*tasks)

def detect_circular_dependencies(files):
    # Placeholder for actual implementation
    pass

async def main():
    files_to_load = [
        "http://example.com/products/electronics1.json",
        "http://example.com/products/books1.json",
    ]

    # Detect circular dependencies before starting the load process
    detect_circular_dependencies(files_to_load)

    loaded_products = await load_files_concurrently(files_to_load)
    for product in loaded_products:
        if product:
            print(product.to_json())

if __name__ == "__main__":
    asyncio.run(main())
