Below is an example implementation of a C++ function to dynamically construct and initialize an octree data structure for a real-time simulation application:

```cpp
#include <iostream>
#include <vector>
#include <memory>
#include <mutex>
#include <condition_variable>

// Define constants for maximum depth and feature size
const int MAX_DEPTH = 10;
const float MIN_FEATURE_SIZE = 0.1f;

struct OctreeNode {
    bool isLeaf;
    std::unique_ptr<OctreeNode> children[8];
    std::vector<float> data; // Data to store, e.g., sensor readings or simulation states

    OctreeNode() : isLeaf(true) {}
};

class Octree {
private:
    OctreeNode root;
    int depth;
    float featureSize;

public:
    Octree(int initialDepth = 0, float initialFeatureSize = 1.0f)
        : depth(initialDepth), featureSize(initialFeatureSize) {}

    void insert(const std::vector<float>& point, const std::vector<float>& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        _insert(&root, point, data);
    }

    bool query(const std::vector<float>& point, std::vector<float>& result) {
        std::lock_guard<std::mutex> lock(mutex_);
        return _query(&root, point, result);
    }

private:
    void _insert(OctreeNode* node, const std::vector<float>& point, const std::vector<float>& data) {
        if (depth == MAX_DEPTH || featureSize <= MIN_FEATURE_SIZE) {
            node->data.push_back(data[0]); // Simplified: storing only one element
            return;
        }

        int index = _getOctantIndex(point);
        if (!node->children[index]) {
            node->children[index] = std::make_unique<OctreeNode>();
            node->isLeaf = false;
        }
        _insert(node->children[index].get(), point, data);

        // Reduce feature size and increase depth for children
        float newFeatureSize = featureSize / 2.0f;
        int newDepth = depth + 1;

        // Update local variables for recursive calls
        this->featureSize = newFeatureSize;
        this->depth = newDepth;
    }

    bool _query(OctreeNode* node, const std::vector<float>& point, std::vector<float>& result) {
        if (!node || node->isLeaf) {
            result.insert(result.end(), node->data.begin(), node->data.end());
            return !result.empty();
        }

        int index = _getOctantIndex(point);
        if (node->children[index]) {
            return _query(node->children[index].get(), point, result);
        }
        return false;
    }

    int _getOctantIndex(const std::vector<float>& point) {
        int index = 0;
        for (size_t i = 0; i < 3; ++i) {
            if (point[i] >= featureSize / 2.0f) {
                index |= (1 << i);
            }
        }
        return index;
    }

    std::mutex mutex_;
};

// Example usage
int main() {
    Octree octree;

    // Simulate insertion of data from external sources
    octree.insert({0.5, 0.5, 0.5}, {1.0});
    octree.insert({0.25, 0.25, 0.25}, {2.0});

    std::vector<float> result;
    if (octree.query({0.5, 0.5, 0.5}, result)) {
        for (float val : result) {
            std::cout << "Found: " << val << std::endl;
        }
    } else {
        std::cout << "No data found." << std::endl;
    }

    return 0;
}
```

