using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text.Json;
using System.Threading.Tasks;

public interface IDynamicRandomGeneratorConfigService
{
    Task<CustomDistribution> FetchDistributionAsync(string distributionId);
    Task UpdateRangeLimitsAsync(int min, int max);
}

public class DynamicRandomGenerator
{
    private static readonly HttpClient httpClient = new HttpClient();
    private ConcurrentDictionary<string, CustomDistribution> _distributionsCache;
    private Random _random;
    private Range _range;

    public DynamicRandomGenerator()
    {
        _distributionsCache = new ConcurrentDictionary<string, CustomDistribution>();
        _random = new Random(); // Replace with a secure random generator if needed
        _range = new Range { Min = int.MinValue, Max = int.MaxValue };
    }

    public async Task InitializeAsync(string configServerUrl)
    {
        try
        {
            var response = await httpClient.GetAsync(configServerUrl);
            response.EnsureSuccessStatusCode();
            var config = JsonSerializer.Deserialize<GeneratorConfig>(await response.Content.ReadAsStringAsync());

            // Set initial range and distributions from the server
            _range.Min = config.Range.Min;
            _range.Max = config.Range.Max;

            foreach (var dist in config.Distributions)
            {
                _distributionsCache[dist.Id] = new CustomDistribution(dist.Function);
            }
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
        }
    }

    public async Task<int> GenerateIntAsync(string distributionId = null)
    {
        var distribution = await GetDistributionAsync(distributionId);
        return distribution.Generate(_range, _random);
    }

    public async Task<double> GenerateDoubleAsync(string distributionId = null)
    {
        var distribution = await GetDistributionAsync(distributionId);
        return distribution.Generate(_range, _random);
    }

    private async Task<CustomDistribution> GetDistributionAsync(string distributionId)
    {
        if (string.IsNullOrEmpty(distributionId) || !_distributionsCache.TryGetValue(distributionId, out var cachedDistribution))
        {
            // Fetch from server or database
            cachedDistribution = await new HttpConfigService().FetchDistributionAsync(distributionId);
            _distributionsCache[distributionId] = cachedDistribution;
        }
        return cachedDistribution;
    }

    private void LogError(string message)
    {
        // Implement logging mechanism
        Console.WriteLine($"Error: {message}");
    }
}

public class Range
{
    public int Min { get; set; }
    public int Max { get; set; }
}

public class CustomDistribution
{
    private Func<int, Random, int> _distributionFunction;

    public CustomDistribution(string function)
    {
        // Parse and compile the distribution function from string
        _distributionFunction = (min, random) =>
        {
            // Example implementation for a uniform distribution
            return min + random.Next(0, (_range.Max - _range.Min));
        };
    }

    public int Generate(Range range, Random random)
    {
        return _distributionFunction.Invoke(range.Min, random);
    }
}

public class GeneratorConfig
{
    public Range Range { get; set; }
    public CustomDistribution[] Distributions { get; set; }
}

public class HttpConfigService : IDynamicRandomGeneratorConfigService
{
    private readonly HttpClient httpClient = new HttpClient();

    public async Task<CustomDistribution> FetchDistributionAsync(string distributionId)
    {
        var response = await httpClient.GetAsync($"https://configserver.com/distribution/{distributionId}");
        response.EnsureSuccessStatusCode();
        var distData = await response.Content.ReadAsStringAsync();

        return new CustomDistribution(distData);
    }

    public async Task UpdateRangeLimitsAsync(int min, int max)
    {
        var rangeUpdate = JsonSerializer.Serialize(new { Min = min, Max = max });
        var content = new StringContent(rangeUpdate, Encoding.UTF8, "application/json");
        await httpClient.PutAsync("https://configserver.com/range", content);
    }
}
