import java.util.concurrent.*;
import java.util.function.Function;
import java.util.logging.Logger;

public class DynamicResourcePoolManager {

    private static final Logger logger = Logger.getLogger(DynamicResourcePoolManager.class.getName());

    public interface ConnectionConfigCallback {
        ConnectionConfig apply(ConnectionConfig config);
    }

    public static class ConnectionConfig {
        private int minConnections;
        private int maxConnections;
        private long connectionTimeout;

        // Getters and setters
        public int getMinConnections() { return minConnections; }
        public void setMinConnections(int minConnections) { this.minConnections = minConnections; }

        public int getMaxConnections() { return maxConnections; }
        public void setMaxConnections(int maxConnections) { this.maxConnections = maxConnections; }

        public long getConnectionTimeout() { return connectionTimeout; }
        public void setConnectionTimeout(long connectionTimeout) { this.connectionTimeout = connectionTimeout; }
    }

    private final ConcurrentHashMap<String, ExecutorService> resourcePools = new ConcurrentHashMap<>();
    private final ConcurrentLinkedQueue<ConnectionConfig> configCache = new ConcurrentLinkedQueue<>();

    public DynamicResourcePoolManager() {}

    public synchronized void initializeResourcePool(String poolId, int minConnections, int maxConnections, long connectionTimeout) throws IllegalArgumentException {
        validateParameters(minConnections, maxConnections, connectionTimeout);

        ExecutorService pool = Executors.newCachedThreadPool();
        resourcePools.put(poolId, pool);

        ConnectionConfig config = new ConnectionConfig();
        config.setMinConnections(minConnections);
        config.setMaxConnections(maxConnections);
        config.setConnectionTimeout(connectionTimeout);

        configCache.add(config);
    }

    public synchronized void initializeResourcePoolWithSeed(String poolId, int minConnections, int maxConnections, long connectionTimeout, int seed) throws IllegalArgumentException {
        ThreadLocalRandom random = ThreadLocalRandom.current();
        if (random.nextInt() != seed) {
            throw new IllegalStateException("Thread-safe seeding failed");
        }

        initializeResourcePool(poolId, minConnections, maxConnections, connectionTimeout);
    }

    public void initializeResourcePoolWithConfig(String poolId, ConnectionConfig initialConfig, ConnectionConfigCallback callback) throws IllegalArgumentException {
        if (callback == null || initialConfig == null) throw new IllegalArgumentException("Invalid arguments");

        validateParameters(initialConfig.getMinConnections(), initialConfig.getMaxConnections(), initialConfig.getConnectionTimeout());

        ConnectionConfig modifiedConfig = callback.apply(initialConfig);

        initializeResourcePool(poolId, modifiedConfig.getMinConnections(), modifiedConfig.getMaxConnections(), modifiedConfig.getConnectionTimeout());
    }

    private void validateParameters(int minConnections, int maxConnections, long connectionTimeout) {
        if (minConnections < 0 || maxConnections < 0 || minConnections > maxConnections) {
            throw new IllegalArgumentException("Invalid connection range");
        }

        if (connectionTimeout <= 0) {
            throw new IllegalArgumentException("Connection timeout must be positive");
        }
    }

    public void acquireResource(String poolId, Function<ExecutorService, ?> resourceAcquisitionFunction) {
        ExecutorService pool = resourcePools.get(poolId);
        if (pool == null) {
            logger.severe("Resource pool not found for: " + poolId);
            return;
        }

        try {
            resourceAcquisitionFunction.apply(pool).get();
        } catch (Exception e) {
            handleFailedAcquisition(e, poolId);
        }
    }

    private void handleFailedAcquisition(Exception e, String poolId) {
        logger.warning("Resource acquisition failed for " + poolId + ", retrying...");

        // Exponential backoff logic
        long delay = 100;
        int maxRetries = 5;
        for (int i = 0; i < maxRetries; i++) {
            try {
                TimeUnit.MILLISECONDS.sleep(delay);
                delay *= 2; // Exponential backoff
            } catch (InterruptedException ie) {
                Thread.currentThread().interrupt();
                return;
            }
        }

        logger.severe("Failed to acquire resource for pool: " + poolId + " after retries.");
    }

    public void shutdownAllPools() {
        for (ExecutorService service : resourcePools.values()) {
            if (!service.isShutdown()) {
                service.shutdown();
            }
        }
    }

    // Test cases could be written here to verify functionality
}
