```python
import os
import logging
from logging.handlers import TimedRotatingFileHandler
import requests
from retrying import retry
import threading
import queue
import time

class MicroserviceLogger:
    def __init__(self, service_name, env_variables):
        self.service_name = service_name
        self.env_variables = env_variables
        self.log_queue = queue.Queue()
        self.configure_logging()

    @retry(stop_max_attempt_number=5, wait_fixed=2000)
    def create_log_directory(self, path):
        os.makedirs(path, exist_ok=True)

    def configure_logging(self):
        log_level = self.env_variables.get("LOG_LEVEL", "INFO").upper()
        log_format = self.env_variables.get("LOG_FORMAT", "%(asctime)s - %(name)s - %(levelname)s - %(message)s")

        logger = logging.getLogger(self.service_name)
        logger.setLevel(log_level)

        log_dir = os.path.join(self.env_variables["BASE_LOG_DIR"], self.service_name)
        self.create_log_directory(log_dir)

        log_file_path = os.path.join(log_dir, f"{self.service_name}.log")
        handler = TimedRotatingFileHandler(log_file_path, when="midnight", interval=1)

        formatter = logging.Formatter(log_format)
        handler.setFormatter(formatter)

        logger.addHandler(handler)

        self.logger = logger
        threading.Thread(target=self.log_rotation_worker).start()

    def log_message(self, level, message):
        if hasattr(self.logger, level.lower()):
            getattr(self.logger, level.lower())(message)

    def log_rotation_worker(self):
        while True:
            try:
                level, message = self.log_queue.get(timeout=1)
                self.log_message(level, message)
            except queue.Empty:
                continue

    def enqueue_log(self, level, message):
        self.log_queue.put((level, message))

    def integrate_external_logging(self, external_service_url):
        def send_logs():
            while True:
                try:
                    if not self.log_queue.empty():
                        log_data = []
                        while not self.log_queue.empty():
                            log_data.append(self.log_queue.get())
                        requests.post(external_service_url, json=log_data)
                except requests.RequestException as e:
                    time.sleep(5)  # Retry after failure
                time.sleep(10)

        threading.Thread(target=send_logs).start()

    def set_permissions_and_ownership(self, path):
        uid = os.getuid()
        gid = os.getgid()
        for root, dirs, files in os.walk(path):
            for d in dirs:
                os.chown(os.path.join(root, d), uid, gid)
            for f in files:
                os.chown(os.path.join(root, f), uid, gid)

    def monitor_and_manage(self):
        # This method could be extended to include interfaces or dashboards
        pass

# Usage example:
env_vars = {
    "BASE_LOG_DIR": "/var/log/microservices",
    "LOG_LEVEL": "DEBUG",
    "LOG_FORMAT": "%(asctime)s - %(name)s - %(levelname)s - %(message)s"
}

service_logger = MicroserviceLogger("example_service", env_vars)
service_logger.enqueue_log("INFO", "Service started successfully.")
service_logger.integrate_external_logging("http://log-aggregator.example.com")

# Set permissions
log_dir = os.path.join(env_vars["BASE_LOG_DIR"], service_logger.service_name)
service_logger.set_permissions_and_ownership(log_dir)

```

This code provides a robust framework for initializing and managing logging in a highly scalable microservices architecture. It handles concurrent access using queues, retry mechanisms for directory creation, log rotation with `TimedRotatingFileHandler`, and integrates real-time log aggregation with external services using HTTP requests. The function also manages file permissions and ownership dynamically.

