    private Map<String, Object> dataCache = new HashMap<>();

    public Vehicle(String id) {
        this.id = id;
    }

    public abstract void manageBattery();

    public abstract double calculateFuelEfficiency();

    protected void cacheData(Map<String, Object> data) {
        dataCache.putAll(data);
    }

    protected Map<String, Object> getCachedData() {
        return dataCache;
    }

    // Custom binary serialization
    public byte[] serializeToBinary() throws IOException {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(bos)) {
            oos.writeObject(this);
            return bos.toByteArray();
        }
    }

    // Custom binary deserialization
    public static Vehicle deserializeFromBinary(byte[] data) throws IOException, ClassNotFoundException {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return (Vehicle) ois.readObject();
        }
    }
}

