// Factory registry for vehicle creation
class VehicleFactoryRegistry {
    private final Map<String, Function<Void, Vehicle>> factoryMap = new ConcurrentHashMap<>();

    public void addFactory(String id, Function<Void, Vehicle> factory) {
        factoryMap.put(id, factory);
    }

    public void updateFactory(String id, Function<Void, Vehicle> factory) {
        factoryMap.replace(id, factory);
    }

    public void removeFactory(String id) {
        factoryMap.remove(id);
    }

    public Vehicle createVehicle(String id) {
        if (factoryMap.containsKey(id)) {
            return factoryMap.get(id).apply(null);
        }
        throw new IllegalArgumentException("No factory found for ID: " + id);
    }

    public Collection<String> listFactories() {
        return Collections.unmodifiableCollection(factoryMap.keySet());
    }
}

// Vehicle Manager class
class VehicleManager {
    private final VehicleFactoryRegistry registry;
    private final ObjectMapper objectMapper = new ObjectMapper();
    private final Map<String, Long> vehicleDataLastUpdated = new ConcurrentHashMap<>();

    public VehicleManager(VehicleFactoryRegistry registry) {
        this.registry = registry;
    }

    // Fetch and update vehicle data from the API
    public void fetchVehicleData(String vehicleId) throws IOException {
        URL url = new URL("http://api.example.com/vehicles/" + vehicleId);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();

        if (conn.getResponseCode() == 200) {
            String response = new BufferedReader(new InputStreamReader(conn.getInputStream()))
                               .lines().reduce("", String::concat);

            Map<String, Object> vehicleData = objectMapper.readValue(response, Map.class);

            // Schema version check and update logic
            int currentSchemaVersion = 1; // Assume current schema version
            if (vehicleData.containsKey("schema_version")) {
                int apiSchemaVersion = Integer.parseInt(vehicleData.get("schema_version").toString());
                if (apiSchemaVersion > currentSchemaVersion) {
                    upgradeSchema(vehicleId, vehicleData);
                }
            }

            Vehicle vehicle = registry.createVehicle(vehicleId);
            vehicle.cacheData(vehicleData);

            // Cache the data with timestamp
            vehicleDataLastUpdated.put(vehicleId, System.currentTimeMillis());

            logEvent("Fetched and updated vehicle data for ID: " + vehicleId);
        } else {
            handleError(conn.getResponseCode(), "Failed to fetch vehicle data.");
        }
    }

    private void upgradeSchema(String vehicleId, Map<String, Object> vehicleData) {
        // Schema migration logic
        logEvent("Upgraded schema for vehicle ID: " + vehicleId);
    }

    public void periodicUpdate() throws IOException {
        registry.listFactories().forEach(vehicleId -> {
            try {
                if (shouldUpdateVehicleData(vehicleId)) {
                    fetchVehicleData(vehicleId);
                }
            } catch (IOException e) {
                handleError(500, "Error during periodic update for vehicle ID: " + vehicleId);
            }
        });
    }

    private boolean shouldUpdateVehicleData(String vehicleId) {
        Long lastUpdated = vehicleDataLastUpdated.get(vehicleId);
        return lastUpdated == null || System.currentTimeMillis() - lastUpdated > 60000; // Update if older than 1 minute
    }

    private void logEvent(String message) {
        // Implement logging logic, possibly integrate with a centralized logging system
        System.out.println(message);
    }

    private void handleError(int errorCode, String errorMessage) {
        // Custom error handling and logging
        System.err.println("Error " + errorCode + ": " + errorMessage);
    }
}

public class Main {
    public static void main(String[] args) throws IOException, ClassNotFoundException {
        VehicleFactoryRegistry factoryRegistry = new VehicleFactoryRegistry();

        // Registering factories for different vehicle types
        factoryRegistry.addFactory("electric", id -> new ElectricCar(id));
        factoryRegistry.addFactory("hybrid", id -> new HybridCar(id));
        factoryRegistry.addFactory("diesel", id -> new DieselCar(id));

        VehicleManager manager = new VehicleManager(factoryRegistry);

        // Fetch and update vehicle data
        try {
            manager.fetchVehicleData("electric1");
            manager.fetchVehicleData("hybrid2");
            manager.fetchVehicleData("diesel3");

            // Periodic updates for real-time changes
            manager.periodicUpdate();
        } catch (IOException e) {
            System.err.println("Error fetching vehicle data: " + e.getMessage());
        }
    }
}
