        obj.AddMember("value", rapidjson::Value(node.value.c_str(), allocator).Move(), allocator);
        obj.AddMember("versionID", node.versionID, allocator);
        doc.PushBack(obj, allocator);
    }

    rapidjson::StringBuffer buffer;
    rapidjson::Writer<rapidjson::StringBuffer> writer(buffer);
    doc.Accept(writer);

    return buffer.GetString();
