// OctreeNode definition
class OctreeNode {
public:
    struct DataPoint {
        float x, y, z; // Example spatial coordinates
        // Additional data fields can be added here
    };

    std::unique_ptr<OctreeNode> children[8];
    std::vector<DataPoint> points;
