// Task for rebalancing or BVH update
using TaskFunc = std::function<void()>;

class Octree {
private:
    std::unique_ptr<OctreeNode> root;
    size_t maxCapacityPerNode;
    std::atomic<int> insertionCount;
    int maxConcurrentOperations;
    std::mutex octreeMutex;
    std::condition_variable operationCondVar;
    std::queue<TaskFunc> taskQueue;
    bool stopping = false;

    void insertPoint(const OctreeNode::DataPoint& point, OctreeNode* node);
    void deletePoint(const OctreeNode::DataPoint& point, OctreeNode* node);
    void rebalance();
    void updateBVH();

public:
    explicit Octree(size_t capacityPerNode = 10, int maxOps = 4)
        : root(std::make_unique<OctreeNode>()), 
          maxCapacityPerNode(capacityPerNode),
          insertionCount(0), maxConcurrentOperations(maxOps) {}

    void loadData(const std::string& dataSourceType, const std::vector<OctreeNode::DataPoint>& points);
    void insertPoint(const OctreeNode::DataPoint& point);
    void deletePoint(const OctreeNode::DataPoint& point);

    void startBackgroundTaskProcessing();
    void stopBackgroundTaskProcessing();

private:
    static bool isWithinBounds(const OctreeNode::DataPoint& point, const OctreeNode* node);
};

bool Octree::isWithinBounds(const OctreeNode::DataPoint& point, const OctreeNode* node) {
    // Implement bounds checking logic
    return true; // Placeholder implementation
}

void Octree::insertPoint(const OctreeNode::DataPoint& point) {
    std::unique_lock<std::mutex> lock(octreeMutex);

    if (root->isLeaf && root->points.size() < maxCapacityPerNode) {
        root->points.push_back(point);
    } else {
        // Insert logic for non-leaf or full leaf node
        insertPoint(point, root.get());
    }

    insertionCount++;
    if (insertionCount % 100 == 0) { // Example threshold for rebalancing
        taskQueue.push([this] { this->rebalance(); });
    }

    lock.unlock();
    operationCondVar.notify_one();
}

void Octree::deletePoint(const OctreeNode::DataPoint& point) {
    std::unique_lock<std::mutex> lock(octreeMutex);
    // Implement deletion logic here
    lock.unlock();
    operationCondVar.notify_one();
}

void Octree::rebalance() {
    std::lock_guard<std::mutex> guard(octreeMutex);
    // Rebalancing implementation
}

void Octree::updateBVH() {
    std::lock_guard<std::mutex> guard(octreeMutex);
    // BVH update logic here
}

void Octree::insertPoint(const OctreeNode::DataPoint& point, OctreeNode* node) {
    if (node->isLeaf && node->points.size() < maxCapacityPerNode) {
        node->points.push_back(point);
        return;
    }

    if (!node->isLeaf) {
        for (auto& child : node->children) {
            if (child && isWithinBounds(point, child.get())) {
                insertPoint(point, child.get());
                return;
            }
        }
    }

    // Create new children and distribute points
    node->isLeaf = false;
    std::vector<OctreeNode::DataPoint> distributedPoints(std::move(node->points));
    node->points.clear();

    for (auto& p : distributedPoints) {
        if (isWithinBounds(p, node)) {
            insertPoint(p, node);
        }
    }
}

void Octree::loadData(const std::string& dataSourceType, const std::vector<OctreeNode::DataPoint>& points) {
    if (dataSourceType != "CSV" && dataSourceType != "database") {
        throw std::invalid_argument("Invalid data source type");
    }

    for (const auto& point : points) {
        insertPoint(point);
    }
}

void Octree::startBackgroundTaskProcessing() {
    std::thread([this] {
        while (!stopping || !taskQueue.empty()) {
            TaskFunc task;
            {
                std::unique_lock<std::mutex> lock(octreeMutex);
                operationCondVar.wait(lock, [this]{ return stopping || !taskQueue.empty(); });

                if (taskQueue.empty() && stopping) break;

                task = std::move(taskQueue.front());
                taskQueue.pop();
            }

            // Execute the task
            task();
        }
    }).detach();
}

void Octree::stopBackgroundTaskProcessing() {
    {
        std::unique_lock<std::mutex> lock(octreeMutex);
        stopping = true;
    }
    operationCondVar.notify_all();
}
