```python
import os
import json
import yaml
from threading import Lock, Thread
from typing import Any, Callable, Dict, Optional
import time
import requests

class ConfigManager:
    def __init__(self, config_file_path: str, fallback_api_url: str = None):
        self.config_file_path = config_file_path
        self.fallback_api_url = fallback_api_url
        self.config_data = {}
        self.last_modified_time = 0
        self.lock = Lock()
        self.cache_ttl = 60  # seconds
        self.cache_expiry_time = time.time()

        self.load_config() 
        self.start_monitor_thread()

    def load_config(self):
        try:
            if self._file_exists_and_changed():
                with open(self.config_file_path, 'r') as f:
                    ext = os.path.splitext(self.config_file_path)[1].lower()
                    if ext == '.json':
                        new_data = json.load(f)
                    elif ext in ['.yaml', '.yml']:
                        new_data = yaml.safe_load(f)
                    else:
                        raise ValueError("Unsupported file format")

                with self.lock:
                    self.config_data = new_data
                    self.last_modified_time = os.path.getmtime(self.config_file_path)

        except Exception as e:
            print(f"Failed to load config from {self.config_file_path}: {e}")
            if self.fallback_api_url:
                self.load_from_fallback_api()

    def _file_exists_and_changed(self) -> bool:
        return os.path.exists(self.config_file_path) and \
               (time.time() - self.cache_expiry_time > self.cache_ttl or
                os.path.getmtime(self.config_file_path) != self.last_modified_time)

    def load_from_fallback_api(self):
        try:
            response = requests.get(self.fallback_api_url)
            if response.status_code == 200:
                with self.lock:
                    self.config_data = response.json()
            else:
                print(f"Failed to fetch config from API: {response.status_code}")
        except Exception as e:
            print(f"Error fetching config from fallback API: {e}")

    def start_monitor_thread(self):
        def monitor():
            while True:
                time.sleep(1)  # Check every second
                self.load_config()

        Thread(target=monitor, daemon=True).start()

    def get_config(self, key: str, default: Any = None) -> Any:
        with self.lock:
            return self.config_data.get(key, default)

    def update_config(self, new_data: Dict[str, Any]):
        with self.lock:
            self.config_data.update(new_data)
            self.cache_expiry_time = time.time()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        pass  # Perform any necessary cleanup here

# Usage Example
if __name__ == "__main__":
    config_manager = ConfigManager("config.yaml", "https://api.example.com/config")

    # Access configuration settings
    database_url = config_manager.get_config('database_url', 'sqlite:///default.db')
    print(f"Database URL: {database_url}")

    # Update configuration dynamically
    config_manager.update_config({'debug': True})

# Documentation:
# - The `ConfigManager` class handles configurations in YAML and JSON formats, along with environment variables.
# - It supports dynamic updates by monitoring file changes and loading configurations from an external API if necessary.
# - Access the current configuration using `get_config`, or update it via `update_config`.
# - Use this manager in a multi-process environment safely due to its thread-safe mechanisms.
