use std::path::{Path, PathBuf};
use std::process::{Command, ExitStatus};
use std::time::{Duration, Instant};
use sysinfo::{System, SystemExt, ProcessorExt, MemoryExt};
use tokio::task;
use reqwest::Client;
use anyhow::{Result, Context};

#[derive(Debug)]
struct CompileResult {
    submodule: String,
    exit_code: Option<i32>,
    duration: Duration,
    peak_rss: u64, // in KB
}

async fn compile_submodule(submodule_path: &Path) -> Result<CompileResult> {
    let start_time = Instant::now();
    let output = Command::new("cargo")
        .arg("build")
        .current_dir(submodule_path)
        .output()?;

    let duration = start_time.elapsed();

    let exit_status = ExitStatus::from(output.status);

    // Dummy peak_rss, actual implementation would require profiling or OS-specific tools
    let peak_rss = 1024; // Placeholder value

    Ok(CompileResult {
        submodule: submodule_path.display().to_string(),
        exit_code: match exit_status.success() { 
            true => None,
            false => Some(exit_status.code().unwrap_or(-1)),
        },
        duration,
        peak_rss,
    })
}

async fn log_to_ci(submodule: &str, start_time: Instant, duration: Duration, exit_code: Option<i32>, error_details: Option<String>) -> Result<()> {
    let client = Client::new();
    let payload = json!({
        "submodule": submodule,
        "start_time": start_time.elapsed().as_secs(),
        "duration_ms": duration.as_millis(),
        "exit_code": exit_code,
        "error_details": error_details
    });

    client.post("https://ci-cd.example.com/log")
          .json(&payload)
          .send()
          .await?
          .error_for_status()?;

    Ok(())
}

async fn compile_project(root_dir: &Path) -> Result<Vec<CompileResult>> {
    let system = System::new_all();
    let num_cores = system.get_processors().len() as usize;
    let total_memory_kb = system.get_total_memory();

    let submodules = find_submodules(root_dir)?;
    let mut results = Vec::with_capacity(submodules.len());

    let tasks: Vec<_> = submodules.into_iter()
        .enumerate()
        .map(|(i, submodule)| {
            let start_time = Instant::now();
            task::spawn(async move {
                match compile_submodule(&submodule).await {
                    Ok(result) => {
                        if let Err(e) = log_to_ci(
                            &result.submodule,
                            start_time,
                            result.duration,
                            result.exit_code,
                            None, // Error details can be fetched from `e` in a real implementation
                        ).await {
                            eprintln!("Failed to log CI/CD: {:?}", e);
                        }
                    },
                    Err(e) => {
                        if let Err(log_e) = log_to_ci(
                            &submodule.display().to_string(),
                            start_time,
                            Duration::new(0, 0),
                            None,
                            Some(format!("{:?}", e)),
                        ).await {
                            eprintln!("Failed to log CI/CD error: {:?}", log_e);
                        }
                    }
                }

                Ok::<_, anyhow::Error>(compile_submodule(&submodule).await?)
            })
        })
        .collect();

    for task in tasks.into_iter().take(num_cores) {
        if let Ok(result) = task.await {
            results.push(result?);
        }
    }

    Ok(results)
}

fn find_submodules(root_dir: &Path) -> Result<Vec<PathBuf>> {
    // Assuming submodules are directories containing a Cargo.toml file
    let mut submodules = Vec::new();
    for entry in root_dir.read_dir()? {
        let path = entry?.path();
        if path.is_dir() && path.join("Cargo.toml").exists() {
            submodules.push(path);
        }
    }

    Ok(submodules)
}

#[tokio::main]
async fn main() -> Result<()> {
    let root_directory = Path::new("./src");
    match compile_project(root_directory).await {
        Ok(results) => {
            for result in results {
                println!("{:?}", result);
            }
        },
        Err(e) => eprintln!("Compilation failed: {:?}", e),
    }

    Ok(())
}
```

