```cpp
#include <iostream>
#include <memory>
#include <mutex>
#include <thread>
#include <vector>
#include <unordered_map>
#include <queue>

// Define a structure for spatial data
struct SpatialData {
    float x, y, z;
    int sensorID; // Sensor identifier
};

// Node of the octree
class OctreeNode {
public:
    bool isLeaf;
    std::unique_ptr<OctreeNode> children[8];
    std::vector<SpatialData> data;

    OctreeNode() : isLeaf(true) {}
};

// Octree class definition
class Octree {
private:
    std::unique_ptr<OctreeNode> root;
    float boundaryMin[3], boundaryMax[3];
    int maxDepth, currentNodeCount;

    std::mutex treeMutex;

    void insert(const SpatialData& data, OctreeNode* node, const float bounds[6], int depth);
    bool pointInsideBounds(const float x, const float y, const float z, const float bounds[6]) const;
    int getChildIndex(const float x, const float y, const float z, const float bounds[6]);

public:
    Octree(float minX, float minY, float minZ, float maxX, float maxY, float maxZ, int depth)
        : root(std::make_unique<OctreeNode>()), maxDepth(depth), currentNodeCount(0) {
        boundaryMin[0] = minX; boundaryMin[1] = minY; boundaryMin[2] = minZ;
        boundaryMax[0] = maxX; boundaryMax[1] = maxY; boundaryMax[2] = maxZ;
    }

    void insert(const SpatialData& data);
    void updateFromSensor(std::vector<SpatialData> sensorData, int sensorID);

    // Example API function for spatial queries
    std::vector<SpatialData> queryRegion(float minX, float minY, float minZ, float maxX, float maxY, float maxZ) const;
};

// Implementation of private methods
void Octree::insert(const SpatialData& data, OctreeNode* node, const float bounds[6], int depth) {
    if (!pointInsideBounds(data.x, data.y, data.z, bounds)) return;

    // Check if this is a leaf node or need to subdivide
    if (depth == maxDepth || node->data.size() < 10) { // Leaf condition or small number of elements
        node->isLeaf = true;
        node->data.push_back(data);
    } else {
        if (node->isLeaf) {
            // Subdivide the current node into children
            std::vector<float> newBounds(6);
            for (int i = 0; i < 8; ++i) {
                int index = getChildIndex(bounds[0], bounds[1], bounds[2], bounds); // Compute correct child index
                computeChildBounds(newBounds, bounds, i);
                node->children[i] = std::make_unique<OctreeNode>();
            }
            node->isLeaf = false;

            // Reinsert existing data into children
            for (const auto& d : node->data) {
                insert(d, node.get(), newBounds.data(), depth + 1);
            }
            node->data.clear();
        }

        int childIndex = getChildIndex(data.x, data.y, data.z, bounds);
        if (!node->children[childIndex]) {
            std::vector<float> newBounds(6);
            computeChildBounds(newBounds, bounds, childIndex);
            node->children[childIndex] = std::make_unique<OctreeNode>();
        }
        insert(data, node->children[childIndex].get(), newBounds.data(), depth + 1);
    }
}

bool Octree::pointInsideBounds(const float x, const float y, const float z, const float bounds[6]) const {
    return (x >= bounds[0] && x <= bounds[3] &&
            y >= bounds[1] && y <= bounds[4] &&
            z >= bounds[2] && z <= bounds[5]);
}

int Octree::getChildIndex(const float x, const float y, const float z, const float bounds[6]) {
    int index = 0;
    if (x > (bounds[0] + bounds[3]) / 2) index |= 4;
    if (y > (bounds[1] + bounds[4]) / 2) index |= 2;
    if (z > (bounds[2] + bounds[5]) / 2) index |= 1;
    return index;
}

// Public methods
void Octree::insert(const SpatialData& data) {
    std::lock_guard<std::mutex> lock(treeMutex);
    insert(data, root.get(), {boundaryMin[0], boundaryMin[1], boundaryMin[2],
                              boundaryMax[0], boundaryMax[1], boundaryMax[2]}, 0);
}

void Octree::updateFromSensor(std::vector<SpatialData> sensorData, int /*sensorID*/) {
    for (const auto& data : sensorData) {
        insert(data);
    }
}

std::vector<SpatialData> Octree::queryRegion(float minX, float minY, float minZ,
                                             float maxX, float maxY, float maxZ) const {
    std::vector<SpatialData> result;
    // Placeholder for query logic
    return result;
}

// Helper function to compute child bounds based on index
void computeChildBounds(std::vector<float>& newBounds, const float parentBounds[6], int index) {
    float midX = (parentBounds[0] + parentBounds[3]) / 2.0f;
    float midY = (parentBounds[1] + parentBounds[4]) / 2.0f;
    float midZ = (parentBounds[2] + parentBounds[5]) / 2.0f;

    newBounds[0] = (index & 4) ? midX : parentBounds[0];
    newBounds[1] = (index & 2) ? midY : parentBounds[1];
    newBounds[2] = (index & 1) ? midZ : parentBounds[2];

    newBounds[3] = (index & 4) ? parentBounds[3] : midX;
    newBounds[4] = (index & 2) ? parentBounds[4] : midY;
    newBounds[5] = (index & 1) ? parentBounds[5] : midZ;
}

int main() {
    Octree octree(-1000, -1000, -1000, 1000, 1000, 1000, 10);

    // Simulate sensor data updates
    std::vector<SpatialData> sampleData = {{1.0f, 2.0f, 3.0f, 101}, {4.5f, 6.7f, 8.9f, 102}};
    octree.updateFromSensor(sampleData, 1);

    // Example query
    auto results = octree.queryRegion(0, 0, 0, 10, 10, 10);

    return 0;
}
