using System.Linq;
using System.Net.Http;
using System.Security.Cryptography.X509Certificates;
using System.Text.Json;
using System.Threading.Tasks;

class Program
{
    static async Task Main(string[] args)
    {
        var servicePool = new ServicePool();

        if (args.Length == 0 || !args.All(File.Exists))
        {
            Console.WriteLine("Please provide valid CSV file paths.");
            return;
        }

        await ProcessFilesAsync(args, servicePool);

        // Dynamic site addition example
        string jsonConfig = "{\"ServiceUrl\":\"https://example.com/api\", \"Port\":443}";
        var config = JsonSerializer.Deserialize<RemoteServiceConfig>(jsonConfig);
        try
        {
            await servicePool.AddServiceAsync(config);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to add service: {ex.Message}");
        }

        // Example of fetching a random number sequence from the first available service
        if (servicePool.Services.Any())
        {
            var randomNumberSequence = await servicePool.GetRandomNumberSequenceAsync(10);
            Console.WriteLine(string.Join(", ", randomNumberSequence));
        }
    }

    static async Task ProcessFilesAsync(string[] filePaths, ServicePool pool)
    {
        var tasks = filePaths.Select(filePath => ProcessFileAsync(filePath, pool)).ToArray();
        await Task.WhenAll(tasks);
    }

    static async Task ProcessFileAsync(string filePath, ServicePool pool)
    {
        if (!File.Exists(filePath) || !IsAccessibleDirectory(Path.GetDirectoryName(filePath)))
        {
            Console.WriteLine($"Invalid file or directory: {filePath}");
            return;
        }

        // Simulate file processing
        await Task.Delay(100);
        Console.WriteLine($"Processed file: {filePath}");
    }

    static bool IsAccessibleDirectory(string path)
    {
        try
        {
            return Directory.Exists(path) && new DirectoryInfo(path).GetFiles().Length > 0;
        }
        catch
        {
            return false;
        }
    }
}

public class ServicePool
{
    private readonly ConcurrentBag<RemoteService> _services = new ConcurrentBag<RemoteService>();

    public IEnumerable<RemoteService> Services => _services;

    public async Task AddServiceAsync(RemoteServiceConfig config)
    {
        var service = new RemoteService(config);
        await service.Initialize();
        if (service.IsReady)
        {
            _services.Add(service);
        }
        else
        {
            throw new InvalidOperationException("Failed to initialize the remote service.");
        }
    }

    public async Task<int[]> GetRandomNumberSequenceAsync(int count)
    {
        var randomService = Services.FirstOrDefault(s => s.IsReady);

        if (randomService == null) 
            throw new InvalidOperationException("No available services.");

        return await randomService.GenerateRandomNumbersAsync(count);
    }
}

public class RemoteService
{
    private HttpClient _httpClient;
    public bool IsReady { get; private set; }

    public RemoteService(RemoteServiceConfig config)
    {
        // Initialize with configuration
    }

    public async Task Initialize()
    {
        try
        {
            _httpClient = new HttpClient();
            // Setup SSL, Authentication, etc.
            IsReady = true;
        }
        catch
        {
            IsReady = false;
        }
    }

    public async Task<int[]> GenerateRandomNumbersAsync(int count)
    {
        // Simulate calling an external API to generate random numbers using Mersenne Twister algorithm
        await Task.Delay(50);
        return Enumerable.Range(0, count).Select(i => new Random().Next()).ToArray();
    }
}

