    };

private:
    std::shared_ptr<Node> root;
    mutable std::shared_mutex mutex_;
    HashAlgorithm hash_algorithm_ = HashAlgorithm::MD5;

    void insertNode(const std::string& point) {
        // Implement insertion logic with fine-grained locking
    }

    void queryNode(const std::string& range) {
        // Implement querying logic with fine-grained locking
    }

public:
    AdvancedOctreeManager() : root(std::make_shared<Node>()) {}

    void insert(const std::string& point) {
        std::unique_lock lock(mutex_);
        insertNode(point);
    }

    void query(const std::string& range, std::vector<std::string>& results) const {
        std::shared_lock lock(mutex_);
        queryNode(range);  // Modify to populate 'results'
    }

    void compileStatistics(const fs::path& directoryPath,
                           const fs::path& outputPath = "",
                           const std::chrono::system_clock::time_point& filterDate = std::chrono::system_clock::now(),
                           size_t minFileSize = 0) {
        size_t totalLines = 0, totalWords = 0, totalChars = 0;

        for (const auto& entry : fs::recursive_directory_iterator(directoryPath)) {
            if (!entry.is_regular_file()) continue;

            const auto ext = entry.path().extension();
            if (ext == ".md" || ext == ".pdf") continue;

            std::ifstream file(entry.path());
            if (!file) continue;

            auto lastWriteTime = fs::last_write_time(entry);
            auto fileSize = fs::file_size(entry);

            if (lastWriteTime < filterDate || fileSize < minFileSize) continue;

            std::string line;
            while (std::getline(file, line)) {
                totalLines++;
                totalChars += line.size() + 1; // Add 1 for newline character
                size_t wordCount = 0;
                std::istringstream iss(line);
                std::string word;
                while (iss >> word) wordCount++;
                totalWords += wordCount;
            }
        }

        if (!outputPath.empty()) {
            std::ofstream output(outputPath);
            output << "Total Lines: " << totalLines
                   << "\nTotal Words: " << totalWords
                   << "\nTotal Characters: " << totalChars;
        } else {
            std::cout << "Total Lines: " << totalLines
                      << "\nTotal Words: " << totalWords
                      << "\nTotal Characters: " << totalChars;
        }
    }

    void setHashAlgorithm(HashAlgorithm algorithm) {
        hash_algorithm_ = algorithm;
    }

    static void runUnitTests() {
        // Implement unit tests for hashing methods and other functionalities
    }

private:
    void logMessage(const std::string& message) {
        // Implement logging using the chosen logging service or library
    }
};

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <directory_path> [output_file] [filter_date YYYY-MM-DD] [min_file_size]\n";
        return 1;
    }

    fs::path directoryPath(argv[1]);
    fs::path outputPath = (argc > 2) ? fs::path(argv[2]) : fs::path();
    std::chrono::system_clock::time_point filterDate = std::chrono::system_clock::now();

    if (argc > 3) {
        // Parse and set the filter date
    }

    size_t minFileSize = 0;
    if (argc > 4) {
        minFileSize = static_cast<size_t>(std::stoul(argv[4]));
    }

    AdvancedOctreeManager manager;
    manager.compileStatistics(directoryPath, outputPath, filterDate, minFileSize);

    return 0;
}
