import com.example.weatherapp.repository.WeatherRepository;
import java.time.Duration;

@Service
public class WeatherService {

    private final WeatherRepository weatherRepository;
    private final WeatherCache weatherCache;

    @Autowired
    public WeatherService(WeatherRepository weatherRepository, WeatherCache weatherCache) {
        this.weatherRepository = weatherRepository;
        this.weatherCache = weatherCache;
    }

    public Mono<WeatherData> getWeatherData(String location, String date) {
        return weatherCache.get(location, date)
                .switchIfEmpty(
                    weatherRepository.fetchFromApi(location, date)
                        .doOnSuccess(data -> weatherCache.put(location, date, data))
                        .retryWhen(Retry.backoff(3, Duration.ofSeconds(2)).jitter(0.7))
                );
    }
}

