package com.example.weatherapp.cache;

import org.springframework.stereotype.Component;
import reactor.core.publisher.Mono;
import com.example.weatherapp.data.WeatherData;
import java.time.Duration;
import java.util.concurrent.ConcurrentHashMap;

@Component
public class WeatherCache {

    private final ConcurrentHashMap<String, CacheEntry<WeatherData>> cache = new ConcurrentHashMap<>();

    public Mono<WeatherData> get(String location, String date) {
        String key = generateKey(location, date);
        CacheEntry<WeatherData> entry = cache.get(key);

        if (entry != null && Duration.between(entry.timestamp(), Instant.now()).compareTo(Duration.ofMinutes(10)) < 0) {
            return Mono.just(entry.data());
        }

        return Mono.empty();
    }

    public void put(String location, String date, WeatherData data) {
        String key = generateKey(location, date);
        cache.put(key, new CacheEntry<>(data));
    }

    private String generateKey(String location, String date) {
        return location + ":" + date;
    }
}

