import java.time.Instant;

public class CacheEntry<T> {

    private final T data;
    private final Instant timestamp;

    public CacheEntry(T data) {
        this.data = data;
        this.timestamp = Instant.now();
    }

    public T data() {
        return data;
    }

    public Instant timestamp() {
        return timestamp;
    }
}

