#include <iostream>
#include <random>
#include <chrono>
#include <string>
#include <fstream>
#include <sstream>
#include <unordered_set>
#include <mutex>
#include <stdexcept>

namespace SessionIDGenerator {

    class SecureRandom {
    public:
        SecureRandom();
        ~SecureRandom();

        static std::string generateUniqueSessionID();
        static bool checkIfSessionIDExists(const std::string& sessionId);

    private:
        static std::mt19937_64 rng;
        static std::mutex mtx;

        static void seedGenerator();
        static std::string base64Encode(const unsigned char* bytes, int length);
        static std::string generateRandomBytes(size_t size);

        static std::unordered_set<std::string> sessionIDCache;
    };

    // Static member variable initialization
    std::mt19937_64 SecureRandom::rng(0);  // Default seed value; will be updated in constructor.
    std::mutex SecureRandom::mtx;
    std::unordered_set<std::string> SecureRandom::sessionIDCache;

    SecureRandom::SecureRandom() {
        seedGenerator();
    }

    SecureRandom::~SecureRandom() {}

    void SecureRandom::seedGenerator() {
        unsigned int entropy = 0;

        // Gather time-based entropy
        auto now = std::chrono::high_resolution_clock::now().time_since_epoch();
        entropy ^= static_cast<unsigned int>(now.count());

        // Gather additional system entropy (Unix-like systems)
#ifdef _WIN32
        std::ifstream urandom("/dev/urandom", std::ios::binary);
#else
        std::ifstream urandom("/dev/urandom", std::ios::in | std::ios::binary);
#endif

        if (urandom) {
            entropy ^= static_cast<unsigned int>(std::random_device()());
            unsigned char buffer[4];
            urandom.read(reinterpret_cast<char*>(buffer), sizeof(buffer));
            entropy ^= *reinterpret_cast<unsigned int*>(buffer);
        } else {
            std::cerr << "Warning: Unable to read /dev/urandom for additional entropy." << std::endl;
        }

        std::seed_seq seed{entropy, static_cast<unsigned int>(now.count())};
        rng.seed(seed);
    }

    std::string SecureRandom::generateUniqueSessionID() {
        const size_t idLength = 22;
        const size_t byteLength = (idLength * 3) / 4; // Base64 length calculation

        std::lock_guard<std::mutex> lock(mtx);

        while (true) {
            auto randomBytes = generateRandomBytes(byteLength);
            auto sessionId = base64Encode(reinterpret_cast<const unsigned char*>(randomBytes.data()), byteLength);

            if (!checkIfSessionIDExists(sessionId)) {
                sessionIDCache.insert(sessionId);
                return sessionId;
            }
        }
    }

    bool SecureRandom::checkIfSessionIDExists(const std::string& sessionId) {
        // Check local cache first
        if (sessionIDCache.find(sessionId) != sessionIDCache.end()) {
            return true;
        }

        try {
            // Simulate a distributed database check
            // Example: queryDatabaseForSessionID(sessionId);
            return false;  // Placeholder for actual database checking logic
        } catch (const std::exception& e) {
            std::cerr << "Error checking session ID existence in the database: " << e.what() << std::endl;
            return true; // Assume it exists to prevent potential infinite loops
        }
    }

    std::string SecureRandom::base64Encode(const unsigned char* bytes, int length) {
        static const std::string base64_chars =
            "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
            "abcdefghijklmnopqrstuvwxyz"
            "0123456789+/";

        std::string encoded;
        int i = 0;
        int j = 0;
        unsigned char char_array_3[3];
        unsigned char char_array_4[4];

        while (length--) {
            char_array_3[i++] = *(bytes++);
            if (i == 3) {
                char_array_4[0] = (char_array_3[0] & 0xfc) >> 2;
                char_array_4[1] = ((char_array_3[0] & 0x03) << 4) + ((char_array_3[1] & 0xf0) >> 4);
                char_array_4[2] = ((char_array_3[1] & 0x0f) << 2) + ((char_array_3[2] & 0xc0) >> 6);
                char_array_4[3] = char_array_3[2] & 0x3f;

                for (i = 0; i < 4; ++i)
                    encoded += base64_chars[char_array_4[i]];
                i = 0;
            }
        }

        if (i) {
            for (j = i; j < 3; ++j)
                char_array_3[j] = '\0';

            char_array_4[0] = (char_array_3[0] & 0xfc) >> 2;
            char_array_4[1] = ((char_array_3[0] & 0x03) << 4) + ((char_array_3[1] & 0xf0) >> 4);
            char_array_4[2] = ((char_array_3[1] & 0x0f) << 2) + ((char_array_3[2] & 0xc0) >> 6);

            for (j = 0; j < i + 1; ++j)
                encoded += base64_chars[char_array_4[j]];

            while (i++ < 3)
                encoded += '=';
        }

        return encoded;
    }

    std::string SecureRandom::generateRandomBytes(size_t size) {
        std::vector<unsigned char> randomBytes(size);
        std::uniform_int_distribution<uint64_t> dist(0, UINT64_MAX);

        for (size_t i = 0; i < randomBytes.size(); ++i)
            randomBytes[i] = static_cast<unsigned char>(dist(rng));

        return std::string(randomBytes.begin(), randomBytes.end());
    }

} // namespace SessionIDGenerator

int main() {
    try {
        std::string uniqueSessionID = SessionIDGenerator::SecureRandom().generateUniqueSessionID();
        std::cout << "Generated Unique Session ID: " << uniqueSessionID << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Exception occurred during session ID generation: " << e.what() << std::endl;
    }

    return 0;
}
