#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>
#include <errno.h>

// Define a structure to hold semaphore details
typedef struct {
    sem_t *sem;
    int id;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} Semaphore;

// Function to log messages (stub for external logging system)
void log_message(const char* message) {
    printf("%s\n", message); // Replace with actual logging logic
}

// Array of semaphores and their management locks
#define MAX_SEMAPHORES 100
Semaphore semaphores[MAX_SEMAPHORES];
int semaphore_count = 0;
pthread_mutex_t global_lock;

// Initialize the global lock
void initialize_system() {
    pthread_mutex_init(&global_lock, NULL);
}

// Create a new semaphore with an initial value
int create_semaphore(int init_value) {
    if (semaphore_count >= MAX_SEMAPHORES) {
        log_message("Error: Max semaphores reached.");
        return -1;
    }

    Semaphore *s = &semaphores[semaphore_count];
    pthread_mutex_init(&s->lock, NULL);

    s->sem = malloc(sizeof(sem_t));
    if (s->sem == NULL) {
        log_message("Error: Memory allocation failed for semaphore.");
        return -1;
    }

    if (sem_init(s->sem, 0, init_value) != 0) {
        free(s->sem);
        log_message("Error: Semaphore initialization failed.");
        return -1;
    }

    s->id = semaphore_count++;
    pthread_mutex_lock(&global_lock);
    log_message("Semaphore created with ID: ");
    printf("%d\n", s->id);
    pthread_mutex_unlock(&global_lock);

    return s->id;
}

// Acquire a semaphore
int acquire_semaphore(int sem_id) {
    if (sem_id < 0 || sem_id >= semaphore_count) {
        log_message("Error: Invalid semaphore ID.");
        return -1;
    }

    Semaphore *s = &semaphores[sem_id];

    pthread_mutex_lock(&s->lock);
    if (sem_wait(s->sem) != 0) {
        pthread_mutex_unlock(&s->lock);
        log_message("Error: Failed to acquire semaphore.");
        return -1;
    }
    log_message("Semaphore acquired:");
    printf("%d\n", sem_id);

    pthread_mutex_unlock(&s->lock);
    return 0;
}

// Release a semaphore
int release_semaphore(int sem_id) {
    if (sem_id < 0 || sem_id >= semaphore_count) {
        log_message("Error: Invalid semaphore ID.");
        return -1;
    }

    Semaphore *s = &semaphores[sem_id];

    pthread_mutex_lock(&s->lock);
    if (sem_post(s->sem) != 0) {
        pthread_mutex_unlock(&s->lock);
        log_message("Error: Failed to release semaphore.");
        return -1;
    }
    log_message("Semaphore released:");
    printf("%d\n", sem_id);

    pthread_mutex_unlock(&s->lock);
    return 0;
}

// Cleanup all semaphores
void cleanup_semaphores() {
    for (int i = 0; i < semaphore_count; ++i) {
        Semaphore *s = &semaphores[i];
        if (s->sem != NULL) {
            sem_destroy(s->sem);
            free(s->sem);
            pthread_mutex_destroy(&s->lock);
        }
    }
}

// Prevent starvation by using a fairness mechanism
int acquire_semaphore_fair(int sem_id) {
    if (acquire_semaphore(sem_id) != 0) {
        log_message("Error: Semaphore acquisition failed. Retrying...");
        sleep(1); // Simple backoff strategy to prevent starvation
        return acquire_semaphore(sem_id);
    }
    return 0;
}

// User-friendly interface for semaphore management
void manage_semaphores() {
    initialize_system();

    int sem_id = create_semaphore(3); // Example creation
    if (sem_id >= 0) {
        acquire_semaphore_fair(sem_id); // Acquire with fairness
        release_semaphore(sem_id);
    }

    cleanup_semaphores();
}

// Main function for testing
int main() {
    manage_semaphores();
    return 0;
}
