            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [&] { return !testQueue.empty() || shutdown; });

            if (shutdown && testQueue.empty()) break;

            auto [testFunc, label, attackFunc, config] = testQueue.front();
            testQueue.pop();

            // Mock setup
            mockingLib.initialize(label, databaseConnection.retrieveConfig(moduleLabel));

            lock.unlock(); // Unlock before running the test to allow other threads to enqueue

            runTest(testFunc, label, attackFunc, config);

            // Reset mocks
            mockingLib.reset();
            resourceManager.cleanup();

            std::this_thread::sleep_for(std::chrono::milliseconds(cooldown)); // Cooldown period between tests
        }
    };

    for (int i = 0; i < maxConcurrentTests; ++i) {
        testQueue.emplace(nullptr, nullptr, nullptr, nullptr); // Placeholder to reserve space
        std::thread(workerThread).detach();
    }

    int currentLogLevel = loggingLevel == "verbose" ? 2 : loggingLevel == "info" ? 1 : 0;

    for (const auto& testFunc : testSuite) {
        const std::string label = moduleLabel + "_test";
        auto config = databaseConnection.retrieveConfig(moduleLabel);

        if (shouldLog(loggingLevel, currentLogLevel)) {
            std::cout << "Starting test: " << label << "\n";
        }

        std::function<void()> attackFunction = [&]() { /* Attack function logic */ };

        {
            std::lock_guard<std::mutex> lock(mtx);
            testQueue.emplace(testFunc, label, attackFunction, config);
        }

        cv.notify_one();

        // Log timeout message if needed
        std::this_thread::sleep_for(std::chrono::milliseconds(testTimeout));
    }

    {
        std::lock_guard<std::mutex> lock(mtx);
        shutdown = true;
    }

    cv.notify_all();
}
