public class PasswordManager : IDisposable
{
    private readonly Dictionary<string, string> _cache = new();
    private readonly List<string> _logEntries = new();

    public enum HashAlgorithm { SHA256, Bcrypt, Argon2 }

    private static RNGCryptoServiceProvider rngCsp = new();

    // Securely generate a salt
    private byte[] GenerateSalt(int size = 16)
    {
        var saltBytes = new byte[size];
        rngCsp.GetBytes(saltBytes);
        return saltBytes;
    }

    public string HashPassword(string password, HashAlgorithm algorithm, int saltSize = 16)
    {
        if (string.IsNullOrEmpty(password))
            throw new ArgumentException("Password cannot be null or empty");

        var salt = GenerateSalt(saltSize);
        string hash;

        switch (algorithm)
        {
            case HashAlgorithm.SHA256:
                using var sha256 = SHA256.Create();
                var combinedBytes = salt.Concat(Encoding.UTF8.GetBytes(password)).ToArray();
                var hashedBytes = sha256.ComputeHash(combinedBytes);

                hash = Convert.ToBase64String(salt) + ":" + Convert.ToBase64String(hashedBytes);
                break;

            case HashAlgorithm.Bcrypt:
                hash = BCrypt.Net.BCrypt.HashPassword(password, salt);
                break;

            case HashAlgorithm.Argon2:
                var argon2Config = new Argon2Config
                {
                    Parallelism = 8,
                    DegreeOfParallelism = 4,
                    MemorySize = 102400,
                    TimeCost = 3,
                    Salt = salt
                };

                using var argon2 = new Argon2(argon2Config);
                hash = argon2.GetBytes(password).ToHex();
                break;

            default:
                throw new ArgumentOutOfRangeException(nameof(algorithm), "Unsupported hashing algorithm");
        }

        _logEntries.Add($"Password hashed at {DateTime.UtcNow}");
        return hash;
    }

    public bool VerifyPassword(string password, string storedHash)
    {
        if (string.IsNullOrEmpty(password) || string.IsNullOrEmpty(storedHash))
            return false;

        var parts = storedHash.Split(':');

        if(parts.Length == 2 && HashAlgorithm.SHA256.ToString().Equals("SHA256"))
        {
            var salt = Convert.FromBase64String(parts[0]);
            using var sha256 = SHA256.Create();

            var combinedBytes = salt.Concat(Encoding.UTF8.GetBytes(password)).ToArray();
            var hashedBytes = sha256.ComputeHash(combinedBytes);

            return Convert.ToBase64String(hashedBytes) == parts[1];
        }

        if (BCrypt.Net.BCrypt.Verify(password, storedHash))
            return true;

        using var argon2 = new Argon2(StoredHashToArgonConfig(storedHash));
        return argon2.GetBytes(password).ToHex() == storedHash;
    }

    private static Argon2Config StoredHashToArgonConfig(string hash)
    {
        // Assume the format includes enough data to recreate configuration.
        // Example: Extract salt, iterations, etc., from the hash string (not implemented here).
        return new Argon2Config { Salt = GenerateSalt() }; 
    }

    public int LoadResourceBundle(string filePath)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException("Resource file not found");

        var bundleData = File.ReadAllText(filePath);
        var resourceItems = JsonSerializer.Deserialize<Dictionary<string, object>>(bundleData);

        _logEntries.Add($"Resource bundle loaded at {DateTime.UtcNow} with {resourceItems?.Count ?? 0} items");

        return resourceItems?.Count ?? 0;
    }

    public void Dispose()
    {
        // Clean up resources
        _cache.Clear();
        _logEntries.Clear();
    }

    private string LogActivity(string message)
    {
        _logEntries.Add(message);
        return message;
    }

    public bool AuthenticateWithExternalAPI(string username, string password)
    {
