char *appendSlashIfWithinLimit(const char *input, size_t sizeLimit) {
    if (input == NULL || sizeLimit == 0) {
        return NULL;
    }

    // Calculate the length of input string.
    size_t inputLength = strlen(input);

    // Check if appending a slash exceeds the size limit
    if (inputLength + 1 > sizeLimit) {
        return NULL;
    }

    // Allocate memory for new string with an additional character for slash and null terminator.
    char *result = malloc((inputLength + 2) * sizeof(char));
    if (result == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    // Copy input to result and append a slash at the end.
    strcpy(result, input);
    result[inputLength] = '/';
    result[inputLength + 1] = '\0';

    return result;
}

