```rust
use std::env;
use std::fs;
use std::path::Path;

fn create_directory_and_set_env(var_name: &str, dir_name: &str) -> Result<(), String> {
    if let Ok(value) = env::var(var_name) {
        println!("Environment variable {} is already set to {}", var_name, value);
        return Ok(());
    }

    let path = Path::new(dir_name);

    match fs::create_dir_all(path) {
        Ok(_) => {
            env::set_var(var_name, dir_name.to_string_lossy().into_owned());
            println!("Directory created and environment variable set.");
            Ok(())
        }
        Err(e) => Err(format!("Failed to create directory: {}", e)),
    }
}

#[no_mangle]
pub extern "C" fn setup_environment(var_name: *const i8, dir_name: *const i8) {
    let var_c_str = unsafe { CStr::from_ptr(var_name) };
    let dir_c_str = unsafe { CStr::from_ptr(dir_name) };

    match var_c_str.to_str() {
        Ok(var_name_str) => {
            match dir_c_str.to_str() {
                Ok(dir_name_str) => match create_directory_and_set_env(var_name_str, dir_name_str) {
                    Ok(_) => println!("Setup successful."),
                    Err(e) => eprintln!("{}", e),
                },
                Err(_) => eprintln!("Invalid directory name"),
            }
        }
        Err(_) => eprintln!("Invalid variable name"),
    }
}
