public class LruCache<TKey, TValue>
{
    private readonly Dictionary<TKey, LinkedListNode<(TKey, TValue)>> _cacheMap;
    private readonly LinkedList<(TKey, TValue)> _lruList;
    private readonly int _capacity;

    public LruCache(int capacity)
    {
        _capacity = capacity;
        _cacheMap = new Dictionary<TKey, LinkedListNode<(TKey, TValue)>>();
        _lruList = new LinkedList<(TKey, TValue)>();
    }

    public TValue GetOrAdd(TKey key, Func<TValue> valueFactory)
    {
        if (_cacheMap.TryGetValue(key, out var node))
        {
            _lruList.Remove(node);
            _lruList.AddLast(node);
            return node.Value.Item2;
        }

        var value = valueFactory();
        var newNode = new LinkedListNode<(TKey, TValue)>((key, value));

        if (_cacheMap.Count >= _capacity)
        {
            _cacheMap.Remove(_lruList.First.Value.Item1);
            _lruList.RemoveFirst();
        }

        _cacheMap[key] = newNode;
        _lruList.AddLast(newNode);

        return value;
    }
}

