```cpp
#include <iostream>
#include <random>
#include <string>
#include <vector>
#include <fstream>
#include <stdexcept>

namespace RandomGenerator {

    class SecureMersenneTwister {
    public:
        // Constructor that takes a seed as a string
        explicit SecureMersenneTwister(const std::string& seed) {
            initialize(seed);
        }

        // Destructor
        ~SecureMersenneTwister() = default;

        // Generate a random number from uniform distribution
        int generateUniform(int min, int max) {
            return dist_uniform(rng_);
        }

        // Generate a random number from normal distribution
        double generateNormal(double mean, double stddev) {
            return dist_normal(rng_);
        }

    private:
        std::mt19937_64 rng_;
        std::uniform_int_distribution<int> dist_uniform_;
        std::normal_distribution<double> dist_normal_;

        void initialize(const std::string& seed) {
            try {
                std::vector<std::uint32_t> seeds;
                for (std::size_t i = 0; i < seed.size(); ++i)
                    seeds.push_back(static_cast<std::uint32_t>(seed[i]));

                if (!seeds.empty()) {
                    std::seed_seq seq(seeds.begin(), seeds.end());
                    rng_ = std::mt19937_64(seq);
                } else {
                    throw std::invalid_argument("Seed string is empty");
                }

                dist_uniform_ = std::uniform_int_distribution<int>(0, 100); // Example range
                dist_normal_ = std::normal_distribution<double>(0.0, 1.0);   // Mean and Std Dev
            } catch (const std::exception& e) {
                std::cerr << "Error initializing RNG: " << e.what() << '\n';
                throw;
            }
        }

        static int dist_uniform(std::mt19937_64& rng) {
            return dist_uniform_(rng);
        }

        static double dist_normal(std::mt19937_64& rng) {
            return dist_normal_(rng);
        }
    };

} // namespace RandomGenerator

int main() {
    try {
        std::string seed = "secure_seed_string";
        RandomGenerator::SecureMersenneTwister rng(seed);

        // Generate random numbers
        int uniformRandom = rng.generateUniform(0, 100);
        double normalRandom = rng.generateNormal(0.0, 1.0);

        std::cout << "Uniform Random: " << uniformRandom << '\n';
        std::cout << "Normal Random: " << normalRandom << '\n';

    } catch (const std::exception& e) {
        std::cerr << "Exception caught in main: " << e.what() << '\n';
    }

    return 0;
}
```

