```javascript
// Define default configurations
const DEFAULT_CONFIG = {
  cacheExpirationTime: 60000,
  retryInterval: 2000,
  maxRetries: 3,
  timeoutBaseValue: 5000,
};

class ScriptRenderer {
  constructor(config = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.cacheKey = 'scriptCache';
    this.spinnerElementId = 'loadingSpinner';
    this.scriptContainerId = 'scriptsFooter';
    this.init();
  }

  init() {
    // Initialize loading spinner
    if (!document.getElementById(this.spinnerElementId)) {
      const spinner = document.createElement('div');
      spinner.id = this.spinnerElementId;
      spinner.style.display = 'none'; // Initially hidden
      document.body.appendChild(spinner);
    }
    window.addEventListener('DOMContentLoaded', () => this.cleanupOldScripts());
  }

  async renderScripts(scripts) {
    try {
      scripts.sort((a, b) => (b.priority || 0) - (a.priority || 0));
      await this.showSpinner();
      for (const script of scripts) {
        if (!script.code || typeof script.code !== 'string') {
          console.error('Invalid script code:', script);
          continue;
        }
        const sanitizedCode = this.sanitizeScriptContent(script.code);
        const timeoutValue = this.adjustTimeout(script.type);

        // Check cache
        let cachedScript = localStorage.getItem(this.cacheKey + script.url);
        if (cachedScript) {
          cachedScript = JSON.parse(cachedScript);
          if (Date.now() < cachedScript.expiration) {
            this.insertScriptElement(sanitizedCode, script.type, script.uniqueKey);
            continue;
          }
        }

        // Fetch new script
        const fetchedScript = await this.fetchAndCacheScript(script.url, timeoutValue);

        if (!fetchedScript) {
          console.error('Failed to fetch script:', script.url);
          continue;
        }

        const sanitizedFetchedCode = this.sanitizeScriptContent(fetchedScript);
        this.insertScriptElement(sanitizedFetchedCode, script.type, fetchedScript.uniqueKey);
      }
    } catch (error) {
      console.error('Error rendering scripts:', error);
    } finally {
      this.hideSpinner();
    }
  }

  async fetchAndCacheScript(url, timeoutValue) {
    let retries = 0;
    while (retries < this.config.maxRetries) {
      try {
        const response = await this.fetchWithTimeout(this.fetchScript(url), timeoutValue);
        if (!response.ok) throw new Error('Non-2xx status');

        const data = await response.text();
        const uniqueKey = Date.now() + Math.random().toString(36).substr(2, 9);

        localStorage.setItem(
          this.cacheKey + url,
          JSON.stringify({ content: data, expiration: Date.now() + this.config.cacheExpirationTime, uniqueKey })
        );
        return { code: data, type: 'text/javascript', uniqueKey };
      } catch (error) {
        console.warn(`Fetch attempt ${retries + 1} failed for ${url}:`, error);
        retries++;
        await new Promise((resolve) => setTimeout(resolve, this.config.retryInterval));
      }
    }
    return null;
  }

  async fetchWithTimeout(promise, timeout) {
    const timer = new Promise((_, reject) => setTimeout(() => reject(new Error('Request timed out')), timeout));
    return Promise.race([promise, timer]);
  }

  async fetchScript(url) {
    return fetch(url);
  }

  adjustTimeout(type) {
    if (type === 'module') return this.config.timeoutBaseValue + 2000;
    return this.config.timeoutBaseValue;
  }

  sanitizeScriptContent(content) {
    // Basic sanitization example - customize as needed
    const tempDiv = document.createElement('div');
    tempDiv.textContent = content;
    return tempDiv.innerHTML;
  }

  insertScriptElement(code, type = 'text/javascript', uniqueKey) {
    const container = document.getElementById(this.scriptContainerId) || this.createScriptsContainer();
    const scriptTag = document.createElement('script');
    scriptTag.type = type;
    scriptTag.text = code;
    scriptTag.key = `script-${uniqueKey}`;
    container.appendChild(scriptTag);
  }

  createScriptsContainer() {
    const container = document.createElement('div');
    container.id = this.scriptContainerId;
    document.body.appendChild(container);
    return container;
  }

  cleanupOldScripts() {
    const container = document.getElementById(this.scriptContainerId);
    if (!container) return;

    Array.from(container.querySelectorAll('script')).forEach(script => {
      if (Date.now() > localStorage.getItem(this.cacheKey + script.src)) {
        script.remove();
      }
    });
  }

  async showSpinner() {
    const spinner = document.getElementById(this.spinnerElementId);
    if (spinner) spinner.style.display = 'block';
  }

  hideSpinner() {
    const spinner = document.getElementById(this.spinnerElementId);
    if (spinner) spinner.style.display = 'none';
  }
}

// Usage
const renderer = new ScriptRenderer();
renderer.renderScripts([
  { url: 'https://example.com/script1.js', code: '', type: 'text/javascript' },
  { url: 'https://example.com/script2.js', priority: 10, type: 'module' }
]);
```

