        private static async Task SyncImagesWithExternalAPI(BlobServiceClient blobServiceClient)
        {
            var imagesToSync = new List<Stream>();  // Retrieve batched images from Blob Storage
            HttpClient client = new HttpClient();

            int retryCount = 0;
            bool success = false;

            while (!success && retryCount < 5)
            {
                try
                {
                    await PostImagesAsync(client, imagesToSync);
                    success = true;
                }
                catch (Exception ex) when (IsRateLimitException(ex))
                {
                    int delay = CalculateExponentialBackoff(retryCount);
                    Console.WriteLine($"Rate limit hit. Retrying in {delay} ms...");
                    Thread.Sleep(delay);
                    retryCount++;
                }
            }

            if (!success)
            {
                Console.WriteLine("Failed to sync images after several attempts.");
            }
        }

        private static bool IsRateLimitException(Exception ex) => ex is HttpRequestException;

        private static int CalculateExponentialBackoff(int attempt) => (int)(Math.Pow(2, attempt) * 1000);

        private static async Task PostImagesAsync(HttpClient client, List<Stream> images)
        {
            var content = new MultipartFormDataContent();
            foreach (var image in images)
            {
                content.Add(new StreamContent(image), "images", Path.GetFileName(image.Name));
