using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using UnityEngine;

public class AdvancedCustomRandomGenerator : IDisposable
{
    private int _seed;
    private Dictionary<string, object> _cache = new();
    private readonly ReaderWriterLockSlim _lock = new(true);
    private Func<double>[] _customDistributions;
    private string _configFilePath = "path/to/config.xml";

    public AdvancedCustomRandomGenerator(int seed)
    {
        SetSeed(seed);
    }

    public void SetSeed(int seed, Action<int> onNewSeed = null)
    {
        _lock.EnterWriteLock();
        try
        {
            _seed = seed;
            UnityEngine.Random.InitState(_seed);
            onNewSeed?.Invoke(_seed);
            RotateSeedPeriodically();
        }
        finally
        {
            _lock.ExitWriteLock();
        }
    }

    private void RotateSeedPeriodically()
    {
        Task.Run(async () =>
        {
            while (true)
            {
                await Task.Delay(TimeSpan.FromMinutes(30));
                SetSeed(_seed + 1);
            }
        });
    }

    public T CustomRange<T>(T min, T max) where T : IComparable<T>
    {
        _lock.EnterReadLock();
        try
        {
            string key = $"{typeof(T)}_{min}_{max}";
            if (_cache.ContainsKey(key))
                return (T)_cache[key];

            double range = Convert.ToDouble(max) - Convert.ToDouble(min);
            var randomValue = min + (T)(object)((Convert.ToDouble(UnityEngine.Random.value) * range));
            _cache[key] = randomValue;
            return randomValue;
        }
        finally
        {
            _lock.ExitReadLock();
        }
    }

    public Tuple<T1, T2> CustomRangeMultiDimensional<T1, T2>(T1 min1, T1 max1, T2 min2, T2 max2)
    {
        return new Tuple<T1, T2>(
            CustomRange(min1, max1),
            CustomRange(min2, max2));
    }

    public double[] GenerateRandomCoordinates(params (object min, object max)[] ranges)
    {
        _lock.EnterReadLock();
        try
        {
            return ranges.Select(range => Convert.ToDouble(CustomRange(range.min, range.max))).ToArray();
        }
        finally
        {
            _lock.ExitReadLock();
        }
    }

    public void LoadCustomDistribution(Func<double>[] distributions)
    {
        _customDistributions = distributions;
    }

    public double GenerateWithCustomDistribution()
    {
        if (_customDistributions == null || !_customDistributions.Any())
            throw new InvalidOperationException("No custom distribution loaded.");

        int index = UnityEngine.Random.Range(0, _customDistributions.Length);
        return _customDistributions[index]();
    }

    private void ValidateRange<T>(T min, T max)
    {
        if (min.CompareTo(max) > 0)
            throw new ArgumentException("Min cannot be greater than Max.");
    }

    public void LoadConfigurationsFromXML()
    {
        try
        {
            var doc = System.Xml.Linq.XDocument.Load(_configFilePath);
            // Parse XML and load configurations into the class properties.
        }
        catch (FileNotFoundException ex)
        {
            Console.WriteLine($"Error: Configuration file not found. {ex.Message}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Unexpected error occurred while loading configuration: {ex.Message}");
        }
    }

    public void ClearCache()
    {
        _lock.EnterWriteLock();
        try
        {
            _cache.Clear();
        }
        finally
        {
            _lock.ExitWriteLock();
        }
    }

    public void Dispose()
    {
        _lock.Dispose();
        ClearCache();
    }
}
```

