<?php

function generateSecureToken($length = 32, $charset = 'alphanumeric', $lifetime = 3600) {
    // Validate input parameters
    if (!is_int($length) || $length <= 0) {
        throw new InvalidArgumentException("Length must be a positive integer.");
    }
    if ($lifetime <= 0) {
        throw new InvalidArgumentException("Lifetime must be a positive integer.");
    }

    // Define character sets
    $charsets = [
        'alphanumeric' => '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ',
        'alnum_special' => '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ!@#$%^&*()_-+=[]{}|;:",.<>?'
    ];

    if (!array_key_exists($charset, $charsets)) {
        throw new InvalidArgumentException("Unsupported character set.");
    }

    // Generate secure random string
    $token = '';
    $maxIndex = strlen($charsets[$charset]) - 1;
    for ($i = 0; $i < $length; $i++) {
        $randomChar = $charsets[$charset][random_int(0, $maxIndex)];
        if (!is_string($randomChar)) {
            throw new RuntimeException("Error generating random character.");
        }
        $token .= $randomChar;
    }

    // Validate token strength
    if (!checkTokenStrength($token)) {
        throw new RuntimeException("Generated token does not meet the required criteria.");
    }

    // Start or regenerate session
    if (session_status() == PHP_SESSION_NONE) {
        session_start();
    }
    session_regenerate_id(true);

    // Store token with lifetime in session securely
    $_SESSION['token'] = $token;
    $_SESSION['token_lifetime'] = time() + $lifetime;

    return $token;
}

function checkTokenStrength($token) {
    if (strlen($token) < 12 || preg_match('/[a-zA-Z0-9]/', $token) === false) {
        return false; // Simple pattern check, add more complex checks as needed
    }
    // Add entropy or complexity calculations here
    return true;
}

