```javascript
const fs = require('fs').promises;
const path = require('path');
const cache = new Map();

async function readFileAsync(filePath) {
    if (cache.has(filePath)) {
        return cache.get(filePath);
    }

    try {
        const stats = await fs.stat(filePath);

        let content;
        if (stats.isFile()) {
            content = await fs.readFile(filePath, stats.isDirectory() ? 'binary' : 'utf8');
        } else {
            throw new Error('Not a file');
        }

        cache.set(filePath, content);
        return content;

    } catch (error) {
        handleError(error);
    }
}

async function readDirectoryAsync(directoryPath) {
    try {
        const files = await fs.readdir(directoryPath);
        const promises = files.map(file => readFileAsync(path.join(directoryPath, file)));
        return Promise.all(promises);

    } catch (error) {
        handleError(error);
    }
}

function handleError(error) {
    if (error.code === 'ENOENT') {
        console.error('File not found:', error.message);
    } else if (error.code === 'EACCES') {
        console.error('Permission denied:', error.message);
    } else {
        console.error('Read error:', error.message);
    }
}

// Example usage
(async () => {
    try {
        const directoryContents = await readDirectoryAsync('./your-directory-path');
        console.log(directoryContents);

    } catch (error) {
        handleError(error);
    }
})();
