```javascript
// configMerger.js

import { promises as fs } from 'fs';
import path from 'path';

class ConfigMerger {
  constructor(options = {}) {
    this.directoryPath = options.directoryPath || '';
    this.fileTypes = options.fileTypes || ['.json'];
    this.defaultValues = options.defaultValues || {};
    this.logger = options.logger; // External logging service
  }

  async readAndMergeConfigs() {
    try {
      const files = await fs.readdir(this.directoryPath);
      const filePromises = files.map(file => 
        this.processFile(path.join(this.directoryPath, file))
      );

      const configObjects = await Promise.allSettled(filePromises);

      return configObjects.reduce((mergedConfig, result) => {
        if (result.status === 'fulfilled' && result.value) {
          Object.assign(mergedConfig, result.value);
        } else if (this.logger && result.status === 'rejected') {
          this.logger.error(`Error processing file: ${result.reason}`);
        }
        return mergedConfig;
      }, { ...this.defaultValues });
    } catch (error) {
      if (this.logger) this.logger.error(`Error reading directory: ${error.message}`);
      throw new Error('Failed to read configuration files.');
    }
  }

  async processFile(filePath) {
    const fileExtension = path.extname(filePath);
    if (!this.fileTypes.includes(fileExtension)) return null;

    try {
      const fileContent = await fs.readFile(filePath, 'utf-8');
      return this.parseFileContent(fileContent, fileExtension);
    } catch (error) {
      if (this.logger) this.logger.error(`Error reading file ${filePath}: ${error.message}`);
      throw error;
    }
  }

  parseFileContent(content, extension) {
    switch (extension) {
      case '.json':
        return JSON.parse(content);
      // Add cases for other supported formats like .yaml
      default:
        throw new Error(`Unsupported file type: ${extension}`);
    }
  }
}

export default ConfigMerger;
```

