const app = express();

app.post('/process-image', async (req, res) => {
  try {
    const { bucket, key } = req.body;

    // Trigger image processing via SQS
    await SQS.sendMessage({
      QueueUrl: IMAGE_QUEUE_URL,
      MessageBody: JSON.stringify({ bucket, key })
    }).promise();

    res.status(202).send('Image processing initiated.');
  } catch (error) {
    console.error("Error triggering image processing:", error);
    res.status(500).send('Failed to initiate image processing.');
  }
});

// Start the Express server
const port = process.env.PORT || 3000;
app.listen(port, () => {
