using System;
using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json;
using StackExchange.Redis;
using RestSharp;
using System.Net.Http;
using System.Threading.Tasks;

namespace FSAIntegrationApp
{
    public enum LogLevel { Info, Warning, Error }

    public class LogEntry
    {
        public DateTime Timestamp { get; set; }
        public LogLevel Level { get; set; }
        public string Message { get; set; }
    }

    public static class Logger
    {
        private static readonly List<LogEntry> Logs = new List<LogEntry>();

        public static void Log(LogLevel level, string message)
        {
            var logEntry = new LogEntry
            {
                Timestamp = DateTime.UtcNow,
                Level = level,
                Message = message
            };
            Logs.Add(logEntry);
            Console.WriteLine($"{logEntry.Timestamp} [{level}] {message}");
        }
    }

    public class StateMachine
    {
        private readonly Dictionary<int, List<int>> _transitions;

        public StateMachine(Dictionary<int, List<int>> transitions)
        {
            _transitions = transitions;
        }

        public List<int> GetReachableStates(int stateIndex, HashSet<int> visited = null)
        {
            if (visited == null) visited = new HashSet<int>();

            if (visited.Contains(stateIndex)) return new List<int>();

            var reachableStates = new List<int> { stateIndex };
            visited.Add(stateIndex);

            if (_transitions.TryGetValue(stateIndex, out var nextStates))
            {
                foreach (var nextState in nextStates)
                {
                    if (!visited.Contains(nextState))
                        reachableStates.AddRange(GetReachableStates(nextState, visited));
                }
            }

            return reachableStates;
        }
    }

    public static class FsaSerialization
    {
        public static string Serialize(FSM fsm) => JsonConvert.SerializeObject(fsm);

        public static FSM Deserialize(string json) => JsonConvert.DeserializeObject<FSM>(json);
    }

    public class FSM
    {
        public Dictionary<int, List<int>> Transitions { get; set; }
    }

    public static class CacheManager
    {
        private static readonly ConnectionMultiplexer redis = ConnectionMultiplexer.Connect("localhost");
        private static readonly IDatabase db = redis.GetDatabase();

        public static async Task<string> GetOrSetAsync(string key, Func<Task<string>> valueFactory)
        {
            var cachedValue = await db.StringGetAsync(key);

            if (!cachedValue.IsNullOrEmpty)
                return cachedValue;

            var newValue = await valueFactory();
            await db.StringSetAsync(key, newValue);
            return newValue;
        }

        public static async Task ClearCacheAsync()
        {
            foreach (var endpoint in redis.GetEndPoints())
            {
                using var server = await redis.ConnectAsync(endpoint);
                await server.FlushDatabaseAsync();
            }
        }
    }

    public class RestClient
    {
        private readonly HttpClient _httpClient;
        private readonly string _baseUrl;

        public RestClient(string baseUrl)
        {
            _baseUrl = baseUrl;
            _httpClient = new HttpClient { Timeout = TimeSpan.FromSeconds(10) };
        }

        public async Task<string> CallApiAsync(string endpoint, HttpMethod method)
        {
            var request = new RestRequest(endpoint, method);
            var response = await _httpClient.SendAsync(request);

            if (!response.IsSuccessStatusCode)
                throw new HttpRequestException($"Error calling API: {response.StatusCode}");

            return await response.Content.ReadAsStringAsync();
        }
    }

    public class RateLimiter
    {
        private readonly SemaphoreSlim _semaphore;
        private int _requestCount;

        public RateLimiter(int maxRequests, TimeSpan window)
        {
            _semaphore = new SemaphoreSlim(maxRequests);
            Task.Run(async () => await ResetRateLimitAsync(window));
        }

        private async Task ResetRateLimitAsync(TimeSpan window)
        {
            while (true)
            {
                await Task.Delay(window);
                Interlocked.Exchange(ref _requestCount, 0);
                _semaphore.Release(_semaphore.CurrentCount);
            }
        }

        public async Task<bool> AllowRequestAsync()
        {
            if (_requestCount >= _semaphore.CurrentCount) return false;

            await _semaphore.WaitAsync();
            Interlocked.Increment(ref _requestCount);

            return true;
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            try
            {
                // Setup logging and caching
                Logger.Log(LogLevel.Info, "Application started.");

                // Example FSM setup
                var transitions = new Dictionary<int, List<int>>
                {
                    { 0, new List<int> { 1 } },
                    { 1, new List<int> { 2, 3 } },
                    { 2, new List<int> { 0 } }
                };

                var fsm = new StateMachine(transitions);
                var reachableStates = fsm.GetReachableStates(0);

                Logger.Log(LogLevel.Info, $"Reachable states from 0: {string.Join(", ", reachableStates)}");

                // Serialize FSM
                var serializedFsm = FsaSerialization.Serialize(fsm.Transitions);
                var deserializedFsm = FsaSerialization.Deserialize(serializedFsm);

                Logger.Log(LogLevel.Info, "FSM serialization and deserialization completed.");

                // Example cache usage
                var cachedData = await CacheManager.GetOrSetAsync("key1", async () =>
                {
                    var restClient = new RestClient("http://python-backend/");
                    return await restClient.CallApiAsync("/data/123", HttpMethod.Get);
                });

                Logger.Log(LogLevel.Info, $"Cached data: {cachedData}");

                // Rate limiting example
                var rateLimiter = new RateLimiter(5, TimeSpan.FromSeconds(10));

                for (int i = 0; i < 10; i++)
                {
                    if (await rateLimiter.AllowRequestAsync())
                        Logger.Log(LogLevel.Info, "Request allowed.");
                    else
                        Logger.Log(LogLevel.Warning, "Rate limit exceeded.");
                }

                // Validate file paths and read integers
                foreach (var filePath in args)
                {
                    if (!File.Exists(filePath))
                    {
                        Logger.Log(LogLevel.Error, $"File not found: {filePath}");
                        continue;
                    }

                    var numbers = File.ReadAllLines(filePath);
                    foreach (var number in numbers)
                    {
                        if (int.TryParse(number, out _))
                            Logger.Log(LogLevel.Info, $"Read integer: {number}");
                        else
                            Logger.Log(LogLevel.Warning, $"Invalid data in file: {filePath}");
                    }
                }
            }
            catch (Exception ex)
            {
                Logger.Log(LogLevel.Error, $"An error occurred: {ex.Message}");
            }
            finally
            {
                CacheManager.redis.Close();
                Logger.Log(LogLevel.Info, "Application finished.");
            }
        }
    }
}
