Below is a modular Node.js implementation of a data aggregation service that meets your requirements:

```javascript
const { Readable } = require('stream');
const { Writable } = require('stream');
const axios = require('axios');
const winston = require('winston');

// Configurable parameters
const CONFIG = {
  bufferLimit: 1024 * 1024, // 1MB initial buffer size
  maxConcurrency: 5,
  sourceConfigurations: [
    { id: 'source1', url: 'http://example.com/stream1' },
    { id: 'source2', url: 'http://example.com/stream2' }
    // Add more sources as needed
  ]
};

// Initialize logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.Console()
  ]
});

class DataAggregator extends Writable {
  constructor(options) {
    super({ ...options, objectMode: true });
    this.buffer = Buffer.alloc(0);
    this.totalBytes = 0;
  }

  _write(chunk, encoding, callback) {
    try {
      const bufferLength = this.buffer.length + chunk.length;
      if (bufferLength > CONFIG.bufferLimit) {
        this.emit('overflow', { message: 'Buffer limit exceeded' });
        return callback(new Error('Buffer overflow'));
      }

      this.buffer = Buffer.concat([this.buffer, chunk]);
      this.totalBytes += chunk.length;

      logger.info(`Aggregated ${chunk.length} bytes from stream`);

      callback();
    } catch (error) {
      logger.error(`Error writing data: ${error.message}`);
      callback(error);
    }
  }

  getBuffer() {
    return this.buffer;
  }

  getTotalBytes() {
    return this.totalBytes;
  }
}

async function fetchDataFromSource(sourceConfig, aggregator) {
  try {
    const response = await axios({
      url: sourceConfig.url,
      method: 'GET',
      responseType: 'stream'
    });

    response.data.on('data', (chunk) => {
      aggregator.write(chunk);
    });

    response.data.on('end', () => {
      logger.info(`Finished streaming from ${sourceConfig.id}`);
    });

  } catch (error) {
    logger.error(`Failed to fetch data from ${sourceConfig.id}: ${error.message}`);
    // Implement retry logic or error recovery as needed
  }
}

async function startAggregation() {
  const aggregator = new DataAggregator();
  const streamPromises = CONFIG.sourceConfigurations.map(sourceConfig => 
    fetchDataFromSource(sourceConfig, aggregator)
  );

  await Promise.all(streamPromises);
  console.log('Data aggregation complete');

  // Process the aggregated buffer as needed
}

startAggregation().catch(error => {
  logger.error(`Error in data aggregation: ${error.message}`);
});
```

### Key Components:

1. **Configuration:** The `CONFIG` object contains parameters like initial buffer size and source configurations.

2. **Logger:** Uses Winston to log messages, which can be configured for different environments or outputs (e.g., file logging).

3. **DataAggregator Class:**
   - Inherits from `stream.Writable`.
   - Manages a buffer that aggregates data from multiple streams.
   - Implements `_write` method to handle incoming chunks and logs each operation.

4. **fetchDataFromSource Function:**
   - Asynchronously fetches data from configured network sources using Axios.
   - Streams the response data into the `DataAggregator`.

5. **Concurrency Control:** The `maxConcurrency` parameter can be used to limit simultaneous requests, but actual implementation would require a queue or pool.

6. **Error Handling and Logging:** Errors are logged, and basic error recovery (e.g., logging) is shown. Retry logic can be added for robustness against network failures.

7. **Start Aggregation Function:** Manages the concurrent fetching of data from sources.

### Testing & Documentation:

- **Unit Tests:** Use a testing framework like Jest to create tests that simulate various edge cases such as buffer overflow, failed connections, and high latency.

- **Documentation:** Provide markdown or other documentation detailing configuration options, API usage, and integration steps for new network stream sources. Include best practices for scaling and handling large data volumes.

