<?php

session_start();

class OAuth2Authenticator {
    private $providers = [
        'google' => 'https://accounts.google.com/o/oauth2/auth',
        'facebook' => 'https://www.facebook.com/v9.0/dialog/oauth',
        'twitter' => 'https://api.twitter.com/oauth/authorize'
    ];

    private $tokenStorageKey = 'oauth_token';
    private $rateLimitBurst;
    private $loggingService;

    public function __construct($loggingService, $burstLimit = 5) {
        $this->loggingService = $loggingService;
        $this->rateLimitBurst = $burstLimit;
        if (!isset($_SESSION['request_count'])) {
            $_SESSION['request_count'] = [];
        }
    }

    private function getRateLimited($ipAddress) {
        $currentTime = time();
        if (isset($_SESSION['request_count'][$ipAddress])) {
            $attempts = &$_SESSION['request_count'][$ipAddress];
            array_walk($attempts, function (&$timestamp) use ($currentTime) {
                if ($timestamp < ($currentTime - 60)) { // 1 minute window
                    $timestamp = $currentTime;
                }
            });
            return count(array_filter($attempts, function ($timestamp) use ($currentTime) {
                return $timestamp > ($currentTime - 60);
            })) >= $this->rateLimitBurst;
        }
        $_SESSION['request_count'][$ipAddress] = [$currentTime];
        return false;
    }

    public function authenticate($providerKey, $callbackUrl) {
        $ipAddress = $_SERVER['REMOTE_ADDR'];

        if ($this->getRateLimited($ipAddress)) {
            $this->log('Rate limit exceeded', $ipAddress);
            throw new Exception("Too many requests. Please try again later.");
        }

        $clientId = getenv("OAUTH_{$providerKey}_CLIENT_ID");
        $clientSecret = getenv("OAUTH_{$providerKey}_CLIENT_SECRET");

        if (!$clientId || !$clientSecret) {
            throw new Exception("Missing configuration for {$providerKey}");
        }

        // OAuth 2.0 Authentication URL generation
        $authUrl = sprintf(
            "%s?response_type=code&client_id=%s&redirect_uri=%s&scope=email",
            $this->providers[$providerKey],
            urlencode($clientId),
            urlencode($callbackUrl)
        );

        header("Location: " . $authUrl);
        exit();
    }

    public function handleCallback($providerKey, $authorizationCode) {
        $ipAddress = $_SERVER['REMOTE_ADDR'];

        try {
            $accessToken = $this->fetchAccessToken($providerKey, $authorizationCode);

            if (!$accessToken) {
                throw new Exception("Failed to fetch access token");
            }

            $_SESSION[$this->tokenStorageKey] = [
                'provider' => $providerKey,
                'access_token' => $accessToken
            ];

            $userInfo = $this->fetchUserInfo($accessToken, $providerKey);

            if (!$userInfo) {
                throw new Exception("Failed to fetch user info");
            }

            // Sanitize and store user data safely in a distributed database
            $sanitizedUserData = $this->sanitizeUserData($userInfo);
            $this->storeUserData($sanitizedUserData);

            $this->log('Authentication successful', $ipAddress, true);

            return $sanitizedUserData;
        } catch (Exception $e) {
            $this->log("Authentication failed: " . $e->getMessage(), $ipAddress, false);
            throw new Exception("Authentication error. Please try again.");
        }
    }

    private function fetchAccessToken($providerKey, $authorizationCode) {
        // Implement the logic to exchange authorization code for access token
        return 'mock_access_token';
    }

    private function fetchUserInfo($accessToken, $providerKey) {
