namespace SessionIDGenerator {

class SecureRandom {
public:
    SecureRandom() : rng_(seed()) {}
    ~SecureRandom() = default;

    std::string generateSessionID();

private:
    static std::mt19937_64 rng_;
    static uint64_t seed();
    static void secureSeed(std::random_device& rd, std::mt19937_64& gen);

    static inline std::mutex mtx_;
};

std::mt19937_64 SecureRandom::rng_;

inline std::mutex SecureRandom::mtx_;

uint64_t SecureRandom::seed() {
    std::random_device rd;
    secureSeed(rd, rng_);
    return rng_();
}

void SecureRandom::secureSeed(std::random_device& rd, std::mt19937_64& gen) {
    std::lock_guard<std::mutex> lock(mtx_);
    uint64_t seed1 = rd();
    uint64_t seed2 = 0;

    std::ifstream urandom("/dev/urandom", std::ios::binary);
    if (urandom.is_open()) {
        urandom.read(reinterpret_cast<char*>(&seed2), sizeof(seed2));
    }

    gen.seed((seed1 << 32) + seed2);
}

std::string SecureRandom::generateSessionID() {
    static const char* base64_chars =
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz"
        "0123456789+/";

    uint64_t random_value = rng_();
    std::string session_id;
    session_id.reserve(22);

    for (int i = 0; i < 16; ++i) {
        session_id += base64_chars[(random_value >> (58 - i * 6)) & 0x3F];
    }

    BIO* bmem = BIO_new(BIO_s_mem());
    BUF_MEM* bufferPtr;
    BIO_set_flags(bmem, BIO_FLAGS_BASE64_NO_NL);
    BIO_write(bmem, session_id.c_str(), session_id.length());
    BIO_flush(bmem);
    BIO_get_mem_ptr(bmem, &bufferPtr);
    session_id = std::string(bufferPtr->data, bufferPtr->length);
    BIO_free_all(bmem);

    return session_id;
}

