typedef struct {
    const char* name;
    void (*implementation)(void);
    // Add other necessary parameters here
} CryptoFunction;

// Example implementations
void sha256_impl(void) { printf("SHA-256\n"); }
void aes_128_impl(void) { printf("AES-128\n"); }

int is_function_available(const char* name) {
    // Check availability (e.g., using OpenSSL)
    return 1; // Assume available for demonstration
}

CryptoFunction* get_crypto_functions() {
    static CryptoFunction functions[] = {
        {"SHA-256", sha256_impl, NULL},
        {"AES-128", aes_128_impl, NULL}
    };

    int count = sizeof(functions) / sizeof(CryptoFunction);
    CryptoFunction* available_functions = malloc(count * sizeof(CryptoFunction));

    for (int i = 0; i < count; ++i) {
        if (is_function_available(functions[i].name)) {
            available_functions[i] = functions[i];
        }
    }

    return available_functions;
}

int main() {
    CryptoFunction* funcs = get_crypto_functions();
    int count = sizeof(funcs) / sizeof(CryptoFunction);

    for (int i = 0; i < count; ++i) {
        if (funcs[i].name != NULL) {
            printf("Available: %s\n", funcs[i].name);
        }
    }

    free(funcs);
    return 0;
}
