```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;
using System.Xml.Linq;
using System.Xml.Schema;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class DynamicXmlManager : IDisposable
{
    private readonly ILogger<DynamicXmlManager> _logger;
    private readonly IMemoryCache _cache;
    private XDocument _cachedXmlDocument;
    private XmlSchemaSet _xmlSchemaSet;
    private DateTime _lastUpdateTime;

    public DynamicXmlManager(ILogger<DynamicXmlManager> logger, IMemoryCache cache)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
    }

    public async Task LoadAndValidateXmlAsync(string xmlUrl, string xsdPath, TimeSpan cacheDuration)
    {
        if (_cache.TryGetValue("xmlDocument", out _cachedXmlDocument) && 
            (DateTime.UtcNow - _lastUpdateTime).TotalSeconds < cacheDuration.TotalSeconds)
        {
            _logger.LogInformation("Using cached XML document.");
            return;
        }

        try
        {
            var xmlContent = await LoadXmlFromUrlAsync(xmlUrl);
            ValidateXsdSchema(xsdPath);

            using (var reader = new StringReader(xmlContent))
            {
                _cachedXmlDocument = XDocument.Load(reader, LoadOptions.PreserveWhitespace);
            }

            _lastUpdateTime = DateTime.UtcNow;
            _cache.Set("xmlDocument", _cachedXmlDocument, cacheDuration);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error loading or validating XML document.");
            throw;
        }
    }

    private async Task<string> LoadXmlFromUrlAsync(string url)
    {
        using var httpClient = new System.Net.Http.HttpClient();
        return await httpClient.GetStringAsync(url);
    }

    private void ValidateXsdSchema(string xsdPath)
    {
        _xmlSchemaSet = new XmlSchemaSet();
        _xmlSchemaSet.Add("", File.ReadAllText(xsdPath));

        _cachedXmlDocument?.Validate(_xmlSchemaSet, (o, e) =>
        {
            _logger.LogError(e.Message);
            throw new Exception($"XML validation error: {e.Message}");
        });
    }

    public void ExecuteXPathQuery(string xpath)
    {
        if (string.IsNullOrWhiteSpace(xpath))
            throw new ArgumentException("XPath query cannot be null or empty.", nameof(xpath));

        var sw = System.Diagnostics.Stopwatch.StartNew();
        try
        {
            var results = _cachedXmlDocument.XPathSelectElements(xpath);
            foreach (var element in results)
            {
                Console.WriteLine(element.ToString());
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error executing XPath query.");
            throw;
        }
        finally
        {
            sw.Stop();
            _logger.LogInformation($"XPath execution time: {sw.ElapsedMilliseconds} ms");
        }
    }

    public void Dispose()
    {
        _cachedXmlDocument?.Dispose();
    }
}
