fn parse_tiff_file(file_path: &str) -> Result<(), String> {
    match decoder::Decoder::new(std::fs::File::open(file_path)?, false) {
        Ok(mut decoder) => {
            let (width, height) = decoder.size()?;
            info!("TIFF dimensions: {}x{}", width, height);

            for (_, value) in decoder.into_iter() {
                match value {
                    TagValueType::U8(_) | TagValueType::S16(_) | TagValueType::S32(_) | 
                    TagValueType::Float(_)| TagValueType::Double(_) => continue,
                    _ => return Err("Unsupported bit depth".into()),
                }
            }

            let bits_per_sample = decoder.bits_per_sample()?;
            info!("Bits per sample: {:?}", bits_per_sample);

            let samples_per_pixel = decoder.samples_per_pixel()?;
            info!("Samples per pixel: {:?}", samples_per_pixel);

            if let Some(extra_samples) = decoder.extra_samples()? {
                info!("Extra samples: {:?}", extra_samples);
            }

            Ok(())
        },
        Err(e) => Err(format!("Failed to parse TIFF file: {}", e)),
    }
}

