<?php

class ClinicStatusUpdater {
    private $db;
    private $logger;
    private $cache;
    private $emailService;

    public function __construct($db, $logger, $cache, $emailService) {
        $this->db = $db;
        $this->logger = $logger;
        $this->cache = $cache;
        this->emailService = $emailService;
    }

    public function updateClinicStatus(array $clinicUpdates, $sourceIP, $userDetails) {
        if ($this->isRateLimited($sourceIP)) {
            throw new Exception("Rate limit exceeded for source IP: $sourceIP");
        }

        try {
            $this->db->beginTransaction();

            foreach ($clinicUpdates as $update) {
                $clinicId = $update['id'];
                if (!$this->isValidClinicID($clinicId)) {
                    continue;
                }

                // Validate batch and cache
                $existingData = $this->getFromCacheOrDB($clinicId);
                $oldStatus = $existingData['status'];

                $newStatus = $update['status'];
                $lastModifiedIP = $sourceIP;
                $lastModifiedDate = new DateTime();

                if (!$this->isThrottled($clinicId)) {
                    // Update the clinic status
                    $stmt = $this->db->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE id = ?");
                    $stmt->execute([$newStatus, $lastModifiedIP, $lastModifiedDate->format('Y-m-d H:i:s'), $clinicId]);

                    // Log the change
                    $this->logChange($userDetails['userId'], $clinicId, $oldStatus, $newStatus, $sourceIP);

                    // Send notification email
                    $this->sendEmailNotification($existingData['adminEmail'], $clinicId, $newStatus, $userDetails);
                }

                // Update cache
                $this->updateCache($clinicId, ['status' => $newStatus]);
            }

            $this->db->commit();
        } catch (Exception $e) {
            $this->db->rollBack();
            $this->logger->logError("Transaction failed: " . $e->getMessage());
            throw $e;
        } finally {
            // Clean up resources
            $this->cleanupResources();
        }
    }

