```java
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

public class DynamicResourcePoolManager {
    private static final long DEFAULT_TIMEOUT = 30000; // Default timeout in milliseconds

    public interface ConnectionConfigCallback {
        ConnectionConfig apply(ConnectionConfig config);
    }

    public interface ConnectionHealthChecker {
        boolean isHealthy(Connection conn);
    }

    public static class ConnectionConfig {
        private int minConnections;
        private int maxConnections;
        private long connectionTimeout;

        // Getters and Setters
        public int getMinConnections() { return minConnections; }
        public void setMinConnections(int minConnections) { this.minConnections = minConnections; }

        public int getMaxConnections() { return maxConnections; }
        public void setMaxConnections(int maxConnections) { this.maxConnections = maxConnections; }

        public long getConnectionTimeout() { return connectionTimeout; }
        public void setConnectionTimeout(long connectionTimeout) { this.connectionTimeout = connectionTimeout; }
    }

    private final Map<String, ResourcePool> resourcePools = new ConcurrentHashMap<>();
    private final ReentrantLock lock = new ReentrantLock();

    public void initializeResourcePool(String poolName, int minConnections, int maxConnections, long timeout, ConnectionConfigCallback callback) {
        validateParameters(minConnections, maxConnections, timeout);

        lock.lock();
        try {
            ConnectionConfig config = new ConnectionConfig();
            config.setMinConnections(minConnections);
            config.setMaxConnections(maxConnections);
            config.setConnectionTimeout(timeout);

            if (callback != null) {
                config = callback.apply(config);
            }

            resourcePools.computeIfAbsent(poolName, k -> new ResourcePool(config));
        } finally {
            lock.unlock();
        }
    }

    public void initializeResourcePoolWithSeed(String poolName, int minConnections, int maxConnections, long timeout, long seed, ConnectionConfigCallback callback) {
        Random random = new Random(seed);
        // Use the seed for any initialization logic that requires randomness

        initializeResourcePool(poolName, minConnections, maxConnections, timeout, callback);

        // Additional seeding logic if needed
    }

    private void validateParameters(int minConnections, int maxConnections, long timeout) {
        if (minConnections < 0 || maxConnections <= minConnections) {
            throw new IllegalArgumentException("Invalid connection pool size parameters");
        }
        if (timeout <= 0) {
            throw new IllegalArgumentException("Connection timeout must be positive");
        }
    }

    private static class ResourcePool {
        private final ConnectionConfig config;
        private final List<Connection> connections = new ArrayList<>();
        private final Random random = new Random();
        private final ConnectionHealthChecker healthChecker;

        public ResourcePool(ConnectionConfig config, ConnectionHealthChecker healthChecker) {
            this.config = config;
            this.healthChecker = healthChecker;
            initializeConnections();
        }

        private void initializeConnections() {
            for (int i = 0; i < config.getMinConnections(); i++) {
                connections.add(createConnection());
            }
        }

        public Connection getConnection(long timeout) throws InterruptedException {
            long startTime = System.currentTimeMillis();
            while (System.currentTimeMillis() - startTime < timeout) {
                Optional<Connection> availableConnection = connections.stream()
                        .filter(this::isHealthy)
                        .findFirst();

                if (availableConnection.isPresent()) {
                    return availableConnection.get();
                }

                if (connections.size() < config.getMaxConnections()) {
                    connections.add(createConnection());
                }
                Thread.sleep(100); // Wait before retrying
            }
            throw new TimeoutException("Failed to obtain a connection within the timeout period");
        }

        private boolean isHealthy(Connection conn) {
            return healthChecker == null || healthChecker.isHealthy(conn);
        }

        private Connection createConnection() {
            // Simulate creating a new connection
            return new Connection();
        }
    }

    private static class Connection {
        // Represents a database connection or similar resource
    }

    public void monitorAndReplaceUnhealthyConnections(String poolName) {
        ResourcePool pool = resourcePools.get(poolName);
        if (pool != null) {
            for (int i = 0; i < pool.connections.size(); i++) {
                Connection conn = pool.connections.get(i);
                if (!pool.isHealthy(conn)) {
                    pool.connections.set(i, pool.createConnection());
                }
            }
        }
    }

    public void resizePool(String poolName, int newMinConnections, int newMaxConnections) {
        ResourcePool pool = resourcePools.get(poolName);
        if (pool != null) {
            lock.lock();
            try {
                ConnectionConfig config = pool.config;
                config.setMinConnections(newMinConnections);
                config.setMaxConnections(newMaxConnections);

                while (pool.connections.size() < newMinConnections) {
                    pool.connections.add(pool.createConnection());
                }

                while (pool.connections.size() > newMaxConnections) {
                    pool.connections.remove(pool.connections.size() - 1);
                }
            } finally {
                lock.unlock();
            }
        }
    }
}
