                if (Math.random() > 0.2) { // Simulating success rate
                    return true;
                }
            } catch (Exception e) {
                // Handle network timeouts or transient issues
            }
        }
        return false;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    static class FileStatus {
        private final Path path;
        private final String computedHash;
        private final List<String> mismatchedFiles;
        private final boolean hashMismatch;

        public FileStatus(Path path, String computedHash, List<String> mismatchedFiles, boolean hashMismatch) {
            this.path = path;
            this.computedHash = computedHash;
            this.mismatchedFiles = mismatchedFiles;
            this.hashMismatch = hashMismatch;
        }

        public Path getPath() { return path; }
        public String getComputedHash() { return computedHash; }
        public List<String> getMismatchedFiles() { return mismatchedFiles; }
        public boolean isHashMismatch() { return hashMismatch; }

        @Override
        public String toString() {
            return "FileStatus{" +
                    "path=" + path +
                    ", computedHash='" + computedHash + '\'' +
                    (hashMismatch ? ", mismatch=true" : "") +
                    '}';
        }
    }

    static class HashMismatchException extends RuntimeException {
        private final List<String> mismatchedFiles;

        public HashMismatchException(List<String> mismatchedFiles) {
            super("Hash mismatch found for files: " + String.join(", ", mismatchedFiles));
            this.mismatchedFiles = mismatchedFiles;
        }

        public List<String> getMismatchedFiles() {
            return mismatchedFiles;
        }
    }
