```php
<?php

class OldTestamentExtractor {

    private $allowedBooks = [
        'Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy',
        'Joshua', 'Judges', 'Ruth', '1 Samuel', '2 Samuel',
        '1 Kings', '2 Kings', '1 Chronicles', '2 Chronicles',
        'Ezra', 'Nehemiah', 'Esther', 'Job', 'Psalms',
        'Proverbs', 'Ecclesiastes', 'Song of Solomon', 
        'Isaiah', 'Jeremiah', 'Lamentations', 'Ezekiel', 'Daniel',
        'Hosea', 'Joel', 'Amos', 'Obadiah', 'Jonah',
        'Micah', 'Nahum', 'Habakkuk', 'Zephaniah', 'Haggai',
        'Zechariah', 'Malachi'
    ];

    private $rateLimit = 5; // max requests per minute
    private $cacheKeyPrefix = "user_rate_limit_";

    public function extractOldTestamentBooks($text, $userId) {
        $this->checkRateLimit($userId);

        try {
            $pdo = $this->getDatabaseConnection();
            $pdo->beginTransaction();

            $extractedBooks = $this->extractBookNames($text);
            $validatedBooks = $this->validateBookNames($extractedBooks);

            if (empty($validatedBooks)) {
                throw new Exception("No valid book names found in the text.");
            }

            $logData = [
                'userId' => $userId,
                'books'  => json_encode($validatedBooks),
                'timestamp' => date('Y-m-d H:i:s')
            ];

            $this->logExtraction($pdo, $logData);
            $pdo->commit();

        } catch (Exception $e) {
            if ($pdo) {
                $pdo->rollBack();
            }
            $this->fallbackMechanism($userId);

            throw $e;
        }
    }

    private function checkRateLimit($userId) {
        $cacheKey = $this->cacheKeyPrefix . $userId;
        $requestCount = apcu_fetch($cacheKey, $success);

        if ($success && $requestCount >= $this->rateLimit) {
            throw new Exception("Rate limit exceeded. Please try again later.");
        }

        apcu_store($cacheKey, ($requestCount ?? 0) + 1, 60); // rate limit window of 60 seconds
    }

    private function extractBookNames($text) {
        preg_match_all('/\b(' . implode('|', $this->allowedBooks) . ')\b/i', $text, $matches);
        return array_count_values(array_map('strtolower', $matches[0]));
    }

    private function validateBookNames($bookCounts) {
        return array_filter($bookCounts, fn($key) => in_array(strtoupper($key), $this->allowedBooks));
    }

    private function logExtraction($pdo, $logData) {
        $stmt = $pdo->prepare("INSERT INTO extraction_logs (user_id, books, timestamp) VALUES (:userId, :books, :timestamp)");
        $stmt->execute([
            ':userId' => $logData['userId'],
            ':books'  => $logData['books'],
            ':timestamp' => $logData['timestamp']
        ]);
    }

    private function fallbackMechanism($userId) {
        // Reset user's rate limit in case of failure
        $cacheKey = $this->cacheKeyPrefix . $userId;
        apcu_delete($cacheKey);
    }

    private function getDatabaseConnection() {
        return new PDO('mysql:host=localhost;dbname=test_db', 'username', 'password');
    }
}

// Unit tests

class OldTestamentExtractorTests extends PHPUnit\Framework\TestCase {

    public function testExtractValidBooks() {
        $extractor = new OldTestamentExtractor();
        $text = "In the books of Genesis and Exodus, there are many stories.";
        $result = $extractor->extractOldTestamentBooks($text, 1);

        $this->assertEquals(['genesis' => 1, 'exodus' => 1], $result);
    }

    public function testRateLimitExceeded() {
        $extractor = new OldTestamentExtractor();

        for ($i = 0; $i <= $extractor->rateLimit; $i++) {
            try {
                $text = "Genesis and Exodus";
                $extractor->extractOldTestamentBooks($text, 1);
            } catch (Exception $e) {
                if ($i == $extractor->rateLimit) {
                    $this->assertEquals("Rate limit exceeded. Please try again later.", $e->getMessage());
                }
            }
        }
    }

    public function testTransactionRollback() {
        $extractor = new OldTestamentExtractor();

        try {
            $text = "Invalid book test";
            $extractor->extractOldTestamentBooks($text, 2);
        } catch (Exception $e) {
            // Assert that the database remains unchanged
            $pdo = $extractor->getDatabaseConnection();
            $stmt = $pdo->query("SELECT COUNT(*) FROM extraction_logs WHERE user_id = 2");
            $count = $stmt->fetchColumn();

            $this->assertEquals(0, $count);
        }
    }

}

?>
