void initialize_arrays(size_t num_records, long *offsets, int *keys, Record *records) {
    // Allocate memory and handle allocation failure
    offsets = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));
    records = malloc(num_records * sizeof(Record));

    if (!offsets || !keys || !records) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays with zero values
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = 0;
        records[i].value = 0;
    }

    pthread_t data_thread;

    // Start a thread to handle the external data source delay
    if (pthread_create(&data_thread, NULL, external_data_source_thread, &keys) != 0) {
        perror("Failed to create thread");
        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }

    // Wait for the external data source thread to finish
    if (pthread_join(data_thread, NULL) != 0) {
        perror("Failed to join thread");
        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }

    // Generate unique keys and populate records
    int range_min = 1;
    int range_max = 1000000; // Example range, can be adjusted

    if (!generate_unique_keys(range_min, range_max, num_records, keys)) {
        perror("Failed to generate unique keys");
        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = keys[i];
    }
    pthread_mutex_unlock(&mutex);

    // Here you can do further processing with offsets, keys, and records
}

int generate_unique_keys(int range_min, int range_max, size_t count, int *array) {
    if (range_max - range_min + 1 < count) {
        fprintf(stderr, "Invalid range for unique key generation\n");
        return 0;
    }

    // Use a simple randomized algorithm to generate unique keys
    srand(time(NULL));
    for (size_t i = 0; i < count;) {
        int value = rand() % (range_max - range_min + 1) + range_min;

        // Ensure uniqueness
        int is_unique = 1;
        for (size_t j = 0; j < i; ++j) {
            if (array[j] == value) {
                is_unique = 0;
                break;
            }
        }

        if (is_unique) {
            array[i++] = value;
        }
    }

    return 1;
}

