#define LOG_BUFFER_SIZE 1024

typedef enum {
    LEVEL_ERROR = 1,
    LEVEL_WARNING = 2,
    LEVEL_INFO = 3,
    // Add more levels as needed...
} LogLevel;

typedef struct {
    char logFilePath[256];
    int maxMessages;
    LogLevel minLogLevel;
} LogConfig;

LogConfig config;
int messageCount = 0;
FILE *logFile = NULL;
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void readConfig() {
    // Example: Read from a configuration file
    strcpy(config.logFilePath, "app_log_");
    config.maxMessages = 1000; // Default max messages before rotation
    config.minLogLevel = LEVEL_WARNING; // Default minimum logging level

    // Modify this to actually read from a config file if needed
}

void openLogFile() {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *tm_struct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", tm_struct);

    char logFileName[256];
    snprintf(logFileName, sizeof(logFileName), "%s%s.log", config.logFilePath, timestamp);

    if (logFile) {
        fclose(logFile);
    }
    logFile = fopen(logFileName, "a");
    if (!logFile) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void rotateLogFile() {
    pthread_mutex_lock(&logMutex);
    messageCount++;
    if (messageCount >= config.maxMessages || !logFile) {
        fclose(logFile);
        openLogFile();
        messageCount = 0;
    }
    pthread_mutex_unlock(&logMutex);
}

void logCondition(LogLevel level, const char *format, ...) {
    if (level < config.minLogLevel) return;

    pthread_mutex_lock(&logMutex);

    rotateLogFile();

    va_list args;
    va_start(args, format);

    char buffer[LOG_BUFFER_SIZE];
    int written = vsnprintf(buffer, LOG_BUFFER_SIZE, format, args);
    if (written < 0 || written >= LOG_BUFFER_SIZE) {
        fprintf(stderr, "Buffer overflow or encoding error while formatting log message.\n");
        va_end(args);
        pthread_mutex_unlock(&logMutex);
        return;
    }

    if (fwrite(buffer, sizeof(char), strlen(buffer), logFile) != strlen(buffer)) {
        perror("Failed to write to log file");
    }

    va_end(args);
    fflush(logFile);

    pthread_mutex_unlock(&logMutex);
}

int main() {
    readConfig();
    openLogFile();

    logCondition(LEVEL_ERROR, "Failed to allocate memory for %s", "user");
    logCondition(LEVEL_WARNING, "Low disk space: %d GB remaining", 5);

    // Simulate more logging...
    for (int i = 0; i < config.maxMessages + 10; ++i) {
        logCondition(LEVEL_INFO, "This is a test message number %d", i);
    }

    fclose(logFile);
    return 0;
}
