#include <iostream>
#include <fstream>
#include <unordered_map>
#include <variant>
#include <nlohmann/json.hpp> // Include JSON library (e.g., nlohmann/json)

// Assuming a basic logger function for demonstration purposes.
void logError(const std::string& message) {
    std::cerr << "ERROR: " << message << std::endl;
}

std::unordered_map<std::string, std::variant<int, double, std::string, bool>> loadConfigSettings(const std::string& filePath) {
    std::ifstream file(filePath);

    if (!file.is_open()) {
        logError("Failed to open the configuration file: " + filePath);
        return {};
    }

    try {
        nlohmann::json configJson;
        file >> configJson;

        if (configJson.is_discarded()) { // Check for JSON parsing errors
            logError("Malformed JSON in configuration file: " + filePath);
            return {};
        }

        std::unordered_map<std::string, std::variant<int, double, std::string, bool>> configMap;

        for (auto& [key, value] : configJson.items()) {
            if (value.is_number_integer()) {
                configMap[key] = static_cast<int>(value);
            } else if (value.is_number_float()) {
                configMap[key] = static_cast<double>(value);
            } else if (value.is_string()) {
                configMap[key] = value.get<std::string>();
            } else if (value.is_boolean()) {
                configMap[key] = value;
            } else {
                logError("Unsupported data type for key: " + std::string(key));
            }
        }

        return configMap;

    } catch (const nlohmann::json::parse_error& e) {
        logError("JSON parsing error in configuration file: " + filePath + ". Error: " + e.what());
    } catch (const std::exception& e) {
        logError("An unexpected error occurred while loading the configuration: " + std::string(e.what()));
    }

    return {};
}
