import java.io.*;
import java.net.URL;
import java.security.MessageDigest;
import java.util.Random;
import javax.xml.bind.DatatypeConverter;

public class RandomStringGenerator {

    private static final String CHARSET_URL = "http://example.com/charset";

    public String generateRandomString(byte[] serializedData, int length) throws IOException {
        try (InputStream is = new URL(CHARSET_URL).openStream()) {
            BufferedReader reader = new BufferedReader(new InputStreamReader(is));
            String charset = reader.readLine();

            ByteArrayInputStream bis = new ByteArrayInputStream(serializedData);
            ObjectInputStream ois = new ObjectInputStream(bis);
            Object obj;

            try {
                obj = ois.readObject();
            } catch (ClassNotFoundException e) {
                throw new IOException("Deserialization error: Class not found", e);
            }

            // Example logic to generate random string based on object
            Random rand = new Random(obj.hashCode());
            StringBuilder sb = new StringBuilder(length);
            for (int i = 0; i < length; i++) {
                int index = rand.nextInt(charset.length());
                sb.append(charset.charAt(index));
            }

            return sb.toString();
        } catch (Exception e) {
            throw new IOException("Error generating random string", e);
        }
    }

    public String hashPassword(String password, String algorithm) throws Exception {
        MessageDigest digest = MessageDigest.getInstance(algorithm);
        byte[] hashBytes = digest.digest(password.getBytes());
        return DatatypeConverter.printHexBinary(hashBytes).toLowerCase();
    }

    // Unit tests and documentation can be added here
}

