    if (!load_config(&key_len, &iv_len)) {
        return 0; // Configuration load failed
    }

    aes_ctx->key_length = key_len / 8;
    aes_ctx->iv_length = iv_len;

    if (aes_ctx->key_length < 16 || aes_ctx->key_length > 32 ||
        aes_ctx->iv_length != 16) {
        return 0; // Invalid key or IV length
    }

    EVP_CIPHER_CTX_init(aes_ctx->ctx);

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), hash);

    memcpy(aes_ctx->key, hash, aes_ctx->key_length);
    if (!RAND_bytes(aes_ctx->iv, aes_ctx->iv_length)) {
        EVP_CIPHER_CTX_free(aes_ctx->ctx);
        pthread_mutex_destroy(&aes_ctx->lock);
        return 0; // Random IV generation failed
    }

    int cipher_type = EVP_aes_256_cbc();
    if (aes_ctx->key_length == 16) cipher_type = EVP_aes_128_cbc();

    if (!EVP_EncryptInit_ex(aes_ctx->ctx, cipher_type, NULL, aes_ctx->key, aes_ctx->iv)) {
        EVP_CIPHER_CTX_free(aes_ctx->ctx);
        pthread_mutex_destroy(&aes_ctx->lock);
        return 0; // Cipher initialization failed
    }

    return 1; // Success
}

// Function to clean up AES context
void cleanup_aes_context(AESContext *aes_ctx) {
    if (aes_ctx) {
        EVP_CIPHER_CTX_free(aes_ctx->ctx);
        pthread_mutex_destroy(&aes_ctx->lock);
    }
}

int main() {
    AESContext aes_ctx;
    memset(&aes_ctx, 0, sizeof(AESContext));
    aes_ctx.ctx = EVP_CIPHER_CTX_new();

    const char *password = "secure_password";

    if (!init_aes_context(&aes_ctx, password)) {
        fprintf(stderr, "Failed to initialize AES context.\n");
        cleanup_aes_context(&aes_ctx);
        return 1;
    }

    // Use the AESContext for encryption...

    cleanup_aes_context(&aes_ctx);

    return 0;
}
```

### Key Points:
- **Thread Safety**: The `pthread_mutex_t` ensures that the initialization is thread-safe.
- **Configuration Loading**: A placeholder function (`load_config`) loads key and IV lengths from a configuration file. You need to implement actual file reading logic.
- **Error Handling**: Proper error handling is implemented for OpenSSL operations, ensuring resources are cleaned up on failure.
- **Modular Structure**: The code is organized into functions for initialization, cleanup, and configuration loading.

