import random
import string
from typing import Dict, Any

class GraphDatabase:
    def __init__(self):
        self.vertices = {}
        self.edges = {}

    def generate_random_string(self, length: int) -> str:
        return ''.join(random.choices(string.ascii_letters + string.digits, k=length))

    def add_vertex(self, external_store, max_vertices: int = 1000):
        for _ in range(random.randint(1, max_vertices)):
            vertex_id = self.generate_random_string(8)
            properties = {
                "name": self.generate_random_string(10),
                "value": random.randint(0, 100)
            }
            if vertex_id not in self.vertices:
                try:
                    external_store.save_vertex(vertex_id, properties)
                    self.vertices[vertex_id] = properties
                except Exception as e:
                    print(f"Error adding vertex {vertex_id}: {e}")

    def add_edge(self, external_store, max_edges: int = 2000):
        vertices_list = list(self.vertices.keys())

        for _ in range(random.randint(1, max_edges)):
            if len(vertices_list) < 2:
                break
            start_vertex = random.choice(vertices_list)
            end_vertex = random.choice(vertices_list)

            if start_vertex != end_vertex:
                edge_id = self.generate_random_string(8)

                if (start_vertex, end_vertex) not in self.edges:
                    properties = {
                        "weight": random.random(),
                        "type": self.generate_random_string(5)
                    }

                    try:
                        external_store.save_edge(edge_id, start_vertex, end_vertex, properties)
                        self.edges[(start_vertex, end_vertex)] = properties
                    except Exception as e:
                        print(f"Error adding edge {edge_id} from {start_vertex} to {end_vertex}: {e}")

    def populate_graph(self, external_store):
        try:
            self.add_vertex(external_store)
            self.add_edge(external_store)
            print("Graph populated successfully.")
        except Exception as e:
            print(f"Error populating graph: {e}")
        finally:
            # Clean up resources or connections if needed
            pass

