    let config_content = fs::read_to_string(&args[1])?;
    let config: Config = serde_json::from_str(&config_content)?;

    // Setup logging
    let filter_layer = EnvFilter::try_from_default_env().unwrap_or_else(|_| "info".parse().unwrap());
    tracing_subscriber::registry()
        .with(filter_layer)
        .with(fmt::layer())
        .init();

    info!("Starting application with config: {:?}", config);

    // Execute the function specified in the configuration
    if let Err(err) = execute_function(&config).await {
        error!("Error executing function: {}", err);
    }

    // Setup signal handling for graceful shutdown
    let listener = TcpListener::bind("127.0.0.1:8080").await?;
    tokio::spawn(async move {
        info!("Starting health check server");
        warp::serve(health_check()).run(listener).await;
    });

    let ctrl_c = async {
        signal::ctrl_c().await.expect("failed to install Ctrl+C handler")
    };

    tokio::select! {
        _ = ctrl_c => { info!("Received Ctrl+C, shutting down..."); },
    }

    Ok(())
}

fn health_check() -> impl Filter<Extract = impl warp::Reply, Error = warp::Rejection> + Clone {
    warp::path("health")
        .map(|| warp::reply::json(&"ok"))
}

