```python
import os
import sys
import zipfile
import argparse
from multiprocessing import Pool, cpu_count
import requests
from tqdm import tqdm

def process_file(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            content = f.read()
        lines = content.splitlines()
        words = content.split()
        return len(lines), sum(len(word) for word in words), len(content)
    except Exception as e:
        print(f"Error reading {file_path}: {e}")
        return 0, 0, 0

def scan_directory(directory, file_extension_filter):
    total_lines, total_words, total_chars = 0, 0, 0
    files_to_process = []

    for root, _, files in os.walk(directory):
        for file in files:
            if not any(file.endswith(ext) for ext in file_extension_filter):
                files_to_process.append(os.path.join(root, file))

    with Pool(cpu_count()) as pool:
        results = list(tqdm(pool.imap(process_file, files_to_process), total=len(files_to_process)))

    for lines, words, chars in results:
        total_lines += lines
        total_words += words
        total_chars += chars

    return total_lines, total_words, total_chars, files_to_process

def compress_files(file_paths, output_zip_path):
    try:
        with zipfile.ZipFile(output_zip_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
            for file in tqdm(file_paths, desc="Compressing Files"):
                zipf.write(file)
    except Exception as e:
        print(f"Error compressing files: {e}")

def upload_to_cloud(zip_path):
    try:
        with open(zip_path, 'rb') as f:
            response = requests.post('https://api.example.com/upload', files={'file': f})
        if response.status_code == 200:
            print("Upload successful!")
        else:
            print(f"Upload failed: {response.text}")
    except Exception as e:
        print(f"Error uploading file: {e}")

def main():
    parser = argparse.ArgumentParser(description="Directory Monitoring and Processing Script")
    parser.add_argument('directory', type=str, help='Path to the directory')
    parser.add_argument('--exclude', nargs='+', default=['.csv', '.log'], help='File extensions to exclude')
    parser.add_argument('--output_zip', type=str, help='Output path for ZIP file')
    args = parser.parse_args()

    if not os.path.isdir(args.directory):
        print("Invalid directory path.")
        sys.exit(1)

    total_lines, total_words, total_chars, files_to_process = scan_directory(args.directory, args.exclude)

    print(f"Total Lines: {total_lines}")
    print(f"Total Words: {total_words}")
    print(f"Total Characters: {total_chars}")

    if len(files_to_process) > 100 and args.output_zip:
        compress_files(files_to_process, args.output_zip)

        try:
            upload_to_cloud(args.output_zip)
        except Exception as e:
            print(f"Failed to upload ZIP file: {e}")
    else:
        print("No compression needed.")

if __name__ == '__main__':
    main()
```

