Below is a simplified design of a Java-based distributed cache system with the specified requirements. This example demonstrates key components and concepts but is not a complete implementation.

```java
import org.apache.zookeeper.*;
import java.io.IOException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class DistributedCache {
    private final ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    private ZooKeeper zookeeper;

    public DistributedCache(String zookeeperServers) throws IOException {
        this.zookeeper = new ZooKeeper(zookeeperServers, 3000, event -> {});
        setupZooKeeperNodes();
    }

    private void setupZooKeeperNodes() {
        try {
            // Create a znode for this node
            if (zookeeper.exists("/cache", false) == null) {
                zookeeper.create("/cache", new byte[0], ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void put(String key, String value, long ttlMillis) {
        lock.writeLock().lock();
        try {
            CacheEntry entry = new CacheEntry(value, System.currentTimeMillis() + ttlMillis);
            cache.put(key, entry);
            // Store in cloud storage if needed
        } finally {
            lock.writeLock().unlock();
        }
    }

    public String get(String key) {
        lock.readLock().lock();
        try {
            CacheEntry entry = cache.get(key);
            if (entry == null || System.currentTimeMillis() > entry.expiryTime) {
                return null;
            }
            return entry.value;
        } finally {
            lock.readLock().unlock();
        }
    }

    public void evictExpiredEntries() {
        lock.writeLock().lock();
        try {
            cache.entrySet().removeIf(entry -> System.currentTimeMillis() > entry.getValue().expiryTime);
        } finally {
            lock.writeLock().unlock();
        }
    }

    // Implement additional methods for TTL management, eviction policies, and data rebalancing

    public static void main(String[] args) throws IOException {
        DistributedCache cache = new DistributedCache("localhost:2181");

        // Example usage
        cache.put("key1", "value1", 5000);
        String value = cache.get("key1");
        System.out.println(value);

        // Simulate expiration
        try { Thread.sleep(6000); } catch (InterruptedException e) { }
        cache.evictExpiredEntries();

        value = cache.get("key1");
        System.out.println(value);  // Should print null if expired
    }

    private static class CacheEntry {
        String value;
        long expiryTime;

        CacheEntry(String value, long expiryTime) {
            this.value = value;
            this.expiryTime = expiryTime;
        }
    }
}
```

