// JavaScript Function: dynamicFooterRenderer

async function fetchScripts(apiEndpoint, cache) {
  try {
    const response = await fetch(apiEndpoint);
    if (!response.ok) throw new Error('Network response was not ok');
    const scriptsData = await response.json();

    // Cache update and management logic
    for (const script of scriptsData) {
      const { url, version } = script;
      const cacheKey = `${url}_v${version}`;
      if (!cache[cacheKey] || new Date(cache[cacheKey].timestamp) < new Date()) {
        cache[cacheKey] = { timestamp: new Date(), data: script };
      }
    }

    return scriptsData.map(script => cache[`${script.url}_v${script.version}`]);
  } catch (error) {
    console.error('Error fetching scripts:', error);
    // Retry logic or other error handling could be added here
  }
}

function renderScripts(scripts, footerElement) {
  let spinner = document.createElement('div');
  spinner.innerText = 'Loading...';
  footerElement.appendChild(spinner);

  async function loadScript(script) {
    return new Promise((resolve, reject) => {
      const scriptTag = document.createElement('script');
      scriptTag.src = script.url;

      // Handling execution order
      if (Array.from(footerElement.children).includes(scriptTag)) {
        resolve();
        return;
      }

      footerElement.appendChild(scriptTag);

      scriptTag.onload = () => {
        spinner.innerText = `Loaded ${script.url}`;
        resolve();
      };

      scriptTag.onerror = () => reject(new Error(`Failed to load ${script.url}`));
    });
  }

  async function executeScriptsSequentially(scripts) {
    for (const script of scripts) {
      try {
        await loadScript(script);
      } catch (error) {
        console.error('Error loading script:', error);
      }
    }

    spinner.remove();
  }

  executeScriptsSequentially(scripts).catch(error => {
    console.error('Error in script execution sequence:', error);
  });
}

async function dynamicFooterRenderer(apiEndpoint, cache = {}) {
  const footerElement = document.querySelector('.footer');

  if (!footerElement) return;

  const scriptsData = await fetchScripts(apiEndpoint, cache);
  if (scriptsData && scriptsData.length > 0) {
    renderScripts(scriptsData, footerElement);

    // Cleanup old script tags
    Array.from(footerElement.children)
      .filter(child => child.tagName === 'SCRIPT')
      .forEach(scriptTag => scriptTag.remove());
  }
}

// Initial call example:
dynamicFooterRenderer('/api/scripts');
