#include <stdio.h>
#include <string.h>

#define MAX_FILENAME_LENGTH 255

void dynamicFileNameUpdate(char *filename, const char *fileType, int version) {
    size_t filenameLength = strlen(filename);

    if (filenameLength + strlen(fileType) + 3 >= MAX_FILENAME_LENGTH - 1) {
        fprintf(stderr, "Filename too long\n");
        return;
    }

    // Check for existing extension
    char *dotPos = strrchr(filename, '.');
    int hasExtension = dotPos != NULL;

    if (hasExtension) {
        char *versionPos = strstr(dotPos, ".v");
        if (versionPos != NULL) {
            sprintf(versionPos + 2, "%d", version);
        } else {
            strcat(dotPos, fileType);
            sprintf(strrchr(filename, '.') + 1, "v%d%s", version, fileType);
        }
    } else {
        char newExtension[10];
        snprintf(newExtension, sizeof(newExtension), ".%sv%d", fileType, version);
        strncat(filename, newExtension, MAX_FILENAME_LENGTH - filenameLength - 1);
    }
}

// Example Usage:
int main() {
    char filename[] = "document";
    dynamicFileNameUpdate(filename, "txt", 1);
    printf("Updated filename: %s\n", filename); // Output should be "document.v1.txt"

    return 0;
}
