import logging
from queue import Queue, Empty
from threading import Lock

class DatabaseConnectionManager:
    def __init__(self, max_connections=5):
        self.max_connections = max_connections
        self.connection_pool = Queue(maxsize=max_connections)
        self.lock = Lock()
        self.active_connections = 0
        logging.basicConfig(level=logging.DEBUG)

    def establish_connection(self, db_type, db_config):
        # Example logic to establish a database connection.
        if not hasattr(db_config, 'host') or not hasattr(db_config, 'database'):
            raise ValueError("Invalid database configuration")

        logging.debug(f"Establishing {db_type} connection with config: {db_config}")

        # This is where you would normally create a DB connection using the provided
        # `db_type` and `db_config`. For demonstration purposes:
        connection = f"{db_type}_connection({db_config})"
        return connection

    def get_connection(self):
        try:
            with self.lock:
                if self.connection_pool.empty():
                    logging.debug("Connection pool is empty, establishing new connection.")
                    # Create a new connection
                    db_config = {'host': 'localhost', 'database': 'test'}
                    conn = self.establish_connection('PostgreSQL', db_config)
                    self.active_connections += 1
                else:
                    logging.debug("Reusing connection from the pool.")
                    conn = self.connection_pool.get_nowait()
            return conn
        except Empty:
            raise ConnectionError("No available connections in the pool.")

    def release_connection(self, conn):
        with self.lock:
            try:
                self.connection_pool.put_nowait(conn)
                logging.debug(f"Connection released. Pool size: {self.connection_pool.qsize()}")
            except Full:
                logging.warning("Connection pool is full; connection not returned to pool.")

    def execute_query(self, query, params=None):
        conn = self.get_connection()
        try:
            # Placeholder for executing a query using the established connection
            result = f"Executed {query} with params: {params}"
            logging.debug(result)
            return result
        except Exception as e:
            logging.error(f"Error executing query: {e}")
            raise
        finally:
            self.release_connection(conn)

    def start_transaction(self):
        conn = self.get_connection()
        try:
            # Start transaction logic
            logging.debug("Transaction started.")
        except Exception as e:
            logging.error(f"Failed to start transaction: {e}")
            raise
        return conn

    def commit_transaction(self, conn):
        try:
            # Commit transaction logic
            logging.debug("Transaction committed.")
        except Exception as e:
            logging.error(f"Error committing transaction: {e}")
            raise

    def rollback_transaction(self, conn):
        try:
            # Rollback transaction logic
            logging.debug("Transaction rolled back.")
        except Exception as e:
            logging.error(f"Error rolling back transaction: {e}")
            raise

    def get_pool_size(self):
        return self.connection_pool.qsize()

    def set_pool_size(self, size):
        with self.lock:
            if size < 1 or size > 100:  # Arbitrary max limit for demonstration
                raise ValueError("Invalid pool size")

            logging.debug(f"Setting new pool size to {size}.")
            current_connections = list(self.connection_pool.queue)
            while len(current_connections) > size:
                self.release_connection(current_connections.pop(0))

            self.max_connections = size
            self.connection_pool = Queue(maxsize=size)

