from cachetools import LRUCache, LFUCache
import threading
import requests
from flask import Flask, request, jsonify
import logging
import zlib
import json
from datetime import datetime, timedelta

app = Flask(__name__)

class StockCache:
    def __init__(self, max_size=1000, policy='LRU'):
        self.policy = policy
        if policy == 'LRU':
            self.cache = LRUCache(maxsize=max_size)
        elif policy == 'LFU':
            self.cache = LFUCache(maxsize=max_size)
        else:
            raise ValueError("Unsupported cache policy")

        self.lock = threading.Lock()
        self.logger = logging.getLogger('StockCache')
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)
        self.logger.setLevel(logging.INFO)

    def _compress_data(self, data):
        return zlib.compress(json.dumps(data).encode())

    def _decompress_data(self, compressed_data):
        return json.loads(zlib.decompress(compressed_data).decode())

    def set(self, key, value, ttl=None):
        with self.lock:
            compressed_value = self._compress_data(value)
            expiration = datetime.now() + timedelta(seconds=ttl) if ttl else None
            self.cache[key] = (compressed_value, expiration)
            self.logger.info(f"Set cache: {key}")

    def get(self, key):
        with self.lock:
            data = self.cache.get(key)
            if not data:
                self.logger.info(f"Cache miss: {key}")
                return None
            compressed_value, expiration = data
            if expiration and datetime.now() > expiration:
                del self.cache[key]
                self.logger.info(f"Cache eviction due to TTL: {key}")
                return None
            self.logger.info(f"Cache hit: {key}")
            return self._decompress_data(compressed_value)

    def clear(self):
        with self.lock:
            self.cache.clear()
            self.logger.info("Cache cleared")

class LoadBalancer:
    def __init__(self, nodes):
        self.nodes = nodes
        self.load = {node: 0 for node in nodes}

    def distribute_request(self, request_data):
        selected_node = min(self.load, key=self.load.get)
        # Simulate sending request to node
        self.load[selected_node] += 1
        return f"Request handled by {selected_node}"

    def adjust_nodes(self):
        total_load = sum(self.load.values())
        average_load = total_load / len(self.nodes) if self.nodes else 0

        for node in list(self.nodes):
            if self.load[node] < average_load * 0.5:
                self.nodes.remove(node)
                self.logger.info(f"Node {node} removed due to low load")
            elif not self.nodes and total_load > len(self.nodes) * average_load:
                # Add a new node logic here
                pass

class DataPruner:
    def __init__(self, cache):
        self.cache = cache

    def prune_stale_data(self):
        with self.cache.lock:
            current_time = datetime.now()
            keys_to_delete = [key for key, (_, expiration) in self.cache.cache.items() if expiration and current_time > expiration]

            for key in keys_to_delete:
                del self.cache.cache[key]
                self.logger.info(f"Pruned stale data: {key}")

@app.route('/add', methods=['POST'])
def add_stock_data():
    data = request.json
    stock_cache.set(data['ticker'], data, ttl=data.get('ttl'))
    return jsonify({"message": "Stock data added"}), 200

@app.route('/get/<ticker>', methods=['GET'])
def get_stock_data(ticker):
    data = stock_cache.get(ticker)
    if not data:
        return jsonify({"error": "Data not found"}), 404
    return jsonify(data), 200

@app.route('/clear', methods=['POST'])
def clear_cache():
    stock_cache.clear()
    return jsonify({"message": "Cache cleared"}), 200

if __name__ == '__main__':
    stock_cache = StockCache(max_size=1000, policy='LRU')
    load_balancer = LoadBalancer(nodes=["Node1", "Node2"])
    data_pruner = DataPruner(stock_cache)

    # Start a background thread to prune stale data
    def prune_data_periodically():
        while True:
            data_pruner.prune_stale_data()
            time.sleep(60)  # Prune every minute

    threading.Thread(target=prune_data_periodically, daemon=True).start()

    app.run(port=5000)
