#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdio.h>

// Function to derive AES-256 key using PBKDF2 with SHA-256
int derive_key(const char *password, int password_len, unsigned char *key, int key_length) {
    return PKCS5_PBKDF2_HMAC(
        password,
        password_len,
        NULL, 0, // no salt for simplicity; in practice, use a random salt
        10000,   // iteration count
        EVP_sha256(),
        key_length,
        key);
}

// Function to initialize AES-256-GCM cipher
int init_aes_gcm(EVP_CIPHER_CTX **ctx, const char *password, int password_len, size_t iv_len, size_t tag_len) {
    if (iv_len < 12 || iv_len > 16 || tag_len < 4 || tag_len > 16) {
        fprintf(stderr, "Invalid IV or tag length\n");
        return -1;
    }

    EVP_CIPHER_CTX *cipher_ctx = NULL;
    unsigned char key[EVP_MAX_KEY_LENGTH] = {0};

    if (!derive_key(password, password_len, key, sizeof(key)) ||
        !(cipher_ctx = EVP_CIPHER_CTX_new()) ||
        !EVP_EncryptInit_ex(cipher_ctx, EVP_aes_256_gcm(), NULL, NULL, NULL) ||
        !EVP_CIPHER_CTX_ctrl(cipher_ctx, EVP_CTRL_GCM_SET_IVLEN, iv_len, NULL) ||
        !EVP_EncryptSetKey(cipher_ctx, key, sizeof(key))) {

        if (cipher_ctx) EVP_CIPHER_CTX_free(cipher_ctx);
        fprintf(stderr, "Failed to initialize AES-256-GCM cipher\n");
        return -1;
    }

    *ctx = cipher_ctx;
    return 0;
}

// Function to generate an authentication tag
int aes_gcm_generate_tag(EVP_CIPHER_CTX *ctx, unsigned char *tag, size_t tag_len) {
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, tag_len, tag)) {
        fprintf(stderr, "Failed to generate GCM tag\n");
        return -1;
    }
    return 0;
}

// Function to verify an authentication tag
int aes_gcm_verify_tag(EVP_CIPHER_CTX *ctx, const unsigned char *tag, size_t tag_len) {
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, tag_len, (unsigned char *)tag)) {
        fprintf(stderr, "Failed to set GCM tag\n");
        return -1;
    }

    int result = EVP_DecryptFinal_ex(ctx, NULL, NULL);
    if (result != 1) {
        // If verification fails, clear the error
        ERR_clear_error();
        fprintf(stderr, "GCM tag verification failed\n");
        return -1;
    }
    return 0;
}

// Function to clean up and disable cipher
void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_cleanup(ctx);
        EVP_CIPHER_CTX_free(ctx);
    }
}
