```javascript
function findElementsBySelector(node, selector, callback) {
    if (!(node instanceof Element)) throw new Error("Invalid starting node.");

    const result = [];
    const stack = [node];

    while (stack.length > 0) {
        const current = stack.pop();

        // Use the callback to test each element's class or ID
        if (callback(current, selector)) {
            result.push(current);
        }

        for (let child of current.children || []) {
            stack.push(child);
        }
    }

    return result;
}

