#define MAX_CLIENTS 1000

typedef struct {
    char client_id[256];
    time_t last_request_time;
} Client;

typedef enum { FIXED_WINDOW, MOVING_WINDOW } PolicyType;

typedef struct RateLimiterConfig {
    int request_limit;
    double window_size_seconds;
    PolicyType policy_type;
} RateLimiterConfig;

typedef struct RateLimiter {
    Client clients[MAX_CLIENTS];
    pthread_mutex_t lock;
    RateLimiterConfig config;
} RateLimiter;

void log_event(const char* client_id, const char* event) {
    // Placeholder for integration with an external monitoring system
    printf("Event: %s | Client ID: %s\n", event, client_id);
}

int get_client_index(RateLimiter *rl, const char *client_id) {
    for (int i = 0; i < MAX_CLIENTS; ++i) {
        if (strcmp(rl->clients[i].client_id, client_id) == 0) {
            return i;
        }
    }
    return -1;
}

void initialize_rate_limiter(RateLimiter *rl, RateLimiterConfig config) {
    memset(rl->clients, 0, sizeof(rl->clients));
    pthread_mutex_init(&rl->lock, NULL);
    rl->config = config;
}

int is_rate_limited(RateLimiter *rl, const char *client_id) {
    int index = get_client_index(rl, client_id);
    if (index == -1) {
        // New client
        index = rand() % MAX_CLIENTS;  // Simple random allocation for example purposes
        strncpy(rl->clients[index].client_id, client_id, sizeof(rl->clients[0].client_id));
    }

    pthread_mutex_lock(&rl->lock);
    time_t now = time(NULL);
    time_t last_request_time = rl->clients[index].last_request_time;
    int request_count = 1; // Count current request

    if (rl->config.policy_type == FIXED_WINDOW) {
        if ((now - last_request_time) < rl->config.window_size_seconds) {
            request_count++;
        }
        rl->clients[index].last_request_time = now;
    } else if (rl->config.policy_type == MOVING_WINDOW) {
        // Implement moving window logic
        while ((now - last_request_time) < rl->config.window_size_seconds && index >= 0) {
            ++index; 
            if (index >= MAX_CLIENTS) index = 0;
            last_request_time = rl->clients[index].last_request_time;
            request_count++;
        }
        rl->clients[index % MAX_CLIENTS].last_request_time = now;
    }

    pthread_mutex_unlock(&rl->lock);

    log_event(client_id, (request_count > rl->config.request_limit) ? "Rate limited" : "Request allowed");

    return request_count > rl->config.request_limit;
}

void self_tune(RateLimiter *rl) {
    // Placeholder for adaptive logic based on historical data
}

int main() {
    RateLimiterConfig config = {10, 60.0, FIXED_WINDOW};
    RateLimiter rate_limiter;

    initialize_rate_limiter(&rate_limiter, config);

    const char* clients[] = {"client1", "client2", "client3"};
    for (int i = 0; i < sizeof(clients) / sizeof(clients[0]); ++i) {
        if (is_rate_limited(&rate_limiter, clients[i])) {
            printf("Client %s is rate limited.\n", clients[i]);
        } else {
            printf("Client %s request allowed.\n", clients[i]);
        }
    }

    self_tune(&rate_limiter);

    return 0;
}
