    public static async Task InitializeAsync()
    {
        apiUrl = Environment.GetEnvironmentVariable("API_ENDPOINT");

        while (true)
        {
            try
            {
                var response = await httpClient.GetAsync(apiUrl, HttpCompletionOption.ResponseHeadersRead);
                response.EnsureSuccessStatusCode();

                using (var stream = await response.Content.ReadAsStreamAsync())
                {
                    configuration = await JsonSerializer.DeserializeAsync<Configuration>(stream);

                    if (!ValidateConfiguration(configuration))
                        throw new Exception("Invalid Configuration");
                }
            }
            catch (Exception ex)
            {
                LogError(ex.Message);
            }

            await Task.Delay(TimeSpan.FromMinutes(5)); // Check every 5 minutes
        }
    }

    private static bool ValidateConfiguration(Configuration config)
    {
        return config != null &&
               config.TileSize > 0 &&
               config.WorldDimensions.Length == 2 &&
               config.CameraSpeed > 0;
    }
}

