using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;

public class WebsiteManager
{
    private static readonly object _lock = new object();
    private const int TimeoutMilliseconds = 5000;
    private static DateTime lastAttemptTime = DateTime.MinValue;
    private const int RateLimitSeconds = 10;

    public async Task<bool> AddAndManageSiteAsync(string directoryPath, string siteName, int port)
    {
        if (!Directory.Exists(directoryPath) || !HasAccess(directoryPath))
            throw new UnauthorizedAccessException("Invalid or inaccessible directory path.");

        ValidateSiteName(siteName);

        EnsureRateLimit();

        await GenerateWebConfigIfMissingAsync(directoryPath);

        lock (_lock)
        {
            try
            {
                var process = new Process();
                process.StartInfo.FileName = "powershell";
                process.StartInfo.Arguments = $"New-Website -Name {siteName} -Port {port} -PhysicalPath \"{directoryPath}\"";
                process.StartInfo.UseShellExecute = false;
                process.StartInfo.RedirectStandardOutput = true;
                process.StartInfo.RedirectStandardError = true;

                bool started = await ProcessStartWithTimeout(process, TimeoutMilliseconds);

                if (!started)
                    throw new TimeoutException("Failed to start the site within the allotted time.");

                return true;
            }
            catch (Exception ex)
            {
                LogError(ex);
                return false;
            }
        }
    }

    private bool HasAccess(string path)
    {
        try
        {
            FileIOPermission permission = new FileIOPermission(FileIOPermissionAccess.PathDiscovery, path);
            permission.Demand();
            return true;
        }
        catch (SecurityException)
        {
            return false;
        }
    }

    private void ValidateSiteName(string siteName)
    {
        if (!Regex.IsMatch(siteName, @"^[a-zA-Z0-9\-_]+$"))
            throw new ArgumentException("Invalid site name. Site names must only contain letters, numbers, dashes, and underscores.");
    }

    private async Task GenerateWebConfigIfMissingAsync(string directoryPath)
    {
        string webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            // Simulate calling an external system to create a default web.config
            await Task.Delay(1000); // Placeholder for async config generation call
            File.WriteAllText(webConfigPath, "<configuration></configuration>");  // Simple default content
        }
    }

    private void EnsureRateLimit()
    {
        var now = DateTime.UtcNow;
        if ((now - lastAttemptTime).TotalSeconds < RateLimitSeconds)
        {
            Thread.Sleep(TimeSpan.FromSeconds(RateLimitSeconds) - (now - lastAttemptTime));
        }
        lastAttemptTime = DateTime.UtcNow;
    }

    private async Task<bool> ProcessStartWithTimeout(Process process, int timeoutMilliseconds)
    {
        var tcs = new TaskCompletionSource<bool>();

        using (var cts = new CancellationTokenSource())
        {
            process.EnableRaisingEvents = true;
            process.Exited += (sender, args) =>
            {
                if (!process.HasExited) return;
                tcs.TrySetResult(true);
                cts.Cancel();
            };

            bool started = process.Start();

            if (!started)
            {
                tcs.SetResult(false);
            }
            else
            {
                var completedTask = await Task.WhenAny(tcs.Task, Task.Delay(timeoutMilliseconds));
                if (completedTask == tcs.Task)
                    return true;
                else
                {
                    cts.Cancel();
                    process.Kill();
                    return false;
                }
            }
        }
    }

    private void LogError(Exception ex)
    {
        // Example logging mechanism. Replace with actual logging.
        Console.Error.WriteLine($"Error: {ex.Message}");
    }

    public async Task<bool> StopSiteAsync(string siteName)
    {
        lock (_lock)
        {
            var process = new Process();
            process.StartInfo.FileName = "powershell";
            process.StartInfo.Arguments = $"Stop-Website -Name {siteName}";
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.RedirectStandardOutput = true;
            process.StartInfo.RedirectStandardError = true;

            bool stopped = await ProcessStartWithTimeout(process, TimeoutMilliseconds);

            if (!stopped)
                throw new Exception($"Failed to stop the site '{siteName}'.");

            return true;
        }
    }

    public async Task<bool> RemoveSiteAsync(string siteName)
    {
        lock (_lock)
        {
            var process = new Process();
            process.StartInfo.FileName = "powershell";
            process.StartInfo.Arguments = $"Remove-Website -Name {siteName}";
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.RedirectStandardOutput = true;
            process.StartInfo.RedirectStandardError = true;

            bool removed = await ProcessStartWithTimeout(process, TimeoutMilliseconds);

            if (!removed)
                throw new Exception($"Failed to remove the site '{siteName}'.");

            return true;
        }
    }
}
