async function executeModulesInSequence(modules, concurrencyLimit) {
  const loadedModules = new Set();

  async function loadAndExecuteModule(moduleName) {
    if (!loadedModules.has(moduleName)) {
      const module = loadModule(moduleName);
      if (module && typeof module.default === 'function') {
        await module.default();
        loadedModules.add(moduleName);
      }
    }
  }

  for (let i = 0; i < modules.length; i++) {
    await new Promise(resolve => setTimeout(resolve, 10)); // Simulate delay
    const concurrencyPool = [];

    for (let j = 0; j < concurrencyLimit && i + j < modules.length; j++) {
      concurrencyPool.push(loadAndExecuteModule(modules[i + j]));
      if (concurrencyPool.length === concurrencyLimit) {
        await Promise.all(concurrencyPool);
        concurrencyPool.splice(0, concurrencyPool.length);
      }
    }

    if (concurrencyPool.length > 0) {
      await Promise.all(concurrencyPool);
    }
  }
}

