// Asynchronous reduce function
async function asyncReduce(array, reducer, initialValue) {
  const { cpus } = require('os');
  const concurrencyLimit = Math.min(cpus().length, array.length);

  let index = 0;
  return new Promise((resolve, reject) => {
    const workerPool = Array.from({ length: concurrencyLimit }, () => null);

    async function processChunk() {
      if (index >= array.length) {
        if (!allWorkersIdle(workerPool)) resolve(currentValue);
        return;
      }

      for (let i = 0; i < concurrencyLimit && index < array.length; i++) {
        const workerIndex = (index + i) % concurrencyLimit;

        if (workerPool[workerIndex] === null || workerPool[workerIndex].isFinished()) {
          workerPool[workerIndex] = new Worker('./reduceWorker.js', {
            workerData: { index, value: array[index++] }
          });

          workerPool[workerIndex].on('message', async (result) => {
            currentValue = reducer(currentValue, result);
            workerPool[workerIndex] = null;

            await processChunk();
          });

          workerPool[workerIndex].on('error', reject);

          if (!currentValue) {
            currentValue = initialValue;
          }
        } else {
          break; // Wait for a free worker
        }
      }
    }

    async function allWorkersIdle(pool) {
      return pool.every(worker => !worker || worker.isFinished());
    }

    processChunk();
  });
}

