    fetch(config.logServerUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ level, message, timestamp: new Date().toISOString() }),
    }).catch(err => console.error('Logging error:', err));
