function loadModules(directory) {
  const modules = [];
  fs.readdirSync(directory).forEach(file => {
    try {
      const modulePath = path.resolve(directory, file);
      if (fs.statSync(modulePath).isDirectory()) {
        const { default: Module } = require(`./${modulePath}`);
        modules.push({ name: file, module: new Module() });
      }
    } catch (err) {
      log(`Failed to load module ${file}: ${err.message}`, 'error');
    }
  });
  return modules;
}

