      body: JSON.stringify({
        title: `Test Failure in Module: ${module.name}`,
        description: `${err.message}\n\n${err.stack}`,
        labels: ['test-failure', module.name],
      }),
    }).catch(logErr => log(`Failed to create bug report: ${logErr.message}`, 'error'));
  }
}

function executeTests() {
  const modules = loadModules(config.moduleDir);
  let activeProcesses = 0;

  function runNextModule(module) {
    if (activeProcesses >= config.maxConcurrency || !module) return;

    activeProcesses++;
    log(`Starting tests for module ${module.name}`, 'info');

    runTests(module, `${module.name} Suite`)
      .then(() => {
        activeProcesses--;
        log(`Completed tests for module ${module.name}`, 'info');
        runNextModule(modules.shift());
      })
      .catch(err => {
        handleTestResult(module, `${module.name} Suite`, err);
        activeProcesses--;
        runNextModule(modules.shift());
      });
  }

  modules.forEach(runNextModule);

  if (activeProcesses === 0) log('All tests completed', 'info');
}

// Start execution
executeTests();

// Real-time feedback integration example with Slack
function sendSlackNotification(message, channel = config.notificationChannel) {
  fetch(`https://slack.com/api/chat.postMessage`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${process.env.SLACK_BOT_TOKEN}`,
    },
    body: JSON.stringify({
      channel,
      text: message,
    }),
  }).catch(err => log(`Slack notification error: ${err.message}`, 'error'));
}

// Example usage
sendSlackNotification('Testing started');
```

