using System;
using System.Collections.Concurrent;
using System.Data.SqlClient;
using Microsoft.Extensions.Caching.Memory;

public class DynamicDatabaseConnectionManager : IDisposable
{
    private readonly string _connectionStringTemplate;
    private readonly ConcurrentDictionary<string, string> _tenantIdentifierMapping;
    private readonly ConcurrentBag<SqlConnection> _connectionPool;
    private readonly IMemoryCache _cache;
    private readonly IConfigurationService _configurationService;

    public DynamicDatabaseConnectionManager(string connectionStringTemplate, IConfigurationService configurationService)
    {
        _connectionStringTemplate = connectionStringTemplate;
        _tenantIdentifierMapping = new ConcurrentDictionary<string, string>();
        _connectionPool = new ConcurrentBag<SqlConnection>();
        _cache = new MemoryCache(new MemoryCacheOptions());
        _configurationService = configurationService;

        // Initialize connection pool with dummy connections (for example purposes)
        for (int i = 0; i < 10; i++)
        {
            var connection = new SqlConnection("dummy-connection-string");
            _connectionPool.Add(connection);
        }
    }

    public void EstablishConnection(string tenantId)
    {
        var connectionString = GetTenantConnectionString(tenantId);

        if (!_connectionPool.TryTake(out var connection))
        {
            throw new InvalidOperationException("No available database connections in the pool.");
        }

        try
        {
            connection.ConnectionString = connectionString;
            connection.Open();
        }
        catch (SqlException ex)
        {
            _connectionPool.Add(connection);
            throw new Exception($"Failed to establish a connection for tenant {tenantId}.", ex);
        }
    }

    public object ExecuteQuery(string query, SqlTransaction transaction = null)
    {
        if (_cache.TryGetValue(query, out var cachedResult))
        {
            return cachedResult;
        }

        using (var connection = _connectionPool.Take())
        {
            try
            {
                connection.Open();
                using (var command = new SqlCommand(query, connection))
                {
                    if (transaction != null)
                    {
                        command.Transaction = transaction;
                    }

                    var result = command.ExecuteScalar(); // Modify as needed for different types of queries

                    _cache.Set(query, result);
                    return result;
                }
            }
            catch (Exception ex)
            {
                throw new Exception("Failed to execute query.", ex);
            }
            finally
            {
                _connectionPool.Add(connection);
            }
        }
    }

    public SqlTransaction BeginTransaction(SqlConnection connection)
    {
        try
        {
            return connection.BeginTransaction();
        }
        catch (Exception ex)
        {
            throw new Exception("Failed to begin transaction.", ex);
        }
    }

    public void CommitTransaction(SqlTransaction transaction)
    {
        try
        {
            transaction?.Commit();
        }
        catch (Exception ex)
        {
            throw new Exception("Failed to commit transaction.", ex);
        }
    }

    public void RollbackTransaction(SqlTransaction transaction)
    {
        try
        {
            transaction?.Rollback();
        }
        catch (Exception ex)
        {
            throw new Exception("Failed to rollback transaction.", ex);
        }
    }

    private string GetTenantConnectionString(string tenantId)
    {
        if (_tenantIdentifierMapping.TryGetValue(tenantId, out var connectionString))
        {
            return connectionString;
        }

        _configurationService.RefreshConfiguration(); // Assume this updates _connectionStringTemplate and _tenantIdentifierMapping

        if (!_tenantIdentifierMapping.TryGetValue(tenantId, out connectionString))
        {
            throw new Exception($"No connection string found for tenant {tenantId}.");
        }

        return connectionString;
    }

    public void CloseConnection(SqlConnection connection)
    {
        try
        {
            connection?.Close();
        }
        catch (Exception ex)
        {
            // Log and handle exception as needed
        }
        finally
        {
            _connectionPool.Add(connection);
        }
    }

    public void UpdateConfiguration()
    {
        try
        {
            _configurationService.RefreshConfiguration(); // Assume this updates necessary fields
        }
        catch (Exception ex)
        {
            throw new Exception("Failed to update configuration.", ex);
        }
    }

    public override string ToString()
    {
        return $"DynamicDatabaseConnectionManager with template: {_connectionStringTemplate}";
    }

    public void Dispose()
    {
        foreach (var connection in _connectionPool)
        {
            try
            {
                connection?.Dispose();
            }
            catch (Exception ex)
            {
                // Log and handle exception as needed
            }
        }
    }
}

public interface IConfigurationService
{
    void RefreshConfiguration(); // Assume this updates necessary fields like _connectionStringTemplate and _tenantIdentifierMapping
}
